#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration register values
#define CONFIG_OS_SINGLE 0x8000  // Start single conversion
#define CONFIG_MUX_SINGLE_0 0x4000 // AIN0 single-ended
#define CONFIG_PGA_4_096V 0x0000  // +/-4.096V range
#define CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define CONFIG_DR_128SPS 0x0060   // 128 SPS
#define CONFIG_COMP_MODE_TRAD 0x0000 // Traditional comparator
#define CONFIG_COMP_POL_LOW 0x0000  // Active low comparator
#define CONFIG_COMP_LAT_NON 0x0000  // Non-latching comparator
#define CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold configuration parameters
typedef struct {
    int i2c_address;
    int i2c_bus;
    float gain;
    int data_rate;
} ads1115_config_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the ADS1115
int ads1115_init(int i2c_handle, ads1115_config_t config) {
    // Configure the ADS1115
    uint16_t config_value = CONFIG_OS_SINGLE | CONFIG_MUX_SINGLE_0 | config.gain | CONFIG_MODE_SINGLE | config.data_rate | CONFIG_COMP_MODE_TRAD | CONFIG_COMP_POL_LOW | CONFIG_COMP_LAT_NON | CONFIG_COMP_QUE_DISABLE;

    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config_value >> 8) & 0xFF; // MSB
    buf[2] = config_value & 0xFF;        // LSB

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to ADS1115 config register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read the current from the ADS1115
float ads1115_read_current(int i2c_handle) {
    char buf[1];
    buf[0] = ADS1115_REG_CONVERT;

    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to ADS1115 conversion register: %s\n", strerror(errno));
        return -1.0;
    }

    gpioDelay(10); // Wait for conversion (adjust as needed)

    char read_buf[2];
    result = i2cReadDevice(i2c_handle, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from ADS1115 conversion register: %s\n", strerror(errno));
        return -1.0;
    }

    // Combine the two bytes to form the 16-bit conversion result
    int16_t raw_value = (read_buf[0] << 8) | read_buf[1];

    // Convert the raw value to current (assuming +/- 4.096V range and 16-bit resolution)
    float current = (float)raw_value * 4.096 / 32768.0;

    return current;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ADS1115_ADDR, 0); // Bus 1, address 0x48, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Configure ADS1115
    ads1115_config_t config = {
        .i2c_address = ADS1115_ADDR,
        .i2c_bus = 1,
        .gain = CONFIG_PGA_4_096V,
        .data_rate = CONFIG_DR_128SPS
    };

    if (ads1115_init(i2c_handle, config) != 0) {
        fprintf(stderr, "ADS1115 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        float current = ads1115_read_current(i2c_handle);
        if (current >= 0) {
            printf("Current: %.4f A\n", current);
        } else {
            fprintf(stderr, "Failed to read current\n");
        }

        gpioDelay(500); // Wait 500ms
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

