#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define FLAME_SENSOR_GPIO 4
#define MCP3008_CE0_GPIO 8

// Define SPI channel and baud rate
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz

// Define temperature calibration parameters
#define TEMP_OFFSET 20.0
#define TEMP_SCALE 0.1

// Global variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Structure to hold configuration data
typedef struct {
    int flame_gpio;
    int ce0_gpio;
    int spi_channel;
    int spi_baud;
    float temp_offset;
    float temp_scale;
    char *filename;
} Config;

// Function prototypes
int initialize_pigpio();
int initialize_spi();
int read_mcp3008(int channel);
float calculate_temperature(int adc_value);
int log_data(time_t timestamp, int flame_detected, float temperature);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(MCP3008_CE0_GPIO, 0); // Select MCP3008
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(MCP3008_CE0_GPIO, 1); // Deselect MCP3008

    if (result != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Calculate temperature from ADC value
float calculate_temperature(int adc_value) {
    return TEMP_OFFSET + (adc_value * TEMP_SCALE);
}

// Log data to CSV file
int log_data(time_t timestamp, int flame_detected, float temperature) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%d,%.2f\n", timestamp_str, flame_detected, temperature);
    fflush(fp); // Ensure data is written to disk immediately

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
}

int main() {
    // Configuration
    Config config = {
        .flame_gpio = FLAME_SENSOR_GPIO,
        .ce0_gpio = MCP3008_CE0_GPIO,
        .spi_channel = SPI_CHANNEL,
        .spi_baud = SPI_BAUD,
        .temp_offset = TEMP_OFFSET,
        .temp_scale = TEMP_SCALE,
        .filename = "flame_data.csv"
    };

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(config.flame_gpio, PI_INPUT);
    gpioSetMode(config.ce0_gpio, PI_OUTPUT);
    gpioWrite(config.ce0_gpio, 1); // Deselect MCP3008 initially

    // Open CSV file for logging
    fp = fopen(config.filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file %s\n", config.filename);
        cleanup();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "Timestamp,FlameDetected,Temperature(C)\n");
    }
    rewind(fp);

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read flame sensor
        int flame_detected = gpioRead(config.flame_gpio);

        // Read temperature from MCP3008
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value. Skipping logging.\n");
            gpioDelay(1000); // Wait 1 second
            continue;
        }

        float temperature = calculate_temperature(adc_value);

        // Get current timestamp
        time_t current_time = time(NULL);

        // Log data
        if (log_data(current_time, flame_detected, temperature) != 0) {
            fprintf(stderr, "Failed to log data. Skipping.\n");
        }

        // Wait for 1 second
        gpioDelay(1000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

