#include <wiringPiI2C.h>

// Constants
#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 27
#define ADS1115_I2C_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define ADS1115_CONFIG_OS_SINGLE 0x8000  // Start single conversion
#define ADS1115_CONFIG_MUX_SINGLE_0 0x4000 // AIN0 single-ended
#define ADS1115_CONFIG_PGA_4_096V 0x0000  // +/-4.096V range
#define ADS1115_CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define ADS1115_CONFIG_DR_128SPS 0x0060   // 128 SPS
#define ADS1115_CONFIG_COMP_MODE_TRAD 0x0000 // Traditional comparator
#define ADS1115_CONFIG_COMP_POL_LOW 0x0000  // Active low comparator
#define ADS1115_CONFIG_COMP_LAT_NON 0x0000  // Non-latching comparator
#define ADS1115_CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator

#define TEMPERATURE_THRESHOLD 60.0
#define BUZZER_DURATION_MS 2000
#define DEBOUNCE_DELAY_MS 50

// Global variables
static volatile bool running = true;
static int i2c_fd;
static FILE *log_file;

// Function prototypes
int init_gpio();
int init_i2c();
int init_ads1115();
int read_flame_sensor();
float read_temperature();
void activate_buzzer();
void deactivate_buzzer();
void log_event(const char *message);
void signal_handler(int signal);

// Function to initialize GPIO using wiringPi
int init_gpio() {
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return -1;
    }

    pinMode(FLAME_SENSOR_PIN, INPUT);
    pinMode(BUZZER_PIN, OUTPUT);
    return 0;
}

// Function to initialize I2C communication
int init_i2c() {
    i2c_fd = wiringPiI2CSetup(ADS1115_I2C_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Error initializing I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to initialize the ADS1115 ADC
int init_ads1115() {
    // Configure the ADS1115 for single-ended AIN0, +/-4.096V, 128 SPS, single-shot mode
    uint16_t config = ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_SINGLE_0 | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_COMP_MODE_TRAD | ADS1115_CONFIG_COMP_POL_LOW | ADS1115_CONFIG_COMP_LAT_NON | ADS1115_CONFIG_COMP_QUE_DISABLE;

    // Write the configuration to the ADS1115
    if (wiringPiI2CWriteReg16(i2c_fd, ADS1115_REG_CONFIG, config) == -1) {
        fprintf(stderr, "Error writing to ADS1115 config register: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read the flame sensor value
int read_flame_sensor() {
    int value = digitalRead(FLAME_SENSOR_PIN);
    if (value == -1) {
        fprintf(stderr, "Error reading flame sensor: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

// Function to read the temperature from the ADS1115
float read_temperature() {
    int16_t raw_value;

    // Start a single conversion
    uint16_t config = ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_SINGLE_0 | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_COMP_MODE_TRAD | ADS1115_CONFIG_COMP_POL_LOW | ADS1115_CONFIG_COMP_LAT_NON | ADS1115_CONFIG_COMP_QUE_DISABLE;
    if (wiringPiI2CWriteReg16(i2c_fd, ADS1115_REG_CONFIG, config) == -1) {
        fprintf(stderr, "Error writing to ADS1115 config register for temperature read: %s\n", strerror(errno));
        return -1.0;
    }

    // Wait for the conversion to complete (at least 8ms for 128 SPS)
    delay(10);

    // Read the conversion result
    raw_value = wiringPiI2CReadReg16(i2c_fd, ADS1115_REG_CONVERT);
    if (raw_value == -1) {
        fprintf(stderr, "Error reading from ADS1115 conversion register: %s\n", strerror(errno));
        return -1.0;
    }

    // Convert the raw value to temperature (assuming 16-bit resolution and +/-4.096V range)
    float voltage = (float)raw_value * 4.096 / 32768.0;
    float temperature = voltage * 100.0; // Example conversion: 10mV/°C

    return temperature;
}

// Function to activate the buzzer
void activate_buzzer() {
    digitalWrite(BUZZER_PIN, HIGH);
}

// Function to deactivate the buzzer
void deactivate_buzzer() {
    digitalWrite(BUZZER_PIN, LOW);
}

// Function to log an event to the log file
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure the log is written immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    running = false;
    printf("Caught signal %d, exiting...\n", signal);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (init_gpio() == -1) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() == -1) {
        return 1;
    }

    // Initialize ADS1115
    if (init_ads1115() == -1) {
        return 1;
    }

    // Open log file
    log_file = fopen("fire_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    printf("Fire detection system started. Press Ctrl+C to exit.\n");

    int flame_debounce_count = 0;
    bool flame_detected = false;

    while (running) {
        int flame_value = read_flame_sensor();
        float temperature = read_temperature();

        if (flame_value == -1) {
            fprintf(stderr, "Error reading flame sensor, skipping this iteration.\n");
        } else {
            if (flame_value == LOW) { // Flame detected (LOW signal)
                flame_debounce_count++;
                if (flame_debounce_count >= 3) { // Debounce: require 3 consecutive LOW readings
                    flame_detected = true;
                }
            } else {
                flame_debounce_count = 0;
                flame_detected = false;
            }
        }

        if (temperature == -1.0) {
            fprintf(stderr, "Error reading temperature, skipping this iteration.\n");
        }

        if (flame_detected && temperature > TEMPERATURE_THRESHOLD) {
            log_event("Fire detected!");
            activate_buzzer();
            delay(BUZZER_DURATION_MS);
            deactivate_buzzer();
        } else if (flame_detected) {
            log_event("Flame detected!");
        } else if (temperature > TEMPERATURE_THRESHOLD) {
            char log_message[64];
            snprintf(log_message, sizeof(log_message), "Temperature: %.2f °C", temperature);
            log_event(log_message);
        }

        delay(100); // Check every 100ms
    }

    // Cleanup
    deactivate_buzzer();
    fclose(log_file);
    return 0;
}

