volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float co_ppm;
    float no2_ppm;
} SensorData;

// Function prototypes
int initialize_i2c();
int read_ads1115(int channel);
float convert_to_ppm(int raw_value, float slope, float intercept);
int log_data(SensorData data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read data from ADS1115 ADC
int read_ads1115(int channel) {
    // Configure ADS1115 for single-ended read on the specified channel
    // Set configuration register (0x01)
    // OS = 1 (Start single conversion)
    // MUX = channel (000 = AIN0, 001 = AIN1, 010 = AIN2, 011 = AIN3)
    // PGA = 000 (+/- 4.096V)
    // MODE = 1 (Single-shot mode)
    // DR = 100 (128 SPS)
    // COMP_MODE = 0 (Traditional comparator)
    // COMP_POL = 0 (Active low comparator output)
    // COMP_LAT = 0 (Non-latching comparator)
    // COMP_QUE = 01 (Disable comparator)

    uint16_t config = 0x4000; // Start single conversion
    config |= (channel << 12); // Set MUX
    config |= 0x0080; // Set MODE to single-shot

    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;

    if (i2cWriteDevice(i2c_handle, buf, 3) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read conversion register (0x00)
    buf[0] = CONVERSION_REG;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device for conversion read\n");
        return -1;
    }

    char read_buf[2];
    if (i2cReadDevice(i2c_handle, read_buf, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    int16_t raw_value = (read_buf[0] << 8) | read_buf[1];
    return raw_value;
}

