    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, CO: %.2f ppm, NO2: %.2f ppm\n", timestamp, data.co_ppm, data.no2_ppm);
    fclose(fp);
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    printf("CO sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read raw ADC values from CO and NO2 channels
        int raw_co = read_ads1115(CO_CHANNEL);
        int raw_no2 = read_ads1115(NO2_CHANNEL);

        if (raw_co < 0 || raw_no2 < 0) {
            fprintf(stderr, "Error reading sensor data. Retrying in %d seconds...\n", SAMPLE_INTERVAL);
            sleep(SAMPLE_INTERVAL);
            continue; // Retry the loop
        }

        // Convert raw values to ppm
        float co_ppm = convert_to_ppm(raw_co, CO_SLOPE, CO_INTERCEPT);
        float no2_ppm = convert_to_ppm(raw_no2, NO2_SLOPE, NO2_INTERCEPT);

        // Create sensor data struct
        SensorData data = {co_ppm, no2_ppm};

        // Log data
        if (log_data(data) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        printf("CO: %.2f ppm, NO2: %.2f ppm\n", co_ppm, no2_ppm);

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    printf("CO sensor monitoring stopped.\n");
    return 0;
}

