#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define MCP3008_CS_PIN 8

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_flame_sensor();
int read_mcp3008(int channel);
float convert_to_temperature(int adc_value);
int log_data(int flame_detected, float temperature);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int flame_pin;
    int cs_pin;
    int spi_channel;
    int spi_speed;
    int spi_mode;
    char *log_file_name;
} Config;

Config config = {
    FLAME_SENSOR_PIN,
    MCP3008_CS_PIN,
    SPI_CHANNEL,
    SPI_SPEED,
    SPI_MODE,
    "flame_data.csv"
};

int main() {
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (!terminate) {
        int flame_detected = read_flame_sensor();
        if (flame_detected == -1) {
            fprintf(stderr, "Error reading flame sensor. Skipping.\n");
            gpioDelay(1000); // Wait 1 second
            continue;
        }

        int adc_value = read_mcp3008(0);
        if (adc_value == -1) {
            fprintf(stderr, "Error reading MCP3008. Skipping.\n");
            gpioDelay(1000); // Wait 1 second
            continue;
        }

        float temperature = convert_to_temperature(adc_value);

        if (log_data(flame_detected, temperature) != 0) {
            fprintf(stderr, "Error logging data. Skipping.\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    cleanup();
    return 0;
}

int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(config.flame_pin, PI_INPUT);
    gpioSetMode(config.cs_pin, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(config.spi_channel, config.spi_speed, config.spi_mode);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file_name, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Flame Detected,Temperature (C)\n");
    }
    rewind(log_file);

    return 0;
}

void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int read_flame_sensor() {
    int value = gpioRead(config.flame_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading flame sensor pin\n");
        return -1;
    }
    return value;
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel\n");
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(config.cs_pin, 0); // Select MCP3008
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(config.cs_pin, 1); // Deselect MCP3008

    if (result != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

float convert_to_temperature(int adc_value) {
    // Assuming a linear relationship between ADC value and temperature
    // This is a placeholder; you'll need to calibrate the sensor
    // and determine the appropriate conversion formula.
    // Example: 0 ADC = 20°C, 1023 ADC = 50°C
    float temperature = 20.0 + (float)adc_value * (50.0 - 20.0) / 1023.0;
    return temperature;
}

int log_data(int flame_detected, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%d,%.2f\n", timestamp, flame_detected, temperature) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return 1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

