#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define MICS_4514_ADDR 0x48
#define CO_THRESHOLD 25.0
#define LOG_FILE_CO "co_log.txt"
#define LOG_FILE_ALERT "alert_log.txt"
#define SAMPLE_INTERVAL_SEC 5

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t ox;
    uint16_t red;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(sensor_data_t *data);
float convert_ox_to_co(uint16_t ox_value);
int log_co_data(float co_ppm);
int log_alert(float co_ppm);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// I2C initialization function
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MICS_4514_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buf[4];
    int bytes_read = i2cReadDevice(i2c_handle, buf, 4);

    if (bytes_read != 4) {
        fprintf(stderr, "Failed to read sensor data: %d\n", bytes_read);
        return -1;
    }

    data->ox = (buf[0] << 8) | buf[1];
    data->red = (buf[2] << 8) | buf[3];

    return 0;
}

// Function to convert OX value to CO concentration (ppm)
float convert_ox_to_co(uint16_t ox_value) {
    // This is a placeholder conversion.  Refer to the MICS-4514 datasheet
    // for the correct formula.
    // Assuming a linear relationship for demonstration purposes:
    return (float)ox_value * 0.1; // Example: 0.1 ppm per unit
}

// Function to log CO data to a file
int log_co_data(float co_ppm) {
    FILE *fp = fopen(LOG_FILE_CO, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE_CO);
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, CO: %.2f ppm\n", timestamp, co_ppm);
    fclose(fp);
    return 0;
}

// Function to log alert to a file
int log_alert(float co_ppm) {
    FILE *fp = fopen(LOG_FILE_ALERT, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open alert log file %s\n", LOG_FILE_ALERT);
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, ALERT: CO concentration exceeded threshold (%.2f ppm > %.2f ppm)\n", timestamp, co_ppm, CO_THRESHOLD);
    fclose(fp);
    return 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    sensor_data_t sensor_data;
    float co_ppm;

    printf("Starting CO monitoring...\n");

    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Convert OX value to CO concentration
            co_ppm = convert_ox_to_co(sensor_data.ox);

            // Log CO data
            if (log_co_data(co_ppm) != 0) {
                fprintf(stderr, "Failed to log CO data\n");
            }

            // Check for alert condition
            if (co_ppm > CO_THRESHOLD) {
                if (log_alert(co_ppm) != 0) {
                    fprintf(stderr, "Failed to log alert\n");
                }
            }
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying in %d seconds...\n", SAMPLE_INTERVAL_SEC);
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

