#include <unistd.h>

// Define GPIO pins for microphone data
#define MIC1_GPIO 2
#define MIC2_GPIO 3

// Define I2C address for ADC (example, adjust as needed)
#define ADC_I2C_ADDR 0x48

// Define ADC register addresses (example, adjust as needed)
#define ADC_CONFIG_REG 0x01
#define ADC_DATA_REG 0x00

// Define sampling rate (100ms)
#define SAMPLING_RATE 100000 // microseconds

// Define ADC configuration value (example, adjust as needed)
#define ADC_CONFIG_VALUE 0x83 // Example: Start single conversion, AIN0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold microphone data
typedef struct {
    int gpio;
    int i2c_handle;
} microphone_t;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
int initialize_adc(int i2c_handle);
int read_adc(int i2c_handle);
double calculate_average_level(int mic1_level, int mic2_level);
int log_data(double average_level);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(1, ADC_I2C_ADDR, 0); // Bus 1, address 0x48, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize ADC (set configuration register)
int initialize_adc(int i2c_handle) {
    int result = i2cWriteByteData(i2c_handle, ADC_CONFIG_REG, ADC_CONFIG_VALUE);
    if (result < 0) {
        fprintf(stderr, "Failed to write to ADC config register: %d\n", result);
        return -1;
    }
    return 0;
}

// Read ADC value from the specified register
int read_adc(int i2c_handle) {
    int adc_value = i2cReadWordData(i2c_handle, ADC_DATA_REG);
    if (adc_value < 0) {
        fprintf(stderr, "Failed to read ADC data: %d\n", adc_value);
        return -1;
    }
    return adc_value;
}

// Calculate average sound pressure level
double calculate_average_level(int mic1_level, int mic2_level) {
    // Simple average (replace with more sophisticated calibration if needed)
    double average_level = (mic1_level + mic2_level) / 2.0;

    // Convert ADC value to dB (example, adjust based on ADC and microphone characteristics)
    // This is a placeholder; you'll need to calibrate this based on your setup.
    double db_level = 20.0 * log10(average_level / 1024.0); // Assuming 10-bit ADC

    return db_level;
}

