int log_data(double average_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f dB\n", timestamp, average_level);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize ADC
    if (initialize_adc(i2c_handle) != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("audio_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    printf("Audio monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int mic1_level, mic2_level;
        double average_level;

        // Read microphone 1 data
        mic1_level = read_adc(i2c_handle);
        if (mic1_level < 0) {
            mic1_level = -999; // Indicate error
        }

        // Read microphone 2 data
        mic2_level = read_adc(i2c_handle);
        if (mic2_level < 0) {
            mic2_level = -999; // Indicate error
        }

        // Calculate average level
        average_level = calculate_average_level(mic1_level, mic2_level);

        // Log data
        log_data(average_level);

        // Wait for the next sample
        gpioDelay(SAMPLING_RATE);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

