#define SPI_CHANNEL_1 1
#define SPI_SPEED 1000000 // 1 MHz
#define LED_GPIO 27
#define RMS_THRESHOLD 0.5
#define LED_ON_TIME_MS 500
#define SAMPLE_WINDOW_MS 100
#define SAMPLE_RATE_MS 1
#define NUM_SAMPLES (SAMPLE_WINDOW_MS / SAMPLE_RATE_MS)
#define ADC_RESOLUTION 1024.0

// Global variables
int spi_handle_0 = -1;
int spi_handle_1 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold audio data
typedef struct {
    int16_t mic1_samples[NUM_SAMPLES];
    int16_t mic2_samples[NUM_SAMPLES];
} AudioData;

// Function prototypes
int initialize_spi(int channel);
int read_adc(int channel);
float calculate_rms(const int16_t *samples, int num_samples);
void log_data(time_t timestamp, float mic1_rms, float mic2_rms);
void control_led(int state);
void signal_handler(int signal);
void cleanup();

// Function to initialize SPI
int initialize_spi(int channel) {
    int handle = spiOpen(channel, SPI_SPEED, 0); // Mode 0
    if (handle < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %d\n", channel, handle);
        return -1;
    }
    return handle;
}

// Function to read ADC value from MCP3008
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle_0, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer error\n");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate RMS level
float calculate_rms(const int16_t *samples, int num_samples) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum_of_squares += (double)samples[i] * samples[i];
    }
    double mean_square = sum_of_squares / num_samples;
    return sqrt(mean_square);
