#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define LED_GPIO 17
#define BUFFER_SIZE 100
#define CURRENT_THRESHOLD 50.0 // Amps
#define SAMPLE_RATE 10 // Hz
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE) // microseconds

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float current_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int initialize_i2c();
int read_ads1115(int16_t *raw_value);
float convert_to_current(int16_t raw_value);
void add_to_buffer(float current);
float calculate_average_current();
void control_led(int on);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int ads1115_address;
    int led_pin;
    int buffer_size;
    float current_threshold;
    int sample_rate;
} Config;

Config config = {
    .i2c_bus = I2C_BUS,
    .ads1115_address = ADS1115_ADDR,
    .led_pin = LED_GPIO,
    .buffer_size = BUFFER_SIZE,
    .current_threshold = CURRENT_THRESHOLD,
    .sample_rate = SAMPLE_RATE
};

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(config.led_pin, PI_OUTPUT);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int16_t raw_value;
    float current;

    // Main loop
    while (!terminate) {
        // Read raw value from ADS1115
        if (read_ads1115(&raw_value) == 0) {
            // Convert raw value to current
            current = convert_to_current(raw_value);

            // Add current to buffer
            add_to_buffer(current);

            // Calculate average current
            float average_current = calculate_average_current();

            // Check if average current exceeds threshold
            if (average_current > config.current_threshold) {
                control_led(1); // Turn on LED
            } else {
                control_led(0); // Turn off LED
            }

            printf("Raw Value: %d, Current: %.2f A, Average Current: %.2f A\n", raw_value, current, average_current);
        } else {
            fprintf(stderr, "Failed to read from ADS1115\n");
        }

        // Delay for sampling period
        gpioDelay(SAMPLE_PERIOD_US);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(config.i2c_bus, config.ads1115_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }

    // Configure ADS1115 for single-ended A0, 4.096V range, continuous conversion, 10 Hz
    // 0b01000001 00000000 (Single-ended A0, 4.096V, Continuous, 10 Hz)
    char config_data[3];
    config_data[0] = CONFIG_REG;
    config_data[1] = 0x41; // 0b01000001
    config_data[2] = 0x83; // 0b10000011

    if (i2cWriteDevice(i2c_handle, config_data, 3) != 0) {
        fprintf(stderr, "Failed to write to config register\n");
        i2cClose(i2c_handle);
        return 1;
    }

    return 0;
}

// Read raw value from ADS1115
int read_ads1115(int16_t *raw_value) {
    char reg = CONVERSION_REG;
    char buffer[2];

    if (i2cWriteDevice(i2c_handle, &reg, 1) != 0) {
        fprintf(stderr, "Failed to write to conversion register\n");
        return 1;
    }

    if (i2cReadDevice(i2c_handle, buffer, 2) != 2) {
        fprintf(stderr, "Failed to read from conversion register\n");
        return 1;
    }

    *raw_value = (buffer[0] << 8) | buffer[1];
    return 0;
}

// Convert raw value to current (Amps)
float convert_to_current(int16_t raw_value) {
    // Assuming 4.096V range and 16-bit resolution
    // Sensitivity: 4.096V / 2^16 = 0.000244140625 V/LSB
    // Current = (Raw Value * Sensitivity) / 0.000244140625
    // Current = Raw Value * (4.096 / 2^16) / 0.000244140625
    // Current = Raw Value * 0.000244140625 * 2^16 / 4.096
    // Current = Raw Value * 0.000244140625 * 65536 / 4.096
    // Current = Raw Value * 0.000244140625 * 16384
    float current = (float)raw_value * 0.000244140625 * 16384.0;
    return current;
}

// Add current reading to circular buffer
void add_to_buffer(float current) {
    current_buffer[buffer_index] = current;
    buffer_index = (buffer_index + 1) % config.buffer_size;
}

// Calculate average current from circular buffer
float calculate_average_current() {
    float sum = 0.0;
    for (int i = 0; i < config.buffer_size; i++) {
        sum += current_buffer[i];
    }
    return sum / config.buffer_size;
}

// Control LED state
void control_led(int on) {
    gpioWrite(config.led_pin, on);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    control_led(0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

