#define TCS34725_COMMAND_BIT     (0x80)
#define TCS34725_ENABLE          (0x00)
#define TCS34725_ATIME           (0x01)
#define TCS34725_WTIME           (0x03)
#define TCS34725_AILTL           (0x04)
#define TCS34725_AILTH           (0x05)
#define TCS34725_AIHTL           (0x06)
#define TCS34725_AIHTH           (0x07)
#define TCS34725_ID              (0x12)
#define TCS34725_STATUS          (0x13)
#define TCS34725_CDATA           (0x14)
#define TCS34725_RDATA           (0x16)
#define TCS34725_GDATA           (0x18)
#define TCS34725_BDATA           (0x1A)

// Enable Register Values
#define TCS34725_ENABLE_AIEN     (0x10)   // ALS Interrupt Enable
#define TCS34725_ENABLE_WEN      (0x08)   // Wait enable - Writing 1 activates the wait timer
#define TCS34725_ENABLE_AEN      (0x02)   // ALS Enable
#define TCS34725_ENABLE_PON      (0x01)   // Power on

// Integration Time Values
#define TCS34725_INTEGRATIONTIME_2_4MS  (0xFF)   // 2.4ms - 1 cycle    - Max Count: 1024
#define TCS34725_INTEGRATIONTIME_24MS   (0xF6)   // 24ms  - 10 cycles   - Max Count: 10240
#define TCS34725_INTEGRATIONTIME_50MS   (0xEB)   // 50ms  - 20 cycles   - Max Count: 20480
#define TCS34725_INTEGRATIONTIME_101MS  (0xD5)   // 101ms - 42 cycles   - Max Count: 43008
#define TCS34725_INTEGRATIONTIME_154MS  (0xC0)   // 154ms - 64 cycles   - Max Count: 65535
#define TCS34725_INTEGRATIONTIME_207MS  (0xAB)   // 207ms - 80 cycles   - Max Count: 65535
#define TCS34725_INTEGRATIONTIME_260MS  (0x96)   // 260ms - 97 cycles   - Max Count: 65535
#define TCS34725_INTEGRATIONTIME_313MS  (0x81)   // 313ms - 113 cycles  - Max Count: 65535

// Gain Values
#define TCS34725_GAIN_1X             (0x00)   // No gain
#define TCS34725_GAIN_4X             (0x01)   // 4x gain
#define TCS34725_GAIN_16X            (0x02)   // 16x gain
#define TCS34725_GAIN_60X            (0x03)   // 60x gain

// Global Variables
static int i2c_handle;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

// Function Prototypes
int tcs34725_init(int i2c_handle);
int tcs34725_read_data(int i2c_handle, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue);
int log_data(FILE *fp, uint16_t clear, uint16_t red, uint16_t green, uint16_t blue);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    uint16_t clear;
    uint16_t red;
    uint16_t green;
    uint16_t blue;
} sensor_data_t;

// Function to initialize the TCS34725 sensor
int tcs34725_init(int i2c_handle) {
    int status;

    // Check sensor ID
    uint8_t id;
    status = i2cReadByteData(i2c_handle, TCS34725_COMMAND_BIT | TCS34725_ID);
    if (status < 0) {
        fprintf(stderr, "Error reading sensor ID: %d\n", status);
        return -1;
    }
    id = (uint8_t)status;
    if (id != 0x44) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", id);
        return -1;
    }

    // Enable power and ALS
    status = i2cWriteByteData(i2c_handle, TCS34725_COMMAND_BIT | TCS34725_ENABLE, TCS34725_ENABLE_PON);
    if (status < 0) {
        fprintf(stderr, "Error writing to enable register (PON): %d\n", status);
        return -1;
    }
    gpioDelay(3); // Wait for power-on (at least 2.4ms)

    status = i2cWriteByteData(i2c_handle, TCS34725_COMMAND_BIT | TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN);
    if (status < 0) {
        fprintf(stderr, "Error writing to enable register (PON + AEN): %d\n", status);
        return -1;
    }

    // Set integration time (ATIME)
    status = i2cWriteByteData(i2c_handle, TCS34725_COMMAND_BIT | TCS34725_ATIME, TCS34725_INTEGRATIONTIME_24MS);
    if (status < 0) {
        fprintf(stderr, "Error writing to integration time register: %d\n", status);
        return -1;
    }

    // Set gain (AGAIN)
    status = i2cWriteByteData(i2c_handle, TCS34725_COMMAND_BIT | TCS34725_CONTROL, TCS34725_GAIN_1X);
    if (status < 0) {
        fprintf(stderr, "Error writing to gain register: %d\n", status);
        return -1;
    }

    return 0;
}

// Function to read color data from the TCS34725 sensor
int tcs34725_read_data(int i2c_handle, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    int status;
    uint8_t data[8];

    // Read all color data registers in one go
    status = i2cReadI2CBlockData(i2c_handle, TCS34725_COMMAND_BIT | TCS34725_CDATA, (char *)data, 8);
    if (status < 0) {
        fprintf(stderr, "Error reading color data: %d\n", status);
        return -1;
    }

    *clear = (uint16_t)data[1] << 8 | data[0];
    *red   = (uint16_t)data[3] << 8 | data[2];
    *green = (uint16_t)data[5] << 8 | data[4];
    *blue  = (uint16_t)data[7] << 8 | data[6];

    return 0;
}

// Function to log data to a CSV file
int log_data(FILE *fp, uint16_t clear, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%u,%u,%u,%u\n", timestamp, clear, red, green, blue) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    int status;
    sensor_data_t sensor_data;
    int consecutive_failures = 0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, TCS34725_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (tcs34725_init(i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is empty and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Clear,Red,Green,Blue\n");
    }
    rewind(log_file);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        status = tcs34725_read_data(i2c_handle, &sensor_data.clear, &sensor_data.red, &sensor_data.green, &sensor_data.blue);
        if (status == 0) {
            // Log the data
            if (log_data(log_file, sensor_data.clear, sensor_data.red, sensor_data.green, sensor_data.blue) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
            consecutive_failures = 0; // Reset failure count
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            consecutive_failures++;
            if (consecutive_failures >= 3) {
                fprintf(stderr, "Too many consecutive failures, exiting\n");
                break;
            }
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function takes milliseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

