#define OVERCURRENT_THRESHOLD 10.0
#define SAMPLING_INTERVAL 1 // seconds
#define MAX_RETRIES 3

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

