    log_file = fopen("current_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is empty and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Current (A)\n");
    }
    fseek(log_file, 0, SEEK_END); // Reset file pointer to the end

    return 0;
}

// Cleanup function
void cleanup() {
    fprintf(stderr, "Cleaning up...\n");

    // Disable motor
    gpioWrite(MOTOR_SHUTDOWN_GPIO, 0);

    // Close SPI channel
    spiClose(spi_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main() {
