    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    fprintf(stderr, "Current monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value >= 0) {
            // Convert ADC value to current
            float current = adc_to_current(adc_value);

            // Log current
            log_current(current);

            // Check for overcurrent
            check_overcurrent(current);
        } else {
            fprintf(stderr, "Error: Failed to read ADC value\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLING_INTERVAL * 1000); // pigpioDelay takes milliseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

