#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Configuration
#define I2C_BUS 1
#define MLX90817_ADDR 0x60
#define PRESSURE_REG 0x00 // Example register, check datasheet
#define LOG_FILE "pressure_log.csv"
#define READ_INTERVAL_SEC 1
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure_kPa;
    char timestamp[32];
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_pressure(float *pressure);
int log_data(float pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX90817_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read pressure from MLX90817
int read_pressure(float *pressure) {
    char buf[2];
    int result;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REG, buf, 2);
        if (result == 2) {
            // Convert raw data to kPa (example conversion, adjust as needed)
            int16_t raw_pressure = (buf[0] << 8) | buf[1];
            *pressure = (float)raw_pressure / 10.0; // Example scaling
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(10000); // Wait 10ms before retrying
        }
    }

    fprintf(stderr, "Failed to read pressure after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Log data to CSV file
int log_data(float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, pressure);
    fflush(log_file); // Ensure data is written immediately

    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,pressure_kPa\n");
    }

    float pressure;

    // Main loop
    while (!terminate) {
        if (read_pressure(&pressure) == 0) {
            log_data(pressure);
            printf("Pressure: %.2f kPa\n", pressure);
        } else {
            fprintf(stderr, "Failed to read pressure.\n");
        }

        gpioDelay(READ_INTERVAL_SEC * 1000000); // Delay for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

