            gpioDelay(1000); // Wait 1ms before retrying
            retries++;
            continue;
        }

        *raw_value = (data[0] << 8) | data[1];
        return 0; // Success
    }

    fprintf(stderr, "Failed to read ADS1115 after %d retries\n", RETRY_COUNT);
    return -1; // Failure
