#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define PRESSURE_MIN 0.0  // kPa
#define PRESSURE_MAX 100.0 // kPa
#define SAMPLE_RATE_HZ 1
#define LOG_FILE "pressure_log.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for configuration
typedef struct {
    int i2c_bus;
    int ads1115_address;
    int sample_rate_hz;
    char *log_file;
} Config;

// Function prototypes
int initialize_i2c(int bus, int addr);
int configure_ads1115(int handle);
int16_t read_ads1115(int handle);
float convert_to_pressure(int16_t raw_value);
int validate_pressure(float pressure);
int log_pressure(float pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int initialize_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Configure ADS1115 for single-ended AIN0, 4.096V range, continuous conversion
int configure_ads1115(int handle) {
    // Configuration register value: Single-ended AIN0, +/-4.096V, Continuous conversion
    uint16_t config = 0x4003; //0b0100000000000011
    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;

    int result = i2cWriteDevice(handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to configuration register: %d\n", result);
        return -1;
    }
    return 0;
}

// Read raw ADC value from ADS1115
int16_t read_ads1115(int handle) {
    char buf[1];
    buf[0] = CONVERSION_REG;
    int result = i2cWriteDevice(handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to conversion register: %d\n", result);
        return -1;
    }

    char read_buf[2];
    result = i2cReadDevice(handle, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from conversion register: %d\n", result);
        return -1;
    }

    int16_t raw_value = (read_buf[0] << 8) | read_buf[1];
    return raw_value;
}

// Convert raw ADC value to pressure (kPa)
float convert_to_pressure(int16_t raw_value) {
    // Assuming a linear relationship between raw value and pressure
    // This needs to be calibrated based on the sensor's datasheet
    // and the specific setup (e.g., sensor placement, load cell).
    // Example: 0 raw = 0 kPa, 32767 raw = 100 kPa
    float pressure = (float)raw_value / 32767.0 * 100.0;
    return pressure;
}

// Validate pressure reading
int validate_pressure(float pressure) {
    if (pressure < PRESSURE_MIN || pressure > PRESSURE_MAX) {
        fprintf(stderr, "Error: Pressure reading out of range: %.2f kPa\n", pressure);
        return -1;
    }
    return 0;
}

// Log pressure reading to file
int log_pressure(float pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(fp, "%s, %.2f kPa\n", timestamp, pressure);
    fclose(fp);
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_handle = initialize_i2c(I2C_BUS, ADS1115_ADDR);
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    // Configure ADS1115
    if (configure_ads1115(i2c_handle) < 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read raw ADC value
        int16_t raw_value = read_ads1115(i2c_handle);
        if (raw_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Convert to pressure
        float pressure = convert_to_pressure(raw_value);

        // Validate pressure
        if (validate_pressure(pressure) == 0) {
            // Log pressure
            if (log_pressure(pressure) != 0) {
                fprintf(stderr, "Error logging pressure.\n");
            }
        }

        // Wait for the next sample
        gpioDelay(1000); // 1000 ms = 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

