#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3208_CHANNEL 0
#define GPIO_CE 8
#define VREF 3.3
#define TEMP_MIN -40.0
#define TEMP_MAX 125.0
#define LOG_FILE "temperature_log.csv"
#define SAMPLE_INTERVAL_SEC 1

// Global variables
int spi_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int read_mcp3208(int channel);
float adc_to_celsius(int adc_value);
int log_temperature(float temperature);
void signal_handler(int signal);
void cleanup(void);

// Structure for SPI configuration
struct spi_config {
    int fd;
    uint8_t mode;
    uint8_t bits_per_word;
    uint32_t speed;
};

// SPI initialization function
int spi_init(void) {
    struct spi_config config;
    config.mode = SPI_MODE;
    config.bits_per_word = SPI_BITS_PER_WORD;
    config.speed = SPI_SPEED;

    config.fd = open(SPI_DEVICE, O_RDWR);
    if (config.fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    if (ioctl(config.fd, SPI_IOC_WR_MODE, &config.mode) == -1) {
        perror("Error setting SPI mode");
        close(config.fd);
        return -1;
    }

    // Set bits per word
    if (ioctl(config.fd, SPI_IOC_WR_BITS_PER_WORD, &config.bits_per_word) == -1) {
        perror("Error setting bits per word");
        close(config.fd);
        return -1;
    }

    // Set SPI speed
    if (ioctl(config.fd, SPI_IOC_WR_MAX_SPEED_HZ, &config.speed) == -1) {
        perror("Error setting SPI speed");
        close(config.fd);
        return -1;
    }

    spi_fd = config.fd; // Store the file descriptor
    return 0;
}

// Function to read from MCP3208 ADC
int read_mcp3208(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    // Perform SPI transfer
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to Celsius
float adc_to_celsius(int adc_value) {
    float voltage = (adc_value / 4095.0) * VREF;
    float temperature = (voltage - 0.5) * 100.0;
    return temperature;
}

// Function to log temperature to file
int log_temperature(float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Check if the file exists and write the header if it doesn't
    if (access(LOG_FILE, F_OK) == -1) {
        log_file = fopen(LOG_FILE, "w");
        if (log_file == NULL) {
            perror("Error opening log file for writing");
            return -1;
        }
        fprintf(log_file, "timestamp,temperature_celsius\n");
    } else {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file for appending");
            return -1;
        }
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fclose(log_file);
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup(void) {
    printf("Cleaning up...\n");
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO8 as output
    gpioSetMode(GPIO_CE, PI_OUTPUT);
    gpioWrite(GPIO_CE, 1); // Enable MCP3208

    // Initialize SPI
    if (spi_init() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3208(MCP3208_CHANNEL);
        if (adc_value == -1) {
            fprintf(stderr, "Error reading ADC value\n");
            continue; // Skip to the next iteration
        }

        float temperature = adc_to_celsius(adc_value);

        // Data validation
        if (temperature < TEMP_MIN || temperature > TEMP_MAX) {
            fprintf(stderr, "Temperature out of range: %.2f\n", temperature);
        } else {
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Error logging temperature\n");
            }
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

