// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    int x;
    int y;
    int z;
} accelerometer_data_t;

// Function prototypes
int initialize_spi();
int read_mcp3008(int channel);
accelerometer_data_t read_accelerometer();
int log_data(accelerometer_data_t data);
int detect_impact(accelerometer_data_t data);
void signal_handler(int signal);
void cleanup();

// Function to initialize the SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read data from the MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct the SPI message to send to the MCP3008
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(CS_PIN, 0); // Select the MCP3008
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(CS_PIN, 1); // Deselect the MCP3008

    if (result != 0) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    // Extract the ADC value from the received data
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to read accelerometer data from all three channels
accelerometer_data_t read_accelerometer() {
    accelerometer_data_t data;
    data.x = read_mcp3008(0);
    data.y = read_mcp3008(1);
    data.z = read_mcp3008(2);
    return data;
}

