    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Deselect the MCP3008 initially

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        accelerometer_data_t data = read_accelerometer();

        if (data.x == -1 || data.y == -1 || data.z == -1) {
            fprintf(stderr, "Error reading accelerometer data, retrying...\n");
            gpioDelay(10000); // Wait 10ms before retrying
            continue;
        }

        log_data(data);
        detect_impact(data);

        gpioDelay(10000); // Sample at 100 Hz (10ms delay)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

