int initialize_sensor() {
    // Implement Si1172 initialization sequence here
    // This is a placeholder; refer to the Si1172 datasheet for the correct sequence
    // Example: Writing to a register to enable the sensor
    char buf[2];
    buf[0] = 0x01; // Register address
    buf[1] = 0x01; // Value to write

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error initializing sensor: %d\n", result);
        return 1; // Indicate failure
    }

    gpioDelay(100); // Small delay after initialization

    return 0; // Indicate success
}

// Reads raw IR and RED ADC values from the Si1172 sensor
int read_sensor_data(uint16_t *ir_value, uint16_t *red_value) {
    // Implement Si1172 data reading sequence here
    // This is a placeholder; refer to the Si1172 datasheet for the correct sequence
    // Example: Reading from two registers to get IR and RED values
    char reg_ir = 0x02; // Register address for IR value
    char reg_red = 0x04; // Register address for RED value
    char buf[1];
    char data[4];

    buf[0] = reg_ir;
    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device for IR: %d\n", result);
        return 1;
    }
    result = i2cReadDevice(i2c_handle, data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading IR data: %d\n", result);
        return 1;
    }
    *ir_value = (data[1] << 8) | data[0];

    buf[0] = reg_red;
    result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device for RED: %d\n", result);
