    if (*hr < 0 || *hr > 200) {
        fprintf(stderr, "HR value out of range: %.2f\n", *hr);
        return 1; // Indicate invalid data
    }
    if (*spo2 < 0 || *spo2 > 100) {
        fprintf(stderr, "SpO2 value out of range: %.2f\n", *spo2);
        return 1; // Indicate invalid data
    }

    return 0; // Indicate success
}

