    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1172_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write the header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,HR (bpm),SpO2 (%%),Error Flag\n");
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    uint16_t ir_value, red_value;
    float hr, spo2;
    int error_flag;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&ir_value, &red_value) == 0) {
            // Process sensor data
            if (process_sensor_data(ir_value, red_value, &hr, &spo2) == 0) {
                // Log data with no error
                error_flag = 0;
                log_data(hr, spo2, error_flag);
            } else {
                // Log data with SpO2 processing error
                error_flag = 2;
                log_data(0.0, 0.0, error_flag);
            }
        } else {
            // Log data with sensor read error
            error_flag = 1;
            log_data(0.0, 0.0, error_flag);
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

