#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define ICP10125_ADDR 0x69
#define MEASURE_CMD 0x2403 // High precision measurement command
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 5000
#define SAMPLE_INTERVAL_SEC 5

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Calibration data structure
typedef struct {
    int32_t c0;
    int32_t c1;
    int32_t c00;
    int32_t c10;
    int32_t c01;
    int32_t c11;
    int32_t c20;
    int32_t c21;
    int32_t c30;
} icp10125_calibration_data_t;

// Function prototypes
int init_i2c();
int read_calibration_data(icp10125_calibration_data_t *cal_data);
int read_raw_data(int32_t *pressure, int32_t *temperature);
int convert_data(int32_t raw_pressure, int32_t raw_temperature, icp10125_calibration_data_t cal_data, float *temperature, float *pressure);
int log_data(float temperature, float pressure);
void display_data(float temperature, float pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_fd = i2cOpen(I2C_BUS, ICP10125_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_fd);
        return -1;
    }
    return 0;
}

// Read calibration data from the sensor
int read_calibration_data(icp10125_calibration_data_t *cal_data) {
    char buf[18];
    int result;

    // Read calibration data registers (0x10 to 0x27)
    result = i2cReadI2CBlockData(i2c_fd, 0x10, buf, 18);
    if (result != 18) {
        fprintf(stderr, "Error reading calibration data: %d\n", result);
        return -1;
    }

    // Combine bytes and apply calibration formulas (from ICP-10125 datasheet)
    cal_data->c0 = (int32_t)((((uint32_t)buf[0]) << 8) | ((uint32_t)buf[1]));
    cal_data->c1 = (int32_t)((((uint32_t)buf[2]) << 8) | ((uint32_t)buf[3]));
    cal_data->c00 = (int32_t)((((uint32_t)buf[4]) << 8) | ((uint32_t)buf[5]));
    cal_data->c10 = (int32_t)((((uint32_t)buf[6]) << 8) | ((uint32_t)buf[7]));
    cal_data->c01 = (int32_t)((((uint32_t)buf[8]) << 8) | ((uint32_t)buf[9]));
    cal_data->c11 = (int32_t)((((uint32_t)buf[10]) << 8) | ((uint32_t)buf[11]));
    cal_data->c20 = (int32_t)((((uint32_t)buf[12]) << 8) | ((uint32_t)buf[13]));
    cal_data->c21 = (int32_t)((((uint32_t)buf[14]) << 8) | ((uint32_t)buf[15]));
    cal_data->c30 = (int32_t)((((uint32_t)buf[16]) << 8) | ((uint32_t)buf[17]));

    return 0;
}

// Read raw pressure and temperature data from the sensor
int read_raw_data(int32_t *pressure, int32_t *temperature) {
    char buf[6];
    int result;

    // Send measurement command
    result = i2cWriteWordData(i2c_fd, 0x00, MEASURE_CMD);
    if (result != 0) {
        fprintf(stderr, "Error writing measurement command: %d\n", result);
        return -1;
    }

    // Wait for conversion (at least 10 ms)
    gpioDelay(10000); // 10 ms

    // Read 6 bytes of data (pressure MSB/LSB, temperature MSB/LSB, CRC bytes)
    result = i2cReadI2CBlockData(i2c_fd, 0x00, buf, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading raw data: %d\n", result);
        return -1;
    }

    // Combine bytes to get raw pressure and temperature values
    *pressure = (int32_t)((((uint32_t)buf[0]) << 8) | ((uint32_t)buf[1]));
    *temperature = (int32_t)((((uint32_t)buf[3]) << 8) | ((uint32_t)buf[4]));

    return 0;
}

// Convert raw data to temperature and pressure using calibration formulas
int convert_data(int32_t raw_pressure, int32_t raw_temperature, icp10125_calibration_data_t cal_data, float *temperature, float *pressure) {
    // Apply calibration formulas (from ICP-10125 datasheet)
    float p_scaled = (float)raw_pressure;
    float t_scaled = (float)raw_temperature;

    *temperature = cal_data.c0 * 0.5 + cal_data.c1 * t_scaled;
    *pressure = cal_data.c00 + cal_data.c10 * t_scaled + cal_data.c01 * p_scaled + cal_data.c11 * t_scaled * p_scaled + cal_data.c20 * p_scaled * p_scaled + cal_data.c21 * t_scaled * p_scaled * p_scaled + cal_data.c30 * t_scaled * t_scaled * p_scaled;

    return 0;
}

// Log data to CSV file
int log_data(float temperature, float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, pressure);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Display data on the console
void display_data(float temperature, float pressure) {
    printf("Temperature: %.2f °C, Pressure: %.2f Pa\n", temperature, pressure);
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_fd >= 0) {
        i2cClose(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    icp10125_calibration_data_t cal_data;
    int32_t raw_pressure, raw_temperature;
    float temperature, pressure;
    int retry;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen("environmental_data.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Initialize I2C with retry
        retry = 0;
        while (retry < RETRY_COUNT) {
            if (init_i2c() == 0) {
                break; // I2C initialized successfully
            } else {
                fprintf(stderr, "I2C initialization failed, retrying in %d ms...\n", RETRY_DELAY_MS);
                gpioDelay(RETRY_DELAY_MS * 1000); // pigpioDelay takes microseconds
                retry++;
            }
        }

        if (i2c_fd < 0) {
            fprintf(stderr, "I2C initialization failed after %d retries. Skipping this sample.\n", RETRY_COUNT);
            gpioDelay(SAMPLE_INTERVAL_SEC * 1000000); // Wait before next sample
            continue;
        }

        // Read calibration data
        if (read_calibration_data(&cal_data) != 0) {
            fprintf(stderr, "Failed to read calibration data. Skipping this sample.\n");
            i2cClose(i2c_fd);
            i2c_fd = -1;
            gpioDelay(SAMPLE_INTERVAL_SEC * 1000000); // Wait before next sample
            continue;
        }

        // Read raw data
        retry = 0;
        while (retry < RETRY_COUNT) {
            if (read_raw_data(&raw_pressure, &raw_temperature) == 0) {
                break; // Data read successfully
            } else {
                fprintf(stderr, "Failed to read raw data, retrying in %d ms...\n", RETRY_DELAY_MS);
                gpioDelay(RETRY_DELAY_MS * 1000); // pigpioDelay takes microseconds
                retry++;
            }
        }

        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Failed to read raw data after %d retries. Skipping this sample.\n", RETRY_COUNT);
            i2cClose(i2c_fd);
            i2c_fd = -1;
            gpioDelay(SAMPLE_INTERVAL_SEC * 1000000); // Wait before next sample
            continue;
        }

        // Convert data
        if (convert_data(raw_pressure, raw_temperature, cal_data, &temperature, &pressure) != 0) {
            fprintf(stderr, "Failed to convert data. Skipping this sample.\n");
            i2cClose(i2c_fd);
            i2c_fd = -1;
            gpioDelay(SAMPLE_INTERVAL_SEC * 1000000); // Wait before next sample
            continue;
        }

        // Log data
        if (log_data(temperature, pressure) != 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        // Display data
        display_data(temperature, pressure);

        // Close I2C connection
        i2cClose(i2c_fd);
        i2c_fd = -1;

        // Wait before next sample
        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

