    // Open log file
    log_file = fopen("environmental_data.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Initialize I2C with retry
        retry = 0;
        while (retry < RETRY_COUNT) {
            if (init_i2c() == 0) {
                break; // I2C initialized successfully
            } else {
                fprintf(stderr, "I2C initialization failed, retrying in %d ms...\n", RETRY_DELAY_MS);
                gpioDelay(RETRY_DELAY_MS * 1000); // pigpioDelay takes microseconds
                retry++;
            }
        }

        if (i2c_fd < 0) {
            fprintf(stderr, "I2C initialization failed after %d retries. Skipping this sample.\n", RETRY_COUNT);
            gpioDelay(SAMPLE_INTERVAL_SEC * 1000000); // Wait before next sample
            continue;
        }

        // Read calibration data
        if (read_calibration_data(&cal_data) != 0) {
            fprintf(stderr, "Failed to read calibration data. Skipping this sample.\n");
            i2cClose(i2c_fd);
            i2c_fd = -1;
            gpioDelay(SAMPLE_INTERVAL_SEC * 1000000); // Wait before next sample
            continue;
        }

        // Read raw data
        retry = 0;
        while (retry < RETRY_COUNT) {
            if (read_raw_data(&raw_pressure, &raw_temperature) == 0) {
                break; // Data read successfully
            } else {
                fprintf(stderr, "Failed to read raw data, retrying in %d ms...\n", RETRY_DELAY_MS);
                gpioDelay(RETRY_DELAY_MS * 1000); // pigpioDelay takes microseconds
                retry++;
            }
        }

        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Failed to read raw data after %d retries. Skipping this sample.\n", RETRY_COUNT);
            i2cClose(i2c_fd);
            i2c_fd = -1;
            gpioDelay(SAMPLE_INTERVAL_SEC * 1000000); // Wait before next sample
            continue;
        }

        // Convert data
        if (convert_data(raw_pressure, raw_temperature, cal_data, &temperature, &pressure) != 0) {
            fprintf(stderr, "Failed to convert data. Skipping this sample.\n");
            i2cClose(i2c_fd);
            i2c_fd = -1;
            gpioDelay(SAMPLE_INTERVAL_SEC * 1000000); // Wait before next sample
            continue;
        }

        // Log data
        if (log_data(temperature, pressure) != 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        // Display data
        display_data(temperature, pressure);

        // Close I2C connection
        i2cClose(i2c_fd);
        i2c_fd = -1;

        // Wait before next sample
        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

