        data.mic1_sample = (int16_t)(mic1_adc * mic1_gain);
        data.mic2_sample = (int16_t)(mic2_adc * mic2_gain);

        // Apply noise cancellation
        data.cancelled_sample = noise_cancel(data.mic1_sample, data.mic2_sample, &data.noise_estimate);

        // Print data to CSV format
        printf("%d,%d,%d,%d\n", data.mic1_sample, data.mic2_sample, data.noise_estimate, data.cancelled_sample);

        // Delay to control sampling rate
