// Constants
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define BUZZER_PIN 18
#define FLAME_THRESHOLD 500
#define TEMPERATURE_FILE "ambient_temp.txt"
#define LOG_FILE "flame_log.txt"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
static int spi_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
float temperature_compensation(int adc_value, float temperature);
int log_data(int raw_adc, float voltage, float compensated_voltage, float temperature, int flame_detected);
void signal_handler(int sig);
void cleanup(void);
float read_ambient_temperature(void);

// SPI initialization function
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device: %s\n", strerror(errno));
        return -1;
    }

    // Set SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    // Set bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        fprintf(stderr, "Error setting bits per word: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    // Set SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Dummy byte

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 1) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return (adc_value / 1023.0) * 3.3;
