#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define LED_GPIO 17
#define WATER_LEVEL_THRESHOLD_HIGH 75.0
#define WATER_LEVEL_THRESHOLD_LOW 70.0
#define JSON_FILE "water_levels.json"

// Global variables
int spi_handle;
FILE *json_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_water_level(int adc_value);
void log_water_level(float percentage);
void control_led(float percentage);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_speed;
    int mcp3008_channel;
    int led_gpio;
    float water_level_threshold_high;
    float water_level_threshold_low;
    char json_file[64];
} Config;

Config config = {
    SPI_CHANNEL,
    SPI_SPEED,
    MCP3008_CHANNEL,
    LED_GPIO,
    WATER_LEVEL_THRESHOLD_HIGH,
    WATER_LEVEL_THRESHOLD_LOW,
    JSON_FILE
};

int main() {
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        int adc_value = read_mcp3008(config.mcp3008_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading MCP3008. Skipping.\n");
            gpioDelay(100000); // 100ms
            continue;
        }

        float water_level = calculate_water_level(adc_value);
        log_water_level(water_level);
        control_led(water_level);

        gpioDelay(5000000); // 5 seconds
    }

    cleanup();
    return 0;
}

int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(config.spi_channel, config.spi_speed, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(config.led_gpio, PI_OUTPUT);
    gpioWrite(config.led_gpio, 0); // Initially off

    json_file = fopen(config.json_file, "a");
    if (json_file == NULL) {
        fprintf(stderr, "Failed to open JSON file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write opening bracket if the file is newly created
    fseek(json_file, 0, SEEK_END);
    long file_size = ftell(json_file);
    if (file_size == 0) {
        fprintf(json_file, "[");
    } else {
        // If the file already contains data, go back one character and overwrite the closing bracket
        fseek(json_file, -1, SEEK_END);
        fprintf(json_file, ",");
    }
    fflush(json_file);

    return 0;
}

void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(config.led_gpio, 0); // Turn off LED
    spiClose(spi_handle);
    gpioTerminate();

    // Write closing bracket to JSON file
    if (json_file != NULL) {
        fprintf(json_file, "]");
        fclose(json_file);
    }
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result < 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

float calculate_water_level(int adc_value) {
    return ((float)adc_value / 1023.0) * 100.0;
}

void log_water_level(float percentage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ldZ", time(NULL) % 1000);

    fprintf(json_file, "{\"timestamp\": \"%s\", \"water_level\": %.2f}", timestamp, percentage);
    fflush(json_file);

    printf("Timestamp: %s, Water Level: %.2f%%\n", timestamp, percentage);
}

void control_led(float percentage) {
    if (percentage > config.water_level_threshold_high) {
        gpioWrite(config.led_gpio, 1); // Turn on LED
    } else if (percentage < config.water_level_threshold_low) {
        gpioWrite(config.led_gpio, 0); // Turn off LED
    }
}

void signal_handler(int signal) {
    printf("Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

