    if (file_size == 0) {
        fprintf(log_file, "Timestamp,LPM\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(config.mcp3008_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value. Retrying.\n");
            gpioDelay(100); // Wait before retrying
