float calculate_moisture_percentage(int adc_value, int min_calibration, int max_calibration) {
    if (adc_value < min_calibration) {
        return 100.0;
    } else if (adc_value > max_calibration) {
        return 0.0;
    } else {
        return 100.0 - ((float)(adc_value - min_calibration) / (float)(max_calibration - min_calibration)) * 100.0;
    }
