                fprintf(stderr, "Usage: %s [-c spi_channel] [-a adc_channel] [-m min_calibration] [-x max_calibration] [-t moisture_threshold] [-i logging_interval] [-e email_address] [-f msmtp_config_file]\n", argv[0]);
                return 1;
        }
