#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define VREF 3.3
#define PRESSURE_MIN 0.0
#define PRESSURE_MAX 100.0
#define SENSOR_ABSENT_VOLTAGE_MIN 0.0
#define SENSOR_ABSENT_VOLTAGE_MAX 3.3
#define READ_INTERVAL_SEC 1

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure for configuration
typedef struct {
    int spi_channel;
    int spi_speed;
    int mcp3008_channel;
    float vref;
    float pressure_min;
    float pressure_max;
    float sensor_absent_voltage_min;
    float sensor_absent_voltage_max;
    int read_interval_sec;
} Config;

// Function prototypes
int initialize_pigpio();
int initialize_spi(int channel, int speed);
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value, float vref);
float voltage_to_pressure(float voltage);
void log_data(float pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize SPI interface
int initialize_spi(int channel, int speed) {
    spi_handle = spiOpen(channel, speed, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Convert ADC value to voltage
float adc_to_voltage(int adc_value, float vref) {
    return ((float)adc_value / 1023.0) * vref;
}

// Convert voltage to pressure (kPa)
float voltage_to_pressure(float voltage) {
    // Assuming a linear relationship between voltage and pressure
    // This is a placeholder; replace with the actual sensor's calibration curve
    // Example: 0V = 0 kPa, 3.3V = 100 kPa
    return (voltage / VREF) * (PRESSURE_MAX - PRESSURE_MIN) + PRESSURE_MIN;
}

// Log data with timestamp
void log_data(float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    printf("%s Pressure: %.2f kPa\n", timestamp, pressure);
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
}

int main() {
    // Configuration
    Config config = {
        .spi_channel = SPI_CHANNEL,
        .spi_speed = SPI_SPEED,
        .mcp3008_channel = MCP3008_CHANNEL,
        .vref = VREF,
        .pressure_min = PRESSURE_MIN,
        .pressure_max = PRESSURE_MAX,
        .sensor_absent_voltage_min = SENSOR_ABSENT_VOLTAGE_MIN,
        .sensor_absent_voltage_max = SENSOR_ABSENT_VOLTAGE_MAX,
        .read_interval_sec = READ_INTERVAL_SEC
    };

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi(config.spi_channel, config.spi_speed) != 0) {
        cleanup();
        return 1;
    }

    printf("Pressure sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(config.mcp3008_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to voltage
        float voltage = adc_to_voltage(adc_value, config.vref);

        // Validate voltage
        if (voltage < config.sensor_absent_voltage_min || voltage > config.sensor_absent_voltage_max) {
            fprintf(stderr, "Sensor absent or out of range: Voltage = %.2f V\n", voltage);
            continue; // Skip to the next iteration
        }

        // Convert voltage to pressure
        float pressure = voltage_to_pressure(voltage);

        // Validate pressure
        if (pressure < config.pressure_min || pressure > config.pressure_max) {
            fprintf(stderr, "Pressure out of range: Pressure = %.2f kPa\n", pressure);
            continue; // Skip to the next iteration
        }

        // Log data
        log_data(pressure);

        // Wait for the next reading
        sleep(config.read_interval_sec);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

