        // Read ADC value
        int adc_value = read_mcp3008(config.mcp3008_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to voltage
        float voltage = adc_to_voltage(adc_value, config.vref);

        // Validate voltage
        if (voltage < config.sensor_absent_voltage_min || voltage > config.sensor_absent_voltage_max) {
            fprintf(stderr, "Sensor absent or out of range: Voltage = %.2f V\n", voltage);
