#define MAX30102_REG_FIFO_RD_PTR 0x04
#define MAX30102_REG_FIFO_DATA 0x05
#define MAX30102_REG_FIFO_CONFIG 0x08
#define MAX30102_REG_MODE_CONFIG 0x09
#define MAX30102_REG_SPO2_CONFIG 0x0A
#define MAX30102_REG_LED_CONFIG 0x0C
#define MAX30102_REG_TEMP_INTR 0x1F
#define MAX30102_REG_TEMP_FRAC 0x20
#define MAX30102_REG_TEMP_VALUE 0x21
#define MAX30102_REG_PROX_INT_THRESH 0x30
#define MAX30102_REG_REV_ID 0xFE
#define MAX30102_REG_PART_ID 0xFF

// Configuration values
#define FIFO_SAMPLE_AVG_1 0x40 // 1 sample averaged
#define FIFO_ROLLOVER_ENABLE 0x00 // Rollover disabled
#define FIFO_ALMOST_FULL 0x01 // FIFO almost full interrupt
#define MODE_HRS_ONLY 0x20 // Heart rate only mode
#define SPO2_ADC_RGE_4096 0x03 // ADC range 4096nA
#define SPO2_SR_100 0x03 // Sample rate 100 Hz
#define SPO2_LED_PA_20_MA 0x03 // LED current 20mA
#define TEMP_ENABLE 0x02 // Enable temperature sensor
#define TEMP_ADC_RGE_4096 0x03 // Temperature ADC range 4096nA
#define TEMP_SR_100 0x03 // Temperature sample rate 100 Hz

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int spo2;
    int heart_rate;
} sensor_data_t;

