    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Initialize MAX30102 sensor
int init_max30102() {
    // Check Part ID
    int part_id = i2cReadByteData(i2c_handle, MAX30102_REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error reading Part ID: %d\n", part_id);
        return -1;
    }
    if (part_id != 0x15) {
        fprintf(stderr, "Incorrect Part ID: 0x%02X\n", part_id);
        return -1;
    }

    // Reset the device
    if (i2cWriteByteData(i2c_handle, MAX30102_REG_MODE_CONFIG, 0x40) < 0) {
        fprintf(stderr, "Error resetting MAX30102\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure FIFO
    if (i2cWriteByteData(i2c_handle, MAX30102_REG_FIFO_CONFIG, FIFO_SAMPLE_AVG_1 | FIFO_ROLLOVER_ENABLE | FIFO_ALMOST_FULL) < 0) {
        fprintf(stderr, "Error configuring FIFO\n");
        return -1;
    }

    // Configure Mode
    if (i2cWriteByteData(i2c_handle, MAX30102_REG_MODE_CONFIG, MODE_HRS_ONLY) < 0) {
        fprintf(stderr, "Error configuring Mode\n");
        return -1;
    }

    // Configure SpO2
    if (i2cWriteByteData(i2c_handle, MAX30102_REG_SPO2_CONFIG, SPO2_ADC_RGE_4096 | SPO2_SR_100 | SPO2_LED_PA_20_MA) < 0) {
        fprintf(stderr, "Error configuring SpO2\n");
        return -1;
    }

    // Configure LED Pulse Width
    if (i2cWriteByteData(i2c_handle, MAX30102_REG_LED_CONFIG, 0x03) < 0) {
        fprintf(stderr, "Error configuring LED Pulse Width\n");
        return -1;
    }

    // Configure Temperature
    if (i2cWriteByteData(i2c_handle, MAX30102_REG_TEMP_INTR, TEMP_ENABLE) < 0) {
        fprintf(stderr, "Error configuring Temperature\n");
        return -1;
    }

    return 0;
}

// Read data from MAX30102 sensor
int read_max30102_data(sensor_data_t *data) {
    // Read FIFO data (adjust size as needed)
    char fifo_data[6]; // Example: 3 bytes for red, 3 bytes for IR
    if (i2cReadI2CBlockData(i2c_handle, MAX30102_REG_FIFO_DATA, fifo_data, 6) < 0) {
        fprintf(stderr, "Error reading FIFO data\n");
        return -1;
    }

    // Process the data (replace with actual processing logic)
    // This is a placeholder; refer to the MAX30102 datasheet for the correct data format
    // and processing algorithm.
    int red_value = (fifo_data[0] << 16) | (fifo_data[1] << 8) | fifo_data[2];
    int ir_value = (fifo_data[3] << 16) | (fifo_data[4] << 8) | fifo_data[5];

    // Simple SpO2 and Heart Rate estimation (replace with actual algorithm)
    data->spo2 = 98 + (red_value % 5); // Example SpO2
    data->heart_rate = 70 + (ir_value % 10); // Example Heart Rate

    return 0;
}

// Validate sensor data
int validate_sensor_data(sensor_data_t data) {
    if (data.spo2 < 95 || data.heart_rate > 100) {
        return -1; // Data is invalid
    }
    return 0; // Data is valid
}

// Log health data to file
int log_health_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, SpO2: %d%%, Heart Rate: %d BPM\n", timestamp, data.spo2, data.heart_rate);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MAX30102_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MAX30102 sensor
    if (init_max30102() < 0) {
        fprintf(stderr, "MAX30102 initialization failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("health_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_max30102_data(&sensor_data) == 0) {
            // Validate sensor data
            if (validate_sensor_data(sensor_data) == 0) {
                // Log health data
                log_health_data(sensor_data);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(1000); // Wait for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

