#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define VREF 3.3         // Reference voltage
#define NUM_CHANNELS 3
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define LOG_INTERVAL_MS 500

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_voltage(int adc_value);
char* get_iso8601_timestamp();
int log_data(const char *timestamp, int channel, float voltage);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_speed;
    float vref;
    int num_channels;
    int retry_count;
    int retry_delay_ms;
    int log_interval_ms;
} Config;

Config config = {
    SPI_CHANNEL,
    SPI_SPEED,
    VREF,
    NUM_CHANNELS,
    RETRY_COUNT,
    RETRY_DELAY_MS,
    LOG_INTERVAL_MS
};

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01;                           // Start bit
    tx_buffer[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;                           // Don't care

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (channel %d): %d\n", channel, result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to voltage
float convert_to_voltage(int adc_value) {
    return ((float)adc_value / 1023.0) * config.vref;
}

// Function to get ISO 8601 timestamp
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for timestamp

    if (timestamp == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for timestamp\n");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log data to CSV file
int log_data(const char *timestamp, int channel, float voltage) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open\n");
        return -1;
    }

    int result = fprintf(log_file, "%s,%d,%.3f\n", timestamp, channel, voltage);
    if (result < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C detected. Exiting gracefully...\n");
        terminate = 1;
    }
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    // Open SPI channel
    spi_handle = spiOpen(config.spi_channel, config.spi_speed, 0); // CE0, 1MHz, SPI mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return -1;
    }

    // Open log file
    log_file = fopen("analog_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Channel,Voltage\n");
    }

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    printf("Analog data logger started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        for (int channel = 0; channel < config.num_channels; channel++) {
            int adc_value = -1;
            int retry = 0;

            while (retry < config.retry_count) {
                adc_value = read_mcp3008(channel);
                if (adc_value >= 0) {
                    break; // Success, exit retry loop
                } else {
                    fprintf(stderr, "Retrying read from channel %d (attempt %d/%d)...\n", channel, retry + 1, config.retry_count);
                    gpioDelay(config.retry_delay_ms * 1000); // Delay in microseconds
                    retry++;
                }
            }

            if (adc_value < 0) {
                fprintf(stderr, "Error: Failed to read from channel %d after %d retries\n", channel, config.retry_count);
                // Log the error to the CSV file
                char *timestamp = get_iso8601_timestamp();
                if (timestamp != NULL) {
                    log_data(timestamp, channel, -1.0); // Log -1.0 to indicate error
                    free(timestamp);
                }
                continue; // Skip to the next channel
            }

            float voltage = convert_to_voltage(adc_value);

            // Get timestamp
            char *timestamp = get_iso8601_timestamp();
            if (timestamp == NULL) {
                continue; // Skip to the next channel if timestamp fails
            }

            // Log data
            if (log_data(timestamp, channel, voltage) != 0) {
                fprintf(stderr, "Error: Failed to log data for channel %d\n", channel);
            }

            free(timestamp);
        }

        gpioDelay(config.log_interval_ms * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

