#define NUM_BASELINE_SAMPLES 10
#define BASELINE_SAMPLE_DELAY_MS 50
#define RELAY_PULSE_DURATION_S 3
#define LOG_FILE "/var/log/door_events.log"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_ads1115(int16_t *value);
int calibrate_sensor(int16_t *baseline);
int control_relay(int state);
int read_reed_sensor();
int log_event(const char *event);
