void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int ads1115_address;
    int gpio_relay;
    int gpio_reed_sensor;
    int distance_threshold;
    int num_baseline_samples;
    int baseline_sample_delay_ms;
    int relay_pulse_duration_s;
    char log_file[256];
} config_t;

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Read data from ADS1115
int read_ads1115(int16_t *value) {
    uint8_t config[3];
    uint8_t buffer[2];

    // Configure ADS1115 for single-ended A0, 4.096V range, continuous conversion, 128 SPS
    config[0] = ADS1115_REG_CONFIG;
    config[1] = 0xC2; // 0b11000010
    config[2] = 0x83; // 0b10000011

    if (write(i2c_fd, config, 3) != 3) {
        perror("Error writing to ADS1115 config register");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    usleep(10000); // 10ms

    // Read conversion register
    config[0] = ADS1115_REG_CONVERT;
    if (write(i2c_fd, config, 1) != 1) {
        perror("Error writing to ADS1115 conversion register");
        return -1;
    }

    if (read(i2c_fd, buffer, 2) != 2) {
        perror("Error reading from ADS1115 conversion register");
        return -1;
    }

    *value = (buffer[0] << 8) | buffer[1];
    return 0;
