                usleep(RELAY_PULSE_DURATION_S * 1000000); // Convert seconds to microseconds

                // De-activate relay
                control_relay(0);
                log_event("Relay de-activated.");

                // Read reed sensor
                reed_state = read_reed_sensor();

                // Log event based on reed sensor state
                if (reed_state == 0) {
