#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

// Define GPIO pins for chip select lines
#define CS0_PIN 8
#define CS1_PIN 7
#define CS2_PIN 25

// Define SPI device
#define SPI_DEVICE "/dev/spidev0.0"

// Define SPI mode
#define SPI_MODE SPI_MODE_0

// Define SPI speed (1 MHz)
#define SPI_SPEED 1000000

// Define CSV file name
#define CSV_FILE "soil_moisture_log.csv"

// Global variables
int spi_fd;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int read_mcp3008(int channel, int cs_pin);
int log_data(int sensor1, int sensor2, int sensor3);
void signal_handler(int signal);
void cleanup(void);

// Structure to hold SPI configuration
typedef struct {
    int fd;
    int mode;
    int speed;
} spi_config_t;

// SPI initialization function
int spi_init(void) {
    spi_config_t config;
    config.mode = SPI_MODE;
    config.speed = SPI_SPEED;

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &config.mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set SPI speed
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &config.speed) == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel, int cs_pin) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = 8;

    // Manually control chip select
    gpioWrite(cs_pin, 0); // Select the chip

    // Transfer data
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 1) {
        perror("Error during SPI transfer");
        gpioWrite(cs_pin, 1); // Deselect the chip
        return -1;
    }

    gpioWrite(cs_pin, 1); // Deselect the chip

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// Function to log data to CSV file
int log_data(int sensor1, int sensor2, int sensor3) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Get current timestamp
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Check if the file exists and write the header if it doesn't
    if (access(CSV_FILE, F_OK) == -1) {
        log_file = fopen(CSV_FILE, "w");
        if (log_file == NULL) {
            perror("Error opening CSV file for writing");
            return -1;
        }
        fprintf(log_file, "timestamp,sensor1,sensor2,sensor3\n");
        fclose(log_file);
    }

    // Open the file in append mode
    log_file = fopen(CSV_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening CSV file for appending");
        return -1;
    }

    // Write data to the file
    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, sensor1, sensor2, sensor3);

    // Close the file
    fclose(log_file);

    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup(void) {
    printf("Cleaning up...\n");

    // Close SPI device
    if (spi_fd > 0) {
        close(spi_fd);
    }

    // Release GPIO pins
    gpioWrite(CS0_PIN, 1);
    gpioWrite(CS1_PIN, 1);
    gpioWrite(CS2_PIN, 1);
    gpioSetMode(CS0_PIN, PI_INPUT); // Set back to input
    gpioSetMode(CS1_PIN, PI_INPUT);
    gpioSetMode(CS2_PIN, PI_INPUT);

    // Terminate pigpio
    gpioTerminate();
}

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as output
    gpioSetMode(CS0_PIN, PI_OUTPUT);
    gpioSetMode(CS1_PIN, PI_OUTPUT);
    gpioSetMode(CS2_PIN, PI_OUTPUT);

    // Initialize SPI
    if (spi_init() != 0) {
        cleanup();
        return 1;
    }

    // Set initial chip select states to high (inactive)
    gpioWrite(CS0_PIN, 1);
    gpioWrite(CS1_PIN, 1);
    gpioWrite(CS2_PIN, 1);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int sensor1_value = read_mcp3008(0, CS0_PIN);
        int sensor2_value = read_mcp3008(0, CS1_PIN);
        int sensor3_value = read_mcp3008(0, CS2_PIN);

        // Log the data
        if (log_data(sensor1_value, sensor2_value, sensor3_value) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

