#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define PUMP_GPIO 18
#define DEFAULT_THRESHOLD 30.0
#define DEFAULT_PUMP_DURATION 10.0
#define DEFAULT_SLEEP_INTERVAL 60.0
#define MAX_RETRIES 3
#define LOG_FILE "irrigation.log"

// Global variables
int spi_handle;
double threshold = DEFAULT_THRESHOLD;
double pump_duration = DEFAULT_PUMP_DURATION;
double sleep_interval = DEFAULT_SLEEP_INTERVAL;
FILE *log_file;

// Function prototypes
int read_mcp3008(int channel);
double calculate_moisture_percentage(int adc_value);
int control_pump(int state);
void log_message(const char *message);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        log_message("Error: Invalid MCP3008 channel.");
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;

    int retries = 0;
    while (retries < MAX_RETRIES) {
        int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
        if (result == 0) {
            int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
            return adc_value;
        } else {
            char error_message[100];
            snprintf(error_message, sizeof(error_message), "SPI transfer failed (attempt %d): %d", retries + 1, result);
            log_message(error_message);
            gpioDelay(10000); // Wait 10ms before retrying
            retries++;
        }
    }

    log_message("Error: SPI transfer failed after multiple retries.");
    return -1; // Indicate failure
}

// Function to calculate moisture percentage
double calculate_moisture_percentage(int adc_value) {
    return ((double)adc_value / 1023.0) * 100.0;
}

// Function to control the water pump
int control_pump(int state) {
    if (gpioWrite(PUMP_GPIO, state) != 0) {
        log_message("Error: Failed to write to pump GPIO.");
        return -1;
    }
    return 0;
}

// Function to log messages to a file
void log_message(const char *message) {
