    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is initially off

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    log_message("Program started.");

    return 0;
}

// Cleanup function
void cleanup() {
    log_message("Cleaning up...");
    control_pump(0); // Ensure pump is off
    spiClose(spi_handle);
    gpioTerminate();
    fclose(log_file);
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            case 'd':
                pump_duration = atof(optarg);
                break;
            case 's':
                sleep_interval = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d pump_duration] [-s sleep_interval]\n", argv[0]);
                return 1;
        }
    }

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value == -1) {
            log_message("Error: Failed to read ADC value.");
            gpioDelay(sleep_interval * 1000000); // Sleep before next attempt
            continue;
        }

        // Calculate moisture percentage
        double moisture_percentage = calculate_moisture_percentage(adc_value);

        // Log moisture reading
        char log_message_buffer[100];
        snprintf(log_message_buffer, sizeof(log_message_buffer), "Moisture level: %.2f%% (ADC: %d)", moisture_percentage, adc_value);
        log_message(log_message_buffer);

        // Check if moisture level is below threshold
        if (moisture_percentage < threshold) {
            // Activate pump
            if (control_pump(1) == 0) {
                log_message("Pump activated.");

                // Wait for pump duration
                gpioDelay(pump_duration * 1000000);

                // Deactivate pump
                if (control_pump(0) == 0) {
                    log_message("Pump deactivated.");
                } else {
                    log_message("Error: Failed to deactivate pump.");
                }
            } else {
                log_message("Error: Failed to activate pump.");
            }
        }

        // Sleep for specified interval
        gpioDelay(sleep_interval * 1000000);
    }

    return 0;
}

