#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define THRESHOLD_MULTIPLIER 1.5
#define LOG_FILE "/var/log/sound_events.log"
#define SAMPLE_INTERVAL_MS 10

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold program state
typedef struct {
    int spi_handle;
    FILE *log_file;
} ProgramState;

// Function prototypes
int initialize_pigpio();
int initialize_spi();
int read_mcp3008(int channel);
float calculate_threshold(int *history, int history_size);
int detect_peak(int sample, float threshold);
int log_event(int sample);
void signal_handler(int signal);
void cleanup(ProgramState *state);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Calculate dynamic threshold
float calculate_threshold(int *history, int history_size) {
    if (history_size <= 0) return 0.0;

    float sum = 0.0;
    for (int i = 0; i < history_size; i++) {
        sum += history[i];
    }
    float average = sum / history_size;

    return average * THRESHOLD_MULTIPLIER;
}

// Detect peak
int detect_peak(int sample, float threshold) {
    return (sample > threshold);
}

// Log event to file
int log_event(int sample) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s, %d\n", timestamp, sample);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Cleanup resources
void cleanup(ProgramState *state) {
    printf("Cleaning up...\n");
    if (state->spi_handle >= 0) {
        spiClose(state->spi_handle);
    }
    if (state->log_file != NULL) {
        fclose(state->log_file);
    }
    gpioTerminate();
}

int main() {
    ProgramState state = { .spi_handle = -1, .log_file = NULL };

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup(&state);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        cleanup(&state);
        return 1;
    }

    // Moving average filter history
    int history_size = 100; // 1 second of history
    int history[history_size];
    int history_index = 0;
    float threshold = 0.0;

    printf("Sound level monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC value
        int sample = read_mcp3008(MCP3008_CHANNEL);
        if (sample < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            break;
        }

        // Update moving average filter
        history[history_index] = sample;
        history_index = (history_index + 1) % history_size;

        // Calculate threshold
        threshold = calculate_threshold(history, history_size);

        // Detect peak
        if (detect_peak(sample, threshold)) {
            printf("Peak detected: %d (Threshold: %.2f)\n", sample, threshold);
            if (log_event(sample) != 0) {
                fprintf(stderr, "Failed to log event\n");
                break;
            }
        }

        // Delay
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup(&state);
    printf("Exiting.\n");
    return 0;
}

