    int history_index = 0;
    float threshold = 0.0;

    printf("Sound level monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC value
        int sample = read_mcp3008(MCP3008_CHANNEL);
        if (sample < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            break;
        }

        // Update moving average filter
        history[history_index] = sample;
        history_index = (history_index + 1) % history_size;

        // Calculate threshold
        threshold = calculate_threshold(history, history_size);

        // Detect peak
        if (detect_peak(sample, threshold)) {
            printf("Peak detected: %d (Threshold: %.2f)\n", sample, threshold);
