#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <syslog.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define GPIO_PIN 27
#define THRESHOLD 500.0 // Gauss
#define BUFFER_SIZE 10
#define VOLTAGE_MIN 0.0
#define VOLTAGE_MAX 3.3
#define SENSITIVITY 0.000122 // V/Gauss (for SS49E)
#define ADC_RESOLUTION 4096.0

// Global variables
int i2c_handle;
bool running = true;

// Circular buffer
float magnetic_field_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int initialize_i2c();
int read_adc(int channel);
float convert_to_voltage(int adc_value);
float convert_to_magnetic_field(float voltage);
void update_circular_buffer(float magnetic_field);
float calculate_rolling_average();
void control_gpio(float average_magnetic_field);
void signal_handler(int signal);
void log_message(int priority, const char *message);

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        log_message(LOG_ERR, "Failed to open I2C device.");
        return -1;
    }

    // Configure ADS1115 for single-ended AIN0, 128 SPS, +/-4.096V, continuous conversion
    uint16_t config = 0x4003; // 0b0100000000000011
    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;

    if (i2cWriteDevice(i2c_handle, buf, 3) != 0) {
        log_message(LOG_ERR, "Failed to write to I2C device.");
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Function to read ADC value from ADS1115
int read_adc(int channel) {
    if (channel < 0 || channel > 3) {
        log_message(LOG_ERR, "Invalid ADC channel.");
        return -1;
    }

    // Read conversion register
    char buf[1];
    buf[0] = CONVERSION_REG;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        log_message(LOG_ERR, "Failed to write to I2C device for conversion read.");
        return -1;
    }

    char read_buf[2];
    if (i2cReadDevice(i2c_handle, read_buf, 2) != 2) {
        log_message(LOG_ERR, "Failed to read from I2C device.");
        return -1;
    }

    int16_t adc_value = (read_buf[0] << 8) | read_buf[1];
    return adc_value;
}

// Function to convert ADC value to voltage
float convert_to_voltage(int adc_value) {
    float voltage = (float)adc_value * 4.096 / ADC_RESOLUTION;
    return voltage;
}

// Function to convert voltage to magnetic field strength
float convert_to_magnetic_field(float voltage) {
    float magnetic_field = voltage / SENSITIVITY;
    return magnetic_field;
}

// Function to update the circular buffer
void update_circular_buffer(float magnetic_field) {
    magnetic_field_buffer[buffer_index] = magnetic_field;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to calculate the rolling average
float calculate_rolling_average() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += magnetic_field_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Function to control GPIO pin
void control_gpio(float average_magnetic_field) {
    if (average_magnetic_field > THRESHOLD) {
        gpioWrite(GPIO_PIN, 1); // Set GPIO HIGH
        log_message(LOG_WARNING, "Threshold exceeded! Motor shutdown.");
    } else {
        gpioWrite(GPIO_PIN, 0); // Set GPIO LOW
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = false;
    log_message(LOG_INFO, "Received signal, shutting down...");
}

// Function to log messages to syslog
void log_message(int priority, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    char log_entry[256];
    snprintf(log_entry, sizeof(log_entry), "%s: %s", timestamp, message);
    syslog(priority, "%s", log_entry);
}

int main() {
    // Initialize syslog
    openlog("honeywell_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Initialize to LOW

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_message(LOG_INFO, "Honeywell monitor started.");

    // Main loop
    while (running) {
        // Read ADC value
        int adc_value = read_adc(0);
        if (adc_value < 0) {
            log_message(LOG_ERR, "Failed to read ADC value.");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Convert ADC value to voltage
        float voltage = convert_to_voltage(adc_value);

        // Validate voltage
        if (voltage < VOLTAGE_MIN || voltage > VOLTAGE_MAX) {
            log_message(LOG_ERR, "Voltage out of range.");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Convert voltage to magnetic field strength
        float magnetic_field = convert_to_magnetic_field(voltage);

        // Update circular buffer
        update_circular_buffer(magnetic_field);

        // Calculate rolling average
        float average_magnetic_field = calculate_rolling_average();

        // Control GPIO pin
        control_gpio(average_magnetic_field);

        // Log data
        char log_buffer[256];
        snprintf(log_buffer, sizeof(log_buffer), "Voltage: %.3f V, Magnetic Field: %.3f Gauss, Average: %.3f Gauss", voltage, magnetic_field, average_magnetic_field);
        log_message(LOG_INFO, log_buffer);

        // Wait for 1 second
        gpioDelay(1000);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(GPIO_PIN, 0); // Set GPIO LOW
    gpioTerminate();
    closelog();

    log_message(LOG_INFO, "Honeywell monitor stopped.");

    return 0;
}

