float map_adc_to_rainfall(int adc_value) {
    if (adc_value < 0 || adc_value > MAX_ADC_VALUE) {
        fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
        return -1.0; // Indicate error
    }

    float rainfall_intensity = rainfall_levels[0]; // Default to lowest level
    for (int i = 0; i < RAIN_INTENSITY_LEVELS - 1; i++) {
        if (adc_value >= (MAX_ADC_VALUE * (float)i / (RAIN_INTENSITY_LEVELS - 1)) &&
            adc_value <= (MAX_ADC_VALUE * (float)(i + 1) / (RAIN_INTENSITY_LEVELS - 1))) {
            rainfall_intensity = rainfall_levels[i];
            break;
        }
    }

    return rainfall_intensity;
}

