        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value, retrying in 1 second...\n");
            sleep(1);
            continue; // Retry
        }

        // Map ADC value to rainfall intensity
        float rainfall_intensity = map_adc_to_rainfall(adc_value);
        if (rainfall_intensity < 0) {
            fprintf(stderr, "Failed to map ADC value to rainfall intensity, retrying in 1 second...\n");
            sleep(1);
            continue; // Retry
        }

        // Log data
        log_data(adc_value, rainfall_intensity);

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

