// Define GPIO pins
#define MCP3008_CE0 8
#define MCP3008_CE1 7
#define MCP3008_CS 25
#define MCP3008_MOSI 10
#define MCP3008_MISO 9
#define MCP3008_SCLK 11
#define MOTOR_PWM 18

// Define SPI channel
#define SPI_CHANNEL 0

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Define PWM range
#define PWM_RANGE 1024

// Define ADC channel
#define ADC_CHANNEL 0

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int initialize_spi();
int read_mcp3008(int channel);
int set_motor_speed(int speed);
void signal_handler(int signal);
void cleanup();

// Structure to hold SPI configuration
typedef struct {
    int ce_pin;
    int cs_pin;
    int mosi_pin;
    int miso_pin;
    int sclk_pin;
} spi_config_t;

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to initialize SPI
int initialize_spi() {
    spi_config_t spi_config = {
        .ce_pin = MCP3008_CE0,
        .cs_pin = MCP3008_CS,
        .mosi_pin = MCP3008_MOSI,
        .miso_pin = MCP3008_MISO,
        .sclk_pin = MCP3008_SCLK
    };

    gpioSetMode(spi_config.ce_pin, PI_OUTPUT);
    gpioSetMode(spi_config.cs_pin, PI_OUTPUT);
    gpioSetMode(spi_config.mosi_pin, PI_OUTPUT);
    gpioSetMode(spi_config.miso_pin, PI_INPUT);
    gpioSetMode(spi_config.sclk_pin, PI_OUTPUT);

    gpioWrite(spi_config.ce_pin, 1); // Deselect CE0 initially
    gpioWrite(spi_config.cs_pin, 1); // Deselect CS initially

    spi_handle = spiOpen(SPI_CHANNEL, 1000000, 0); // Open SPI channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read from MCP3008
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(MCP3008_CS, 0); // Select MCP3008
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(MCP3008_CS, 1); // Deselect MCP3008

    if (result != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to set motor speed using PWM
int set_motor_speed(int speed) {
    if (speed < 0 || speed > PWM_RANGE) {
        fprintf(stderr, "Invalid PWM value: %d\n", speed);
        return -1;
    }

    gpioPWM(MOTOR_PWM, speed);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stdout, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    fprintf(stdout, "Cleaning up resources...\n");
    gpioPWM(MOTOR_PWM, 0); // Stop PWM
    spiClose(spi_handle);
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Configure PWM
    gpioSetMode(MOTOR_PWM, PI_OUTPUT);
    gpioSetPWMfrequency(MOTOR_PWM, PWM_FREQUENCY);
    gpioSetPWMrange(MOTOR_PWM, PWM_RANGE);

    fprintf(stdout, "Motor control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Set motor speed
        if (set_motor_speed(adc_value) != 0) {
            fprintf(stderr, "Failed to set motor speed, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Print ADC value and PWM value
        fprintf(stdout, "ADC Value: %d, PWM Value: %d\n", adc_value, adc_value);

        // Wait for 100ms
        gpioDelay(100);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

