#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define LED_GPIO 17
#define DEFAULT_THRESHOLD 100.0
#define SENSITIVITY 0.000122 // V/Gauss (for SS49E)
#define VREF 4.096 // Reference voltage

// Global variables
int i2c_handle;
double threshold = DEFAULT_THRESHOLD;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_adc(int channel);
double convert_to_gauss(int adc_value);
void control_led(int state);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional, but good practice)
typedef struct {
    int i2c_bus;
    int ads1115_address;
    int led_gpio;
    double default_threshold;
    double sensitivity;
    double vref;
} AppConfig;

AppConfig config = {
    .i2c_bus = I2C_BUS,
    .ads1115_address = ADS1115_ADDR,
    .led_gpio = LED_GPIO,
    .default_threshold = DEFAULT_THRESHOLD,
    .sensitivity = SENSITIVITY,
    .vref = VREF
};

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(config.led_gpio, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Monitoring magnetic field... (Threshold: %.2f Gauss)\n", threshold);

    // Main loop
    while (!terminate) {
        // Read ADC value from AIN0
        int adc_value = read_adc(0);
        if (adc_value < 0) {
