        double gauss = convert_to_gauss(adc_value);

        // Print Gauss value
        printf("Magnetic Field: %.2f Gauss\n", gauss);

        // Check if threshold is exceeded
        if (gauss > threshold) {
            printf("Threshold exceeded! Blinking LED...\n");
            control_led(1); // Turn LED on
            gpioDelay(1000); // Wait for 1 second
            control_led(0); // Turn LED off
        }

        gpioDelay(100); // Wait 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

