int init_i2c() {
    i2c_handle = i2cOpen(config.i2c_bus, config.ads1115_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }

    // Configure ADS1115 for single-ended AIN0, PGA=4.096V, continuous conversion
    uint16_t config_value = 0x4003; // 0b0100000000000011
    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config_value >> 8) & 0xFF;
    buf[2] = config_value & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to write to config register: %d\n", result);
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Read ADC value from specified channel
int read_adc(int channel) {
    // Construct the configuration register value
    uint16_t config_value = 0x4003; // 0b0100000000000011
    config_value |= (channel << 12); // Set the channel

    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config_value >> 8) & 0xFF;
    buf[2] = config_value & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to write to config register for channel %d: %d\n", channel, result);
        return -1;
    }

    gpioDelay(10); // Wait for conversion to complete

    // Read the conversion register
    char read_buf[2];
    result = i2cReadDevice(i2c_handle, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read conversion register: %d\n", result);
        return -1;
    }

    // Combine the two bytes to form the ADC value
    int16_t adc_value = (read_buf[0] << 8) | read_buf[1];

    return adc_value;
}

// Convert ADC value to Gauss
double convert_to_gauss(int adc_value) {
    // Convert ADC value to voltage
    double voltage = (adc_value * config.vref) / 32768.0;

    // Convert voltage to Gauss
    double gauss = voltage / config.sensitivity;

    return gauss;
}

// Control the LED
void control_led(int state) {
    gpioWrite(config.led_gpio, state);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    control_led(0); // Turn off LED
    i2cClose(i2c_handle); // Close I2C device
    gpioTerminate(); // Terminate pigpio
}

