    return adc_value;
}

// Function to calculate moisture percentage
int calculate_moisture_percentage(int adc_value) {
    // Assuming ADC range is 0-1023 and moisture range is 0-100%
    // This is a linear mapping.  Adjust as needed for your sensor.
    if (adc_value < 0) adc_value = 0; //Clamp negative values
    if (adc_value > 1023) adc_value = 1023; //Clamp max value
    return 100 - (int)(((float)adc_value / 1023.0) * 100.0);
}

// Function to control the pump
void control_pump(int moisture_percentage) {
    static int pump_state = 0; // 0 = off, 1 = on

    if (moisture_percentage < MOISTURE_THRESHOLD_LOW && pump_state == 0) {
        gpioWrite(PUMP_GPIO, 1); // Turn pump on
        pump_state = 1;
        syslog(LOG_INFO, "Pump turned ON (Moisture: %d%%)", moisture_percentage);
    } else if (moisture_percentage > MOISTURE_THRESHOLD_HIGH && pump_state == 1) {
        gpioWrite(PUMP_GPIO, 0); // Turn pump off
        pump_state = 0;
        syslog(LOG_INFO, "Pump turned OFF (Moisture: %d%%)", moisture_percentage);
    }
}

// Function to publish moisture data to MQTT
void publish_moisture_data(int moisture_percentage) {
    char payload[10];
    snprintf(payload, sizeof(payload), "%d", moisture_percentage);

    int result = mosquitto_publish(mosq, NULL, MQTT_TOPIC_SOIL_MOISTURE, strlen(payload), payload, 0, false);
    if (result != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to publish moisture data: %s", mosquitto_strerror(result));
    } else {
        syslog(LOG_INFO, "Published moisture data: %s", payload);
    }
}

// MQTT message callback function
void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        syslog(LOG_INFO, "Received message on topic %s: %s", message->topic, (char *)message->payload);

        if (strcmp(message->topic, MQTT_TOPIC_PUMP_CONTROL) == 0) {
            if (strcmp((char *)message->payload, "pump_on") == 0) {
                gpioWrite(PUMP_GPIO, 1);
                syslog(LOG_INFO, "Pump turned ON via MQTT command");
            } else if (strcmp((char *)message->payload, "pump_off") == 0) {
                gpioWrite(PUMP_GPIO, 0);
                syslog(LOG_INFO, "Pump turned OFF via MQTT command");
            } else {
                syslog(LOG_WARNING, "Invalid pump control command: %s", (char *)message->payload);
            }
        }
    }
}

// MQTT connect callback function
void connect_callback(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "Connected to MQTT broker");
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC_PUMP_CONTROL, 0);
    } else {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(result));
    }
}

// MQTT disconnect callback function
void disconnect_callback(struct mosquitto *mosq, void *userdata, int rc) {
    syslog(LOG_WARNING, "Disconnected from MQTT broker (rc=%d)", rc);
}

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is initially off
    syslog(LOG_INFO, "GPIO initialized");
    return 0;
}

// Initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        syslog(LOG_ERR, "SPI initialisation failed: %d", spi_handle);
        return -1;
    }
    syslog(LOG_INFO, "SPI initialized");
    return 0;
}

// Initialize MQTT
int initialize_mqtt() {
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create mosquitto instance");
        return -1;
    }

    mosquitto_connect_callback_set(mosq, connect_callback);
    mosquitto_disconnect_callback_set(mosq, disconnect_callback);
    mosquitto_message_callback_set(mosq, message_callback);

    int result = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (result != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(result));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return -1;
    }

    mosquitto_loop_start(mosq);
    syslog(LOG_INFO, "MQTT initialized and connected");
    return 0;
}

// Cleanup resources
void cleanup() {
    syslog(LOG_INFO, "Cleaning up resources...");

    // Turn off pump
    gpioWrite(PUMP_GPIO, 0);

    // Close SPI
    spiClose(spi_handle);

    // Disconnect from MQTT
    if (mosq) {
        mosquitto_loop_stop(mosq, false);
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
    }
    mosquitto_lib_cleanup();

    // Terminate pigpio
    gpioTerminate();

    syslog(LOG_INFO, "Cleanup complete. Exiting.");
}

int main() {
    // Open syslog
    openlog("soil_moisture_sensor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        syslog(LOG_ERR, "SPI initialization failed, exiting");
        cleanup();
        closelog();
        return 1;
    }

    // Initialize MQTT
    if (initialize_mqtt() != 0) {
        syslog(LOG_ERR, "MQTT initialization failed, exiting");
        cleanup();
        closelog();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            syslog(LOG_ERR, "Failed to read ADC value, retrying in %d seconds", MQTT_RECONNECT_DELAY);
            sleep(MQTT_RECONNECT_DELAY);
            continue;
        }

        // Calculate moisture percentage
        int moisture_percentage = calculate_moisture_percentage(adc_value);

        // Control pump
        control_pump(moisture_percentage);

        // Publish moisture data
        publish_moisture_data(moisture_percentage);

        // Sleep for 60 seconds
        sleep(SLEEP_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    closelog();
    return 0;
}

