#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define SPI device and mode
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz

// Define MCP3008 channel
#define MCP3008_CHANNEL 0

// Define VDD and VREF
#define VDD 3.3
#define VREF 3.3

// Global variable for SPI file descriptor
int spi_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (spi_fd != -1) {
        close(spi_fd);
    }
    exit(0);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int spi_fd, int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    // Perform SPI transaction
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        fprintf(stderr, "Error: SPI transaction failed: %s\n", strerror(errno));
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error: Could not open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return 1;
    }

    // Configure SPI mode
    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error: Could not set SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    // Configure bits per word
    int bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error: Could not set bits per word: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    // Configure SPI speed
    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error: Could not set SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read ADC value
        int adc_value = read_mcp3008(spi_fd, MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Continue to the next iteration
        }

        // Calculate voltage
        float voltage = ((float)adc_value / 1023.0) * VREF;

        // Print ADC value and voltage
        printf("Raw ADC Value: %d, Voltage: %.3f V\n", adc_value, voltage);

        // Wait 500 milliseconds
        usleep(500000);
    }

    // Close SPI device (this will not be reached in the infinite loop)
    close(spi_fd);

    return 0;
}

