#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define BH1750_I2C_ADDR 0x23
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define CSV_FILE "tamper_log.csv"
#define SAMPLE_INTERVAL_SEC 5

// Global variables
int spi_fd = -1;
int i2c_fd = -1;
FILE *csv_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_sound_level(int adc_value);
int read_bh1750();
float calculate_light_level(int raw_value);
void log_data(float sound_level, float light_level, int error_code);
void signal_handler(int signal);
int initialize();
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize pigpio and SPI
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    spi_fd = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_fd < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return -1;
    }

    i2c_fd = i2cOpen(1, BH1750_I2C_ADDR, 0); // Bus 1, address 0x23, no flags
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C open failed\n");
        spiClose(spi_fd);
        gpioTerminate();
        return -1;
    }

    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Failed to open CSV file\n");
        i2cClose(i2c_fd);
        spiClose(spi_fd);
        gpioTerminate();
        return -1;
    }

    // Write header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "timestamp,sound_level_db,light_level_lux,error_code\n");
    }
    rewind(csv_file);

    return 0;
}

// Cleanup resources
void cleanup() {
    if (spi_fd >= 0) {
        spiClose(spi_fd);
    }
    if (i2c_fd >= 0) {
        i2cClose(i2c_fd);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    gpioTerminate();
}

// Read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel\n");
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;

    if (spiXfer(spi_fd, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Calculate sound level (example: linear mapping)
float calculate_sound_level(int adc_value) {
    // Assuming ADC range is 0-1023 and sound level is 0-100 dB
    return (float)adc_value / 1023.0 * 100.0;
}

// Read from BH1750 sensor
int read_bh1750() {
    char config_cmd = BH1750_CONTINUOUS_HIGH_RES_MODE;
    char buffer[2];

    if (i2cWriteByteData(i2c_fd, 0x00, config_cmd) != 0) {
        fprintf(stderr, "Failed to configure BH1750\n");
        return -1;
    }

    gpioDelay(180000); // Wait 180 ms

    if (i2cReadI2CBlockData(i2c_fd, 0x00, buffer, 2) != 2) {
        fprintf(stderr, "Failed to read BH1750 data\n");
        return -1;
    }

    int raw_value = (buffer[0] << 8) | buffer[1];
    return raw_value;
}

// Calculate light level (example: lux calculation)
float calculate_light_level(int raw_value) {
    // BH1750 datasheet formula
    return (float)raw_value / 1.2;
}

// Log data to CSV file
void log_data(float sound_level, float light_level, int error_code) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(csv_file, "%s,%.2f,%.2f,%d\n", timestamp, sound_level, light_level, error_code);
    fflush(csv_file); // Ensure data is written to disk immediately
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize() != 0) {
        return 1;
    }

    printf("Tamper detection system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        int bh1750_value = read_bh1750();
        int error_code = 0;

        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            error_code |= 1;
        }
        if (bh1750_value < 0) {
            fprintf(stderr, "Error reading BH1750 value\n");
            error_code |= 2;
        }

        float sound_level = calculate_sound_level(adc_value);
        float light_level = calculate_light_level(bh1750_value);

        log_data(sound_level, light_level, error_code);

        sleep(SAMPLE_INTERVAL_SEC);
    }

    cleanup();
    printf("Tamper detection system stopped.\n");
    return 0;
}

