    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Door monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            // Attempt to re-initialize SPI
            spiClose(spi_handle);
            spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
            if (spi_handle < 0) {
                fprintf(stderr, "Error: SPI re-initialization failed: %d\n", spi_handle);
                program_running = 0; // Exit loop if re-initialization fails
                continue;
            }
            gpioDelay(100); // Small delay before retrying
            continue;
        }

        // Convert ADC value to distance
        float distance = adc_to_distance(adc_value);

        // Check if distance is below threshold
        if (distance < DISTANCE_THRESHOLD) {
