#include <wiringPi.h>
#include <wiringPiSPI.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define VALVE_GPIO 17
#define PWM_FREQUENCY 100
#define PWM_RANGE 100
#define LOG_FILE "irrigation.log"
#define SAMPLE_INTERVAL 5 // seconds

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
float calculate_average(int sample1, int sample2, int sample3);
void set_valve_position(float average);
void log_data(int sample1, int sample2, int sample3, float average, int valve_position);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char buffer[3];
    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00;

    if (wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3) == -1) {
        fprintf(stderr, "Error: SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];
    return adc_value;
}

// Function to calculate the average of three samples
float calculate_average(int sample1, int sample2, int sample3) {
    float sum = 0.0;
    int valid_samples = 0;

    if (sample1 >= 0) {
        sum += sample1;
        valid_samples++;
    }
    if (sample2 >= 0) {
        sum += sample2;
        valid_samples++;
    }
    if (sample3 >= 0) {
        sum += sample3;
        valid_samples++;
    }

    if (valid_samples == 0) {
        return -1.0; // Indicate no valid samples
    }

    return sum / valid_samples;
}

// Function to set the valve position using PWM
void set_valve_position(float average) {
    if (average < 0.0) {
        fprintf(stderr, "Error: Invalid average value: %f\n", average);
        return;
    }

    int duty_cycle = (int)(average / 1023.0 * PWM_RANGE); // Scale to PWM range
    pwmWrite(VALVE_GPIO, duty_cycle);
}

// Function to log data to a file
void log_data(int sample1, int sample2, int sample3, float average, int valve_position) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Sample1: %d, Sample2: %d, Sample3: %d, Average: %.2f, Valve Position: %d\n",
            timestamp, sample1, sample2, sample3, average, valve_position);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    program_running = 0;
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error: wiringPiSetupGpio failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize SPI
    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) == -1) {
        fprintf(stderr, "Error: wiringPiSPISetup failed: %s\n", strerror(errno));
        return 1;
    }

    // Configure valve GPIO as PWM output
    pinMode(VALVE_GPIO, PWM_OUTPUT);
    pwmSetMode(PWM_MODE_MS); // Mark:Space PWM mode
    pwmSetClock(192); // Adjust clock for desired frequency (19.2 MHz / 192 = 100 kHz)
    pwmSetRange(PWM_RANGE);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil moisture monitoring and valve control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int sample1 = read_mcp3008(0);
        int sample2 = read_mcp3008(1);
        int sample3 = read_mcp3008(2);

        float average = calculate_average(sample1, sample2, sample3);

        if (average >= 0.0) {
            set_valve_position(average);
            int valve_position = (int)(average / 1023.0 * PWM_RANGE);
            log_data(sample1, sample2, sample3, average, valve_position);
        } else {
            fprintf(stderr, "Error: Could not calculate average. Skipping valve control.\n");
        }

        delay(SAMPLE_INTERVAL * 1000); // Delay for 5 seconds
    }

    // Cleanup
    pwmWrite(VALVE_GPIO, 0); // Stop the valve
    fclose(log_file);

    printf("Program terminated.\n");
    return 0;
}

