#define MIN_DISTANCE 2.0   // Minimum measurable distance in cm
#define MAX_DISTANCE 200.0  // Maximum measurable distance in cm
#define MIN_FREQUENCY 200.0 // Minimum frequency in Hz
#define MAX_FREQUENCY 2000.0 // Maximum frequency in Hz
#define MIN_VOLUME 0.0      // Minimum volume (0.0 - 1.0)
#define MAX_VOLUME 1.0      // Maximum volume (0.0 - 1.0)
#define PWM_RANGE 1000      // PWM range
#define CONFIG_FILE "theremin_config.txt"

// Global variables
static volatile int running = 1;
static int spi_handle;
static float distance_offset = 0.0;
static float ldr_offset = 0.0;

