    fclose(fp);
    printf("Configuration saved: distance_offset=%f, ldr_offset=%f\n", distance_offset, ldr_offset);
    return 0;
}

// Function to read ultrasonic distance using HC-SR04
float read_ultrasonic_distance() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIG_PIN, 0);

    uint32_t start_tick = 0, end_tick = 0;

    // Wait for echo to start
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < 10000) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }
    if (count >= 10000) {
        fprintf(stderr, "Timeout waiting for echo start\n");
        return -1.0; // Indicate error
    }
    start_tick = gpioTick();

    // Wait for echo to end
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < 10000) {
        count++;
        gpioDelay(1);
    }
    if (count >= 10000) {
        fprintf(stderr, "Timeout waiting for echo end\n");
        return -1.0; // Indicate error
    }
    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    if (diff > 0xFFFFFFFF) {
        fprintf(stderr, "Tick difference overflow\n");
        return -1.0;
    }

    float time_taken = (float)diff / 1000000.0; // Time in seconds
    float distance = (time_taken * SOUND_SPEED) / 2.0; // Distance in cm

    return distance;
}

// Function to read LDR value from MCP3008
int read_ldr() {
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // MCP3008 configuration: single-ended channel 0
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = 0x80; // Single-ended, channel 0 (10000000)
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1; // Indicate error
    }

    // Extract the ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to map distance to frequency
float map_distance_to_frequency(float distance) {
    if (distance < MIN_DISTANCE) {
        distance = MIN_DISTANCE;
    } else if (distance > MAX_DISTANCE) {
        distance = MAX_DISTANCE;
    }

    // Apply calibration offset
    distance += distance_offset;

    // Map distance to frequency linearly
    float frequency = MIN_FREQUENCY + (distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE);

    return frequency;
}

// Function to map LDR value to volume
float map_ldr_to_volume(int ldr_value) {
    if (ldr_value < 0) {
        ldr_value = 0;
    } else if (ldr_value > 1023) {
        ldr_value = 1023;
    }

    // Apply calibration offset
    ldr_value += (int)ldr_offset;

    // Map LDR value to volume logarithmically
    float volume = MIN_VOLUME + (log10((float)ldr_value + 1) - log10(1.0)) * (MAX_VOLUME - MIN_VOLUME) / (log10(1024.0) - log10(1.0));

    return volume;
}

// Function to set PWM frequency
void set_pwm_frequency(float frequency) {
    if (frequency < MIN_FREQUENCY) {
        frequency = MIN_FREQUENCY;
    } else if (frequency > MAX_FREQUENCY) {
        frequency = MAX_FREQUENCY;
    }

    // Calculate PWM period in microseconds
    int period = (int)(1000000.0 / frequency);

    // Set PWM period
    gpioSetPWMfrequency(PWM_PIN, frequency);
}

// Function to set PWM volume
void set_pwm_volume(float volume) {
    if (volume < MIN_VOLUME) {
        volume = MIN_VOLUME;
    } else if (volume > MAX_VOLUME) {
        volume = MAX_VOLUME;
    }

    // Calculate duty cycle (0-1000)
    int duty_cycle = (int)(volume * PWM_RANGE);

    // Set PWM duty cycle
    gpioPWM(PWM_PIN, duty_cycle);
}

// Function to clean up resources
void cleanup() {
    printf("Cleaning up resources...\n");
    gpioPWM(PWM_PIN, 0); // Stop PWM
    gpioTerminate();       // Terminate pigpio
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    printf("Cleanup complete.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    // Initialize PWM
    gpioSetPWMrange(PWM_PIN, PWM_RANGE);
    gpioSetPWMfrequency(PWM_PIN, MIN_FREQUENCY); // Set initial frequency
    gpioPWM(PWM_PIN, 0); // Initially off

    // Initialize SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        cleanup();
        return 1;
    }

    // Read configuration from file
    if (read_config() != 0) {
        fprintf(stderr, "Failed to read configuration, using default values.\n");
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float last_valid_distance = 0.0;
    float last_valid_volume = 0.0;

    // Main loop
    while (running) {
        // Read ultrasonic distance
        float distance = read_ultrasonic_distance();

        if (distance < 0) {
            fprintf(stderr, "Error reading ultrasonic distance, using last valid value.\n");
            distance = last_valid_distance;
        } else {
            last_valid_distance = distance;
        }

        // Read LDR value
        int ldr_value = read_ldr();

        if (ldr_value < 0) {
            fprintf(stderr, "Error reading LDR value, using last valid value.\n");
            ldr_value = (int)(last_valid_volume * 1023.0); // Revert to last valid volume
        } else {
            last_valid_volume = (float)ldr_value / 1023.0;
        }

        // Map distance to frequency and LDR value to volume
        float frequency = map_distance_to_frequency(distance);
        float volume = map_ldr_to_volume(ldr_value);

        // Set PWM frequency and volume
        set_pwm_frequency(frequency);
        set_pwm_volume(volume);

        // Print debug information
        printf("Distance: %.2f cm, LDR: %d, Frequency: %.2f Hz, Volume: %.2f\n", distance, ldr_value, frequency, volume);

        // Delay
        gpioDelay(50); // 50ms delay
    }

    // Clean up and exit
    cleanup();
    return 0;
}

