#include <pigpio.h>

// Define GPIO pins
#define MOTOR1_ENABLE 18
#define MOTOR1_DIRECTION 23
#define MOTOR2_ENABLE 24
#define MOTOR2_DIRECTION 25

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_FLAGS 0

// Define PWM parameters
#define PWM_FREQUENCY 1000 // 1 kHz
#define PWM_RANGE 1000

// Define speed mapping parameters
#define MIN_POT_VALUE 0
#define MAX_POT_VALUE 1023
#define MIN_SPEED 0
#define MAX_SPEED 1000

// Define acceleration and deceleration time
#define ACCELERATION_TIME 2.0 // seconds
#define DECELERATION_TIME 2.0 // seconds

// Define constant-speed phase duration
#define CONSTANT_SPEED_TIME 2.0 // seconds

// Define pause duration
#define PAUSE_DURATION 5.0 // seconds

// Define reverse direction delay
#define REVERSE_DIRECTION_DELAY 1.0 // seconds

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
int map_pot_to_speed(int pot_value);
void set_motor_speed(int motor_enable, int motor_direction, int speed);
void accelerate_motor(int motor_enable, int motor_direction, int target_speed);
void decelerate_motor(int motor_enable, int motor_direction, int target_speed);
void stop_motor(int motor_enable);
void reverse_motor_direction(int motor_enable, int motor_direction);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to map potentiometer value to speed
int map_pot_to_speed(int pot_value) {
    if (pot_value < MIN_POT_VALUE) {
        return MIN_SPEED;
    } else if (pot_value > MAX_POT_VALUE) {
        return MAX_SPEED;
    } else {
        return MIN_SPEED + (int)(((float)(pot_value - MIN_POT_VALUE) / (MAX_POT_VALUE - MIN_POT_VALUE)) * (MAX_SPEED - MIN_SPEED));
    }
}

// Function to set motor speed using PWM
void set_motor_speed(int motor_enable, int motor_direction, int speed) {
    if (speed < 0 || speed > PWM_RANGE) {
        fprintf(stderr, "Error: Invalid speed value: %d\n", speed);
        return;
    }

    gpioPWM(motor_enable, speed);
    gpioWrite(motor_direction, (speed > 0) ? 1 : 0); // Set direction based on speed
}

// Function to accelerate motor
void accelerate_motor(int motor_enable, int motor_direction, int target_speed) {
    int current_speed = 0;
    float increment = (float)target_speed / (ACCELERATION_TIME * PWM_FREQUENCY);

    while (current_speed < target_speed && !terminate) {
        current_speed += increment;
        if (current_speed > target_speed) {
            current_speed = target_speed;
        }
        set_motor_speed(motor_enable, motor_direction, (int)current_speed);
        gpioDelay(1000000 / PWM_FREQUENCY); // Delay for 1ms (adjust for PWM frequency)
    }
}

// Function to decelerate motor
void decelerate_motor(int motor_enable, int motor_direction, int target_speed) {
    int current_speed = (target_speed > 0) ? target_speed : 0; // Ensure target_speed is positive
    float decrement = (float)current_speed / (DECELERATION_TIME * PWM_FREQUENCY);

    while (current_speed > 0 && !terminate) {
        current_speed -= decrement;
        if (current_speed < 0) {
            current_speed = 0;
        }
        set_motor_speed(motor_enable, motor_direction, (int)current_speed);
        gpioDelay(1000000 / PWM_FREQUENCY); // Delay for 1ms (adjust for PWM frequency)
    }
}

// Function to stop motor
void stop_motor(int motor_enable) {
    set_motor_speed(motor_enable, 0, 0); // Set speed to 0
}

// Function to reverse motor direction
void reverse_motor_direction(int motor_enable, int motor_direction) {
    gpioWrite(motor_direction, !gpioRead(motor_direction)); // Toggle direction
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
