        accelerate_motor(MOTOR1_ENABLE, MOTOR1_DIRECTION, speed1);
        accelerate_motor(MOTOR2_ENABLE, MOTOR2_DIRECTION, speed2);

        // Hold at constant speed
        gpioDelay(CONSTANT_SPEED_TIME * 1000000); // Delay for constant speed time

        // Decelerate motors
        decelerate_motor(MOTOR1_ENABLE, MOTOR1_DIRECTION, 0);
        decelerate_motor(MOTOR2_ENABLE, MOTOR2_DIRECTION, 0);

        // Pause
        gpioDelay(PAUSE_DURATION * 1000000); // Delay for pause duration

        // Reverse motor directions
        reverse_motor_direction(MOTOR1_ENABLE, MOTOR1_DIRECTION);
        reverse_motor_direction(MOTOR2_ENABLE, MOTOR2_DIRECTION);
        gpioDelay(REVERSE_DIRECTION_DELAY * 1000000); // Delay for reverse direction delay
    }

