#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define LED_PIN 17
#define SPI_CE 0 // Chip Enable 0 (GPIO8)

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define sound threshold
#define SOUND_THRESHOLD 500

// Define debounce time (in milliseconds)
#define DEBOUNCE_TIME 10

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
int calibrate_noise_level(int num_samples);
void control_led(int state);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    // Construct SPI message (MCP3008 datasheet)
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to calibrate the noise level
int calibrate_noise_level(int num_samples) {
    int sum = 0;
    for (int i = 0; i < num_samples; i++) {
        int sample = read_mcp3008(0);
        if (sample == -1) {
            fprintf(stderr, "Error: Failed to read sample during calibration\n");
            return -1; // Indicate calibration failure
        }
        sum += sample;
        gpioDelay(1000); // Wait 1 ms
    }
    return sum / num_samples;
}

// Function to control the LED
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CE, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Calibrate noise level
    int noise_level = calibrate_noise_level(500);
    if (noise_level == -1) {
        fprintf(stderr, "Error: Noise calibration failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    printf("Noise level: %d\n", noise_level);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    int led_on = 0;
    unsigned long last_toggle_time = 0;
    while (!terminate) {
        // Read sound level from microphone
        int sound_level = read_mcp3008(0);
        if (sound_level == -1) {
            fprintf(stderr, "Error: Failed to read sound level\n");
            continue; // Skip to the next iteration
        }

        // Compare sound level to threshold
        if (sound_level > noise_level + SOUND_THRESHOLD) {
            // Debounce logic
            unsigned long current_time = gpioTick();
            if (!led_on || (current_time - last_toggle_time) > DEBOUNCE_TIME * 1000) { // Convert ms to us
                control_led(1); // Turn LED on
                led_on = 1;
                last_toggle_time = current_time;
            }
        } else {
            control_led(0); // Turn LED off
            led_on = 0;
        }

        gpioDelay(1000); // Delay 1 ms
    }

    // Cleanup
    control_led(0); // Turn LED off
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

