#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SPEED 1000000 // 1 MHz
#define GPIO_CE0 8
#define SAMPLE_RATE 1000 // 1 kHz
#define LOG_FILE "audio_log.txt"

// Global variables
int spi_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure for SPI configuration
typedef struct {
    int fd;
    uint8_t mode;
    uint8_t bits_per_word;
    uint32_t max_speed_hz;
} spi_config_t;

// Function prototypes
int spi_init(spi_config_t *config);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len);
int read_adc(int channel);
void log_data(long long timestamp_ns, int adc_value);
void signal_handler(int signal);
void cleanup();

// SPI initialization function
int spi_init(spi_config_t *config) {
    config->fd = open(SPI_DEVICE, O_RDWR);
    if (config->fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    config->mode = SPI_MODE;
    if (ioctl(config->fd, SPI_IOC_WR_MODE, &config->mode) == -1) {
        perror("Error setting SPI mode");
        close(config->fd);
        return -1;
    }

    config->bits_per_word = SPI_BITS_PER_WORD;
    if (ioctl(config->fd, SPI_IOC_WR_BITS_PER_WORD, &config->bits_per_word) == -1) {
        perror("Error setting bits per word");
        close(config->fd);
        return -1;
    }

    config->max_speed_hz = SPI_MAX_SPEED;
    if (ioctl(config->fd, SPI_IOC_WR_MAX_SPEED_HZ, &config->max_speed_hz) == -1) {
        perror("Error setting max speed");
        close(config->fd);
        return -1;
    }

    return 0;
}

// SPI transfer function
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_MAX_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// Function to read ADC value from MCP3008
int read_adc(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    gpioWrite(GPIO_CE0, 0); // Select the ADC
    if (spi_transfer(spi_fd, tx_buf, rx_buf, 3) < 0) {
        gpioWrite(GPIO_CE0, 1); // Deselect the ADC
        return -1;
    }
    gpioWrite(GPIO_CE0, 1); // Deselect the ADC

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to log data to file
void log_data(long long timestamp_ns, int adc_value) {
    fprintf(log_file, "%lld|%d\n", timestamp_ns, adc_value);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(GPIO_CE0, 1); // Deselect the ADC
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO_CE0 as output
    gpioSetMode(GPIO_CE0, PI_OUTPUT);
    gpioWrite(GPIO_CE0, 1); // Deselect the ADC initially

    // Initialize SPI
    spi_config_t spi_config;
    if (spi_init(&spi_config) < 0) {
        gpioTerminate();
        return 1;
    }
    spi_fd = spi_config.fd;

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    struct timespec req, rem;
    req.tv_sec = 0;
    req.tv_nsec = 1000000; // 1 ms

    while (!terminate) {
        // Read ADC value
        int adc_value = read_adc(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            break;
        }

        // Get timestamp
        struct timespec ts;
        if (clock_gettime(CLOCK_MONOTONIC_RAW, &ts) == -1) {
            perror("Error getting timestamp");
            break;
        }
        long long timestamp_ns = (long long)ts.tv_sec * 1000000000LL + ts.tv_nsec;

        // Log data
        log_data(timestamp_ns, adc_value);

        // Sleep until next sample
        if (nanosleep(&req, &rem) == -1) {
            if (errno == EINTR) {
                // Interrupted by signal, exit loop
                break;
            } else {
                perror("nanosleep");
                break;
            }
        }
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

