#include <wiringPi.h>
#include <wiringPiSPI.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>

// Define SPI channel and speed
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define MCP3008 channel assignments
#define X_CHANNEL 0
#define Y_CHANNEL 1
#define Z_CHANNEL 2

// Define ADXL335 sensitivity (300mV/g)
#define ADXL335_SENSITIVITY 0.3

// Define 3.3V reference voltage
#define VREF 3.3

// Define Kalman filter parameters
#define Q 0.01
#define R 0.1

// Global variables for Kalman filter states
float x_est = 0.0;
float y_est = 0.0;
float z_est = 0.0;
float P_est = 1.0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_acceleration(float voltage);
float kalman_filter(float measurement, float *state, float *P);
void print_acceleration(float x, float y, float z);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    wiringPiSPIDataRW(SPI_CHANNEL, NULL, 0); // Deselect the MCP3008
    exit(0);
}

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char buffer[3];
    int adc_value = 0;

    // Construct SPI message
    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3);

    // Extract ADC value from response
    adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];

    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return ((float)adc_value / 1023.0) * VREF;
}

// Function to convert voltage to acceleration
float voltage_to_acceleration(float voltage) {
    return (voltage - (VREF / 2.0)) / ADXL335_SENSITIVITY;
}

// Function to implement Kalman filter
float kalman_filter(float measurement, float *state, float *P) {
    // Prediction step
    float x_pred = *state;
    float P_pred = *P + Q;

    // Update step
    float K = P_pred / (P_pred + R);
    float x_est_new = x_pred + K * (measurement - x_pred);
    float P_est_new = (1 - K) * P_pred;

    // Update state and P
    *state = x_est_new;
    *P = P_est_new;

    return x_est_new;
}

// Function to print acceleration values
void print_acceleration(float x, float y, float z) {
    printf("X: %.2f g, Y: %.2f g, Z: %.2f g\n", x, y, z);
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "wiringPiSetup failed, exiting...\n");
        return 1;
    }

    // Initialize SPI
    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) == -1) {
        fprintf(stderr, "wiringPiSPISetup failed, exiting...\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("ADXL335 Kalman Filter Program\n");

    // Main loop
    while (1) {
        // Read ADC values from each channel
        int x_adc = read_mcp3008(X_CHANNEL);
        int y_adc = read_mcp3008(Y_CHANNEL);
        int z_adc = read_mcp3008(Z_CHANNEL);

        // Convert ADC values to voltage
        float x_voltage = adc_to_voltage(x_adc);
        float y_voltage = adc_to_voltage(y_adc);
        float z_voltage = adc_to_voltage(z_adc);

        // Convert voltage to acceleration
        float x_acceleration = voltage_to_acceleration(x_voltage);
        float y_acceleration = voltage_to_acceleration(y_voltage);
        float z_acceleration = voltage_to_acceleration(z_voltage);

        // Apply Kalman filter
        float x_filtered = kalman_filter(x_acceleration, &x_est, &P_est);
        float y_filtered = kalman_filter(y_acceleration, &y_est, &P_est);
        float z_filtered = kalman_filter(z_acceleration, &z_est, &P_est);

        // Print filtered acceleration values
        print_acceleration(x_filtered, y_filtered, z_filtered);

        // Delay for 100ms (10Hz sampling rate)
        delay(100);
    }

    return 0;
}

