#include <string.h>

// Define GPIO pins for the Hall-Effect sensors
#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define SENSOR3_GPIO 27

// Define the magnetic field range in milliTeslas
#define MIN_MAGNETIC_FIELD -100.0
#define MAX_MAGNETIC_FIELD 100.0

// Define the ADC resolution (assuming 10-bit ADC)
#define ADC_RESOLUTION 1024.0

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the digital state of a Hall-Effect sensor
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to convert the digital state to a magnetic field strength in milliTeslas
float convert_to_mT(int digital_state) {
    if (digital_state == 1) {
        return MAX_MAGNETIC_FIELD;
    } else {
        return MIN_MAGNETIC_FIELD;
    }
}

// Function to log the magnetic field strength values to a file
void log_data(float sensor1_mT, float sensor2_mT, float sensor3_mT) {
    FILE *fp = fopen("magnetic_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening magnetic_log.txt for writing!\n");
        return;
    }

    fprintf(fp, "%.2f,%.2f,%.2f\n", sensor1_mT, sensor2_mT, sensor3_mT);
    fflush(fp); // Ensure data is written to the file immediately
    fclose(fp);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);
    gpioSetMode(SENSOR3_GPIO, PI_INPUT);

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor1_digital = read_sensor(SENSOR1_GPIO);
        int sensor2_digital = read_sensor(SENSOR2_GPIO);
        int sensor3_digital = read_sensor(SENSOR3_GPIO);

        // Check for errors during sensor reading
        if (sensor1_digital == -1 || sensor2_digital == -1 || sensor3_digital == -1) {
            fprintf(stderr, "Error reading sensor data, skipping logging.\n");
            gpioDelay(100); // Wait 100ms before the next iteration
            continue;
        }

        // Convert sensor values to magnetic field strengths
        float sensor1_mT = convert_to_mT(sensor1_digital);
        float sensor2_mT = convert_to_mT(sensor2_digital);
        float sensor3_mT = convert_to_mT(sensor3_digital);

        // Check if magnetic field strengths are within the valid range
        if (sensor1_mT < MIN_MAGNETIC_FIELD || sensor1_mT > MAX_MAGNETIC_FIELD ||
            sensor2_mT < MIN_MAGNETIC_FIELD || sensor2_mT > MAX_MAGNETIC_FIELD ||
            sensor3_mT < MIN_MAGNETIC_FIELD || sensor3_mT > MAX_MAGNETIC_FIELD) {
            fprintf(stderr, "Warning: Magnetic field strength out of range!\n");
        }

        // Log the data
        log_data(sensor1_mT, sensor2_mT, sensor3_mT);

        // Wait for 100 milliseconds
        gpioDelay(100);
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();

    return 0;
}

