#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <mosquitto.h>
#include <jansson.h>
#include <pigpio.h>

// Configuration
#define MQTT_BROKER "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "rpi_led_control"
#define MQTT_TOPIC "home/led_control"
#define GPIO_PIN 17
#define MAX_RECONNECT_DELAY 60 // seconds

// Global variables
static struct mosquitto *mosq = NULL;
static volatile int running = 1;
static int reconnect_delay = 1;

// Function prototypes
void log_message(const char *message);
void signal_handler(int signum);
int mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int result);
int mqtt_disconnect_callback(struct mosquitto *mosq, void *userdata, int rc);
int mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
int parse_json_payload(const char *payload, int *led_state);
int set_led_state(int led_state);

// Logging function
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] %s\n", timestamp, message);
}

// Signal handler
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        log_message("Received signal, shutting down...");
        running = 0;
    }
}

// MQTT connect callback
int mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        log_message("Connected to MQTT broker");
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    } else {
        char error_message[100];
        snprintf(error_message, sizeof(error_message), "Connection error: %s", mosquitto_connack_string(result));
        log_message(error_message);
    }
    return result;
}

// MQTT disconnect callback
int mqtt_disconnect_callback(struct mosquitto *mosq, void *userdata, int rc) {
    if (rc != 0) {
        log_message("Disconnected from MQTT broker");
    }
    return rc;
}

// MQTT message callback
int mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        char *payload = (char *)message->payload;
        int led_state;

        if (parse_json_payload(payload, &led_state) == 0) {
            if (set_led_state(led_state) != 0) {
                log_message("Failed to set LED state");
            }
        } else {
            log_message("Failed to parse JSON payload");
        }
    } else {
        log_message("Empty message received");
    }
    return 0;
}

// JSON parsing function
int parse_json_payload(const char *payload, int *led_state) {
    json_error_t error;
    json_t *root = json_loads(payload, 0, &error);

    if (!root) {
        char error_message[200];
        snprintf(error_message, sizeof(error_message), "JSON parse error: %s", error.text);
        log_message(error_message);
        return -1;
    }

    json_t *led_state_json = json_object_get(root, "led_state");
    if (!led_state_json) {
        log_message("Missing 'led_state' key in JSON");
        json_decref(root);
        return -1;
