#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 18

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SOUND_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(ALARM_LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", ALARM_LED_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read the sound sensor
int read_sound_sensor() {
    int sound_level = gpioRead(SOUND_SENSOR_PIN);
    if (sound_level < 0) {
        fprintf(stderr, "Failed to read GPIO%d\n", SOUND_SENSOR_PIN);
        return -1; // Indicate error
    }
    return sound_level;
}

// Function to trigger the alarm
void trigger_alarm() {
    if (gpioWrite(ALARM_LED_PIN, 1) != 0) {
        fprintf(stderr, "Failed to write to GPIO%d\n", ALARM_LED_PIN);
        return;
    }
    gpioDelay(1000); // 1 second
    if (gpioWrite(ALARM_LED_PIN, 0) != 0) {
        fprintf(stderr, "Failed to write to GPIO%d\n", ALARM_LED_PIN);
        return;
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int sound_level = read_sound_sensor();
        if (sound_level == 0) {
            printf("Sound detected!\n");
            trigger_alarm();
        } else if (sound_level == 1) {
            //printf("No sound detected\n"); //Commented out to reduce console output
        } else {
            fprintf(stderr, "Error reading sound sensor, exiting.\n");
            break;
        }

        gpioDelay(100); // 100 milliseconds
    }

    // Clean up GPIO
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

