#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define LOG_FILE "/var/log/vibration_shutdown.log"

static volatile sig_atomic_t terminate = 0;
static int gpio_fd = -1;
static int log_fd = -1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nSignal received, exiting gracefully...\n");
}

// Function to open the GPIO chip
int open_gpio_chip(const char *chip) {
    int fd = open(chip, O_RDWR);
    if (fd < 0) {
        perror("Error opening GPIO chip");
        return -1;
    }
    return fd;
}

// Function to get the GPIO line number
int get_gpio_line(int fd, int line) {
    struct gpiochip_info info;
    if (ioctl(fd, GPIO_GET_CHIPINFO, &info) < 0) {
        perror("Error getting GPIO chip info");
        return -1;
    }

    if (line < 0 || line >= info.lines) {
        fprintf(stderr, "Error: Invalid GPIO line number %d\n", line);
        return -1;
    }

    return line;
}

// Function to request the GPIO line
int request_gpio_line(int fd, int line) {
    struct gpio_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "vibration-monitor";
    config.request_type = GPIO_REQUEST_DIRECTION_INPUT;
    config.flags = 0;

    if (ioctl(fd, GPIO_REQUEST, &config) < 0) {
        perror("Error requesting GPIO line");
        return -1;
    }
    return 0;
}

// Function to configure the GPIO line for falling edge detection
int configure_gpio_line(int fd, int line) {
    struct gpio_event_request_config config;
    memset(&config, 0, sizeof(config));
    config.event_type = GPIO_EVENT_FALLING_EDGE;
    config.consumer = "vibration-monitor";
    config.line = line;

    if (ioctl(fd, GPIO_EVENT_REQUEST, &config) < 0) {
        perror("Error configuring GPIO line for falling edge detection");
        return -1;
    }
    return 0;
}

// Function to read the GPIO line value
int read_gpio_line(int fd, int line) {
    int value;
    if (ioctl(fd, GPIO_GET_VALUE, &value) < 0) {
        perror("Error reading GPIO line value");
        return -1;
    }
    return value;
}

// Function to open the log file
int open_log_file(const char *filename) {
    int fd = open(filename, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd < 0) {
        perror("Error opening log file");
        return -1;
    }
    return fd;
}

// Function to write a message to the log file
int write_to_log(int fd, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    char log_entry[256];
    snprintf(log_entry, sizeof(log_entry), "%s: %s\n", timestamp, message);

    if (write(fd, log_entry, strlen(log_entry)) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    return 0;
}

// Function to close the log file
int close_log_file(int fd) {
    if (close(fd) < 0) {
        perror("Error closing log file");
        return -1;
    }
    return 0;
}

// Function to release the GPIO line
int release_gpio_line(int fd, int line) {
    struct gpio_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "vibration-monitor";
    config.line = line;

    if (ioctl(fd, GPIO_RELEASE, &config) < 0) {
        perror("Error releasing GPIO line");
        return -1;
    }
    return 0;
}

// Function to close the GPIO chip
int close_gpio_chip(int fd) {
    if (close(fd) < 0) {
        perror("Error closing GPIO chip");
        return -1;
    }
    return 0;
}

int main() {
    // Install signal handlers
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("Error installing signal handler");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    gpio_fd = open_gpio_chip(GPIO_CHIP);
    if (gpio_fd < 0) {
        return EXIT_FAILURE;
    }

    // Get GPIO line number
    int line = get_gpio_line(gpio_fd, GPIO_LINE);
    if (line < 0) {
        close_gpio_chip(gpio_fd);
        return EXIT_FAILURE;
    }

    // Request GPIO line
    if (request_gpio_line(gpio_fd, line) < 0) {
        close_gpio_chip(gpio_fd);
        return EXIT_FAILURE;
    }

    // Configure GPIO line for falling edge detection
    if (configure_gpio_line(gpio_fd, line) < 0) {
        release_gpio_line(gpio_fd, line);
        close_gpio_chip(gpio_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_fd = open_log_file(LOG_FILE);
    if (log_fd < 0) {
        release_gpio_line(gpio_fd, line);
        close_gpio_chip(gpio_fd);
        return EXIT_FAILURE;
    }

    printf("Vibration monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read GPIO line value
        int value = read_gpio_line(gpio_fd, line);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO line, exiting...\n");
            break;
        }

        // Check for falling edge (value == 0)
        if (value == 0) {
            // Log the event
            if (write_to_log(log_fd, "Vibration detected!") < 0) {
                fprintf(stderr, "Error writing to log, exiting...\n");
                break;
            }

            // Print the event to stdout
            printf("Vibration detected!\n");

            // Shutdown the system
            if (system("sudo shutdown -h now") != 0) {
                perror("Error executing shutdown command");
            }

            // Exit the loop after shutdown is initiated
            break;
        }

        // Small delay to avoid busy-waiting
        usleep(100000); // 100ms
    }

    // Cleanup
    printf("Cleaning up resources...\n");
    if (log_fd != -1) {
        close_log_file(log_fd);
    }
    if (gpio_fd != -1) {
        release_gpio_line(gpio_fd, line);
        close_gpio_chip(gpio_fd);
    }

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

