        }

        // Check for falling edge (value == 0)
        if (value == 0) {
            // Log the event
            if (write_to_log(log_fd, "Vibration detected!") < 0) {
                fprintf(stderr, "Error writing to log, exiting...\n");
                break;
            }

            // Print the event to stdout
            printf("Vibration detected!\n");

            // Shutdown the system
            if (system("sudo shutdown -h now") != 0) {
                perror("Error executing shutdown command");
            }

            // Exit the loop after shutdown is initiated
            break;
        }

        // Small delay to avoid busy-waiting
        usleep(100000); // 100ms
    }

    // Cleanup
    printf("Cleaning up resources...\n");
    if (log_fd != -1) {
        close_log_file(log_fd);
    }
    if (gpio_fd != -1) {
        release_gpio_line(gpio_fd, line);
        close_gpio_chip(gpio_fd);
    }

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

