// Constants
#define BH1750_ADDR 0x23
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define LOG_FILE "environmental_log.txt"

// Global variables
int i2c_handle;
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_bh1750(int i2c_handle);
int read_mcp3008(int spi_handle, int channel);
void log_data(FILE *fp, int lux, int adc_value);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read light level from BH1750 sensor
int read_bh1750(int i2c_handle) {
    char config[1] = {0x10}; // Continuous high-resolution mode
    char buffer[2];
    int lux;

    if (i2cWriteDevice(i2c_handle, config, 1) != 0) {
        fprintf(stderr, "Error writing to BH1750\n");
        return -1;
    }

    gpioDelay(200); // Wait for measurement (at least 180ms)

    if (i2cReadDevice(i2c_handle, buffer, 2) != 2) {
        fprintf(stderr, "Error reading from BH1750\n");
        return -1;
    }

    lux = (buffer[0] << 8) | buffer[1];
    return lux;
}

// Function to read analog value from MCP3008 ADC
int read_mcp3008(int spi_handle, int channel) {
    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error reading from MCP3008\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to log data to file
void log_data(FILE *fp, int lux, int adc_value) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, Light: %d lux, Sound: %d\n", timestamp, lux, adc_value);
    fflush(fp); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open SPI connection
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI device: %d\n", spi_handle);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        spiClose(spi_handle);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Environmental monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int lux = read_bh1750(i2c_handle);
        int adc_value = read_mcp3008(spi_handle, 0);

        if (lux != -1 && adc_value != -1) {
            log_data(log_file, lux, adc_value);
        } else {
            fprintf(stderr, "Error reading sensor data. Skipping logging.\n");
        }

        sleep(1);
    }

    // Clean up
    printf("Cleaning up...\n");
    fclose(log_file);
    spiClose(spi_handle);
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Environmental monitoring stopped.\n");
    return 0;
}

