#include <time.h>
#include <signal.h>
#include <string.h>

#define FLAME_SENSOR_PIN 17
#define LOG_FILE "flame_events.log"

static volatile int running = 1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library and GPIO pin
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(FLAME_SENSOR_PIN, PI_PUD_DOWN); // Use pull-down resistor

    return 0;
}

// Function to read the flame sensor value
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_PIN);
}

// Function to log the flame event to a CSV file
int log_flame_event(int pin, int state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%d,%d\n", timestamp, pin, state);
    fclose(fp);
    return 0;
}

// Function to print an alarm message to stdout
void print_alarm_message() {
    printf("ALARM: Flame detected!\n");
}

// Function to clean up GPIO resources
void cleanup_gpio() {
    gpioTerminate();
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int sensor_value = read_flame_sensor();

        if (sensor_value == 1) {
            print_alarm_message();
        }

        if (log_flame_event(FLAME_SENSOR_PIN, sensor_value) != 0) {
            fprintf(stderr, "Error logging flame event.\n");
        }

        gpioDelay(1000); // Wait for 1 second
    }

    // Clean up GPIO resources before exiting
    cleanup_gpio();

    printf("Flame sensor monitoring stopped.\n");

    return 0;
}

