// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Reads the ADC value from the specified MCP3008 channel
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Validates the ADC value to ensure it's within the expected range
int validate_adc_value(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: Invalid ADC value: %d\n", adc_value);
        return -1;
    }
    return 0;
}

// Gets the current timestamp in the format YYYY-MM-DD HH:MM:SS
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(20 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for timestamp\n");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Logs the sensor data to the file
int log_data(char *timestamp, int sensor_id, int adc_value) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s, Sensor %d, ADC Value: %d\n", timestamp, sensor_id, adc_value);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Initializes the pigpio library and SPI interface
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return -1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Cleans up resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        for (int i = 0; i < MCP3008_CHANNELS; i++) {
            int adc_value = read_mcp3008(i);
            if (adc_value >= 0) {
                if (validate_adc_value(adc_value) == 0) {
                    char *timestamp = get_timestamp();
                    if (timestamp != NULL) {
                        if (log_data(timestamp, i, adc_value) != 0) {
                            fprintf(stderr, "Error: Failed to log data for sensor %d\n", i);
                        }
                        free(timestamp);
                    } else {
                        fprintf(stderr, "Error: Failed to get timestamp for sensor %d\n", i);
                    }
                }
            } else {
                fprintf(stderr, "Error: Failed to read ADC value from sensor %d\n", i);
            }
        }
        gpioSleep(PI_TIME_RELATIVE, SLEEP_DURATION, 0); // Sleep for 60 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

