#define MOTOR_IN2 18
#define MOTOR_ENA 27
#define SPI_CE 0

// Define SPI channel
#define SPI_CHANNEL 0

// Define SPI baud rate
#define SPI_BAUD 1000000

// Define rain threshold
#define RAIN_THRESHOLD 5

// Define motor run time (seconds)
#define MOTOR_RUN_TIME 3

// Define PWM duty cycle
#define PWM_DUTY_CYCLE 150

// Define PWM range
#define PWM_RANGE 255

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_rain_sensor(int spi_handle);
void control_motor(int in1, int in2, int ena, int duty_cycle, int direction);
void log_data(FILE *log_file, int rain_level, int motor_direction);
void signal_handler(int signal);

// Function to read rain sensor value from MCP3008
int read_rain_sensor(int spi_handle) {
    char tx_buffer[3];
    char rx_buffer[3];

    // MCP3008 configuration: single-ended channel 0
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = 0x80; // Single-ended, channel 0
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1; // Indicate error
    }

    // Extract the 10-bit ADC value from the response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to control the DC motor
void control_motor(int in1, int in2, int ena, int duty_cycle, int direction) {
    gpioWrite(in1, direction);
    gpioWrite(in2, !direction);
    gpioPWM(ena, duty_cycle);
}

// Function to log data to file
void log_data(FILE *log_file, int rain_level, int motor_direction) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Rain Level: %d, Motor Direction: %s\n", timestamp, rain_level, motor_direction == 1 ? "Forward" : "Reverse");
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR_ENA, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CE, SPI_BAUD, 0); // SPI channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("rain_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read rain sensor value
        int rain_level = read_rain_sensor(spi_handle);
        if (rain_level < 0) {
            fprintf(stderr, "Error: Failed to read rain sensor value\n");
            continue; // Skip to the next iteration
        }

        // Control motor based on rain level
        if (rain_level > RAIN_THRESHOLD) {
            printf("Rain level exceeds threshold. Closing window.\n");
            control_motor(MOTOR_IN1, MOTOR_IN2, MOTOR_ENA, PWM_DUTY_CYCLE, 1); // Forward
            log_data(log_file, rain_level, 1);
            gpioDelay(MOTOR_RUN_TIME * 1000000); // Run for 3 seconds
            control_motor(MOTOR_IN1, MOTOR_IN2, MOTOR_ENA, 0, 0); // Stop motor
        } else {
            printf("Rain level below threshold. Opening window.\n");
            control_motor(MOTOR_IN1, MOTOR_IN2, MOTOR_ENA, PWM_DUTY_CYCLE, 0); // Reverse
            log_data(log_file, rain_level, 0);
            gpioDelay(MOTOR_RUN_TIME * 1000000); // Run for 3 seconds
            control_motor(MOTOR_IN1, MOTOR_IN2, MOTOR_ENA, 0, 0); // Stop motor
        }

        gpioDelay(1000000); // Wait for 1 second
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_motor(MOTOR_IN1, MOTOR_IN2, MOTOR_ENA, 0, 0); // Stop motor
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Rain sensor monitoring stopped.\n");

    return 0;
}

