#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define LOG_FILE "distance_log.txt"
#define DISTANCE_THRESHOLD 200 // mm

static volatile int running = 1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the distance sensor
int read_distance_sensor() {
    int distance = gpioRead(GPIO_PIN);
    if (distance < 0) {
        fprintf(stderr, "Error reading GPIO pin: %d\n", distance);
        return -1; // Indicate an error
    }
    return distance;
}

// Function to log the distance to a file
void log_distance(int distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, Distance: %d\n", timestamp, distance);
    fclose(fp);
}

// Function to control the feeder based on distance
void control_feeder(int distance) {
    if (distance < DISTANCE_THRESHOLD) {
        printf("Feeder Activated\n");
    } else {
        printf("Feeder Idle\n");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Distance monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int distance = read_distance_sensor();
        if (distance >= 0) {
            log_distance(distance);
            control_feeder(distance);
        } else {
            fprintf(stderr, "Error reading distance, retrying in 1 second...\n");
            sleep(1);
            continue; // Retry reading
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Clean up and exit
    gpioTerminate();
    printf("Distance monitoring stopped.\n");
    return 0;
}

