#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define DRV5055_SENSITIVITY 0.0001 // 10 mV/Gauss
#define DRV5055_ZERO_FIELD_OUTPUT 2.5 // V
#define VREF 3.3 // Reference voltage
#define LOG_FILE "magnetic_log.txt"

// Global variables
int spi_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int read_mcp3008(int channel);
float convert_to_gauss(int adc_value);
int log_data(float gauss);
void signal_handler(int signal);
void cleanup(void);

// Structure for SPI configuration
struct spi_config {
    int fd;
    uint8_t mode;
    uint8_t bits_per_word;
    uint32_t speed;
};

// SPI initialization function
int spi_init(void) {
    struct spi_config config;
    config.fd = -1;
    config.mode = SPI_MODE;
    config.bits_per_word = SPI_BITS_PER_WORD;
    config.speed = SPI_SPEED;

    config.fd = open(SPI_DEVICE, O_RDWR);
    if (config.fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    if (ioctl(config.fd, SPI_IOC_WR_MODE, &config.mode) == -1) {
        perror("Error setting SPI mode");
        close(config.fd);
        return -1;
    }

    if (ioctl(config.fd, SPI_IOC_WR_BITS_PER_WORD, &config.bits_per_word) == -1) {
        perror("Error setting SPI bits per word");
        close(config.fd);
        return -1;
    }

    if (ioctl(config.fd, SPI_IOC_WR_MAX_SPEED_HZ, &config.speed) == -1) {
        perror("Error setting SPI speed");
        close(config.fd);
        return -1;
    }

    spi_fd = config.fd; // Update global variable
    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to Gauss
float convert_to_gauss(int adc_value) {
    float voltage = (float)adc_value * VREF / 1024.0;
    float gauss = (voltage - DRV5055_ZERO_FIELD_OUTPUT) / DRV5055_SENSITIVITY;
    return gauss;
}

// Function to log data to file
int log_data(float gauss) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, gauss);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup(void) {
    printf("Cleaning up...\n");
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (spi_init() != 0) {
        cleanup();
        return 1;
    }

    printf("Magnetic field sensor data logging started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value == -1) {
            fprintf(stderr, "Error reading ADC value, skipping sample.\n");
            sleep(1); // Wait before retrying
            continue;
        }

        float gauss = convert_to_gauss(adc_value);

        if (log_data(gauss) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        printf("Magnetic field: %.2f Gauss\n", gauss);
        sleep(0.5); // Sample every 500ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

