#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define GPIO_PIN 17
#define VREF 3.3
#define SENSITIVITY 0.1 // 100 mV/A
#define LOG_FILE "current_log.txt"
#define SAMPLE_INTERVAL 1 // seconds

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for configuration
typedef struct {
    int spi_channel;
    int spi_speed;
    int gpio_pin;
    float vref;
    float sensitivity;
    char *log_file;
    int sample_interval;
} Config;

// Function prototypes
int initialize_gpio(int pin);
int initialize_spi(int channel, int speed);
int read_adc(int channel);
float convert_to_current(int adc_value, float vref, float sensitivity);
int log_current(float current);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize GPIO pin
int initialize_gpio(int pin) {
    if (gpioSetMode(pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", pin);
        return -1;
    }
    gpioWrite(pin, 1); // Enable sensor
    return 0;
}

// Initialize SPI interface
int initialize_spi(int channel, int speed) {
    spi_handle = spiOpen(channel, speed, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %d\n", channel, spi_handle);
        return -1;
    }
    return 0;
}

// Read ADC value from MCP3008
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "Error during SPI transfer\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Convert ADC value to current (Amperes)
float convert_to_current(int adc_value, float vref, float sensitivity) {
    float voltage = (adc_value / 1023.0) * vref;
    float current = voltage / sensitivity;
    return current;
}

// Log current to CSV file
int log_current(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.4f\n", timestamp, current);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(GPIO_PIN, 0); // Disable sensor
    spiClose(spi_handle);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configuration
    Config config = {
        .spi_channel = SPI_CHANNEL,
        .spi_speed = SPI_SPEED,
        .gpio_pin = GPIO_PIN,
        .vref = VREF,
        .sensitivity = SENSITIVITY,
        .log_file = LOG_FILE,
        .sample_interval = SAMPLE_INTERVAL
    };

    // Initialize GPIO
    if (initialize_gpio(config.gpio_pin) != 0) {
        cleanup();
        return 1;
    }

    // Initialize SPI
    if (initialize_spi(config.spi_channel, config.spi_speed) != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s\n", config.log_file);
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,current_A\n");
    }
    rewind(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int adc_value = read_adc(0);
        if (adc_value >= 0) {
            float current = convert_to_current(adc_value, config.vref, config.sensitivity);
            log_current(current);
            printf("Current: %.4f A\n", current);
        } else {
            fprintf(stderr, "Error reading ADC value\n");
        }

        gpioDelay(config.sample_interval * 1000000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

