    int spi_channel;
    int spi_speed;
    int spi_mode;
    int mcp3008_channel;
    float vref;
    float sensor_sensitivity;
    float sensor_offset;
    char *log_file;
    int sample_interval_ms;
} Config;

// Function prototypes
int initialize_spi();
int read_mcp3008(int channel);
float convert_to_current(int adc_value);
int log_current(float current);
void signal_handler(int signal);
void cleanup();

