        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, skipping sample.\n");
            gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
            continue;
        }

        float current = convert_to_current(adc_value);

        // Data validation
        if (current < 0.0 || current > 10.0) {
            fprintf(stderr, "Warning: Current value out of range: %.2f A\n", current);
        }

        if (log_current(current) != 0) {
            fprintf(stderr, "Error logging current, skipping sample.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
