// Define GPIO pins for the sensors
#define SENSOR_1_GPIO 4
#define SENSOR_2_GPIO 17

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 2

// Number of readings for debouncing
#define NUM_READINGS 5

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the sensor value with debouncing
int read_sensor(int gpio_pin) {
    int readings[NUM_READINGS];
    int i;

    // Read the sensor multiple times with a delay
    for (i = 0; i < NUM_READINGS; i++) {
        readings[i] = gpioRead(gpio_pin);
        gpioDelay(DEBOUNCE_DELAY * 1000); // Convert ms to microseconds
    }

    // Calculate the majority value
    int majority_value = 0;
    for (i = 0; i < NUM_READINGS; i++) {
        majority_value += readings[i];
    }

    // Return the majority value (0 or 1)
    return (majority_value >= (NUM_READINGS / 2)) ? 0 : 1;
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_UP);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_UP);

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR_1_GPIO);
        int sensor2_value = read_sensor(SENSOR_2_GPIO);

        // Log the sensor states
        printf("Sensor 1: %d, Sensor 2: %d\n", sensor1_value, sensor2_value);

        // Check for simultaneous object detection
        if (sensor1_value == 0 && sensor2_value == 0) {
            printf("ALERT: Both sensors detect object\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Release GPIO resources before exiting
    gpioTerminate();

    return 0;
}

