#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <sys/stat.h>
#include <pigpio.h>

// Configuration
#define PIR_GPIO 17
#define DEBOUNCE_DELAY_MS 200
#define CAPTURE_DIR "/home/pi/security_cam/"
#define LOG_FILE "/var/log/security_cam.log"

// Global variables
volatile sig_atomic_t program_running = 1;
int pigpio_initialized = 0;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
int debounce_motion();
int capture_image(const char *filename);
int log_event(int priority, const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        program_running = 0;
        log_event(LOG_INFO, "Received signal, shutting down...");
    }
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_event(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    pigpio_initialized = 1;

    gpioSetMode(PIR_GPIO, PI_INPUT);
    gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN); // Use pull-down resistor

    log_event(LOG_INFO, "GPIO initialized successfully");
    return 0;
}

// Read PIR sensor
int read_pir_sensor() {
    return gpioRead(PIR_GPIO);
}

// Debounce motion
int debounce_motion() {
    gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Convert ms to microseconds
    return 0;
}

// Capture image using libcamera-still
int capture_image(const char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "libcamera-still -o %s --width 640 --height 480 --encoding jpeg --timeout 1000", filename);

    pid_t pid = fork();
    if (pid == 0) {
        // Child process
        execlp("libcamera-still", "libcamera-still", "-o", filename, "--width", "640", "--height", "480", "--encoding", "jpeg", "--timeout", "1000", NULL);
        perror("execlp failed");
        exit(EXIT_FAILURE);
    } else if (pid < 0) {
        // Fork failed
        log_event(LOG_ERR, "Failed to fork libcamera-still");
        return -1;
    } else {
        // Parent process
        int status;
        waitpid(pid, &status, 0);

        if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
            log_event(LOG_INFO, "Image captured successfully");
            return 0;
        } else {
            log_event(LOG_ERR, "Image capture failed");
            return -1;
        }
    }
}

// Log event to syslog
int log_event(int priority, const char *message) {
    openlog("security_cam", LOG_PID | LOG_CONS, LOG_USER);
    syslog(priority, "%s", message);
    closelog();
    return 0;
}

// Cleanup resources
void cleanup() {
    log_event(LOG_INFO, "Cleaning up resources...");
    if (pigpio_initialized) {
        gpioTerminate();
        log_event(LOG_INFO, "pigpio terminated");
    }
    log_event(LOG_INFO, "Exiting program");
    closelog();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize syslog
    openlog("security_cam", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_event(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    // Create capture directory if it doesn't exist
    struct stat st = {0};
    if (stat(CAPTURE_DIR, &st) == -1) {
        if (mkdir(CAPTURE_DIR, 0777) == -1) {
            log_event(LOG_ERR, "Failed to create capture directory");
            cleanup();
            return 1;
        }
        log_event(LOG_INFO, "Capture directory created");
    }

    log_event(LOG_INFO, "Security camera started");

    // Main loop
    while (program_running) {
        int motion_detected = read_pir_sensor();

        if (motion_detected) {
            log_event(LOG_INFO, "Motion detected!");

            // Debounce
            debounce_motion();

            // Re-read sensor to confirm motion
            if (read_pir_sensor()) {
                // Generate filename
                time_t rawtime;
                struct tm *timeinfo;
                char filename[256];
                time(&rawtime);
                timeinfo = localtime(&rawtime);
                strftime(filename, sizeof(filename), "%Y%m%d_%H%M%S.jpg", timeinfo);
                char full_path[512];
                snprintf(full_path, sizeof(full_path), "%s%s", CAPTURE_DIR, filename);

                // Capture image
                if (capture_image(full_path) == 0) {
                    log_event(LOG_INFO, "Image saved to %s", full_path);
                } else {
                    log_event(LOG_ERR, "Failed to capture image");
                }
            }
        }

        gpioDelay(50 * 1000); // Check every 50ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

