                snprintf(full_path, sizeof(full_path), "%s%s", CAPTURE_DIR, filename);

                // Capture image
                if (capture_image(full_path) == 0) {
                    log_event(LOG_INFO, "Image saved to %s", full_path);
                } else {
                    log_event(LOG_ERR, "Failed to capture image");
                }
            }
        }

        gpioDelay(50 * 1000); // Check every 50ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

