#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/select.h>

#define CLEAR(x) memset(&(x), 0, sizeof(x))

struct buffer {
    void   *start;
    size_t  length;
};

static int              fd                 = -1;
static struct buffer    *buffers           = NULL;
static unsigned int     n_buffers          = 0;
static int              image_width        = 640;
static int              image_height       = 480;
static char             *device_name        = "/dev/video0";
static int              frame_count        = 0;
static int              running            = 1;

static void errno_exit(const char *s)
{
    fprintf(stderr, "%s error %d, %s\n", s, errno, strerror(errno));
    exit(EXIT_FAILURE);
}

static int xioctl(int fh, int request, void *arg)
{
    int r;

    do {
        r = ioctl(fh, request, arg);
    } while (-1 == r && EINTR == errno);

    return r;
}

static int read_device_info(int fd)
{
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_streamparm streamparm;

    if (-1 == xioctl(fd, VIDIOC_QUERYCAP, &cap)) {
        if (EINVAL == errno) {
            fprintf(stderr, "%s is no V4L2 device\n", device_name);
            return -1;
        } else {
            errno_exit("VIDIOC_QUERYCAP");
        }
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is no video capture device\n", device_name);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", device_name);
        return -1;
    }

    CLEAR(fmt);
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = image_width;
    fmt.fmt.pix.height = image_height;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_GREY;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (-1 == xioctl(fd, VIDIOC_S_FMT, &fmt)) {
        errno_exit("VIDIOC_S_FMT");
    }

    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_GREY) {
        fprintf(stderr, "Libcamera doesn't support GREY format\n");
        return -1;
    }

    if (fmt.fmt.pix.width != image_width || fmt.fmt.pix.height != image_height) {
        fprintf(stderr, "Libcamera doesn't support %dx%d resolution\n", image_width, image_height);
        return -1;
    }

    CLEAR(streamparm);
    streamparm.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    streamparm.parm.capture.timeperframe.numerator = 1;
    streamparm.parm.capture.timeperframe.denominator = 30; // 30 fps

    if (-1 == xioctl(fd, VIDIOC_S_PARM, &streamparm)) {
        fprintf(stderr, "VIDIOC_S_PARM failed, trying VIDIOC_S_FMT\n");
        if (-1 == xioctl(fd, VIDIOC_S_FMT, &fmt)) {
            errno_exit("VIDIOC_S_FMT");
        }
    }

    return 0;
}

static int init_device(void)
{
    struct v4l2_requestbuffers req;

    CLEAR(req);
    req.count               = 4; // Number of buffers
    req.type                = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory              = V4L2_MEMORY_MMAP;

    if (-1 == xioctl(fd, VIDIOC_REQBUFS, &req)) {
        if (EINVAL == errno) {
            fprintf(stderr, "%s does not support memory mapping\n", device_name);
            return -1;
        } else {
            errno_exit("VIDIOC_REQBUFS");
        }
    }

    if (req.count < 2) {
        fprintf(stderr, "Insufficient buffer memory on %s\n", device_name);
        return -1;
    }

    buffers = calloc(req.count, sizeof(*buffers));

    if (!buffers) {
        fprintf(stderr, "Out of memory\n");
        return -1;
    }

    for (n_buffers = 0; n_buffers < req.count; ++n_buffers) {
        struct v4l2_buffer buf;

        CLEAR(buf);
        buf.type        = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory      = V4L2_MEMORY_MMAP;
        buf.index       = n_buffers;

        if (-1 == xioctl(fd, VIDIOC_QUERYBUF, &buf)) {
            errno_exit("VIDIOC_QUERYBUF");
        }

        buffers[n_buffers].length = buf.length;
        buffers[n_buffers].start = mmap(NULL /* start anywhere */, buf.length, PROT_READ | PROT_WRITE /* required */, MAP_SHARED /* recommended */, fd, buf.m.offset);

        if (MAP_FAILED == buffers[n_buffers].start) {
            errno_exit("mmap");
        }
    }

    return 0;
}

static int start_capturing(void)
{
    unsigned int i;
    enum v4l2_buf_type type;

    for (i = 0; i < n_buffers; ++i) {
        struct v4l2_buffer buf;

        CLEAR(buf);
        buf.type        = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory      = V4L2_MEMORY_MMAP;
        buf.index       = i;

        if (-1 == xioctl(fd, VIDIOC_QBUF, &buf)) {
            errno_exit("VIDIOC_QBUF");
        }
    }

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    if (-1 == xioctl(fd, VIDIOC_STREAMON, &type)) {
        errno_exit("VIDIOC_STREAMON");
    }

    return 0;
}

static int stop_capturing(void)
{
    enum v4l2_buf_type type;

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    if (-1 == xioctl(fd, VIDIOC_STREAMOFF, &type)) {
        errno_exit("VIDIOC_STREAMOFF");
    }

    return 0;
}

static int uninit_device(void)
{
    unsigned int i;

    for (i = 0; i < n_buffers; ++i) {
        if (-1 == munmap(buffers[i].start, buffers[i].length)) {
            errno_exit("munmap");
        }
    }

    free(buffers);

    return 0;
}

static int close_device(void)
{
    if (-1 == close(fd)) {
        errno_exit("close");
    }

    fd = -1;

    return 0;
}

static int save_image(const void *buffer, size_t size, const char *filename)
{
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    if (fwrite(buffer, 1, size, fp) != size) {
        fprintf(stderr, "Error writing to file %s: %s\n", filename, strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

static void signal_handler(int sig)
{
    fprintf(stderr, "Signal %d received, stopping...\n", sig);
    running = 0;
}

int main(int argc, char **argv)
{
    int opt;

    while ((opt = getopt(argc, argv, "d:w:h:")) != -1) {
        switch (opt) {
            case 'd':
                device_name = optarg;
                break;
            case 'w':
                image_width = atoi(optarg);
                break;
            case 'h':
                image_height = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-d device] [-w width] [-h height]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (-1 == fd) {
        fprintf(stderr, "Cannot open '%s': %s\n", device_name, strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (read_device_info(fd) == -1) {
        close_device();
        exit(EXIT_FAILURE);
    }

    if (init_device() == -1) {
        close_device();
        exit(EXIT_FAILURE);
    }

    if (start_capturing() == -1) {
        uninit_device();
        close_device();
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        fd_set fds;
        struct timeval tv;
        int r;

        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        tv.tv_sec = 2; // Timeout of 2 seconds
        tv.tv_usec = 0;

        r = select(fd + 1, &fds, NULL, NULL, &tv);

        if (-1 == r) {
            if (EINTR == errno) {
                fprintf(stderr, "select interrupted by signal\n");
                break;
            } else {
                errno_exit("select");
            }
        } else if (0 == r) {
            fprintf(stderr, "select timeout\n");
            break;
        } else {
            struct v4l2_buffer buf;

            CLEAR(buf);
            buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
            buf.memory = V4L2_MEMORY_MMAP;

            if (-1 == xioctl(fd, VIDIOC_DQBUF, &buf)) {
                if (EAGAIN == errno) {
                    fprintf(stderr, "VIDIOC_DQBUF EAGAIN\n");
                    continue;
                } else {
                    errno_exit("VIDIOC_DQBUF");
                }
            }

            frame_count++;
            char filename[50];
            snprintf(filename, sizeof(filename), "image_%04d.pgm", frame_count);

            if (save_image(buffers[buf.index].start, buf.bytesused, filename) == -1) {
                fprintf(stderr, "Failed to save image %s\n", filename);
            }

            if (-1 == xioctl(fd, VIDIOC_QBUF, &buf)) {
                errno_exit("VIDIOC_QBUF");
            }
        }
    }

    stop_capturing();
    uninit_device();
    close_device();

    fprintf(stderr, "Captured %d frames\n", frame_count);

    return 0;
}

