#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define LOG_FILE "frame_log.txt"
#define MAX_BUFFERS 4

// Structure to hold video buffer information
typedef struct {
    void   *start;
    size_t  length;
} buffer;

// Global variables
static int              fd              = -1;
static buffer           *buffers        = NULL;
static unsigned int     n_buffers       = 0;
static FILE             *log_file       = NULL;
static volatile sig_atomic_t keep_running = 1;

// Function prototypes
int  open_device(const char *device_name);
int  init_device(int fd);
int  start_capturing(int fd);
int  stop_capturing(int fd);
int  uninit_device(int fd);
int  close_device(int fd);
int  init_mmap(int fd);
int  uninit_mmap(int fd);
int  capture_frame(int fd, FILE *log_file);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    if (sig == SIGINT) {
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully.\n");
        keep_running = 0;
    }
}

// Open the video device
int open_device(const char *device_name) {
    int fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (fd == -1) {
        perror("Error opening device");
        return -1;
    }
    return fd;
}

// Initialize the video device
int init_device(int fd) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;

    // Check device capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("Error querying capabilities");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        return -1;
    }

    // Set video format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640; // Example width
    fmt.fmt.pix.height = 480; // Example height
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG; // Request MJPEG format
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("Error setting format");
        return -1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = MAX_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("Error requesting buffers");
        return -1;
    }

    if (req.count < 2) {
        fprintf(stderr, "Insufficient buffer memory\n");
        return -1;
    }

    return 0;
}

// Initialize memory mapping
int init_mmap(int fd) {
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;

    memset(&req, 0, sizeof(req));
