#define DEVICE_NAME "/dev/video0"
#define UDP_PORT 5000
#define MAX_BUFFERS 4
#define MAX_FRAME_SIZE (640 * 480 * 2) // YUYV format
#define MAX_PAYLOAD_SIZE (65000 - sizeof(struct frame_header))
#define MAX_FRAGMENTS ((MAX_FRAME_SIZE + MAX_PAYLOAD_SIZE - 1) / MAX_PAYLOAD_SIZE)

// Structure to hold frame header information
struct frame_header {
    uint32_t frame_index;
    uint32_t fragment_index;
    uint32_t total_fragments;
    uint32_t payload_size;
};

// Global variables
int fd = -1;
struct v4l2_capability cap;
struct v4l2_format fmt;
struct v4l2_requestbuffers req;
struct v4l2_buffer buf;
void *buffers[MAX_BUFFERS];
size_t buffer_sizes[MAX_BUFFERS];
int buffer_count = 0;
int frame_index = 0;
int running = 1;
char *target_ip = NULL;

// Function prototypes
int init_camera();
int configure_camera();
int allocate_buffers();
int capture_frame(void **frame_data, size_t *frame_size);
int fragment_frame(const void *frame_data, size_t frame_size, void **fragments, size_t *fragment_sizes, int *total_fragments);
int send_udp_packet(const void *data, size_t data_size, const char *ip_address, int port);
void signal_handler(int sig);
void cleanup();

// Signal handler function
void signal_handler(int sig) {
    printf("Caught signal %d, exiting...\n", sig);
    running = 0;
}

// Initialize the camera
int init_camera() {
    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening device");
        return -1;
    }

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        close(fd);
        return -1;
    }

    return 0;
}

// Configure the camera for YUYV format
int configure_camera() {
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        return -1;
    }

    return 0;
}

// Allocate memory for buffers
int allocate_buffers() {
    memset(&req, 0, sizeof(req));
    req.count = MAX_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        return -1;
    }

    if (req.count < 2) {
        fprintf(stderr, "Insufficient buffer memory\n");
        return -1;
    }

    buffer_count = req.count;

    for (int i = 0; i < buffer_count; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("Error querying buffer");
            return -1;
        }

        buffers[i] = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffers[i] == MAP_FAILED) {
            perror("Error mapping buffer");
            return -1;
        }
        buffer_sizes[i] = buf.length;
    }

    return 0;
}

// Capture a single frame
int capture_frame(void **frame_data, size_t *frame_size) {
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    *frame_data = buffers[buf.index];
    *frame_size = buf.bytesused;

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        return -1;
    }

    return 0;
}

// Fragment a frame into UDP packets
int fragment_frame(const void *frame_data, size_t frame_size, void **fragments, size_t *fragment_sizes, int *total_fragments) {
    *total_fragments = (frame_size + MAX_PAYLOAD_SIZE - 1) / MAX_PAYLOAD_SIZE;

    for (int i = 0; i < *total_fragments; i++) {
        size_t payload_size = (i < *total_fragments - 1) ? MAX_PAYLOAD_SIZE : (frame_size - i * MAX_PAYLOAD_SIZE);
        fragments[i] = malloc(payload_size);
        if (fragments[i] == NULL) {
            perror("Error allocating memory for fragment");
            return -1;
        }
        memcpy(fragments[i], (const char *)frame_data + i * MAX_PAYLOAD_SIZE, payload_size);
        fragment_sizes[i] = payload_size;
    }

    return 0;
}

// Send a UDP packet
int send_udp_packet(const void *data, size_t data_size, const char *ip_address, int port) {
    int sockfd;
    struct sockaddr_in servaddr;

    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("Error creating socket");
        return -1;
    }

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(port);
    if (inet_pton(AF_INET, ip_address, &servaddr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(sockfd);
        return -1;
    }

    if (sendto(sockfd, data, data_size, 0, (const struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        perror("Error sending data");
        close(sockfd);
        return -1;
    }

    close(sockfd);
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    for (int i = 0; i < buffer_count; i++) {
        if (buffers[i] != NULL) {
            munmap(buffers[i], buffer_sizes[i]);
        }
    }

    if (fd != -1) {
        close(fd);
    }
}

