        return -1;
    }

    return 0;
}

// Function to start capturing
int start_capturing(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("Error starting capturing");
        return -1;
    }

    return 0;
}

// Function to stop capturing
int stop_capturing(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    if (ioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        perror("Error stopping capturing");
        return -1;
    }

    return 0;
}

// Function to uninitialize the device
int uninit_device(int fd) {
    // No specific uninitialization needed for this example
    return 0;
}

// Function to allocate buffers
int allocate_buffers(int fd, unsigned int n_buffers, buffer **buffers) {
    struct v4l2_requestbuffers req;

    memset(&req, 0, sizeof(req));
    req.count = n_buffers;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("Error requesting buffers");
        return -1;
    }

    if (req.count < n_buffers) {
        fprintf(stderr, "Insufficient buffer memory\n");
        return -1;
    }

    *buffers = calloc(req.count, sizeof(**buffers));
    if (!*buffers) {
        perror("Out of memory");
        return -1;
    }

    for (unsigned int i = 0; i < req.count; ++i) {
        struct v4l2_buffer buf;

        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            perror("Error querying buffer");
            free(*buffers);
            return -1;
        }

        (*buffers)[i].length = buf.length;
        (*buffers)[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if ((*buffers)[i].start == MAP_FAILED) {
            perror("Error mapping buffer");
            free(*buffers);
            return -1;
        }
    }

    return 0;
}

// Function to free buffers
int free_buffers(int fd, unsigned int n_buffers, buffer *buffers) {
    for (unsigned int i = 0; i < n_buffers; ++i) {
        if (munmap(buffers[i].start, buffers[i].length) == -1) {
            perror("Error unmapping buffer");
            return -1;
        }
    }
    free(buffers);
    return 0;
}

// Function to dequeue a buffer
int dequeue_buffer(int fd, buffer *buffers, unsigned int n_buffers, unsigned int *index) {
    struct v4l2_buffer buf;

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("Error dequeueing buffer");
        return -1;
    }

    *index = buf.index;
    return 0;
}

// Function to enqueue a buffer
int enqueue_buffer(int fd, buffer *buffers, unsigned int n_buffers, unsigned int index) {
    struct v4l2_buffer buf;

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = index;

    if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        perror("Error enqueueing buffer");
        return -1;
    }

    return 0;
}

// Function to write image to file
int write_image_to_file(const char *filename, const void *data, size_t size) {
    image_file = fopen(filename, "wb");
    if (!image_file) {
        perror("Error opening file for writing");
        return -1;
    }

    if (fwrite(data, 1, size, image_file) != size) {
        perror("Error writing to file");
        fclose(image_file);
        return -1;
    }

    if (fclose(image_file) != 0) {
        perror("Error closing file");
        return -1;
    }

    return 0;
}

int main() {
    unsigned int buffer_index;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the device
    fd = open_device(DEVICE_NAME);
    if (fd == -1) {
        return EXIT_FAILURE;
    }

    // Initialize the device
    if (init_device(fd) == -1) {
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Allocate buffers
    if (allocate_buffers(fd, NUM_BUFFERS, &buffers) == -1) {
        uninit_device(fd);
        close_device(fd);
        return EXIT_FAILURE;
    }
    n_buffers = NUM_BUFFERS;

    // Start capturing
    if (start_capturing(fd) == -1) {
        free_buffers(fd, n_buffers, buffers);
        uninit_device(fd);
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!stop_streaming) {
        // Dequeue a buffer
        if (dequeue_buffer(fd, buffers, n_buffers, &buffer_index) == -1) {
            break;
        }

        // Check if data is available
        if (buffers[buffer_index].length > 0) {
            // Write the image to file
            if (write_image_to_file("image.jpg", buffers[buffer_index].start, buffers[buffer_index].length) == -1) {
                fprintf(stderr, "Error writing image to file\n");
            }
        }

        // Enqueue the buffer
        if (enqueue_buffer(fd, buffers, n_buffers, buffer_index) == -1) {
            break;
        }
    }

    // Stop capturing
    if (stop_capturing(fd) == -1) {
        fprintf(stderr, "Error stopping capturing during cleanup\n");
    }

    // Free buffers
    if (free_buffers(fd, n_buffers, buffers) == -1) {
        fprintf(stderr, "Error freeing buffers during cleanup\n");
    }

    // Uninitialize the device
    if (uninit_device(fd) == -1) {
        fprintf(stderr, "Error uninitializing device during cleanup\n");
    }

    // Close the device
    if (close_device(fd) == -1) {
        fprintf(stderr, "Error closing device during cleanup\n");
    }

    return EXIT_SUCCESS;
}

