#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define TILT_UP_BUTTON_PIN 6
#define TILT_DOWN_BUTTON_PIN 7
#define PAN_LEFT_BUTTON_PIN 8
#define PAN_RIGHT_BUTTON_PIN 9

// Define PWM frequency and range
#define PWM_FREQUENCY 50
#define PWM_RANGE 1000

// Define servo pulse width limits (microseconds)
#define SERVO_MIN_PULSE_WIDTH 1000
#define SERVO_MAX_PULSE_WIDTH 2000

// Define servo pulse width range
#define SERVO_PULSE_WIDTH_RANGE (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH)

// Define servo mid-position value
#define SERVO_MID_POSITION 75

// Define button press debounce delay (milliseconds)
#define DEBOUNCE_DELAY 50

// Global variables
volatile sig_atomic_t program_running = 1;
int pan_position = SERVO_MID_POSITION;
int tilt_position = SERVO_MID_POSITION;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void cleanup_gpio();
int set_servo_position(int gpio_pin, int position);
int read_button(int gpio_pin);
void update_servo_positions();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_UP_BUTTON_PIN, PI_INPUT);
    gpioSetMode(TILT_DOWN_BUTTON_PIN, PI_INPUT);
    gpioSetMode(PAN_LEFT_BUTTON_PIN, PI_INPUT);
    gpioSetMode(PAN_RIGHT_BUTTON_PIN, PI_INPUT);

    // Enable pull-up resistors for buttons
    gpioSetPullUpDown(TILT_UP_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(TILT_DOWN_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(PAN_LEFT_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(PAN_RIGHT_BUTTON_PIN, PI_PUD_UP);

    // Set PWM frequency
    gpioSetPWMfrequency(PAN_SERVO_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_SERVO_PIN, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(PAN_SERVO_PIN, PWM_RANGE);
    gpioSetPWMrange(TILT_SERVO_PIN, PWM_RANGE);

    // Initialize servo positions to mid-position
    if (set_servo_position(PAN_SERVO_PIN, SERVO_MID_POSITION) != 0) {
        fprintf(stderr, "Failed to set initial pan servo position\n");
        return 1;
    }
    if (set_servo_position(TILT_SERVO_PIN, SERVO_MID_POSITION) != 0) {
        fprintf(stderr, "Failed to set initial tilt servo position\n");
        return 1;
    }

    return 0;
}

// Cleanup GPIO resources
void cleanup_gpio() {
    // Stop PWM signals
    gpioPWM(PAN_SERVO_PIN, 0);
    gpioPWM(TILT_SERVO_PIN, 0);

    // Release GPIO pins
    gpioSetMode(PAN_SERVO_PIN, PI_INPUT); // Set to input to avoid spurious signals
    gpioSetMode(TILT_SERVO_PIN, PI_INPUT);
    gpioSetMode(TILT_UP_BUTTON_PIN, PI_INPUT);
    gpioSetMode(TILT_DOWN_BUTTON_PIN, PI_INPUT);
    gpioSetMode(PAN_LEFT_BUTTON_PIN, PI_INPUT);
    gpioSetMode(PAN_RIGHT_BUTTON_PIN, PI_INPUT);

    gpioTerminate();
}

// Set servo position using PWM
int set_servo_position(int gpio_pin, int position) {
    if (position < 0 || position > 100) {
        fprintf(stderr, "Invalid servo position: %d\n", position);
        return 1;
    }

    // Calculate pulse width in microseconds
    int pulse_width = SERVO_MIN_PULSE_WIDTH + (int)(((float)position / 100.0) * SERVO_PULSE_WIDTH_RANGE);

    // Set PWM duty cycle
    int duty_cycle = (int)(((float)pulse_width / 1000000.0) * PWM_RANGE); // Convert us to s and then to duty cycle
    if (gpioPWM(gpio_pin, duty_cycle) != 0) {
        fprintf(stderr, "Failed to set PWM duty cycle for GPIO %d\n", gpio_pin);
        return 1;
    }

    return 0;
}

// Read button state with debouncing
int read_button(int gpio_pin) {
    int button_state = gpioRead(gpio_pin);
    gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay in microseconds
    return (gpioRead(gpio_pin) == button_state) ? button_state : 0; // Return stable state
}

// Update servo positions based on button presses
void update_servo_positions() {
    if (read_button(TILT_UP_BUTTON_PIN) == 0) {
        tilt_position += 5;
        if (tilt_position > 125) {
            tilt_position = 125;
        }
        if (set_servo_position(TILT_SERVO_PIN, tilt_position) != 0) {
            fprintf(stderr, "Failed to set tilt servo position\n");
        }
        printf("Tilt: %d\n", tilt_position);
    }
    if (read_button(TILT_DOWN_BUTTON_PIN) == 0) {
        tilt_position -= 5;
        if (tilt_position < 25) {
            tilt_position = 25;
        }
        if (set_servo_position(TILT_SERVO_PIN, tilt_position) != 0) {
            fprintf(stderr, "Failed to set tilt servo position\n");
        }
        printf("Tilt: %d\n", tilt_position);
    }
    if (read_button(PAN_LEFT_BUTTON_PIN) == 0) {
        pan_position -= 5;
        if (pan_position < 25) {
            pan_position = 25;
        }
        if (set_servo_position(PAN_SERVO_PIN, pan_position) != 0) {
            fprintf(stderr, "Failed to set pan servo position\n");
        }
        printf("Pan: %d\n", pan_position);
    }
    if (read_button(PAN_RIGHT_BUTTON_PIN) == 0) {
        pan_position += 5;
        if (pan_position > 125) {
            pan_position = 125;
        }
        if (set_servo_position(PAN_SERVO_PIN, pan_position) != 0) {
            fprintf(stderr, "Failed to set pan servo position\n");
        }
        printf("Pan: %d\n", pan_position);
    }
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Pan-Tilt Camera Control Program\n");
    printf("Press Ctrl+C to exit\n");

    // Main loop
    while (program_running) {
        update_servo_positions();
        gpioDelay(50000); // Poll buttons every 50ms
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio();

    return 0;
}

