#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <jpeglib.h>
#include <setjmp.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define NUM_BUFFERS 4
#define TIMEOUT_SEC 2

// Structure to hold buffer information
typedef struct {
    void   *start;
    size_t  length;
} buffer;

// Global variables
static int              fd = -1;
static buffer          *buffers = NULL;
static unsigned int     n_buffers = 0;
static int              running = 1;

// Function prototypes
int  open_device(const char *device_name);
int  init_device(int fd);
int  start_capturing(int fd);
int  stop_capturing(int fd);
int  uninit_device(int fd);
int  close_device(int fd);
int  allocate_buffers(int fd, buffer **buffers, unsigned int *n_buffers);
int  free_buffers(buffer *buffers, unsigned int n_buffers);
int  capture_frame(int fd, buffer *buffers, unsigned int n_buffers, unsigned char **yuyv_data, unsigned char **rgb_data);
int  convert_yuyv_to_rgb24(unsigned char *yuyv_data, unsigned char *rgb_data, int width, int height);
int  apply_blur_filter(unsigned char *rgb_data, int width, int height);
int  encode_jpeg(unsigned char *rgb_data, int width, int height, int quality, unsigned char **jpeg_data, unsigned long *jpeg_size);
int  save_jpeg_file(unsigned char *jpeg_data, unsigned long jpeg_size, const char *filename);
void signal_handler(int signum);

// Error handling macro
#define CHECK_ERROR(ret, msg) \
    if (ret < 0) { \
        fprintf(stderr, "%s: %s\n", msg, strerror(errno)); \
        return -1; \
    }

// Signal handler for Ctrl+C
void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        running = 0;
    }
}

// Open the video device
int open_device(const char *device_name) {
    int fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        fprintf(stderr, "Error opening device %s: %s\n", device_name, strerror(errno));
        return -1;
    }
    return fd;
}

// Initialize the video device
int init_device(int fd) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;

    // Check device capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        return -1;
    }

    // Set image format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        return -1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Start capturing frames
int start_capturing(int fd) {
    unsigned int i;
    struct v4l2_buffer buf;

    for (i = 0; i < n_buffers; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Stop capturing frames
int stop_capturing(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        fprintf(stderr, "Error stopping stream: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Uninitialize the video device
int uninit_device(int fd) {
    unsigned int i;
    struct v4l2_buffer buf;

    for (i = 0; i < n_buffers; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
            fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
