// Allocate memory for buffers
int allocate_buffers(int fd, buffer **buffers, unsigned int *n_buffers) {
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    unsigned int i;

    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        return -1;
    }

    *buffers = calloc(req.count, sizeof(**buffers));
    if (!*buffers) {
        fprintf(stderr, "Out of memory\n");
        return -1;
    }

    *n_buffers = req.count;

    for (i = 0; i < *n_buffers; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
            return -1;
        }

        (*buffers)[i].length = buf.length;
        (*buffers)[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if ((*buffers)[i].start == MAP_FAILED) {
            fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
            return -1;
        }
    }

    return 0;
}

// Free memory for buffers
int free_buffers(buffer *buffers, unsigned int n_buffers) {
    unsigned int i;

    for (i = 0; i < n_buffers; ++i) {
        if (munmap(buffers[i].start, buffers[i].length) < 0) {
            fprintf(stderr, "Error unmapping buffer: %s\n", strerror(errno));
            return -1;
        }
    }

    free(buffers);
    return 0;
}

// Capture a frame
int capture_frame(int fd, buffer *buffers, unsigned int n_buffers, unsigned char **yuyv_data, unsigned char **rgb_data) {
    fd_set fds;
    struct timeval tv;
    int r;
    struct v4l2_buffer buf;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = TIMEOUT_SEC;
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        fprintf(stderr, "Error in select: %s\n", strerror(errno));
        return -1;
    }

    if (r == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        return -1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        return -1;
    }

    *yuyv_data = buffers[buf.index].start;

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
        return -1;
    }

    *rgb_data = malloc(IMAGE_WIDTH * IMAGE_HEIGHT * 3);
    if (!*rgb_data) {
