int encode_jpeg(unsigned char *rgb_data, int width, int height, int quality, unsigned char **jpeg_data, unsigned long *jpeg_size) {
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;
    unsigned char *row_pointer[1];
    int row_stride;

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);

    jpeg_mem_dest(&cinfo, jpeg_data, jpeg_size);

    cinfo.image_width = width;
    cinfo.image_height = height;
    cinfo.input_components = 3;
    cinfo.in_color_space = JCS_RGB;

    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, quality, TRUE);

    jpeg_start_compress(&cinfo, TRUE);

    row_stride = width * 3;

    while (cinfo.next_scanline < cinfo.image_height) {
        row_pointer[0] = &rgb_data[cinfo.next_scanline * row_stride];
        jpeg_write_scanlines(&cinfo, row_pointer, 1);
    }

    jpeg_finish_compress(&cinfo);
    jpeg_destroy_compress(&cinfo);

    return 0;
}

// Save JPEG data to file
int save_jpeg_file(unsigned char *jpeg_data, unsigned long jpeg_size, const char *filename) {
    FILE *outfile = fopen(filename, "wb");
    if (!outfile) {
        fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    fwrite(jpeg_data, 1, jpeg_size, outfile);
    fclose(outfile);

    return 0;
}

int main() {
    unsigned char *yuyv_data = NULL;
    unsigned char *rgb_data = NULL;
    unsigned char *jpeg_data = NULL;
    unsigned long jpeg_size = 0;
    time_t rawtime;
    struct tm *timeinfo;
    char filename[80];

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Open the video device
    fd = open_device(DEVICE_NAME);
    if (fd < 0) {
        return EXIT_FAILURE;
    }

    // Initialize the video device
    if (init_device(fd) < 0) {
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Allocate memory for buffers
    if (allocate_buffers(fd, &buffers, &n_buffers) < 0) {
        uninit_device(fd);
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Start capturing frames
    if (start_capturing(fd) < 0) {
        free_buffers(buffers, n_buffers);
        uninit_device(fd);
        close_device(fd);
        return EXIT_FAILURE;
    }

    printf("Capturing frames... Press Ctrl+C to exit.\n");

    // Capture and process frames until Ctrl+C is pressed
    while (running) {
        if (capture_frame(fd, buffers, n_buffers, &yuyv_data, &rgb_data) == 0) {
            // Convert YUYV to RGB24
            if (convert_yuyv_to_rgb24(yuyv_data, rgb_data, IMAGE_WIDTH, IMAGE_HEIGHT) == 0) {
                // Apply blur filter
                if (apply_blur_filter(rgb_data, IMAGE_WIDTH, IMAGE_HEIGHT) == 0) {
                    // Encode RGB24 to JPEG
                    if (encode_jpeg(rgb_data, IMAGE_WIDTH, IMAGE_HEIGHT, 75, &jpeg_data, &jpeg_size) == 0) {
                        // Get current timestamp
                        time(&rawtime);
                        timeinfo = localtime(&rawtime);

                        // Format filename with timestamp
                        strftime(filename, sizeof(filename), "capture_%Y%m%d_%H%M%S.jpg", timeinfo);

                        // Save JPEG file
                        if (save_jpeg_file(jpeg_data, jpeg_size, filename) == 0) {
                            printf("Saved JPEG file: %s\n", filename);
                        } else {
                            fprintf(stderr, "Failed to save JPEG file.\n");
                        }

                        // Free JPEG data
                        free(jpeg_data);
                    } else {
                        fprintf(stderr, "Failed to encode JPEG.\n");
                    }
                } else {
                    fprintf(stderr, "Failed to apply blur filter.\n");
                }
            } else {
                fprintf(stderr, "Failed to convert YUYV to RGB24.\n");
            }

            // Free RGB data
            free(rgb_data);
        } else {
            fprintf(stderr, "Failed to capture frame.\n");
        }
    }

    // Stop capturing frames
    if (stop_capturing(fd) < 0) {
        fprintf(stderr, "Failed to stop capturing frames.\n");
    }

    // Uninitialize the video device
    if (uninit_device(fd) < 0) {
        fprintf(stderr, "Failed to uninitialize device.\n");
    }

    // Free memory for buffers
    if (free_buffers(buffers, n_buffers) < 0) {
        fprintf(stderr, "Failed to free buffers.\n");
    }

    // Close the video device
    if (close_device(fd) < 0) {
        fprintf(stderr, "Failed to close device.\n");
    }

    return EXIT_SUCCESS;
}

