#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <linux/videodev2.h>
#include <errno.h>

#define DEVICE_NAME "/dev/video0"

// Function to check if a file exists
int file_exists(const char *filename) {
    struct stat buffer;
    return (stat(filename, &buffer) == 0);
}

// Function to open the camera device
int open_camera(const char *device_name) {
    int fd = open(device_name, O_RDWR);
    if (fd < 0) {
        perror("Error opening camera device");
        return -1;
    }
    return fd;
}

// Function to query device capabilities
int query_capabilities(int fd, struct v4l2_capability *cap) {
    if (ioctl(fd, VIDIOC_QUERYCAP, cap) < 0) {
        perror("Error querying capabilities");
        return -1;
    }
    return 0;
}

// Function to enumerate frame sizes
int enumerate_frame_sizes(int fd, struct v4l2_frmivalenum *fival) {
    fival->index = 0;
    fival->pixel_format = V4L2_PIX_FMT_YUYV; // Example pixel format

    while (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, fival) == 0) {
        if (fival->type == V4L2_FRMSIZE_TYPE_DISCRETE) {
            printf("  Supported frame size: %dx%d\n", fival->discrete.width, fival->discrete.height);

            struct v4l2_frmsizeenum frmsize;
            frmsize.index = 0;
            frmsize.pixel_format = V4L2_PIX_FMT_YUYV;
            frmsize.discrete.width = fival->discrete.width;
            frmsize.discrete.height = fival->discrete.height;

            struct v4l2_frmivalenum interval;
            interval.pixel_format = V4L2_PIX_FMT_YUYV;
            interval.width = fival->discrete.width;
            interval.height = fival->discrete.height;

            while (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &interval) == 0) {
                if (interval.type == V4L2_FRMIVAL_TYPE_DISCRETE) {
                    printf("    Supported frame interval: %d/%d seconds\n", interval.discrete.numerator, interval.discrete.denominator);
                } else if (interval.type == V4L2_FRMIVAL_TYPE_CONTINUOUS) {
                    printf("    Supported frame interval: Continuous from %d/%d to %d/%d seconds\n",
                           interval.discrete.numerator, interval.discrete.denominator,
                           interval.range.max.numerator, interval.range.max.denominator);
                } else if (interval.type == V4L2_FRMIVAL_TYPE_STEPWISE) {
                    printf("    Supported frame interval: Stepwise from %d/%d to %d/%d seconds, step %d/%d\n",
                           interval.discrete.numerator, interval.discrete.denominator,
                           interval.range.max.numerator, interval.range.max.denominator,
                           interval.step.numerator, interval.step.denominator);
                }
                interval.index++;
            }
            if (errno != EINVAL) {
                perror("Error enumerating frame intervals");
                return -1;
            }
        }
        fival->index++;
    }
    if (errno != EINVAL) {
        perror("Error enumerating frame sizes");
        return -1;
    }
    return 0;
}

// Function to query autofocus control
int query_autofocus_control(int fd, struct v4l2_queryctrl *ctrl) {
    ctrl->id = V4L2_CID_FOCUS_AUTO;
    if (ioctl(fd, VIDIOC_QUERYCTRL, ctrl) < 0) {
        if (errno == EINVAL) {
            printf("  Autofocus control not supported\n");
            return 0; // Not an error, just not supported
        }
        perror("Error querying autofocus control");
        return -1;
    }

    if (ctrl->flags & V4L2_CTRL_FLAG_DISABLED) {
        printf("  Autofocus control disabled\n");
    } else {
        printf("  Autofocus control enabled\n");
    }
    return 0;
}

int main() {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_frmivalenum fival;
    struct v4l2_queryctrl ctrl;

    // Check if the device node exists
    if (!file_exists(DEVICE_NAME)) {
        fprintf(stderr, "Error: %s does not exist. Ensure the camera is connected and enabled.\n", DEVICE_NAME);
        return 1;
    }

    // Open the camera device
    fd = open_camera(DEVICE_NAME);
    if (fd < 0) {
        return 1;
    }

    // Query device capabilities
    if (query_capabilities(fd, &cap) < 0) {
        close(fd);
        return 1;
    }

    printf("Camera device: %s\n", DEVICE_NAME);
    printf("Driver: %s\n", cap.driver);
    printf("Card: %s\n", cap.card);
    printf("Bus info: %s\n", cap.bus_info);
    printf("Version: %u.%u.%u\n", (cap.version >> 16) & 0xFF, (cap.version >> 8) & 0xFF, cap.version & 0xFF);
    printf("Capabilities: 0x%08x\n", cap.capabilities);

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", DEVICE_NAME);
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", DEVICE_NAME);
        close(fd);
        return 1;
    }

    printf("Supported formats:\n");
    // Enumerate supported frame sizes
    if (enumerate_frame_sizes(fd, &fival) < 0) {
        close(fd);
        return 1;
    }

    // Query autofocus control
    if (query_autofocus_control(fd, &ctrl) < 0) {
        close(fd);
        return 1;
    }

    // Close the camera device
    close(fd);

    printf("Camera information summary complete.\n");

    return 0;
}

