#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define UP_BUTTON_PIN 6
#define DOWN_BUTTON_PIN 7
#define LEFT_BUTTON_PIN 8
#define RIGHT_BUTTON_PIN 9

// Define servo pulse width limits
#define MIN_PULSE_WIDTH 1000
#define MAX_PULSE_WIDTH 2000
#define CENTER_PULSE_WIDTH 1500

// Define pulse width increment/decrement step
#define PULSE_WIDTH_STEP 10

// Global variables for pulse widths
volatile int pan_pulse_width = CENTER_PULSE_WIDTH;
volatile int tilt_pulse_width = CENTER_PULSE_WIDTH;

// Function prototypes
void button_callback(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioPWM(PAN_SERVO_PIN, 0); // Stop PWM on pan servo
    gpioPWM(TILT_SERVO_PIN, 0); // Stop PWM on tilt servo
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Button callback function
void button_callback(int gpio, int level, uint32_t tick) {
    if (level == 0) { // Button pressed (active low)
        switch (gpio) {
            case UP_BUTTON_PIN:
                tilt_pulse_width += PULSE_WIDTH_STEP;
                if (tilt_pulse_width > MAX_PULSE_WIDTH) {
                    tilt_pulse_width = MAX_PULSE_WIDTH;
                }
                break;
            case DOWN_BUTTON_PIN:
                tilt_pulse_width -= PULSE_WIDTH_STEP;
                if (tilt_pulse_width < MIN_PULSE_WIDTH) {
                    tilt_pulse_width = MIN_PULSE_WIDTH;
                }
                break;
            case LEFT_BUTTON_PIN:
                pan_pulse_width -= PULSE_WIDTH_STEP;
                if (pan_pulse_width < MIN_PULSE_WIDTH) {
                    pan_pulse_width = MIN_PULSE_WIDTH;
                }
                break;
            case RIGHT_BUTTON_PIN:
                pan_pulse_width += PULSE_WIDTH_STEP;
                if (pan_pulse_width > MAX_PULSE_WIDTH) {
                    pan_pulse_width = MAX_PULSE_WIDTH;
                }
                break;
            default:
                fprintf(stderr, "Error: Unknown button GPIO %d\n", gpio);
                break;
        }
        gpioPWM(PAN_SERVO_PIN, pan_pulse_width);
        gpioPWM(TILT_SERVO_PIN, tilt_pulse_width);
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(UP_BUTTON_PIN, PI_INPUT);
    gpioSetMode(DOWN_BUTTON_PIN, PI_INPUT);
    gpioSetMode(LEFT_BUTTON_PIN, PI_INPUT);
    gpioSetMode(RIGHT_BUTTON_PIN, PI_INPUT);

    // Enable pull-up resistors on button pins
    gpioSetPullUpDown(UP_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(DOWN_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(LEFT_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(RIGHT_BUTTON_PIN, PI_PUD_UP);

    // Set PWM frequency to 50 Hz
    gpioSetPWMfrequency(PAN_SERVO_PIN, 50);
    gpioSetPWMfrequency(TILT_SERVO_PIN, 50);

    // Set PWM range (0-255)
    gpioSetPWMrange(PAN_SERVO_PIN, 255);
    gpioSetPWMrange(TILT_SERVO_PIN, 255);

    // Set initial servo positions
    gpioPWM(PAN_SERVO_PIN, CENTER_PULSE_WIDTH);
    gpioPWM(TILT_SERVO_PIN, CENTER_PULSE_WIDTH);

    // Print startup message
    printf("Pan-Tilt Camera Control Program\n");
    printf("Pan Servo Pin: GPIO%d, Tilt Servo Pin: GPIO%d\n", PAN_SERVO_PIN, TILT_SERVO_PIN);
    printf("Up Button Pin: GPIO%d, Down Button Pin: GPIO%d\n", UP_BUTTON_PIN, DOWN_BUTTON_PIN);
    printf("Left Button Pin: GPIO%d, Right Button Pin: GPIO%d\n", LEFT_BUTTON_PIN, RIGHT_BUTTON_PIN);
    printf("Center Position: %d us\n", CENTER_PULSE_WIDTH);

    // Set up signal handlers for Ctrl+C and termination signals
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up button callbacks
    gpioSetAlertFunc(UP_BUTTON_PIN, button_callback);
    gpioSetAlertFunc(DOWN_BUTTON_PIN, button_callback);
    gpioSetAlertFunc(LEFT_BUTTON_PIN, button_callback);
    gpioSetAlertFunc(RIGHT_BUTTON_PIN, button_callback);

    // Main loop
    while (1) {
        // Keep the program running
        sleep(1);
    }

    return 0;
}

