#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <errno.h>
#include <curl/curl.h>
#include <pigpio.h>

// Configuration
#define GPIO_PIN 17
#define DEBOUNCE_TIME_MS 2000
#define POLL_INTERVAL_MS 100
#define IMAGE_QUALITY 85
#define CAPTURE_DIR "motion_captures"

// Global variables
static volatile int running = 1;
static char *ip_address = NULL;
static int port = 0;
static int last_motion_time = 0;

// Structure to hold the image data
typedef struct {
    char *data;
    size_t size;
} ImageData;

// Function prototypes
int initialize_gpio();
int read_sensor();
int debounce_motion();
int capture_image(ImageData *image_data);
int encode_jpeg(unsigned char *raw_data, int width, int height, int quality, unsigned char **jpeg_data, unsigned long *jpeg_size);
int generate_filename(char *filename, size_t filename_size);
int generate_timestamp(char *timestamp, size_t timestamp_size);
int generate_json_payload(const char *filename, const char *timestamp, int motion_status, int gpio_pin, char *json_payload, size_t json_payload_size);
int post_data(const char *url, const char *json_payload, const unsigned char *image_data, size_t image_size);
void signal_handler(int signal);
void cleanup();

// Callback function for libcurl to write received data to memory
size_t write_callback(char *contents, size_t size, size_t nmemb, void *userp) {
    size_t real_size = size * nmemb;
    // This function is not used in this example, but it's good practice to have it.
    return real_size;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <IP address> <port>\n", argv[0]);
        return 1;
    }

    ip_address = argv[1];
    port = atoi(argv[2]);

    if (port <= 0) {
        fprintf(stderr, "Invalid port number.\n");
        return 1;
    }

    // Initialize libcurl
    if (curl_global_init(CURL_GLOBAL_DEFAULT) != 0) {
        fprintf(stderr, "Error initializing libcurl.\n");
        return 1;
    }

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Error initializing pigpio.\n");
        curl_global_cleanup();
        return 1;
    }

    // Create the capture directory if it doesn't exist
    if (mkdir(CAPTURE_DIR, 0777) == -1 && errno != EEXIST) {
        fprintf(stderr, "Error creating directory %s: %s\n", CAPTURE_DIR, strerror(errno));
        gpioTerminate();
        curl_global_cleanup();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    while (running) {
        int motion_detected = read_sensor();

        if (motion_detected) {
            if (debounce_motion()) {
                ImageData image_data;
                if (capture_image(&image_data) == 0) {
                    char filename[64];
                    char timestamp[32];
                    char json_payload[256];
                    char url[128];

                    generate_filename(filename, sizeof(filename));
                    generate_timestamp(timestamp, sizeof(timestamp));
                    generate_json_payload(filename, timestamp, motion_detected, GPIO_PIN, json_payload, sizeof(json_payload));

                    snprintf(url, sizeof(url), "http://%s:%d/upload", ip_address, port);

                    if (post_data(url, json_payload, (unsigned char *)image_data.data, image_data.size) != 0) {
                        fprintf(stderr, "Error posting data.\n");
                    }

                    free(image_data.data);
                } else {
                    fprintf(stderr, "Error capturing image.\n");
                }
            }
        }

        gpioDelay(POLL_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    cleanup();

    return 0;
}

int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    return 0;
}

int read_sensor() {
    return gpioRead(GPIO_PIN);
}

int debounce_motion() {
    int current_time = gpioTick();
    if (current_time - last_motion_time > DEBOUNCE_TIME_MS * 1000) {
        last_motion_time = current_time;
        return 1;
    }
    return 0;
}

int capture_image(ImageData *image_data) {
    FILE *fp;
    char filename[64];
    char command[128];
    unsigned char *raw_data = NULL;
    int width = 640; // Example resolution
    int height = 480;

    generate_filename(filename, sizeof(filename));

    snprintf(command, sizeof(command), "libcamera-still -o %s/%s --width %d --height %d --encoding rgb --timeout 1000", CAPTURE_DIR, filename, width, height);

    int status = system(command);
    if (status != 0) {
        fprintf(stderr, "Error capturing image with libcamera-still: %d\n", status);
        return 1;
    }

    snprintf(filename, sizeof(filename), "%s/%s", CAPTURE_DIR, filename);

    fp = fopen(filename, "rb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening image file: %s\n", strerror(errno));
        return 1;
    }

    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    fseek(fp, 0, SEEK_SET);

    raw_data = (unsigned char *)malloc(file_size);
    if (raw_data == NULL) {
        fprintf(stderr, "Error allocating memory for raw data.\n");
        fclose(fp);
        return 1;
    }

    if (fread(raw_data, 1, file_size, fp) != file_size) {
        fprintf(stderr, "Error reading image data.\n");
        free(raw_data);
        fclose(fp);
        return 1;
    }

    fclose(fp);

    unsigned char *jpeg_data = NULL;
    unsigned long jpeg_size = 0;

    if (encode_jpeg(raw_data, width, height, IMAGE_QUALITY, &jpeg_data, &jpeg_size) != 0) {
        fprintf(stderr, "Error encoding JPEG image.\n");
        free(raw_data);
        return 1;
    }

    free(raw_data);

    image_data->data = (char *)jpeg_data;
    image_data->size = jpeg_size;

    return 0;
}

