    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("SPI transaction failed");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to capture image using libcamera-still
int capture_image() {
    time_t rawtime;
    struct tm *timeinfo;
    char filename[256];
    char command[512];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(filename, sizeof(filename), "/home/pi/images/%Y%m%d_%H%M%S_%3N.jpg", timeinfo);
    snprintf(command, sizeof(command), CAPTURE_COMMAND, filename);

    int status = system(command);
    if (status == -1) {
        perror("Failed to execute capture command");
        return -1;
    } else if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "Capture command exited with status %d\n", WEXITSTATUS(status));
        return -1;
    }

    return 0;
}

// Function to log messages to file
void log_message(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_fp, "[%s] %s\n", timestamp, message);
    fflush(log_fp); // Ensure immediate write to file
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    log_message("Signal received, exiting...");
    keep_running = 0;
}

// Setup function to initialize GPIO and SPI
int setup() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "wiringPiSetupGpio failed: %s\n", strerror(errno));
        return -1;
    }

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    // Configure SPI mode
    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure bits per word
    int bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set bits per word");
        close(spi_fd);
        return -1;
    }

    // Configure SPI speed
    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return -1;
    }

    // Set PIR GPIO pin as input
    pinMode(PIR_GPIO_PIN, INPUT);
    pullUpDnControl(PIR_GPIO_PIN, PUD_DOWN); // Use pull-down resistor

    // Open log file
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("Failed to open log file");
        close(spi_fd);
        return -1;
    }

    log_message("System started");
    return 0;
}

// Cleanup function to release resources
void cleanup() {
    log_message("Cleaning up...");

    // Close SPI device
    if (spi_fd != -1) {
        close(spi_fd);
    }

    // Close log file
    if (log_fp != NULL) {
        fclose(log_fp);
    }

    log_message("System stopped");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (setup() == -1) {
        fprintf(stderr, "Setup failed, exiting\n");
        return 1;
    }

    log_message("Motion detection started");

    // Main loop
    while (keep_running) {
        // Read PIR sensor
        int pir_value = digitalRead(PIR_GPIO_PIN);

        if (pir_value == LOW) { // Motion detected (falling edge)
            log_message("Motion detected!");

            // Debounce delay
            delay(DEBOUNCE_DELAY_MS);

            // Read light sensor
            int light_level = read_mcp3008(MCP3008_CHANNEL);
            if (light_level == -1) {
                log_message("Failed to read light sensor");
            } else {
                char light_message[50];
                snprintf(light_message, sizeof(light_message), "Light level: %d", light_level);
                log_message(light_message);
            }

            // Capture image
            if (capture_image() == -1) {
                log_message("Failed to capture image");
            } else {
                log_message("Image captured successfully");
            }
        }

        delay(10); // Small delay to prevent busy-waiting
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

