#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define DEVICE_NAME "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define PIXEL_FORMAT V4L2_PIX_FMT_YUYV
#define FIELD V4L2_FIELD_NONE
#define CROP_WIDTH 200
#define CROP_HEIGHT 150
#define TIMEOUT_SEC 2

// Structure to hold camera parameters
typedef struct {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    void *buffer;
    size_t buffer_size;
    FILE *fp;
} camera_t;

// Global camera instance
camera_t camera;

// Signal handler flag
volatile sig_atomic_t stop_flag = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, stopping...\n");
    stop_flag = 1;
}

// Function to initialize the camera
int init_camera(camera_t *cam) {
    int ret;

    // Open the device
    cam->fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (cam->fd < 0) {
        perror("Error opening device");
        return -1;
    }

    // Query capabilities
    ret = ioctl(cam->fd, VIDIOC_QUERYCAP, &cam->cap);
    if (ret < 0) {
        perror("Error querying capabilities");
        close(cam->fd);
        return -1;
    }

    if (!(cam->cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(cam->fd);
        return -1;
    }

    if (!(cam->cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        close(cam->fd);
        return -1;
    }

    // Set format
    cam->fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    cam->fmt.fmt.pix.width = WIDTH;
    cam->fmt.fmt.pix.height = HEIGHT;
    cam->fmt.fmt.pix.pixelformat = PIXEL_FORMAT;
    cam->fmt.fmt.pix.field = FIELD;

    ret = ioctl(cam->fd, VIDIOC_S_FMT, &cam->fmt);
    if (ret < 0) {
        perror("Error setting format");
        close(cam->fd);
        return -1;
    }

    // Check if the format was set correctly
    if (cam->fmt.fmt.pix.width != WIDTH || cam->fmt.fmt.pix.height != HEIGHT || cam->fmt.fmt.pix.pixelformat != PIXEL_FORMAT) {
        fprintf(stderr, "Format not set correctly. Requested: %dx%d, %c%c%c%c, Got: %dx%d, %c%c%c%c\n",
                WIDTH, HEIGHT, PIXEL_FORMAT & 0xFF, (PIXEL_FORMAT >> 8) & 0xFF, (PIXEL_FORMAT >> 16) & 0xFF, (PIXEL_FORMAT >> 24) & 0xFF,
                cam->fmt.fmt.pix.width, cam->fmt.fmt.pix.height, cam->fmt.fmt.pix.pixelformat & 0xFF, (cam->fmt.fmt.pix.pixelformat >> 8) & 0xFF, (cam->fmt.fmt.pix.pixelformat >> 16) & 0xFF, (cam->fmt.fmt.pix.pixelformat >> 24) & 0xFF);
        close(cam->fd);
        return -1;
    }

    // Request buffers
    cam->req.count = 1; // Single buffer
    cam->req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    cam->req.memory = V4L2_MEMORY_MMAP;

    ret = ioctl(cam->fd, VIDIOC_REQBUFS, &cam->req);
    if (ret < 0) {
        perror("Error requesting buffers");
        close(cam->fd);
        return -1;
    }

    // Map the buffer
    cam->buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    cam->buf.memory = V4L2_MEMORY_MMAP;
    cam->buf.index = 0;

    ret = ioctl(cam->fd, VIDIOC_QUERYBUF, &cam->buf);
    if (ret < 0) {
        perror("Error querying buffer");
        close(cam->fd);
        return -1;
    }

    cam->buffer_size = cam->buf.length;
    cam->buffer = mmap(NULL, cam->buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, cam->fd, cam->buf.m.offset);
    if (cam->buffer == MAP_FAILED) {
        perror("Error mapping buffer");
        close(cam->fd);
        return -1;
    }

    return 0;
}

// Function to start streaming
int start_streaming(camera_t *cam) {
    int ret;

    // Queue the buffer
    ret = ioctl(cam->fd, VIDIOC_QBUF, &cam->buf);
    if (ret < 0) {
        perror("Error queuing buffer");
        return -1;
    }

    // Start streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    ret = ioctl(cam->fd, VIDIOC_STREAMON, &type);
    if (ret < 0) {
        perror("Error starting streaming");
        return -1;
    }

    return 0;
}

// Function to capture a frame
int capture_frame(camera_t *cam) {
    int ret;
    fd_set fds;
    struct timeval tv;

    FD_ZERO(&fds);
    FD_SET(cam->fd, &fds);

    tv.tv_sec = TIMEOUT_SEC;
    tv.tv_usec = 0;

    ret = select(cam->fd + 1, &fds, NULL, NULL, &tv);
    if (ret < 0) {
        if (errno == EINTR) {
            fprintf(stderr, "Select interrupted by signal\n");
            return -1;
        }
        perror("Error in select");
        return -1;
    } else if (ret == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        return -1;
    }

    // Dequeue the buffer
    ret = ioctl(cam->fd, VIDIOC_DQBUF, &cam->buf);
    if (ret < 0) {
        perror("Error dequeueing buffer");
        return -1;
    }

    return 0;
}

// Function to crop the frame
int crop_frame(camera_t *cam, unsigned char *cropped_data) {
    unsigned char *yuyv_data = (unsigned char *)cam->buffer;
    int yuyv_width = WIDTH; // YUYV is 2 bytes per pixel
    int yuyv_height = HEIGHT;
    int yuyv_row_size = yuyv_width * 2; // Each YUYV pixel is 2 bytes

    // Calculate the starting offset for the cropped region
    int start_x = (WIDTH - CROP_WIDTH) / 2;
    int start_y = (HEIGHT - CROP_HEIGHT) / 2;

    // Calculate the starting offset in the YUYV data
    int yuyv_start_offset = (start_y * yuyv_row_size) + (start_x * 2);

    // Copy the cropped region
    for (int i = 0; i < CROP_HEIGHT; i++) {
        memcpy(cropped_data + (i * CROP_WIDTH * 2), yuyv_data + yuyv_start_offset + (i * yuyv_row_size), CROP_WIDTH * 2);
    }

    return 0;
}

// Function to write the cropped data to a file
int write_to_file(camera_t *cam, unsigned char *cropped_data) {
    cam->fp = fopen("cropped.yuv", "wb");
    if (cam->fp == NULL) {
        perror("Error opening file");
        return -1;
    }

    size_t bytes_written = fwrite(cropped_data, 1, CROP_WIDTH * CROP_HEIGHT * 2, cam->fp);
    if (bytes_written != CROP_WIDTH * CROP_HEIGHT * 2) {
        perror("Error writing to file");
        fclose(cam->fp);
        return -1;
    }

    fclose(cam->fp);
    return 0;
}

// Function to stop streaming
int stop_streaming(camera_t *cam) {
    int ret;
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    ret = ioctl(cam->fd, VIDIOC_STREAMOFF, &type);
    if (ret < 0) {
        perror("Error stopping streaming");
        return -1;
    }

    return 0;
}

// Function to unmap the buffer
int unmap_buffer(camera_t *cam) {
    if (munmap(cam->buffer, cam->buffer_size) < 0) {
        perror("Error unmapping buffer");
        return -1;
    }
    return 0;
}

// Function to close the device
int close_device(camera_t *cam) {
    if (close(cam->fd) < 0) {
        perror("Error closing device");
        return -1;
    }
    return 0;
}

int main() {
    int ret;
    unsigned char *cropped_data;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the camera
    if (init_camera(&camera) < 0) {
        fprintf(stderr, "Camera initialization failed\n");
        return EXIT_FAILURE;
    }

    // Start streaming
    if (start_streaming(&camera) < 0) {
        fprintf(stderr, "Streaming start failed\n");
        close_device(&camera);
        return EXIT_FAILURE;
    }

    // Allocate memory for the cropped data
    cropped_data = (unsigned char *)malloc(CROP_WIDTH * CROP_HEIGHT * 2);
    if (cropped_data == NULL) {
        perror("Error allocating memory for cropped data");
        stop_streaming(&camera);
        close_device(&camera);
        return EXIT_FAILURE;
    }

    // Capture and process a frame
    if (capture_frame(&camera) == 0) {
        if (crop_frame(&camera, cropped_data) == 0) {
            if (write_to_file(&camera, cropped_data) < 0) {
                fprintf(stderr, "Failed to write to file\n");
            }
        } else {
            fprintf(stderr, "Failed to crop frame\n");
        }
    } else {
        fprintf(stderr, "Failed to capture frame\n");
    }

    // Stop streaming
    if (stop_streaming(&camera) < 0) {
        fprintf(stderr, "Streaming stop failed\n");
    }

    // Unmap the buffer
    if (unmap_buffer(&camera) < 0) {
        fprintf(stderr, "Buffer unmapping failed\n");
    }

    // Close the device
    if (close_device(&camera) < 0) {
        fprintf(stderr, "Device closing failed\n");
    }

    // Free allocated memory
    free(cropped_data);

    fprintf(stderr, "Program finished successfully\n");
    return EXIT_SUCCESS;
}

