#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for pan and tilt servos
#define PAN_SERVO_PIN 17
#define TILT_SERVO_PIN 18

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 50

// Define PWM range (0-255)
#define PWM_RANGE 255

// Define servo pulse width limits (microseconds)
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500

// Define angle limits (degrees)
#define MIN_ANGLE 0
#define MAX_ANGLE 180

// Define angle to pulse width conversion factor
#define ANGLE_TO_PULSE_WIDTH_FACTOR ((SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) / (MAX_ANGLE - MIN_ANGLE))

// Global variables for servo angles
int pan_angle = 90;
int tilt_angle = 90;

// Function prototypes
int initialize_gpio();
void set_servo_angle(int gpio_pin, int angle);
void cleanup_gpio();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    cleanup_gpio();
    exit(0);
}

// Function to initialize the pigpio library and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins to output mode
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PAN_SERVO_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_SERVO_PIN, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(PAN_SERVO_PIN, PWM_RANGE);
    gpioSetPWMrange(TILT_SERVO_PIN, PWM_RANGE);

    return 0; // Indicate success
}

// Function to set the servo angle
void set_servo_angle(int gpio_pin, int angle) {
    // Validate angle
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle out of range (%d). Angle must be between %d and %d.\n", angle, MIN_ANGLE, MAX_ANGLE);
        return;
    }

    // Calculate pulse width
    int pulse_width = SERVO_MIN_PULSE_WIDTH + (int)((angle - MIN_ANGLE) * ANGLE_TO_PULSE_WIDTH_FACTOR);

    // Set PWM duty cycle
    int duty_cycle = (int)(((float)pulse_width / 20000.0) * PWM_RANGE); // Convert pulse width to duty cycle (0-255)
    gpioPWM(gpio_pin, duty_cycle);

    // Update global angle
    if (gpio_pin == PAN_SERVO_PIN) {
        pan_angle = angle;
    } else if (gpio_pin == TILT_SERVO_PIN) {
        tilt_angle = angle;
    }

    printf("Servo on GPIO %d set to angle %d\n", gpio_pin, angle);
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    // Set servos to neutral position
    set_servo_angle(PAN_SERVO_PIN, 90);
    set_servo_angle(TILT_SERVO_PIN, 90);

    // Terminate pigpio library
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    // Set initial servo positions
    set_servo_angle(PAN_SERVO_PIN, 90);
    set_servo_angle(TILT_SERVO_PIN, 90);

    // Main loop
    int ch;
    while ((ch = getchar()) != 'q') {
        switch (ch) {
            case 'A': // Left arrow
                pan_angle -= 5;
                if (pan_angle < MIN_ANGLE) {
                    pan_angle = MIN_ANGLE;
                }
                set_servo_angle(PAN_SERVO_PIN, pan_angle);
                break;
            case 'D': // Right arrow
                pan_angle += 5;
                if (pan_angle > MAX_ANGLE) {
                    pan_angle = MAX_ANGLE;
                }
                set_servo_angle(PAN_SERVO_PIN, pan_angle);
                break;
            case 'W': // Up arrow
                tilt_angle += 5;
                if (tilt_angle > MAX_ANGLE) {
                    tilt_angle = MAX_ANGLE;
                }
                set_servo_angle(TILT_SERVO_PIN, tilt_angle);
                break;
            case 'S': // Down arrow
                tilt_angle -= 5;
                if (tilt_angle < MIN_ANGLE) {
                    tilt_angle = MIN_ANGLE;
                }
                set_servo_angle(TILT_SERVO_PIN, tilt_angle);
                break;
            default:
                fprintf(stderr, "Invalid input. Press A, D, W, S, or q.\n");
                break;
        }
        usleep(100000); // 100ms delay
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio();

    return 0;
}

