// I2C initialization function
int init_i2c(int bus, int addr) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// SSD1306 initialization function
int ssd1306_init(int fd) {
    unsigned char init_commands[] = {
        0xAE,       // Display off
        0xD5, 0x80, // Clock divide ratio (0x80 = 100Hz)
        0xA8, 0x3F, // Multiplex ratio (63 = 64 rows)
        0xD3, 0x00, // Display offset
        0x40,       // Start line
        0x8D, 0x14, // Charge pump setting (0x14 = enable)
        0x20, 0x00, // Memory addressing mode (0x00 = horizontal)
        0xA1,       // Segment remap (A0 = normal, A1 = remapped)
        0xC8,       // COM output scan direction (C0 = normal, C8 = remapped)
        0xDA, 0x12, // COM pins hardware configuration
        0x81, 0xCF, // Contrast control
        0xD9, 0xF1, // Pre-charge period
        0xDB, 0x40, // VCOM deselect level
        0xA4,       // Entire display ON/OFF (A4 = normal, A5 = all ON)
        0xA6,       // Normal/Inverse display (A6 = normal, A7 = inverse)
        0xAF        // Display on
    };

    for (size_t i = 0; i < sizeof(init_commands); i++) {
        unsigned char buf[2] = {0x00, init_commands[i]};
        if (write(fd, buf, 2) != 2) {
            perror("Error writing to SSD1306");
            return -1;
        }
    }

    return 0;
}

// SSD1306 clear display function
int ssd1306_clear(int fd) {
    unsigned char buf[1025];
    buf[0] = 0x40; // Data command
    memset(buf + 1, 0x00, 1024);

    if (write(fd, buf, 1025) != 1025) {
        perror("Error clearing SSD1306");
        return -1;
    }

    return 0;
}

// SSD1306 display string function
int ssd1306_display_string(int fd, int x, int y, const char *str) {
    if (x < 0 || x + strlen(str) * FONT_WIDTH > SSD1306_WIDTH || y < 0 || y + FONT_HEIGHT > SSD1306_HEIGHT) {
        fprintf(stderr, "String out of bounds\n");
        return -1;
    }

    unsigned char buf[1 + FONT_WIDTH * strlen(str)];
    buf[0] = 0x40; // Data command

    for (size_t i = 0; i < strlen(str); i++) {
        char c = str[i];
        if (c < 32 || c > 126) c = 0; // Handle out-of-range characters
        c -= 32; // Adjust index to font array

        for (int j = 0; j < FONT_WIDTH; j++) {
            buf[1 + i * FONT_WIDTH + j] = font[c][j];
        }
    }

    // Set column and page address
    unsigned char col_cmd[3] = {0x21, x, x + strlen(str) * FONT_WIDTH - 1};
    unsigned char page_cmd[3] = {0x22, y / 8, (y + FONT_HEIGHT - 1) / 8};

    if (write(fd, col_cmd, 3) != 3 || write(fd, page_cmd, 3) != 3) {
        perror("Error setting column/page address");
        return -1;
    }

    if (write(fd, buf, 1 + FONT_WIDTH * strlen(str)) != 1 + FONT_WIDTH * strlen(str)) {
        perror("Error writing string to SSD1306");
        return -1;
    }

    return 0;
}

// Read CPU temperature from file
int read_cpu_temp(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening CPU temperature file");
        return -1;
    }

    int temp;
    if (fscanf(fp, "%d", &temp) != 1) {
        perror("Error reading CPU temperature");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temp;
}

// Read CPU usage from file
int read_cpu_usage(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening CPU usage file");
        return -1;
    }

    char line[256];
    int user = 0, nice = 0, system = 0, idle = 0, iowait = 0, irq = 0, softirq = 0, steal = 0, guest = 0, guest_nice = 0;

    if (fgets(line, sizeof(line), fp) == NULL) {
        perror("Error reading CPU usage file");
        fclose(fp);
        return -1;
    }

    if (sscanf(line, "cpu  %d %d %d %d %d %d %d %d %d %d", &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        perror("Error parsing CPU usage file");
        fclose(fp);
        return -1;
    }

    fclose(fp);

    // Calculate CPU usage percentage
    long long total_time = user + nice + system + idle + iowait + irq + softirq + steal + guest + guest_nice;
    long long idle_time = idle + iowait;
    long long usage = (total_time - idle_time) * 100 / total_time;

    return (int)usage;
}

// Display data on SSD1306
void display_data(int fd, int temp, int usage) {
    char temp_str[20];
    char usage_str[20];

    snprintf(temp_str, sizeof(temp_str), "Temp: %d C", temp);
    snprintf(usage_str, sizeof(usage_str), "Usage: %d%%", usage);

    ssd1306_clear(fd);
    ssd1306_display_string(fd, 0, 0, temp_str);
    ssd1306_display_string(fd, 0, 16, usage_str);
}

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        terminate = 1;
    }
}

// Cleanup function
void cleanup(int fd) {
    ssd1306_clear(fd);
    close(fd);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, SSD1306_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize SSD1306
    if (ssd1306_init(i2c_fd) < 0) {
        fprintf(stderr, "SSD1306 initialization failed. Exiting.\n");
        cleanup(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read CPU temperature and usage
        int temp = read_cpu_temp(CPU_TEMP_FILE);
        int usage = read_cpu_usage(CPU_STAT_FILE);

        if (temp == -1 || usage == -1) {
            fprintf(stderr, "Error reading CPU data. Displaying previous values.\n");
        } else {
            // Display data on SSD1306
            display_data(i2c_fd, temp, usage);
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup(i2c_fd);
    return 0;
}

