#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <wiringPiI2C.h>

// Define GPIO pins
#define FLOW_SENSOR_1 17
#define FLOW_SENSOR_2 18
#define FLOW_SENSOR_3 27

// Define I2C address for LCD
#define LCD_ADDR 0x27

// Define LCD dimensions
#define LCD_WIDTH 16
#define LCD_HEIGHT 2

// Define flow rate calibration factor (pulses/Liter)
#define FLOW_RATE_CALIBRATION 7.5

// Define LCD commands
#define LCD_CLEARDISPLAY 0x01
#define LCD_RETURNHOME 0x02
#define LCD_ENTRYMODESET 0x04
#define LCD_DISPLAYCONTROL 0x08
#define LCD_CURSORSHIFT 0x10
#define LCD_FUNCTIONSET 0x20

// Define LCD flags
#define LCD_ENTRYRIGHT 0x00
#define LCD_ENTRYLEFT 0x02
#define LCD_ENTRYSHIFTINCREMENT 0x01
#define LCD_ENTRYSHIFTDECREMENT 0x00

#define LCD_DISPLAYON 0x04
#define LCD_DISPLAYOFF 0x00
#define LCD_CURSORON 0x02
#define LCD_CURSOROFF 0x00
#define LCD_BLINKON 0x01
#define LCD_BLINKOFF 0x00

#define LCD_8BITMODE 0x10
#define LCD_4BITMODE 0x00
#define LCD_2LINE 0x08
#define LCD_1LINE 0x00
#define LCD_5x10DOTS 0x04
#define LCD_5x8DOTS 0x00

// Global variables
volatile int pulse_count_1 = 0;
volatile int pulse_count_2 = 0;
volatile int pulse_count_3 = 0;
double total_volume_1 = 0.0;
double total_volume_2 = 0.0;
double total_volume_3 = 0.0;
int lcd_fd;

// Function prototypes
void pulse_counter_1(int gpio, int level, uint32_t tick);
void pulse_counter_2(int gpio, int level, uint32_t tick);
void pulse_counter_3(int gpio, int level, uint32_t tick);
double calculate_flow_rate(int pulse_count);
void update_total_volume(double flow_rate, double *total_volume);
void log_data(double flow_rate_1, double flow_rate_2, double flow_rate_3, double total_volume_1, double total_volume_2, double total_volume_3);
void lcd_init();
void lcd_byte(int bits, int mode);
void lcd_string(const char *s);
void lcd_clear();
void lcd_home();
void lcd_set_cursor(int col, int row);
void lcd_display_data(double flow_rate_1, double flow_rate_2, double flow_rate_3, double total_volume_1, double total_volume_2, double total_volume_3);
void signal_handler(int signal);

// Pulse counter callback functions
void pulse_counter_1(int gpio, int level, uint32_t tick) {
    if (level == 1) { // Rising edge
        pulse_count_1++;
    }
}

void pulse_counter_2(int gpio, int level, uint32_t tick) {
    if (level == 1) { // Rising edge
        pulse_count_2++;
    }
}

void pulse_counter_3(int gpio, int level, uint32_t tick) {
    if (level == 1) { // Rising edge
        pulse_count_3++;
    }
}

// Function to calculate flow rate
double calculate_flow_rate(int pulse_count) {
    return (double)pulse_count / FLOW_RATE_CALIBRATION;
}

// Function to update total volume
void update_total_volume(double flow_rate, double *total_volume) {
    *total_volume += flow_rate;
}

// Function to log data to console
void log_data(double flow_rate_1, double flow_rate_2, double flow_rate_3, double total_volume_1, double total_volume_2, double total_volume_3) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Sensor 1: Flow Rate = %.2f L/min, Total Volume = %.2f L\n", timestamp, flow_rate_1, total_volume_1);
    printf("%s - Sensor 2: Flow Rate = %.2f L/min, Total Volume = %.2f L\n", timestamp, flow_rate_2, total_volume_2);
    printf("%s - Sensor 3: Flow Rate = %.2f L/min, Total Volume = %.2f L\n", timestamp, flow_rate_3, total_volume_3);
}

// LCD functions
void lcd_init() {
    // Initialize LCD in 4-bit mode
    gpioDelay(50); // Wait for more than 4.1ms after VCC rises to 2.7V
    lcd_byte(0x33, 0); // Initialize
    gpioDelay(5);  // Wait for more than 4.1ms
    lcd_byte(0x32, 0); // Initialize
    gpioDelay(1);  // Wait for more than 100us
    lcd_byte(0x28, 0); // 2 Line, 5x8 matrix
    gpioDelay(1);
    lcd_byte(0x0C, 0); // Display on, cursor off, blink off
    gpioDelay(1);
    lcd_byte(0x06, 0); // Increment cursor, no shift
    gpioDelay(1);
    lcd_byte(0x01, 0); // Clear display
    gpioDelay(2);
}

void lcd_byte(int bits, int mode) {
    // Send byte to data pins
    // bits = the data
    // mode = 1 for data, 0 for command

    int bits_high = mode | (bits & 0xF0) | LCD_BACKLIGHT;
    int bits_low = mode | ((bits << 4) & 0xF0) | LCD_BACKLIGHT;

    // High bits
    wiringPiI2CWriteReg8(lcd_fd, 0x00, bits_high);
    wiringPiI2CWriteReg8(lcd_fd, 0x00, bits_high | LCD_EN);
    gpioDelay(1); // Enable pulse must be > 300ns
    wiringPiI2CWriteReg8(lcd_fd, 0x00, bits_high & ~LCD_EN);
    gpioDelay(100);

    // Low bits
    wiringPiI2CWriteReg8(lcd_fd, 0x00, bits_low);
    wiringPiI2CWriteReg8(lcd_fd, 0x00, bits_low | LCD_EN);
    gpioDelay(1); // Enable pulse must be > 300ns
    wiringPiI2CWriteReg8(lcd_fd, 0x00, bits_low & ~LCD_EN);
    gpioDelay(100);
}

void lcd_string(const char *s) {
    while (*s) {
        lcd_byte(*s++, 1);
    }
}

void lcd_clear() {
    lcd_byte(LCD_CLEARDISPLAY, 0);
    gpioDelay(2); // This command requires a long execution time
}

void lcd_home() {
    lcd_byte(LCD_RETURNHOME, 0);
    gpioDelay(2); // This command requires a long execution time
}

void lcd_set_cursor(int col, int row) {
    int row_offsets[] = {0x00, 0x40};
    lcd_byte(LCD_SETDDRAMADDR | (col + row_offsets[row]), 0);
}

void lcd_display_data(double flow_rate_1, double flow_rate_2, double flow_rate_3, double total_volume_1, double total_volume_2, double total_volume_3) {
