#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <math.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>
#include <wiringPiI2C.h>

// Configuration
#define ANEMOMETER_PIN 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define LCD_I2C_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_HEIGHT 2
#define SAMPLE_WINDOW_MS 500
#define DIAGNOSTIC_INTERVAL_MS 1000

// Global variables
volatile int pulse_count = 0;
int lcd_fd;
FILE *log_file;
bool running = true;

// Function prototypes
void anemometer_interrupt(void);
int read_wind_direction(void);
float calculate_wind_speed(int pulses);
void lcd_init(int fd);
void lcd_clear(int fd);
void lcd_set_cursor(int fd, int row, int col);
void lcd_print(int fd, const char *str);
void display_wind_data(int fd, float speed, int direction);
void log_message(const char *message);
void signal_handler(int signal);

// Anemometer interrupt routine
void anemometer_interrupt(void) {
    pulse_count++;
}

// Function to read wind direction from MCP3008
int read_wind_direction(void) {
    unsigned char buffer[3];
    int adc_value;

    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | MCP3008_CHANNEL) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00;

    if (wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3) == -1) {
        log_message("SPI read failed");
        return -1; // Indicate error
    }

    adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];

    return adc_value;
}

// Function to calculate wind speed
float calculate_wind_speed(int pulses) {
    // Assuming 1.75 pulses per second per m/s
    // and a sample window of 500ms
    float pulses_per_second = (float)pulses / (SAMPLE_WINDOW_MS / 1000.0);
    float wind_speed = pulses_per_second / 1.75;
    return wind_speed;
}

// LCD functions (PCF8574 backpack)
void lcd_init(int fd) {
    // Initialization sequence (adjust based on your LCD)
    delay(50); // Wait for LCD to power up
    wiringPiI2CWriteReg8(fd, 0x00, 0x33); // Initialize
    delay(5);
    wiringPiI2CWriteReg8(fd, 0x00, 0x32); // Initialize
    delay(5);
    wiringPiI2CWriteReg8(fd, 0x00, 0x06); // Cursor move direction
    delay(5);
    wiringPiI2CWriteReg8(fd, 0x00, 0x0C); // Display on, cursor off, blink off
    delay(5);
    wiringPiI2CWriteReg8(fd, 0x00, 0x28); // Data length, number of lines, font size
    delay(5);
    wiringPiI2CWriteReg8(fd, 0x00, 0x01); // Clear display
    delay(5);
}

void lcd_clear(int fd) {
    wiringPiI2CWriteReg8(fd, 0x00, 0x01); // Clear display
    delay(5);
}

void lcd_set_cursor(int fd, int row, int col) {
    int addr;
    if (row == 0) {
        addr = 0x80 + col;
    } else {
        addr = 0xC0 + col;
    }
    wiringPiI2CWriteReg8(fd, 0x00, addr);
    delay(5);
}

void lcd_print(int fd, const char *str) {
    for (int i = 0; str[i] != '\0'; i++) {
        wiringPiI2CWriteReg8(fd, 0x40, str[i]); // Send data
        delay(5);
    }
}

// Function to display wind data on LCD
void display_wind_data(int fd, float speed, int direction) {
    char buffer[20];

    lcd_clear(fd);
    lcd_set_cursor(fd, 0, 0);
    snprintf(buffer, sizeof(buffer), "Speed: %.2f m/s", speed);
    lcd_print(fd, buffer);

    lcd_set_cursor(fd, 1, 0);
    snprintf(buffer, sizeof(buffer), "Dir: %d", direction);
    lcd_print(fd, buffer);
}

// Function to log messages to file
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
    fflush(log_file); // Ensure immediate write
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = false;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main(void) {
    // Initialize WiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "WiringPi initialization failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize SPI
    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) == -1) {
        fprintf(stderr, "SPI initialization failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    lcd_fd = wiringPiI2CSetup(LCD_I2C_ADDR);
    if (lcd_fd == -1) {
        fprintf(stderr, "I2C initialization failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize LCD
    lcd_init(lcd_fd);

    // Open log file
    log_file = fopen("wind_monitor.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up anemometer interrupt
    if (wiringPiISR(ANEMOMETER_PIN, INT_EDGE_RISING, anemometer_interrupt) < 0) {
        fprintf(stderr, "Unable to setup ISR: %s\n", strerror(errno));
        return 1;
    }

    time_t last_diagnostic_time = time(NULL);

    // Main loop
    while (running) {
        // Read wind direction
        int wind_direction = read_wind_direction();
        if (wind_direction == -1) {
            log_message("Failed to read wind direction");
        }

        // Calculate wind speed
        float wind_speed = calculate_wind_speed(pulse_count);

        // Display wind data
        display_wind_data(lcd_fd, wind_speed, wind_direction);

        // Reset pulse count
        pulse_count = 0;

        // Diagnostic logging
        time_t current_time = time(NULL);
        if (difftime(current_time, last_diagnostic_time) >= DIAGNOSTIC_INTERVAL_MS / 1000.0) {
            char diagnostic_message[200];
            snprintf(diagnostic_message, sizeof(diagnostic_message), "Wind Speed: %.2f m/s, Direction: %d, Pulses: %d", wind_speed, wind_direction, pulse_count);
            log_message(diagnostic_message);
            last_diagnostic_time = current_time;
        }

        delay(SAMPLE_WINDOW_MS);
    }

    // Cleanup
    lcd_clear(lcd_fd);
    fclose(log_file);

    return 0;
}

