        delay(5);
    }
}

// Function to display wind data on LCD
void display_wind_data(int fd, float speed, int direction) {
    char buffer[20];

    lcd_clear(fd);
    lcd_set_cursor(fd, 0, 0);
    snprintf(buffer, sizeof(buffer), "Speed: %.2f m/s", speed);
    lcd_print(fd, buffer);

    lcd_set_cursor(fd, 1, 0);
    snprintf(buffer, sizeof(buffer), "Dir: %d", direction);
    lcd_print(fd, buffer);
}

// Function to log messages to file
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
    fflush(log_file); // Ensure immediate write
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = false;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main(void) {
    // Initialize WiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "WiringPi initialization failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize SPI
    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) == -1) {
        fprintf(stderr, "SPI initialization failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    lcd_fd = wiringPiI2CSetup(LCD_I2C_ADDR);
    if (lcd_fd == -1) {
        fprintf(stderr, "I2C initialization failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize LCD
    lcd_init(lcd_fd);

    // Open log file
    log_file = fopen("wind_monitor.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up anemometer interrupt
    if (wiringPiISR(ANEMOMETER_PIN, INT_EDGE_RISING, anemometer_interrupt) < 0) {
        fprintf(stderr, "Unable to setup ISR: %s\n", strerror(errno));
        return 1;
    }

    time_t last_diagnostic_time = time(NULL);

    // Main loop
    while (running) {
        // Read wind direction
        int wind_direction = read_wind_direction();
        if (wind_direction == -1) {
            log_message("Failed to read wind direction");
        }

        // Calculate wind speed
        float wind_speed = calculate_wind_speed(pulse_count);

        // Display wind data
        display_wind_data(lcd_fd, wind_speed, wind_direction);

        // Reset pulse count
        pulse_count = 0;

        // Diagnostic logging
        time_t current_time = time(NULL);
        if (difftime(current_time, last_diagnostic_time) >= DIAGNOSTIC_INTERVAL_MS / 1000.0) {
            char diagnostic_message[200];
            snprintf(diagnostic_message, sizeof(diagnostic_message), "Wind Speed: %.2f m/s, Direction: %d, Pulses: %d", wind_speed, wind_direction, pulse_count);
            log_message(diagnostic_message);
            last_diagnostic_time = current_time;
        }

        delay(SAMPLE_WINDOW_MS);
    }

    // Cleanup
    lcd_clear(lcd_fd);
    fclose(log_file);

    return 0;
}

