#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <wiringPiI2C.h>

// Constants
#define SENSOR_PIN 17
#define LCD_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_CHR 1 // Mode - Sending data
#define LCD_CMD 0 // Mode - Sending command
#define LCD_LINE_1 0x80 // LCD RAM address for the 1st line
#define LCD_LINE_2 0xC0 // LCD RAM address for the 2nd line
#define LCD_BACKLIGHT 0x08  // On
#define ENABLE 0b00000100 // Enable bit

// Global variables
static volatile int pulse_count = 0;
static int lcd_fd;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
void pulse_counter(int gpio, int level, uint32_t tick, void *user);
float calculate_flow_rate(int pulses);
void lcd_init();
void lcd_byte(int bits, int mode);
void lcd_string(const char *s);
void lcd_clear();
void log_data(float flow_rate);
void signal_handler(int signal);

// Pulse counter callback function
void pulse_counter(int gpio, int level, uint32_t tick, void *user) {
    if (level == PI_HIGH) {
        pulse_count++;
    }
}

// Function to calculate flow rate in liters per minute
float calculate_flow_rate(int pulses) {
    // YF-S201: 450 pulses per liter
    return (float)pulses / 450.0 * 60.0;
}

// LCD initialization function
void lcd_init() {
    // Initialise display
    lcd_byte(0x33, LCD_CMD); // Initialise
    lcd_byte(0x32, LCD_CMD); // Initialise
    lcd_byte(0x06, LCD_CMD); // Cursor move direction
    lcd_byte(0x0C, LCD_CMD); // 0x0F = Display on, Cursor on, Blink on. 0x0C = Display on,Cursor off, Blink off.
    lcd_byte(0x28, LCD_CMD); // Data length, number of lines, font size
    lcd_byte(0x01, LCD_CMD); // Clear display
    gpioDelay(500);           // Delay for clear display
}

// Function to send data to the LCD
void lcd_byte(int bits, int mode) {
    // Send byte to data pins
    // bits = the data
    // mode = 1 for data, 0 for command

    int bits_high;
    int bits_low;

    // Use the upper nibble
    bits_high = mode | (bits & 0xF0) | LCD_BACKLIGHT;
    bits_low = mode | ((bits << 4) & 0xF0) | LCD_BACKLIGHT;

    // High bits
    wiringPiI2CWriteReg8(lcd_fd, 0, bits_high);
    wiringPiI2CWriteReg8(lcd_fd, 0, bits_high | ENABLE);
    gpioDelay(1); // Delay
    wiringPiI2CWriteReg8(lcd_fd, 0, bits_high & ~ENABLE);
    gpioDelay(100);

    // Low bits
    wiringPiI2CWriteReg8(lcd_fd, 0, bits_low);
    wiringPiI2CWriteReg8(lcd_fd, 0, bits_low | ENABLE);
    gpioDelay(1); // Delay
    wiringPiI2CWriteReg8(lcd_fd, 0, bits_low & ~ENABLE);
    gpioDelay(100);
}

// Function to send a string to the LCD
void lcd_string(const char *s) {
    while (*s) {
        lcd_byte(*s++, LCD_CHR);
    }
}

// Function to clear the LCD display
void lcd_clear() {
    lcd_byte(0x01, LCD_CMD);
    gpioDelay(500);
}

// Function to log data to a file
void log_data(float flow_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Flow Rate: %.2f L/min\n", timestamp, flow_rate);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as input
    gpioSetMode(SENSOR_PIN, PI_INPUT);

    // Set pull-up/down resistor (optional, adjust as needed)
    gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP);

    // Initialize wiringPi I2C
    lcd_fd = wiringPiI2CSetup(LCD_ADDR);
    if (lcd_fd == -1) {
        fprintf(stderr, "wiringPiI2CSetup failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize LCD
    lcd_init();

    // Open log file
    log_file = fopen("water_flow.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up alert function for pulse counting
    gpioSetAlertFuncEx(SENSOR_PIN, pulse_counter, NULL);

    printf("Water flow monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Reset pulse count
        pulse_count = 0;

        // Wait for 1 second
        gpioDelay(1000);

        // Calculate flow rate
        float flow_rate = calculate_flow_rate(pulse_count);

        // Display flow rate on LCD
        lcd_clear();
        lcd_string("Flow Rate:");
        lcd_byte(LCD_LINE_2, LCD_CMD); // Move cursor to the second line
        char flow_rate_str[20];
        snprintf(flow_rate_str, sizeof(flow_rate_str), "%.2f L/min", flow_rate);
        lcd_string(flow_rate_str);

        // Log data
        log_data(flow_rate);

        // Check for sensor absence
        if (pulse_count == 0) {
            fprintf(stderr, "Sensor absence detected!\n");
            lcd_clear();
            lcd_string("Sensor Absent!");
        }
    }

    // Clean up
    gpioSetAlertFuncEx(SENSOR_PIN, NULL, NULL); // Disable alert function
    fclose(log_file);
    gpioTerminate();

    printf("Water flow monitoring stopped.\n");

    return 0;
}

