#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for row and column control
const int row_pins[] = {17, 18, 27, 22, 23, 24, 25, 4};
const int col_pins[] = {5, 6, 12, 13, 19, 16, 26, 20};
const int num_rows = 8;
const int num_cols = 8;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    // Turn off all LEDs
    for (int i = 0; i < num_rows; i++) {
        gpioWrite(row_pins[i], 0);
    }
    for (int i = 0; i < num_cols; i++) {
        gpioWrite(col_pins[i], 1);
    }

    // Terminate pigpio
    gpioTerminate();
    exit(0);
}

// Function to set the state of a single LED
void set_led(int row, int col, int state) {
    if (row < 0 || row >= num_rows || col < 0 || col >= num_cols) {
        fprintf(stderr, "Error: Invalid LED coordinates (row=%d, col=%d)\n", row, col);
        return;
    }

    gpioWrite(row_pins[row], state);
    gpioWrite(col_pins[col], !state); // Common anode
}

// Function to clear the LED matrix
void clear_matrix() {
    for (int i = 0; i < num_rows; i++) {
        gpioWrite(row_pins[i], 0);
    }
    for (int i = 0; i < num_cols; i++) {
        gpioWrite(col_pins[i], 1);
    }
}

// Function to display a wave animation
void display_wave(int direction) {
    for (int i = 0; i < num_cols; i++) {
        clear_matrix();
        for (int j = 0; j < num_rows; j++) {
            if (direction == 1) { // Left to right
                set_led(j, (i + j) % num_cols, 1);
            } else { // Right to left
                set_led(j, (num_cols - 1 - i + j) % num_cols, 1);
            }
        }
        gpioDelay(800); // Delay for 800 microseconds
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as output
    for (int i = 0; i < num_rows; i++) {
        gpioSetMode(row_pins[i], PI_OUTPUT);
    }
    for (int i = 0; i < num_cols; i++) {
        gpioSetMode(col_pins[i], PI_OUTPUT);
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("LED matrix animation started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        display_wave(1); // Left to right
        display_wave(-1); // Right to left
    }

    return 0; // This line will never be reached due to the infinite loop
}

