#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for row anodes
#define ROW1 2
#define ROW2 3
#define ROW3 4
#define ROW4 17
#define ROW5 27
#define ROW6 22
#define ROW7 10
#define ROW8 9

// Define GPIO pins for column cathodes
#define COL1 14
#define COL2 15
#define COL3 18
#define COL4 23
#define COL5 24
#define COL6 25
#define COL7 8
#define COL8 7

// Define the wave pattern
const int wave_pattern[] = {
    0b00000001, // Column 1
    0b00000010, // Column 2
    0b00000100, // Column 3
    0b00001000, // Column 4
    0b00010000, // Column 5
    0b00100000, // Column 6
    0b01000000, // Column 7
    0b10000000  // Column 8
};

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, cleaning up and exiting...\n", signal);
}

// Function to set the state of a GPIO pin
int set_gpio(int pin, int state) {
    int result = gpioWrite(pin, state);
    if (result != 0) {
        fprintf(stderr, "Error writing to GPIO %d: %d\n", pin, result);
        return -1;
    }
    return 0;
}

// Function to clear the LED matrix
int clear_matrix() {
    // Set all column cathodes HIGH
    if (set_gpio(COL1, 1) != 0 || set_gpio(COL2, 1) != 0 ||
        set_gpio(COL3, 1) != 0 || set_gpio(COL4, 1) != 0 ||
        set_gpio(COL5, 1) != 0 || set_gpio(COL6, 1) != 0 ||
        set_gpio(COL7, 1) != 0 || set_gpio(COL8, 1) != 0) {
        return -1;
    }

    // Set all row anodes LOW
    if (set_gpio(ROW1, 0) != 0 || set_gpio(ROW2, 0) != 0 ||
        set_gpio(ROW3, 0) != 0 || set_gpio(ROW4, 0) != 0 ||
        set_gpio(ROW5, 0) != 0 || set_gpio(ROW6, 0) != 0 ||
        set_gpio(ROW7, 0) != 0 || set_gpio(ROW8, 0) != 0) {
        return -1;
    }
    return 0;
}

// Function to display a column of the wave pattern
int display_column(int column) {
    // Set the column cathode LOW
    int col_pin;
    switch (column) {
        case 0: col_pin = COL1; break;
        case 1: col_pin = COL2; break;
        case 2: col_pin = COL3; break;
        case 3: col_pin = COL4; break;
        case 4: col_pin = COL5; break;
        case 5: col_pin = COL6; break;
        case 6: col_pin = COL7; break;
        case 7: col_pin = COL8; break;
        default: return -1; // Invalid column number
    }

    if (set_gpio(col_pin, 0) != 0) {
        return -1;
    }

    // Light up the LEDs based on the wave pattern
    for (int i = 0; i < 8; i++) {
        int row_pin;
        switch (i) {
            case 0: row_pin = ROW1; break;
            case 1: row_pin = ROW2; break;
            case 2: row_pin = ROW3; break;
            case 3: row_pin = ROW4; break;
