#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define constants
#define I2C_BUS 1
#define MLX75031_ADDR 0x4A
#define DISTANCE_REG 0x00 // Example register address, check datasheet
#define SAMPLE_INTERVAL_MS 100
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor configuration
typedef struct {
    int i2c_bus;
    int i2c_address;
    int distance_register;
    int sample_interval_ms;
} sensor_config_t;

// Function prototypes
int initialize_sensor(int i2c_bus, int i2c_address);
int read_distance(int i2c_handle);
int log_data(FILE *fp, int distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the MLX75031 sensor
int initialize_sensor(int i2c_bus, int i2c_address) {
    i2c_handle = i2cOpen(i2c_bus, i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    printf("I2C bus opened successfully.\n");
    return 0;
}

// Function to read distance data from the MLX75031 sensor
int read_distance(int i2c_handle) {
    char buf[2];
    int distance = -1;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        int bytes_read = i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, buf, 2);
        if (bytes_read == 2) {
            // Combine the two bytes into a 16-bit distance value
            distance = (buf[0] << 8) | buf[1];
            break; // Success, exit retry loop
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", retries + 1, bytes_read);
            retries++;
            gpioDelay(10); // Small delay before retrying
        }
    }

    if (distance == -1) {
        fprintf(stderr, "Failed to read distance after %d retries.\n", MAX_RETRIES);
    }

    return distance;
}

// Function to log data to a CSV file
int log_data(FILE *fp, int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d\n", timestamp, distance) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Sensor configuration
    sensor_config_t config = {
        .i2c_bus = I2C_BUS,
        .i2c_address = MLX75031_ADDR,
        .distance_register = DISTANCE_REG,
        .sample_interval_ms = SAMPLE_INTERVAL_MS
    };

    // Initialize the sensor
    if (initialize_sensor(config.i2c_bus, config.i2c_address) != 0) {
        gpioTerminate();
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("depth_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Distance\n");
    }

    // Main loop
    while (!terminate) {
        int distance = read_distance(i2c_handle);

        if (distance != -1) {
            if (log_data(log_file, distance) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            // Log error to file
            if (log_data(log_file, -1) != 0) {
                fprintf(stderr, "Error logging error data.\n");
            }
        }

        gpioDelay(config.sample_interval_ms);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated successfully.\n");
    return 0;
}

