#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 400.0    // cm
#define TIMEOUT_US 30000       // 30 ms
#define TIMEOUT_HIGH_US 30000  // 30 ms
#define WATERING_THRESHOLD 15.0 // cm

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
void trigger_sensor();
long long get_echo_pulse_width();
float calculate_distance(long long pulse_width);
int log_distance(float distance);
void check_watering_threshold(float distance);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    int trigger_pin;
    int echo_pin;
    float speed_of_sound;
    float min_distance;
    float max_distance;
    int timeout_us;
    int timeout_high_us;
    float watering_threshold;
} sensor_config_t;

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    gpioWrite(TRIGGER_PIN, 0); // Ensure trigger is low initially
    gpioDelay(100);            // Allow sensor to settle

    return 0;
}

// Trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Measure the echo pulse width
long long get_echo_pulse_width() {
    long long start_tick = 0, end_tick = 0;

    // Wait for echo to go high with timeout
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= TIMEOUT_US) {
        return -1; // Timeout waiting for echo high
    }

    start_tick = gpioTick();

    // Wait for echo to go low with timeout
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_HIGH_US) {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= TIMEOUT_HIGH_US) {
        return -2; // Timeout waiting for echo low
    }

    end_tick = gpioTick();

    return end_tick - start_tick;
}

// Calculate the distance in centimeters
float calculate_distance(long long pulse_width) {
    if (pulse_width < 0) {
        return -1.0; // Indicate error
    }
    return (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 1000000.0 to convert us to s and by 2 for one-way distance
}

// Log the distance to a file
int log_distance(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        fprintf(log_file, "%s - ERROR: Distance out of range: %.2f cm\n", timestamp, distance);
        fflush(log_file);
        return 1; // Indicate error
    }

    fprintf(log_file, "%s - Distance: %.2f cm\n", timestamp, distance);
    fflush(log_file);
    return 0;
}

// Check if the distance is below the watering threshold
void check_watering_threshold(float distance) {
    if (distance < WATERING_THRESHOLD) {
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[80];

        time(&rawtime);
        timeinfo = gmtime(&rawtime); // Use gmtime for UTC

        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

        fprintf(log_file, "%s - Time to water the plant!\n", timestamp);
        fflush(log_file);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Ultrasonic sensor program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        trigger_sensor();
        long long pulse_width = get_echo_pulse_width();

        if (pulse_width < 0) {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];

            time(&rawtime);
            timeinfo = gmtime(&rawtime); // Use gmtime for UTC

            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

            if (pulse_width == -1) {
                fprintf(log_file, "%s - ERROR: Timeout waiting for echo high\n", timestamp);
            } else {
                fprintf(log_file, "%s - ERROR: Timeout waiting for echo low\n", timestamp);
            }
            fflush(log_file);
        } else {
            float distance = calculate_distance(pulse_width);

            if (distance > 0) {
                log_distance(distance);
                check_watering_threshold(distance);
            }
        }

        gpioDelay(60000); // Wait 60 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

