#define APDS9960_ID 0x92
#define APDS9960_STATUS 0x93
#define APDS9960_CDATAL 0x94
#define APDS9960_CDATAH 0x95
#define APDS9960_RDATAL 0x96
#define APDS9960_RDATAH 0x97
#define APDS9960_GDATAL 0x98
#define APDS9960_GDATAH 0x99
#define APDS9960_BDATAL 0x9A
#define APDS9960_BDATAH 0x9B
#define APDS9960_PDATA 0x9C

// Enable register values
#define APDS9960_PON 0b00000001
#define APDS9960_AEN 0b00000010
#define APDS9960_PEN 0b00000100
#define APDS9960_WEN 0b00001000

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t red;
    uint16_t green;
    uint16_t blue;
    uint8_t proximity;
} sensor_data_t;

// Function prototypes
int initialize_apds9960();
int read_sensor_data(sensor_data_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Function to initialize the APDS9960 sensor
int initialize_apds9960() {
    // Enable power and proximity sensor
    if (i2cWriteByteData(i2c_handle, APDS9960_ENABLE, APDS9960_PON | APDS9960_PEN) < 0) {
        fprintf(stderr, "Error enabling APDS9960\n");
        return -1;
    }

    // Set proximity gain
    if (i2cWriteByteData(i2c_handle, APDS9960_PPULSE, 0x87) < 0) {
        fprintf(stderr, "Error setting proximity pulse\n");
        return -1;
    }

    // Set proximity time
    if (i2cWriteByteData(i2c_handle, APDS9960_PTIME, 0xFF) < 0) {
        fprintf(stderr, "Error setting proximity time\n");
        return -1;
    }

    // Set ambient light integration time
    if (i2cWriteByteData(i2c_handle, APDS9960_ATIME, 0xD5) < 0) {
        fprintf(stderr, "Error setting ambient light time\n");
        return -1;
    }

    // Set wait time
    if (i2cWriteByteData(i2c_handle, APDS9960_WTIME, 0xFF) < 0) {
        fprintf(stderr, "Error setting wait time\n");
        return -1;
    }

    // Set proximity threshold
    if (i2cWriteByteData(i2c_handle, APDS9960_CONTROL, 0x03) < 0) {
        fprintf(stderr, "Error setting proximity threshold\n");
        return -1;
    }

    return 0;
}

// Function to read sensor data from the APDS9960
int read_sensor_data(sensor_data_t *data) {
    uint8_t buffer[8];

    // Read color and proximity data
    if (i2cReadI2CBlockData(i2c_handle, APDS9960_CDATAL, (char *)buffer, 8) < 0) {
        fprintf(stderr, "Error reading sensor data\n");
        return -1;
    }

    data->red = (buffer[1] << 8) | buffer[0];
    data->green = (buffer[3] << 8) | buffer[2];
    data->blue = (buffer[5] << 8) | buffer[4];
    data->proximity = buffer[6];

    return 0;
}

// Function to log data to a CSV file
int log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Get current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Write data to CSV file
    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, data.red, data.green, data.blue, data.proximity);
    fflush(log_file); // Ensure data is written immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, APDS9960_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize APDS9960 sensor
    if (initialize_apds9960() < 0) {
        fprintf(stderr, "APDS9960 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    log_file = fopen("color_proximity_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to CSV file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Red,Green,Blue,Proximity\n");
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Log data if proximity exceeds threshold
            if (sensor_data.proximity > 200) {
                log_data(sensor_data);
            }
        } else {
            fprintf(stderr, "Error reading sensor data, attempting to re-initialize...\n");
            i2cClose(i2c_handle);
            gpioDelay(100); // Wait before re-initializing
            i2c_handle = i2cOpen(1, APDS9960_I2C_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                terminate = 1; // Exit loop if re-initialization fails
            } else {
                if (initialize_apds9960() < 0) {
                    fprintf(stderr, "APDS9960 re-initialization failed\n");
                    terminate = 1; // Exit loop if re-initialization fails
                }
            }
        }

        gpioDelay(100); // Poll every 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

