#define BPM_THRESHOLD 50
#define BPM_HYSTERESIS 40

// Global variables
int i2c_fd;
FILE *csv_file;
volatile sig_atomic_t running = true;

// Function prototypes
int init_i2c();
int read_proximity_data();
float calculate_bpm(int proximity_value);
int write_to_csv(float bpm);
void signal_handler(int signal);
