    int bpm_hysteresis;
} config_t;

// Signal handler function
void signal_handler(int signal) {
    running = false;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_fd = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
