int read_proximity_data() {
    int proximity_value = i2cReadWordData(i2c_fd, PROX_DATA_REG);
    if (proximity_value < 0) {
        fprintf(stderr, "Error reading proximity data: %d\n", proximity_value);
        return -1;
    }
    return proximity_value;
}

// Calculate heart rate in beats per minute
float calculate_bpm(int proximity_value) {
    // Simple linear conversion (adjust as needed based on sensor characteristics)
    float bpm = (float)proximity_value * 0.1; // Example scaling
    return bpm;
}

// Write heart rate data to CSV file
int write_to_csv(float bpm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(csv_file, "%s,%.2f\n", timestamp, bpm);
    fflush(csv_file); // Ensure data is written immediately

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_fd >= 0) {
        i2cClose(i2c_fd);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open CSV file for writing
    csv_file = fopen("heartrate.csv", "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file!\n");
        cleanup();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int proximity_value;
    float bpm;
    int bpm_above_threshold = 0;

    // Main loop
    while (running) {
        proximity_value = read_proximity_data();
        if (proximity_value >= 0) {
            bpm = calculate_bpm(proximity_value);

            if (bpm > BPM_THRESHOLD) {
                bpm_above_threshold = 1;
            } else if (bpm < BPM_HYSTERESIS && bpm_above_threshold) {
                bpm_above_threshold = 0;
                write_to_csv(bpm);
            }
        } else {
            fprintf(stderr, "Error reading proximity data, skipping sample.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

