    if (result < 0) {
        fprintf(stderr, "Error triggering sensor: %d\n", result);
        return -1;
    }
    gpioDelay(TRIGGER_PULSE_US); // Wait for the trigger pulse
    return 0;
}

// Read the distance from the ultrasonic sensor
int read_distance(int handle) {
    int raw_distance = i2cReadWordData(handle, DISTANCE_REG);
    if (raw_distance < 0) {
        fprintf(stderr, "Error reading distance: %d\n", raw_distance);
        return -1;
    }
    return raw_distance;
}

// Convert raw distance to millimeters
float convert_to_mm(int raw_distance) {
    // Assuming a linear relationship between raw distance and mm
    // Adjust the scaling factor as needed based on the sensor's datasheet
    float distance_mm = (float)raw_distance * 0.1; // Example scaling

    // Clamp the distance to the defined range
    if (distance_mm < MIN_DISTANCE_MM) {
        distance_mm = MIN_DISTANCE_MM;
    } else if (distance_mm > MAX_DISTANCE_MM) {
        distance_mm = MAX_DISTANCE_MM;
    }

    return distance_mm;
}

