        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    printf("Starting distance measurement...\n");

    // Main loop
    while (!terminate) {
        // Trigger the sensor
        if (trigger_sensor(i2c_handle) != 0) {
            fprintf(stderr, "Error triggering sensor, skipping sample\n");
            gpioDelay(SAMPLE_INTERVAL_MS); // Wait before next sample
            continue;
        }

        // Read the distance
        int raw_distance = read_distance(i2c_handle);
        if (raw_distance < 0) {
            fprintf(stderr, "Error reading distance, skipping sample\n");
            gpioDelay(SAMPLE_INTERVAL_MS); // Wait before next sample
            continue;
        }

        // Convert to millimeters
        float distance_mm = convert_to_mm(raw_distance);

        // Log the data
        if (log_data(log_file, distance_mm) != 0) {
            fprintf(stderr, "Error logging data, skipping sample\n");
        }

        // Wait before next sample
        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup and exit
    cleanup();
    printf("Program terminated.\n");
    return 0;
}

