void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the sensor value from a given GPIO pin
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor on GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to log the sensor data to a file
void log_data(int sensor1_value, int sensor2_value) {
    FILE *fp = fopen("obstacle_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening obstacle_log.txt for writing!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%d,%d\n", timestamp, sensor1_value, sensor2_value);
    fclose(fp);
}

