#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define ICU20201_ADDR 0x68
#define WHO_AM_I_REG 0x0F
#define WHO_AM_I_VALUE 0x41
#define DISTANCE_REG_HIGH 0x58
#define DISTANCE_REG_LOW 0x59
#define LED_GPIO 17
#define DEFAULT_THRESHOLD 100 // mm
#define POLLING_INTERVAL_MS 50

// Global variables
int i2c_handle;
FILE *log_file;
int distance_threshold = DEFAULT_THRESHOLD;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_distance(int *distance);
void control_led(int on);
void log_data(int distance);
void signal_handler(int signal);
void cleanup();

// Structure for sensor configuration (optional)
typedef struct {
    int i2c_bus;
    int i2c_address;
    int led_pin;
    int distance_threshold;
} sensor_config_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the sensor
int initialize_sensor() {
    int who_am_i;

    // Verify WHO_AM_I register
    who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "WHO_AM_I check failed: 0x%02X (expected 0x%02X)\n", who_am_i, WHO_AM_I_VALUE);
        return -1;
    }

    printf("Sensor initialized successfully.\n");
    return 0;
}

// Read distance from the sensor
int read_distance(int *distance) {
    int high_byte, low_byte;

    high_byte = i2cReadByteData(i2c_handle, DISTANCE_REG_HIGH);
    if (high_byte < 0) {
        fprintf(stderr, "Error reading high byte: %d\n", high_byte);
        return -1;
    }

    low_byte = i2cReadByteData(i2c_handle, DISTANCE_REG_LOW);
    if (low_byte < 0) {
        fprintf(stderr, "Error reading low byte: %d\n", low_byte);
        return -1;
    }

    *distance = (high_byte << 8) | low_byte;
    return 0;
}

// Control the LED
void control_led(int on) {
    gpioWrite(LED_GPIO, on);
}

// Log data to file
void log_data(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Distance: %d mm\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioSetMode(LED_GPIO, PI_INPUT); // Set GPIO back to input
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int distance;

    // Parse command-line arguments
    if (argc > 1) {
        distance_threshold = atoi(argv[1]);
        printf("Using distance threshold: %d mm\n", distance_threshold);
    } else {
        printf("Using default distance threshold: %d mm\n", distance_threshold);
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, ICU20201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        cleanup();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("tof_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            log_data(distance);

            if (distance < distance_threshold) {
                control_led(1); // Turn on LED
            } else {
                control_led(0); // Turn off LED
            }
        } else {
            fprintf(stderr, "Error reading distance\n");
        }

        gpioDelay(POLLING_INTERVAL_MS * 1000); // Delay for 50ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

