#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MAX_DISTANCE 400.0    // Maximum measurable distance in cm
#define TIMEOUT_US 200000      // Timeout in microseconds (200ms)

// Global variables
volatile sig_atomic_t program_running = 1;

// Structure to hold echo start and end times
typedef struct {
    uint32_t start_time;
    uint32_t end_time;
} EchoTimes;

// Function prototypes
int initialize_gpio();
void trigger_sensor();
EchoTimes get_echo_times();
float calculate_distance(uint32_t pulse_duration);
void log_distance(float distance);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Ensure trigger is low initially
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(100); // Allow sensor to settle

    return 0; // Indicate success
}

// Trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Get echo start and end times
EchoTimes get_echo_times() {
    EchoTimes times;
    times.start_time = 0;
    times.end_time = 0;

    // Wait for echo to go high (rising edge)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every microsecond
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for rising edge\n");
        return times; // Return default values
    }

    times.start_time = gpioTick();

    // Wait for echo to go low (falling edge)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1);
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for falling edge\n");
        return times; // Return default values
    }

    times.end_time = gpioTick();

    return times;
}

// Calculate distance in centimeters
float calculate_distance(uint32_t pulse_duration) {
    if (pulse_duration <= 0 || pulse_duration > TIMEOUT_US) {
        fprintf(stderr, "Invalid pulse duration: %u us\n", pulse_duration);
        return -1.0; // Indicate error
    }

