// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MAX_DISTANCE 400.0    // Maximum measurable distance in cm
#define TIMEOUT_US 200000      // Timeout in microseconds (200ms)

// Global variables
volatile sig_atomic_t program_running = 1;

// Structure to hold echo start and end times
typedef struct {
    uint32_t start_time;
    uint32_t end_time;
} EchoTimes;

// Function prototypes
int initialize_gpio();
void trigger_sensor();
EchoTimes get_echo_times();
float calculate_distance(uint32_t pulse_duration);
void log_distance(float distance);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Ensure trigger is low initially
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(100); // Allow sensor to settle

    return 0; // Indicate success
}

// Trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

