#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <pigpio.h>

// Constants
#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 115200
#define MAGIC_WORD_LENGTH 8
#define RANGE_PROFILE_LENGTH 128
#define TARGET_THRESHOLD 1.0 // meters
#define ALERT_LED_GPIO 17
#define ALERT_DURATION_MS 2000
#define LOG_FILE "intrusion_log.csv"

// Global variables
volatile sig_atomic_t program_running = 1;
int uart_fd = -1;
FILE *log_file = NULL;

// Structure for configuration
typedef struct {
    char uart_device[20];
    int baud_rate;
    char magic_word[MAGIC_WORD_LENGTH];
    int range_profile_length;
    float target_threshold;
    int alert_led_gpio;
    int alert_duration_ms;
    char log_file[20];
} Config;

// Function prototypes
int initialize_uart(const char *device, int baud_rate);
int read_magic_word(int fd, const char *magic_word, int length);
int read_range_profile(int fd, short *range_profile, int length);
float calculate_distance(short range_bin);
int detect_intrusion(short *range_profile, int length, float threshold);
int log_intrusion(const char *timestamp, float distance);
void activate_alert(int gpio_pin, int duration_ms);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize UART
int initialize_uart(const char *device, int baud_rate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;     // 8-bit chars
    tty.c_iflag &= ~IGNBRK;         // disable break processing
    tty.c_lflag = 0;                // no signaling chars, no echo, no canonical processing
    tty.c_oflag = 0;                // no remapping, no delays
    tty.c_cc[VMIN] = 0;              // read doesn't block
    tty.c_cc[VTIME] = 5;             // 0.5 seconds read timeout

    tty.c_iflag &= ~(IXON | IXOFF | IXANY); // shut off xon/xoff ctrl

    tty.c_cflag |= (CLOCAL | CREAD);   // ignore modem controls, enable reading
    tty.c_cflag &= ~(PARENB | PARODD); // shut off parity
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    if (cfsetospeed(&tty, baud_rate) != 0 || cfsetispeed(&tty, baud_rate) != 0) {
        perror("Error setting baud rate");
        close(fd);
        return -1;
    }

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

// Read magic word from UART
int read_magic_word(int fd, const char *magic_word, int length) {
    char buffer[length];
    ssize_t bytes_read = read(fd, buffer, length);
    if (bytes_read != length) {
        fprintf(stderr, "Error reading magic word: expected %d bytes, got %zd\n", length, bytes_read);
        return -1;
    }
    if (memcmp(buffer, magic_word, length) != 0) {
        fprintf(stderr, "Error: Magic word mismatch. Expected: %s, Received: %s\n", magic_word, buffer);
        return -1;
    }
    return 0;
}

// Read range profile from UART
int read_range_profile(int fd, short *range_profile, int length) {
    ssize_t bytes_read = read(fd, range_profile, length * sizeof(short));
    if (bytes_read != length * sizeof(short)) {
        fprintf(stderr, "Error reading range profile: expected %d bytes, got %zd\n", length * sizeof(short), bytes_read);
        return -1;
    }
    return 0;
}

// Calculate distance from range bin (example formula, adjust as needed)
float calculate_distance(short range_bin) {
    // This is a placeholder.  The actual formula depends on the radar's
    // configuration and calibration.
    // Assuming range_bin is in units of mm.
    return (float)range_bin / 1000.0; // Convert mm to meters
}

// Detect intrusion based on range profile
int detect_intrusion(short *range_profile, int length, float threshold) {
    for (int i = 0; i < length; i++) {
        float distance = calculate_distance(range_profile[i]);
        if (distance <= threshold) {
            return 1; // Intrusion detected
        }
    }
    return 0; // No intrusion detected
}

// Log intrusion event to file
int log_intrusion(const char *timestamp, float distance) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Activate alert LED
void activate_alert(int gpio_pin, int duration_ms) {
    gpioWrite(gpio_pin, 1); // Turn LED on
    gpioDelay(duration_ms);
    gpioWrite(gpio_pin, 0); // Turn LED off
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (uart_fd != -1) {
        close(uart_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Configuration
    Config config = {
        .uart_device = UART_DEVICE,
        .baud_rate = BAUD_RATE,
        .magic_word = {0x02, 0x01, 0x04, 0x03, 0x06, 0x05, 0x08, 0x07},
        .range_profile_length = RANGE_PROFILE_LENGTH,
        .target_threshold = TARGET_THRESHOLD,
        .alert_led_gpio = ALERT_LED_GPIO,
        .alert_duration_ms = ALERT_DURATION_MS,
        .log_file = LOG_FILE
    };

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(config.alert_led_gpio, PI_OUTPUT);

    // Initialize UART
    uart_fd = initialize_uart(config.uart_device, config.baud_rate);
    if (uart_fd == -1) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(uart_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read magic word
        if (read_magic_word(uart_fd, config.magic_word, MAGIC_WORD_LENGTH) == 0) {
            // Read range profile
            short range_profile[config.range_profile_length];
            if (read_range_profile(uart_fd, range_profile, config.range_profile_length) == 0) {
                // Detect intrusion
                if (detect_intrusion(range_profile, config.range_profile_length, config.target_threshold)) {
                    // Get timestamp
                    time_t rawtime;
                    struct tm *timeinfo;
                    char timestamp[20];

                    time(&rawtime);
                    timeinfo = localtime(&rawtime);

                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

                    // Log intrusion
                    if (log_intrusion(timestamp, config.target_threshold) == 0) {
                        printf("Intrusion detected at %s! Distance: %.2f meters\n", timestamp, config.target_threshold);
                    } else {
                        fprintf(stderr, "Error logging intrusion.\n");
                    }

                    // Activate alert
                    activate_alert(config.alert_led_gpio, config.alert_duration_ms);
                }
            }
        } else {
            fprintf(stderr, "Error reading magic word. Sensor may be absent or bus error.\n");
            // Attempt to re-initialize UART
            close(uart_fd);
            uart_fd = initialize_uart(config.uart_device, config.baud_rate);
            if (uart_fd == -1) {
                fprintf(stderr, "Failed to re-initialize UART. Exiting.\n");
                program_running = 0; // Exit loop if re-initialization fails
            }
        }

        usleep(10000); // 10ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

