#include <pigpio.h>

// Define GPIO pins
#define SENSOR_PIN 17
#define BUZZER_PIN 18

// Define log file name
#define LOG_FILE "obstacle_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int read_sensor();
void control_buzzer(int state);
void log_event(int sensor_state);
void signal_handler(int signal);

// Function to read the sensor value
int read_sensor() {
    int sensor_value = gpioRead(SENSOR_PIN);
    if (sensor_value < 0) {
        fprintf(stderr, "Error reading sensor value: %d\n", sensor_value);
        return -1; // Indicate an error
    }
    return sensor_value;
}

// Function to control the buzzer
void control_buzzer(int state) {
    int result = gpioWrite(BUZZER_PIN, state);
    if (result < 0) {
        fprintf(stderr, "Error writing to buzzer: %d\n", result);
    }
}

// Function to log an event to the file
void log_event(int sensor_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Obstacle: %s\n", timestamp, sensor_state == 0 ? "Detected" : "Removed");
        fflush(log_file); // Ensure data is written to disk immediately
