int read_distance(float *distance) {
    // Example: Read two bytes from register 0x00 (replace with actual register address)
    char buffer[2];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, 0x00, buffer, 2);

    if (bytes_read != 2) {
        fprintf(stderr, "Error reading distance: %d\n", bytes_read);
        return -1;
    }

    // Convert the two bytes to a distance value (example conversion)
    int raw_distance = (buffer[0] << 8) | buffer[1];
    *distance = (float)raw_distance / 100.0; // Example scaling

    return 0;
}

// Function to log the distance to a file
int log_distance(float distance) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    fprintf(log_file, "%s, Distance: %.2f cm\n", timestamp, distance);
    fclose(log_file);
    return 0;
}

