#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Define constants
#define I2C_BUS 1
#define CH201_ADDR 0x70
#define LED_GPIO 18
#define DISTANCE_REG 0x00 // Example register address, check datasheet
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define BLINK_PERIOD_US 500000 // 0.5 seconds

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_distance(int *distance);
float calculate_frequency(int distance);
void control_led(float frequency);
void log_data(int distance, float frequency);
void signal_handler(int signal);
void cleanup();

// Structure for sensor configuration (example)
typedef struct {
    int i2c_bus;
    int i2c_address;
    int led_gpio;
} sensor_config_t;

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, CH201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read distance from the sensor
int read_distance(int *distance) {
    char buf[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        int bytes_read = i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, buf, 2);
        if (bytes_read == 2) {
            // Combine the two bytes into a 16-bit distance value
            *distance = (buf[0] << 8) | buf[1];
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (attempt %d): %d\n", retries + 1, bytes_read);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }

    fprintf(stderr, "Failed to read distance after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Calculate blink frequency based on distance
float calculate_frequency(int distance) {
    // Map distance (0-1000mm) to frequency (0-10Hz)
    if (distance < 0) distance = 0; // Ensure distance is not negative
    if (distance > 1000) distance = 1000; // Ensure distance is not too large

    float frequency = (float)distance / 1000.0 * 10.0;
    return frequency;
}

// Control the LED blinking frequency
void control_led(float frequency) {
    if (frequency <= 0) {
        gpioWrite(LED_GPIO, 0); // Turn off LED
        return;
    }

    // Calculate the half-period in microseconds
    int half_period_us = (int)(1000000.0 / frequency / 2.0);

    // Blink the LED
    gpioWrite(LED_GPIO, 1); // Turn on LED
    gpioDelay(half_period_us); // Delay for half the period
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioDelay(half_period_us); // Delay for half the period
}

// Log data to stdout
void log_data(int distance, float frequency) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s, Distance: %d mm, Frequency: %.2f Hz\n", timestamp, distance, frequency);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int distance;
    float frequency;

    // Main loop
    while (!terminate) {
        // Read distance from sensor
        if (read_distance(&distance) == 0) {
            // Calculate blink frequency
            frequency = calculate_frequency(distance);

            // Control LED
            control_led(frequency);

            // Log data
            log_data(distance, frequency);
        } else {
            fprintf(stderr, "Failed to read distance. Retrying...\n");
        }

        gpioDelay(100000); // Delay for 100ms (100000 microseconds)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

