#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define MLX75030_ADDR 0x4A
#define MEASURE_CMD 0x00 // Example command, check datasheet
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define SAMPLING_INTERVAL_MS 100
#define LOG_FILE "distance_log.csv"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for sensor configuration
typedef struct {
    int i2c_bus;
    int i2c_address;
    int measure_command;
    char *log_file;
} sensor_config_t;

// Function prototypes
int initialize_i2c(int bus, int addr);
int read_distance(int handle, int *distance);
int log_data(const char *filename, time_t timestamp, int distance);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// I2C initialization function
int initialize_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d: %d\n", bus, handle);
        return -1;
    }
    return handle;
}

// Function to read distance from the sensor
int read_distance(int handle, int *distance) {
    char buf[2];
    int result;

    // Send measurement command
    result = i2cWriteByteData(handle, MEASURE_CMD, 0); // Example: Send 0 as data
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Wait for measurement to complete (adjust delay as needed)
    gpioDelay(10000); // 10 ms

    // Read distance data
    result = i2cReadI2CBlockData(handle, 0, buf, 2); // Read 2 bytes
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Convert data to distance (example: assuming big-endian)
    *distance = (buf[0] << 8) | buf[1];

    return 0;
}

// Function to log data to a file
int log_data(const char *filename, time_t timestamp, int distance) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s\n", filename);
        return -1;
    }

    fprintf(fp, "%ld,%d\n", timestamp, distance);
    fclose(fp);
    return 0;
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    sensor_config_t config = {
        .i2c_bus = I2C_BUS,
        .i2c_address = MLX75030_ADDR,
        .measure_command = MEASURE_CMD,
        .log_file = LOG_FILE
    };

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_handle = initialize_i2c(config.i2c_bus, config.i2c_address);
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int distance;
        time_t timestamp = time(NULL);

        // Retry loop for reading distance
        int retry = 0;
        while (retry < RETRY_COUNT) {
            if (read_distance(i2c_handle, &distance) == 0) {
                break; // Success, exit retry loop
            } else {
                fprintf(stderr, "Retry %d failed, retrying in %d ms...\n", retry + 1, RETRY_DELAY_MS);
                gpioDelay(RETRY_DELAY_MS * 1000); // pigpioDelay takes microseconds
                retry++;
            }
        }

        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Failed to read distance after %d retries.\n", RETRY_COUNT);
        } else {
            // Log data
            if (log_data(config.log_file, timestamp, distance) != 0) {
                fprintf(stderr, "Failed to log data.\n");
            }
        }

        // Wait for the next sample
        gpioDelay(SAMPLING_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

