#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27
#define DEBOUNCE_TIME_MS 50
#define POLLING_INTERVAL_MS 10

static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold sensor state
typedef struct {
    int gpio;
    int last_state;
    unsigned long last_debounce_time;
} sensor_t;

sensor_t sensor1 = {SENSOR_1_GPIO, 1, 0}; // Initialize last_state to HIGH
sensor_t sensor2 = {SENSOR_2_GPIO, 1, 0};

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio);
int debounce(sensor_t *sensor);
int log_event(int sensor_id, const char *event_type);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);

    return 0;
}

// Function to read sensor value
int read_sensor(int gpio) {
    return gpioRead(gpio);
}

// Function to debounce sensor readings
int debounce(sensor_t *sensor) {
    int current_state = read_sensor(sensor->gpio);
    unsigned long now = gpioTick();

    if (current_state != sensor->last_state) {
        if (now - sensor->last_debounce_time > DEBOUNCE_TIME_MS * 1000) { // Convert ms to microseconds
            sensor->last_state = current_state;
            sensor->last_debounce_time = now;
            return current_state; // Return the debounced state
        }
    }
    return sensor->last_state; // Return the last known state
}

// Function to log events to file
int log_event(int sensor_id, const char *event_type) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Sensor %d, %s\n", timestamp, sensor_id, event_type);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return 1;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (log_file != NULL) {
        fclose(log_file);
        printf("Log file closed.\n");
    }
    gpioTerminate();
    printf("pigpio terminated.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("proximity_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int sensor1_state = debounce(&sensor1);
        int sensor2_state = debounce(&sensor2);

        if (sensor1_state == 0 && sensor1.last_state == 1) {
            log_event(1, "DETECTED");
        } else if (sensor1_state == 1 && sensor1.last_state == 0) {
            log_event(1, "CLEARED");
        }

        if (sensor2_state == 0 && sensor2.last_state == 1) {
            log_event(2, "DETECTED");
        } else if (sensor2_state == 1 && sensor2.last_state == 0) {
            log_event(2, "CLEARED");
        }

        gpioDelay(POLLING_INTERVAL_MS * 1000); // Convert ms to microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

