    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return 1;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (log_file != NULL) {
        fclose(log_file);
        printf("Log file closed.\n");
    }
    gpioTerminate();
    printf("pigpio terminated.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("proximity_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int sensor1_state = debounce(&sensor1);
        int sensor2_state = debounce(&sensor2);

        if (sensor1_state == 0 && sensor1.last_state == 1) {
            log_event(1, "DETECTED");
        } else if (sensor1_state == 1 && sensor1.last_state == 0) {
            log_event(1, "CLEARED");
        }

        if (sensor2_state == 0 && sensor2.last_state == 1) {
            log_event(2, "DETECTED");
        } else if (sensor2_state == 1 && sensor2.last_state == 0) {
            log_event(2, "CLEARED");
        }

        gpioDelay(POLLING_INTERVAL_MS * 1000); // Convert ms to microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

