#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define VL53L5CX_ADDR 0x29

// Define the number of zones
#define NUM_ZONES 64

// Define the register addresses (example, adjust based on datasheet)
#define VL53L5CX_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L5CX_REG_FIRMWARE_VERSION 0x00c2
#define VL53L5CX_REG_I2C_SLAVE_DEVICE_ADDRESS 0x008a
#define VL53L5CX_REG_ROI_CONFIG 0x001e
#define VL53L5CX_REG_START_STOP_MEASURE 0x0000
#define VL53L5CX_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L5CX_REG_RESULT_SPAD_NB 0x0022
#define VL53L5CX_REG_RESULT_DISTANCE 0x0050

// Global variables
int i2c_fd;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t distances[NUM_ZONES];
} sensor_data_t;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Function to write a byte to an I2C register
int write_register(int fd, uint16_t reg, uint8_t value) {
    uint8_t buf[3];
    buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    buf[1] = reg & 0xFF;      // LSB of register address
    buf[2] = value;

    if (write(fd, buf, 3) != 3) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a byte from an I2C register
int read_register(int fd, uint16_t reg, uint8_t *value) {
    uint8_t buf[2];
    buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    buf[1] = reg & 0xFF;      // LSB of register address

    if (write(fd, buf, 2) != 2) {
        perror("Failed to write register address for read");
        return -1;
    }

    if (read(fd, value, 1) != 1) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

// Function to initialize the VL53L5CX sensor
int init_sensor(int fd) {
    uint8_t model_id;

    // Check sensor ID
    if (read_register(fd, VL53L5CX_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Error reading model ID\n");
        return -1;
    }
    if (model_id != 0xEACC) {
        fprintf(stderr, "Incorrect model ID: 0x%02x\n", model_id);
        return -1;
    }

    // Set I2C slave address (optional, but good practice)
    if (write_register(fd, VL53L5CX_REG_I2C_SLAVE_DEVICE_ADDRESS, VL53L5CX_ADDR) != 0) {
        fprintf(stderr, "Error setting I2C slave address\n");
        return -1;
    }

    // Configure ROI (example: 8x8 grid)
    // This is a placeholder, refer to the VL53L5CX datasheet for the correct register settings
    if (write_register(fd, VL53L5CX_REG_ROI_CONFIG, 0x03) != 0) {
        fprintf(stderr, "Error configuring ROI\n");
        return -1;
    }

    printf("VL53L5CX sensor initialized successfully.\n");
    return 0;
}

// Function to read distance data from the sensor
int read_distance_data(int fd, sensor_data_t *data) {
    uint8_t range_status;
    uint8_t spad_nb;
    uint8_t distance_msb, distance_lsb;
    uint16_t distance;

    // Start a measurement
    if (write_register(fd, VL53L5CX_REG_START_STOP_MEASURE, 0x01) != 0) {
        fprintf(stderr, "Error starting measurement\n");
        return -1;
    }

    // Wait for measurement to complete (polling, adjust as needed)
    int timeout = 100; // Timeout after 100ms
    while (timeout > 0) {
        if (read_register(fd, VL53L5CX_REG_RESULT_RANGE_STATUS, &range_status) != 0) {
            fprintf(stderr, "Error reading range status\n");
            return -1;
        }
        if (range_status == 0x01) { // Example status, check datasheet
            break;
        }
        usleep(1000); // Wait 1ms
        timeout--;
    }

    if (timeout == 0) {
        fprintf(stderr, "Timeout waiting for measurement\n");
        return -1;
    }

    // Read distance data for each zone
    for (int i = 0; i < NUM_ZONES; i++) {
        // Read distance MSB
        if (read_register(fd, VL53L5CX_REG_RESULT_DISTANCE + (i * 2), &distance_msb) != 0) {
            fprintf(stderr, "Error reading distance MSB for zone %d\n", i);
            return -1;
        }

        // Read distance LSB
        if (read_register(fd, VL53L5CX_REG_RESULT_DISTANCE + (i * 2) + 1, &distance_lsb) != 0) {
            fprintf(stderr, "Error reading distance LSB for zone %d\n", i);
            return -1;
        }

        // Combine MSB and LSB to get the distance
        distance = (distance_msb << 8) | distance_lsb;
        data->distances[i] = distance;
    }

    return 0;
}

// Function to log the distance data to the console
void log_distance_data(const sensor_data_t *data) {
    printf("Zone Distances: ");
    for (int i = 0; i < NUM_ZONES; i++) {
        printf("%d ", data->distances[i]);
    }
    printf("\n");
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, VL53L5CX_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize the sensor
    if (init_sensor(i2c_fd) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read distance data
        if (read_distance_data(i2c_fd, &sensor_data) == 0) {
            // Log the data
            log_distance_data(&sensor_data);
        } else {
            fprintf(stderr, "Failed to read distance data\n");
        }

        // Wait 500ms
        usleep(500000);
    }

    // Close I2C bus
    close(i2c_fd);

    printf("Program terminated.\n");
    return 0;
}

