    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_handle, data, NUM_BYTES) == 0) {
            // Convert to distance
            distance = convert_to_distance(data, NUM_BYTES);

            if (distance >= 0) {
                // Get timestamp
                timestamp_ms = get_timestamp_ms();

                // Log distance
                log_distance(timestamp_ms, distance);
            } else {
                fprintf(stderr, "Error: Invalid distance reading\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read sensor data\n");
        }

        // Delay for 100 milliseconds
        gpioDelay(100000); // Delay in microseconds
    }

    // Close I2C device
    close_i2c_device(i2c_handle);

    // Terminate pigpio
    terminate_pigpio();

    return 0;
}

