#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// VL53L4CX I2C address
#define VL53L4CX_ADDR 0x29

// VL53L4CX register addresses (Example - Refer to datasheet for correct values)
#define VL53L4CX_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L4CX_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L4CX_REG_PRE_RANGE_CONFIG_TIMEOUT_MACROP_HI 0x0050
#define VL53L4CX_REG_FINAL_RANGE_CONFIG_TIMEOUT_MACROP_HI 0x0070
#define VL53L4CX_REG_SYSTEM_SEQUENCE_CONFIG 0x0081
#define VL53L4CX_REG_SYSRANGE_START 0x000
#define VL53L4CX_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L4CX_REG_RESULT_SPAD_NB 0x0022
#define VL53L4CX_REG_RESULT_DISTANCE 0x001E
#define VL53L4CX_REG_INTERRUPT_CLEAR 0x0086
#define VL53L4CX_REG_INTERRUPT_STATUS 0x0013

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor configuration
typedef struct {
    uint8_t pre_range_timeout;
    uint8_t final_range_timeout;
} sensor_config_t;

// Function prototypes
int init_vl53l4cx(int i2c_handle);
int read_distance(int i2c_handle, int *distance);
void log_distance(int distance);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

// Initialize the VL53L4CX sensor
int init_vl53l4cx(int i2c_handle) {
    int status;
    uint8_t model_id, revision_id;

    // Check sensor ID
    status = i2cReadI2CBlockData(i2c_handle, VL53L4CX_REG_IDENTIFICATION_MODEL_ID, (char *)&model_id, 1);
    if (status < 0) {
        fprintf(stderr, "Error reading model ID: %d\n", status);
        return -1;
    }

    status = i2cReadI2CBlockData(i2c_handle, VL53L4CX_REG_IDENTIFICATION_REVISION_ID, (char *)&revision_id, 1);
    if (status < 0) {
        fprintf(stderr, "Error reading revision ID: %d\n", status);
        return -1;
    }

    if (model_id != 0xEACC) {
        fprintf(stderr, "Incorrect model ID: 0x%02X\n", model_id);
        return -1;
    }

    printf("VL53L4CX sensor found, Model ID: 0x%02X, Revision ID: 0x%02X\n", model_id, revision_id);

    // Example configuration (Refer to datasheet for correct values)
    status = i2cWriteByteData(i2c_handle, VL53L4CX_REG_PRE_RANGE_CONFIG_TIMEOUT_MACROP_HI, 0x05); // Example value
    if (status < 0) {
        fprintf(stderr, "Error writing pre-range timeout: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, VL53L4CX_REG_FINAL_RANGE_CONFIG_TIMEOUT_MACROP_HI, 0x05); // Example value
    if (status < 0) {
        fprintf(stderr, "Error writing final range timeout: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, VL53L4CX_REG_SYSTEM_SEQUENCE_CONFIG, 0x01); // Example value
    if (status < 0) {
        fprintf(stderr, "Error writing system sequence config: %d\n", status);
        return -1;
    }

    return 0;
}

// Read distance from the VL53L4CX sensor
int read_distance(int i2c_handle, int *distance) {
    int status;
    uint8_t range_status;
    uint8_t spad_nb;
    uint16_t distance_mm;

    // Start a single measurement
    status = i2cWriteByteData(i2c_handle, VL53L4CX_REG_SYSRANGE_START, 0x01);
    if (status < 0) {
        fprintf(stderr, "Error starting measurement: %d\n", status);
        return -1;
    }

    // Wait for measurement to complete (polling interrupt status)
    int timeout = 100; // Timeout after 100ms
    while (timeout > 0) {
        status = i2cReadI2CBlockData(i2c_handle, VL53L4CX_REG_INTERRUPT_STATUS, (char *)&range_status, 1);
        if (status < 0) {
            fprintf(stderr, "Error reading interrupt status: %d\n", status);
            return -1;
        }

        if (range_status & 0x01) {
            break; // Measurement complete
        }
        gpioDelay(1000); // Wait 1ms
        timeout--;
    }

    if (timeout == 0) {
        fprintf(stderr, "Timeout waiting for measurement\n");
        return -1;
    }

    // Read range status
    status = i2cReadI2CBlockData(i2c_handle, VL53L4CX_REG_RESULT_RANGE_STATUS, (char *)&range_status, 1);
    if (status < 0) {
        fprintf(stderr, "Error reading range status: %d\n", status);
        return -1;
    }

    // Read SPAD count
    status = i2cReadI2CBlockData(i2c_handle, VL53L4CX_REG_RESULT_SPAD_NB, (char *)&spad_nb, 1);
    if (status < 0) {
        fprintf(stderr, "Error reading SPAD count: %d\n", status);
        return -1;
    }

    // Read distance
    status = i2cReadI2CBlockData(i2c_handle, VL53L4CX_REG_RESULT_DISTANCE, (char *)&distance_mm, 2);
    if (status < 0) {
        fprintf(stderr, "Error reading distance: %d\n", status);
        return -1;
    }

    // Clear interrupt
    status = i2cWriteByteData(i2c_handle, VL53L4CX_REG_INTERRUPT_CLEAR, 0x01);
    if (status < 0) {
        fprintf(stderr, "Error clearing interrupt: %d\n", status);
        return -1;
    }

    *distance = (int)distance_mm;
    return 0;
}

// Log the distance with a timestamp
void log_distance(int distance) {
    struct timespec ts;
    char timestamp[30];

    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        perror("clock_gettime");
        return;
    }

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%06ld", ts.tv_nsec / 1000);

    printf("Timestamp: %s, Distance: %d mm\n", timestamp, distance);
}

int main() {
    int distance;
    int status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, VL53L4CX_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L4CX sensor
    if (init_vl53l4cx(i2c_handle) != 0) {
        fprintf(stderr, "VL53L4CX initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        status = read_distance(i2c_handle, &distance);
        if (status == 0) {
            log_distance(distance);
        } else {
            fprintf(stderr, "Error reading distance\n");
        }

        gpioDelay(500000); // Wait 500ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

