#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 17

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 50000       // Timeout in microseconds (50ms)
#define MIN_DISTANCE 2.0      // Minimum measurable distance in cm
#define MAX_DISTANCE 400.0    // Maximum measurable distance in cm
#define MIN_ANGLE -90.0        // Minimum servo angle in degrees
#define MAX_ANGLE 90.0         // Maximum servo angle in degrees
#define LOG_FILE "sensor_data.log"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
double measure_distance();
int map_distance_to_angle(double distance);
void set_servo_angle(int angle);
void log_data(double distance, int angle);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to measure distance using HC-SR04 sensor
double measure_distance() {
    long long start_tick, end_tick, diff_tick;

    // Trigger the sensor
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    // Wait for echo to start
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo start timeout\n");
        return -1.0; // Timeout error
    }

    start_tick = gpioTick();

    // Wait for echo to end
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo end timeout\n");
        return -1.0; // Timeout error
    }

    end_tick = gpioTick();

    diff_tick = end_tick - start_tick;

    // Calculate distance in centimeters
    double distance = (double)diff_tick * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance

    return distance;
}

// Function to map distance to servo angle
int map_distance_to_angle(double distance) {
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        fprintf(stderr, "Error: Distance out of range (%.2f cm)\n", distance);
        return -1; // Indicate out-of-range error
    }

    // Linear mapping
    double angle = MIN_ANGLE + (distance - MIN_DISTANCE) * (MAX_ANGLE - MIN_ANGLE) / (MAX_DISTANCE - MIN_DISTANCE);

    return (int)angle;
}

// Function to set servo angle
void set_servo_angle(int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle out of range (%d degrees)\n", angle);
        return;
    }

    // Map angle to pulse width (SG90 servo)
    int pulse_width = 500 + (int)((angle + 90.0) * 2000.0 / 180.0); // Convert angle to pulse width (500-2500 us)

    gpioServo(SERVO_PIN, pulse_width);
}

// Function to log data to file
void log_data(double distance, int angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Distance: %.2f cm, Angle: %d degrees\n", timestamp, distance, angle);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Initialize trigger pin to low
    gpioWrite(TRIGGER_PIN, 0);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Parking assist system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        double distance = measure_distance();

        if (distance > 0) {
            int angle = map_distance_to_angle(distance);

            if (angle != -1) {
                set_servo_angle(angle);
                log_data(distance, angle);
            }
        }

        gpioDelay(200); // Delay 200 ms
    }

    // Cleanup
    gpioServo(SERVO_PIN, 0); // Stop servo
    fclose(log_file);
    gpioTerminate();

    printf("Parking assist system stopped.\n");

    return 0;
}

