#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <mqueue.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define BUZZER_GPIO 23
#define MESSAGE_QUEUE_NAME "/distance_queue"
#define MAX_DISTANCE 8191 // Maximum distance in mm (VL53L1X datasheet)
#define MIN_DISTANCE 0    // Minimum distance in mm
#define DISTANCE_THRESHOLD 100 // Distance threshold in mm
#define TIMEOUT_MS 1000 // Timeout for I2C read in milliseconds

// Global variables
int i2c_handle;
mqd_t mq;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_message_queue();
int init_gpio();
int read_distance(int *distance);
int log_distance(int distance);
void activate_buzzer(int activate);
void signal_handler(int signal);
void cleanup();

// VL53L1X register addresses (Example - adjust based on datasheet)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID  0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_PRE_RANGE_CONFIG_TIMEOUT_MACROP_HI 0x0050
#define VL53L1X_REG_FINAL_RANGE_CONFIG_TIMEOUT_MACROP_HI 0x0070
#define VL53L1X_REG_SYSRANGE_START 0x000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Function to write a byte to a VL53L1X register
int vl53l1x_write_byte(int handle, uint8_t reg, uint8_t value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to VL53L1X register 0x%02x: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a byte from a VL53L1X register
int vl53l1x_read_byte(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cWriteDevice(handle, &reg, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing register address for read 0x%02x: %d\n", reg, result);
        return -1;
    }
    result = i2cReadDevice(handle, value, 1);
    if (result != 0) {
        fprintf(stderr, "Error reading from VL53L1X register 0x%02x: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to initialize the VL53L1X sensor
int init_vl53l1x(int handle) {
    uint8_t model_id;

    // Check sensor ID
    if (vl53l1x_read_byte(handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Error reading VL53L1X model ID\n");
        return -1;
    }
    if (model_id != 0xEACC) {
        fprintf(stderr, "Incorrect VL53L1X model ID: 0x%02x\n", model_id);
        return -1;
    }

    // Configure timing budget (50ms)
    if (vl53l1x_write_byte(handle, VL53L1X_REG_PRE_RANGE_CONFIG_TIMEOUT_MACROP_HI, 0x00) != 0) return -1;
    if (vl53l1x_write_byte(handle, VL53L1X_REG_FINAL_RANGE_CONFIG_TIMEOUT_MACROP_HI, 0x00) != 0) return -1;

    return 0;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Initialize message queue
    if (init_message_queue() != 0) {
        fprintf(stderr, "Message queue initialisation failed\n");
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        fprintf(stderr, "GPIO initialisation failed\n");
        cleanup();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x(i2c_handle) != 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        cleanup();
        return 1;
    }

    int distance;

    // Main loop
    while (!terminate) {
        // Read distance
        if (read_distance(&distance) == 0) {
            // Log distance
            if (log_distance(distance) != 0) {
                fprintf(stderr, "Failed to log distance\n");
            }

            // Activate buzzer if distance is below threshold
            if (distance < DISTANCE_THRESHOLD) {
                activate_buzzer(1);
            } else {
                activate_buzzer(0);
            }
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }

        // Delay
        gpioDelay(50000); // 50ms
    }

    // Cleanup
    cleanup();

    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize message queue
int init_message_queue() {
    struct mq_attr attr;
    attr.mq_flags = 0;
    attr.mq_maxmsg = 10; // Maximum number of messages in the queue
    attr.mq_msgsize = sizeof(int); // Size of each message
    attr.mq_curmsgs = 0;

    mq = mq_open(MESSAGE_QUEUE_NAME, O_CREAT | O_WRONLY | O_NONBLOCK, 0644, &attr);
    if (mq == (mqd_t)-1) {
        fprintf(stderr, "Error opening message queue: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Initialize GPIO
int init_gpio() {
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is off initially
    return 0;
}

// Read distance from VL53L1X sensor
int read_distance(int *distance) {
    uint8_t range_status;
    uint8_t distance_msb, distance_lsb;
    int result;

    // Start a single measurement
    if (vl53l1x_write_byte(i2c_handle, VL53L1X_REG_SYSRANGE_START, 0x01) != 0) return -1;

    // Wait for measurement to complete (polling, but can be improved with interrupts)
    int timeout_count = 0;
    while (timeout_count < TIMEOUT_MS) {
        result = vl53l1x_read_byte(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS, &range_status);
        if (result != 0) return -1;
        if (range_status & 0x01) break; // Check if measurement is ready
        gpioDelay(1000); // Wait 1ms
        timeout_count++;
    }

    if (timeout_count >= TIMEOUT_MS) {
        fprintf(stderr, "Timeout waiting for measurement\n");
        return -1;
    }

    // Read distance data
    if (vl53l1x_read_byte(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, &distance_msb) != 0) return -1;
    if (vl53l1x_read_byte(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 + 1, &distance_lsb) != 0) return -1;

    *distance = (distance_msb << 8) | distance_lsb;

    // Validate distance
    if (*distance < MIN_DISTANCE || *distance > MAX_DISTANCE) {
        fprintf(stderr, "Invalid distance reading: %d\n", *distance);
        return -1;
    }

    return 0;
}

// Log distance to message queue
int log_distance(int distance) {
    if (mq_send(mq, (const char *)&distance, sizeof(int), 0) == -1) {
        fprintf(stderr, "Error sending message: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Activate buzzer
void activate_buzzer(int activate) {
    gpioWrite(BUZZER_GPIO, activate);
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    // Close I2C
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    // Close message queue
    if (mq != (mqd_t)-1) {
        mq_close(mq);
        mq_unlink(MESSAGE_QUEUE_NAME);
    }

    // Release GPIO resources
    gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is off
    gpioTerminate();
}

