#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define BUZZER_PIN 22

// Constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 50000       // Timeout in microseconds (50ms)
#define MIN_DISTANCE_CM 2.0   // Minimum measurable distance in cm
#define MAX_DISTANCE_CM 400.0  // Maximum measurable distance in cm
#define BUZZER_ON_TIME_MS 500  // Buzzer on time in milliseconds
#define BUZZER_OFF_TIME_MS 500 // Buzzer off time in milliseconds

// Global variables
volatile uint32_t start_tick = 0;
volatile uint32_t end_tick = 0;
volatile int echo_received = 0;
volatile int timeout_flag = 0;

// Function prototypes
void triggerSensor();
void echoCallback(int gpio, int level, uint32_t tick);
float calculateDistance(uint32_t pulse_width);
void controlBuzzer(float distance);
void signalHandler(int signal);

// Signal handler for Ctrl+C
void signalHandler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    gpioTerminate();          // Terminate pigpio
    exit(0);
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1); // Set trigger pin HIGH
    gpioDelay(10);             // Wait for 10 microseconds
    gpioWrite(TRIGGER_PIN, 0); // Set trigger pin LOW
}

// Callback function for echo pin
void echoCallback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        start_tick = tick;
        echo_received = 1; // Indicate that echo has started
        timeout_flag = 0; // Reset timeout flag
    } else if (level == 0 && echo_received) {
        end_tick = tick;
        echo_received = 0; // Indicate that echo has ended
    }
}

// Function to calculate distance in centimeters
float calculateDistance(uint32_t pulse_width) {
    float distance = (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
    return distance;
}

// Function to control the buzzer
void controlBuzzer(float distance) {
    if (distance < 30.0) {
        gpioWrite(BUZZER_PIN, 1); // Turn buzzer on
        gpioDelay(BUZZER_ON_TIME_MS);
        gpioWrite(BUZZER_PIN, 0); // Turn buzzer off
        gpioDelay(BUZZER_OFF_TIME_MS);
    } else {
        gpioWrite(BUZZER_PIN, 0); // Ensure buzzer is off
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    // Register callback function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echoCallback, NULL);

    printf("Parking sensor started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        triggerSensor(); // Trigger the sensor

        // Wait for echo or timeout
        int count = 0;
        while (!echo_received && !timeout_flag && count < 100) {
            gpioDelay(1000); // Check every 1 ms
            count++;
            if (count >= 100) {
                timeout_flag = 1;
            }
        }

        if (timeout_flag) {
            fprintf(stderr, "Timeout waiting for echo\n");
        } else if (!echo_received) {
            fprintf(stderr, "No echo received\n");
        } else {
            // Calculate pulse width
            uint32_t pulse_width = end_tick - start_tick;
            if (pulse_width > 0xFFFFFFFF) {
                pulse_width = 0xFFFFFFFF - start_tick + end_tick; // Handle tick wraparound
            }

            // Calculate distance
            float distance = calculateDistance(pulse_width);

            // Validate distance
            if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
                fprintf(stderr, "Invalid distance reading: %.2f cm\n", distance);
            } else {
                // Output distance
                printf("Distance: %.2f cm\n", distance);

                // Control buzzer
                controlBuzzer(distance);
            }
        }

        gpioDelay(100000); // Wait 100 milliseconds
    }

    return 0;
}

