            uint32_t pulse_width = end_tick - start_tick;
            if (pulse_width > 0xFFFFFFFF) {
                pulse_width = 0xFFFFFFFF - start_tick + end_tick; // Handle tick wraparound
            }

            // Calculate distance
            float distance = calculateDistance(pulse_width);

            // Validate distance
            if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
                fprintf(stderr, "Invalid distance reading: %.2f cm\n", distance);
            } else {
                // Output distance
                printf("Distance: %.2f cm\n", distance);

                // Control buzzer
                controlBuzzer(distance);
            }
        }

        gpioDelay(100000); // Wait 100 milliseconds
    }

    return 0;
}

