                servo_set_angle(CLOSE_ANGLE);
            }
        } else {
            log_event("VL53L1X sensor not present, closing gate");
            servo_set_angle(CLOSE_ANGLE);
        }

        delay(100); // Delay for 100ms
    }

    // Cleanup
    log_event("Cleaning up...");
    servo_set_angle(CLOSE_ANGLE); // Ensure gate is closed on exit
    fclose(log_file);
    close(i2c_fd);

    return 0;
}

