#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIG_PIN 23
#define ECHO_PIN 24

// Define constants
#define TRIG_PULSE_DURATION 10 // microseconds
#define SAMPLING_INTERVAL 200 // milliseconds
#define TIMEOUT_THRESHOLD 60 // milliseconds
#define MIN_PULSE_WIDTH 100 // microseconds
#define MAX_PULSE_WIDTH 30000 // microseconds
#define SPEED_OF_SOUND 34300 // cm/s

// Global variables
static volatile int rising_tick = 0;
static volatile int falling_tick = 0;
static volatile int valid_reading = 0;
static FILE *log_file = NULL;
static volatile int running = 1;

// Function prototypes
void trigger_sensor();
void echo_callback(int gpio, int level, uint32_t tick);
double calculate_distance(int pulse_width);
void log_distance(double distance);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure to hold sensor data
typedef struct {
    int rising_tick;
    int falling_tick;
    int valid_reading;
} sensor_data_t;

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(TRIG_PULSE_DURATION);
    gpioWrite(TRIG_PIN, 0);
}

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        rising_tick = tick;
    } else if (level == 0) {
        falling_tick = tick;
        valid_reading = 1;
    }
}

// Function to calculate distance in centimeters
double calculate_distance(int pulse_width) {
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Function to log distance to file
void log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, Distance: %.2f cm\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Initialization function
int initialize() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on ECHO pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Register callback function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Release GPIO resources
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Trigger the sensor
        trigger_sensor();

        // Wait for a valid reading or timeout
        int timeout_count = 0;
        while (!valid_reading && timeout_count < TIMEOUT_THRESHOLD) {
            gpioDelay(1); // Check every millisecond
            timeout_count++;
        }

        if (!valid_reading) {
            fprintf(stderr, "Timeout waiting for echo.\n");
            fprintf(log_file, "Timeout waiting for echo.\n");
            fflush(log_file);
        } else {
            // Calculate pulse width
            int pulse_width = falling_tick - rising_tick;

            // Handle tick wraparound
            if (pulse_width < 0) {
                pulse_width += 0xFFFFFFFF; // Add 2^32 to get the correct pulse width
            }

            // Validate pulse width
            if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
                fprintf(stderr, "Invalid pulse width: %d us\n", pulse_width);
                fprintf(log_file, "Invalid pulse width: %d us\n", pulse_width);
                fflush(log_file);
            } else {
                // Calculate distance
                double distance = calculate_distance(pulse_width);

                // Log distance
                log_distance(distance);

                printf("Distance: %.2f cm\n", distance);
            }
        }

        // Reset flags
        valid_reading = 0;

        // Wait for the next sampling interval
        gpioDelay(SAMPLING_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

