#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SHUTDOWN_PIN 23
#define INTERRUPT_PIN 24
#define SERVO_PIN 18
#define DISTANCE_THRESHOLD_OPEN 500 // mm
#define DISTANCE_THRESHOLD_CLOSE 600 // mm
#define SERVO_OPEN_PULSE_WIDTH 1500 // us
#define SERVO_CLOSE_PULSE_WIDTH 1000 // us
#define LOG_FILE "parking_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_vl53l1x();
int read_distance();
void set_servo_angle(int angle);
void open_gate();
void close_gate();
void log_event(const char *event, int distance);
void signal_handler(int signal);

// VL53L1X register addresses (Example - adjust based on datasheet)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_RANGING_MEASUREMENT_DATA 0x0014
#define VL53L1X_REG_I2C_SLAVE_DEVICE_ADDRESS 0x008A
#define VL53L1X_REG_SYSTEM_START 0x0000

// Function to write a byte to a VL53L1X register
int vl53l1x_write_byte(int handle, uint8_t reg, uint8_t value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to VL53L1X register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a byte from a VL53L1X register
int vl53l1x_read_byte(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cWriteDevice(handle, &reg, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing register address for read 0x%02X: %d\n", reg, result);
        return -1;
    }
    result = i2cReadDevice(handle, value, 1);
    if (result != 0) {
        fprintf(stderr, "Error reading from VL53L1X register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a word (2 bytes) from a VL53L1X register
int vl53l1x_read_word(int handle, uint8_t reg, uint16_t *value) {
    char buf[1];
    buf[0] = reg;
    int result = i2cWriteDevice(handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing register address for word read 0x%02X: %d\n", reg, result);
        return -1;
    }
    char data[2];
    result = i2cReadDevice(handle, data, 2);
    if (result != 0) {
        fprintf(stderr, "Error reading word from VL53L1X register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (data[0] << 8) | data[1];
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set servo pin to PWM mode
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(SERVO_PIN, 50); // 50 Hz
    gpioSetPWMrange(SERVO_PIN, 20000); // 20 ms period

    // Main loop
    int distance;
    int gate_open = 0; // 0 = closed, 1 = open

    while (program_running) {
        distance = read_distance();

        if (distance < 0) {
            fprintf(stderr, "Error reading distance\n");
        } else {
            printf("Distance: %d mm\n", distance);

            if (distance < DISTANCE_THRESHOLD_OPEN && !gate_open) {
                open_gate();
                gate_open = 1;
            } else if (distance > DISTANCE_THRESHOLD_CLOSE && gate_open) {
                close_gate();
                gate_open = 0;
            }
        }

        gpioDelay(100); // Delay 100 ms
    }

    // Cleanup
    close_gate(); // Ensure gate is closed on exit
    fclose(log_file);
    gpioTerminate();

    return 0;
}

int init_vl53l1x() {
    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }

    // Check VL53L1X model ID
    uint8_t model_id;
    if (vl53l1x_read_byte(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Error reading model ID\n");
        i2cClose(i2c_handle);
        return -1;
    }

    if (model_id != 0xEACC) {
        fprintf(stderr, "Incorrect model ID: 0x%02X\n", model_id);
        i2cClose(i2c_handle);
        return -1;
    }

    // Configure VL53L1X (Example - adjust based on datasheet)
    if (vl53l1x_write_byte(i2c_handle, 0x002D, 0x04) != 0) return -1; // set bit 2 to 1
    if (vl53l1x_write_byte(i2c_handle, 0x002E, 0x01) != 0) return -1; // set bit 0 to 1
    if (vl53l1x_write_byte(i2c_handle, 0x0088, 0x00) != 0) return -1; // set bit 0 to 0
    if (vl53l1x_write_byte(i2c_handle, 0x0080, 0x01) != 0) return -1; // set bit 0 to 1
    if (vl53l1x_write_byte(i2c_handle, 0x00FF, 0x01) != 0) return -1; // set bit 0 to 1
    if (vl53l1x_write_byte(i2c_handle, 0x0100, 0x00) != 0) return -1; // set bit 0 to 0
    if (vl53l1x_write_byte(i2c_handle, 0x0091, 0x3C) != 0) return -1; // set bit 0 to 1
    if (vl53l1x_write_byte(i2c_handle, 0x0000, 0x01) != 0) return -1; // set bit 0 to 1
    if (vl53l1x_write_byte(i2c_handle, 0x00FF, 0x00) != 0) return -1; // set bit 0 to 0
    if (vl53l1x_write_byte(i2c_handle, 0x0080, 0x00) != 0) return -1; // set bit 0 to 0

    return 0;
}

int read_distance() {
    uint16_t distance;
    if (vl53l1x_read_word(i2c_handle, VL53L1X_REG_RANGING_MEASUREMENT_DATA, &distance) != 0) {
        return -1;
    }
    return (int)distance;
}

void set_servo_angle(int angle) {
    // Map angle (0-180) to pulse width (1000-2000 us)
    int pulse_width = (int)(((float)angle / 180.0) * (SERVO_OPEN_PULSE_WIDTH - SERVO_CLOSE_PULSE_WIDTH) + SERVO_CLOSE_PULSE_WIDTH);
    gpioPWM(SERVO_PIN, pulse_width);
}

void open_gate() {
    set_servo_angle(180); // Open the gate
    log_event("Gate Opened", 0);
}

void close_gate() {
    set_servo_angle(0); // Close the gate
    log_event("Gate Closed", 0);
}

void log_event(const char *event, int distance) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s, Distance: %d mm\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, event, distance);
    fflush(log_file); // Ensure the log is written immediately
}

void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    program_running = 0;
}

