    printf("Caught signal %d, terminating...\n", signal);
}

// VL53L1X Initialization function
int init_vl53l1x() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SOFT_RESET, 0x01) < 0) {
        fprintf(stderr, "Error: Soft reset failed\n");
        return -1;
    }
    gpioDelay(10000); // Wait for reset to complete (10ms)

    // Set I2C address (optional, but good practice)
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_I2C_SLAVE_DEVICE_ADDRESS, VL53L1X_ADDR) < 0) {
        fprintf(stderr, "Error: Failed to set I2C address\n");
        return -1;
