    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() < 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed\n");
        cleanup();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(GATE_OPEN_PIN, PI_OUTPUT);
    gpioSetMode(GATE_CLOSE_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        cleanup();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Gate control system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int distance = read_distance();
        if (distance < 0) {
            fprintf(stderr, "Error: Failed to read distance\n");
            log_event("Error: Failed to read distance");
        } else {
            printf("Distance: %d mm\n", distance);

            if (distance < DISTANCE_THRESHOLD) {
                control_gate(1); // Open gate
            } else {
                control_gate(0); // Close gate
            }
        }

        gpioDelay(POLLING_INTERVAL_MS * 1000); // Delay for polling interval
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

