#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define MOTOR_FORWARD_PIN 17
#define MOTOR_BACKWARD_PIN 18
#define DISTANCE_THRESHOLD_FORWARD 100 // mm
#define DISTANCE_THRESHOLD_BACKWARD 300 // mm
#define GPIO_INTERRUPT_PIN 24
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// VL53L1X Register Addresses (Example - Refer to datasheet for complete list)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_PRE_RANGE_CONFIG_TIMEOUT_MACROP_HI 0x0050
#define VL53L1X_REG_FINAL_RANGE_CONFIG_TIMEOUT_MACROP_HI 0x0070
#define VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG 0x0081
#define VL53L1X_REG_SYSRANGE_START 0x000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// Global variables
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance(int *distance);
void motor_forward();
void motor_backward();
void motor_stop();
void gpio_isr_handler(int gpio, int level, uint32_t tick, void *user_data);
void signal_handler(int signal);
void log_message(const char *message);

// VL53L1X Initialization Sequence (Example - Refer to datasheet for complete sequence)
int vl53l1x_init() {
    int status;
    uint8_t model_id, revision_id;

    // Soft reset
    status = i2cWriteByteData(i2c_handle, 0x0000, 0x01); // Software reset command
    if (status < 0) {
        log_message("Error: VL53L1X soft reset failed.");
        return -1;
    }
    gpioDelay(1000); // Wait for reset to complete

    // Read model ID and revision ID
    status = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (status < 0) {
        log_message("Error: VL53L1X read model ID failed.");
        return -1;
    }
    model_id = (uint8_t)status;

    status = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_REVISION_ID);
    if (status < 0) {
        log_message("Error: VL53L1X read revision ID failed.");
        return -1;
    }
    revision_id = (uint8_t)status;

    printf("VL53L1X Model ID: 0x%02X, Revision ID: 0x%02X\n", model_id, revision_id);

    // Configure sensor (Example - Refer to datasheet for correct values)
    status = i2cWriteByteData(i2c_handle, VL53L1X_REG_PRE_RANGE_CONFIG_TIMEOUT_MACROP_HI, 0x05);
    if (status < 0) {
        log_message("Error: VL53L1X write pre-range config failed.");
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, VL53L1X_REG_FINAL_RANGE_CONFIG_TIMEOUT_MACROP_HI, 0x05);
    if (status < 0) {
        log_message("Error: VL53L1X write final range config failed.");
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG, 0x01); // Start ranging
    if (status < 0) {
        log_message("Error: VL53L1X write system sequence config failed.");
        return -1;
    }

    return 0;
}

// VL53L1X Distance Reading Function
int vl53l1x_read_distance(int *distance) {
    int status;
    uint8_t range_status;
    uint16_t distance_mm;

    // Start a single measurement
    status = i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSRANGE_START, 0x01);
    if (status < 0) {
        log_message("Error: VL53L1X start measurement failed.");
        return -1;
    }

    // Wait for data ready (polling with retry)
    int retries = 0;
    while (retries < MAX_RETRIES) {
        status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS);
        if (status < 0) {
            log_message("Error: VL53L1X read range status failed.");
            retries++;
            gpioDelay(RETRY_DELAY_MS * (1 << retries)); // Exponential backoff
            continue;
        }
        range_status = (uint8_t)status;

        if (range_status & 0x01) {
            break; // Data ready
        }
        retries++;
        gpioDelay(RETRY_DELAY_MS * (1 << retries)); // Exponential backoff
    }

    if (retries == MAX_RETRIES) {
        log_message("Error: VL53L1X data not ready after multiple retries.");
        return -1;
    }

    // Read distance
    status = i2cReadWordData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
    if (status < 0) {
        log_message("Error: VL53L1X read distance failed.");
        return -1;
    }
    distance_mm = (uint16_t)status;

    *distance = distance_mm;
    return 0;
}

// Motor Control Functions
void motor_forward() {
    gpioWrite(MOTOR_FORWARD_PIN, 1);
    gpioWrite(MOTOR_BACKWARD_PIN, 0);
    log_message("Motor: Forward");
}

void motor_backward() {
    gpioWrite(MOTOR_FORWARD_PIN, 0);
    gpioWrite(MOTOR_BACKWARD_PIN, 1);
    log_message("Motor: Backward");
}

void motor_stop() {
    gpioWrite(MOTOR_FORWARD_PIN, 0);
    gpioWrite(MOTOR_BACKWARD_PIN, 0);
    log_message("Motor: Stop");
}

// GPIO Interrupt Service Routine
void gpio_isr_handler(int gpio, int level, uint32_t tick, void *user_data) {
    int distance;

    if (level == 1) { // Rising edge
        if (vl53l1x_read_distance(&distance) == 0) {
            char message[100];
            snprintf(message, sizeof(message), "Distance: %d mm", distance);
            log_message(message);

            if (distance < DISTANCE_THRESHOLD_FORWARD) {
                motor_forward();
            } else if (distance > DISTANCE_THRESHOLD_BACKWARD) {
                motor_backward();
            } else {
                motor_stop();
            }
        } else {
            log_message("Error: Failed to read distance in ISR.");
            motor_stop(); // Stop the motor on error
        }
    }
}

// Signal Handler
void signal_handler(int signal) {
    program_running = 0;
    log_message("Signal received, stopping...");
}

// Logging Function
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init() != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_FORWARD_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_BACKWARD_PIN, PI_OUTPUT);
    gpioSetMode(GPIO_INTERRUPT_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_INTERRUPT_PIN, PI_PUD_UP); // Enable pull-up resistor

    // Set up interrupt handler
    if (gpioSetISRFuncEx(GPIO_INTERRUPT_PIN, RISING_EDGE, 0, gpio_isr_handler, NULL) != 0) {
        fprintf(stderr, "Error setting up interrupt handler\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_message("Program started");

    // Main loop
    while (program_running) {
        gpioDelay(100); // Sleep for 100ms
    }

    // Cleanup
    log_message("Cleaning up...");
    motor_stop(); // Stop the motor
    i2cClose(i2c_handle);
