#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define MPR121 I2C address
#define MPR121_ADDR 0x5A

// Define MPR121 registers
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_SOFTRESET 0x80

// Define GPIO pins for LEDs
#define LED_PIN_0 17
#define LED_PIN_1 18
#define LED_PIN_2 27
#define LED_PIN_3 22

// Define LED patterns
const uint8_t led_patterns[] = {
    0b0000, // 0
    0b0001, // 1
    0b0010, // 2
    0b0011, // 3
    0b0100, // 4
    0b0101, // 5
    0b0110, // 6
    0b0111, // 7
    0b1000, // 8
    0b1001, // 9
    0b1010, // A
    0b1011, // B
    0b1100, // C
    0b1101, // D
    0b1110, // E
    0b1111  // F
};

// Global variables
int i2c_fd;
FILE *log_file;
bool running = true;

// Function prototypes
int mpr121_init(int fd);
int mpr121_read_touch_status(int fd);
void set_led_pattern(uint8_t pattern);
void log_proximity_event(int electrode);
void signal_handler(int signal);

// Function to initialize the MPR121 sensor
int mpr121_init(int fd) {
    // Soft reset the sensor
    if (wiringPiI2CWriteReg8(fd, MPR121_SOFTRESET, 0x63) < 0) {
        fprintf(stderr, "Error: Failed to reset MPR121. Error code: %s\n", strerror(errno));
        return -1;
    }
    delay(100); // Wait for reset to complete

    // Configure electrode sensitivity and release thresholds
    // This is a simplified configuration. Refer to the MPR121 datasheet for more details.
    for (int i = 0; i < 12; i++) {
        if (wiringPiI2CWriteReg8(fd, 0x41 + (i * 2), 0x30) < 0) { // Touch threshold
            fprintf(stderr, "Error: Failed to write touch threshold for electrode %d. Error code: %s\n", i, strerror(errno));
            return -1;
        }
        if (wiringPiI2CWriteReg8(fd, 0x42 + (i * 2), 0x10) < 0) { // Release threshold
            fprintf(stderr, "Error: Failed to write release threshold for electrode %d. Error code: %s\n", i, strerror(errno));
            return -1;
        }
    }

    // Enable all electrodes
    if (wiringPiI2CWriteReg8(fd, MPR121_ELECTRODE_CONFIG, 0x0C) < 0) {
        fprintf(stderr, "Error: Failed to configure electrodes. Error code: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read the touch status from the MPR121 sensor
int mpr121_read_touch_status(int fd) {
    int touch_status_l = wiringPiI2CReadReg8(fd, MPR121_TOUCHSTATUS_L);
    if (touch_status_l < 0) {
        fprintf(stderr, "Error: Failed to read touch status low byte. Error code: %s\n", strerror(errno));
        return -1;
    }

    int touch_status_h = wiringPiI2CReadReg8(fd, MPR121_TOUCHSTATUS_H);
    if (touch_status_h < 0) {
        fprintf(stderr, "Error: Failed to read touch status high byte. Error code: %s\n", strerror(errno));
        return -1;
    }

    return (touch_status_h << 8) | touch_status_l;
}

// Function to set the LED pattern on the GPIO pins
void set_led_pattern(uint8_t pattern) {
    digitalWrite(LED_PIN_0, (pattern >> 0) & 1);
    digitalWrite(LED_PIN_1, (pattern >> 1) & 1);
    digitalWrite(LED_PIN_2, (pattern >> 2) & 1);
    digitalWrite(LED_PIN_3, (pattern >> 3) & 1);
}

// Function to log a proximity event to the console and file
void log_proximity_event(int electrode) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Proximity detected on electrode %d\n", timestamp, electrode);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Proximity detected on electrode %d\n", timestamp, electrode);
        fflush(log_file); // Ensure the log is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = false;
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error: Failed to initialize wiringPi. Error code: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C device
    i2c_fd = wiringPiI2CSetup(MPR121_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Error: Failed to initialize I2C communication. Error code: %s\n", strerror(errno));
        return 1;
    }

    // Initialize MPR121 sensor
    if (mpr121_init(i2c_fd) == -1) {
        fprintf(stderr, "Error: Failed to initialize MPR121 sensor.\n");
        close(i2c_fd);
        return 1;
    }

    // Configure GPIO pins as output
    pinMode(LED_PIN_0, OUTPUT);
    pinMode(LED_PIN_1, OUTPUT);
    pinMode(LED_PIN_2, OUTPUT);
    pinMode(LED_PIN_3, OUTPUT);

    // Open log file
    log_file = fopen("proximity_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file. Error code: %s\n", strerror(errno));
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Proximity-based interactive art installation started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int touch_status = mpr121_read_touch_status(i2c_fd);
        if (touch_status == -1) {
            fprintf(stderr, "Error: Failed to read touch status. Retrying...\n");
            delay(50); // Wait before retrying
            continue;
        }

        // Check each electrode for proximity
        for (int i = 0; i < 12; i++) {
            if (touch_status & (1 << i)) {
                // Proximity detected on electrode i
                set_led_pattern(led_patterns[i]);
                log_proximity_event(i);
                delay(50); // Debounce delay
            }
        }

        delay(50); // Polling interval
    }

    // Cleanup
    printf("Cleaning up resources...\n");
    set_led_pattern(0b0000); // Turn off LEDs
    if (log_file != NULL) {
        fclose(log_file);
    }
    close(i2c_fd);

    printf("Exiting.\n");
    return 0;
}

