// Constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define LED_GPIO 27
#define PROXIMITY_THRESHOLD 50 // Adjust as needed
#define DEBOUNCE_DELAY_MS 50

// MPR121 Registers
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ECR 0x5E
#define MPR121_CONFIG1 0x5B
#define MPR121_CONFIG2 0x5C
#define MPR121_FFI 0x41
#define MPR121_SFI 0x42
#define MPR121_ESI 0x43
#define MPR121_BASELINE_FILTER_CONFIG 0x5D

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init();
int read_touch_status(uint16_t *touch_status);
int is_proximity_detected(uint16_t touch_status);
void control_led(int on);
void log_proximity_event();
