void triggerSensor();
long pulseIn(int pin, int level, int timeout);
float calculateDistance(long pulse_width);
void logDistance(float distance);
void signalHandler(int signal);

// Signal handler function
void signalHandler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 0); // Ensure trigger is low
    gpioDelay(5);              // Wait 5 us
    gpioWrite(TRIGGER_PIN, 1); // Set trigger high
    gpioDelay(10);             // Wait 10 us
    gpioWrite(TRIGGER_PIN, 0); // Set trigger low
}

// Function to measure the pulse width on a GPIO pin
long pulseIn(int pin, int level, int timeout) {
    long start_tick = 0, end_tick = 0;

    // Wait for the pulse to start
    int count = 0;
    while (gpioRead(pin) != level) {
        if (count++ > timeout) {
            return -1; // Timeout
        }
        gpioDelay(1); // Small delay to prevent busy-waiting
    }
    start_tick = gpioTick();

    // Wait for the pulse to end
    count = 0;
    while (gpioRead(pin) == level) {
        if (count++ > timeout) {
            return -1; // Timeout
        }
        gpioDelay(1); // Small delay to prevent busy-waiting
    }
    end_tick = gpioTick();

    return end_tick - start_tick;
}

