#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define TRIG_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TRIG_PULSE_DURATION 10 // Trigger pulse duration in microseconds
#define MIN_PULSE_WIDTH 58      // Minimum pulse width in microseconds (1cm)
#define MAX_PULSE_WIDTH 25000   // Maximum pulse width in microseconds (4m)
#define LOG_FILE "distance_log.txt"

// Global variables
static volatile int echo_start_tick = 0;
static volatile int echo_end_tick = 0;
static volatile int pulse_width = 0;
static volatile int valid_pulse = 0;
static FILE *log_file = NULL;
static volatile int running = 1;

// Function prototypes
void trigger_sensor();
void echo_callback(int gpio, int level, uint32_t tick);
float calculate_distance(int pulse_width);
void log_distance(float distance);
void signal_handler(int signal);

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(TRIG_PULSE_DURATION);
    gpioWrite(TRIG_PIN, 0);
}

// Callback function for echo pin changes
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        echo_start_tick = tick;
        valid_pulse = 0; // Reset valid pulse flag on rising edge
    } else if (level == 0) {
        echo_end_tick = tick;

        // Calculate pulse width
        pulse_width = echo_end_tick - echo_start_tick;

        // Handle tick wrap-around
        if (pulse_width < 0) {
            pulse_width += 0xFFFFFFFF; // Add 2^32 to get the correct pulse width
        }

        // Validate pulse width
        if (pulse_width > MIN_PULSE_WIDTH && pulse_width < MAX_PULSE_WIDTH) {
            valid_pulse = 1;
        } else {
            valid_pulse = 0;
        }
    }
}

// Function to calculate distance in meters
float calculate_distance(int pulse_width) {
    return (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Function to log distance to file
void log_distance(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on ECHO pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt handler for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        trigger_sensor();
        gpioDelay(100); // Delay between measurements

        if (valid_pulse) {
