#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <syslog.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

// VL53L1X I2C address
#define VL53L1X_ADDR 0x29

// VL53L1X register addresses (Example - refer to datasheet for complete list)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID  0x010F
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x0110
#define VL53L1X_REG_PRE_RANGE_CONFIG_TIMEOUT_MACROP_HI 0x0050
#define VL53L1X_REG_FINAL_RANGE_CONFIG_TIMEOUT_MACROP_HI 0x0070
#define VL53L1X_REG_SYSRANGE_START 0x000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// GPIO pin for XSHUT
#define XSHUT_PIN 27

// I2C handle
int i2c_handle;

// Function prototypes
int init_vl53l1x();
int read_distance(int *distance);
void log_data(int distance, int status);
void signal_handler(int signal);

// Structure to hold sensor configuration
typedef struct {
    int i2c_address;
    int xshut_pin;
    int i2c_bus;
} sensor_config_t;

// Global configuration
sensor_config_t config = {
    .i2c_address = VL53L1X_ADDR,
    .xshut_pin = XSHUT_PIN,
    .i2c_bus = 1
};

int main() {
    // Initialize syslog
    openlog("vl53l1x_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set XSHUT pin as output
    gpioSetMode(config.xshut_pin, PI_OUTPUT);
    gpioWrite(config.xshut_pin, 1); // Set high to enable sensor

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        syslog(LOG_ERR, "VL53L1X initialisation failed");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Main loop
    int distance;
    while (1) {
        if (read_distance(&distance) == 0) {
            log_data(distance, 0); // Status 0 for success
        } else {
            log_data(-1, -1); // Log error
        }
        gpioDelay(100); // Delay 100ms
    }

    return 0;
}

// Initialize VL53L1X sensor
int init_vl53l1x() {
    // Open I2C device
    i2c_handle = i2cOpen(config.i2c_bus, config.i2c_address, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %d", i2c_handle);
        return -1;
    }

    // Check sensor ID (Example - refer to datasheet for correct value)
    int model_id = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (model_id < 0) {
        syslog(LOG_ERR, "Failed to read model ID: %d", model_id);
        i2cClose(i2c_handle);
        return -1;
    }
    if (model_id != 0xEACC) {
        syslog(LOG_ERR, "Incorrect model ID: 0x%04X", model_id);
        i2cClose(i2c_handle);
        return -1;
    }

    // Configure sensor (Example - refer to datasheet for correct values)
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_PRE_RANGE_CONFIG_TIMEOUT_MACROP_HI, 0x05) < 0) {
        syslog(LOG_ERR, "Failed to write pre-range config");
        i2cClose(i2c_handle);
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_FINAL_RANGE_CONFIG_TIMEOUT_MACROP_HI, 0x05) < 0) {
        syslog(LOG_ERR, "Failed to write final range config");
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Read distance from VL53L1X sensor
int read_distance(int *distance) {
    // Start a single measurement
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSRANGE_START, 0x01) < 0) {
        syslog(LOG_ERR, "Failed to start measurement");
        return -1;
    }

    // Wait for measurement to complete (adjust timeout as needed)
    gpioDelay(10); // Wait 10ms

    // Read range status
    int range_status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS);
    if (range_status < 0) {
        syslog(LOG_ERR, "Failed to read range status");
        return -1;
    }

    // Read distance
    int distance_raw = i2cReadWordData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
    if (distance_raw < 0) {
        syslog(LOG_ERR, "Failed to read distance");
        return -1;
    }

    *distance = distance_raw;
    return 0;
}

// Log data to syslog
void log_data(int distance, int status) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    if (status == 0) {
        syslog(LOG_INFO, "%s Distance: %d mm", timestamp, distance);
    } else {
        syslog(LOG_ERR, "%s Error reading sensor", timestamp);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Received signal %d, shutting down...", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    closelog();
    exit(0);
}

