    if (init_vl53l1x() != 0) {
        log_message("VL53L1X initialization failed.");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set GPIO24 as output
    gpioSetMode(GATE_GPIO, PI_OUTPUT);
    gpioWrite(GATE_GPIO, 0); // Initialize gate to CLOSED state
    log_message("Gate initialized to CLOSED.");

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int distance = read_distance();
        if (distance >= 0) {
            char message[50];
            snprintf(message, sizeof(message), "Distance: %d mm", distance);
            log_message(message);

            if (distance < DISTANCE_THRESHOLD) {
                control_gate(1); // Open gate
            } else {
                control_gate(0); // Close gate
            }
        } else {
            log_message("Error reading distance.");
        }

        gpioDelay(POLLING_INTERVAL_MS * 1000); // Delay for 100 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    log_message("Program terminated.");
    return 0;
}

