#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 30000       // 30 ms timeout
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 400.0    // cm
#define SERVO_MIN_PULSE_WIDTH 500 // us
#define SERVO_MAX_PULSE_WIDTH 2500 // us
#define SERVO_CENTER_PULSE_WIDTH 1500 // us
#define SERVO_RANGE 180.0
#define TRIGGER_PULSE_WIDTH 10 // us
#define TRIGGER_INTERVAL_MS 100

// Global variables
static volatile int pulse_width = 0;
static volatile int new_pulse = 0;
static volatile sig_atomic_t terminate = 0;
static FILE *log_file = NULL;

// Function prototypes
void trigger_sensor();
void echo_callback(int gpio, int level, uint32_t tick);
float calculate_distance(int pulse_width);
float moving_average(float new_value, float *history, int history_size, int *index);
void set_servo_angle(float angle);
void log_data(float distance, float angle);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure to hold program state
typedef struct {
    float distance_history[5];
    int history_index;
} ProgramState;

ProgramState state = {{0.0}, 0};

// Function to initialize the program
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set PWM frequency (adjust as needed)
    gpioSetPWMfrequency(SERVO_PIN, 50); // 50 Hz

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open log file
    log_file = fopen("distance_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,Distance (cm),Angle (degrees)\n");
    fflush(log_file);

    return 0;
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_WIDTH);
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
    static uint32_t start_tick = 0;

    if (level == 1) {
        start_tick = tick;
    } else if (level == 0) {
        uint32_t end_tick = tick;
        uint32_t diff = end_tick - start_tick;

        if (diff > TIMEOUT_US) {
            pulse_width = 0; // Timeout
        } else {
            pulse_width = diff;
        }
        new_pulse = 1;
    }
}

// Function to calculate distance from pulse width
float calculate_distance(int pulse_width) {
    if (pulse_width == 0) {
        return -1.0; // Timeout or invalid pulse width
    }
    return (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Convert us to s and divide by 2
}

// Function to calculate moving average
float moving_average(float new_value, float *history, int history_size, int *index) {
    history[*index] = new_value;
    *index = (*index + 1) % history_size;

    float sum = 0.0;
    for (int i = 0; i < history_size; i++) {
        sum += history[i];
    }
    return sum / history_size;
}

// Function to set servo angle
void set_servo_angle(float angle) {
    if (angle < 0.0) angle = 0.0;
    if (angle > SERVO_RANGE) angle = SERVO_RANGE;

    float pulse_width = SERVO_MIN_PULSE_WIDTH + (angle / SERVO_RANGE) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH);
    gpioServo(SERVO_PIN, (int)pulse_width);
}

// Function to log data to file
void log_data(float distance, float angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, distance, angle);
    fflush(log_file);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Ctrl+C pressed. Exiting...\n");
}

// Function to cleanup resources
void cleanup() {
    // Stop servo
    set_servo_angle(0.0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    if (initialize()) {
        return 1;
    }

    // Register alert function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    time_t last_trigger_time = 0;

    while (!terminate) {
        time_t current_time = time(NULL);

        // Trigger sensor every 100 ms
        if (difftime(current_time, last_trigger_time) >= 0.1) {
            trigger_sensor();
            last_trigger_time = current_time;
        }

        // Read pulse width and calculate distance
        if (new_pulse) {
            float distance = calculate_distance(pulse_width);
            new_pulse = 0;

            // Filter invalid readings
            if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
                distance = -1.0;
            }

            // Calculate moving average
            float filtered_distance = moving_average(distance, state.distance_history, 5, &state.history_index);

            // Calculate servo angle
            float angle = 0.0;
            if (filtered_distance > 0) {
                angle = (filtered_distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE) * SERVO_RANGE;
            } else {
                angle = SERVO_CENTER_PULSE_WIDTH;
            }

            // Set servo angle
            set_servo_angle(angle);

            // Log data
            log_data(filtered_distance, angle);
        }

        gpioDelay(10); // Small delay to prevent busy-waiting
    }

    cleanup();
    return 0;
}

