#define REG_INT_CFG 0x03
#define REG_IRQ_ENABLE 0x04
#define REG_MEAS_RATE0 0x08
#define REG_MEAS_RATE1 0x09
#define REG_PS_LED21_SELECT 0x0F
#define REG_PS_ENCODING 0x10
#define REG_PS1_ADCMUX 0x18
#define REG_PS_ADC_GAIN 0x1B
#define REG_PS_ADC_MISC 0x1C

// Global Variables
static int i2c_handle;
static int threshold = DEFAULT_THRESHOLD;
static int i2c_address = DEFAULT_I2C_ADDRESS;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function Prototypes
int initialize_sensor();
int read_proximity();
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data);
void log_data(int proximity_value, const char *status);
void signal_handler(int signal);
void cleanup();

// Function to initialize the Si1102 sensor
int initialize_sensor() {
    // Reset the device
    if (i2cWriteByteData(i2c_handle, REG_MEAS_RATE0, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to reset Si1102 (REG_MEAS_RATE0)\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset

    // Configure the sensor for proximity sensing
    if (i2cWriteByteData(i2c_handle, REG_PS_LED21_SELECT, 0x03) < 0) {
        fprintf(stderr, "Error: Failed to configure PS_LED21_SELECT\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, REG_PS_ENCODING, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to configure PS_ENCODING\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, REG_PS1_ADCMUX, 0x07) < 0) {
        fprintf(stderr, "Error: Failed to configure PS1_ADCMUX\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, REG_PS_ADC_GAIN, 0x40) < 0) {
        fprintf(stderr, "Error: Failed to configure PS_ADC_GAIN\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, REG_PS_ADC_MISC, 0x20) < 0) {
        fprintf(stderr, "Error: Failed to configure PS_ADC_MISC\n");
        return -1;
    }

    // Enable proximity interrupt
    if (i2cWriteByteData(i2c_handle, REG_INT_CFG, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to configure INT_CFG\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, REG_IRQ_ENABLE, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to configure IRQ_ENABLE\n");
        return -1;
    }

    // Set measurement rate
    if (i2cWriteByteData(i2c_handle, REG_MEAS_RATE0, 0x0A) < 0) {
        fprintf(stderr, "Error: Failed to configure MEAS_RATE0\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, REG_MEAS_RATE1, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to configure MEAS_RATE1\n");
        return -1;
    }

    return 0;
}

// Function to read the proximity value from the Si1102 sensor
int read_proximity() {
    int proximity_value;
    int retries = 3;

    while (retries > 0) {
        proximity_value = i2cReadWordData(i2c_handle, REG_PS1_DATA0);
        if (proximity_value >= 0) {
            return proximity_value;
        } else {
            fprintf(stderr, "Error: Failed to read proximity data (attempt %d): %s\n", 4 - retries, strerror(errno));
            gpioDelay(10); // Small delay before retrying
            retries--;
        }
    }

    fprintf(stderr, "Error: Failed to read proximity data after multiple retries.\n");
    return -1; // Indicate failure
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; // unused
    (void)level; // unused
    (void)tick; // unused
    (void)user_data; // unused

    int proximity_value = read_proximity();
    if (proximity_value >= 0) {
        const char *status = (proximity_value <= threshold) ? "SAFE" : "ALERT";
        log_data(proximity_value, status);
    }
}

// Function to log data to the log file
void log_data(int proximity_value, const char *status) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    pthread_mutex_lock(&log_mutex);
    if (log_file != NULL) {
        fprintf(log_file, "%s, %d, %s\n", timestamp, proximity_value, status);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
    pthread_mutex_unlock(&log_mutex);
}

// Signal handler function
void signal_handler(int signal) {
    (void)signal; // unused
    terminate = 1;
    printf("Received signal, terminating...\n");
}

// Cleanup function to close resources
void cleanup() {
    printf("Cleaning up...\n");

    // Disable interrupt
    gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, NULL, NULL);

    // Close I2C device
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    pthread_mutex_destroy(&log_mutex);

    printf("Cleanup complete.\n");
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 0); // Allow hex or decimal
                break;
            case 't':
                threshold = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-a <i2c_address>] [-t <threshold>]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, i2c_address, 0); // Bus 1, address, flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Error: Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Set interrupt handler
    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error: Could not set interrupt handler\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        gpioDelay(100); // Sleep for 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

