#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 200.0    // cm
#define MIN_FREQUENCY 200.0   // Hz
#define MAX_FREQUENCY 2000.0  // Hz
#define TIMEOUT_US 200000      // 200 ms in microseconds

// Global variables
volatile sig_atomic_t terminate = 0;
double current_frequency = 0.0;

// Function prototypes
void triggerSensor();
double measureDistance();
double mapDistanceToFrequency(double distance);
void setPWMFrequency(double frequency);
void signalHandler(int signal);

// Signal handler function
void signalHandler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioPWM(PWM_PIN, 0); // Stop PWM
    gpioTerminate();       // Terminate pigpio
    exit(0);
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the distance using the ultrasonic sensor
double measureDistance() {
    long long start_tick, end_tick, diff_tick;

    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Wait for echo to go high (with timeout)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every microsecond
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Timeout waiting for echo high\n");
        return -1.0; // Indicate timeout error
    }

    start_tick = gpioTick();

    // Wait for echo to go low (with timeout)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every microsecond
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Timeout waiting for echo low\n");
        return -1.0; // Indicate timeout error
    }

    end_tick = gpioTick();

    diff_tick = end_tick - start_tick;

    // Calculate distance in centimeters
    double distance = (double)diff_tick * SPEED_OF_SOUND / 2000000.0; // Divide by 1000000.0 to convert us to s and divide by 2 for one-way distance

    return distance;
}

// Function to map distance to frequency
double mapDistanceToFrequency(double distance) {
    if (distance < MIN_DISTANCE) {
        return MAX_FREQUENCY; // Return max frequency for close objects
    } else if (distance > MAX_DISTANCE) {
        return MIN_FREQUENCY; // Return min frequency for far objects
    } else {
        // Logarithmic mapping
        double log_distance = log10(distance / MIN_DISTANCE);
        double log_range = log10(MAX_DISTANCE / MIN_DISTANCE);
        double normalized_distance = log_distance / log_range;
        double frequency = MIN_FREQUENCY + normalized_distance * (MAX_FREQUENCY - MIN_FREQUENCY);
        return frequency;
    }
}

// Function to set the PWM frequency
void setPWMFrequency(double frequency) {
    if (frequency != current_frequency) {
        int range = 1000; // PWM range
        int dutycycle = 500; // 50% duty cycle

        gpioSetPWMfrequency(PWM_PIN, (int)frequency);
        gpioSetPWMrange(PWM_PIN, range);
        gpioPWM(PWM_PIN, dutycycle);

        current_frequency = frequency;
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    // Initialize trigger pin to low
    gpioWrite(TRIGGER_PIN, 0);

    // Set PWM frequency and range
    int range = 1000; // PWM range
    int dutycycle = 500; // 50% duty cycle
    gpioSetPWMfrequency(PWM_PIN, 440); // Initial frequency
    gpioSetPWMrange(PWM_PIN, range);
    gpioPWM(PWM_PIN, dutycycle);

    // Install signal handler
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    printf("Theremin-like instrument started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Trigger the sensor
        triggerSensor();

        // Measure the distance
        double distance = measureDistance();

        if (distance > 0) {
            // Map distance to frequency
            double frequency = mapDistanceToFrequency(distance);

            // Set the PWM frequency
            setPWMFrequency(frequency);

            printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, frequency);
        } else {
            fprintf(stderr, "Error: Invalid distance measurement\n");
        }

        // Delay to avoid overwhelming the sensor
        gpioDelay(50); // 50 ms delay
    }

    // Clean up and exit
    gpioPWM(PWM_PIN, 0); // Stop PWM
    gpioTerminate();       // Terminate pigpio

    return 0;
}

