#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MIN_DISTANCE 5.0      // Minimum measurable distance in cm
#define MAX_DISTANCE 50.0     // Maximum measurable distance in cm
#define MIN_FREQUENCY 200.0   // Minimum frequency in Hz
#define MAX_FREQUENCY 2000.0  // Maximum frequency in Hz
#define ECHO_TIMEOUT 100000   // Echo timeout in microseconds (100ms)

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
void triggerSensor();
long measurePulseWidth();
float calculateDistance(long pulseWidth);
float mapDistanceToFrequency(float distance);
void generateTone(float frequency);
void printData(float distance, float frequency);
void signalHandler(int signal);

// Signal handler function
void signalHandler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping program...\n", signal);
    gpioPWM(BUZZER_PIN, 0); // Stop PWM
    gpioTerminate();       // Terminate pigpio
    exit(0);
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 0); // Ensure trigger is low
    gpioDelay(2);              // Wait 2 microseconds
    gpioWrite(TRIGGER_PIN, 1); // Send a 10 microsecond pulse
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse width
long measurePulseWidth() {
    long startTime = 0, endTime = 0;

    // Wait for echo to go high (with timeout)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < ECHO_TIMEOUT) {
        startTime = gpioTick();
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= ECHO_TIMEOUT) {
        fprintf(stderr, "Error: Echo timeout occurred.\n");
        return -1; // Indicate timeout error
    }

    // Wait for echo to go low (with timeout)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < ECHO_TIMEOUT) {
        endTime = gpioTick();
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= ECHO_TIMEOUT) {
        fprintf(stderr, "Error: Echo timeout occurred.\n");
        return -1; // Indicate timeout error
    }

    return endTime - startTime;
}

// Function to calculate the distance from the pulse width
float calculateDistance(long pulseWidth) {
    if (pulseWidth < 0) {
        return -1.0; // Indicate error
    }
    return (pulseWidth * SPEED_OF_SOUND) / 2000000.0; // Convert microseconds to seconds and divide by 2
}

// Function to map the distance to a frequency
float mapDistanceToFrequency(float distance) {
    if (distance < MIN_DISTANCE) {
        return MIN_FREQUENCY;
    } else if (distance > MAX_DISTANCE) {
        return MAX_FREQUENCY;
    } else {
        return MIN_FREQUENCY + (distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE);
    }
}

// Function to generate a tone on the buzzer
void generateTone(float frequency) {
    if (frequency > 0) {
        gpioSetPWMfrequency(BUZZER_PIN, (int)frequency);
        gpioPWM(BUZZER_PIN, 128); // 50% duty cycle
    } else {
        gpioPWM(BUZZER_PIN, 0); // Stop PWM
    }
}

// Function to print the distance and frequency
void printData(float distance, float frequency) {
    printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, frequency);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    float lastValidDistance = MAX_DISTANCE; // Initialize with a reasonable value

    // Main loop
    while (program_running) {
        triggerSensor();
        long pulseWidth = measurePulseWidth();

        if (pulseWidth >= 0) {
            float distance = calculateDistance(pulseWidth);

            if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
                float frequency = mapDistanceToFrequency(distance);
                generateTone(frequency);
                printData(distance, frequency);
                lastValidDistance = distance;
            } else {
                fprintf(stderr, "Error: Distance out of range (%.2f cm)\n", distance);
                generateTone(0); // Stop tone
                printData(lastValidDistance, mapDistanceToFrequency(lastValidDistance)); // Print last valid distance
            }
        } else {
            fprintf(stderr, "Error: Sensor read failed\n");
            generateTone(0); // Stop tone
            printData(lastValidDistance, mapDistanceToFrequency(lastValidDistance)); // Print last valid distance
        }

        gpioDelay(10000); // Wait 10 milliseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioPWM(BUZZER_PIN, 0); // Stop PWM
    gpioTerminate();       // Terminate pigpio

    return 0;
}

