    while (gpioRead(ECHO_PIN) == 1 && count < ECHO_TIMEOUT) {
        endTime = gpioTick();
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= ECHO_TIMEOUT) {
        fprintf(stderr, "Error: Echo timeout occurred.\n");
        return -1; // Indicate timeout error
    }

    return endTime - startTime;
}

// Function to calculate the distance from the pulse width
float calculateDistance(long pulseWidth) {
    if (pulseWidth < 0) {
        return -1.0; // Indicate error
    }
    return (pulseWidth * SPEED_OF_SOUND) / 2000000.0; // Convert microseconds to seconds and divide by 2
}

// Function to map the distance to a frequency
float mapDistanceToFrequency(float distance) {
    if (distance < MIN_DISTANCE) {
        return MIN_FREQUENCY;
    } else if (distance > MAX_DISTANCE) {
        return MAX_FREQUENCY;
    } else {
        return MIN_FREQUENCY + (distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE);
    }
}

// Function to generate a tone on the buzzer
void generateTone(float frequency) {
    if (frequency > 0) {
        gpioSetPWMfrequency(BUZZER_PIN, (int)frequency);
        gpioPWM(BUZZER_PIN, 128); // 50% duty cycle
    } else {
        gpioPWM(BUZZER_PIN, 0); // Stop PWM
    }
}

// Function to print the distance and frequency
void printData(float distance, float frequency) {
    printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, frequency);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    float lastValidDistance = MAX_DISTANCE; // Initialize with a reasonable value

    // Main loop
    while (program_running) {
        triggerSensor();
        long pulseWidth = measurePulseWidth();

        if (pulseWidth >= 0) {
            float distance = calculateDistance(pulseWidth);

            if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
                float frequency = mapDistanceToFrequency(distance);
                generateTone(frequency);
                printData(distance, frequency);
                lastValidDistance = distance;
            } else {
                fprintf(stderr, "Error: Distance out of range (%.2f cm)\n", distance);
                generateTone(0); // Stop tone
                printData(lastValidDistance, mapDistanceToFrequency(lastValidDistance)); // Print last valid distance
            }
        } else {
            fprintf(stderr, "Error: Sensor read failed\n");
            generateTone(0); // Stop tone
            printData(lastValidDistance, mapDistanceToFrequency(lastValidDistance)); // Print last valid distance
        }

        gpioDelay(10000); // Wait 10 milliseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioPWM(BUZZER_PIN, 0); // Stop PWM
    gpioTerminate();       // Terminate pigpio

    return 0;
}

