#include <string.h>
#include <unistd.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8          // GPIO8 (CE0)
#define LOG_FILE "distance_log.csv"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor configuration (example)
typedef struct {
    uint8_t config_reg;
    uint8_t config_value;
} sensor_config_t;

// Function prototypes
int initialize_sensor();
int read_distance(uint16_t *distance);
int log_data(uint16_t distance);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Function to initialize the sensor
int initialize_sensor() {
    // Example configuration (replace with actual initialization sequence)
    sensor_config_t config[] = {
        {0x01, 0x02}, // Example register and value
        {0x02, 0x04}  // Another example register and value
    };
    int num_configs = sizeof(config) / sizeof(config[0]);

    for (int i = 0; i < num_configs; i++) {
        char tx_buffer[2];
        tx_buffer[0] = config[i].config_reg; // Register address
        tx_buffer[1] = config[i].config_value; // Value to write

        char rx_buffer[2];
        int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 2);

        if (result != 0) {
            fprintf(stderr, "Error writing to sensor configuration register 0x%02X: %d\n", config[i].config_reg, result);
            return -1;
        }
        gpioDelay(1000); // Small delay after each write
    }

    printf("Sensor initialized successfully.\n");
    return 0;
}

// Function to read the distance from the sensor
int read_distance(uint16_t *distance) {
    char tx_buffer[2];
    char rx_buffer[2];
    int retries = RETRY_COUNT;

    // Example: Read two bytes from register 0x00 (replace with actual register)
    tx_buffer[0] = 0x00; // Register address to read from
    tx_buffer[1] = 0x00; // Dummy byte for reading

    while (retries > 0) {
        int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 2);

        if (result == 0) {
            // Combine the two bytes into a 16-bit distance value
            *distance = (rx_buffer[0] << 8) | rx_buffer[1];
            return 0; // Success
        } else {
            fprintf(stderr, "SPI read error: %d, retrying...\n", result);
            retries--;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "Failed to read distance after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

