#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Si1120 I2C address
#define SI1120_ADDR 0x60

// Si1120 register addresses
#define REG_PART_ID 0x00
#define REG_ALS_VIS_DATA0 0x10
#define REG_PS1_DATA0 0x18
#define REG_RESET 0x07
#define REG_COMMAND 0x30

// Si1120 reset command
#define RESET_CMD 0x01

// Si1120 Part ID
#define SI1120_PART_ID_VAL 0x20

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t als;
    uint16_t proximity;
} sensor_data_t;

// Function prototypes
int init_si1120();
sensor_data_t read_sensor_data();
void log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize the Si1120 sensor
int init_si1120() {
    int retries = 3;
    int result;

    // Reset the sensor
    while (retries > 0) {
        result = i2cWriteByteData(i2c_handle, REG_RESET, RESET_CMD);
        if (result == 0) {
            gpioDelay(10); // Wait for reset to complete
            break;
        } else {
            fprintf(stderr, "Error resetting Si1120 (attempt %d): %d\n", 4 - retries, result);
            gpioDelay(10);
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to reset Si1120 after multiple retries.\n");
        return -1;
    }

    // Verify Part ID
    retries = 3;
    while (retries > 0) {
        result = i2cReadByteData(i2c_handle, REG_PART_ID);
        if (result >= 0) {
            if (result != SI1120_PART_ID_VAL) {
                fprintf(stderr, "Error: Incorrect Part ID (0x%02X, expected 0x%02X)\n", result, SI1120_PART_ID_VAL);
                return -1;
            }
            break;
        } else {
            fprintf(stderr, "Error reading Part ID (attempt %d): %d\n", 4 - retries, result);
            gpioDelay(10);
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read Part ID after multiple retries.\n");
        return -1;
    }

    // Add more initialization commands here based on the Si1120 datasheet
    // Example: Configure ALS and proximity parameters
    // i2cWriteByteData(i2c_handle, REG_ALS_RATE, 0x08); // Example ALS rate
    // i2cWriteByteData(i2c_handle, REG_PS_RATE, 0x0A);  // Example proximity rate

    printf("Si1120 initialized successfully.\n");
    return 0;
}

// Read ambient light and proximity data from the Si1120
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    int retries = 3;
    int result;

    // Read ALS data
    retries = 3;
    while (retries > 0) {
        result = i2cReadByteData(i2c_handle, REG_ALS_VIS_DATA0);
        if (result >= 0) {
            data.als = (uint16_t)result;
            break;
        } else {
            fprintf(stderr, "Error reading ALS data (attempt %d): %d\n", 4 - retries, result);
            gpioDelay(10);
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read ALS data after multiple retries.\n");
        data.als = 0; // Set to 0 to avoid using uninitialized data
    }

    retries = 3;
