#include <errno.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define SI1182_ADDR 0x60

// Define register addresses
#define REG_PART_ID 0x00
#define REG_MEAS_RATE 0x08
#define REG_ALS_DATA0 0x22
#define REG_PS_DATA0 0x24

// Define measurement rate values
#define MEAS_RATE_100MS 0x0A

// Global variables for file descriptors and file pointers
int i2c_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int si1182_init(int fd);
int read_sensor_data(int fd, float *lux, uint16_t *proximity);
void log_data(FILE *fp, float lux, uint16_t proximity);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float lux;
    uint16_t proximity;
} sensor_data_t;

// Function to read a single byte from an I2C register
int i2c_read_reg(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

// Function to write a single byte to an I2C register
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to initialize the Si1182 sensor
int si1182_init(int fd) {
    // Verify the part ID
    int part_id = i2c_read_reg(fd, REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error reading part ID\n");
        return -1;
    }
    if (part_id != 0x50) {
        fprintf(stderr, "Incorrect part ID: 0x%02X\n", part_id);
        return -1;
    }
    printf("Si1182 part ID: 0x%02X\n", part_id);

    // Configure the measurement rate
    if (i2c_write_reg(fd, REG_MEAS_RATE, MEAS_RATE_100MS) < 0) {
        fprintf(stderr, "Error writing measurement rate\n");
        return -1;
    }
    printf("Measurement rate set to 100ms\n");

    return 0;
}

// Function to read sensor data (lux and proximity)
int read_sensor_data(int fd, float *lux, uint16_t *proximity) {
    int als_data0, als_data1, ps_data0, ps_data1;

    als_data0 = i2c_read_reg(fd, REG_ALS_DATA0);
    als_data1 = i2c_read_reg(fd, REG_ALS_DATA0 + 1);
    ps_data0 = i2c_read_reg(fd, REG_PS_DATA0);
    ps_data1 = i2c_read_reg(fd, REG_PS_DATA0 + 1);

    if (als_data0 < 0 || als_data1 < 0 || ps_data0 < 0 || ps_data1 < 0) {
        fprintf(stderr, "Error reading sensor data\n");
        return -1;
    }

    *lux = (float)((als_data1 << 8) | als_data0); // Combine the two bytes
    *proximity = (uint16_t)((ps_data1 << 8) | ps_data0); // Combine the two bytes

    return 0;
}

// Function to log data to a CSV file
void log_data(FILE *fp, float lux, uint16_t proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.2f,%u\n", timestamp, lux, proximity);
    fflush(fp); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the I2C device
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Initialize the sensor
    if (si1182_init(i2c_fd) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Open the log file
    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    float lux;
    uint16_t proximity;
    while (1) {
        if (read_sensor_data(i2c_fd, &lux, &proximity) == 0) {
            log_data(log_file, lux, proximity);
            printf("%.2f,%u\n", lux, proximity);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }
        usleep(100000); // 100ms delay
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness.
    close(i2c_fd);
    fclose(log_file);
    return 0;
}

