#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define BUZZER_PIN 27

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define DISTANCE_THRESHOLD 20.0 // Distance threshold in cm
#define TRIGGER_PULSE_DURATION 10 // Trigger pulse duration in microseconds

// Global variables
volatile unsigned int start_tick = 0;
volatile unsigned int end_tick = 0;
volatile int echo_received = 0;

// Function prototypes
void trigger_sensor();
void echo_callback(int gpio, int level, unsigned int tick);
float calculate_distance(unsigned int pulse_width);
void control_buzzer(float distance);
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1); // Set trigger pin high
    gpioDelay(TRIGGER_PULSE_DURATION); // Wait for trigger pulse duration
    gpioWrite(TRIGGER_PIN, 0); // Set trigger pin low
}

// Callback function for echo pin
void echo_callback(int gpio, int level, unsigned int tick) {
    if (level == 1) {
        start_tick = tick;
        echo_received = 1; // Indicate rising edge received
    } else if (level == 0 && echo_received == 1) {
        end_tick = tick;
        echo_received = 0; // Indicate falling edge received
    }
}

// Function to calculate distance from pulse width
float calculate_distance(unsigned int pulse_width) {
    return (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Convert microseconds to seconds and divide by 2
}

// Function to control the buzzer based on distance
void control_buzzer(float distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(BUZZER_PIN, 1); // Turn on buzzer
    } else {
        gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Register callback function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    printf("Ultrasonic sensor program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        trigger_sensor(); // Trigger the sensor

        // Wait for echo pulse to be received (with timeout)
        int timeout_count = 0;
        while (!echo_received && timeout_count < 1000) {
            gpioDelay(1); // Wait 1 ms
            timeout_count++;
        }

        if (!echo_received) {
            fprintf(stderr, "Timeout waiting for echo pulse\n");
            continue; // Skip to the next iteration
        }

        // Calculate pulse width
        unsigned int pulse_width = end_tick - start_tick;

        // Calculate distance
        float distance = calculate_distance(pulse_width);

        // Control buzzer
        control_buzzer(distance);

        // Print distance to stdout
        printf("Distance: %.2f cm\n", distance);

        // Wait for 1 second
        gpioDelay(1000);
    }

    return 0; // This line will never be reached due to the infinite loop
}

