#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 50000       // Timeout for echo pulse in microseconds
#define MIN_DISTANCE 20.0     // Minimum measurable distance in cm
#define MAX_DISTANCE 200.0    // Maximum measurable distance in cm
#define MIN_PULSE_WIDTH 500   // Minimum pulse width for servo (us)
#define MAX_PULSE_WIDTH 2500  // Maximum pulse width for servo (us)
#define SERVO_CENTER_PULSE_WIDTH 1500 // Center pulse width for servo (us)

// Global variable for program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCtrl+C pressed. Exiting gracefully...\n");
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse width
long measurePulseWidth() {
    long start_tick, end_tick, diff;

    // Wait for echo to go high (with timeout)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every 1 us
    }
    if (count >= TIMEOUT_US) {
        return -1; // Timeout
    }
    start_tick = gpioTick();

    // Wait for echo to go low (with timeout)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every 1 us
    }
    if (count >= TIMEOUT_US) {
        return -1; // Timeout
    }
    end_tick = gpioTick();

    diff = end_tick - start_tick;
    if (diff < 0) {
        diff += 0xFFFFFFFF; // Handle tick rollover
    }

    return diff;
}

// Function to calculate the distance in centimeters
float calculateDistance(long pulse_width) {
    if (pulse_width < 0) {
        return -1.0; // Indicate error
    }
    return (pulse_width * SPEED_OF_SOUND) / 2000000.0; // Divide by 1000000.0 to convert us to s and multiply by 2 for one-way distance
}

// Function to set the servo angle
void setServoAngle(float distance) {
    // Map distance to pulse width (0° to 180°)
    float pulse_width = MIN_PULSE_WIDTH + (distance - MIN_DISTANCE) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) / (MAX_DISTANCE - MIN_DISTANCE);

    // Ensure pulse width is within valid range
    if (pulse_width < MIN_PULSE_WIDTH) {
        pulse_width = MIN_PULSE_WIDTH;
    } else if (pulse_width > MAX_PULSE_WIDTH) {
        pulse_width = MAX_PULSE_WIDTH;
    }

    gpioServo(SERVO_PIN, (int)pulse_width);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Initialize trigger pin to low
    gpioWrite(TRIGGER_PIN, 0);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Parking assist system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Trigger the sensor
        triggerSensor();

        // Measure the pulse width
        long pulse_width = measurePulseWidth();

        // Calculate the distance
        float distance = calculateDistance(pulse_width);

        // Set the servo angle
        if (distance > 0) {
            setServoAngle(distance);
        } else {
            gpioServo(SERVO_PIN, SERVO_CENTER_PULSE_WIDTH); // Set to center on error
        }

        // Print the distance
        if (distance > 0) {
            printf("Distance: %.2f cm\n", distance);
        } else {
            printf("Error: No echo received or timeout occurred.\n");
        }

        // Delay for 100 ms
        gpioDelay(100);
    }

    // Stop the servo motor
    gpioServo(SERVO_PIN, 0);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

