    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Initialize trigger pin to low
    gpioWrite(TRIGGER_PIN, 0);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Parking assist system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Trigger the sensor
        triggerSensor();

        // Measure the pulse width
        long pulse_width = measurePulseWidth();

        // Calculate the distance
        float distance = calculateDistance(pulse_width);

        // Set the servo angle
        if (distance > 0) {
            setServoAngle(distance);
        } else {
            gpioServo(SERVO_PIN, SERVO_CENTER_PULSE_WIDTH); // Set to center on error
        }

        // Print the distance
        if (distance > 0) {
            printf("Distance: %.2f cm\n", distance);
        } else {
            printf("Error: No echo received or timeout occurred.\n");
        }

        // Delay for 100 ms
        gpioDelay(100);
    }

    // Stop the servo motor
    gpioServo(SERVO_PIN, 0);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

