#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 50000       // Timeout in microseconds (50ms)
#define MIN_DISTANCE 2.0      // Minimum measurable distance in cm
#define MAX_DISTANCE 400.0    // Maximum measurable distance in cm
#define MIN_ANGLE 0.0          // Minimum servo angle in degrees
#define MAX_ANGLE 180.0        // Maximum servo angle in degrees
#define MIN_PULSE_WIDTH 500    // Minimum pulse width for servo (us)
#define MAX_PULSE_WIDTH 2500   // Maximum pulse width for servo (us)

// Global variables
volatile int echo_start_tick = 0;
volatile int echo_end_tick = 0;
volatile int echo_received = 0;

// Function prototypes
int initialize_gpio();
void trigger_sensor();
void echo_callback(int gpio, int level, uint32_t tick);
float calculate_distance(int start_tick, int end_tick);
int map_distance_to_angle(float distance);
int set_servo_angle(int angle);
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    set_servo_angle(0); // Stop the servo
    gpioTerminate();       // Terminate pigpio
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set pull-down resistor on echo pin to avoid floating values
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    return 0; // Indicate success
}

// Trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        echo_start_tick = tick;
        echo_received = 1; // Indicate rising edge received
    } else if (level == 0 && echo_received) {
        echo_end_tick = tick;
        echo_received = 0; // Indicate falling edge received
    }
}

// Calculate distance in centimeters
float calculate_distance(int start_tick, int end_tick) {
    if (start_tick == 0 || end_tick == 0) {
        return -1.0; // Indicate timeout
    }

    int diff = end_tick - start_tick;
