#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Si7005 I2C address
#define SI7005_ADDR 0x40

// Si7005 register addresses
#define SI7005_TEMP_MEASURE_CMD 0xE3
#define SI7005_HUMID_MEASURE_CMD 0xE5
#define SI7005_CONFIG_REG 0x00

// Configuration value (example: enable heater)
#define SI7005_CONFIG_VALUE 0x00

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
    terminate = 1;
}

// Function to initialize the Si7005 sensor
int init_si7005() {
    // Write the configuration register
    int result = i2cWriteByteData(i2c_handle, SI7005_CONFIG_REG, SI7005_CONFIG_VALUE);
    if (result != 0) {
        fprintf(stderr, "Error writing to config register: %d\n", result);
        return -1;
    }
    gpioDelay(10000); // Wait 10ms
    return 0;
}

// Function to read temperature from the Si7005 sensor
int read_temperature(float *temperature) {
    // Write the temperature measurement command
    int result = i2cWriteByte(i2c_handle, SI7005_TEMP_MEASURE_CMD);
    if (result != 0) {
        fprintf(stderr, "Error writing temperature command: %d\n", result);
        return -1;
    }
    gpioDelay(10000); // Wait 10ms

    // Read the temperature data
    uint16_t raw_temperature = i2cReadWordData(i2c_handle, 0); // Register address is not used for reading, so we pass 0
    if (raw_temperature == PI_I2C_READ_FAILED) {
        fprintf(stderr, "Error reading temperature data: %d\n", raw_temperature);
        return -1;
    }

    // Convert the raw temperature to Celsius
    *temperature = (175.72 * raw_temperature / 65536.0) - 46.85;
    return 0;
}

// Function to read humidity from the Si7005 sensor
int read_humidity(float *humidity) {
    // Write the humidity measurement command
    int result = i2cWriteByte(i2c_handle, SI7005_HUMID_MEASURE_CMD);
    if (result != 0) {
        fprintf(stderr, "Error writing humidity command: %d\n", result);
        return -1;
    }
    gpioDelay(10000); // Wait 10ms

    // Read the humidity data
    uint16_t raw_humidity = i2cReadWordData(i2c_handle, 0); // Register address is not used for reading, so we pass 0
    if (raw_humidity == PI_I2C_READ_FAILED) {
        fprintf(stderr, "Error reading humidity data: %d\n", raw_humidity);
        return -1;
    }

    // Convert the raw humidity to relative humidity
    *humidity = (125.0 * raw_humidity / 65536.0) - 6.0;
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SI7005_ADDR, 0); // Bus 1, address 0x40, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the Si7005 sensor
    if (init_si7005() != 0) {
        fprintf(stderr, "Si7005 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        float temperature, humidity;

        // Read temperature
        if (read_temperature(&temperature) == 0) {
            // Read humidity
            if (read_humidity(&humidity) == 0) {
                // Log the data
                printf("Temperature: %.2f °C, Humidity: %.2f %%\n", temperature, humidity);
            } else {
                fprintf(stderr, "Failed to read humidity\n");
            }
        } else {
            fprintf(stderr, "Failed to read temperature\n");
        }

        gpioDelay(2000000); // Wait 2 seconds
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

