    // Wake up the MPU-6050 (clear sleep mode bit)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) != 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050\n");
        return -1;
    }

    // Set sample rate divider
    if (i2cWriteByteData(i2c_handle, SMPLRT_DIV, 7) != 0) { // Sample rate = Gyroscope Output Rate / (1 + SMPLRT_DIV)
        fprintf(stderr, "Error: Could not set sample rate divider\n");
        return -1;
    }

    // Configure DLPF (Digital Low Pass Filter)
    if (i2cWriteByteData(i2c_handle, CONFIG, 0x00) != 0) { // Set DLPF_CFG to 0 for no filtering
        fprintf(stderr, "Error: Could not configure DLPF\n");
        return -1;
    }

    // Configure gyroscope range (+/- 250 degrees/sec)
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) != 0) {
        fprintf(stderr, "Error: Could not configure gyroscope range\n");
        return -1;
    }

    // Configure accelerometer range (+/- 2g)
    if (i2cWriteByteData(i2c_handle, ACCEL_CONFIG, 0x00) != 0) {
        fprintf(stderr, "Error: Could not configure accelerometer range\n");
        return -1;
    }

    return 0;
}

// Function to read raw data from the MPU-6050
int read_raw_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *temp, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    char buf[14];

    if (i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, buf, 14) != 14) {
        fprintf(stderr, "Error: Could not read raw data\n");
        return -1;
    }

    *accel_x = (int16_t)((buf[0] << 8) | buf[1]);
    *accel_y = (int16_t)((buf[2] << 8) | buf[3]);
    *accel_z = (int16_t)((buf[4] << 8) | buf[5]);
    *temp    = (int16_t)((buf[6] << 8) | buf[7]);
    *gyro_x  = (int16_t)((buf[8] << 8) | buf[9]);
    *gyro_y  = (int16_t)((buf[10] << 8) | buf[11]);
    *gyro_z  = (int16_t)((buf[12] << 8) | buf[13]);

    return 0;
}

// Function to process raw data and convert to meaningful units
void process_data(int16_t accel_x, int16_t accel_y, int16_t accel_z, int16_t temp, int16_t gyro_x, int16_t gyro_y, int16_t gyro_z, float *accel_x_g, float *accel_y_g, float *accel_z_g, float *temp_c, float *gyro_x_dps, float *gyro_y_dps, float *gyro_z_dps) {
    // Sensitivity scales (from datasheet)
    const float ACCEL_SCALE = 16384.0f; // +/- 2g range
    const float GYRO_SCALE = 131.0f;    // +/- 250 degrees/sec range

    *accel_x_g = (float)accel_x / ACCEL_SCALE;
    *accel_y_g = (float)accel_y / ACCEL_SCALE;
    *accel_z_g = (float)accel_z / ACCEL_SCALE;
    *temp_c = (float)temp / 340.0f + 36.53f; // Temperature in degrees Celsius
    *gyro_x_dps = (float)gyro_x / GYRO_SCALE;
    *gyro_y_dps = (float)gyro_y / GYRO_SCALE;
    *gyro_z_dps = (float)gyro_z / GYRO_SCALE;
}

// Function to log the processed data to the console
void log_data(float accel_x_g, float accel_y_g, float accel_z_g, float temp_c, float gyro_x_dps, float gyro_y_dps, float gyro_z_dps) {
    printf("Accel: X=%.2f g, Y=%.2f g, Z=%.2f g, Temp=%.2f C, Gyro: X=%.2f dps, Y=%.2f dps, Z=%.2f dps\n",
           accel_x_g, accel_y_g, accel_z_g, temp_c, gyro_x_dps, gyro_y_dps, gyro_z_dps);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Verify sensor presence
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i != 0x68) {
        fprintf(stderr, "Error: MPU-6050 not found (WHO_AM_I=0x%x)\n", who_am_i);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int16_t accel_x, accel_y, accel_z, temp, gyro_x, gyro_y, gyro_z;
    float accel_x_g, accel_y_g, accel_z_g, temp_c, gyro_x_dps, gyro_y_dps, gyro_z_dps;

    printf("MPU-6050 data logger started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read raw data
        if (read_raw_data(&accel_x, &accel_y, &accel_z, &temp, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Process data
            process_data(accel_x, accel_y, accel_z, temp, gyro_x, gyro_y, gyro_z, &accel_x_g, &accel_y_g, &accel_z_g, &temp_c, &gyro_x_dps, &gyro_y_dps, &gyro_z_dps);

            // Log data
            log_data(accel_x_g, accel_y_g, accel_z_g, temp_c, gyro_x_dps, gyro_y_dps, gyro_z_dps);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data. Retrying...\n");
        }

        // Delay for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Clean up
    printf("Cleaning up and exiting...\n");
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

