#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI7015_ADDR 0x40
#define TEMP_CMD 0xE3
#define HUMID_CMD 0xE5
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define SAMPLE_INTERVAL_SEC 5

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_pigpio();
int open_i2c_bus(int bus, int addr);
int write_i2c_byte(int handle, int cmd);
int read_i2c_word(int handle);
int read_sensor_data(int handle, sensor_data_t *data);
float convert_temperature(int raw_temp);
float convert_humidity(int raw_humidity);
int log_data(FILE *fp, float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(handle));
        return -1;
    }
    return handle;
}

// Write a byte to I2C
int write_i2c_byte(int handle, int cmd) {
    int result = i2cWriteByte(handle, cmd);
    if (result < 0) {
        fprintf(stderr, "Failed to write to I2C: %s\n", strerror(result));
        return -1;
    }
    return 0;
}

// Read a word from I2C
int read_i2c_word(int handle) {
    int result = i2cReadWordData(handle, 0); // Register address is not used for Si7015
    if (result < 0) {
        fprintf(stderr, "Failed to read from I2C: %s\n", strerror(result));
        return -1;
    }
    return result;
}

// Read temperature and humidity data from the sensor
int read_sensor_data(int handle, sensor_data_t *data) {
    int raw_temp, raw_humidity;

    // Measure temperature
    if (write_i2c_byte(handle, TEMP_CMD) != 0) {
        fprintf(stderr, "Failed to write temperature command\n");
        return -1;
    }
    gpioDelay(20); // Wait for measurement (datasheet specifies 12.1ms for temp, 12.1ms for humidity)
    raw_temp = read_i2c_word(handle);
    if (raw_temp < 0) {
        fprintf(stderr, "Failed to read temperature data\n");
        return -1;
    }

    // Measure humidity
    if (write_i2c_byte(handle, HUMID_CMD) != 0) {
        fprintf(stderr, "Failed to write humidity command\n");
        return -1;
    }
    gpioDelay(20); // Wait for measurement
    raw_humidity = read_i2c_word(handle);
    if (raw_humidity < 0) {
        fprintf(stderr, "Failed to read humidity data\n");
        return -1;
    }

    // Convert raw data to Celsius and percentage relative humidity
    data->temperature = convert_temperature(raw_temp);
    data->humidity = convert_humidity(raw_humidity);

    return 0;
}

// Convert raw temperature to Celsius
float convert_temperature(int raw_temp) {
    return (175.72 * raw_temp / 65536.0) - 46.85;
}

// Convert raw humidity to percentage relative humidity
float convert_humidity(int raw_humidity) {
    return (125.0 * raw_humidity / 65536.0) - 6.0;
}

// Log data to file
int log_data(FILE *fp, float temperature, float humidity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s, %.2f, %.2f\n", timestamp, temperature, humidity) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    sensor_data_t sensor_data;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    i2c_handle = open_i2c_bus(I2C_BUS, SI7015_ADDR);
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("sensor_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_handle, &sensor_data) == 0) {
            // Log data
            if (log_data(log_file, sensor_data.temperature, sensor_data.humidity) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }

            // Print data to console
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", sensor_data.temperature, sensor_data.humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

