#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define TRIGGER_CMD 0x362F // Continuous measurement without averaging
#define CRC8_POLYNOMIAL 0x31
#define DATA_FILE "airflow_data.txt"
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_handle;
FILE *data_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int send_trigger_command();
int read_sensor_data(uint8_t *data);
int validate_crc(const uint8_t *data, int len);
sensor_data_t convert_data(const uint8_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C communication
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Send the continuous measurement trigger command
int send_trigger_command() {
    char cmd[2] = {(TRIGGER_CMD >> 8) & 0xFF, TRIGGER_CMD & 0xFF};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write trigger command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data from the SDP800-500Pa sensor
int read_sensor_data(uint8_t *data) {
    int bytes_read = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (bytes_read != 9) {
        fprintf(stderr, "Failed to read sensor data: %d\n", bytes_read);
        return -1;
    }
    return 0;
}

// Validate CRC-8 checksum
int validate_crc(const uint8_t *data, int len) {
    uint8_t crc = crc8(data, len);
    return (crc == data[len]);
}

// Convert raw data to pressure and temperature
sensor_data_t convert_data(const uint8_t *data) {
    sensor_data_t sensor_data;
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];

    // Scale factors (from datasheet)
    float pressure_scale_factor = 60.0; // Pa
    float temperature_scale_factor = 200.0; // Degrees C

    sensor_data.pressure = (float)raw_pressure / pressure_scale_factor;
    sensor_data.temperature = (float)raw_temperature / temperature_scale_factor;

    return sensor_data;
}

