    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(data_file, "%s,%.2f,%.2f\n", timestamp, data.pressure, data.temperature);
    fflush(data_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (data_file != NULL) {
        fclose(data_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Open data file
    data_file = fopen(DATA_FILE, "a");
    if (data_file == NULL) {
        fprintf(stderr, "Failed to open data file\n");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(data_file, 0, SEEK_END);
    long file_size = ftell(data_file);
    if (file_size == 0) {
        fprintf(data_file, "Timestamp,Pressure (Pa),Temperature (C)\n");
    }
    rewind(data_file);

    // Main loop
    while (!terminate) {
        uint8_t data[9];

        // Send trigger command
        if (send_trigger_command() != 0) {
            fprintf(stderr, "Error sending trigger command, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Wait for measurement (adjust as needed)
        gpioDelay(45); // 45 ms

        // Read sensor data
        if (read_sensor_data(data) != 0) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Validate CRC checksums
        if (!validate_crc(data, 2) || !validate_crc(data + 3, 2) || !validate_crc(data + 6, 2)) {
            fprintf(stderr, "CRC validation failed, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Convert data
        sensor_data_t sensor_data = convert_data(data);

        // Log data
        log_data(sensor_data);

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

