#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define STS30_ADDR 0x4A
#define MEASURE_HIGH_REPEATABILITY 0x2C06
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF
#define SAMPLE_INTERVAL_SEC 5
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
FILE *log_file;
FILE *error_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float temperature;
    time_t timestamp;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sts30(float *temperature);
uint8_t calculate_crc8(const uint8_t *data, size_t len);
int validate_crc8(const uint8_t *data, size_t len, uint8_t crc);
int log_data(float temperature);
int log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, STS30_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C device");
        return -1;
    }
    return 0;
}

// Read temperature from STS30 sensor
int read_sts30(float *temperature) {
    uint8_t cmd[2] = {(MEASURE_HIGH_REPEATABILITY >> 8) & 0xFF, MEASURE_HIGH_REPEATABILITY & 0xFF};
    uint8_t data[6];
    int result;

    // Send measurement command
    result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        log_error("Failed to write measurement command");
        return -1;
    }

    // Wait for conversion (at least 15 ms)
    gpioDelay(15000); // 15 ms

    // Read 6 bytes of data (2 bytes temperature, 2 bytes humidity, 2 bytes CRC)
    result = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (result != 6) {
        log_error("Failed to read data from sensor");
        return -1;
    }

    // Validate CRC for temperature data
    if (!validate_crc8(data, 2, data[2])) {
        log_error("Temperature CRC check failed");
        return -1;
    }

    // Convert raw temperature data to Celsius
    int32_t raw_temperature = (data[0] << 8) | data[1];
    *temperature = -45.0 + (175.0 * (float)raw_temperature / 65535.0);

    return 0;
}

// Calculate CRC-8 checksum
uint8_t calculate_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INITIAL_VALUE;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC-8 checksum
int validate_crc8(const uint8_t *data, size_t len, uint8_t crc) {
    return calculate_crc8(data, len) == crc;
}

// Log data to file
int log_data(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s, %.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Log error to file
int log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(error_file, "%s, %s\n", timestamp, message);
    fflush(error_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (error_file != NULL) {
        fclose(error_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log files
    log_file = fopen("enclosure_temp_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    error_file = fopen("error_log.txt", "a");
    if (error_file == NULL) {
        perror("Failed to open error log file");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float temperature;
    int retry;

    // Main loop
    while (!terminate) {
        retry = 0;
        while (retry < RETRY_COUNT) {
            if (read_sts30(&temperature) == 0) {
                log_data(temperature);
                break; // Exit retry loop on success
            } else {
                retry++;
                log_error("Failed to read temperature, retrying...");
                gpioDelay(100000); // Wait 100ms before retrying
            }
        }

        if (retry == RETRY_COUNT) {
            log_error("Failed to read temperature after multiple retries");
        }

        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000); // Wait for the next sample
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

