#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// SCD40 I2C address
#define SCD40_ADDR 0x62

// SCD40 commands
#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_READ_MEASUREMENT 0xEC05
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3F86

// CRC-8 polynomial and initialization values
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIALIZATION 0xFF

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int initialize_pigpio();
int open_i2c_connection();
int send_command(uint16_t command);
int read_data(uint8_t *data, int count);
uint8_t calculate_crc(uint8_t data[], int count);
int verify_crc(uint8_t data[], int count);
int read_scd40_data(sensor_data_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
int stop_periodic_measurement();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C connection
int open_i2c_connection() {
    i2c_handle = i2cOpen(1, SCD40_ADDR, 0); // Bus 1, address 0x62, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send a command to the SCD40
int send_command(uint16_t command) {
    char buf[2];
    buf[0] = command >> 8;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write command 0x%04X: %d\n", command, result);
        return -1;
    }
    return 0;
}

// Read data from the SCD40
int read_data(uint8_t *data, int count) {
    int result = i2cReadDevice(i2c_handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Calculate CRC-8 checksum
uint8_t calculate_crc(uint8_t data[], int count) {
    uint8_t crc = CRC8_INITIALIZATION;
    for (int i = 0; i < count; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Verify CRC-8 checksum
int verify_crc(uint8_t data[], int count) {
    uint8_t crc = calculate_crc(data, count);
    if (crc != data[count]) {
        fprintf(stderr, "CRC check failed: calculated 0x%02X, received 0x%02X\n", crc, data[count]);
        return -1;
    }
    return 0;
}

// Read data from SCD40 sensor
int read_scd40_data(sensor_data_t *data) {
    uint8_t raw_data[9];

    // Read 9 bytes of data
    if (read_data(raw_data, 9) != 0) {
        return -1;
    }

    // Verify CRC for each 2-byte word
    if (verify_crc(raw_data, 2) != 0 || verify_crc(raw_data + 3, 2) != 0 || verify_crc(raw_data + 6, 2) != 0) {
        return -1;
    }

    // Extract raw data
    data->co2 = (raw_data[0] << 8) | raw_data[1];
    data->temperature = -45 + 175 * ((float)((raw_data[3] << 8) | raw_data[4])) / 65535;
    data->humidity = 100 * ((float)((raw_data[6] << 8) | raw_data[7])) / 65535;

    return 0;
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%d,%.2f,%.2f\n", timestamp, data.co2, data.temperature, data.humidity);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Stop periodic measurement
int stop_periodic_measurement() {
    if (send_command(CMD_STOP_PERIODIC_MEASUREMENT) != 0) {
        fprintf(stderr, "Failed to stop periodic measurement\n");
        return -1;
    }
    gpioDelay(1000); // Wait for 1 second
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C connection
    if (open_i2c_connection() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Start periodic measurement
    if (send_command(CMD_START_PERIODIC_MEASUREMENT) != 0) {
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioDelay(1000); // Wait for 1 second

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read data from SCD40
        if (read_scd40_data(&sensor_data) == 0) {
            // Log data
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(5000); // Wait for 5 seconds
    }

    // Stop periodic measurement
    if (stop_periodic_measurement() != 0) {
        fprintf(stderr, "Failed to stop periodic measurement during shutdown\n");
    }

    // Close I2C connection and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

