#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SCD40_ADDR 0x62
#define GPIO_LED 17
#define BUFFER_SIZE 20
#define CO2_THRESHOLD 1000
#define MEASUREMENT_INTERVAL_SEC 5

// SCD40 Commands
#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_READ_MEASUREMENT 0xEC05
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3F86

// Data Structures
typedef struct {
    uint16_t co2;
    float temperature;
    float humidity;
} scd40_data_t;

typedef struct {
    scd40_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global Variables
int i2c_handle;
circular_buffer_t buffer;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int init_pigpio();
int init_i2c();
int init_scd40();
int read_scd40_data(scd40_data_t *data);
uint8_t crc8(const uint8_t *data, int len);
void add_to_buffer(circular_buffer_t *buffer, scd40_data_t data);
scd40_data_t get_latest_reading(circular_buffer_t *buffer);
void print_data(scd40_data_t data);
void control_led(int co2_ppm);
void signal_handler(int signal);
void cleanup();

// CRC-8 Checksum Calculation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize SCD40 sensor
int init_scd40() {
    uint8_t cmd[2];
    cmd[0] = (CMD_START_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    cmd[1] = CMD_START_PERIODIC_MEASUREMENT & 0xFF;

    int result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to start periodic measurement: %d\n", result);
        return -1;
    }
    gpioDelay(1000); // Wait for sensor to start
    return 0;
}

// Read data from SCD40 sensor
int read_scd40_data(scd40_data_t *data) {
    uint8_t cmd[2];
    uint8_t buffer[9];
    int result;

    cmd[0] = (CMD_READ_MEASUREMENT >> 8) & 0xFF;
    cmd[1] = CMD_READ_MEASUREMENT & 0xFF;

    result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to send read measurement command: %d\n", result);
        return -1;
    }

    gpioDelay(1); // Small delay after sending command

    result = i2cReadDevice(i2c_handle, (char *)buffer, 9);
    if (result != 9) {
        fprintf(stderr, "Failed to read measurement data: %d\n", result);
        return -1;
    }

    // CRC Check
    if (crc8(buffer, 2) != buffer[2] ||
        crc8(buffer + 3, 2) != buffer[5] ||
        crc8(buffer + 6, 2) != buffer[8]) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    // Convert data
    data->co2 = (buffer[0] << 8) | buffer[1];
    data->temperature = -45 + 175 * ((float)((buffer[3] << 8) | buffer[4])) / 65535;
    data->humidity = 100 * ((float)((buffer[6] << 8) | buffer[7])) / 65535;

    return 0;
}

// Add data to circular buffer
void add_to_buffer(circular_buffer_t *buffer, scd40_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Get latest reading from circular buffer
scd40_data_t get_latest_reading(circular_buffer_t *buffer) {
    if (buffer->count == 0) {
        scd40_data_t empty_data = {0, 0.0, 0.0};
        return empty_data;
    }
    int index = (buffer->head - 1 + BUFFER_SIZE) % BUFFER_SIZE;
    return buffer->data[index];
}

// Print data to stdout
void print_data(scd40_data_t data) {
    printf("CO2: %.2f ppm, Temperature: %.2f °C, Humidity: %.2f %%\n", data.co2, data.temperature, data.humidity);
}

// Control LED based on CO2 concentration
void control_led(int co2_ppm) {
    if (co2_ppm > CO2_THRESHOLD) {
        gpioWrite(GPIO_LED, 1); // Turn LED on
    } else {
        gpioWrite(GPIO_LED, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    // Stop periodic measurement
    uint8_t cmd[2];
    cmd[0] = (CMD_STOP_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    cmd[1] = CMD_STOP_PERIODIC_MEASUREMENT & 0xFF;
    i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    gpioDelay(1000);

    // Close I2C connection
    i2cClose(i2c_handle);

    // Release GPIO
    gpioWrite(GPIO_LED, 0); // Turn LED off
    gpioSetMode(GPIO_LED, PI_INPUT); // Set GPIO to input to avoid spurious signals

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Initialize
    if (init_pigpio() != 0) {
        return 1;
    }

    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    if (init_scd40() != 0) {
        cleanup();
        return 1;
    }

    // Configure GPIO for LED
    gpioSetMode(GPIO_LED, PI_OUTPUT);
    gpioWrite(GPIO_LED, 0); // Initially turn LED off

    // Initialize circular buffer
    buffer.head = 0;
    buffer.count = 0;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    scd40_data_t data;

    // Main loop
    while (!terminate) {
        if (read_scd40_data(&data) == 0) {
            add_to_buffer(&buffer, data);
            print_data(data);
            control_led(data.co2);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(MEASUREMENT_INTERVAL_SEC * 1000); // Wait 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

