#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define GPIO_PIN 4
#define LOG_FILE "temperature_log.txt"
#define VALID_TEMP_MIN -40.0
#define VALID_TEMP_MAX 150.0
#define MAX_CONSECUTIVE_FAILURES 3

static volatile int running = 1;
static FILE *log_file = NULL;
static int consecutive_failures = 0;

// Structure to hold timestamp data
typedef struct {
    unsigned int seconds;
    unsigned int micros;
} timestamp_t;

// Function prototypes
int initialize_gpio();
timestamp_t get_timestamp();
int measure_pulse_width(timestamp_t *start, timestamp_t *end);
float calculate_temperature(int high_pulse_width, int total_cycle_width);
int log_temperature(float temperature);
void signal_handler(int signal);
void cleanup();

// Function to initialize the pigpio library and set the GPIO pin mode
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    return 0;
}

// Function to get the current timestamp in seconds and microseconds
timestamp_t get_timestamp() {
    timestamp_t ts;
    ts.seconds = time(NULL);
    ts.micros = gpioTick();
    return ts;
}

// Function to measure the pulse width of the PWM signal
int measure_pulse_width(timestamp_t *start, timestamp_t *end) {
    int high_pulse_width = 0;
    int total_cycle_width = 0;
    timestamp_t current_time;

    // Wait for the signal to go high
    while (gpioRead(GPIO_PIN) == 0 && running) {
        current_time = get_timestamp();
        if ((current_time.seconds - start->seconds) * 1000000 + (current_time.micros - start->micros) > 50000) {
            fprintf(stderr, "Timeout waiting for high signal\n");
            return -1; // Timeout
        }
    }

    if (!running) return -1; // Signal received during timeout

    *start = get_timestamp();

    // Wait for the signal to go low
    while (gpioRead(GPIO_PIN) == 1 && running) {
        current_time = get_timestamp();
        if ((current_time.seconds - start->seconds) * 1000000 + (current_time.micros - start->micros) > 50000) {
            fprintf(stderr, "Timeout waiting for low signal\n");
            return -1; // Timeout
        }
    }

    if (!running) return -1; // Signal received during timeout

    *end = get_timestamp();

    high_pulse_width = (end->seconds - start->seconds) * 1000000 + (end->micros - start->micros);
    total_cycle_width = high_pulse_width;

    return high_pulse_width;
}

// Function to calculate the temperature in Celsius
float calculate_temperature(int high_pulse_width, int total_cycle_width) {
    if (total_cycle_width == 0) {
        fprintf(stderr, "Division by zero error\n");
        return -999.0; // Indicate an error
    }

    float temperature = (float)high_pulse_width / (float)total_cycle_width * 100.0;
    return temperature;
}

// Function to log the temperature to a file with an ISO-8601 timestamp
int log_temperature(float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, temperature);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, shutting down...\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    timestamp_t start, end;
    int high_pulse_width;
    float temperature;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        // Measure the pulse width
        high_pulse_width = measure_pulse_width(&start, &end);

        if (high_pulse_width > 0) {
            // Calculate the temperature
            temperature = calculate_temperature(high_pulse_width, high_pulse_width);

            // Validate the temperature
            if (temperature >= VALID_TEMP_MIN && temperature <= VALID_TEMP_MAX) {
                // Log the temperature
                if (log_temperature(temperature) != 0) {
                    fprintf(stderr, "Error logging temperature\n");
                }
                consecutive_failures = 0; // Reset failure count
            } else {
                fprintf(stderr, "Temperature out of range: %.2f\n", temperature);
                consecutive_failures++;
                if (consecutive_failures >= MAX_CONSECUTIVE_FAILURES) {
                    fprintf(log_file, "SENSOR MALFUNCTION\n");
                    fflush(log_file);
                    consecutive_failures = 0; // Reset after logging
                }
            }
        } else {
            consecutive_failures++;
            if (consecutive_failures >= MAX_CONSECUTIVE_FAILURES) {
                fprintf(log_file, "SENSOR MALFUNCTION\n");
                fflush(log_file);
                consecutive_failures = 0; // Reset after logging
            }
        }

        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

