// Constants
#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define MEASUREMENT_COMMAND 0x2400 // High repeatability, clock stretching disabled
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 1000
#define SINUSOIDAL_PERIOD_SEC (60 * 60) // 1 hour
#define SINUSOIDAL_AMPLITUDE_TEMP 2.0
#define SINUSOIDAL_AMPLITUDE_HUMIDITY 5.0
#define LOG_FILE "environmental_data.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int initialize_pigpio();
int open_i2c_connection();
int read_sensor_data(uint8_t *data);
int validate_crc(uint8_t data[], int len);
sensor_data_t convert_data(uint8_t *data);
float apply_sinusoidal_offset(float value, float time_elapsed);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation (as per SHT35 datasheet)
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open I2C connection
    if (open_i2c_connection() != 0) {
        fprintf(stderr, "Failed to open I2C connection. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    uint8_t sensor_data[6];
    sensor_data_t processed_data;
    time_t current_time;
    struct tm *time_info;
    char timestamp[32];
    float time_elapsed;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(sensor_data) == 0) {
            // Validate CRC
            if (validate_crc(sensor_data, 2) && validate_crc(sensor_data + 3, 2)) {
                // Convert data
                processed_data = convert_data(sensor_data);

                // Get current time
                time(&current_time);
                time_info = gmtime(&current_time);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", time_info);

                // Apply sinusoidal offset
                time_elapsed = difftime(current_time, time(NULL));
                processed_data.temperature = apply_sinusoidal_offset(processed_data.temperature, time_elapsed);
                processed_data.humidity = apply_sinusoidal_offset(processed_data.humidity, time_elapsed);

                // Log data
                if (log_data(processed_data) != 0) {
                    fprintf(stderr, "Failed to log data.\n");
                }
            } else {
                fprintf(stderr, "CRC validation failed.\n");
                fprintf(log_file, "%s,NaN,NaN\n", timestamp);
                fflush(log_file);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
            fprintf(log_file, "%s,NaN,NaN\n", timestamp);
            fflush(log_file);
        }

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

int open_i2c_connection() {
    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

int read_sensor_data(uint8_t *data) {
    char cmd[2] = {(MEASUREMENT_COMMAND >> 8) & 0xFF, MEASUREMENT_COMMAND & 0xFF};
    int result;

    for (int i = 0; i < RETRY_COUNT; i++) {
        result = i2cWriteDevice(i2c_handle, cmd, 2);
        if (result == 0) {
            gpioDelay(15000); // Wait 15 ms
            result = i2cReadDevice(i2c_handle, (char *)data, 6);
            if (result == 6) {
                return 0; // Success
            } else {
                fprintf(stderr, "I2C read failed (attempt %d): %d\n", i + 1, result);
            }
        } else {
            fprintf(stderr, "I2C write failed (attempt %d): %d\n", i + 1, result);
        }
        gpioDelay(RETRY_DELAY_MS * 1000); // Wait 1 second
    }
    return 1; // Failure after retries
}

int validate_crc(uint8_t data[], int len) {
    uint8_t crc = crc8(data, len);
    return (crc == data[len]);
}

sensor_data_t convert_data(uint8_t *data) {
    sensor_data_t result;
    uint16_t temperature_raw = (data[0] << 8) | data[1];
    uint16_t humidity_raw = (data[3] << 8) | data[4];

    result.temperature = -45.0 + (175.0 * (float)temperature_raw / 65535.0);
    result.humidity = 100.0 * (float)humidity_raw / 65535.0;

    return result;
}

float apply_sinusoidal_offset(float value, float time_elapsed) {
    return value + SINUSOIDAL_AMPLITUDE_TEMP * sin(2 * M_PI * time_elapsed / SINUSOIDAL_PERIOD_SEC) + SINUSOIDAL_AMPLITUDE_HUMIDITY * sin(2 * M_PI * time_elapsed / SINUSOIDAL_PERIOD_SEC);
}

