    char timestamp[32];

    time(&current_time);
    time_info = gmtime(&current_time);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", time_info);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);
    fflush(log_file);

    return 0;
}

void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    gpioTerminate();
}

