sensor_data_t convert_data(const char *data) {
    sensor_data_t sensor_data;
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];
    uint8_t scale_factor = data[6];

    // Apply scaling factors (from datasheet)
    sensor_data.pressure = (float)raw_pressure / 60.0; // Pa
    sensor_data.temperature = (float)raw_temperature / 200.0; // °C

    return sensor_data;
}

// Log data to CSV file
int log_data(sensor_data_t data) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, data.pressure, data.temperature);
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open CSV file
    fp = fopen(CSV_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CSV file\n");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "Timestamp,Pressure (Pa),Temperature (C)\n");
    }

    // Main loop
    while (!terminate) {
        char buffer[9];
        int retry = 0;

        // Retry loop for reading data
        while (retry < RETRY_COUNT) {
            if (send_command(i2c_handle, MEASURE_CMD) == 0) {
                gpioDelay(45000); // Wait 45 ms

                if (read_data(i2c_handle, buffer, 9) == 0) {
                    // Validate CRCs
                    if (validate_crc(buffer, 2, buffer[2]) &&
                        validate_crc(buffer + 3, 2, buffer[5]) &&
                        validate_crc(buffer + 6, 1, buffer[8])) {

                        // Convert data
                        sensor_data_t sensor_data = convert_data(buffer);

                        // Log data
                        log_data(sensor_data);

                        break; // Exit retry loop on success
                    } else {
                        fprintf(stderr, "CRC validation failed, retrying...\n");
                    }
                } else {
                    fprintf(stderr, "Data read failed, retrying...\n");
                }
            } else {
                fprintf(stderr, "Command send failed, retrying...\n");
            }
            retry++;
            gpioDelay(10000); // Wait 10 ms before retrying
        }

        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Failed to read sensor data after %d retries.\n", RETRY_COUNT);
        }

        sleep(1); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

