#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define TEMP_MEASURE_CMD 0xE3
#define HUMID_MEASURE_CMD 0xE5
#define RESET_CMD 0xFE
#define CSV_FILE "environment.log"
#define POLYNOMIAL 0x31
#define INITIAL_VALUE 0x00
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define MEASUREMENT_DELAY_MS 100
#define LOG_INTERVAL_SEC 5

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(sensor_data_t *data);
float convert_temperature(uint16_t raw_temp);
float convert_humidity(uint16_t raw_humidity);
uint8_t crc8(const uint8_t *data, int len);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// CRC-8 checksum calculation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C communication
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read temperature and humidity data from the sensor
int read_sensor_data(sensor_data_t *data) {
    uint8_t buf[3];
    int result;

    // Measure temperature
    result = i2cWriteByte(i2c_handle, TEMP_MEASURE_CMD);
    if (result != 0) {
        fprintf(stderr, "Failed to write temperature command: %d\n", result);
        return -1;
    }
    gpioDelay(MEASUREMENT_DELAY_MS);

    result = i2cReadDevice(i2c_handle, (char *)buf, 3);
    if (result != 3) {
        fprintf(stderr, "Failed to read temperature data: %d\n", result);
        return -1;
    }

    uint16_t raw_temp = (buf[0] << 8) | buf[1];
    uint8_t temp_crc = buf[2];

    // Measure humidity
    result = i2cWriteByte(i2c_handle, HUMID_MEASURE_CMD);
    if (result != 0) {
        fprintf(stderr, "Failed to write humidity command: %d\n", result);
        return -1;
    }
    gpioDelay(MEASUREMENT_DELAY_MS);

    result = i2cReadDevice(i2c_handle, (char *)buf, 3);
    if (result != 3) {
        fprintf(stderr, "Failed to read humidity data: %d\n", result);
        return -1;
    }

    uint16_t raw_humidity = (buf[0] << 8) | buf[1];
    uint8_t humidity_crc = buf[2];

    // CRC validation
    if (crc8(buf, 2) != temp_crc) {
        fprintf(stderr, "Temperature CRC check failed\n");
        return -1;
    }

    if (crc8(buf, 2) != humidity_crc) {
        fprintf(stderr, "Humidity CRC check failed\n");
        return -1;
    }

    // Convert data
    data->temperature = convert_temperature(raw_temp);
    data->humidity = convert_humidity(raw_humidity);

    return 0;
}

// Convert raw temperature to Celsius
float convert_temperature(uint16_t raw_temp) {
    return (175.72 * raw_temp / 65536.0) - 46.85;
}

// Convert raw humidity to percentage
float convert_humidity(uint16_t raw_humidity) {
    return (125.0 * raw_humidity / 65536.0) - 6.0;
}

// Log data to CSV file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(CSV_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,temperature_C,humidity_percent\n");
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            if (log_data(sensor_data) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data, resetting...\n");
            i2cClose(i2c_handle);
            gpioDelay(100); // Small delay before reset
            i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to re-open I2C device: %d\n", i2c_handle);
                terminate = 1; // Exit if re-initialization fails
            }
        }

        gpioDelay(LOG_INTERVAL_SEC * 1000); // Wait for the next log interval
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

