int log_pressure(float pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.2f Pa\n", timestamp, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Send measurement command
        if (send_measurement_command() != 0) {
            fprintf(stderr, "Error sending measurement command, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Wait for conversion time
        gpioDelay(CONVERSION_TIME_MS);

        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Convert pressure
            float pressure = convert_pressure(sensor_data.differential_pressure);

            // Log pressure
            if (log_pressure(pressure) != 0) {
                fprintf(stderr, "Error logging pressure\n");
