#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define MEASURE_CMD 0x362F // Continuous measurement without averaging
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF
#define CONVERSION_TIME_MS 45
#define LOG_FILE "pressure_log.txt"
#define SLEEP_SECONDS 5

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    int16_t differential_pressure;
    uint16_t temperature;
    uint16_t status;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int send_measurement_command();
int read_sensor_data(sensor_data_t *data);
int validate_crc(uint8_t data[], int len);
float convert_pressure(int16_t raw_pressure);
int log_pressure(float pressure);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send measurement command to the sensor
int send_measurement_command() {
    char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing measurement command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data from the sensor
int read_sensor_data(sensor_data_t *data) {
    char buffer[9];
    int result = i2cReadDevice(i2c_handle, buffer, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    // Extract data and CRC values
    data->differential_pressure = (int16_t)((buffer[0] << 8) | buffer[1]);
    data->temperature = (uint16_t)((buffer[3] << 8) | buffer[4]);
    data->status = (uint16_t)((buffer[6] << 8) | buffer[7]);

    // Validate CRCs
    if (!validate_crc((uint8_t *)buffer, 2)) {
        fprintf(stderr, "CRC error for differential pressure\n");
        return -1;
    }
    if (!validate_crc((uint8_t *)buffer + 3, 2)) {
        fprintf(stderr, "CRC error for temperature\n");
        return -1;
    }
    if (!validate_crc((uint8_t *)buffer + 6, 2)) {
        fprintf(stderr, "CRC error for status\n");
        return -1;
    }

    return 0;
}

// Validate CRC checksum
int validate_crc(uint8_t data[], int len) {
    uint8_t crc = crc8(data, len);
    return (crc == data[len]);
}

// Convert raw pressure data to Pascals
float convert_pressure(int16_t raw_pressure) {
    // Scaling factor from the datasheet (adjust as needed)
    const float scale_factor = 60.0; // Example: 60 Pa/LSB
    return (float)raw_pressure / scale_factor;
}

// Log pressure data to a file
int log_pressure(float pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.2f Pa\n", timestamp, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Send measurement command
        if (send_measurement_command() != 0) {
            fprintf(stderr, "Error sending measurement command, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Wait for conversion time
        gpioDelay(CONVERSION_TIME_MS);

        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
