// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x28
#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define PRESSURE_MIN 0.0  // Minimum pressure in Pascals
#define PRESSURE_MAX 100.0 // Maximum pressure in Pascals
#define FLOW_RATE_MIN 0.0  // Minimum flow rate in SLPM
#define FLOW_RATE_MAX 100.0 // Maximum flow rate in SLPM
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_sensor_data(int16_t *raw_pressure);
float convert_to_pressure(int16_t raw_pressure);
float convert_to_flow_rate(float pressure);
int set_fan_speed(float flow_rate);
int log_data(float pressure, float flow_rate);
void signal_handler(int signal);
void cleanup();

// Structure for sensor calibration data (example)
typedef struct {
    float zero_offset;
    float sensitivity;
} sensor_calibration_t;

sensor_calibration_t sensor_calibration = {0.0, 1.0}; // Initialize with default values

// Function to initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read raw sensor data from the I2C bus
int read_sensor_data(int16_t *raw_pressure) {
    char buffer[2];
    int bytes_read = i2cReadDevice(i2c_handle, buffer, 2);

    if (bytes_read != 2) {
        fprintf(stderr, "Error reading sensor data: %d\n", bytes_read);
        return -1;
    }

    *raw_pressure = (int16_t)((buffer[0] << 8) | buffer[1]);
    return 0;
}

// Function to convert raw sensor data to pressure in Pascals
float convert_to_pressure(int16_t raw_pressure) {
    // Apply calibration parameters here
    float pressure = (float)raw_pressure * sensor_calibration.sensitivity + sensor_calibration.zero_offset;
    return pressure;
}

// Function to convert pressure to flow rate in SLPM
float convert_to_flow_rate(float pressure) {
    // Linear conversion: 0 Pa -> 0 SLPM, 100 Pa -> 100 SLPM
    return (pressure - PRESSURE_MIN) * (FLOW_RATE_MAX - FLOW_RATE_MIN) / (PRESSURE_MAX - PRESSURE_MIN) + FLOW_RATE_MIN;
}

