        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output for PWM
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);

    // Initialize I2C communication
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("flow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t raw_pressure;
    float pressure, flow_rate;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&raw_pressure) == 0) {
            // Convert to pressure
            pressure = convert_to_pressure(raw_pressure);

            // Convert to flow rate
            flow_rate = convert_to_flow_rate(pressure);

            // Set fan speed
            set_fan_speed(flow_rate);

            // Log data
            log_data(pressure, flow_rate);

            printf("Pressure: %.2f Pa, Flow Rate: %.2f SLPM\n", pressure, flow_rate);
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

