#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// LPS33HW I2C address
#define LPS33HW_ADDR 0x5C

// LPS33HW register addresses
#define CTRL_REG1 0x20
#define PRESS_OUT_XL 0x28
#define PRESS_OUT_L 0x29
#define PRESS_OUT_H 0x2A
#define TEMP_OUT_L 0x2B
#define TEMP_OUT_H 0x2C

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int init_sensor();
sensor_data_t read_sensor_data();
float convert_pressure(int32_t raw_pressure);
float convert_temperature(int16_t raw_temperature);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        terminate = 1;
        printf("Received SIGINT. Exiting gracefully.\n");
    }
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, LPS33HW_ADDR, 0); // Bus 1, address 0x5C, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize the LPS33HW sensor
int init_sensor() {
    // Enable continuous data acquisition (ODR = 1 Hz)
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0xB0) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }
    return 0;
}

// Read raw pressure and temperature data from the sensor
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    int32_t raw_pressure;
    int16_t raw_temperature;
    char buffer[5];

    // Read pressure data (3 bytes)
    if (i2cReadI2CBlockData(i2c_handle, PRESS_OUT_XL, buffer, 3) != 3) {
        fprintf(stderr, "Error reading pressure data\n");
        data.pressure = -1.0; // Indicate error
    } else {
        raw_pressure = (int32_t)buffer[0] | ((int32_t)buffer[1] << 8) | ((int32_t)buffer[2] << 16);
        data.pressure = convert_pressure(raw_pressure);
    }

    // Read temperature data (2 bytes)
    if (i2cReadI2CBlockData(i2c_handle, TEMP_OUT_L, buffer, 2) != 2) {
        fprintf(stderr, "Error reading temperature data\n");
        data.temperature = -1000.0; // Indicate error
    } else {
        raw_temperature = (int16_t)buffer[0] | ((int16_t)buffer[1] << 8);
        data.temperature = convert_temperature(raw_temperature);
    }

    return data;
}

// Convert raw pressure data to hPa
float convert_pressure(int32_t raw_pressure) {
    return (float)raw_pressure / 4096.0;
}

// Convert raw temperature data to Celsius
float convert_temperature(int16_t raw_temperature) {
    return 42.5 + (float)raw_temperature / 480.0;
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t t = time(NULL);
    struct tm tm = *localtime_r(&t, &tm);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (data.pressure == -1.0 || data.temperature == -1000.0) {
        fprintf(log_file, "%s, Error reading sensor data\n", timestamp);
        fprintf(stderr, "%s, Error reading sensor data\n", timestamp);
    } else {
        fprintf(log_file, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n", timestamp, data.pressure, data.temperature);
        fprintf(stderr, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n", timestamp, data.pressure, data.temperature);
    }

    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize sensor
    if (init_sensor() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        sensor_data_t data = read_sensor_data();
        log_data(data);
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

