        fprintf(stderr, "Error reading pressure data\n");
        data.pressure = -1.0; // Indicate error
    } else {
        raw_pressure = (int32_t)buffer[0] | ((int32_t)buffer[1] << 8) | ((int32_t)buffer[2] << 16);
        data.pressure = convert_pressure(raw_pressure);
    }

    // Read temperature data (2 bytes)
    if (i2cReadI2CBlockData(i2c_handle, TEMP_OUT_L, buffer, 2) != 2) {
        fprintf(stderr, "Error reading temperature data\n");
        data.temperature = -1000.0; // Indicate error
    } else {
        raw_temperature = (int16_t)buffer[0] | ((int16_t)buffer[1] << 8);
        data.temperature = convert_temperature(raw_temperature);
    }

    return data;
}

// Convert raw pressure data to hPa
float convert_pressure(int32_t raw_pressure) {
    return (float)raw_pressure / 4096.0;
}

// Convert raw temperature data to Celsius
float convert_temperature(int16_t raw_temperature) {
    return 42.5 + (float)raw_temperature / 480.0;
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t t = time(NULL);
    struct tm tm = *localtime_r(&t, &tm);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (data.pressure == -1.0 || data.temperature == -1000.0) {
