#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// SCD30 I2C address
#define SCD30_ADDR 0x61

// SCD30 commands
#define CMD_START_PERIODIC_MEASUREMENT 0x0010
#define CMD_READ_MEASUREMENT 0x0300
#define CMD_STOP_PERIODIC_MEASUREMENT 0x0104
#define CMD_SET_MEASUREMENT_INTERVAL 0x4600
#define CMD_GET_DATA_READY 0x0202

// Ventilation control thresholds
#define CO2_LOW_THRESHOLD 800.0
#define CO2_HIGH_THRESHOLD 1200.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_pigpio();
int open_i2c_connection();
int start_periodic_measurement();
int read_measurement(sensor_data_t *data);
int stop_periodic_measurement();
int set_measurement_interval(int interval);
int get_data_ready(int *ready);
int log_data(sensor_data_t data);
void ventilation_control(float co2);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open I2C connection
int open_i2c_connection() {
    i2c_handle = i2cOpen(1, SCD30_ADDR, 0); // Bus 1, address 0x61, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to start periodic measurement
int start_periodic_measurement() {
    unsigned char cmd[2] = {(CMD_START_PERIODIC_MEASUREMENT >> 8) & 0xFF, CMD_START_PERIODIC_MEASUREMENT & 0xFF};
    int result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to start periodic measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read measurement data
int read_measurement(sensor_data_t *data) {
    unsigned char cmd[2] = {(CMD_READ_MEASUREMENT >> 8) & 0xFF, CMD_READ_MEASUREMENT & 0xFF};
    unsigned char buffer[18];
    int result;

    result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to send read measurement command: %d\n", result);
        return -1;
    }

    gpioDelay(1); // Small delay after sending the command

    result = i2cReadDevice(i2c_handle, (char *)buffer, 18);
    if (result != 18) {
        fprintf(stderr, "Failed to read measurement data: %d\n", result);
        return -1;
    }

    // CRC check
    if (crc8(buffer, 2) != buffer[2] ||
        crc8(buffer + 3, 2) != buffer[5] ||
        crc8(buffer + 6, 2) != buffer[8] ||
        crc8(buffer + 9, 2) != buffer[11] ||
        crc8(buffer + 12, 2) != buffer[14] ||
        crc8(buffer + 15, 2) != buffer[17]) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    // Convert data
    int co2_raw = (buffer[0] << 8) | buffer[1];
    int temp_raw = (buffer[3] << 8) | buffer[4];
    int hum_raw = (buffer[6] << 8) | buffer[7];

    data->co2 = (float)co2_raw;
    data->temperature = -45 + 175 * (float)temp_raw / 65535.0;
    data->humidity = 100 * (float)hum_raw / 65535.0;

    return 0;
}

// Function to stop periodic measurement
int stop_periodic_measurement() {
    unsigned char cmd[2] = {(CMD_STOP_PERIODIC_MEASUREMENT >> 8) & 0xFF, CMD_STOP_PERIODIC_MEASUREMENT & 0xFF};
    int result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to stop periodic measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to set measurement interval
int set_measurement_interval(int interval) {
    unsigned char cmd[3] = {(CMD_SET_MEASUREMENT_INTERVAL >> 8) & 0xFF, CMD_SET_MEASUREMENT_INTERVAL & 0xFF, interval};
    int result = i2cWriteDevice(i2c_handle, (char *)cmd, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to set measurement interval: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to get data ready status
int get_data_ready(int *ready) {
    unsigned char cmd[2] = {(CMD_GET_DATA_READY >> 8) & 0xFF, CMD_GET_DATA_READY & 0xFF};
    unsigned char buffer[3];
    int result;

    result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to send get data ready command: %d\n", result);
        return -1;
    }

    gpioDelay(1); // Small delay after sending the command

    result = i2cReadDevice(i2c_handle, (char *)buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Failed to read data ready status: %d\n", result);
        return -1;
    }

    *ready = (buffer[0] << 8) | buffer[1];

    return 0;
}

// Function to log data to file
int log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, data.co2, data.temperature, data.humidity);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Function to control ventilation based on CO2 level
void ventilation_control(float co2) {
    if (co2 < CO2_LOW_THRESHOLD) {
        printf("Ventilation: OFF\n");
    } else if (co2 < CO2_HIGH_THRESHOLD) {
        printf("Ventilation: LOW\n");
    } else {
        printf("Ventilation: HIGH\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        stop_periodic_measurement();
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C connection
    if (open_i2c_connection() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Start periodic measurement
    if (start_periodic_measurement() != 0) {
        cleanup();
        return 1;
    }

    // Set measurement interval to 5 seconds
    if (set_measurement_interval(5) != 0) {
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;
    int data_ready;

    // Main loop
    while (!terminate) {
        // Check if data is ready
        if (get_data_ready(&data_ready) == 0 && data_ready > 0) {
            // Read measurement data
            if (read_measurement(&sensor_data) == 0) {
                // Log data
                log_data(sensor_data);

                // Control ventilation
                ventilation_control(sensor_data.co2);
            } else {
                fprintf(stderr, "Failed to read sensor data\n");
            }
        } else {
            //fprintf(stderr, "Data not ready yet\n");
        }

        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

