    return 0;
}

// Function to stop periodic measurement
int stop_periodic_measurement() {
    unsigned char cmd[2] = {(CMD_STOP_PERIODIC_MEASUREMENT >> 8) & 0xFF, CMD_STOP_PERIODIC_MEASUREMENT & 0xFF};
    int result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to stop periodic measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to set measurement interval
int set_measurement_interval(int interval) {
    unsigned char cmd[3] = {(CMD_SET_MEASUREMENT_INTERVAL >> 8) & 0xFF, CMD_SET_MEASUREMENT_INTERVAL & 0xFF, interval};
    int result = i2cWriteDevice(i2c_handle, (char *)cmd, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to set measurement interval: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to get data ready status
int get_data_ready(int *ready) {
    unsigned char cmd[2] = {(CMD_GET_DATA_READY >> 8) & 0xFF, CMD_GET_DATA_READY & 0xFF};
    unsigned char buffer[3];
    int result;

    result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to send get data ready command: %d\n", result);
        return -1;
    }

    gpioDelay(1); // Small delay after sending the command

    result = i2cReadDevice(i2c_handle, (char *)buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Failed to read data ready status: %d\n", result);
        return -1;
    }

    *ready = (buffer[0] << 8) | buffer[1];

    return 0;
}

// Function to log data to file
int log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, data.co2, data.temperature, data.humidity);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Function to control ventilation based on CO2 level
void ventilation_control(float co2) {
    if (co2 < CO2_LOW_THRESHOLD) {
        printf("Ventilation: OFF\n");
    } else if (co2 < CO2_HIGH_THRESHOLD) {
        printf("Ventilation: LOW\n");
    } else {
        printf("Ventilation: HIGH\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        stop_periodic_measurement();
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C connection
    if (open_i2c_connection() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Start periodic measurement
    if (start_periodic_measurement() != 0) {
        cleanup();
        return 1;
    }

    // Set measurement interval to 5 seconds
    if (set_measurement_interval(5) != 0) {
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;
    int data_ready;

    // Main loop
    while (!terminate) {
        // Check if data is ready
        if (get_data_ready(&data_ready) == 0 && data_ready > 0) {
            // Read measurement data
            if (read_measurement(&sensor_data) == 0) {
                // Log data
                log_data(sensor_data);

                // Control ventilation
                ventilation_control(sensor_data.co2);
            } else {
                fprintf(stderr, "Failed to read sensor data\n");
            }
        } else {
            //fprintf(stderr, "Data not ready yet\n");
        }

        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

