#define SDP32_TRIGGER_MEASUREMENT 0x362F

// Global variables
int i2c_handle;
int sampling_interval_ms = 1000;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t pressure;
    int16_t temperature;
    int16_t scale_factor;
} sensor_data_t;

