int initialize_i2c();
int read_sdp32(sensor_data_t *data);
int verify_crc(uint8_t data[], int len);
void process_data(sensor_data_t data);
void print_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C communication
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

