        fprintf(stderr, "Failed to write trigger command\n");
        return -1;
    }

    gpioDelay(50); // Wait for measurement (adjust as needed)

    if (i2cReadDevice(i2c_handle, buf, 9) != 9) {
        fprintf(stderr, "Failed to read data from sensor\n");
        return -1;
    }

