#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <string.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define SDP810_ADDR 0x25

// Define the trigger command
#define TRIGGER_COMMAND 0x362F

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// CRC-8 polynomial and initial value
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF

// Function prototypes
int initialize_i2c();
int read_sensor_data(sensor_data_t *data);
float convert_pressure(int16_t raw_pressure);
float convert_temperature(int16_t raw_temperature);
uint8_t crc8(const uint8_t *data, int len);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Cleanup function to close I2C and terminate pigpio
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

// Function to initialize the I2C bus
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buf[9];
    int16_t raw_pressure, raw_temperature;
    uint8_t crc_pressure, crc_temperature;

    // Send the trigger command
    char trigger_cmd[2] = {(TRIGGER_COMMAND >> 8) & 0xFF, TRIGGER_COMMAND & 0xFF};
    if (i2cWriteDevice(i2c_handle, trigger_cmd, 2) != 0) {
        fprintf(stderr, "Failed to write trigger command\n");
        return -1;
    }

    // Wait for the conversion to complete (at least 45 ms)
    gpioDelay(45000); // 45 ms

    // Read 9 bytes of data
    if (i2cReadDevice(i2c_handle, buf, 9) != 9) {
        fprintf(stderr, "Failed to read sensor data\n");
        return -1;
    }

    // Extract raw pressure and temperature values
    raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    crc_pressure = buf[2];
    raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);
    crc_temperature = buf[5];

    // CRC validation
    if (crc8((uint8_t *)buf, 3) != crc_pressure) {
        fprintf(stderr, "Pressure CRC check failed\n");
        return -1;
    }

    if (crc8((uint8_t *)buf + 3, 3) != crc_temperature) {
        fprintf(stderr, "Temperature CRC check failed\n");
        return -1;
    }

    // Convert raw values to physical units
    data->pressure = convert_pressure(raw_pressure);
    data->temperature = convert_temperature(raw_temperature);

    return 0;
}

// Function to convert raw pressure to Pascals
float convert_pressure(int16_t raw_pressure) {
    // Scale factor from the datasheet (125 Pa range)
    const float scale_factor = 60.0f; // Pa
    return (float)raw_pressure / scale_factor;
}

// Function to convert raw temperature to degrees Celsius
float convert_temperature(int16_t raw_temperature) {
    // Scale factor from the datasheet (125 Pa range)
    const float scale_factor = 200.0f; // degrees Celsius
    return (float)raw_temperature / scale_factor;
}

// CRC-8 checksum calculation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    sensor_data_t sensor_data;
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Get current timestamp
            time(&current_time);
            time_info = localtime(&current_time);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

            // Log the data to stdout
            printf("%s, Pressure: %.2f Pa, Temperature: %.2f °C\n", timestamp, sensor_data.pressure, sensor_data.temperature);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

