#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI7051_ADDR 0x40
#define TEMP_MEASURE_CMD 0xE3
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define LOG_INTERVAL_SEC 5

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for sensor configuration
typedef struct {
    int i2c_bus;
    int i2c_address;
    int temp_measure_command;
} sensor_config_t;

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open the I2C device
int open_i2c_device(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Function to read temperature from the Si7051 sensor
float read_temperature(int handle) {
    char buf[2];
    int result;
    int retries = RETRY_COUNT;

    while (retries > 0) {
        result = i2cWriteByte(handle, TEMP_MEASURE_CMD);
        if (result == 0) {
            gpioDelay(30); // Wait for measurement (datasheet specifies 25ms)
            result = i2cReadDevice(handle, buf, 2);
            if (result == 2) {
                uint16_t raw_temperature = (buf[0] << 8) | buf[1];
                return (175.72 * raw_temperature / 65536.0) - 46.85;
            } else {
                fprintf(stderr, "I2C read failed (attempt %d): %d\n", RETRY_COUNT - retries + 1, result);
            }
        } else {
            fprintf(stderr, "I2C write failed (attempt %d): %d\n", RETRY_COUNT - retries + 1, result);
        }
        gpioDelay(RETRY_DELAY_MS);
        retries--;
    }

    fprintf(stderr, "Failed to read temperature after %d retries\n", RETRY_COUNT);
    return -1000.0; // Indicate error
}

// Function to log the temperature to the console
void log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("%s Temperature: %.2f °C\n", timestamp, temperature);
}

// Function to close the I2C device
void close_i2c_device(int handle) {
    i2cClose(handle);
}

// Function to terminate the pigpio library
void terminate_pigpio() {
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C device
    i2c_handle = open_i2c_device(I2C_BUS, SI7051_ADDR);
    if (i2c_handle < 0) {
        terminate_pigpio();
        return 1;
    }

    // Main loop
    while (!terminate) {
        float temperature = read_temperature(i2c_handle);
        if (temperature > -999.0) {
            log_temperature(temperature);
        } else {
            fprintf(stderr, "Failed to read temperature\n");
        }
        sleep(LOG_INTERVAL_SEC);
    }

    // Cleanup
    close_i2c_device(i2c_handle);
    terminate_pigpio();

    return 0;
}

