#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define MEASURE_CMD 0x362F // Trigger continuous measurement without averaging
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF
#define SAMPLE_INTERVAL_MS 45
#define LOG_FILE "pressure_log.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float differential_pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(sensor_data_t *data);
int validate_crc(uint8_t data[], int len);
void log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C communication
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read sensor data
int read_sensor_data(sensor_data_t *data) {
    char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    char buffer[9];

    // Send measurement command
    if (i2cWriteDevice(i2c_handle, cmd, 2) != 2) {
        fprintf(stderr, "Failed to write measurement command\n");
        return -1;
    }

    // Wait for measurement to complete
    gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Convert ms to microseconds

    // Read 9 bytes of data
    if (i2cReadDevice(i2c_handle, buffer, 9) != 9) {
        fprintf(stderr, "Failed to read sensor data\n");
        return -1;
    }

    // Validate CRC for each word
    if (!validate_crc((uint8_t *)buffer, 2) || !validate_crc((uint8_t *)buffer + 3, 2) || !validate_crc((uint8_t *)buffer + 6, 2)) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Convert data to physical units
    int16_t raw_pressure = (buffer[0] << 8) | buffer[1];
    int16_t raw_temperature = (buffer[3] << 8) | buffer[4];

    data->differential_pressure = (float)raw_pressure / 60.0; // Pa
    data->temperature = (float)raw_temperature / 200.0; // °C

    return 0;
}

// Validate CRC-8 checksum
int validate_crc(uint8_t data[], int len) {
    uint8_t crc = crc8(data, len - 1);
    return crc == data[len - 1];
}

// Log data to file
void log_data(sensor_data_t data) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, data.differential_pressure, data.temperature);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying in %d seconds...\n", SAMPLE_INTERVAL_MS / 1000);
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for the next sample
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

