#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Configuration
#define I2C_BUS 1
#define MLX90821_ADDR 0x60
#define PRESSURE_REG 0x00 // Example register address, check datasheet
#define LOG_FILE "pressure_log.csv"
#define MIN_PRESSURE 200.0
#define MAX_PRESSURE 250.0
#define RETRY_COUNT 3

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float pressure_kPa;
} sensor_data_t;

// Function prototypes
int initialize_pigpio();
int open_i2c_bus(int bus, int addr);
int read_pressure(int handle, float *pressure);
int log_pressure(FILE *fp, float pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return -1;
    }
    return handle;
}

// Read pressure from MLX90821
int read_pressure(int handle, float *pressure) {
    char buf[2];
    int result;

    for (int i = 0; i < RETRY_COUNT; ++i) {
        result = i2cReadDevice(handle, buf, 2);
        if (result == 2) {
            // Convert raw data to pressure (kPa) - Example conversion
            int16_t raw_pressure = (buf[0] << 8) | buf[1];
            *pressure = (float)raw_pressure / 10.0; // Example scaling
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %s\n", i + 1, strerror(errno));
            gpioDelay(10000); // Wait 10ms before retrying
        }
    }

    fprintf(stderr, "I2C read failed after %d retries\n", RETRY_COUNT);
    return -1; // Failure
}

// Log pressure to CSV file
int log_pressure(FILE *fp, float pressure) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f\n", timestamp, pressure) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    i2c_handle = open_i2c_bus(I2C_BUS, MLX90821_ADDR);
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Check if the file is empty and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,pressure_kPa\n");
        fflush(log_file);
    }
    fseek(log_file, 0, SEEK_END); // Reset file pointer to the end

    // Main loop
    float pressure;
    while (!terminate) {
        if (read_pressure(i2c_handle, &pressure) == 0) {
            if (log_pressure(log_file, pressure) != 0) {
                fprintf(stderr, "Failed to log pressure\n");
            }

            // Check pressure range
            if (pressure < MIN_PRESSURE || pressure > MAX_PRESSURE) {
                fprintf(stderr, "Warning: Pressure out of safe range: %.2f kPa\n", pressure);
            }
        } else {
            fprintf(stderr, "Failed to read pressure\n");
        }

        gpioDelay(1000000); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

