// Constants
#define I2C_BUS 1
#define HIH6130_ADDR 0x27
#define LOG_FILE "environmental_data.log"
#define LOG_FILE_SIZE_LIMIT 1048576 // 1 MB
#define MEASUREMENT_INTERVAL 5 // seconds
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
int initialize_i2c();
int read_sensor_data(uint8_t *data);
SensorData process_sensor_data(const uint8_t *data);
int log_data(SensorData data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, HIH6130_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Reads sensor data from the HIH6130
int read_sensor_data(uint8_t *data) {
    int result, retries = 0;

    while (retries < RETRY_COUNT) {
        result = i2cReadDevice(i2c_handle, (char *)data, 4);
        if (result == 4) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (attempt %d): %d\n", retries + 1, result);
            gpioDelay(1000); // Wait 1 ms before retrying
            retries++;
        }
    }

    fprintf(stderr, "Failed to read sensor data after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Processes the raw sensor data and converts it to temperature and humidity
SensorData process_sensor_data(const uint8_t *data) {
    SensorData sensor_data;
    uint16_t humidity_raw = (data[0] << 8) | data[1];
    uint16_t temperature_raw = (data[2] << 6) | (data[3] >> 2);

    // Validate sensor status bits
    if (data[0] & 0x08) {
        fprintf(stderr, "Error: Stale data.\n");
        sensor_data.temperature = -999.0; // Indicate error
        sensor_data.humidity = -999.0;
        return sensor_data;
    }
    if (data[0] & 0x04) {
        fprintf(stderr, "Error: In command mode.\n");
        sensor_data.temperature = -999.0; // Indicate error
        sensor_data.humidity = -999.0;
        return sensor_data;
    }
    if (data[0] & 0x02) {
        fprintf(stderr, "Error: Heater on.\n");
        sensor_data.temperature = -999.0; // Indicate error
        sensor_data.humidity = -999.0;
        return sensor_data;
    }

    // Convert raw data to temperature and humidity
    sensor_data.humidity = ((float)humidity_raw / 16383) * 100;
    sensor_data.temperature = ((float)temperature_raw / 16383) * 165 - 40;

    return sensor_data;
}

// Logs the temperature and humidity data to a file with an ISO-8601 timestamp
int log_data(SensorData data) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[32];

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    // Open log file in append mode
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    // Check file size and truncate if necessary
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size >= LOG_FILE_SIZE_LIMIT) {
        fclose(fp);
        fp = fopen(LOG_FILE, "w"); // Truncate the file
        if (fp == NULL) {
            fprintf(stderr, "Error truncating log file: %s\n", LOG_FILE);
            return -1;
        }
    } else {
        rewind(fp);
    }

    // Write data to log file
    fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, data.temperature, data.humidity);

    // Close log file
    fclose(fp);

    return 0;
}

// Cleans up resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    printf("Environmental data logger started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        uint8_t sensor_data[4];
        SensorData processed_data;

        // Read sensor data
        if (read_sensor_data(sensor_data) == 0) {
            // Process sensor data
            processed_data = process_sensor_data(sensor_data);

            // Log data
            if (processed_data.temperature != -999.0 && processed_data.humidity != -999.0) {
                if (log_data(processed_data) != 0) {
                    fprintf(stderr, "Error logging data.\n");
                }
            } else {
                fprintf(stderr, "Error: Invalid sensor data. Skipping logging.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        // Wait for the next measurement
        sleep(MEASUREMENT_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    printf("Environmental data logger stopped.\n");
    return 0;
}

