#include <unistd.h>

// Define GPIO pin for SENT data
#define SENT_GPIO 4

// Define timeout duration in milliseconds
#define TIMEOUT_MS 100

// Define log file name
#define LOG_FILE "pressure_log.txt"

// Structure to hold sensor data
typedef struct {
    int status;
    int data1;
    int data2;
    int data3;
    int checksum;
} sensor_data_t;

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sent_data(sensor_data_t *data);
int decode_sent_data(int *pulse_widths, sensor_data_t *data);
float convert_to_pressure(int raw_pressure);
int log_pressure_data(float pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO using pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SENT_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENT_GPIO, PI_PUD_UP); // Enable pull-up resistor

    return 0;
}

// Read SENT data from the sensor
int read_sent_data(sensor_data_t *data) {
    int pulse_widths[32]; // Array to store pulse widths
    int i = 0;
    int level;
    int last_level = 1; // Initialize to a high level
    unsigned int start_time, end_time;

    // Wait for the start of the synchronization pulse
    start_time = gpioTick();
    while (gpioRead(SENT_GPIO) == 1 && running) {
        if (gpioTick() - start_time > TIMEOUT_MS * 1000) {
            fprintf(stderr, "Timeout waiting for start of synchronization pulse\n");
            return -1;
        }
    }
    if (!running) return -1;

    start_time = gpioTick();
    while (gpioRead(SENT_GPIO) == 0 && running) {
        if (gpioTick() - start_time > TIMEOUT_MS * 1000) {
            fprintf(stderr, "Timeout waiting for end of synchronization pulse\n");
            return -1;
        }
    }
    if (!running) return -1;

    // Read pulse widths
    while (i < 32 && running) {
        start_time = gpioTick();
        while (gpioRead(SENT_GPIO) == last_level && running) {
            if (gpioTick() - start_time > TIMEOUT_MS * 1000) {
                fprintf(stderr, "Timeout waiting for level change\n");
                return -1;
            }
        }
        if (!running) return -1;

        end_time = gpioTick();
        pulse_widths[i] = end_time - start_time;
        last_level = gpioRead(SENT_GPIO);
        i++;
    }

    if (!running) return -1;

    // Decode the SENT data
    if (decode_sent_data(pulse_widths, data) != 0) {
        fprintf(stderr, "Failed to decode SENT data\n");
        return -1;
    }

    return 0;
}

// Decode SENT data from pulse widths
int decode_sent_data(int *pulse_widths, sensor_data_t *data) {
    // Check for valid pulse widths
    for (int i = 0; i < 32; i++) {
        if (pulse_widths[i] < 12 || pulse_widths[i] > 271) {
            fprintf(stderr, "Invalid pulse width: %d\n", pulse_widths[i]);
            return -1;
        }
    }

    // Extract nibbles from pulse widths
    data->status = (pulse_widths[0] > 150) ? 1 : 0; // Example: 150us is considered a '1'
    data->data1 = (pulse_widths[1] > 150) ? 1 : 0;
    data->data2 = (pulse_widths[2] > 150) ? 1 : 0;
    data->data3 = (pulse_widths[3] > 150) ? 1 : 0;
    data->checksum = (pulse_widths[4] > 150) ? 1 : 0;

    // Validate checksum (example: simple XOR)
    int calculated_checksum = data->status ^ data->data1 ^ data->data2 ^ data->data3;
    if (calculated_checksum != data->checksum) {
        fprintf(stderr, "Checksum mismatch: calculated = %d, received = %d\n", calculated_checksum, data->checksum);
        return -1;
    }

    return 0;
}

// Convert raw pressure data to Pascals
float convert_to_pressure(int raw_pressure) {
    // Implement the conversion formula from the MLX90824 datasheet
    // This is a placeholder; replace with the actual formula
    float pressure = (float)raw_pressure * 0.1; // Example conversion
    return pressure;
}

// Log pressure data to a file
int log_pressure_data(float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Pressure: %.2f Pa\n", timestamp, pressure);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open\n");
        return -1;
    }
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;
    float pressure;

    printf("Starting pressure monitoring...\n");

    while (running) {
        // Read SENT data
        if (read_sent_data(&sensor_data) == 0) {
            // Convert raw data to pressure
            pressure = convert_to_pressure(sensor_data.data1); // Example: using data1 for pressure

            // Log pressure data
            if (log_pressure_data(pressure) != 0) {
                fprintf(stderr, "Error logging pressure data\n");
            }
        } else {
            fprintf(stderr, "Error reading SENT data\n");
        }

        // Delay before next reading
        gpioDelay(100); // 100ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

