#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_HIGH_PRECISION 0xFD
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF
#define LOG_FILE "environmental_data.txt"
#define SAMPLE_INTERVAL_SEC 5

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sht40_data(uint8_t *data);
uint8_t calculate_crc8(const uint8_t *data, int len);
int validate_crc8(const uint8_t *data, int len);
sensor_data_t convert_data(const uint8_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t calculate_crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC-8 validation function
int validate_crc8(const uint8_t *data, int len) {
    if (len < 2) return 0; // Need at least 2 bytes for data and CRC
    uint8_t crc = calculate_crc8(data, len - 1);
    return (crc == data[len - 1]);
}

// Function to initialize the I2C interface
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read data from the SHT40 sensor
int read_sht40_data(uint8_t *data) {
    if (i2cWriteByte(i2c_handle, MEASURE_HIGH_PRECISION) != 0) {
        fprintf(stderr, "Failed to write measurement command\n");
        return -1;
    }

    gpioDelay(10); // Wait for measurement (at least 8.5ms)

    int bytes_read = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (bytes_read != 6) {
        fprintf(stderr, "Failed to read 6 bytes from sensor: %d\n", bytes_read);
        return -1;
    }

    return 0;
}

// Function to convert raw data to temperature and humidity
sensor_data_t convert_data(const uint8_t *data) {
    sensor_data_t sensor_data;

    // Validate CRC for temperature
    if (!validate_crc8(data, 2)) {
        fprintf(stderr, "Temperature CRC validation failed\n");
        sensor_data.temperature = -999.0; // Indicate error
    } else {
        uint16_t temperature_raw = (data[0] << 8) | data[1];
        sensor_data.temperature = -45.0 + 175.0 * (float)temperature_raw / 65535.0;
    }

    // Validate CRC for humidity
    if (!validate_crc8(data + 3, 2)) {
        fprintf(stderr, "Humidity CRC validation failed\n");
        sensor_data.humidity = -999.0; // Indicate error
    } else {
        uint16_t humidity_raw = (data[3] << 8) | data[4];
        sensor_data.humidity = -6.0 + 125.0 * (float)humidity_raw / 65535.0;
        if (sensor_data.humidity > 100.0) sensor_data.humidity = 100.0; // Clamp to 100%
    }

    return sensor_data;
}

// Function to log data to a file
int log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (data.temperature == -999.0 || data.humidity == -999.0) {
        fprintf(log_file, "%s, ERROR: CRC validation failed\n", timestamp);
    } else {
        fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, data.temperature, data.humidity);
    }

    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to close resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    uint8_t data[6];
    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read data from sensor
        if (read_sht40_data(data) == 0) {
            // Convert data
            sensor_data = convert_data(data);

            // Log data
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

