#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define BUFFER_SIZE 100
#define SAMPLE_INTERVAL_SEC 5
#define LOG_FILE "temperature_log.dat"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for circular buffer
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

CircularBuffer temp_buffer;

// Function prototypes
int init_i2c();
float read_temperature();
void add_to_buffer(float temperature);
float get_from_buffer(int index);
int save_buffer_to_file(const char *filename);
void signal_handler(int signal);
void cleanup();

// Initialize circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Function to initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read temperature from TMP117
float read_temperature() {
    char buf[2];
    int16_t raw_temp;
    float temperature;

    if (i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2) != 2) {
        fprintf(stderr, "Failed to read temperature data\n");
        return -1000.0; // Indicate error with a very low temperature
    }

    raw_temp = (buf[0] << 8) | buf[1];
    temperature = raw_temp * 0.0078125; // Convert to Celsius

    return temperature;
}

// Function to add temperature to circular buffer
void add_to_buffer(float temperature) {
    temp_buffer.buffer[temp_buffer.head] = temperature;
    temp_buffer.head = (temp_buffer.head + 1) % BUFFER_SIZE;
    if (temp_buffer.count < BUFFER_SIZE) {
        temp_buffer.count++;
    }
}

// Function to get temperature from circular buffer
float get_from_buffer(int index) {
    if (index < 0 || index >= temp_buffer.count) {
        fprintf(stderr, "Index out of bounds\n");
        return -1000.0; // Indicate error
    }
    return temp_buffer.buffer[(temp_buffer.head - temp_buffer.count + index + BUFFER_SIZE) % BUFFER_SIZE];
}

// Function to save buffer to file
int save_buffer_to_file(const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file for writing\n");
        return -1;
    }

