#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// SHTC3 I2C address
#define SHTC3_ADDR 0x70

// SHTC3 commands
#define SHTC3_MEASURE_HIGH_REPEATABILITY 0x7866

// CRC-8 polynomial and initial value
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_shtc3_data(uint8_t *data);
uint8_t calculate_crc(const uint8_t *data, int len);
int validate_crc(const uint8_t *data, int len);
sensor_data_t convert_data(const uint8_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, SHTC3_ADDR, 0); // Bus 1, address 0x70, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read data from SHTC3 sensor
int read_shtc3_data(uint8_t *data) {
    char cmd[2] = {(SHTC3_MEASURE_HIGH_REPEATABILITY >> 8) & 0xFF, SHTC3_MEASURE_HIGH_REPEATABILITY & 0xFF};
    int result;

    result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write command to SHTC3: %d\n", result);
        return -1;
    }

    gpioDelay(12); // Wait for measurement (at least 12.4 ms)

    result = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Failed to read data from SHTC3: %d\n", result);
        return -1;
    }

    return 0;
}

// Calculate CRC-8 checksum
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC checksum
int validate_crc(const uint8_t *data, int len) {
    uint8_t crc_calculated = calculate_crc(data, len);
    uint8_t crc_received = data[len];

    return (crc_calculated == crc_received);
}

// Convert raw data to temperature and humidity
sensor_data_t convert_data(const uint8_t *data) {
    sensor_data_t sensor_data;
    uint16_t temperature_raw = (data[0] << 8) | data[1];
    uint16_t humidity_raw = (data[3] << 8) | data[4];

    sensor_data.temperature = 175.0 * temperature_raw / 65535.0 - 45.0;
    sensor_data.humidity = 100.0 * humidity_raw / 65535.0;

    return sensor_data;
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    uint8_t data[6];
    sensor_data_t sensor_data;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("shtc3_environment.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read data from SHTC3
        if (read_shtc3_data(data) == 0) {
            // Validate CRC
            if (validate_crc(data, 2) && validate_crc(data + 3, 2)) {
                // Convert data
                sensor_data = convert_data(data);

                // Validate sensor readings
                if (sensor_data.temperature >= -40.0 && sensor_data.temperature <= 125.0 &&
                    sensor_data.humidity >= 0.0 && sensor_data.humidity <= 100.0) {
                    // Log data
                    if (log_data(sensor_data) == 0) {
                        // Print data to stdout
                        printf("%.2f,%.2f\n", sensor_data.temperature, sensor_data.humidity);
                    } else {
                        fprintf(stderr, "Failed to log data\n");
                    }
                } else {
                    fprintf(stderr, "Sensor reading out of range: Temperature=%.2f, Humidity=%.2f\n",
                            sensor_data.temperature, sensor_data.humidity);
                }
            } else {
                fprintf(stderr, "CRC validation failed\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

