#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI7202_ADDR 0x40
#define ROTATIONAL_SPEED_REG 0x00 // Example register, adjust as needed
#define TEMPERATURE_REG 0x02      // Example register, adjust as needed
#define LOG_FILE "mag_temp_log.csv"
#define SAMPLE_INTERVAL_SEC 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_sensor_data(float *rotational_speed, float *temperature);
int log_data(float rotational_speed, float temperature);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float rotational_speed;
    float temperature;
} sensor_data_t;

// Function to initialize the I2C bus
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7202_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(float *rotational_speed, float *temperature) {
    char buf[4];
    int result;

    // Read rotational speed
    result = i2cReadI2CBlockData(i2c_handle, ROTATIONAL_SPEED_REG, buf, 4);
    if (result != 4) {
        fprintf(stderr, "Failed to read rotational speed data: %d\n", result);
        *rotational_speed = NAN; // Indicate error with NaN
        return -1;
    }
    // Convert raw data to rotational speed (example conversion)
    int32_t raw_speed = (buf[0] << 24) | (buf[1] << 16) | (buf[2] << 8) | buf[3];
    *rotational_speed = (float)raw_speed / 100.0; // Example scaling

    // Read temperature
    result = i2cReadI2CBlockData(i2c_handle, TEMPERATURE_REG, buf, 4);
    if (result != 4) {
        fprintf(stderr, "Failed to read temperature data: %d\n", result);
        *temperature = NAN; // Indicate error with NaN
        return -1;
    }
    // Convert raw data to temperature (example conversion)
    int32_t raw_temp = (buf[0] << 24) | (buf[1] << 16) | (buf[2] << 8) | buf[3];
    *temperature = (float)raw_temp / 100.0; // Example scaling

    return 0;
}

// Function to log data to a file
int log_data(float rotational_speed, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, rotational_speed, temperature);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Cleanup function to close resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    sensor_data_t sensor_data;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed, exiting\n");
        return 1;
    }

    // Open log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file, exiting\n");
        cleanup();
        return 1;
    }

    // Check if the file is empty, if so, write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,RotationalSpeed,Temperature\n");
        fflush(log_file);
    }
    fseek(log_file, 0, SEEK_END); // Reset file pointer to the end

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data.rotational_speed, &sensor_data.temperature) == 0) {
            // Log data
            if (log_data(sensor_data.rotational_speed, sensor_data.temperature) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            // Log NaN values if sensor read failed
            if (log_data(NAN, NAN) != 0) {
                fprintf(stderr, "Failed to log NaN values\n");
            }
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

