#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define DHT11_GPIO 4
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100
#define READ_INTERVAL_SEC 2

// Structure to hold DHT11 data
typedef struct {
    int humidity_integer;
    int humidity_decimal;
    int temperature_integer;
    int temperature_decimal;
    int checksum;
} DHT11Data;

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static FILE *data_file = NULL;

// Function prototypes
int initialize_gpio();
int read_dht11_data(DHT11Data *data);
int validate_checksum(const DHT11Data *data);
int log_error(const char *message, int status_code);
int log_data(const DHT11Data *data);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO using pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(DHT11_GPIO, PI_OUTPUT);
    gpioWrite(DHT11_GPIO, 1); // Set high initially
    gpioDelay(100); // Wait for sensor to settle

    return 0;
}

// Function to read DHT11 data
int read_dht11_data(DHT11Data *data) {
    int retries = 0;
    int timeout;
    int i, j;
    int bit_count = 0;
    int data_bits[40] = {0};

    while (retries < MAX_RETRIES) {
        // Send start signal
        gpioSetMode(DHT11_GPIO, PI_OUTPUT);
        gpioWrite(DHT11_GPIO, 0);
        gpioDelay(18); // 18ms
        gpioWrite(DHT11_GPIO, 1);
        gpioDelay(20); // 20us

        // Switch to input mode to read response
        gpioSetMode(DHT11_GPIO, PI_INPUT);

        // Wait for DHT11 to pull low (response signal)
        timeout = 0;
        while (gpioRead(DHT11_GPIO) == 1) {
            gpioDelay(1); // Wait 1 us
            timeout++;
            if (timeout > 100) {
                log_error("DHT11 response timeout (low)", -1);
                retries++;
                break;
            }
        }

        if (timeout > 100) continue; // Retry if timeout

        // Wait for DHT11 to pull high
        timeout = 0;
        while (gpioRead(DHT11_GPIO) == 0) {
            gpioDelay(1); // Wait 1 us
            timeout++;
            if (timeout > 100) {
                log_error("DHT11 response timeout (high)", -2);
                retries++;
                break;
            }
        }

        if (timeout > 100) continue; // Retry if timeout

        // Read 40 bits of data
        for (i = 0; i < 40; i++) {
            // Wait for low
            timeout = 0;
            while (gpioRead(DHT11_GPIO) == 1) {
                gpioDelay(1); // Wait 1 us
                timeout++;
                if (timeout > 100) {
                    log_error("DHT11 data timeout (low)", -3);
                    retries++;
                    break;
                }
