#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SHT31_ADDR 0x44
#define MEASUREMENT_COMMAND 0x2C06 // High repeatability, clock stretching disabled
#define DATA_LENGTH 6
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF
#define RETRY_COUNT 3
#define LOG_FILE "sht31d_data.log"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int initialize_pigpio();
int open_i2c_connection();
int send_measurement_command();
int read_sensor_data(uint8_t *data);
int validate_crc(uint8_t data[], int length);
sensor_data_t convert_data(uint8_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C connection
int open_i2c_connection() {
    i2c_handle = i2cOpen(I2C_BUS, SHT31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send measurement command
int send_measurement_command() {
    char command[2] = {(MEASUREMENT_COMMAND >> 8) & 0xFF, MEASUREMENT_COMMAND & 0xFF};
    int result = i2cWriteDevice(i2c_handle, command, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write measurement command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(uint8_t *data) {
    int bytes_read = i2cReadDevice(i2c_handle, (char *)data, DATA_LENGTH);
    if (bytes_read != DATA_LENGTH) {
        fprintf(stderr, "Failed to read sensor data: %d\n", bytes_read);
        return -1;
    }
    return 0;
}

// Validate CRC-8 checksum
int validate_crc(uint8_t data[], int length) {
    for (int i = 0; i < length; i += 2) {
        uint8_t crc = crc8(data + i, 2);
        if (crc != data[i + 2]) {
            fprintf(stderr, "CRC validation failed for data[%d]: calculated 0x%02X, received 0x%02X\n", i, crc, data[i + 2]);
            return -1;
        }
    }
    return 0;
}

// Convert raw data to temperature and humidity
sensor_data_t convert_data(uint8_t *data) {
    sensor_data_t sensor_data;
    int temperature_raw = (data[0] << 8) | data[1];
    int humidity_raw = (data[3] << 8) | data[4];

    sensor_data.temperature = -45.0 + (175.0 * (float)temperature_raw / 65535.0);
    sensor_data.humidity = 100.0 * (float)humidity_raw / 65535.0;

    return sensor_data;
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C connection
    if (open_i2c_connection() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    uint8_t data[DATA_LENGTH];
    sensor_data_t sensor_data;
    int retries;

    // Main loop
    while (!terminate) {
        retries = 0;
        while (retries < RETRY_COUNT) {
            // Send measurement command
            if (send_measurement_command() != 0) {
                fprintf(stderr, "Retry %d: Failed to send measurement command\n", retries + 1);
                retries++;
                gpioDelay(1000); // Wait 1 second before retrying
                continue;
            }

            // Wait for measurement (at least 15 ms)
            gpioDelay(15000);

            // Read sensor data
            if (read_sensor_data(data) != 0) {
                fprintf(stderr, "Retry %d: Failed to read sensor data\n", retries + 1);
                retries++;
                gpioDelay(1000); // Wait 1 second before retrying
                continue;
            }

            // Validate CRC
            if (validate_crc(data, DATA_LENGTH) != 0) {
                fprintf(stderr, "Retry %d: CRC validation failed\n", retries + 1);
                retries++;
                gpioDelay(1000); // Wait 1 second before retrying
                continue;
            }

            // Convert data
            sensor_data = convert_data(data);

            // Log data
            log_data(sensor_data);

            break; // Exit retry loop if successful
        }

        if (retries == RETRY_COUNT) {
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[32];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
            fprintf(stderr, "%s: Sensor read failed after %d retries\n", timestamp, RETRY_COUNT);
            fprintf(log_file, "%s,ERROR,ERROR\n", timestamp);
            fflush(log_file);
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

