    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    uint8_t data[DATA_LENGTH];
    sensor_data_t sensor_data;
    int retries;

    // Main loop
    while (!terminate) {
        retries = 0;
        while (retries < RETRY_COUNT) {
            // Send measurement command
            if (send_measurement_command() != 0) {
                fprintf(stderr, "Retry %d: Failed to send measurement command\n", retries + 1);
                retries++;
                gpioDelay(1000); // Wait 1 second before retrying
                continue;
            }

            // Wait for measurement (at least 15 ms)
            gpioDelay(15000);

            // Read sensor data
            if (read_sensor_data(data) != 0) {
                fprintf(stderr, "Retry %d: Failed to read sensor data\n", retries + 1);
                retries++;
                gpioDelay(1000); // Wait 1 second before retrying
                continue;
            }

            // Validate CRC
            if (validate_crc(data, DATA_LENGTH) != 0) {
                fprintf(stderr, "Retry %d: CRC validation failed\n", retries + 1);
                retries++;
                gpioDelay(1000); // Wait 1 second before retrying
                continue;
            }

            // Convert data
            sensor_data = convert_data(data);

            // Log data
            log_data(sensor_data);

            break; // Exit retry loop if successful
        }

        if (retries == RETRY_COUNT) {
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[32];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
            fprintf(stderr, "%s: Sensor read failed after %d retries\n", timestamp, RETRY_COUNT);
            fprintf(log_file, "%s,ERROR,ERROR\n", timestamp);
            fflush(log_file);
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

