#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define MLX90824_ADDR 0x60
#define LOG_FILE "pressure_log.txt"
#define READ_INTERVAL_SEC 2

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(sensor_data_t *data);
int log_data(sensor_data_t data);
void cleanup();
void signal_handler(int signal);
char* get_iso8601_timestamp();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to get ISO 8601 timestamp
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX90824_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buf[4];
    int result;

    // Read pressure data (2 bytes)
    result = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2); // Assuming pressure register is 0x00
    if (result != 2) {
        fprintf(stderr, "Error reading pressure data: %d\n", result);
        return -1;
    }
    int16_t raw_pressure = (buf[0] << 8) | buf[1];

    // Read temperature data (2 bytes)
    result = i2cReadI2CBlockData(i2c_handle, 0x02, buf, 2); // Assuming temperature register is 0x02
    if (result != 2) {
        fprintf(stderr, "Error reading temperature data: %d\n", result);
        return -1;
    }
    int16_t raw_temperature = (buf[0] << 8) | buf[1];

    // Convert raw data to physical units (example conversion, adjust as needed)
    data->pressure = (float)raw_pressure * 0.1; // kPa
    data->temperature = (float)raw_temperature * 0.01 - 40.0; // Celsius

    return 0;
}

// Function to log data to file
int log_data(sensor_data_t data) {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp for logging.\n");
        return -1;
    }

    fprintf(log_file, "%s, %.2f kPa, %.2f C\n", timestamp, data.pressure, data.temperature);
    fflush(log_file); // Ensure data is written to disk immediately
    free(timestamp);
    return 0;
}

// Function to cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            if (log_data(sensor_data) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            char *timestamp = get_iso8601_timestamp();
            if (timestamp != NULL) {
                fprintf(log_file, "%s, ERROR: Failed to read sensor data\n", timestamp);
                fflush(log_file);
                free(timestamp);
            } else {
                fprintf(stderr, "Failed to get timestamp for error logging.\n");
            }
        }

        sleep(READ_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

