// Configuration
#define I2C_BUS 1
#define LM75B_ADDR 0x48
#define FAN_GPIO 18
#define TEMP_THRESHOLD_ON 28.0
#define TEMP_THRESHOLD_OFF 26.0
#define SAMPLE_INTERVAL_SEC 1
#define BUFFER_SIZE 60

// Global variables
int i2c_handle;
bool fan_on = false;
double temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_i2c();
double read_temperature();
void add_to_buffer(double temperature);
double calculate_average();
void control_fan(double average_temperature);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int lm75b_address;
    int fan_gpio;
    double temp_threshold_on;
    double temp_threshold_off;
    int sample_interval_sec;
    int buffer_size;
} Config;

Config config = {
    .i2c_bus = I2C_BUS,
    .lm75b_address = LM75B_ADDR,
    .fan_gpio = FAN_GPIO,
    .temp_threshold_on = TEMP_THRESHOLD_ON,
    .temp_threshold_off = TEMP_THRESHOLD_OFF,
    .sample_interval_sec = SAMPLE_INTERVAL_SEC,
    .buffer_size = BUFFER_SIZE
};

