    // Initialize signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Read temperature
        double temperature = read_temperature();

        if (temperature != -1000.0) { // Check for error value
            // Add to buffer
            add_to_buffer(temperature);

            // Calculate average
            double average_temperature = calculate_average();

            // Control fan
            control_fan(average_temperature);

            // Print temperature and average
            printf("Temperature: %.2f °C, Average: %.2f °C, Fan: %s\n", temperature, average_temperature, fan_on ? "ON" : "OFF");
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
        }

        // Wait for the next sample
        sleep(config.sample_interval_sec);
    }

    return 0;
}

