    i2c_handle = i2cOpen(config.i2c_bus, config.lm75b_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

