        if (gpioWrite(config.fan_gpio, 0) != 0) {
            fprintf(stderr, "Error writing to GPIO: %s\n", strerror(errno));
        } else {
            fan_on = false;
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Cleanup resources
void cleanup() {
    // Stop the fan
    gpioWrite(config.fan_gpio, 0);

    // Close I2C handle
    i2cClose(i2c_handle);
}

