#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define STTS2004_ADDR 0x48
#define LED_GPIO 17
#define TEMP_HIGH 28.0
#define TEMP_LOW 27.0
#define I2C_RETRIES 3
#define I2C_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
float read_temperature();
void control_led(float temperature);
void log_temperature(float temperature);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int stts2004_address;
    int led_pin;
    float temp_high;
    float temp_low;
    int i2c_retries;
    int i2c_delay_ms;
} config_t;

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the system
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, STTS2004_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Initially turn LED off

    return 0;
}

// Function to read temperature from STTS2004
float read_temperature() {
    char buf[2];
    int result;
    int retries = I2C_RETRIES;

    while (retries > 0) {
        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) {
            // Combine the two bytes into a 16-bit integer
            int16_t raw_temp = (buf[0] << 8) | buf[1];

            // Convert raw temperature to Celsius (refer to STTS2004 datasheet)
            float temperature = (float)raw_temp / 256.0;

            return temperature;
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %s\n", I2C_RETRIES - retries + 1, strerror(errno));
            gpioDelay(I2C_DELAY_MS * 1000); // Delay in microseconds
            retries--;
        }
    }

    fprintf(stderr, "I2C read failed after %d retries\n", I2C_RETRIES);
    return -1000.0; // Indicate error
}

// Function to control the LED based on temperature
void control_led(float temperature) {
    if (temperature > TEMP_HIGH) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else if (temperature < TEMP_LOW) {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Function to log the temperature with timestamp
void log_temperature(float temperature) {
    time_t now = time(NULL);
