#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define MEASURE_CMD 0x362F // Continuous measurement without averaging
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT_VALUE 0xFF
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float differential_pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(uint8_t *data);
int validate_crc(uint8_t data[], int len);
sensor_data_t convert_data(uint8_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INIT_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data with retry mechanism
int read_sensor_data(uint8_t *data) {
    int retries = RETRY_COUNT;
    int bytes_read;

    while (retries > 0) {
        bytes_read = i2cReadDevice(i2c_handle, (char *)data, 9);
        if (bytes_read == 9) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (bytes read: %d), retrying...\n", bytes_read);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
        }
    }

    fprintf(stderr, "Failed to read sensor data after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Validate CRC-8 checksum
int validate_crc(uint8_t data[], int len) {
    uint8_t crc = crc8(data, len);
    return (crc == data[len]);
}

// Convert raw data to physical units
sensor_data_t convert_data(uint8_t *data) {
    sensor_data_t sensor_data;
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];

    // Scaling factors (from datasheet)
    float pressure_scale_factor = 60.0; // Pa
    float temperature_scale_factor = 200.0; // Degrees C

    sensor_data.differential_pressure = (float)raw_pressure / pressure_scale_factor;
    sensor_data.temperature = (float)raw_temperature / temperature_scale_factor;

    return sensor_data;
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f Pa, %.2f °C\n", timestamp, data.differential_pressure, data.temperature);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("flow_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    uint8_t sensor_data[9];
    sensor_data_t converted_data;

    // Main loop
    while (!terminate) {
        // Send measurement command
        char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
        if (i2cWriteDevice(i2c_handle, cmd, 2) != 2) {
            fprintf(stderr, "Error writing measurement command!\n");
            cleanup();
            return 1;
        }

        gpioDelay(45000); // Wait 45 ms

        // Read sensor data
        if (read_sensor_data(sensor_data) == 0) {
            // Validate CRC checksums
            if (validate_crc(sensor_data, 2) && validate_crc(sensor_data + 3, 2)) {
                // Convert data
                converted_data = convert_data(sensor_data);

                // Log data
                log_data(converted_data);

                printf("Pressure: %.2f Pa, Temperature: %.2f °C\n", converted_data.differential_pressure, converted_data.temperature);
            } else {
                fprintf(stderr, "CRC validation failed!\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        gpioDelay(100000); // Delay 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

