#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define TEMP_CMD 0xE3
#define HUMID_CMD 0xE5
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define SAMPLE_INTERVAL_SEC 60
#define LOG_FILE "environment.log"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(sensor_data_t *data);
float convert_temperature(uint16_t raw_temp);
float convert_humidity(uint16_t raw_humidity);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature and humidity data from the sensor
int read_sensor_data(sensor_data_t *data) {
    uint8_t buf[2];
    int result;

    // Measure temperature
    result = i2cWriteByte(i2c_handle, TEMP_CMD);
    if (result != 0) {
        fprintf(stderr, "Error writing temperature command: %d\n", result);
        return -1;
    }
    gpioDelay(20); // Wait for measurement (datasheet specifies 12.1ms for temp, 12.1ms for humidity)

    result = i2cReadDevice(i2c_handle, (char *)buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature data: %d\n", result);
        return -1;
    }
    uint16_t raw_temp = (buf[0] << 8) | buf[1];
    data->temperature = convert_temperature(raw_temp);

    // Measure humidity
    result = i2cWriteByte(i2c_handle, HUMID_CMD);
    if (result != 0) {
        fprintf(stderr, "Error writing humidity command: %d\n", result);
        return -1;
    }
    gpioDelay(20); // Wait for measurement

    result = i2cReadDevice(i2c_handle, (char *)buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading humidity data: %d\n", result);
        return -1;
    }
    uint16_t raw_humidity = (buf[0] << 8) | buf[1];
    data->humidity = convert_humidity(raw_humidity);

    return 0;
}

// Convert raw temperature data to Celsius
float convert_temperature(uint16_t raw_temp) {
    return (175.72 * raw_temp / 65536.0) - 46.85;
}

// Convert raw humidity data to percentage relative humidity
float convert_humidity(uint16_t raw_humidity) {
    return (125.0 * raw_humidity / 65536.0) - 6.0;
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);
    fflush(log_file); // Ensure data is written to disk immediately

    printf("%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);

    return 0;
}

