#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define STS40_ADDR 0x4A
#define MEASURE_HIGH_PRECISION 0xFD
#define CRC8_POLYNOMIAL 0x31
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL 5 // seconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int sts40_address;
    char *log_file_name;
    int sample_interval;
} config_t;

// Function prototypes
int init_i2c(int bus, int addr);
int read_temperature(int handle, float *temperature);
int log_temperature(FILE *fp, float temperature);
void signal_handler(int signal);
void cleanup();
uint8_t crc8(const uint8_t *data, int len);

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C communication
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Read temperature from STS40 sensor
int read_temperature(int handle, float *temperature) {
    char buf[3];
    int result;

    // Send measurement command
    result = i2cWriteByteData(handle, MEASURE_HIGH_PRECISION, 0); // No data to write, just the command
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Wait for conversion (at least 10 ms)
    gpioDelay(10000); // 10 ms

    // Read 3 bytes from the sensor
    result = i2cReadDevice(handle, buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // CRC check
    uint8_t crc = crc8((uint8_t *)buf, 2);
    if (crc != buf[2]) {
        fprintf(stderr, "CRC check failed: calculated 0x%02X, received 0x%02X\n", crc, buf[2]);
        return -1;
    }

    // Convert raw data to temperature (Celsius)
    int16_t raw_temperature = (buf[0] << 8) | buf[1];
    *temperature = -45.0 + (175.0 * raw_temperature) / 65535.0;

    return 0;
}

// Log temperature to file
int log_temperature(FILE *fp, float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[32];

    // Format timestamp in ISO 8601 format
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    // Write to log file
    if (fprintf(fp, "%s, %.2f\n", timestamp, temperature) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }

    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    float temperature;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    i2c_handle = init_i2c(I2C_BUS, STS40_ADDR);
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read temperature
        result = read_temperature(i2c_handle, &temperature);
        if (result == 0) {
            // Log temperature
            if (log_temperature(log_file, temperature) != 0) {
                fprintf(stderr, "Error logging temperature\n");
            }
        } else {
            fprintf(stderr, "Error reading temperature\n");
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

