    int temperature_raw = (read_buf[3] << 8) | read_buf[4];
    int humidity_raw = (read_buf[6] << 8) | read_buf[7];

    data->co2 = (float)co2_raw;
    data->temperature = -45 + 175 * ((float)temperature_raw / 65535);
    data->humidity = 100 * ((float)humidity_raw / 65535);

    return 0;
}

// CRC-8 calculation
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = CRC8_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC
int validate_crc(unsigned char data[], int len) {
    unsigned char crc = crc8(data, len - 1);
    return crc == data[len - 1];
}

// Add data to circular buffer
int add_to_buffer(circular_buffer_t *buffer, sensor_data_t data) {
    pthread_mutex_lock(&buffer->mutex);
    buffer->buffer[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count == BUFFER_SIZE) {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    } else {
        buffer->count++;
    }
    pthread_mutex_unlock(&buffer->mutex);
    return 0;
}

// Get data from circular buffer
int get_from_buffer(circular_buffer_t *buffer, sensor_data_t *data) {
    pthread_mutex_lock(&buffer->mutex);
    if (buffer->count == 0) {
        pthread_mutex_unlock(&buffer->mutex);
        return -1; // Buffer is empty
    }
    *data = buffer->buffer[buffer->tail];
    buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    buffer->count--;
    pthread_mutex_unlock(&buffer->mutex);
    return 0;
}

// Logging thread function
void *logging_thread_func(void *arg) {
    FILE *fp = NULL;
    char filename[256];
    time_t current_time;
    struct tm *time_info;
    sensor_data_t data;

    while (running) {
        sleep(60);

        // Create filename
        time(&current_time);
        time_info = localtime(&current_time);
        strftime(filename, sizeof(filename), LOG_DIR CSV_FILE_PREFIX "%Y%m%d_%H%M%S" CSV_FILE_SUFFIX, time_info);

        // Open file
        fp = fopen(filename, "w");
        if (fp == NULL) {
            log_error("Failed to open log file for writing");
            continue;
        }

        // Write header
        fprintf(fp, "Timestamp,CO2 (ppm),Temperature (C),Humidity (%%RH)\n");

        // Write data from buffer
        while (get_from_buffer(&data_buffer, &data) == 0) {
            fprintf(fp, "%s,%.2f,%.2f,%.2f\n", get_timestamp(), data.co2, data.temperature, data.humidity);
        }

        // Close file
        fclose(fp);
    }

    return NULL;
}

// Signal handler
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Log error message
void log_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open error log file");
        return;
    }

    char timestamp[32];
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tstruct);

    fprintf(fp, "%s: %s\n", timestamp, message);
    fclose(fp);
}

// Log data message
void log_data(sensor_data_t data) {
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open error log file");
        return;
    }

    char timestamp[32];
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tstruct);

    fprintf(fp, "%s: CO2: %.2f ppm, Temperature: %.2f C, Humidity: %.2f %%RH\n", timestamp, data.co2, data.temperature, data.humidity);
    fclose(fp);
}

// Get timestamp
char* get_timestamp() {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    static char timestamp[32]; // Static to persist across calls
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tstruct);
    return timestamp;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Create log directory if it doesn't exist
    if (mkdir(LOG_DIR, 0777) == -1) {
        // Ignore error if directory already exists
        // perror("mkdir failed");
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    data_buffer.head = 0;
    data_buffer.tail = 0;
    data_buffer.count = 0;
    pthread_mutex_init(&data_buffer.mutex, NULL);

    // Start periodic measurement
    if (start_periodic_measurement() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Create logging thread
    if (pthread_create(&logging_thread, NULL, logging_thread_func, NULL) != 0) {
        log_error("Failed to create logging thread");
        stop_periodic_measurement();
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set signal handler
    signal(SIGINT, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    sleep(1); // Wait for sensor to be ready
    while (running) {
        if (read_measurement(&sensor_data) == 0) {
            add_to_buffer(&data_buffer, sensor_data);
            log_data(sensor_data);
        } else {
            log_error("Failed to read sensor data");
        }
        sleep(5);
    }

    // Stop periodic measurement
    if (stop_periodic_measurement() != 0) {
        log_error("Failed to stop periodic measurement");
    }

    // Join logging thread
    pthread_join(logging_thread, NULL);

    // Flush remaining data to CSV file
    logging_thread_func(NULL);

    // Close I2C handle
    i2cClose(i2c_handle);

    // Clean up
    pthread_mutex_destroy(&data_buffer.mutex);
    gpioTerminate();

    return 0;
}

