#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// ICP-10110 I2C address
#define ICP10110_ADDR 0x69

// ICP-10110 register addresses
#define ICP10110_WHO_AM_I 0x71
#define ICP10110_RESET 0x80
#define ICP10110_MEASURE 0x07
#define ICP10110_PRESSURE_MSB 0x00
#define ICP10110_TEMPERATURE_MSB 0x03

// Calibration data registers
#define ICP10110_CALIB_START 0x31
#define ICP10110_CALIB_LENGTH 18

// Global variables
int i2c_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Calibration data structure
typedef struct {
    int32_t c0;
    int32_t c1;
    int32_t c00;
    int32_t c10;
    int32_t c01;
    int32_t c11;
    int32_t c20;
    int32_t c21;
    int32_t c30;
} icp10110_calibration_data_t;

icp10110_calibration_data_t calib_data;

// Function prototypes
int initialize_sensor();
int read_calibration_data();
int read_raw_data(int32_t *pressure, int32_t *temperature);
double convert_pressure(int32_t raw_pressure);
double convert_temperature(int32_t raw_temperature);
char* get_iso8601_timestamp();
int write_data_to_file(const char *timestamp, double pressure, double temperature);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C detected. Exiting gracefully...\n");
        terminate = 1;
    }
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
}

// Initialize the ICP-10110 sensor
int initialize_sensor() {
    // Reset the sensor
    if (i2cWriteByteData(i2c_handle, ICP10110_RESET, 0x89) < 0) {
        fprintf(stderr, "Error: Failed to reset sensor.\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Check WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, ICP10110_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error: Failed to read WHO_AM_I register.\n");
        return -1;
    }
    if (who_am_i != 0x41) {
        fprintf(stderr, "Error: Incorrect WHO_AM_I value: 0x%02X\n", who_am_i);
        return -1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Error: Failed to read calibration data.\n");
        return -1;
    }

    return 0;
}

// Read calibration data from the sensor
int read_calibration_data() {
    char buffer[ICP10110_CALIB_LENGTH];
    if (i2cReadI2CBlockData(i2c_handle, ICP10110_CALIB_START, buffer, ICP10110_CALIB_LENGTH) != ICP10110_CALIB_LENGTH) {
        fprintf(stderr, "Error: Failed to read calibration data block.\n");
        return -1;
    }

    calib_data.c0 = (int32_t)((((uint32_t)buffer[0]) << 4) | ((uint32_t)buffer[1] >> 4));
    calib_data.c1 = (int32_t)((((uint32_t)buffer[2]) << 4) | ((uint32_t)buffer[3] >> 4));
    calib_data.c00 = (int32_t)((((uint32_t)buffer[4]) << 12) | (((uint32_t)buffer[5]) << 4) | ((uint32_t)buffer[6] >> 4));
    calib_data.c10 = (int32_t)((((uint32_t)buffer[7]) << 12) | (((uint32_t)buffer[8]) << 4) | ((uint32_t)buffer[9] >> 4));
    calib_data.c01 = (int32_t)((((uint32_t)buffer[10]) << 8) | ((uint32_t)buffer[11]));
    calib_data.c11 = (int32_t)((((uint32_t)buffer[12]) << 8) | ((uint32_t)buffer[13]));
    calib_data.c20 = (int32_t)((((uint32_t)buffer[14]) << 8) | ((uint32_t)buffer[15]));
    calib_data.c21 = (int32_t)((((uint32_t)buffer[16]) << 8) | ((uint32_t)buffer[17]));

    // Sign extend if necessary
    if (calib_data.c0 & 0x800) calib_data.c0 |= 0xFFFFF000;
    if (calib_data.c1 & 0x800) calib_data.c1 |= 0xFFFFF000;
    if (calib_data.c00 & 0x8000) calib_data.c00 |= 0xFFF00000;
    if (calib_data.c10 & 0x8000) calib_data.c10 |= 0xFFF00000;
    if (calib_data.c01 & 0x8000) calib_data.c01 |= 0xFFFF0000;
    if (calib_data.c11 & 0x8000) calib_data.c11 |= 0xFFFF0000;
    if (calib_data.c20 & 0x8000) calib_data.c20 |= 0xFFFF0000;
    if (calib_data.c21 & 0x8000) calib_data.c21 |= 0xFFFF0000;

    return 0;
}

// Read raw pressure and temperature data from the sensor
int read_raw_data(int32_t *pressure, int32_t *temperature) {
