#include <signal.h>
#include <time.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define ICP10125_ADDR 0x69
#define GPIO_LED 17
#define PRESSURE_THRESHOLD 95000.0 // Pa
#define CRC_POLYNOMIAL 0x31
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(sensor_data_t *data);
uint8_t calculate_crc(const uint8_t *data, int len);
int verify_crc(const uint8_t *data, int len);
void control_led(float pressure);
void signal_handler(int signal);
void log_data(sensor_data_t data);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ICP10125_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from ICP-10125
int read_sensor_data(sensor_data_t *data) {
    uint8_t buffer[6];
    int result;
    int retries = 0;

    while (retries < RETRY_COUNT) {
        result = i2cReadDevice(i2c_handle, (char *)buffer, 6);
        if (result == 6) {
            // Verify CRC
            if (verify_crc(buffer, 2) && verify_crc(buffer + 2, 2)) {
                // Convert data
                int32_t raw_pressure = (buffer[0] << 8) | buffer[1];
                int32_t raw_temperature = (buffer[2] << 8) | buffer[3];

                // Placeholder conversion formulas (replace with actual formulas from datasheet)
                data->pressure = (float)raw_pressure * 10.0; // Example: Pa
                data->temperature = (float)raw_temperature / 100.0; // Example: C

                return 0; // Success
            } else {
                fprintf(stderr, "CRC check failed, retrying...\n");
            }
        } else {
            fprintf(stderr, "I2C read error: %d, retrying...\n", result);
        }
        retries++;
        gpioDelay(10); // Small delay before retrying
    }

    fprintf(stderr, "Failed to read sensor data after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Calculate CRC checksum
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Verify CRC checksum
int verify_crc(const uint8_t *data, int len) {
    uint8_t crc = calculate_crc(data, len);
    return crc == data[len];
}

// Control LED based on pressure
void control_led(float pressure) {
    if (pressure < PRESSURE_THRESHOLD) {
        // 5 Hz blinking
        gpioWrite(GPIO_LED, 1);
        gpioDelay(100);
        gpioWrite(GPIO_LED, 0);
        gpioDelay(100);
    } else {
        // 1 Hz blinking
        gpioWrite(GPIO_LED, 1);
        gpioDelay(500);
        gpioWrite(GPIO_LED, 0);
        gpioDelay(500);
    }
}

