            fprintf(stderr, "Failed to read sensor data.\n");
        }

        gpioDelay(20); // 20 ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(GPIO_LED, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

