#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_HIGH_PRECISION 0xFD
#define PORT 8080
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define BUFFER_SIZE 1024

// Global variables
int i2c_handle;
int server_fd;

// Function prototypes
int read_sht40(float *temperature, float *humidity);
int clamp_humidity(float humidity);
char *create_html_page(float temperature, float humidity);
void handle_client(int client_socket);
void signal_handler(int signal);

// Structure for sensor data (optional)
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function to read SHT40 sensor data
int read_sht40(float *temperature, float *humidity) {
    char cmd[1] = {MEASURE_HIGH_PRECISION};
    char buf[6];
    int result, retries;

    for (retries = 0; retries < MAX_RETRIES; retries++) {
        result = i2cWriteDevice(i2c_handle, cmd, 1);
        if (result != 0) {
            fprintf(stderr, "Error writing to I2C device: %d\n", result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        gpioDelay(10000); // Wait 10ms

        result = i2cReadDevice(i2c_handle, buf, 6);
        if (result != 6) {
            fprintf(stderr, "Error reading from I2C device: %d\n", result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        // Convert data
        unsigned short temp_raw = (buf[0] << 8) | buf[1];
        unsigned short hum_raw = (buf[3] << 8) | buf[4];

        *temperature = -45.0 + 175.0 * (float)temp_raw / 65535.0;
        *humidity = -6.0 + 125.0 * (float)hum_raw / 65535.0;

        return 0; // Success
    }

    fprintf(stderr, "Failed to read SHT40 after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to clamp humidity to 0-100%
int clamp_humidity(float humidity) {
    if (humidity < 0.0) {
        return 0;
    } else if (humidity > 100.0) {
        return 100;
    } else {
        return (int)humidity;
    }
}

// Function to create HTML page
char *create_html_page(float temperature, float humidity) {
    char *html_page = (char *)malloc(BUFFER_SIZE);
    if (html_page == NULL) {
        fprintf(stderr, "Failed to allocate memory for HTML page\n");
        return NULL;
    }

    snprintf(html_page, BUFFER_SIZE, 
             "HTTP/1.1 200 OK\r\n"
             "Content-Type: text/html\r\n"
             "\r\n"
             "<!DOCTYPE html><html><head><title>SHT40 Sensor Data</title></head><body>"
             "<h1>SHT40 Sensor Data</h1>"
             "<p>Temperature: %.2f &deg;C</p>"
             "<p>Humidity: %d %%</p>"
             "</body></html>",
             temperature, clamp_humidity(humidity));

    return html_page;
}

// Function to handle client connection
void handle_client(int client_socket) {
    float temperature, humidity;
    char *html_page;
    ssize_t bytes_received, bytes_sent;
    char buffer[BUFFER_SIZE];

    // Receive data from client (optional)
    bytes_received = recv(client_socket, buffer, BUFFER_SIZE - 1, 0);
    if (bytes_received > 0) {
        buffer[bytes_received] = '\0';
        printf("Received: %s\n", buffer);
    }

    // Read sensor data
    if (read_sht40(&temperature, &humidity) == 0) {
        // Create HTML page
        html_page = create_html_page(temperature, humidity);
        if (html_page != NULL) {
            // Send HTML page to client
            bytes_sent = send(client_socket, html_page, strlen(html_page), 0);
            if (bytes_sent < 0) {
                fprintf(stderr, "Error sending data to client\n");
            }
            free(html_page);
        } else {
            fprintf(stderr, "Failed to create HTML page\n");
        }
    } else {
        fprintf(stderr, "Failed to read sensor data\n");
    }

    // Close client socket
    close(client_socket);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (server_fd >= 0) {
        close(server_fd);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    struct sockaddr_in address;
    int addrlen = sizeof(address);
    int new_socket;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Create socket
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    // Bind socket to address
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        perror("listen failed");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Server listening on port %d\n", PORT);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Accept connection
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("accept failed");
            continue; // Continue listening
        }

        // Handle client connection
        handle_client(new_socket);
    }

    // Cleanup (should not reach here under normal circumstances due to signal handler)
    close(server_fd);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

