#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// HDC2010 I2C address
#define HDC2010_ADDR 0x40

// HDC2010 register addresses
#define TEMPERATURE_REG 0x00
#define HUMIDITY_REG 0x02
#define MEASUREMENT_CONFIG_REG 0x0F

// Measurement configuration values
#define TEMP_AND_HUMID_MEASURE 0x00

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCtrl+C pressed. Exiting gracefully...\n");
    terminate = 1;
}

// Function to initialize the HDC2010 sensor
int init_hdc2010() {
    // Configure the sensor for temperature and humidity measurement
    if (i2cWriteByteData(i2c_handle, MEASUREMENT_CONFIG_REG, TEMP_AND_HUMID_MEASURE) != 0) {
        fprintf(stderr, "Error writing to MEASUREMENT_CONFIG_REG\n");
        return -1;
    }
    return 0;
}

// Function to read temperature and humidity data from the HDC2010
int read_hdc2010(sensor_data_t *data) {
    uint8_t buffer[4];
    int retries = 3; // Number of retries for I2C read

    // Wait for measurement to complete (bit 0 of MEASUREMENT_CONFIG_REG to clear)
    while (retries > 0) {
        if (i2cReadByteData(i2c_handle, MEASUREMENT_CONFIG_REG) < 0) {
            fprintf(stderr, "Error reading MEASUREMENT_CONFIG_REG\n");
            retries--;
            gpioDelay(10); // Small delay before retry
            continue;
        }
        if ((i2cReadByteData(i2c_handle, MEASUREMENT_CONFIG_REG) & 0x01) == 0) {
            break; // Measurement complete
        }
        gpioDelay(10); // Wait 10ms
        retries--;
    }

    if (retries == 0) {
        fprintf(stderr, "Timeout waiting for measurement to complete\n");
        return -1;
    }

    // Read temperature and humidity data
    if (i2cReadI2CBlockData(i2c_handle, TEMPERATURE_REG, (char *)buffer, 4) != 4) {
        fprintf(stderr, "Error reading temperature and humidity data\n");
        return -1;
    }

    // Convert raw data to temperature and humidity
    uint16_t raw_temperature = (buffer[0] << 8) | buffer[1];
    uint16_t raw_humidity = (buffer[2] << 8) | buffer[3];

    data->temperature = ((float)raw_temperature / 65536.0) * 165.0 - 40.0;
    data->humidity = ((float)raw_humidity / 65536.0) * 100.0;

    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, HDC2010_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the HDC2010 sensor
    if (init_hdc2010() != 0) {
        fprintf(stderr, "HDC2010 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read temperature and humidity data
        if (read_hdc2010(&sensor_data) == 0) {
            // Print the temperature and humidity readings
            printf("Temperature: %.2f °C, Humidity: %.2f %%\n", sensor_data.temperature, sensor_data.humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for 5 seconds
        gpioDelay(5000);
    }

    // Close I2C bus and terminate pigpio library
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

