#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// SDP800-500Pa I2C address
#define SDP800_ADDR 0x25

// I2C bus number
#define I2C_BUS 1

// Measurement command (continuous measurement without averaging)
#define MEASURE_CMD 0x362F

// CRC-8 polynomial
#define CRC8_POLYNOMIAL 0x31

// CRC-8 initial value
#define CRC8_INITIAL_VALUE 0xFF

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t pressure;
    int16_t temperature;
} sensor_data_t;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to calculate CRC-8 checksum
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INITIAL_VALUE;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the SDP800 sensor
int read_sdp800(int i2c_handle, sensor_data_t *data) {
    uint8_t cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    uint8_t buffer[6];

    // Send measurement command
    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    // Wait for measurement to complete (45 ms)
    gpioDelay(45000); // 45 ms

    // Read 6 bytes of data
    if (i2cReadDevice(i2c_handle, (char *)buffer, 6) != 6) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    // CRC validation
    if (crc8(buffer, 2) != buffer[2] || crc8(buffer + 3, 2) != buffer[5]) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Convert data
    data->pressure = (int16_t)((buffer[0] << 8) | buffer[1]);
    data->temperature = (int16_t)((buffer[3] << 8) | buffer[4]);

    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sdp800(i2c_handle, &sensor_data) == 0) {
            // Get current timestamp
            time_t rawtime;
            struct tm *timeinfo;
            time(&rawtime);
            timeinfo = localtime(&rawtime);

            // Log data to console
            printf("[%04d-%02d-%02d %02d:%02d:%02d] Pressure: %d, Temperature: %d\n",
                   timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday,
                   timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec,
                   sensor_data.pressure, sensor_data.temperature);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait 500 ms
        gpioDelay(500000); // 500 ms
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

