#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0 // CE0
#define SPI_SPEED 1000000 // 1 MHz
#define SSR_GPIO 17
#define MAX_TEMP 200.0
#define MIN_TEMP 0.0
#define LOG_FILE "reflow_log.csv"
#define PROFILE_FILE "profile.txt"
#define TARGET_TEMP_FILE "target_temp.txt"

// PID Gains
#define KP 1.0
#define KI 0.1
#define KD 0.01

// Global Variables
int spi_handle;
FILE *log_file;
FILE *profile_file;
FILE *target_temp_file;
volatile sig_atomic_t terminate = 0;

// Structure for PID controller
typedef struct {
    double integral;
    double previous_error;
} PIDController;

// Function Prototypes
int initialize();
double read_temperature();
double calculate_pid(double setpoint, double actual_temperature, PIDController *pid);
void set_ssr_duty_cycle(double duty_cycle);
void log_data(double temperature, double duty_cycle);
void load_profile(double *target_temp, int *profile_length);
void signal_handler(int signal);
void cleanup();

// Signal Handler
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set SSR GPIO as output
    gpioSetMode(SSR_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open profile file
    profile_file = fopen(PROFILE_FILE, "r");
    if (profile_file == NULL) {
        fprintf(stderr, "Failed to open profile file\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

