#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define DS18B20_ADDR 0x28
#define RELAY_GPIO 17
#define PWM_GPIO 18
#define PWM_FREQUENCY 1000 // Hz
#define LOG_FILE "greenhouse.log"
#define SLEEP_DURATION 5 // seconds

// Global variables
static volatile int running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

// PID gains
static float Kp = 1.0;
static float Ki = 0.1;
static float Kd = 0.01;

// Setpoint
static float setpoint = 25.0;

// PID variables
static float integral = 0.0;
static float previous_error = 0.0;

// Function prototypes
float read_ds18b20();
float read_bmp280();
float calculate_pid(float temperature);
void set_pwm(float duty_cycle);
void set_relay(int state);
void log_data(float temp1, float temp2, float setpoint, float pid_output, float duty_cycle);
void signal_handler(int signal);
int init_i2c();
void close_i2c();

// CRC8 calculation function
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0x00;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read temperature from DS18B20 sensor
float read_ds18b20() {
    unsigned char data[9];
    int retries = 3;

    while (retries > 0) {
        // Reset 1-wire bus
        if (ioctl(i2c_fd, I2C_SLAVE, DS18B20_ADDR) < 0) {
            perror("Error: Could not set I2C slave address");
            return -1000.0; // Indicate error
        }

        unsigned char reset_cmd = 0xCC; // Skip ROM
        if (write(i2c_fd, &reset_cmd, 1) != 1) {
            perror("Error: Could not write reset command");
            retries--;
            usleep(10000); // Wait before retrying
            continue;
        }

        usleep(1000); // Wait for reset

        // Convert T command
        unsigned char convert_cmd = 0x44;
        if (write(i2c_fd, &convert_cmd, 1) != 1) {
            perror("Error: Could not write convert command");
            retries--;
            usleep(10000); // Wait before retrying
            continue;
        }

        usleep(750000); // Wait for conversion (750ms)

        // Read scratchpad
        unsigned char read_cmd = 0xBE;
        if (write(i2c_fd, &read_cmd, 1) != 1) {
            perror("Error: Could not write read command");
            retries--;
            usleep(10000); // Wait before retrying
            continue;
        }

        if (read(i2c_fd, data, 9) != 9) {
            perror("Error: Could not read scratchpad");
            retries--;
            usleep(10000); // Wait before retrying
            continue;
        }

        // CRC check
        if (crc8(data, 8) != data[8]) {
            fprintf(stderr, "Error: CRC check failed\n");
            retries--;
            usleep(10000); // Wait before retrying
            continue;
        }

        // Convert data
        int16_t raw_temperature = (data[1] << 8) | data[0];
        float temperature = (float)raw_temperature / 16.0;

        return temperature;
    }

    fprintf(stderr, "Error: Failed to read DS18B20 after multiple retries\n");
    return -1000.0; // Indicate error
}

// Function to read temperature from BMP280 sensor
float read_bmp280() {
    unsigned char data[6];
    int retries = 3;

    while (retries > 0) {
        // Set I2C slave address
        if (ioctl(i2c_fd, I2C_SLAVE, DS18B20_ADDR) < 0) {
            perror("Error: Could not set I2C slave address");
            return -1000.0; // Indicate error
        }

        // Read temperature registers (0xFA-0xFD)
        unsigned char reg = 0xFA;
        if (write(i2c_fd, &reg, 1) != 1) {
            perror("Error: Could not write register address");
            retries--;
            usleep(10000); // Wait before retrying
            continue;
        }

        if (read(i2c_fd, data, 6) != 6) {
            perror("Error: Could not read temperature data");
            retries--;
            usleep(10000); // Wait before retrying
            continue;
        }

        // Combine the two bytes for temperature
        int32_t raw_temperature = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);
        float temperature = (float)raw_temperature / 100.0;

        return temperature;
    }

    fprintf(stderr, "Error: Failed to read BMP280 after multiple retries\n");
    return -1000.0; // Indicate error
}

// Function to calculate PID output
float calculate_pid(float temperature) {
    float error = setpoint - temperature;
    integral += error;
    float derivative = error - previous_error;
    float output = Kp * error + Ki * integral + Kd * derivative;
    previous_error = error;

    // Clamp the output to the range 0-100
    if (output < 0) output = 0;
    if (output > 100) output = 100;

    return output;
}

// Function to set PWM duty cycle
void set_pwm(float duty_cycle) {
    int pwm_value = (int)(duty_cycle * 2.55); // Convert duty cycle (0-100) to PWM value (0-255)
    gpioPWM(PWM_GPIO, pwm_value);
}

// Function to set relay state
void set_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
}

// Function to log data to file
void log_data(float temp1, float temp2, float setpoint, float pid_output, float duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.2f, %.2f, %.2f, %.2f, %.2f\n", timestamp, temp1, temp2, setpoint, pid_output, duty_cycle);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Initialize I2C
int init_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error: Could not open I2C device");
        return -1;
    }
    return 0;
}

// Close I2C
void close_i2c() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <setpoint> <Kp> <Ki> <Kd>\n", argv[0]);
        return 1;
    }

    setpoint = atof(argv[1]);
    Kp = atof(argv[2]);
    Ki = atof(argv[3]);
    Kd = atof(argv[4]);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioSetMode(PWM_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_GPIO, 255); // Set PWM range to 0-255

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error: Could not open log file");
        close_i2c();
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Greenhouse control system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        float temp1 = read_ds18b20();
        float temp2 = read_bmp280();

        if (temp1 > -999.0 && temp2 > -999.0) {
            float avg_temp = (temp1 + temp2) / 2.0;
            float pid_output = calculate_pid(avg_temp);
            set_pwm(pid_output);
            if (pid_output > 0) {
                set_relay(1); // Turn on relay
            } else {
                set_relay(0); // Turn off relay
            }
            log_data(temp1, temp2, setpoint, pid_output, pid_output);
        } else {
            fprintf(stderr, "Error: Could not read temperature from one or more sensors\n");
            log_data(-999.0, -999.0, setpoint, 0.0, 0.0); // Log error
        }

        sleep(SLEEP_DURATION);
    }

    // Cleanup
    set_relay(0); // Turn off relay
    set_pwm(0);   // Set PWM to 0
    close_i2c();
    fclose(log_file);
    gpioTerminate();

    printf("Greenhouse control system stopped.\n");

    return 0;
}

