int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(DEHUMIDIFIER_GPIO, PI_OUTPUT);
    gpioWrite(DEHUMIDIFIER_GPIO, 0); // Ensure dehumidifier is off initially
    return 0;
}

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, AHT20_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read humidity from AHT20 sensor
int read_aht20(float *humidity) {
    uint8_t init_cmd[3] = {0xBE, 0x08, 0x00};
    uint8_t data[6];
    int retries = 0;
    int result;

    // Trigger measurement
    while (retries < MAX_RETRIES) {
        result = i2cWriteDevice(i2c_handle, (char *)init_cmd, 3);
        if (result == 0) {
            break;
        } else {
            fprintf(stderr, "I2C write failed (trigger): %d, retry %d\n", result, retries + 1);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to trigger measurement after %d retries\n", MAX_RETRIES);
        return -1;
    }

    gpioDelay(80000); // Wait 80ms

    retries = 0;
    while (retries < MAX_RETRIES) {
        result = i2cReadDevice(i2c_handle, (char *)data, 6);
        if (result == 6) {
            break;
        } else {
            fprintf(stderr, "I2C read failed: %d, retry %d\n", result, retries + 1);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read data after %d retries\n", MAX_RETRIES);
        return -1;
    }

    // Check status byte
    if ((data[0] & 0x80) != 0) {
        fprintf(stderr, "AHT20 busy\n");
        return -1;
    }
    if ((data[0] & 0x08) != 0) {
        fprintf(stderr, "AHT20 calibration error\n");
        return -1;
    }

    // Convert data to humidity (example, adjust based on datasheet)
    uint32_t humidity_raw = ((uint32_t)data[1] << 12) | ((uint32_t)data[2] << 4) | ((uint32_t)data[3] >> 4);
    *humidity = ((float)humidity_raw / 0x100000) * 100;

    return 0;
}

// Function to control dehumidifier
void control_dehumidifier(float humidity) {
    static int dehumidifier_on = 0;

    if (humidity > HUMIDITY_THRESHOLD_HIGH && !dehumidifier_on) {
        gpioWrite(DEHUMIDIFIER_GPIO, 1); // Turn on dehumidifier
        dehumidifier_on = 1;
        printf("Dehumidifier ON (Humidity: %.2f%%)\n", humidity);
    } else if (humidity < HUMIDITY_THRESHOLD_LOW && dehumidifier_on) {
        gpioWrite(DEHUMIDIFIER_GPIO, 0); // Turn off dehumidifier
        dehumidifier_on = 0;
        printf("Dehumidifier OFF (Humidity: %.2f%%)\n", humidity);
    }
}

// Function to log data
void log_data(float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] Humidity: %.2f%%\n", timestamp, humidity);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(DEHUMIDIFIER_GPIO, 0); // Ensure dehumidifier is off
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    float humidity;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    printf("AHT20 dehumidifier control started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        if (read_aht20(&humidity) == 0) {
            log_data(humidity);
            control_dehumidifier(humidity);
        } else {
            fprintf(stderr, "Failed to read humidity\n");
        }

        sleep(MEASUREMENT_INTERVAL);
    }

    cleanup();
    return 0;
}

