#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <sys/time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// Configuration
#define I2C_BUS 1
#define HTU21D_ADDR 0x40
#define API_ENDPOINT "http://api.example.com/humidity"
#define POLLING_INTERVAL 60 // seconds
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_htu21d(sensor_data_t *data);
float convert_temperature(unsigned int raw_temp);
float convert_humidity(unsigned int raw_humidity);
int post_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, HTU21D_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %d", i2c_handle);
        return -1;
    }
    syslog(LOG_INFO, "I2C device opened successfully.");
    return 0;
}

// Read data from HTU21D sensor
int read_htu21d(sensor_data_t *data) {
    unsigned char cmd[2];
    unsigned char buf[3];
    int retries = 0;

    // Trigger temperature measurement
    cmd[0] = 0xE3; // Measure temperature, hold master
    if (i2cWriteDevice(i2c_handle, cmd, 1) != 0) {
        syslog(LOG_ERR, "Failed to write temperature measurement command.");
        return -1;
    }
    gpioDelay(50); // Wait for measurement (datasheet specifies 50ms)

    // Read temperature data
    if (i2cReadDevice(i2c_handle, buf, 3) != 3) {
        syslog(LOG_ERR, "Failed to read temperature data.");
        return -1;
    }

    // Trigger humidity measurement
    cmd[0] = 0xE5; // Measure humidity, hold master
    if (i2cWriteDevice(i2c_handle, cmd, 1) != 0) {
        syslog(LOG_ERR, "Failed to write humidity measurement command.");
        return -1;
    }
    gpioDelay(50); // Wait for measurement (datasheet specifies 50ms)

    // Read humidity data
    if (i2cReadDevice(i2c_handle, buf, 3) != 3) {
        syslog(LOG_ERR, "Failed to read humidity data.");
        return -1;
    }

    // Convert raw data
    unsigned int raw_temp = (buf[0] << 8) | buf[1];
    unsigned int raw_humidity = (buf[0] << 8) | buf[1];

    data->temperature = convert_temperature(raw_temp);
    data->humidity = convert_humidity(raw_humidity);

    syslog(LOG_INFO, "Temperature: %.2f C, Humidity: %.2f %%", data->temperature, data->humidity);
    return 0;
}

// Convert raw temperature to Celsius
float convert_temperature(unsigned int raw_temp) {
    return -46.85 + 175.72 * (raw_temp / 65536.0);
}

// Convert raw humidity to percentage
float convert_humidity(unsigned int raw_humidity) {
    return -6.0 + 125.0 * (raw_humidity / 65536.0);
}

// Post data to API endpoint
int post_data(sensor_data_t data) {
    int sockfd;
    struct sockaddr_in servaddr;
    char json_data[100];
    char response[1000];
    int retries = 0;

    // Create JSON payload
    snprintf(json_data, sizeof(json_data), "{\"temperature\": %.2f, \"humidity\": %.2f}", data.temperature, data.humidity);

    // Create socket
    if ((sockfd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        syslog(LOG_ERR, "Socket creation failed");
        return -1;
    }

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(80); // Standard HTTP port

    // Convert IPv4 and IPv6 addresses from text to binary form
    if (inet_pton(AF_INET, "api.example.com", &servaddr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid address/ Address not supported");
        close(sockfd);
        return -1;
    }

    // Connect to server
    if (connect(sockfd, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        syslog(LOG_ERR, "Connection Failed");
        close(sockfd);
        return -1;
    }

    // Construct HTTP POST request
    char request[500];
    snprintf(request, sizeof(request), "POST %s HTTP/1.1\r\nHost: api.example.com\r\nContent-Type: application/json\r\nContent-Length: %ld\r\n\r\n%s", API_ENDPOINT, strlen(json_data), json_data);

    // Send HTTP request
    if (send(sockfd, request, strlen(request), 0) < 0) {
        syslog(LOG_ERR, "Send failed");
        close(sockfd);
        return -1;
    }

    // Receive response (optional, for debugging)
    memset(response, 0, sizeof(response));
    ssize_t bytes_received = recv(sockfd, response, sizeof(response) - 1, 0);
    if (bytes_received > 0) {
        syslog(LOG_DEBUG, "Received response: %s", response);
    } else if (bytes_received == 0) {
        syslog(LOG_WARNING, "Server closed connection.");
    } else {
        syslog(LOG_ERR, "Receive failed");
    }

    close(sockfd);
    syslog(LOG_INFO, "Data posted successfully.");
    return 0;
}

// Cleanup resources
void cleanup() {
    syslog(LOG_INFO, "Cleaning up...");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        syslog(LOG_INFO, "I2C device closed.");
    }
    gpioTerminate();
    syslog(LOG_INFO, "pigpio terminated.");
    closelog();
}

int main() {
    // Initialize syslog
    openlog("htu21d_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }
    syslog(LOG_INFO, "pigpio initialised successfully.");

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_htu21d(&sensor_data) == 0) {
            // Post data to API
            if (post_data(sensor_data) != 0) {
                syslog(LOG_ERR, "Failed to post data to API.");
            }
        } else {
            syslog(LOG_ERR, "Failed to read sensor data.");
        }

        // Wait for the next polling interval
        sleep(POLLING_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

