#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define AHT20_ADDR 0x38
#define PIR_GPIO 17
#define SAMPLE_INTERVAL 1 // seconds
#define MAX_RETRIES 3
#define BACKOFF_MS 10

// Global variables
int i2c_handle_tmp117 = -1;
int i2c_handle_aht20 = -1;
FILE *log_file = NULL;

// Function prototypes
int init_i2c(int bus, int addr);
int read_tmp117(int handle, float *temperature);
int read_aht20(int handle, float *humidity);
int read_pir_sensor(int gpio);
int log_data(FILE *fp, float temperature, float humidity, int motion_detected);
void create_new_log_file(FILE **fp);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data (optional)
typedef struct {
    float temperature;
    float humidity;
    int motion_detected;
} sensor_data_t;

// Initialize I2C communication
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02x: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Read temperature from TMP117
int read_tmp117(int handle, float *temperature) {
    char buf[2];
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cReadDevice(handle, buf, 2);
        if (result == 2) {
            // Success
            int raw_temp = (buf[0] << 8) | buf[1];
            *temperature = (raw_temp * 0.0078125); // Resolution is 0.0078125 degrees C
            return 0;
        } else {
            fprintf(stderr, "Error reading TMP117 (attempt %d): %d\n", retries + 1, result);
            gpioDelay(BACKOFF_MS * 1000); // pigpioDelay takes microseconds
            retries++;
        }
    }

    fprintf(stderr, "Failed to read TMP117 after %d retries.\n", MAX_RETRIES);
    return -1;
}

// Read humidity from AHT20
int read_aht20(int handle, float *humidity) {
    char init_cmd[3] = {0xBE, 0x08, 0x00};
    char buf[6];
    int retries = 0;
    int result;

    // Send initialization command
    while (retries < MAX_RETRIES) {
        result = i2cWriteDevice(handle, init_cmd, 3);
        if (result == 0) {
            break; // Initialization successful
        } else {
            fprintf(stderr, "Error writing AHT20 init command (attempt %d): %d\n", retries + 1, result);
            gpioDelay(BACKOFF_MS * 1000);
            retries++;
        }
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to write AHT20 init command after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    gpioDelay(80000); // Wait for measurement (at least 75ms)

    retries = 0;
    while (retries < MAX_RETRIES) {
        result = i2cReadDevice(handle, buf, 6);
        if (result == 6) {
            // Success
            unsigned long humidity_raw = ((unsigned long)buf[1] << 12) | ((unsigned long)buf[2] << 4) | (buf[3] >> 4);
            *humidity = ((float)humidity_raw / 0x100000) * 100;
            return 0;
        } else {
            fprintf(stderr, "Error reading AHT20 data (attempt %d): %d\n", retries + 1, result);
            gpioDelay(BACKOFF_MS * 1000);
            retries++;
        }
    }

    fprintf(stderr, "Failed to read AHT20 data after %d retries.\n", MAX_RETRIES);
    return -1;
}

// Read PIR sensor state
int read_pir_sensor(int gpio) {
    return gpioRead(gpio);
}

// Log data to CSV file
int log_data(FILE *fp, float temperature, float humidity, int motion_detected) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%.2f,%d\n", timestamp, temperature, humidity, motion_detected) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }
    fflush(fp); // Ensure data is written immediately
    return 0;
}

// Create a new log file at midnight
void create_new_log_file(FILE **fp) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char filename[50];
    strftime(filename, sizeof(filename), "sensor_data_%Y-%m-%d.csv", &tm);

    if (*fp != NULL) {
        fclose(*fp);
    }

    *fp = fopen(filename, "a");
    if (*fp == NULL) {
        fprintf(stderr, "Error opening log file %s.\n", filename);
        exit(EXIT_FAILURE);
    }

    // Write header if the file is newly created
    fseek(*fp, 0, SEEK_END);
    long file_size = ftell(*fp);
    if (file_size == 0) {
        fprintf(*fp, "Timestamp,Temperature(C),Humidity(%),MotionDetected\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Cleanup resources
void cleanup() {
    if (i2c_handle_tmp117 >= 0) {
        i2cClose(i2c_handle_tmp117);
    }
    if (i2c_handle_aht20 >= 0) {
        i2cClose(i2c_handle_aht20);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set PIR GPIO as input
    gpioSetMode(PIR_GPIO, PI_INPUT);

    // Initialize I2C devices
    i2c_handle_tmp117 = init_i2c(I2C_BUS, TMP117_ADDR);
    i2c_handle_aht20 = init_i2c(I2C_BUS, AHT20_ADDR);

    // Create log file
    create_new_log_file(&log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float temperature, humidity;
    int motion_detected;

    // Main loop
    while (1) {
        // Read sensor data
        if (i2c_handle_tmp117 >= 0) {
            if (read_tmp117(i2c_handle_tmp117, &temperature) != 0) {
                fprintf(stderr, "Failed to read temperature.\n");
            }
        } else {
            temperature = -999.0; // Indicate sensor not present
        }

        if (i2c_handle_aht20 >= 0) {
            if (read_aht20(i2c_handle_aht20, &humidity) != 0) {
                fprintf(stderr, "Failed to read humidity.\n");
            }
        } else {
            humidity = -999.0; // Indicate sensor not present
        }

        motion_detected = read_pir_sensor(PIR_GPIO);

        // Log data
        if (log_data(log_file, temperature, humidity, motion_detected) != 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        // Create new log file at midnight
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        if (tm.tm_hour == 0 && tm.tm_min == 0 && tm.tm_sec == 0) {
            create_new_log_file(&log_file);
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL);
    }

    return 0;
}

