#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

// Define motor run time (seconds)
#define MOTOR_RUN_TIME 5

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_rain_sensor();
void control_motor(int direction);
void stop_motor();
void log_message(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        log_message("Received signal, stopping motor and exiting...");
        stop_motor();
        program_running = 0;
        gpioTerminate();
        exit(0);
    }
}

// Function to read the rain sensor
int read_rain_sensor() {
    int sensor_value = gpioRead(RAIN_SENSOR_PIN);
    if (sensor_value < 0) {
        log_message("Error reading rain sensor");
        return -1; // Indicate error
    }
    return sensor_value;
}

// Function to control the motor
void control_motor(int direction) {
    if (direction == 1) { // Forward
        gpioWrite(MOTOR_IN1_PIN, 1);
        gpioWrite(MOTOR_IN2_PIN, 0);
        gpioPWM(MOTOR_ENA_PIN, 100); // 100% duty cycle
        log_message("Motor started (forward)");
    } else if (direction == 0) { // Stop
        gpioWrite(MOTOR_IN1_PIN, 0);
        gpioWrite(MOTOR_IN2_PIN, 0);
        gpioPWM(MOTOR_ENA_PIN, 0);
        log_message("Motor stopped");
    } else {
        log_message("Invalid motor direction");
    }
}

// Function to stop the motor
void stop_motor() {
    control_motor(0);
}

// Function to log messages with timestamps
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);
    fprintf(stdout, "[%s] %s\n", timestamp, message);
    fflush(stdout); // Ensure immediate output
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);

    // Set PWM range for ENA pin
    gpioSetPWMrange(MOTOR_ENA_PIN, 100);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_message("Rain sensor monitoring started");

    // Main loop
    while (program_running) {
        int rain_detected = read_rain_sensor();
        if (rain_detected == 0) { // Assuming active-low sensor
            log_message("Rain detected!");
            control_motor(1); // Start motor
            gpioDelay(MOTOR_RUN_TIME * 1000000); // Run motor for 5 seconds
            stop_motor(); // Stop motor
        } else if (rain_detected < 0) {
            log_message("Error reading rain sensor, retrying...");
        }

        gpioDelay(2000000); // Wait 2 seconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    stop_motor();
    gpioTerminate();

    return 0;
}

