    gpioSetPWMrange(MOTOR_ENA_PIN, 100);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_message("Rain sensor monitoring started");

    // Main loop
    while (program_running) {
        int rain_detected = read_rain_sensor();
        if (rain_detected == 0) { // Assuming active-low sensor
            log_message("Rain detected!");
            control_motor(1); // Start motor
            gpioDelay(MOTOR_RUN_TIME * 1000000); // Run motor for 5 seconds
            stop_motor(); // Stop motor
        } else if (rain_detected < 0) {
            log_message("Error reading rain sensor, retrying...");
        }

        gpioDelay(2000000); // Wait 2 seconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    stop_motor();
    gpioTerminate();

    return 0;
}

