#define GREEN_PIN 22
#define BLUE_PIN  27

// Define CPU load file path
#define CPU_STAT_FILE "/proc/stat"

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read CPU load from /proc/stat
float read_cpu_load() {
    FILE *fp;
    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    unsigned long long prev_user, prev_nice, prev_system, prev_idle, prev_iowait, prev_irq, prev_softirq, prev_steal, prev_guest, prev_guest_nice;
    float cpu_usage;
    static unsigned long long last_user = 0, last_nice = 0, last_system = 0, last_idle = 0, last_iowait = 0, last_irq = 0, last_softirq = 0, last_steal = 0, last_guest = 0, last_guest_nice = 0;

    fp = fopen(CPU_STAT_FILE, "r");
    if (fp == NULL) {
        perror("Error opening CPU stat file");
        return -1.0;
    }

    if (fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        fclose(fp);
        fprintf(stderr, "Error reading CPU stat file\n");
        return -1.0;
    }

    fclose(fp);

    unsigned long long previdle = last_idle + last_iowait;
    unsigned long long prevnonidle = last_user + last_nice + last_system + last_irq + last_softirq + last_steal;
    unsigned long long idletime = idle + iowait;
    unsigned long long nonidletime = user + nice + system + irq + softirq + steal;

    unsigned long long totald = idletime - previdle;
    unsigned long long workd = nonidletime - prevnonidle;

    cpu_usage = (float)(workd) / (float)(totald) * 100.0;

    last_user = user;
    last_nice = nice;
    last_system = system;
    last_idle = idle;
    last_iowait = iowait;
    last_irq = irq;
    last_softirq = softirq;
    last_steal = steal;
    last_guest = guest;
    last_guest_nice = guest_nice;

    return cpu_usage;
}

// Function to map CPU load to RGB color values
void map_cpu_load_to_color(float cpu_load, int *red, int *green, int *blue) {
    if (cpu_load < 0.0 || cpu_load > 100.0) {
        fprintf(stderr, "Error: CPU load out of range (0-100): %.2f\n", cpu_load);
        *red = *green = *blue = 0; // Set to black on error
        return;
    }

    if (cpu_load <= 50.0) {
        // Green to Yellow (0-255)
        *green = 255;
        *red = 0;
        *blue = (int)(cpu_load / 50.0 * 255.0);
    } else {
        // Yellow to Red (255-0)
        *green = 255 - (int)((cpu_load - 50.0) / 50.0 * 255.0);
        *red = 255;
        *blue = 0;
    }
}

// Function to set RGB LED color using hardware PWM
void set_led_color(int red, int green, int blue) {
    gpioPWM(RED_PIN, 255 - red);   // Common anode, invert PWM
    gpioPWM(GREEN_PIN, 255 - green); // Common anode, invert PWM
    gpioPWM(BLUE_PIN, 255 - blue);  // Common anode, invert PWM
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("CPU Load Monitor started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read CPU load
        float cpu_load = read_cpu_load();

        if (cpu_load >= 0.0) {
            // Map CPU load to RGB color
            int red, green, blue;
            map_cpu_load_to_color(cpu_load, &red, &green, &blue);

            // Set LED color
            set_led_color(red, green, blue);

            printf("CPU Load: %.2f%%, RGB: (%d, %d, %d)\n", cpu_load, red, green, blue);
        } else {
            fprintf(stderr, "Failed to read CPU load. Setting LED to black.\n");
            set_led_color(0, 0, 0); // Set LED to black on error
        }

        // Wait for 500 milliseconds
        gpioDelay(500000); // pigpio's delay function takes microseconds
    }

    // Turn off LED before exiting
    set_led_color(0, 0, 0);

    // Terminate pigpio library
    gpioTerminate();

    printf("CPU Load Monitor stopped.\n");

    return 0;
}

