#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define FAN_PIN 18       // BCM GPIO 18
#define PWM_FREQUENCY 1000 // 1 kHz
#define PWM_RANGE 255
#define BUFFER_SIZE 20
#define TEMPERATURE_THRESHOLD 60.0

// MAX31855 Fault Codes
#define FAULT_OPEN_CIRCUIT 0x01
#define FAULT_SHORT_TO_GROUND 0x02
#define FAULT_SHORT_TO_VCC 0x04

// Global Variables
volatile sig_atomic_t program_running = 1;

// Circular Buffer Structure
typedef struct {
    time_t timestamp;
    float temperature;
    int duty_cycle;
} LogEntry;

LogEntry log_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function Prototypes
int read_max31855(float *temperature);
int calculate_duty_cycle(float temperature);
void set_fan_speed(int duty_cycle);
void add_to_buffer(time_t timestamp, float temperature, int duty_cycle);
void print_buffer();
void signal_handler(int signal);

// Function to read temperature from MAX31855
int read_max31855(float *temperature) {
    unsigned char data[4];
    int result;

    result = wiringPiSPIDataRW(SPI_CHANNEL, data, 4);
    if (result == -1) {
        fprintf(stderr, "SPI read failed: %s\n", strerror(errno));
        return -1;
    }

    // Check for fault bits
    if (data[3] & FAULT_OPEN_CIRCUIT) {
        fprintf(stderr, "MAX31855 Fault: Open Circuit\n");
        return -1;
    }
    if (data[3] & FAULT_SHORT_TO_GROUND) {
        fprintf(stderr, "MAX31855 Fault: Short to Ground\n");
        return -1;
    }
    if (data[3] & FAULT_SHORT_TO_VCC) {
        fprintf(stderr, "MAX31855 Fault: Short to VCC\n");
        return -1;
    }

    // Extract temperature data (bits 31:18)
    int16_t raw_temp = ((data[0] << 8) | data[1]) >> 2;

    // Check for negative temperature
    if (raw_temp & 0x2000) {
        raw_temp |= 0xC000; // Sign extend
    }

    *temperature = raw_temp * 0.25;

    return 0;
}

// Function to calculate duty cycle based on temperature
int calculate_duty_cycle(float temperature) {
    int duty_cycle = 0;

    if (temperature < 25.0) {
        duty_cycle = 0;
    } else if (temperature < 40.0) {
        duty_cycle = (int)((temperature - 25.0) / (40.0 - 25.0) * 50.0);
    } else if (temperature < 60.0) {
        duty_cycle = 50 + (int)((temperature - 40.0) / (60.0 - 40.0) * 150.0);
    } else {
        duty_cycle = 200;
    }

    return duty_cycle;
}

// Function to set fan speed using PWM
void set_fan_speed(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

    pwmWrite(FAN_PIN, duty_cycle);
}

// Function to add data to the circular buffer
void add_to_buffer(time_t timestamp, float temperature, int duty_cycle) {
    log_buffer[buffer_index].timestamp = timestamp;
    log_buffer[buffer_index].temperature = temperature;
    log_buffer[buffer_index].duty_cycle = duty_cycle;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Log Buffer ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE;
        char time_str[30];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&log_buffer[index].timestamp));
        printf("[%s] Temperature: %.2f °C, Duty Cycle: %d\n", time_str, log_buffer[index].temperature, log_buffer[index].duty_cycle);
    }
    printf("--- End of Log ---\n\n");
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    float temperature;
    int duty_cycle;
    time_t current_time;

    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "wiringPiSetupGpio failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize SPI
    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) == -1) {
        fprintf(stderr, "wiringPiSPISetup failed: %s\n", strerror(errno));
        return 1;
    }

    // Configure PWM on FAN_PIN
    pinMode(FAN_PIN, PWM_OUTPUT);
    pwmSetMode(PWM_MODE_MS);
    pwmSetClock(192); // Adjust clock for desired frequency (19.2 MHz / 192 = 100 kHz)
    pwmSetRange(PWM_RANGE);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Temperature-controlled fan started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read temperature from MAX31855
        if (read_max31855(&temperature) == 0) {
            // Calculate duty cycle
            duty_cycle = calculate_duty_cycle(temperature);

            // Set fan speed
            set_fan_speed(duty_cycle);

            // Get current timestamp
            current_time = time(NULL);

            // Add data to buffer
            add_to_buffer(current_time, temperature, duty_cycle);

            printf("Temperature: %.2f °C, Duty Cycle: %d\n", temperature, duty_cycle);

            // Check temperature threshold and print warning if exceeded
            if (temperature > TEMPERATURE_THRESHOLD) {
                fprintf(stderr, "WARNING: Temperature exceeds threshold (%.2f > %.2f)!\n", temperature, TEMPERATURE_THRESHOLD);
            }
        } else {
            fprintf(stderr, "Failed to read temperature. Skipping fan update.\n");
        }

        // Wait for 1 second
        delay(1000);
    }

    // Stop the fan
    set_fan_speed(0);

    // Close SPI interface
    // No explicit SPI close function in wiringPi, but reset the SPI channel
    wiringPiSPISetup(SPI_CHANNEL, 0); // Set speed to 0 to disable

    // Print the log buffer
    print_buffer();

    printf("Temperature-controlled fan stopped.\n");

    return 0;
}

