#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CE0_PIN 8
#define RTD_NOMINAL 100.0 // 100 ohms
#define REF_RESISTANCE 430.0 // 430 ohms
#define A 3.9083e-3
#define B -5.775e-7
#define MAX_RETRIES 3

// Global variables
int spi_fd;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for configuration
typedef struct {
    int spi_channel;
    int spi_speed;
    int ce0_pin;
    float rtd_nominal;
    float ref_resistance;
    float a;
    float b;
    int max_retries;
} Config;

// Function prototypes
int spi_init(int channel, int speed, int ce0_pin);
int spi_read_register(int fd, uint8_t reg, uint8_t *data, int len);
int spi_write_register(int fd, uint8_t reg, uint8_t *data, int len);
int read_rtd(int fd, float *temperature);
float calculate_temperature(uint16_t rtd_raw);
int log_data(FILE *fp, float temperature);
void signal_handler(int signal);
void cleanup();

// SPI Initialization
int spi_init(int channel, int speed, int ce0_pin) {
    int fd = spiOpen(channel, speed, 0); // Mode 0
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %d\n", channel, fd);
        return -1;
    }
    gpioSetMode(ce0_pin, PI_OUTPUT);
    gpioWrite(ce0_pin, 1); // Ensure CE0 is initially high
    return fd;
}

// SPI Read Register
int spi_read_register(int fd, uint8_t reg, uint8_t *data, int len) {
    char tx_buf[len + 1];
    char rx_buf[len + 1];
    tx_buf[0] = reg | 0x80; // Set MSB for read operation
    memset(tx_buf + 1, 0, len); // Fill with dummy data
    memset(rx_buf, 0, len + 1);

    gpioWrite(CE0_PIN, 0); // Select the device
    int result = spiXfer(fd, tx_buf, rx_buf, len + 1);
    gpioWrite(CE0_PIN, 1); // Deselect the device

    if (result != len + 1) {
        fprintf(stderr, "SPI read error: %d\n", result);
        return -1;
    }

    memcpy(data, rx_buf + 1, len);
    return 0;
}

// SPI Write Register
int spi_write_register(int fd, uint8_t reg, uint8_t *data, int len) {
    char tx_buf[len + 1];
    char rx_buf[len + 1];
    tx_buf[0] = reg & 0x7F; // Clear MSB for write operation
    memcpy(tx_buf + 1, data, len);
    memset(rx_buf, 0, len + 1);

    gpioWrite(CE0_PIN, 0); // Select the device
    int result = spiXfer(fd, tx_buf, rx_buf, len + 1);
    gpioWrite(CE0_PIN, 1); // Deselect the device

    if (result != len + 1) {
        fprintf(stderr, "SPI write error: %d\n", result);
        return -1;
    }

    return 0;
}

// Read RTD Value
int read_rtd(int fd, float *temperature) {
    uint8_t config_data[2];
    uint8_t rtd_data[2];
    uint16_t rtd_raw;
    int retries = 0;

    // Configure for single conversion mode, 50/60 Hz filter, auto conversion
    config_data[0] = 0xC2; // VBIAS = 1, 50/60 Hz filter, auto conversion
    config_data[1] = 0x01; // Enable RTD conversion

    while (retries < MAX_RETRIES) {
        if (spi_write_register(fd, 0x00, config_data, 2) == 0) {
            break;
        } else {
            fprintf(stderr, "Error writing config register, retry %d\n", retries + 1);
            retries++;
            gpioDelay(1000); // Wait 1 ms before retrying
        }
    }

    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to write config register after %d retries\n", MAX_RETRIES);
        return -1;
    }

    gpioDelay(100); // Wait for conversion to complete (adjust as needed)

    retries = 0;
    while (retries < MAX_RETRIES) {
        if (spi_read_register(fd, 0x01, rtd_data, 2) == 0) {
            break;
        } else {
            fprintf(stderr, "Error reading RTD register, retry %d\n", retries + 1);
            retries++;
            gpioDelay(1000); // Wait 1 ms before retrying
        }
    }

    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read RTD register after %d retries\n", MAX_RETRIES);
        return -1;
    }

    rtd_raw = (rtd_data[0] << 8) | rtd_data[1];
    rtd_raw >>= 1; // Remove fault bit

    // Check for fault conditions
    uint8_t fault_data[1];
    if (spi_read_register(fd, 0x07, fault_data, 1) != 0) {
        fprintf(stderr, "Error reading fault register\n");
        return -1;
    }

    if (fault_data[0] & 0x01) {
        fprintf(stderr, "RTD High Threshold Fault\n");
        return -1;
