int spi_init(int channel, int speed, int ce0_pin) {
    int fd = spiOpen(channel, speed, 0); // Mode 0
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %d\n", channel, fd);
        return -1;
    }
    gpioSetMode(ce0_pin, PI_OUTPUT);
    gpioWrite(ce0_pin, 1); // Ensure CE0 is initially high
    return fd;
}

// SPI Read Register
int spi_read_register(int fd, uint8_t reg, uint8_t *data, int len) {
    char tx_buf[len + 1];
    char rx_buf[len + 1];
    tx_buf[0] = reg | 0x80; // Set MSB for read operation
    memset(tx_buf + 1, 0, len); // Fill with dummy data
    memset(rx_buf, 0, len + 1);

    gpioWrite(CE0_PIN, 0); // Select the device
    int result = spiXfer(fd, tx_buf, rx_buf, len + 1);
    gpioWrite(CE0_PIN, 1); // Deselect the device

    if (result != len + 1) {
        fprintf(stderr, "SPI read error: %d\n", result);
        return -1;
    }

    memcpy(data, rx_buf + 1, len);
    return 0;
}

// SPI Write Register
int spi_write_register(int fd, uint8_t reg, uint8_t *data, int len) {
    char tx_buf[len + 1];
    char rx_buf[len + 1];
    tx_buf[0] = reg & 0x7F; // Clear MSB for write operation
    memcpy(tx_buf + 1, data, len);
    memset(rx_buf, 0, len + 1);

    gpioWrite(CE0_PIN, 0); // Select the device
    int result = spiXfer(fd, tx_buf, rx_buf, len + 1);
    gpioWrite(CE0_PIN, 1); // Deselect the device

