// Initialize BME280 sensor
int init_bme280() {
    // Check if pigpio is initialized
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BME280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Check BME280 ID
    int chip_id = i2cReadByteData(i2c_handle, BME280_REG_ID);
    if (chip_id < 0) {
        fprintf(stderr, "Failed to read chip ID: %d\n", chip_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }
    if (chip_id != 0x60) {
        fprintf(stderr, "Incorrect chip ID: 0x%x\n", chip_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Set humidity oversampling to 1x
    if (i2cWriteByteData(i2c_handle, BME280_REG_CTRL_HUMIDITY, 0x01) < 0) {
        fprintf(stderr, "Failed to write humidity control register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Set temperature and pressure oversampling to 1x and normal mode
    if (i2cWriteByteData(i2c_handle, BME280_REG_CTRL_MEAS, 0x27) < 0) {
        fprintf(stderr, "Failed to write control register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read calibration data from BME280
int read_calibration_data() {
    uint8_t data[26];
    if (i2cReadI2CBlockData(i2c_handle, BME280_REG_CALIB_00, (char *)data, 26) < 0) {
        fprintf(stderr, "Failed to read calibration data block 1\n");
        return -1;
    }

    calib.dig_T1 = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
    calib.dig_T2 = (int16_t)data[2] | ((int16_t)data[3] << 8);
    calib.dig_T3 = (int16_t)data[4] | ((int16_t)data[5] << 8);
    calib.dig_P1 = (uint16_t)data[6] | ((uint16_t)data[7] << 8);
    calib.dig_P2 = (int16_t)data[8] | ((int16_t)data[9] << 8);
    calib.dig_P3 = (int16_t)data[10] | ((int16_t)data[11] << 8);
    calib.dig_P4 = (int16_t)data[12] | ((int16_t)data[13] << 8);
    calib.dig_P5 = (int16_t)data[14] | ((int16_t)data[15] << 8);
    calib.dig_P6 = (int16_t)data[16] | ((int16_t)data[17] << 8);
    calib.dig_P7 = (int16_t)data[18] | ((int16_t)data[19] << 8);
    calib.dig_P8 = (int16_t)data[20] | ((int16_t)data[21] << 8);
    calib.dig_P9 = (int16_t)data[22] | ((int16_t)data[23] << 8);
    calib.dig_H1 = data[25];

    uint8_t data_h[7];
    if (i2cReadI2CBlockData(i2c_handle, 0xE1, (char *)data_h, 7) < 0) {
        fprintf(stderr, "Failed to read calibration data block 2\n");
        return -1;
    }

    calib.dig_H2 = (int16_t)data_h[0] | ((int16_t)data_h[1] << 8);
    calib.dig_H3 = data_h[2];
    calib.dig_H4 = (int16_t)((data_h[3] << 4) | (data_h[4] & 0x0F));
    calib.dig_H5 = (int16_t)((data_h[5] << 4) | (data_h[4] >> 4));
    calib.dig_H6 = (int8_t)data_h[6];

    return 0;
}

// Read raw temperature, pressure and humidity data from BME280
int read_raw_data(int32_t *temperature, int32_t *pressure, int32_t *humidity) {
    uint8_t data[8];

    if (i2cReadI2CBlockData(i2c_handle, BME280_REG_PRESSURE_MSB, (char *)data, 8) < 0) {
        fprintf(stderr, "Failed to read raw data\n");
        return -1;
    }

    *pressure = (int32_t)data[0] << 12 | (int32_t)data[1] << 4 | (int32_t)data[2] >> 4;
    *temperature = (int32_t)data[3] << 12 | (int32_t)data[4] << 4 | (int32_t)data[5] >> 4;
    *humidity = (int32_t)data[6] << 8 | (int32_t)data[7];

