#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define BMP180_ADDR 0x77
#define GPIO_ALERT 24
#define BUFFER_SIZE 12
#define SAMPLE_INTERVAL_MS 50
#define DEVIATION_THRESHOLD_HPA 5.0
#define MAX_RETRIES 3

// BMP180 Registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration Data Registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling Setting (OSS)
#define OSS 0 // Highest resolution

// Global Variables
int i2c_handle;
bool running = true;

// Calibration Data
int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
uint16_t ac4, ac5, ac6;

// Circular Buffer
double pressure_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function Prototypes
int init_i2c();
int read_calibration_data();
int read_raw_temperature(int32_t *raw_temperature);
int read_raw_pressure(int32_t *raw_pressure);
double calculate_pressure(int32_t raw_temperature, int32_t raw_pressure);
void add_to_buffer(double pressure);
double calculate_rolling_average();
void check_pressure_deviation(double current_pressure, double average_pressure);
void set_alert_gpio(int state);
void log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read calibration data from BMP180
int read_calibration_data() {
    char buf[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, buf, 22) != 22) {
        log_error("Error reading calibration data");
        return -1;
    }

    ac1 = (buf[0] << 8) | buf[1];
    ac2 = (buf[2] << 8) | buf[3];
    ac3 = (buf[4] << 8) | buf[5];
    ac4 = (buf[6] << 8) | buf[7];
    ac5 = (buf[8] << 8) | buf[9];
    ac6 = (buf[10] << 8) | buf[11];
    b1 = (buf[12] << 8) | buf[13];
    b2 = (buf[14] << 8) | buf[15];
    mb = (buf[16] << 8) | buf[17];
    mc = (buf[18] << 8) | buf[19];
    md = (buf[20] << 8) | buf[21];

    return 0;
}

// Function to read raw temperature data from BMP180
int read_raw_temperature(int32_t *raw_temperature) {
    char buf[2];
    char write_buf[1];

    write_buf[0] = 0x2E; // Temperature measurement command
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, write_buf, 1) != 1) {
        log_error("Error writing temperature measurement command");
        return -1;
    }
    gpioDelay(5000); // Wait 4.5ms

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 2) != 2) {
        log_error("Error reading raw temperature data");
        return -1;
    }

    *raw_temperature = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to read raw pressure data from BMP180
int read_raw_pressure(int32_t *raw_pressure) {
    char buf[3];
    char write_buf[1];

    write_buf[0] = 0x34 + (OSS << 6); // Pressure measurement command
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, write_buf, 1) != 1) {
        log_error("Error writing pressure measurement command");
        return -1;
    }

    gpioDelay(26000); // Wait 25.5ms for OSS = 3

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 3) != 3) {
        log_error("Error reading raw pressure data");
        return -1;
    }

    *raw_pressure = ((int32_t)buf[0] << 16 | (int32_t)buf[1] << 8 | (int32_t)buf[2]) >> (8 - OSS);
    return 0;
}

// Function to calculate pressure in hPa
double calculate_pressure(int32_t raw_temperature, int32_t raw_pressure) {
    int32_t X1, X2, X3, B3, B5, B6, p;
    uint32_t B4, B7;

    // Temperature calculations
    X1 = ((int32_t)raw_temperature - (int32_t)ac6) * ((int32_t)ac5) / pow(2, 15);
    X2 = ((int32_t)mc * pow(2, 11)) / (X1 + md);
    B5 = X1 + X2;

    // Pressure calculations
    B6 = B5 - 4000;
    X1 = (b2 * (B6 * B6 / pow(2, 12))) / pow(2, 11);
    X2 = ac2 * B6 / pow(2, 11);
    X3 = X1 + X2;
    B3 = (((((int32_t)ac1) * 4 + X3) << OSS) + 2) / 4;

    X1 = ac3 * B6 / pow(2, 13);
    X2 = (b1 * (B6 * B6 / pow(2, 12))) / pow(2, 16);
    X3 = ((X1 + X2) + 2) / pow(2, 2);
    B4 = ac4 * (uint32_t)(X3 + 32768) / pow(2, 15);
    B7 = ((uint32_t)raw_pressure - B3) * (50000 >> OSS);

    if (B7 < 0x80000000)
    {
        p = (B7 * 2) / B4;
    }
    else
    {
        p = (B7 / B4) * 2;
    }

    X1 = (p / pow(2, 8)) * (p / pow(2, 8));
    X1 = (X1 * 3038) / pow(2, 16);
    X2 = (-7357 * p) / pow(2, 16);
    p = p + (X1 + X2 + 3791) / pow(2, 4);

    return (double)p / 100.0; // Convert to hPa
}

// Function to add pressure reading to the circular buffer
void add_to_buffer(double pressure) {
    pressure_buffer[buffer_index] = pressure;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to calculate the rolling average of the pressure readings
double calculate_rolling_average() {
    double sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += pressure_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Function to check for pressure deviation and set the alert GPIO
void check_pressure_deviation(double current_pressure, double average_pressure) {
    double deviation = fabs(current_pressure - average_pressure);
    if (deviation > DEVIATION_THRESHOLD_HPA) {
        set_alert_gpio(1); // Set GPIO HIGH
        fprintf(stderr, "Pressure deviation detected: %.2f hPa (Average: %.2f hPa)\n", deviation, average_pressure);
    } else {
        set_alert_gpio(0); // Set GPIO LOW
    }
}

// Function to set the alert GPIO state
void set_alert_gpio(int state) {
    gpioWrite(GPIO_ALERT, state);
}

// Function to log errors to stderr
void log_error(const char *message) {
    fprintf(stderr, "Error: %s (errno: %d)\n", message, errno);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    running = false;
    printf("Caught signal %d, exiting...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    i2cClose(i2c_handle);
    gpioWrite(GPIO_ALERT, 0); // Reset GPIO
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO24 as output
    gpioSetMode(GPIO_ALERT, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        cleanup();
        return 1;
    }

    // Initialize circular buffer with zero values
    for (int i = 0; i < BUFFER_SIZE; i++) {
        pressure_buffer[i] = 0.0;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("BMP180 Pressure Sensor Monitoring Started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int32_t raw_temperature, raw_pressure;
        double pressure;

        // Read raw temperature and pressure
        if (read_raw_temperature(&raw_temperature) == 0 && read_raw_pressure(&raw_pressure) == 0) {
            // Calculate pressure
            pressure = calculate_pressure(raw_temperature, raw_pressure);

            // Add pressure to buffer
            add_to_buffer(pressure);

            // Calculate rolling average
            double average_pressure = calculate_rolling_average();

            // Check for pressure deviation
            check_pressure_deviation(pressure, average_pressure);

            printf("Pressure: %.2f hPa, Rolling Average: %.2f hPa\n", pressure, average_pressure);
        } else {
            log_error("Failed to read sensor data");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for 50ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

