        // Read raw data
        if (read_raw_data(&raw_temperature, &raw_pressure) == 0) {
            // Compensate temperature and pressure
            temperature = compensate_temperature(raw_temperature);
            pressure = compensate_pressure(raw_pressure, temperature);

            // Log data
            if (log_data(temperature, pressure) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read raw data\n");
        }

        // Wait for 5 seconds
        sleep(5);
    }

    return 0;
}

int init_i2c() {
    i2c_handle = i2cOpen(1, bmp280_address, 0); // Bus 1, address, flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
