    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("weather_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (1) {
        int32_t raw_temperature, raw_pressure;
        double temperature, pressure;

        // Read raw data
        if (read_raw_data(&raw_temperature, &raw_pressure) == 0) {
            // Compensate temperature and pressure
            temperature = compensate_temperature(raw_temperature);
            pressure = compensate_pressure(raw_pressure, temperature);

            // Log data
            if (log_data(temperature, pressure) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read raw data\n");
        }

        // Wait for 5 seconds
        sleep(5);
    }

    return 0;
}

int init_i2c() {
    i2c_handle = i2cOpen(1, bmp280_address, 0); // Bus 1, address, flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

int init_bmp280() {
    // Check the sensor ID
    int sensor_id = read_register(i2c_handle, BMP280_REG_ID);
    if (sensor_id != 0x58) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", sensor_id);
        return -1;
    }

    // Set oversampling and mode
    uint8_t ctrl_meas = (BMP280_OVERSAMPLING_TEMP << 5) | (BMP280_OVERSAMPLING_PRESS << 2) | BMP280_MODE_FORCED;
    if (write_register(i2c_handle, BMP280_REG_CTRL_MEAS, ctrl_meas) != 0) {
        return -1;
    }

    // Set filter and standby time (optional, using default values)
    uint8_t config = (0x00 << 5) | (0x00 << 2); // t_sb = 0.5ms, filter off
    if (write_register(i2c_handle, BMP280_REG_CONFIG, config) != 0) {
        return -1;
    }

    return 0;
}

int read_calibration_data() {
    dig_T1 = (read_register(i2c_handle, BMP280_REG_CALIB_00) | (read_register(i2c_handle, BMP280_REG_CALIB_00 + 1) << 8));
    dig_T2 = (int16_t)(read_register(i2c_handle, BMP280_REG_CALIB_00 + 2) | (read_register(i2c_handle, BMP280_REG_CALIB_00 + 3) << 8));
    dig_T3 = (int16_t)(read_register(i2c_handle, BMP280_REG_CALIB_00 + 4) | (read_register(i2c_handle, BMP280_REG_CALIB_00 + 5) << 8));
    dig_P1 = (read_register(i2c_handle, BMP280_REG_CALIB_00 + 6) | (read_register(i2c_handle, BMP280_REG_CALIB_00 + 7) << 8));
    dig_P2 = (int16_t)(read_register(i2c_handle, BMP280_REG_CALIB_00 + 8) | (read_register(i2c_handle, BMP280_REG_CALIB_00 + 9) << 8));
    dig_P3 = (int16_t)(read_register(i2c_handle, BMP280_REG_CALIB_00 + 10) | (read_register(i2c_handle, BMP280_REG_CALIB_00 + 11) << 8));
    dig_P4 = (int16_t)(read_register(i2c_handle, BMP280_REG_CALIB_00 + 12) | (read_register(i2c_handle, BMP280_REG_CALIB_00 + 13) << 8));
    dig_P5 = (int16_t)(read_register(i2c_handle, BMP280_REG_CALIB_00 + 14) | (read_register(i2c_handle, BMP280_REG_CALIB_00 + 15) << 8));
    dig_P6 = (int16_t)(read_register(i2c_handle, BMP280_REG_CALIB_00 + 16) | (read_register(i2c_handle, BMP280_REG_CALIB_00 + 17) << 8));
    dig_P7 = (int16_t)(read_register(i2c_handle, BMP280_REG_CALIB_00 + 18) | (read_register(i2c_handle, BMP280_REG_CALIB_00 + 19) << 8));
    dig_P8 = (int16_t)(read_register(i2c_handle, BMP280_REG_CALIB_00 + 20) | (read_register(i2c_handle, BMP280_REG_CALIB_00 + 21) << 8));
    dig_P9 = (int16_t)(read_register(i2c_handle, BMP280_REG_CALIB_00 + 22) | (read_register(i2c_handle, BMP280_REG_CALIB_00 + 23) << 8));

    return 0;
}

int read_raw_data(int32_t *temperature, int32_t *pressure) {
    // Trigger a measurement by writing to the control register
    uint8_t ctrl_meas = (BMP280_OVERSAMPLING_TEMP << 5) | (BMP280_OVERSAMPLING_PRESS << 2) | BMP280_MODE_FORCED;
    if (write_register(i2c_handle, BMP280_REG_CTRL_MEAS, ctrl_meas) != 0) {
        return -1;
    }

    // Wait for the measurement to complete (adjust delay as needed)
    gpioDelay(100); // 100 ms

    // Read the raw temperature data
    int32_t raw_temp_msb = read_register(i2c_handle, BMP280_REG_TEMP_MSB);
    int32_t raw_temp_lsb = read_register(i2c_handle, BMP280_REG_TEMP_MSB + 1);
    int32_t raw_temp_xlsb = read_register(i2c_handle, BMP280_REG_TEMP_MSB + 2);

    if (raw_temp_msb < 0 || raw_temp_lsb < 0 || raw_temp_xlsb < 0) {
        return -1;
    }

    *temperature = (raw_temp_msb << 12) | (raw_temp_lsb << 4) | (raw_temp_xlsb >> 4);

    // Read the raw pressure data
    int32_t raw_press_msb = read_register(i2c_handle, BMP280_REG_PRESSURE_MSB);
    int32_t raw_press_lsb = read_register(i2c_handle, BMP280_REG_PRESSURE_MSB + 1);
    int32_t raw_press_xlsb = read_register(i2c_handle, BMP280_REG_PRESSURE_MSB + 2);

    if (raw_press_msb < 0 || raw_press_lsb < 0 || raw_press_xlsb < 0) {
        return -1;
    }

    *pressure = (raw_press_msb << 12) | (raw_press_lsb << 4) | (raw_press_xlsb >> 4);

    return 0;
}

double compensate_temperature(int32_t raw_temperature) {
    double var1, var2, T;

    var1 = (((double)raw_temperature) / 16384.0 - ((double)dig_T1) / 1024.0) * ((double)dig_T2);
    var2 = ((((double)raw_temperature) / 131072.0 - ((double)dig_T1) / 8192.0) * (((double)raw_temperature) / 131072.0 - ((double)dig_T1) / 8192.0)) * ((double)dig_T3);
    double t_fine = (var1 + var2);
    T = (var1 + var2) / 5120.0;
    return T;
}

double compensate_pressure(int32_t raw_pressure, double t_fine) {
    double var1, var2, p;

    var1 = ((double)t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * ((double)dig_P6) / 32768.0;
    var2 = var2 + var1 * ((double)dig_P5) * 2.0;
    var2 = (var2 / 4.0) + (((double)dig_P4) * 65536.0);
    var1 = (((double)dig_P3) * var1 * var1 / 524288.0 + ((double)dig_P2) * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * ((double)dig_P1);

    if (var1 == 0)
    {
        return 0;
    }

    p = 1048576.0 - (double)raw_pressure;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = ((double)dig_P9) * p * p / 2147483648.0;
    var2 = p * ((double)dig_P8) / 32768.0;
    p = p + (var1 + var2 + ((double)dig_P7)) / 16.0;

    return p/100.0; // in hPa
}

int log_data(double temperature, double pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Temperature: %.2f °C, Pressure: %.2f hPa\n", timestamp, temperature, pressure);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    cleanup();
    exit(0);
}

void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (error_log_file != NULL) {
        fclose(error_log_file);
    }
