#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pthread.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>

// Constants
#define I2C_BUS 1
#define LM75_ADDR 0x48
#define GPIO_PIN 18 // BCM GPIO 18
#define BUFFER_SIZE 60
#define TEMP_THRESHOLD 28.0
#define NUM_SENSORS 2

// Sensor addresses
const int sensor_addresses[NUM_SENSORS] = {LM75_ADDR, 0x49};

// Global variables
volatile sig_atomic_t program_running = 1;
pthread_mutex_t buffer_mutex;
float temperature_buffer[NUM_SENSORS][BUFFER_SIZE];
int buffer_index[NUM_SENSORS] = {0};
float running_average[NUM_SENSORS] = {0.0};
int i2c_fds[NUM_SENSORS];

// Function prototypes
void signal_handler(int signal);
float read_temperature(int fd);
void update_buffer(float temperature, int sensor_id);
float calculate_average(int sensor_id);
void *alert_thread(void *arg);
void log_error(const char *message);

// Signal handler
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        program_running = 0;
    }
}

// Function to read temperature from LM75 sensor
float read_temperature(int fd) {
    int raw_temp;
    float temperature;

    raw_temp = wiringPiI2CReadReg16(fd, 0x00); // Read temperature register
    if (raw_temp == -1) {
        log_error("Failed to read temperature from I2C.");
        return -1000.0; // Indicate error
    }

    // Convert raw temperature to Celsius
    temperature = (float)((raw_temp >> 5) * 0.125);

    return temperature;
}

// Function to update the circular buffer
void update_buffer(float temperature, int sensor_id) {
    pthread_mutex_lock(&buffer_mutex);
    temperature_buffer[sensor_id][buffer_index[sensor_id]] = temperature;
    buffer_index[sensor_id] = (buffer_index[sensor_id] + 1) % BUFFER_SIZE;
    running_average[sensor_id] = calculate_average(sensor_id);
    pthread_mutex_unlock(&buffer_mutex);
}

// Function to calculate the running average
float calculate_average(int sensor_id) {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += temperature_buffer[sensor_id][i];
    }
    return sum / BUFFER_SIZE;
}

// Alert thread function
void *alert_thread(void *arg) {
    (void)arg; // Suppress unused parameter warning
    while (program_running) {
        bool alert_active = false;
        for (int i = 0; i < NUM_SENSORS; i++) {
            if (running_average[i] > TEMP_THRESHOLD) {
                alert_active = true;
                break;
            }
        }

        if (alert_active) {
            digitalWrite(GPIO_PIN, HIGH); // Turn LED on
        } else {
            digitalWrite(GPIO_PIN, LOW);  // Turn LED off
        }

        delay(100); // Check every 100ms
    }
    pthread_exit(NULL);
}

// Function to log errors to stderr
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(stderr, "[%d-%02d-%02d %02d:%02d:%02d] ERROR: %s (errno: %d)\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message, errno);
}

int main() {
    pthread_t alert_thread_id;

    // Initialize WiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "WiringPi initialization failed!\n");
        return 1;
    }

    // Initialize mutex
    if (pthread_mutex_init(&buffer_mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed!\n");
        return 1;
    }

    // Initialize GPIO pin
    pinMode(GPIO_PIN, OUTPUT);
    digitalWrite(GPIO_PIN, LOW); // Initially turn LED off

    // Initialize I2C
    for (int i = 0; i < NUM_SENSORS; i++) {
        i2c_fds[i] = wiringPiI2CSetup(sensor_addresses[i]);
        if (i2c_fds[i] == -1) {
            fprintf(stderr, "I2C initialization failed for sensor %d at address 0x%02X!\n", i, sensor_addresses[i]);
            log_error("I2C initialization failed.");
            return 1;
        }
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Create alert thread
    if (pthread_create(&alert_thread_id, NULL, alert_thread, NULL) != 0) {
        fprintf(stderr, "Failed to create alert thread!\n");
        log_error("Failed to create alert thread.");
        return 1;
    }

    // Main loop
    while (program_running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            float temperature = read_temperature(i2c_fds[i]);
            if (temperature > -999.0) { // Check for valid temperature reading
                printf("Sensor %d: Temperature = %.2f °C, Running Average = %.2f °C\n", i, temperature, running_average[i]);
                update_buffer(temperature, i);
            } else {
                log_error("Failed to read temperature from sensor.");
            }
        }
        delay(1000); // Read every 1 second
    }

    // Cleanup
    printf("Cleaning up...\n");
    pthread_join(alert_thread_id, NULL);
    pthread_mutex_destroy(&buffer_mutex);
    digitalWrite(GPIO_PIN, LOW); // Turn off LED

    for (int i = 0; i < NUM_SENSORS; i++) {
        close(i2c_fds[i]);
    }

    return 0;
}

