#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <jansson.h>
#include <errno.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define HEATER_GPIO 18
#define PWM_FREQUENCY 1000 // 1 kHz
#define PWM_RANGE 1000
#define MAX_TEMP 80.0
#define CONFIG_FILE "config.json"
#define LOG_FILE "heater_control.log"

// Global variables
int spi_handle;
double target_temperature = 25.0;
double Kp = 1.0;
double Ki = 0.1;
double Kd = 0.01;
volatile sig_atomic_t terminate = 0;
FILE *log_file = NULL;

// Function prototypes
int read_config(const char *filename);
double read_temperature();
double calculate_pid(double setpoint, double actual_temperature, double *integral, double *previous_error);
void set_heater_power(double power);
void signal_handler(int signal);
void log_message(const char *message);

// Function to read configuration from JSON file
int read_config(const char *filename) {
    json_t *root;
    json_error_t error;

    root = json_load_file(filename, 0, &error);
    if (!root) {
        fprintf(stderr, "Error: Could not load config file: %s\n", error.text);
        return -1;
    }

    json_t *temp = json_object_get(root, "target_temperature");
    if (json_is_real(temp)) {
        target_temperature = json_real_value(temp);
    } else {
        fprintf(stderr, "Warning: target_temperature not found in config file, using default: %.2f\n", target_temperature);
    }

    json_t *kp = json_object_get(root, "Kp");
    if (json_is_real(kp)) {
        Kp = json_real_value(kp);
    } else {
        fprintf(stderr, "Warning: Kp not found in config file, using default: %.2f\n", Kp);
    }

    json_t *ki = json_object_get(root, "Ki");
    if (json_is_real(ki)) {
        Ki = json_real_value(ki);
    } else {
        fprintf(stderr, "Warning: Ki not found in config file, using default: %.2f\n", Ki);
    }

    json_t *kd = json_object_get(root, "Kd");
    if (json_is_real(kd)) {
        Kd = json_real_value(kd);
    } else {
        fprintf(stderr, "Warning: Kd not found in config file, using default: %.2f\n", Kd);
    }

    json_decref(root);
    return 0;
}

// Function to read temperature from MAX31865
double read_temperature() {
    unsigned char data[4];
    int result;
    double temperature = -1000.0; // Initialize to an invalid value

    // Read RTD MSB and LSB registers (0x01 and 0x02)
    result = spiRead(spi_handle, data, 4);
    if (result != 4) {
        fprintf(stderr, "Error: SPI read failed: %s\n", strerror(errno));
        log_message("SPI read failed");
        return temperature;
    }

    // Check for fault conditions
    if (data[3] & 0x01) {
        fprintf(stderr, "Error: MAX31865 fault detected!\n");
        log_message("MAX31865 fault detected");
        return temperature;
    }

    // Extract RTD value (bits 31:18)
    int16_t rtd_raw = ((data[0] << 8) | data[1]) >> 2;

    // Convert RTD value to temperature (PT100)
    temperature = (rtd_raw * 0.25) - 25.0;

    return temperature;
}

// Function to calculate PID output
double calculate_pid(double setpoint, double actual_temperature, double *integral, double *previous_error) {
    double error = setpoint - actual_temperature;
    *integral += error;
    double derivative = error - *previous_error;
    double output = Kp * error + Ki * (*integral) + Kd * derivative;
    *previous_error = error;

    // Clamp the output to the PWM range
    if (output < 0) output = 0;
    if (output > PWM_RANGE) output = PWM_RANGE;

    return output;
}

// Function to set heater power using PWM
void set_heater_power(double power) {
    gpioPWM(HEATER_GPIO, (int)power);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    log_message("Signal received, terminating...");
    terminate = 1;
}

// Function to log messages to file
void log_message(const char *message) {
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", message);
        fflush(log_file); // Ensure immediate write
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

