    X1 = (X1 * 3038) >> 16;
    X2 = (-7357 * p) >> 16;
    float pressure = p + ((X1 + X2 + 3791) >> 4);

    return pressure;
}

// Function to add data to the circular buffer
void add_to_buffer(sensor_data_t data)
{
    buffer[buffer_index] = data;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void print_buffer()
{
    printf("\n--- Sensor Data Buffer ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE;
        printf("[%d] Timestamp: %ld, Temperature: %.2f °C, Pressure: %.2f Pa\n",
               i, buffer[index].timestamp, buffer[index].temperature, buffer[index].pressure);
    }
    printf("--- End of Buffer ---\n\n");
}

// Function to control the cooling fan
void control_fan(float temperature)
{
    if (temperature > 30.0f) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
        printf("Fan ON (Temperature: %.2f °C)\n", temperature);
    } else {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
        printf("Fan OFF (Temperature: %.2f °C)\n", temperature);
    }
}

// Timer callback function
void timer_callback()
{
    int32_t raw_temperature, raw_pressure;
    float temperature, pressure;
    sensor_data_t data;

    if (read_raw_temperature(&raw_temperature) == 0 && read_raw_pressure(&raw_pressure) == 0) {
        temperature = calculate_temperature(raw_temperature);
        pressure = calculate_pressure(raw_pressure, raw_temperature);

        data.timestamp = time(NULL);
        data.temperature = temperature;
        data.pressure = pressure;

        add_to_buffer(data);

        printf("Timestamp: %ld, Temperature: %.2f °C, Pressure: %.2f Pa\n",
               data.timestamp, data.temperature, data.pressure);

        control_fan(temperature);
    } else {
        fprintf(stderr, "Error reading sensor data in timer callback\n");
    }
}

// Signal handler function
void signal_handler(int signal)
{
    printf("Caught signal %d, exiting gracefully...\n", signal);
    program_running = 0;
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set FAN_GPIO as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0); // Initially turn the fan off

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up timer callback (every 500ms)
    gpioSetTimerFuncEx(0, 500, timer_callback, NULL);

    printf("BMP180 sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        sleep(1); // Sleep for 1 second
    }

    // Cleanup
    gpioWrite(FAN_GPIO, 0); // Turn fan off
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

