#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 2000000 // 2 MHz
#define HEATER_GPIO 17
#define TARGET_TEMPERATURE 25.0
#define MAX_DUTY_CYCLE 80.0
#define LOG_FILE "heater_log.csv"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_max31855(int spi_handle, float *temperature, float *internal_temperature, uint8_t *fault);
float calculate_duty_cycle(float target_temperature, float current_temperature, float *integral, float *previous_error);
void set_heater_duty_cycle(int gpio_pin, float duty_cycle);
void log_data(float temperature, float internal_temperature, float duty_cycle, const char *error_message);
void signal_handler(int signal);

// Function to read data from MAX31855
int read_max31855(int spi_handle, float *temperature, float *internal_temperature, uint8_t *fault) {
    char rx_buffer[4];
    int result = spiRead(spi_handle, rx_buffer, 4);

    if (result != 4) {
        log_data(*temperature, *internal_temperature, 0.0, "SPI read failed");
        return -1;
    }

    // Check for fault bits
    *fault = rx_buffer[3] & 0x07;
    if (*fault != 0) {
        char error_message[50];
        sprintf(error_message, "MAX31855 Fault: 0x%02X", *fault);
        log_data(*temperature, *internal_temperature, 0.0, error_message);
        return -1;
    }

    // Extract temperature data
    int16_t raw_temp = ((rx_buffer[0] << 8) | rx_buffer[1]) >> 2;
    *temperature = raw_temp * 0.25;

    // Extract internal temperature data
    int16_t raw_internal_temp = ((rx_buffer[2] << 8) | rx_buffer[3]) >> 4;
    *internal_temperature = raw_internal_temp * 0.0625;

    return 0;
}

// Function to calculate duty cycle using PI controller
float calculate_duty_cycle(float target_temperature, float current_temperature, float *integral, float *previous_error) {
    float error = target_temperature - current_temperature;
    *integral += error;

    // Anti-windup
    if (*integral > 100.0) *integral = 100.0;
    if (*integral < -100.0) *integral = -100.0;

    float derivative = error - *previous_error;
    float proportional_gain = 1.0; // Adjust as needed
    float integral_gain = 0.1;    // Adjust as needed

    float output = proportional_gain * error + integral_gain * (*integral) + 0.0 * derivative; // 0.0 for derivative gain

    *previous_error = error;

    // Limit duty cycle to 0-100%
    if (output > 100.0) output = 100.0;
    if (output < 0.0) output = 0.0;

    return output;
}

// Function to set heater duty cycle using PWM
void set_heater_duty_cycle(int gpio_pin, float duty_cycle) {
    int pwm_range = 1000; // Adjust as needed
    int pwm_value = (int)(duty_cycle * pwm_range / 100.0);
    gpioPWM(gpio_pin, pwm_value);
}

// Function to log data to file
void log_data(float temperature, float internal_temperature, float duty_cycle, const char *error_message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%s\n", timestamp, temperature, internal_temperature, duty_cycle, error_message);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 2MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set heater GPIO as output
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);

    // Set PWM range and frequency
    gpioSetPWMrange(HEATER_GPIO, 1000); // Adjust range as needed
    gpioSetPWMfrequency(HEATER_GPIO, 1000); // Adjust frequency as needed

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
