    uint8_t fault;

    // Main loop
    while (!terminate) {
        // Read temperature from MAX31855
        if (read_max31855(spi_handle, &temperature, &internal_temperature, &fault) == 0) {
            // Calculate duty cycle
            float duty_cycle = calculate_duty_cycle(TARGET_TEMPERATURE, temperature, &integral, &previous_error);

            // Set heater duty cycle
            set_heater_duty_cycle(HEATER_GPIO, duty_cycle);

            // Log data
            log_data(temperature, internal_temperature, duty_cycle, "OK");

            printf("Temperature: %.2f C, Internal Temperature: %.2f C, Duty Cycle: %.2f %%\n", temperature, internal_temperature, duty_cycle);
