#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Temperature thresholds (millidegrees Celsius)
#define TEMP_THRESHOLD_LOW  40000
#define TEMP_THRESHOLD_HIGH 60000

// Global flag for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read CPU temperature from file
int read_cpu_temperature() {
    FILE *fp;
    char buffer[10];
    int temperature = -1;

    fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening temperature file: %s\n", strerror(errno));
        return -1;
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        if (ferror(fp)) {
            fprintf(stderr, "Error reading temperature file: %s\n", strerror(errno));
        } else {
            fprintf(stderr, "Error reading temperature file: EOF reached\n");
        }
        fclose(fp);
        return -1;
    }

    fclose(fp);

    temperature = atoi(buffer);
    return temperature;
}

// Function to set RGB LED color using PWM
void set_led_color(int red, int green, int blue) {
    if (gpioPWM(RED_PIN, 255 - red) != 0) {
        fprintf(stderr, "Error setting PWM for RED_PIN: %s\n", strerror(errno));
    }
    if (gpioPWM(GREEN_PIN, 255 - green) != 0) {
        fprintf(stderr, "Error setting PWM for GREEN_PIN: %s\n", strerror(errno));
    }
    if (gpioPWM(BLUE_PIN, 255 - blue) != 0) {
        fprintf(stderr, "Error setting PWM for BLUE_PIN: %s\n", strerror(errno));
    }
}

int main() {
    int temperature;
    int red, green, blue;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("CPU Temperature Monitoring and RGB LED Control\n");

    // Main loop
    while (program_running) {
        // Read CPU temperature
        temperature = read_cpu_temperature();

        if (temperature == -1) {
            fprintf(stderr, "Failed to read CPU temperature. Skipping this iteration.\n");
            sleep(0.5);
            continue;
        }

        // Determine RGB color based on temperature
        if (temperature < TEMP_THRESHOLD_LOW) {
            red = 0;
            green = 0;
            blue = 255;
        } else if (temperature < TEMP_THRESHOLD_HIGH) {
            red = 0;
            green = 255;
            blue = 0;
        } else {
            red = 255;
            green = 0;
            blue = 0;
        }

        // Set LED color
        set_led_color(red, green, blue);

        // Print temperature and PWM values
        printf("Temperature: %d m°C, Red: %d, Green: %d, Blue: %d\n", temperature, red, green, blue);

        // Wait for 0.5 seconds
        sleep(0.5);
    }

    // Turn off LED before exiting
    set_led_color(0, 0, 0);

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

