#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <curl/curl.h>
#include <pigpio.h>

#define DHT22_GPIO 4
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100
#define SERVER_URL "http://yourserver.com/api/humidity"

// Structure to hold DHT22 data
typedef struct {
    float temperature;
    float humidity;
} DHT22Data;

// Global flag for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to read data from DHT22 sensor
int read_dht22(DHT22Data *data) {
    int i, j;
    int data_bits[40];
    int checksum;
    int calculated_checksum;

    // Set GPIO mode to output
    gpioSetMode(DHT22_GPIO, PI_OUTPUT);

    // Send start signal
    gpioWrite(DHT22_GPIO, 0);
    gpioDelay(1); // 1ms
    gpioWrite(DHT22_GPIO, 1);
    gpioDelay(30); // 30us

    // Set GPIO mode to input
    gpioSetMode(DHT22_GPIO, PI_INPUT);

    // Read data bits
    for (i = 0; i < 40; i++) {
        // Wait for low
        int count = 0;
        while (gpioRead(DHT22_GPIO) == 0) {
            gpioDelay(1); // 1us delay
            count++;
            if (count > 100) return -1; // Timeout
        }

        // Wait for high
        count = 0;
        while (gpioRead(DHT22_GPIO) == 1) {
            gpioDelay(1); // 1us delay
            count++;
            if (count > 100) return -1; // Timeout
        }

        // Determine bit value based on high duration
        if (count > 40) {
            data_bits[i] = 1;
        } else {
            data_bits[i] = 0;
        }
    }

    // Convert data bits to bytes
    int bytes[5];
    for (i = 0; i < 5; i++) {
        bytes[i] = 0;
        for (j = 0; j < 8; j++) {
            bytes[i] <<= 1;
            bytes[i] |= data_bits[i * 8 + j];
        }
    }

    // Validate checksum
    checksum = bytes[4];
    calculated_checksum = 0;
    for (i = 0; i < 4; i++) {
        calculated_checksum += bytes[i];
    }
    calculated_checksum &= 0xFF;

    if (checksum != calculated_checksum) {
        fprintf(stderr, "Checksum mismatch: received 0x%02X, calculated 0x%02X\n", checksum, calculated_checksum);
        return -1;
    }

    // Extract temperature and humidity
    data->humidity = (float)(((bytes[0] << 8) | bytes[1])) / 10.0;
    data->temperature = (float)(((bytes[2] << 8) | bytes[3])) / 10.0;

    // Check for negative temperature
    if (data->temperature > 125) {
        data->temperature = data->temperature - 256;
    }

    return 0;
}

// Function to format data as JSON
char *format_json(const DHT22Data *data) {
    char *json_string = malloc(100); // Allocate memory for the JSON string
    if (json_string == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    snprintf(json_string, 100, "{\"temperature\": %.1f, \"humidity\": %.1f}", data->temperature, data->humidity);
    return json_string;
}

// Function to post data to server
int post_data(const char *json_data) {
    CURL *curl;
    CURLcode res;
    struct curl_slist *headers = NULL;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, SERVER_URL);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);

        // Set content type header
        headers = curl_slist_append(headers, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        } else {
            long response_code;
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
            if (response_code >= 200 && response_code < 300) {
                printf("Data posted successfully\n");
            } else {
                fprintf(stderr, "HTTP request failed with code: %ld\n", response_code);
                res = CURLE_HTTP_RETURNED_ERROR; // Indicate HTTP error
            }
        }

        curl_easy_cleanup(curl);
        curl_slist_free_all(headers);
    } else {
        fprintf(stderr, "curl_easy_init() failed\n");
        res = CURLE_FAILED_INIT;
    }
    curl_global_cleanup();
    return (res == CURLE_OK) ? 0 : -1;
}

int main() {
    DHT22Data data;
    char *json_data;
    int retries;
    int result;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        retries = 0;
        result = -1; // Initialize to failure

        while (retries < MAX_RETRIES && result != 0) {
            // Read DHT22 data
            if (read_dht22(&data) == 0) {
                // Format data as JSON
                json_data = format_json(&data);
                if (json_data != NULL) {
                    // Post data to server
                    if (post_data(json_data) == 0) {
                        result = 0; // Success
                    } else {
                        fprintf(stderr, "Failed to post data, retrying...\n");
                    }
                    free(json_data);
                } else {
                    fprintf(stderr, "Failed to format JSON, retrying...\n");
                }
            } else {
                fprintf(stderr, "Failed to read DHT22 data, retrying...\n");
            }

            if (result != 0) {
                retries++;
                gpioDelay(RETRY_DELAY_MS); // Wait before retrying
            }
        }

        if (result != 0) {
            fprintf(stderr, "Failed to read DHT22 data after %d retries\n", MAX_RETRIES);
        }

        sleep(5); // Wait 5 seconds before next reading
    }

    // Clean up
    gpioTerminate();

    fprintf(stderr, "Program terminated successfully\n");
    return 0;
}

