    data->humidity = (float)(((bytes[0] << 8) | bytes[1])) / 10.0;
    data->temperature = (float)(((bytes[2] << 8) | bytes[3])) / 10.0;

    // Check for negative temperature
    if (data->temperature > 125) {
        data->temperature = data->temperature - 256;
    }

    return 0;
}

// Function to format data as JSON
char *format_json(const DHT22Data *data) {
    char *json_string = malloc(100); // Allocate memory for the JSON string
    if (json_string == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    snprintf(json_string, 100, "{\"temperature\": %.1f, \"humidity\": %.1f}", data->temperature, data->humidity);
    return json_string;
}

// Function to post data to server
int post_data(const char *json_data) {
    CURL *curl;
    CURLcode res;
    struct curl_slist *headers = NULL;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, SERVER_URL);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);

        // Set content type header
        headers = curl_slist_append(headers, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        } else {
            long response_code;
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
            if (response_code >= 200 && response_code < 300) {
                printf("Data posted successfully\n");
            } else {
                fprintf(stderr, "HTTP request failed with code: %ld\n", response_code);
                res = CURLE_HTTP_RETURNED_ERROR; // Indicate HTTP error
            }
        }

        curl_easy_cleanup(curl);
        curl_slist_free_all(headers);
    } else {
        fprintf(stderr, "curl_easy_init() failed\n");
        res = CURLE_FAILED_INIT;
    }
    curl_global_cleanup();
    return (res == CURLE_OK) ? 0 : -1;
}

