    DHT22Data data;
    char *json_data;
    int retries;
    int result;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        retries = 0;
        result = -1; // Initialize to failure

        while (retries < MAX_RETRIES && result != 0) {
            // Read DHT22 data
            if (read_dht22(&data) == 0) {
                // Format data as JSON
                json_data = format_json(&data);
                if (json_data != NULL) {
                    // Post data to server
                    if (post_data(json_data) == 0) {
                        result = 0; // Success
                    } else {
                        fprintf(stderr, "Failed to post data, retrying...\n");
                    }
                    free(json_data);
                } else {
                    fprintf(stderr, "Failed to format JSON, retrying...\n");
                }
            } else {
                fprintf(stderr, "Failed to read DHT22 data, retrying...\n");
            }

            if (result != 0) {
                retries++;
                gpioDelay(RETRY_DELAY_MS); // Wait before retrying
            }
        }

        if (result != 0) {
            fprintf(stderr, "Failed to read DHT22 data after %d retries\n", MAX_RETRIES);
        }

        sleep(5); // Wait 5 seconds before next reading
    }

    // Clean up
    gpioTerminate();

    fprintf(stderr, "Program terminated successfully\n");
    return 0;
}

