#include <unistd.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting (OSS = 3)
#define OSS 3

// Conversion delay (26 ms for OSS = 3)
#define CONVERSION_DELAY 26000

// Debounce time (200 ms)
#define DEBOUNCE_TIME 200000

// GPIO pin for the push-button
#define BUTTON_GPIO 4

// Global variables
int i2c_handle;
volatile int logging_enabled = 0;
volatile uint32_t last_interrupt_time = 0;

// Calibration data
int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
uint16_t ac4, ac5, ac6;

// Function prototypes
int read_calibration_data();
int read_raw_temperature(int32_t *raw_temperature);
int read_raw_pressure(int32_t *raw_pressure);
double calculate_temperature(int32_t raw_temperature);
double calculate_pressure(int32_t raw_pressure, int32_t raw_temperature);
void log_pressure(double pressure);
void button_interrupt_handler(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// Function to read a 16-bit value from the I2C bus
int16_t read_i2c_word(int handle, uint8_t reg)
{
    char buf[2];
    if (i2cReadI2CBlockData(handle, reg, buf, 2) != 2) {
        fprintf(stderr, "Error reading I2C block data from register 0x%02X\n", reg);
        return -1;
    }
    return (int16_t)((buf[0] << 8) | buf[1]);
}

// Function to read a 8-bit value from the I2C bus
int8_t read_i2c_byte(int handle, uint8_t reg)
{
    char buf[1];
    if (i2cReadI2CBlockData(handle, reg, buf, 1) != 1) {
        fprintf(stderr, "Error reading I2C block data from register 0x%02X\n", reg);
        return -1;
    }
    return buf[0];
}

// Function to write a 8-bit value to the I2C bus
int write_i2c_byte(int handle, uint8_t reg, uint8_t value)
{
    char buf[1];
    buf[0] = value;
    if (i2cWriteI2CBlockData(handle, reg, buf, 1) != 1) {
        fprintf(stderr, "Error writing I2C block data to register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

// Function to read calibration data from the BMP180
int read_calibration_data()
{
    ac1 = read_i2c_word(i2c_handle, BMP180_REG_CAL_AC1);
    ac2 = read_i2c_word(i2c_handle, BMP180_REG_CAL_AC2);
    ac3 = read_i2c_word(i2c_handle, BMP180_REG_CAL_AC3);
    ac4 = read_i2c_word(i2c_handle, BMP180_REG_CAL_AC4);
    ac5 = read_i2c_word(i2c_handle, BMP180_REG_CAL_AC5);
    ac6 = read_i2c_word(i2c_handle, BMP180_REG_CAL_AC6);
    b1 = read_i2c_word(i2c_handle, BMP180_REG_CAL_B1);
    b2 = read_i2c_word(i2c_handle, BMP180_REG_CAL_B2);
    mb = read_i2c_word(i2c_handle, BMP180_REG_CAL_MB);
    mc = read_i2c_word(i2c_handle, BMP180_REG_CAL_MC);
    md = read_i2c_word(i2c_handle, BMP180_REG_CAL_MD);

    if (ac1 == -1 || ac2 == -1 || ac3 == -1 || ac4 == -1 || ac5 == -1 || ac6 == -1 ||
        b1 == -1 || b2 == -1 || mb == -1 || mc == -1 || md == -1) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    return 0;
}

// Function to read the raw temperature value from the BMP180
int read_raw_temperature(int32_t *raw_temperature)
{
    if (write_i2c_byte(i2c_handle, BMP180_REG_CONTROL, 0x2E) != 0) {
        fprintf(stderr, "Error writing temperature conversion command\n");
        return -1;
    }
    gpioDelay(CONVERSION_DELAY);

    int msb = read_i2c_byte(i2c_handle, BMP180_REG_MSB);
    int lsb = read_i2c_byte(i2c_handle, BMP180_REG_LSB);

    if (msb == -1 || lsb == -1) {
        fprintf(stderr, "Error reading raw temperature data\n");
        return -1;
    }

    *raw_temperature = ((int32_t)msb << 8) | (int32_t)lsb;
    return 0;
}

// Function to read the raw pressure value from the BMP180
int read_raw_pressure(int32_t *raw_pressure)
{
    if (write_i2c_byte(i2c_handle, BMP180_REG_CONTROL, 0x34 + (OSS << 6)) != 0) {
        fprintf(stderr, "Error writing pressure conversion command\n");
        return -1;
    }
    gpioDelay(CONVERSION_DELAY);

    int msb = read_i2c_byte(i2c_handle, BMP180_REG_MSB);
    int lsb = read_i2c_byte(i2c_handle, BMP180_REG_LSB);
    int xlsb = read_i2c_byte(i2c_handle, BMP180_REG_XLSB);

    if (msb == -1 || lsb == -1 || xlsb == -1) {
        fprintf(stderr, "Error reading raw pressure data\n");
        return -1;
    }

    *raw_pressure = (((int32_t)msb << 16) | ((int32_t)lsb << 8) | (int32_t)xlsb) >> (8 - OSS);
    return 0;
}

// Function to calculate the compensated temperature in degrees Celsius
double calculate_temperature(int32_t raw_temperature)
{
    int32_t X1 = ((int32_t)raw_temperature - (int32_t)ac6) * ((int32_t)ac5) / pow(2, 15);
    int32_t X2 = ((int32_t)mc * pow(2, 11)) / (X1 + md);
    int32_t B5 = X1 + X2;
    double temperature = (B5 + 8) / pow(2, 4) / 10.0;
    return temperature;
}

// Function to calculate the compensated pressure in hPa
double calculate_pressure(int32_t raw_pressure, int32_t raw_temperature)
{
    int32_t X1 = ((int32_t)raw_temperature - (int32_t)ac6) * ((int32_t)ac5) / pow(2, 15);
    int32_t X2 = ((int32_t)mc * pow(2, 11)) / (X1 + md);
    int32_t B5 = X1 + X2;

    int32_t B6 = B5 - 4000;
    int32_t X3 = ((int32_t)b2 * (B6 * B6) / pow(2, 12)) / pow(2, 11);
    int32_t X4 = ((int32_t)ac2 * B6) / pow(2, 11);
    int32_t B3 = (((((int32_t)ac1) * 4 + X3) << OSS) + 2) / 4;

    uint32_t X1_u = ((uint32_t)ac3 * B6) / pow(2, 13);
    uint32_t X2_u = ((uint32_t)b1 * (B6 * B6) / pow(2, 12)) / pow(2, 16);
    uint32_t B4 = ((uint32_t)ac4 * (X1_u + X2_u + 32768)) / pow(2, 15);

    uint32_t B7 = ((uint32_t)raw_pressure - B3) * (50000 >> OSS);
    int32_t p;
    if (B7 < 0x80000000)
    {
        p = (B7 * 2) / B4;
    }
    else
    {
        p = (B7 / B4) * 2;
    }

    X1 = (p / pow(2, 8)) * (p / pow(2, 8));
    X1 = (X1 * 3038) / pow(2, 16);
    X2 = (-7357 * p) / pow(2, 16);
    double pressure = p + (X1 + X2 + 3791) / pow(2, 4);
    return pressure / 100.0; // Convert to hPa
}

// Function to log the pressure value to a file
void log_pressure(double pressure)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen("pressure_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening pressure_log.txt for writing\n");
        return;
    }

    fprintf(fp, "%s, %.2f hPa\n", timestamp, pressure);
    fclose(fp);
}

// Interrupt handler for the push-button
void button_interrupt_handler(int gpio, int level, uint32_t tick)
{
    if (level == FALLING_EDGE) {
        uint32_t current_time = gpioTick();
        if (current_time - last_interrupt_time > DEBOUNCE_TIME) {
            logging_enabled = !logging_enabled;
            printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
            last_interrupt_time = current_time;
        }
    }
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure GPIO 4 as input with pull-up resistor
    gpioSetMode(BUTTON_GPIO, PI_INPUT);
    gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP);

    // Set interrupt handler for falling edge on GPIO 4
    gpioSetAlertFuncEx(BUTTON_GPIO, button_interrupt_handler, NULL);

    // Set up signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("BMP180 data logger started. Press the button to toggle logging.\n");

    // Main loop
    while (1) {
        if (logging_enabled) {
            int32_t raw_temperature, raw_pressure;

            // Read raw temperature and pressure
            if (read_raw_temperature(&raw_temperature) == 0 && read_raw_pressure(&raw_pressure) == 0) {
                // Calculate compensated temperature and pressure
                double temperature = calculate_temperature(raw_temperature);
                double pressure = calculate_pressure(raw_pressure, raw_temperature);

                // Log the pressure value
                log_pressure(pressure);

                printf("Temperature: %.2f °C, Pressure: %.2f hPa\n", temperature, pressure);
            } else {
                fprintf(stderr, "Error reading sensor data\n");
            }
        } else {
            printf("Logging disabled. Press the button to enable.\n");
        }

        gpioDelay(2000000); // Wait 2 seconds
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

