    gpioSetMode(BUTTON_GPIO, PI_INPUT);
    gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP);

    // Set interrupt handler for falling edge on GPIO 4
    gpioSetAlertFuncEx(BUTTON_GPIO, button_interrupt_handler, NULL);

    // Set up signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("BMP180 data logger started. Press the button to toggle logging.\n");

    // Main loop
    while (1) {
        if (logging_enabled) {
            int32_t raw_temperature, raw_pressure;

            // Read raw temperature and pressure
            if (read_raw_temperature(&raw_temperature) == 0 && read_raw_pressure(&raw_pressure) == 0) {
                // Calculate compensated temperature and pressure
                double temperature = calculate_temperature(raw_temperature);
                double pressure = calculate_pressure(raw_pressure, raw_temperature);

                // Log the pressure value
                log_pressure(pressure);

                printf("Temperature: %.2f °C, Pressure: %.2f hPa\n", temperature, pressure);
            } else {
                fprintf(stderr, "Error reading sensor data\n");
            }
        } else {
            printf("Logging disabled. Press the button to enable.\n");
        }

        gpioDelay(2000000); // Wait 2 seconds
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

