#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <curl/curl.h>
#include <jansson.h>
#include <pigpio.h>

#define DHT22_GPIO 4
#define MAX_RETRIES 3
#define DEFAULT_URL "http://your-the-librarys-api-call.com/api/humidity"

// Structure to hold DHT22 data
typedef struct {
    float temperature;
    float humidity;
} DHT22Data;

// Global variables
static volatile int running = 1;
static char *api_url = DEFAULT_URL;

// Function prototypes
int read_dht22(DHT22Data *data);
int validate_checksum(const unsigned char *data);
int post_data(const DHT22Data *data, const char *url);
void signal_handler(int signal);
void log_message(int priority, const char *message);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_message(LOG_INFO, "Received signal, shutting down...");
}

// Logging function
void log_message(int priority, const char *message) {
    syslog(priority, "%s", message);
}

// Function to read DHT22 data
int read_dht22(DHT22Data *data) {
    int retries = 0;
    int result;
    unsigned char raw_data[5] = {0};

    while (retries < MAX_RETRIES) {
        // Reset GPIO
        gpioSetMode(DHT22_GPIO, PI_OUTPUT);
        gpioWrite(DHT22_GPIO, 0);
        gpioDelay(1); // 1ms
        gpioWrite(DHT22_GPIO, 1);
        gpioDelay(30); // 30us

        // Set GPIO as input
        gpioSetMode(DHT22_GPIO, PI_INPUT);

        // Read data
        for (int i = 0; i < 40; i++) {
            int count = 0;
            while (gpioRead(DHT22_GPIO) == 0) {
                count++;
                gpioDelay(1); // Delay 1us
                if (count > 200) {
                    log_message(LOG_ERR, "Timeout waiting for start of data bit");
                    return -1;
                }
            }

            count = 0;
            while (gpioRead(DHT22_GPIO) == 1) {
                count++;
                gpioDelay(1); // Delay 1us
                if (count > 200) {
                    log_message(LOG_ERR, "Timeout waiting for end of data bit");
                    return -1;
                }
            }

            raw_data[i / 8] <<= 1;
            if (count > 40) {
                raw_data[i / 8] |= 1;
            }
        }

        // Validate checksum
        if (validate_checksum(raw_data)) {
            data->humidity = (float)(((unsigned int)raw_data[0] << 8) | raw_data[1]) / 10.0;
            data->temperature = (float)(((unsigned int)(raw_data[2] & 0x7F) << 8) | raw_data[3]) / 10.0;
            if (raw_data[2] & 0x80) {
                data->temperature *= -1.0;
            }
            return 0; // Success
        } else {
            log_message(LOG_WARNING, "Checksum validation failed, retrying...");
            retries++;
            sleep(2);
        }
    }

    log_message(LOG_ERR, "Failed to read DHT22 data after multiple retries.");
    return -1; // Failure
}

// Function to validate checksum
int validate_checksum(const unsigned char *data) {
    return (data[0] + data[1] + data[2] + data[3]) == data[4];
}

// Function to post data to API
int post_data(const DHT22Data *data, const char *url) {
    CURL *curl;
    CURLcode res;
    char json_string[100];
    struct curl_slist *headers = NULL;
    int retries = 0;

    // Format data as JSON
    json_string[0] = '\0'; // Initialize string
    snprintf(json_string, sizeof(json_string), "{\"temperature\": %.1f, \"humidity\": %.1f}", data->temperature, data->humidity);

    while (retries < MAX_RETRIES) {
        curl_global_init(CURL_GLOBAL_DEFAULT);
        curl = curl_easy_init();
        if (curl) {
            curl_easy_setopt(curl, CURLOPT_URL, url);
            curl_easy_setopt(curl, CURLOPT_POST, 1L);
            curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_string);
            curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, (long)strlen(json_string));

            headers = curl_slist_append(headers, "Content-Type: application/json");
            curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

            res = curl_easy_perform(curl);
            if (res != CURLE_OK) {
                log_message(LOG_ERR, curl_easy_strerror(res));
            } else {
                long response_code;
                curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
                if (response_code >= 200 && response_code < 300) {
                    log_message(LOG_INFO, "Data posted successfully.");
                    curl_slist_free_all(headers);
                    curl_easy_cleanup(curl);
                    curl_global_cleanup();
                    return 0; // Success
                } else {
                    log_message(LOG_ERR, "HTTP request failed with status code: %ld", response_code);
                }
            }

            curl_slist_free_all(headers);
            curl_easy_cleanup(curl);
        } else {
            log_message(LOG_ERR, "Failed to initialize libcurl.");
        }
        curl_global_cleanup();
        retries++;
        sleep(2);
    }

    log_message(LOG_ERR, "Failed to post data after multiple retries.");
    return -1; // Failure
}

int main(int argc, char *argv[]) {
    int opt;
    DHT22Data data;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                api_url = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-s <url>]\n", argv[0]);
                return 1;
        }
    }

    // Initialize syslog
    openlog("dht22_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    log_message(LOG_INFO, "DHT22 monitor started.");

    // Main loop
    while (running) {
        if (read_dht22(&data) == 0) {
            char log_buffer[100];
            snprintf(log_buffer, sizeof(log_buffer), "Temperature: %.1f°C, Humidity: %.1f%%", data.temperature, data.humidity);
            log_message(LOG_INFO, log_buffer);

            if (post_data(&data, api_url) != 0) {
                log_message(LOG_ERR, "Failed to post data.");
            }
        } else {
            log_message(LOG_ERR, "Failed to read DHT22 data.");
        }

        sleep(10);
    }

    // Cleanup
    gpioTerminate();
    log_message(LOG_INFO, "DHT22 monitor stopped.");
    closelog();

    return 0;
}

