#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>

// Constants
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_STATE_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define MAX_STATE_FILE "/sys/class/thermal/cooling_device0/max_state"
#define LOG_FILE "/var/log/fan_control.log"
#define POLL_INTERVAL 5 // seconds

// Global variables
volatile sig_atomic_t program_running = 1;
int current_fan_speed = 0;

// Function prototypes
int read_temperature();
int read_fan_state();
int read_max_fan_state();
int set_fan_speed(int speed);
int log_event(const char *message);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        program_running = 0;
        printf("Received signal %d, shutting down...\n", signal);
        log_event("Program shutting down...");
        set_fan_speed(0); // Turn off the fan
        exit(0);
    }
}

// Function to read CPU temperature from file
int read_temperature() {
    FILE *fp;
    int temperature = -1;
    char buffer[10];

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        log_event("Error opening temperature file.");
        return -1;
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        log_event("Error reading temperature from file.");
        fclose(fp);
        return -1;
    }

    fclose(fp);

    temperature = atoi(buffer) / 1000; // Convert to Celsius
    return temperature;
}

// Function to read fan state from file
int read_fan_state() {
    FILE *fp;
    int fan_state = -1;
    char buffer[10];

    fp = fopen(FAN_STATE_FILE, "r");
    if (fp == NULL) {
        log_event("Error opening fan state file.");
        return -1;
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        log_event("Error reading fan state from file.");
        fclose(fp);
        return -1;
    }

    fclose(fp);

    fan_state = atoi(buffer);
    return fan_state;
}

// Function to read maximum fan state from file
int read_max_fan_state() {
    FILE *fp;
    int max_fan_state = -1;
    char buffer[10];

    fp = fopen(MAX_STATE_FILE, "r");
    if (fp == NULL) {
        log_event("Error opening max fan state file.");
        return -1;
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        log_event("Error reading max fan state from file.");
        fclose(fp);
        return -1;
    }

    fclose(fp);

    max_fan_state = atoi(buffer);
    return max_fan_state;
}

// Function to set fan speed
int set_fan_speed(int speed) {
    FILE *fp;
    char buffer[10];

    if (speed < 0 || speed > 3) {
        log_event("Invalid fan speed. Speed must be between 0 and 3.");
        return -1;
    }

    fp = fopen(FAN_STATE_FILE, "w");
    if (fp == NULL) {
        log_event("Error opening fan state file for writing.");
        return -1;
    }

    snprintf(buffer, sizeof(buffer), "%d", speed);
    if (fputs(buffer, fp) == EOF) {
        log_event("Error writing fan speed to file.");
        fclose(fp);
        return -1;
    }

    fclose(fp);

    current_fan_speed = speed; // Update global variable
    return 0;
}

// Function to log events to file
int log_event(const char *message) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(fp, "%s: %s\n", timestamp, message);
    fclose(fp);
    return 0;
}

int main() {
    int temperature;
    int fan_speed;
    int max_fan_state;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize logging
    log_event("Program started.");

    // Main loop
    while (program_running) {
        temperature = read_temperature();
        if (temperature == -1) {
            log_event("Failed to read temperature. Retrying...");
            sleep(POLL_INTERVAL);
            continue;
        }

        max_fan_state = read_max_fan_state();
        if (max_fan_state == -1) {
            log_event("Failed to read max fan state. Retrying...");
            sleep(POLL_INTERVAL);
            continue;
        }

        if (temperature < 45) {
            fan_speed = 0;
        } else if (temperature < 55) {
            fan_speed = 1;
        } else if (temperature < 65) {
            fan_speed = 2;
        } else {
            fan_speed = 3;
        }

        // Limit fan speed to max_fan_state
        if (fan_speed > max_fan_state) {
            fan_speed = max_fan_state;
        }

        if (fan_speed != current_fan_speed) {
            if (set_fan_speed(fan_speed) == 0) {
                char log_message[100];
                snprintf(log_message, sizeof(log_message), "Fan speed set to %d.", fan_speed);
                log_event(log_message);
            } else {
                log_event("Failed to set fan speed.");
            }
        }

        sleep(POLL_INTERVAL);
    }

    return 0;
}

