    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(fp, "%s: %s\n", timestamp, message);
    fclose(fp);
    return 0;
}

int main() {
    int temperature;
    int fan_speed;
    int max_fan_state;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize logging
    log_event("Program started.");

    // Main loop
    while (program_running) {
        temperature = read_temperature();
        if (temperature == -1) {
            log_event("Failed to read temperature. Retrying...");
            sleep(POLL_INTERVAL);
            continue;
        }

        max_fan_state = read_max_fan_state();
        if (max_fan_state == -1) {
            log_event("Failed to read max fan state. Retrying...");
            sleep(POLL_INTERVAL);
            continue;
        }

        if (temperature < 45) {
            fan_speed = 0;
        } else if (temperature < 55) {
            fan_speed = 1;
        } else if (temperature < 65) {
            fan_speed = 2;
        } else {
            fan_speed = 3;
        }

        // Limit fan speed to max_fan_state
        if (fan_speed > max_fan_state) {
            fan_speed = max_fan_state;
        }

        if (fan_speed != current_fan_speed) {
            if (set_fan_speed(fan_speed) == 0) {
                char log_message[100];
                snprintf(log_message, sizeof(log_message), "Fan speed set to %d.", fan_speed);
                log_event(log_message);
            } else {
                log_event("Failed to set fan speed.");
            }
        }

        sleep(POLL_INTERVAL);
    }

    return 0;
}

