#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define HEATER_PIN 18
#define SPI_CLK 11
#define SPI_CS 8
#define SPI_DO 9

// Define SPI channel
#define SPI_CHANNEL 0

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Define PID parameters
#define KP 1.0
#define KI 0.1
#define KD 0.01

// Define target temperature
#define TARGET_TEMPERATURE 50.0

// Define failsafe temperature limits
#define MAX_TEMPERATURE 100.0
#define MIN_TEMPERATURE 0.0

// Define MAX31855 fault bits
#define FAULT_OPEN_CIRCUIT 0x01
#define FAULT_SHORT_TO_GND 0x02
#define FAULT_SHORT_TO_VCC 0x04

// Global variables
static volatile int running = 1;
static int spi_handle;
static FILE *log_file;
static double integral = 0.0;
static double previous_error = 0.0;

// Function prototypes
double read_temperature();
double calculate_pid(double setpoint, double actual_temperature);
void set_heater_duty_cycle(double duty_cycle);
void log_data(double temperature, double duty_cycle, double pid_output);
void signal_handler(int signal);
void cleanup();

// Function to read temperature from MAX31855
double read_temperature() {
    unsigned char buffer[4];
    int result;

    result = spiRead(spi_handle, buffer, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading SPI data: %d\n", result);
        return -1000.0; // Indicate error
    }

    // Check for fault bits
    if (buffer[3] & FAULT_OPEN_CIRCUIT) {
        fprintf(stderr, "MAX31855 Fault: Open Circuit\n");
        return -1000.0;
    }
    if (buffer[3] & FAULT_SHORT_TO_GND) {
        fprintf(stderr, "MAX31855 Fault: Short to GND\n");
        return -1000.0;
    }
    if (buffer[3] & FAULT_SHORT_TO_VCC) {
        fprintf(stderr, "MAX31855 Fault: Short to VCC\n");
        return -1000.0;
    }

    // Extract temperature data (bits 31:18)
    int16_t raw_temperature = ((buffer[0] << 8) | buffer[1]) >> 2;

    // Convert to Celsius
    double temperature = raw_temperature * 0.25;

    return temperature;
}

// Function to calculate PID output
double calculate_pid(double setpoint, double actual_temperature) {
    double error = setpoint - actual_temperature;
    integral += error;
    double derivative = error - previous_error;
    double output = KP * error + KI * integral + KD * derivative;
    previous_error = error;

    // Limit the output to the range 0-100
    if (output < 0) output = 0;
    if (output > 100) output = 100;

    return output;
}

// Function to set heater duty cycle
void set_heater_duty_cycle(double duty_cycle) {
    int pwm_value = (int)(duty_cycle * 2.55); // Convert duty cycle to PWM value (0-255)
    gpioPWM(HEATER_PIN, pwm_value);
}

// Function to log data to file
void log_data(double temperature, double duty_cycle, double pid_output) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Temperature: %.2f, Duty Cycle: %.2f, PID Output: %.2f\n",
            timestamp, temperature, duty_cycle, pid_output);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    set_heater_duty_cycle(0.0); // Turn off heater
    spiClose(spi_handle);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(HEATER_PIN, PI_OUTPUT);
    gpioSetMode(SPI_CLK, PI_OUTPUT);
    gpioSetMode(SPI_CS, PI_OUTPUT);
    gpioSetMode(SPI_DO, PI_INPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, 500000, 0); // Channel 0, 500kHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        cleanup();
        return 1;
    }

    // Set PWM frequency
    gpioSetPWMfrequency(HEATER_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_PIN, 255); // Set PWM range to 0-255

    // Open log file
    log_file = fopen("heater_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("PID controller started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        double temperature = read_temperature();

        if (temperature > MAX_TEMPERATURE || temperature < MIN_TEMPERATURE) {
            fprintf(stderr, "Temperature out of range: %.2f\n", temperature);
            set_heater_duty_cycle(0.0);
            integral = 0.0;
            previous_error = 0.0;
            running = 0; // Stop the loop
            continue;
        }

        if (temperature < -999.0) {
            fprintf(stderr, "Error reading temperature, skipping PID calculation.\n");
            set_heater_duty_cycle(0.0);
            sleep(1);
            continue;
        }

        double pid_output = calculate_pid(TARGET_TEMPERATURE, temperature);
        set_heater_duty_cycle(pid_output);
        log_data(temperature, pid_output, pid_output);

        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

