#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define FAN_GPIO 18
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "cooling_log.csv"
#define POLLING_INTERVAL 5 // seconds

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
float read_cpu_temp();
int set_fan_speed(float temperature);
int log_data(float temperature, int duty_cycle);
void signal_handler(int signal);
int initialize();
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read CPU temperature from file
float read_cpu_temp() {
    FILE *fp;
    int temp_milli;
    float temp_celsius;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1.0; // Indicate error
    }

    if (fscanf(fp, "%d", &temp_milli) != 1) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1.0; // Indicate error
    }

    fclose(fp);
    temp_celsius = (float)temp_milli / 1000.0;
    return temp_celsius;
}

// Function to set fan speed based on temperature
int set_fan_speed(float temperature) {
    int duty_cycle;

    if (temperature <= 40.0) {
        duty_cycle = 0;
    } else if (temperature >= 70.0) {
        duty_cycle = 100;
    } else {
        duty_cycle = (int)(((temperature - 40.0) / 30.0) * 100.0);
    }

    if (gpioPWM(FAN_GPIO, duty_cycle) != 0) {
        fprintf(stderr, "Error setting fan speed\n");
        return -1; // Indicate error
    }

    return duty_cycle;
}

// Function to log data to file
int log_data(float temperature, int duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1; // Indicate error
    }

    if (fprintf(log_file, "%s,%.2f,%d\n", timestamp, temperature, duty_cycle) < 0) {
        perror("Error writing to log file");
        return -1; // Indicate error
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO18 as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency to 25 kHz
    if (gpioSetPWMfrequency(FAN_GPIO, 25000) != 0) {
        fprintf(stderr, "Error setting PWM frequency\n");
        gpioTerminate();
        return -1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return -1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature (C),Duty Cycle (%)\n");
    }

    return 0;
}

// Cleanup function
void cleanup() {
    // Turn off the fan
    gpioPWM(FAN_GPIO, 0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    printf("Cooling system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        float temperature = read_cpu_temp();
        if (temperature < 0) {
            fprintf(stderr, "Error reading temperature, skipping this iteration\n");
        } else {
            int duty_cycle = set_fan_speed(temperature);
            if (duty_cycle >= 0) {
                if (log_data(temperature, duty_cycle) != 0) {
                    fprintf(stderr, "Error logging data\n");
                }
            } else {
                fprintf(stderr, "Error setting fan speed\n");
            }
        }

        gpioDelay(POLLING_INTERVAL * 1000000); // Delay for 5 seconds (microseconds)
    }

    // Cleanup and exit
    cleanup();
    printf("Cooling system stopped.\n");
    return 0;
}

