#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for Channel A and Channel B
#define CHANNEL_A_PIN 17
#define CHANNEL_B_PIN 18

// Define the log file name
#define LOG_FILE "encoder_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold encoder state
typedef struct {
    int channel_a_state;
    int channel_b_state;
    float angle;
} EncoderState;

// Function prototypes
int initialize_gpio();
void cleanup_gpio();
void log_position(float angle);
void signal_handler(int signal);
int read_channel_a();
int read_channel_b();
void update_angle(EncoderState *state);

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(CHANNEL_A_PIN, PI_INPUT);
    gpioSetPullUpDown(CHANNEL_A_PIN, PI_PUD_UP);

    gpioSetMode(CHANNEL_B_PIN, PI_INPUT);
    gpioSetPullUpDown(CHANNEL_B_PIN, PI_PUD_UP);

    return 0;
}

// Function to cleanup GPIO pins
void cleanup_gpio() {
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

// Function to read the state of Channel A
int read_channel_a() {
    return gpioRead(CHANNEL_A_PIN);
}

// Function to read the state of Channel B
int read_channel_b() {
    return gpioRead(CHANNEL_B_PIN);
}

// Function to update the angle based on the quadrature state
void update_angle(EncoderState *state) {
    int new_channel_a_state = read_channel_a();
    int new_channel_b_state = read_channel_b();

    if (new_channel_a_state != state->channel_a_state) {
        if (new_channel_b_state != state->channel_b_state) {
            state->angle += 90.0;
        } else {
            state->angle -= 90.0;
        }
    } else if (new_channel_b_state != state->channel_b_state) {
        state->angle += 90.0;
    }

    // Normalize angle to 0-360 degrees
    while (state->angle < 0.0) {
        state->angle += 360.0;
    }
    while (state->angle >= 360.0) {
        state->angle -= 360.0;
    }

    state->channel_a_state = new_channel_a_state;
    state->channel_b_state = new_channel_b_state;
}

// Function to log the current timestamp and angle to the log file
void log_position(float angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Angle: %.2f\n", timestamp, angle);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup_gpio();
        return 1;
    }

    EncoderState encoder_state = {0, 0, 0.0};

    printf("Rotary encoder monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        update_angle(&encoder_state);
        log_position(encoder_state.angle);
        gpioDelay(10); // Delay for 10 milliseconds
    }

    // Cleanup and exit
    cleanup_gpio();
    printf("Rotary encoder monitoring stopped.\n");
    return 0;
}

