#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define ADPD144RI_ADDR 0x39
#define LED_GPIO 17
#define IR_THRESHOLD 2000
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
int initialize_gpio();
int read_adpd144ri(uint16_t *red, uint16_t *ir);
int log_data(uint16_t red, uint16_t ir);
void control_led(uint16_t ir);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data
typedef struct {
    uint16_t red;
    uint16_t ir;
} sensor_data_t;

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to initialize I2C
int initialize_i2c() {
    i2c_fd = i2cOpen(I2C_BUS, ADPD144RI_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_fd);
        return -1;
    }
    return 0;
}

// Function to initialize GPIO
int initialize_gpio() {
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Initially turn off the LED
    return 0;
}

// Function to read data from ADPD144RI
int read_adpd144ri(uint16_t *red, uint16_t *ir) {
    char buf[4];
    int result;

    // Read Red data (2 bytes)
    result = i2cReadI2CBlockData(i2c_fd, 0x00, buf, 2); // Example register address, adjust as needed
    if (result != 2) {
        fprintf(stderr, "Error reading Red data: %d\n", result);
        return -1;
    }
    *red = (buf[1] << 8) | buf[0];

    // Read IR data (2 bytes)
    result = i2cReadI2CBlockData(i2c_fd, 0x02, buf, 2); // Example register address, adjust as needed
    if (result != 2) {
        fprintf(stderr, "Error reading IR data: %d\n", result);
        return -1;
    }
    *ir = (buf[1] << 8) | buf[0];

    return 0;
}

// Function to log data to CSV file
int log_data(uint16_t red, uint16_t ir) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u\n", timestamp, red, ir);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Function to control the LED based on IR value
void control_led(uint16_t ir) {
    if (ir > IR_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn on LED
    } else {
        gpioWrite(LED_GPIO, 0); // Turn off LED
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_fd != -1) {
        i2cClose(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    uint16_t red, ir;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("adpd144ri_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        if (read_adpd144ri(&red, &ir) == 0) {
            log_data(red, ir);
            control_led(ir);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

