// Interrupt service routine (ISR)
void pulse_counter(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == PI_HIGH) { // Rising edge
        pthread_mutex_lock(&pulse_mutex);
        pulse_count++;
        pthread_mutex_unlock(&pulse_mutex);
    }
}

// Function to calculate RPM
double calculate_rpm() {
    pthread_mutex_lock(&pulse_mutex);
    int count = pulse_count;
    pulse_count = 0; // Reset pulse count
    pthread_mutex_unlock(&pulse_mutex);

    return (double)count * PULSES_PER_REVOLUTION * 60.0; // Convert pulses/second to RPM
}

// Function to log RPM to file
void log_rpm(double rpm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f\n", timestamp, rpm);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioTerminate(); // Terminate pigpio
    if (log_file != NULL) {
        fclose(log_file); // Close log file
    }
    pthread_mutex_destroy(&pulse_mutex); // Destroy mutex
    exit(0);
}

