    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input with pull-down resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    // Initialize mutex
    if (pthread_mutex_init(&pulse_mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        pthread_mutex_destroy(&pulse_mutex);
        return 1;
    }

    // Register interrupt handler
    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, pulse_counter, NULL) != 0) {
        fprintf(stderr, "Error setting ISR function!\n");
        fclose(log_file);
        gpioTerminate();
        pthread_mutex_destroy(&pulse_mutex);
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("RPM monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        double rpm = calculate_rpm();
        log_rpm(rpm);
        gpioDelay(1000); // Wait for 1 second
    }

    return 0; // This line will never be reached due to the infinite loop
}

