void cleanup();

// Structure to hold GPIO configuration
typedef struct {
    int audio_out_pin;
    int gain_select_pin;
} gpio_config_t;

// Structure to hold logging configuration
typedef struct {
    char *log_file_name;
} logging_config_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(AUDIO_OUT_PIN, PI_INPUT);
    gpioSetMode(GAIN_SELECT_PIN, PI_OUTPUT);

    return 0;
}

// Function to select the gain of the microphone amplifier
int select_gain(int gain) {
    if (gain != 0 && gain != 1) {
        fprintf(stderr, "Invalid gain value. Must be 0 or 1.\n");
        return 1;
    }

    gpioWrite(GAIN_SELECT_PIN, gain);
    return 0;
}

// Function to read the audio level from the microphone
int read_audio_level() {
    return gpioRead(AUDIO_OUT_PIN);
}

// Function to log an event to the log file
int log_event(int level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s %d\n", timestamp, level);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return 1;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Select gain (60dB)
    if (select_gain(0) != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Audio event logger started. Logging to %s\n", LOG_FILE);

    // Main loop
    while (running) {
        int audio_level = read_audio_level();

        if (audio_level == 1) {
            if (log_event(1) != 0) {
                fprintf(stderr, "Error logging event!\n");
            }
        }

        gpioDelay(10000); // 10ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

