#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SLF3S_ADDR 0x36
#define FLOW_RATE_CMD 0x3608
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF
#define FLOW_RATE_SCALE_FACTOR 0.064 // uL/min per raw unit
#define MEASUREMENT_INTERVAL_MS 1000
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    int16_t raw_flow_rate;
    uint8_t crc;
} sensor_data_t;

// Function prototypes
int initialize_pigpio();
int open_i2c_connection();
int read_flow_rate(sensor_data_t *data);
float convert_to_flow_rate(int16_t raw_flow_rate);
int validate_crc(uint8_t crc, uint8_t data[], int len);
int log_data(float flow_rate);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open I2C connection
    if (open_i2c_connection() != 0) {
        fprintf(stderr, "Failed to open I2C connection. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("flow_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;
    float flow_rate;

    // Main loop
    while (!terminate) {
        // Read flow rate
        if (read_flow_rate(&sensor_data) == 0) {
            // Convert raw flow rate to uL/min
            flow_rate = convert_to_flow_rate(sensor_data.raw_flow_rate);

            // Log data
            if (log_data(flow_rate) != 0) {
                fprintf(stderr, "Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Failed to read flow rate.\n");
        }

        // Wait for the next measurement
        gpioDelay(MEASUREMENT_INTERVAL_MS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Open I2C connection
int open_i2c_connection() {
    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Read flow rate from the sensor
int read_flow_rate(sensor_data_t *data) {
    char cmd[2] = {(FLOW_RATE_CMD >> 8) & 0xFF, FLOW_RATE_CMD & 0xFF};
    char buffer[3];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        // Write command to sensor
        if (i2cWriteDevice(i2c_handle, cmd, 2) != 0) {
            fprintf(stderr, "I2C write failed (attempt %d): %d\n", retries + 1, i2c_handle);
            gpioDelay(10); // Small delay before retry
            retries++;
            continue;
        }

        // Read data from sensor
        if (i2cReadDevice(i2c_handle, buffer, 3) != 3) {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", retries + 1, i2c_handle);
            gpioDelay(10); // Small delay before retry
            retries++;
            continue;
        }

        // Extract raw flow rate and CRC
        data->raw_flow_rate = (buffer[0] << 8) | buffer[1];
        data->crc = buffer[2];

        // Validate CRC
        if (validate_crc(data->crc, (uint8_t *)buffer, 2) != 0) {
            fprintf(stderr, "CRC validation failed (attempt %d)\n", retries + 1);
            retries++;
            continue;
        }

        return 0; // Success
    }

    fprintf(stderr, "Failed to read flow rate after %d retries.\n", MAX_RETRIES);
    return 1; // Failure
}

// Convert raw flow rate to uL/min
float convert_to_flow_rate(int16_t raw_flow_rate) {
    return (float)raw_flow_rate * FLOW_RATE_SCALE_FACTOR;
}

// Validate CRC checksum
int validate_crc(uint8_t crc, uint8_t data[], int len) {
    return (crc8(data, len) != crc) ? 1 : 0;
}

// Log data to CSV file
int log_data(float flow_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

