#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define INTRUSION_THRESHOLD 5 // seconds
#define POLLING_INTERVAL 100 // milliseconds

static volatile int running = 1;
static time_t intrusion_start_time = 0;

// Function prototypes
int initialize_gpio();
int read_sensor();
void handle_intrusion();
void cleanup();
void signal_handler(int signal);

// Structure to hold program state
typedef struct {
    int gpio_initialized;
} ProgramState;

ProgramState state = {0};

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return EXIT_FAILURE;
    }
    state.gpio_initialized = 1;

    printf("Tamper detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        int sensor_value = read_sensor();

        if (sensor_value == 1) {
            // Sensor is touched
            if (intrusion_start_time == 0) {
                intrusion_start_time = time(NULL);
            }

            time_t current_time = time(NULL);
            if (difftime(current_time, intrusion_start_time) >= INTRUSION_THRESHOLD) {
                handle_intrusion();
                intrusion_start_time = 0; // Reset timer after intrusion
            }
        } else if (sensor_value == 0) {
            // Sensor is released
            intrusion_start_time = 0; // Reset timer
        } else {
            fprintf(stderr, "Error reading sensor value. Continuing.\n");
        }

        gpioDelay(POLLING_INTERVAL * 1000); // pigpioDelay takes microseconds
    }

    cleanup();
    printf("Tamper detection system stopped.\n");
    return EXIT_SUCCESS;
}

int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN); // Use pull-down resistor

    return 0;
}

int read_sensor() {
    int value = gpioRead(GPIO_PIN);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", GPIO_PIN, strerror(errno));
        return -1; // Indicate error
    }
    return value;
}

void handle_intrusion() {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

    printf("INTRUSION DETECTED: %s\n", buf);
}

void cleanup() {
    if (state.gpio_initialized) {
        gpioTerminate();
    }
}

void signal_handler(int signal) {
    printf("Signal received (%d). Cleaning up and exiting.\n", signal);
    running = 0;
}

