#include <sys/ioctl.h>
#include <linux/i2s/pcm.h>
#include <pigpio.h>

// Configuration
#define I2S_DEVICE "/dev/snd/pcmC0D0c"
#define GPIO_PIN 17
#define SAMPLE_RATE 44100
#define NUM_CHANNELS 2
#define BITS_PER_SAMPLE 16
#define BUFFER_SIZE 1024
#define FILE_NAME "audio_capture.pcm"

// Global variables
static volatile int running = 1;
static int i2s_fd = -1;
static int gpio_initialized = 0;
static FILE *output_file = NULL;

// Structure to hold I2S configuration
typedef struct {
    char device[64];
    int sample_rate;
    int num_channels;
    int bits_per_sample;
} i2s_config_t;

// Function prototypes
int init_i2s(i2s_config_t *config);
int init_gpio(int pin);
int select_left_channel(int gpio_pin);
int select_right_channel(int gpio_pin);
int capture_audio(int i2s_fd, FILE *output_file);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2S
int init_i2s(i2s_config_t *config) {
    int fd;
    struct i2s_hw_params params;

    fd = open(config->device, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2S device");
        return -1;
    }

    if (ioctl(fd, I2S_IOC_HW_PARAMS, &params) < 0) {
        perror("Error setting I2S parameters");
        close(fd);
        return -1;
    }

    params.channels = config->num_channels;
    params.rate = config->sample_rate;
    params.format = I2S_FMT_S16_LE; // Assuming little-endian 16-bit PCM

    if (ioctl(fd, I2S_IOC_HW_PARAMS, &params) < 0) {
        perror("Error setting I2S parameters");
        close(fd);
        return -1;
    }

    return fd;
}

// Initialize GPIO
int init_gpio(int pin) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpio_initialized = 1;

    gpioSetMode(pin, PI_OUTPUT);
    return 0;
}

// Select left channel
int select_left_channel(int gpio_pin) {
    gpioWrite(gpio_pin, 0); // Assuming 0 selects left channel
    return 0;
}

// Select right channel
int select_right_channel(int gpio_pin) {
    gpioWrite(gpio_pin, 1); // Assuming 1 selects right channel
    return 0;
}

// Capture audio
int capture_audio(int i2s_fd, FILE *output_file) {
    char buffer[BUFFER_SIZE];
    ssize_t bytes_read;

    while (running) {
        bytes_read = read(i2s_fd, buffer, BUFFER_SIZE);
        if (bytes_read < 0) {
            perror("Error reading from I2S device");
            return -1;
        }

        if (fwrite(buffer, 1, bytes_read, output_file) != bytes_read) {
            perror("Error writing to file");
            return -1;
        }
    }

    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2s_fd != -1) {
        close(i2s_fd);
    }
    if (output_file != NULL) {
        fclose(output_file);
    }
    if (gpio_initialized) {
        gpioTerminate();
    }
}

int main() {
    i2s_config_t i2s_config = {
        .device = I2S_DEVICE,
        .sample_rate = SAMPLE_RATE,
        .num_channels = NUM_CHANNELS,
        .bits_per_sample = BITS_PER_SAMPLE
    };

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2S
    i2s_fd = init_i2s(&i2s_config);
    if (i2s_fd < 0) {
        return 1;
    }

    // Initialize GPIO
    if (init_gpio(GPIO_PIN) != 0) {
        close(i2s_fd);
        return 1;
    }

    // Open output file
    output_file = fopen(FILE_NAME, "wb");
    if (output_file == NULL) {
        perror("Error opening output file");
        close(i2s_fd);
        gpioTerminate();
        return 1;
    }

    // Capture audio
    printf("Capturing audio... Press Ctrl+C to stop.\n");
    if (capture_audio(i2s_fd, output_file) != 0) {
        cleanup();
        return 1;
    }

    // Cleanup and exit
    cleanup();
    printf("Audio capture complete.\n");
    return 0;
}

