#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define FAN_PIN 18

// Define PWM frequency
#define PWM_FREQUENCY 100

// Define PWM duty cycle (0-255)
#define PWM_DUTY_CYCLE 128

// Define debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Define sensor timeout in milliseconds
#define SENSOR_TIMEOUT 100

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_flame_sensor();
void control_fan(int state);
void log_event(const char *event);
void signal_handler(int signal);
void cleanup();

// Structure to hold program state
typedef struct {
    int flame_detected;
    unsigned long last_flame_time;
} ProgramState;

ProgramState state = {0, 0};

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("flame_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Log program start
    log_event("Program started");

    // Main loop
    while (program_running) {
        int flame_detected = read_flame_sensor();

        if (flame_detected == 0) { // Flame detected (LOW signal)
            unsigned long current_time = gpioTick();

            if (!state.flame_detected) {
                // Debounce
                if (current_time - state.last_flame_time > DEBOUNCE_TIME * 1000) { // Convert ms to us
                    control_fan(1); // Turn fan on
                    log_event("Flame detected");
                    state.flame_detected = 1;
                    state.last_flame_time = current_time;
                }
            }
        } else if (flame_detected == 1) { // No flame detected (HIGH signal)
            if (state.flame_detected) {
                control_fan(0); // Turn fan off
                log_event("Flame extinguished");
                state.flame_detected = 0;
            }
        } else {
            fprintf(stderr, "Error reading flame sensor.\n");
        }

        gpioDelay(50); // Check every 50ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(FAN_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(FAN_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_PIN, 255); // Set PWM range to 0-255

    return 0;
}

// Read flame sensor with timeout
int read_flame_sensor() {
    int count = 0;
    unsigned long start_time = gpioTick();

    while (count < SENSOR_TIMEOUT) {
        int value = gpioRead(FLAME_SENSOR_PIN);
        if (value >= 0) {
            return value; // Return the sensor value
        } else {
            fprintf(stderr, "Error reading GPIO %d\n", FLAME_SENSOR_PIN);
            gpioDelay(1); // Small delay to avoid busy-waiting
            count++;
        }
    }

    fprintf(stderr, "Timeout reading flame sensor.\n");
    return -1; // Indicate timeout
}

// Control fan (1 for on, 0 for off)
void control_fan(int state) {
    gpioPWM(FAN_PIN, state ? PWM_DUTY_CYCLE : 0);
}

// Log events to file
void log_event(const char *event) {
    if (log_file != NULL) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        char timestamp[30];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

        fprintf(log_file, "%s: %s\n", timestamp, event);
        fflush(log_file); // Ensure immediate write to file
    } else {
        fprintf(stderr, "Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Received signal %d, shutting down...\n", signal);
    log_event("Program shutting down");
}

// Cleanup resources
void cleanup() {
    control_fan(0); // Turn off fan
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT); // Set back to input
    gpioSetMode(FAN_PIN, PI_INPUT); // Set back to input
    gpioTerminate(); // Terminate pigpio

    if (log_file != NULL) {
        fclose(log_file);
    }
}

