    }
    return 0;
}

// Initialize I2C bus
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", handle);
        return -1;
    }
    return handle;
}

// Read a 16-bit register from the OPT3001
int read_register(int handle, uint8_t reg) {
    int result = i2cReadWordData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Failed to read register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return result;
}

// Write a 16-bit register to the OPT3001
int write_register(int handle, uint8_t reg, uint16_t value) {
    int result = i2cWriteWordData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Failed to write register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Configure the OPT3001 for continuous conversion mode
int configure_opt3001(int handle) {
    // Continuous conversion mode, auto range, 100ms conversion time
    uint16_t config_value = 0xCB01; // Continuous conversion, auto range, 100ms
    if (write_register(handle, CONFIG_REG, config_value) < 0) {
        fprintf(stderr, "Failed to configure OPT3001\n");
        return -1;
    }
    return 0;
}

// Read the lux value from the OPT3001
float read_lux(int handle) {
    int result = read_register(handle, RESULT_REG);
    if (result < 0) {
        fprintf(stderr, "Failed to read result register\n");
        return -1.0;
    }

    // Extract exponent and result
    int exponent = (result >> 12) & 0x0F;
    int mantissa = result & 0x0FFF;

    // Calculate lux value
    float lux = mantissa * (0.01 * (1 << exponent));

    return lux;
}

// Get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    return timestamp;
}

// Log the timestamp and lux value to a file
int log_data(const char *timestamp, float lux) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, lux);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() < 0) {
        return 1;
    }

    // Initialize I2C
    i2c_handle = init_i2c(I2C_BUS, OPT3001_ADDR);
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    // Configure OPT3001
    if (configure_opt3001(i2c_handle) < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("light_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read lux value
        float lux = read_lux(i2c_handle);
        if (lux < 0) {
            fprintf(stderr, "Failed to read lux value\n");
        } else {
            // Get timestamp
            char *timestamp = get_iso8601_timestamp();

            // Log data
            if (log_data(timestamp, lux) < 0) {
                fprintf(stderr, "Failed to log data\n");
            }

            free(timestamp); // Free the allocated memory
        }

        // Wait for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

