int read_flame_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to log the flame detection status
void log_flame_status(int flame_detected) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (flame_detected == 0) {
        printf("%s Flame Detected: YES\n", timestamp);
    } else {
        printf("%s Flame Detected: NO\n", timestamp);
    }
}

