    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", FLAME_SENSOR_GPIO);
        gpioTerminate();
        return 1;
    }

    // Set a pull-up resistor on GPIO 17
    if (gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up resistor on GPIO %d\n", FLAME_SENSOR_GPIO);
        gpioTerminate();
        return 1;
    }

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop to continuously read and log the sensor value
    while (program_running) {
        int flame_detected = read_flame_sensor(FLAME_SENSOR_GPIO);
        if (flame_detected >= 0) {
            log_flame_status(flame_detected);
        } else {
            fprintf(stderr, "Failed to read flame sensor, retrying...\n");
        }

        sleep(1); // Wait for 1 second
    }

    // Clean up and terminate the pigpio library
    gpioTerminate();

    return 0;
}

