#include <pigpio.h>

// Define GPIO pins for the TTP226 sensor
#define SENSOR_PIN_1 2
#define SENSOR_PIN_2 3
#define SENSOR_PIN_3 4
#define SENSOR_PIN_4 5
#define SENSOR_PIN_5 6
#define SENSOR_PIN_6 7
#define SENSOR_PIN_7 8
#define SENSOR_PIN_8 9

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library and configure GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO pins as inputs with pull-down resistors
    gpioSetMode(SENSOR_PIN_1, PI_INPUT);
    gpioSetPullUpDown(SENSOR_PIN_1, PI_PUD_DOWN);
    gpioSetMode(SENSOR_PIN_2, PI_INPUT);
    gpioSetPullUpDown(SENSOR_PIN_2, PI_PUD_DOWN);
    gpioSetMode(SENSOR_PIN_3, PI_INPUT);
    gpioSetPullUpDown(SENSOR_PIN_3, PI_PUD_DOWN);
    gpioSetMode(SENSOR_PIN_4, PI_INPUT);
    gpioSetPullUpDown(SENSOR_PIN_4, PI_PUD_DOWN);
    gpioSetMode(SENSOR_PIN_5, PI_INPUT);
    gpioSetPullUpDown(SENSOR_PIN_5, PI_PUD_DOWN);
    gpioSetMode(SENSOR_PIN_6, PI_INPUT);
    gpioSetPullUpDown(SENSOR_PIN_6, PI_PUD_DOWN);
    gpioSetMode(SENSOR_PIN_7, PI_INPUT);
    gpioSetPullUpDown(SENSOR_PIN_7, PI_PUD_DOWN);
    gpioSetMode(SENSOR_PIN_8, PI_INPUT);
    gpioSetPullUpDown(SENSOR_PIN_8, PI_PUD_DOWN);

    return 0;
}

// Function to read the sensor data
int read_sensor_data(int *channel_values) {
    channel_values[0] = gpioRead(SENSOR_PIN_1);
    channel_values[1] = gpioRead(SENSOR_PIN_2);
    channel_values[2] = gpioRead(SENSOR_PIN_3);
    channel_values[3] = gpioRead(SENSOR_PIN_4);
    channel_values[4] = gpioRead(SENSOR_PIN_5);
    channel_values[5] = gpioRead(SENSOR_PIN_6);
    channel_values[6] = gpioRead(SENSOR_PIN_7);
    channel_values[7] = gpioRead(SENSOR_PIN_8);

    return 0;
}

// Function to print the sensor data with timestamp
void print_sensor_data(int *channel_values) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long milliseconds = ts.tv_nsec / 1000000;

    printf("[+%ld ms] CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d\n",
           milliseconds,
           channel_values[0],
           channel_values[1],
