#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define the GPIO pins connected to the TTP226 channels
const int sensor_pins[8] = {2, 3, 4, 17, 27, 22, 10, 9};

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library and configure the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set each sensor pin as an input with bias disabled
    for (int i = 0; i < 8; i++) {
        if (gpioSetMode(sensor_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as input\n", sensor_pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPullUpDown(sensor_pins[i], PI_PUD_OFF) != 0) {
            fprintf(stderr, "Failed to disable pull-up/down on GPIO %d\n", sensor_pins[i]);
            gpioTerminate();
            return -1;
        }
    }

    return 0;
}

// Function to read the state of all eight sensor channels
int read_sensor_data(int *sensor_states) {
    for (int i = 0; i < 8; i++) {
        int value = gpioRead(sensor_pins[i]);
        if (value < 0) {
            fprintf(stderr, "Failed to read GPIO %d\n", sensor_pins[i]);
            return -1;
        }
        sensor_states[i] = value;
    }
    return 0;
}

// Function to format the sensor data into a CSV string
int format_csv_string(char *csv_string, size_t buffer_size, const int *sensor_states) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    int result = snprintf(csv_string, buffer_size, "%s,%d,%d,%d,%d,%d,%d,%d,%d\n",
                         timestamp, sensor_states[0], sensor_states[1], sensor_states[2],
                         sensor_states[3], sensor_states[4], sensor_states[5],
                         sensor_states[6], sensor_states[7]);

    if (result < 0 || result >= buffer_size) {
        fprintf(stderr, "Error formatting CSV string\n");
        return -1;
    }

    return 0;
}

// Function to write the CSV string to the console
int write_to_console(const char *csv_string) {
    printf("%s", csv_string);
    return 0;
}

// Function to release GPIO resources and terminate the pigpio library
void cleanup_gpio() {
    gpioTerminate();
}

int main() {
    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    int sensor_states[8];
    char csv_string[256];

    // Main loop
    while (program_running) {
        // Read sensor data
        if (read_sensor_data(sensor_states) == 0) {
            // Format CSV string
            if (format_csv_string(csv_string, sizeof(csv_string), sensor_states) == 0) {
                // Write to console
                if (write_to_console(csv_string) != 0) {
                    fprintf(stderr, "Failed to write to console\n");
                }
            } else {
                fprintf(stderr, "Failed to format CSV string\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for 50 milliseconds
        gpioDelay(50000); // pigpio uses microseconds
    }

    // Cleanup GPIO resources
    cleanup_gpio();

    return 0;
}

