#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TILT_SENSOR_GPIO 4

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int pigpio_init_result;
    int gpio_read_result;
    int tilt_state = -1; // Initialize to an invalid state

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    pigpio_init_result = gpioInitialise();
    if (pigpio_init_result < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", pigpio_init_result);
        return 1;
    }

    // Configure GPIO4 as an input with pull-up resistor
    gpioSetMode(TILT_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(TILT_SENSOR_GPIO, PI_PUD_UP);

    printf("Tilt sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read the tilt sensor value
        gpio_read_result = gpioRead(TILT_SENSOR_GPIO);

        if (gpio_read_result == PI_BAD_GPIO) {
            fprintf(stderr, "Error reading GPIO %d\n", TILT_SENSOR_GPIO);
            break; // Exit the loop on error
        } else if (gpio_read_result == PI_BAD_MODE) {
            fprintf(stderr, "GPIO %d is not configured as input\n", TILT_SENSOR_GPIO);
            break; // Exit the loop on error
        } else if (gpio_read_result != 0 && gpio_read_result != 1) {
            fprintf(stderr, "Unexpected GPIO read value: %d\n", gpio_read_result);
            break; // Exit the loop on error
        }

        // Check if the tilt state has changed
        if (gpio_read_result != tilt_state) {
            // Flush the output buffer to ensure immediate printing
            fflush(stdout);

            // Log the tilt state to the console
            if (gpio_read_result == 0) {
                printf("Tilted\n");
            } else {
                printf("Not Tilted\n");
            }

            // Update the tilt state
            tilt_state = gpio_read_result;
        }

        // Wait for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Clean up and terminate pigpio library before exiting
    gpioTerminate();
    printf("pigpio terminated.\n");

    return 0;
}

