    // Set gain (example values)

    // Example configuration (replace with actual values from datasheet)
    if (i2cWriteByteData(i2c_handle, 0x02, 0x01) < 0) return -1; // Enable UV
    if (i2cWriteByteData(i2c_handle, 0x03, 0x01) < 0) return -1; // Enable ALS
    if (i2cWriteByteData(i2c_handle, 0x0F, 0x78) < 0) return -1; // ALS Integration Time
    if (i2cWriteByteData(i2c_handle, 0x10, 0x67) < 0) return -1; // ALS Gain
    if (i2cWriteByteData(i2c_handle, 0x17, 0x78) < 0) return -1; // UV Integration Time
    if (i2cWriteByteData(i2c_handle, 0x18, 0x67) < 0) return -1; // UV Gain

