#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x70
#define SENSOR2_ADDR 0x71
#define ALARM_GPIO 17
#define FLOW_THRESHOLD 0.5 // ml/min
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF
#define MEASUREMENT_COMMAND 0x3608 // Start continuous measurement without averaging
#define MEASUREMENT_DELAY_MS 100
#define READ_INTERVAL_S 1

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int handle;
    int address;
} sensor_t;

// Function prototypes
int initialize_pigpio();
int initialize_i2c(int bus, int address);
int start_measurement(int handle);
int read_flow_rate(int handle, float *flow_rate);
float calculate_average_flow_rate(float flow_rate1, float flow_rate2);
void set_alarm_state(int state);
void log_data(float flow_rate1, float flow_rate2, float average_flow_rate, int alarm_state);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INITIAL_VALUE;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Initialize I2C for both sensors
    i2c_handle1 = initialize_i2c(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Failed to initialize I2C for sensor 1. Exiting.\n");
        cleanup();
        return 1;
    }

    i2c_handle2 = initialize_i2c(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Failed to initialize I2C for sensor 2. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("flow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        float flow_rate1 = -1.0; // Initialize to an invalid value
        float flow_rate2 = -1.0;
        float average_flow_rate;
        int alarm_state;

        // Read flow rate from sensor 1
        if (read_flow_rate(i2c_handle1, &flow_rate1) != 0) {
            fprintf(stderr, "Error reading flow rate from sensor 1.\n");
            flow_rate1 = -1.0; // Mark as invalid
        }

        // Read flow rate from sensor 2
        if (read_flow_rate(i2c_handle2, &flow_rate2) != 0) {
            fprintf(stderr, "Error reading flow rate from sensor 2.\n");
            flow_rate2 = -1.0; // Mark as invalid
        }

        // Calculate average flow rate
        average_flow_rate = calculate_average_flow_rate(flow_rate1, flow_rate2);

        // Set alarm state
        alarm_state = (average_flow_rate < FLOW_THRESHOLD) ? 1 : 0;
        set_alarm_state(alarm_state);

        // Log data
        log_data(flow_rate1, flow_rate2, average_flow_rate, alarm_state);

        // Wait for 1 second
        gpioDelay(READ_INTERVAL_S * 1000000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Initialize I2C communication
int initialize_i2c(int bus, int address) {
    int handle = i2cOpen(bus, address, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02x: %d\n", address, handle);
        return -1;
    }

    // Start continuous measurement
    if (start_measurement(handle) != 0) {
        fprintf(stderr, "Failed to start measurement on I2C device at address 0x%02x\n", address);
        i2cClose(handle);
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_MS * 1000); // Wait for measurement to start

    return handle;
}

// Start continuous measurement on the sensor
int start_measurement(int handle) {
    char buf[2];
    buf[0] = (MEASUREMENT_COMMAND >> 8) & 0xFF;
    buf[1] = MEASUREMENT_COMMAND & 0xFF;

    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write measurement command: %d\n", result);
        return 1;
    }
    return 0;
}

// Read flow rate from the sensor
int read_flow_rate(int handle, float *flow_rate) {
    char buf[3];
    int result = i2cReadDevice(handle, buf, 3);

    if (result != 3) {
        fprintf(stderr, "Failed to read flow rate data: %d\n", result);
        return 1;
    }

    // CRC check
    uint8_t crc = crc8((uint8_t *)buf, 2);
    if (crc != buf[2]) {
        fprintf(stderr, "CRC check failed: calculated 0x%02x, received 0x%02x\n", crc, buf[2]);
        return 1;
    }

    // Convert raw data to flow rate (ml/min)
    int16_t raw_flow = (buf[0] << 8) | buf[1];
    *flow_rate = (float)raw_flow / 120.0; // SLF3S-0600F: 120 counts/ml

    return 0;
}

// Calculate the average flow rate
float calculate_average_flow_rate(float flow_rate1, float flow_rate2) {
    float sum = 0.0;
    int count = 0;

    if (flow_rate1 >= 0) {
        sum += flow_rate1;
        count++;
    }
    if (flow_rate2 >= 0) {
        sum += flow_rate2;
        count++;
    }

    if (count > 0) {
        return sum / count;
    } else {
        return 0.0; // Return 0 if no valid readings
    }
}

// Set the alarm state
void set_alarm_state(int state) {
    gpioWrite(ALARM_GPIO, state);
}

// Log data to file
void log_data(float flow_rate1, float flow_rate2, float average_flow_rate, int alarm_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Sensor 1: %.2f ml/min, Sensor 2: %.2f ml/min, Average: %.2f ml/min, Alarm: %s\n",
            timestamp, flow_rate1, flow_rate2, average_flow_rate, alarm_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(ALARM_GPIO, 0); // Turn off alarm
    gpioTerminate();
}

