#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define D7S_ADDR 0x1D
#define SDA_PIN 2
#define SCL_PIN 3
#define MODE_REG 0x20
#define X_REG 0x28
#define Y_REG 0x2A
#define Z_REG 0x2C
#define SAMPLE_INTERVAL_MS 500
#define ACTIVE_TIMEOUT_S 1
#define MODE_ACTIVE 0x01
#define MODE_STANDBY 0x00

// Global variables
int i2c_fd = -1;
FILE *csv_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function prototypes
int init_i2c();
int set_sensor_mode(int mode);
int read_sensor_data(sensor_data_t *data);
int write_data_to_csv(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_fd = i2cOpen(I2C_BUS, D7S_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Set the sensor mode
int set_sensor_mode(int mode) {
    int result = i2cWriteByteData(i2c_fd, MODE_REG, mode);
    if (result < 0) {
        fprintf(stderr, "Error writing to mode register: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buf[6];
    int result = i2cReadI2CBlockData(i2c_fd, X_REG, buf, 6);
    if (result < 0) {
        fprintf(stderr, "Error reading sensor data: %s\n", strerror(errno));
        return -1;
    }

    data->x = (int16_t)((buf[1] << 8) | buf[0]);
    data->y = (int16_t)((buf[3] << 8) | buf[2]);
    data->z = (int16_t)((buf[5] << 8) | buf[4]);

    return 0;
}

// Write data to CSV file
int write_data_to_csv(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (csv_file == NULL) {
        csv_file = fopen("fan_health.csv", "w");
        if (csv_file == NULL) {
            fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
            return -1;
        }
        fprintf(csv_file, "Timestamp,X,Y,Z\n");
    }

    fprintf(csv_file, "%s,%d,%d,%d\n", timestamp, data.x, data.y, data.z);
    fflush(csv_file); // Ensure data is written immediately

    return 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_fd >= 0) {
        i2cClose(i2c_fd);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set sensor to active mode
    if (set_sensor_mode(MODE_ACTIVE) != 0) {
        cleanup();
        return 1;
    }

    // Wait for sensor to become active
    time_t start_time = time(NULL);
    while (time(NULL) - start_time < ACTIVE_TIMEOUT_S) {
        sensor_data_t data;
        if (read_sensor_data(&data) == 0) {
            // Check if the sensor is active (example: check X value)
            if (abs(data.x) > 100) { // Adjust threshold as needed
                break;
            }
        }
        gpioDelay(100); // Check every 100ms
    }

    if (time(NULL) - start_time >= ACTIVE_TIMEOUT_S) {
        fprintf(stderr, "Sensor did not become active within timeout.\n");
        cleanup();
        return 1;
    }

    // Main loop
    sensor_data_t sensor_data;
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            if (write_data_to_csv(sensor_data) != 0) {
                fprintf(stderr, "Error writing data to CSV.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }
        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

