#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR_1_GPIO 23
#define SENSOR_2_GPIO 24
#define LED_GPIO 25

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    return 0;
}

// Function to read the sensor value from a given GPIO pin
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to control the LED state
void control_led(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

// Function to check if either sensor detects an obstacle
int obstacle_detected(int sensor1_value, int sensor2_value) {
    return (sensor1_value == 0 || sensor2_value == 0) ? 1 : 0;
}

// Function to clean up GPIO resources
void cleanup_gpio() {
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Obstacle avoidance system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR_1_GPIO);
        int sensor2_value = read_sensor(SENSOR_2_GPIO);

        // Check for errors during sensor reading
        if (sensor1_value == PI_BAD_GPIO || sensor2_value == PI_BAD_GPIO) {
            fprintf(stderr, "Error reading sensor values\n");
            cleanup_gpio();
            return 1;
        }

        // Check for obstacle detection
        int obstacle = obstacle_detected(sensor1_value, sensor2_value);

        // Control LED based on obstacle detection
        control_led(LED_GPIO, obstacle);

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Clean up GPIO resources before exiting
    cleanup_gpio();

    printf("Obstacle avoidance system stopped.\n");

    return 0;
}

