#include <signal.h>
#include <string.h>

// Define GPIO pins for the sensors
#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18

// Define the stall duration in seconds
#define STALL_DURATION 2

// Define the log file name
#define LOG_FILE "stall_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static time_t last_stall_time = 0;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio_pin);
int is_stall_confirmed(int sensor1_value, int sensor2_value);
int log_stall(time_t timestamp);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    int sensor1_value;
    int sensor2_value;
} SensorData;

// Function to initialize the pigpio library and set GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);

    return 0; // Indicate success
}

// Function to read the value from a sensor
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value != 0 && value != 1) {
        fprintf(stderr, "Invalid sensor reading: %d\n", value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to check if a stall is confirmed
int is_stall_confirmed(int sensor1_value, int sensor2_value) {
    return (sensor1_value == 0 && sensor2_value == 0);
}

// Function to log a stall event to the log file
int log_stall(time_t timestamp) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return 1; // Indicate failure
    }

    // Check if the stall event has already been logged within the last 5 seconds
    if (timestamp - last_stall_time < 5) {
        return 0; // Indicate that the stall has already been logged
    }

    fprintf(log_file, "%s - Stall detected\n", timestamp_str);
    fflush(log_file); // Ensure the data is written to the file immediately
    last_stall_time = timestamp;

    return 0; // Indicate success
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    printf("Conveyor belt monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        SensorData sensor_data;
        sensor_data.sensor1_value = read_sensor(SENSOR_1_GPIO);
        sensor_data.sensor2_value = read_sensor(SENSOR_2_GPIO);

        if (sensor_data.sensor1_value == -1 || sensor_data.sensor2_value == -1) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        if (is_stall_confirmed(sensor_data.sensor1_value, sensor_data.sensor2_value)) {
            time_t current_time = time(NULL);
            log_stall(current_time);
        }

        gpioDelay(100); // Delay to avoid excessive CPU usage
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

