#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 23
#define LOG_FILE "flood_log.txt"
#define REINIT_DELAY 60 // seconds

static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sensor();
void log_event(const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("Received signal %d, shutting down...\n", signal);
        running = 0;
    }
}

// Initialize GPIO using pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN); // Use pull-down resistor

    return 0;
}

// Read the sensor value
int read_sensor() {
    int value = gpioRead(GPIO_PIN);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO pin %d\n", GPIO_PIN);
        return -1;
    }
    return value;
}

// Log an event to the log file
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s %s\n", timestamp, message);
        fflush(log_file); // Ensure immediate write to file
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_event("ERROR: GPIO initialization failed. Exiting.");
        fclose(log_file);
        return 1;
    }

    printf("Water level monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int sensor_value = read_sensor();
        if (sensor_value == 1) {
            log_event("ALERT: Water detected");
            printf("ALERT: Water detected\n");
        } else if (sensor_value < 0) {
            log_event("ERROR: Failed to read sensor. Attempting re-initialization.");
            fprintf(stderr, "Failed to read sensor. Attempting re-initialization.\n");
            gpioTerminate();
            sleep(REINIT_DELAY);
            if (initialize_gpio() != 0) {
                log_event("ERROR: GPIO re-initialization failed.");
                fprintf(stderr, "GPIO re-initialization failed.\n");
            }
        }

        sleep(2);
    }

    cleanup();
    return 0;
}

