#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define LOG_FILE "rpm_log.txt"

static volatile int pulse_count = 0;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to get the current timestamp in YYYY-MM-DD HH:MM:SS format
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; // Ensure buffer is large enough

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log RPM data to a file
void log_rpm(int rpm) {
    char *timestamp = get_timestamp();
    if (log_file != NULL) {
        fprintf(log_file, "%s %d\n", timestamp, rpm);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to calculate RPM from pulse count
int calculate_rpm(int pulse_count) {
    return pulse_count * 60; // Assuming one pulse per revolution
}

// Callback function for GPIO interrupt
void pulse_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) { // Rising edge
        pulse_count++;
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input with pull-up resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt callback
    if (gpioSetAlertFuncEx(GPIO_PIN, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Error setting alert function\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("RPM monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        gpioDelay(1000); // Wait for 1 second

        // Disable interrupt callback
        gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL);

        // Calculate RPM
        int rpm = calculate_rpm(pulse_count);

        // Log RPM data
        log_rpm(rpm);

        // Print RPM data to stdout
        char *timestamp = get_timestamp();
        printf("%s %d\n", timestamp, rpm);

        // Reset pulse count
        pulse_count = 0;

        // Re-enable interrupt callback
        gpioSetAlertFuncEx(GPIO_PIN, pulse_callback, NULL);
    }

    // Disable interrupt callback
    gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio library
    gpioTerminate();

    printf("RPM monitoring stopped.\n");

    return 0;
}

