        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to calculate RPM from pulse count
int calculate_rpm(int pulse_count) {
    return pulse_count * 60; // Assuming one pulse per revolution
}

