            }
            break;
        case QUAD_STATE_1:
            state.current_state = QUAD_STATE_2;
            if (gpioRead(SENSOR_A_GPIO) == 1) {
                log_rotation(&state, 1); // Clockwise
            } else {
                log_rotation(&state, -1); // Counter-Clockwise
            }
            break;
        case QUAD_STATE_2:
            state.current_state = QUAD_STATE_1;
            if (gpioRead(SENSOR_A_GPIO) == 0) {
                log_rotation(&state, 1); // Clockwise
            } else {
                log_rotation(&state, -1); // Counter-Clockwise
            }
            break;
        case QUAD_STATE_3:
            state.current_state = QUAD_STATE_0;
            if (gpioRead(SENSOR_A_GPIO) == 1) {
                log_rotation(&state, 1); // Clockwise
