int initialize_logging(ProgramState *state) {
    state->log_file = fopen(LOG_FILE, "a");
    if (state->log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s\n", LOG_FILE);
        return -1;
    }
    return 0;
}

