    printf("Cleaning up...\n");

    // Disable interrupts
    gpioSetISRFuncEx(SENSOR_A_GPIO, RISING_EDGE, 0, NULL, NULL);
    gpioSetISRFuncEx(SENSOR_B_GPIO, RISING_EDGE, 0, NULL, NULL);

    // Close the log file
    if (state->log_file != NULL) {
        fclose(state->log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    // Destroy mutex and condition variable
    pthread_mutex_destroy(&state->mutex);
    pthread_cond_destroy(&state->condition);
}

int main() {
    // Initialize program state
    state.current_state = QUAD_STATE_0;
    state.log_file = NULL;
    state.terminate = 0;

    // Initialize mutex and condition variable
    if (pthread_mutex_init(&state.mutex, NULL) != 0) {
        fprintf(stderr, "Error: Mutex initialization failed\n");
        return 1;
    }
    if (pthread_cond_init(&state.condition, NULL) != 0) {
        fprintf(stderr, "Error: Condition variable initialization failed\n");
        pthread_mutex_destroy(&state.mutex);
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio(&state) != 0) {
        cleanup(&state);
        return 1;
    }

    // Initialize logging
    if (initialize_logging(&state) != 0) {
        cleanup(&state);
        return 1;
    }

    printf("Rotation logger started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!state.terminate) {
        pthread_mutex_lock(&state.mutex);
        pthread_cond_wait(&state.condition, &state.mutex);
        pthread_mutex_unlock(&state.mutex);
    }

    // Cleanup and exit
    cleanup(&state);
    printf("Exiting.\n");
    return 0;
}

