#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>

// Define GPIO pins
#define SENSOR_PIN 23
#define LED_PIN 18

// Define GPIO chip
#define GPIO_CHIP "gpiochip0"

// Define GPIO path prefix
#define GPIO_PATH "/sys/class/gpio"

// Global variables for GPIO file descriptors
int sensor_fd = -1;
int led_fd = -1;

// Function prototypes
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_read(int pin);
int gpio_write(int pin, int value);
void signal_handler(int sig);
void log_message(int priority, const char *message);

// Signal handler function
void signal_handler(int sig) {
    log_message(LOG_INFO, "Signal received, shutting down...");

    // Turn off the LED
    gpio_write(LED_PIN, 0);

    // Unexport GPIO pins
    gpio_unexport(SENSOR_PIN);
    gpio_unexport(LED_PIN);

    // Close GPIO file descriptors
    if (sensor_fd != -1) {
        close(sensor_fd);
    }
    if (led_fd != -1) {
        close(led_fd);
    }

    // Close syslog
    closelog();

    exit(0);
}

// Function to export a GPIO pin
int gpio_export(int pin) {
    char buffer[64];
    int len;
    int fd;

    fd = open(GPIO_PATH "/export", O_WRONLY);
    if (fd < 0) {
        log_message(LOG_ERR, "Failed to open export file: ");
        perror("open");
        return -1;
    }

    len = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, len) != len) {
        log_message(LOG_ERR, "Failed to write to export file: ");
        perror("write");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to unexport a GPIO pin
int gpio_unexport(int pin) {
    char buffer[64];
    int len;
    int fd;

    fd = open(GPIO_PATH "/unexport", O_WRONLY);
    if (fd < 0) {
        log_message(LOG_ERR, "Failed to open unexport file: ");
        perror("open");
        return -1;
    }

    len = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, len) != len) {
        log_message(LOG_ERR, "Failed to write to unexport file: ");
        perror("write");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to set the direction of a GPIO pin (in or out)
int gpio_set_direction(int pin, const char *direction) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), GPIO_PATH "/gpio%d/direction", pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        log_message(LOG_ERR, "Failed to open direction file: ");
        perror("open");
        return -1;
    }

    if (write(fd, direction, strlen(direction)) != strlen(direction)) {
        log_message(LOG_ERR, "Failed to write to direction file: ");
        perror("write");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to read the value of a GPIO pin
int gpio_read(int pin) {
    char path[64];
    char value_str[3];
    int fd;

    snprintf(path, sizeof(path), GPIO_PATH "/gpio%d/value", pin);
    fd = open(path, O_RDONLY);
    if (fd < 0) {
        log_message(LOG_ERR, "Failed to open value file: ");
        perror("open");
        return -1;
    }

    if (read(fd, value_str, 3) < 0) {
        log_message(LOG_ERR, "Failed to read value file: ");
        perror("read");
        close(fd);
        return -1;
    }

    close(fd);
    return atoi(value_str);
}

// Function to write a value to a GPIO pin
int gpio_write(int pin, int value) {
    char path[64];
    char value_str[3];
    int fd;

    snprintf(path, sizeof(path), GPIO_PATH "/gpio%d/value", pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        log_message(LOG_ERR, "Failed to open value file: ");
        perror("open");
        return -1;
    }

    snprintf(value_str, sizeof(value_str), "%d", value);
    if (write(fd, value_str, strlen(value_str)) != strlen(value_str)) {
        log_message(LOG_ERR, "Failed to write to value file: ");
        perror("write");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to log messages to syslog
void log_message(int priority, const char *message) {
    syslog(priority, "%s", message);
}

int main() {
