#define LED_1_PIN 27
#define LED_2_PIN 22

// Define debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Define log buffer size
#define LOG_BUFFER_SIZE 100

// Structure to store log entry
typedef struct {
    int sensor_pin;
    time_t timestamp;
    int state;
} log_entry_t;

// Global variables
volatile sig_atomic_t program_running = 1;
log_entry_t log_buffer[LOG_BUFFER_SIZE];
int log_index = 0;
int overflow_count = 0;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio_pin);
void control_led(int gpio_pin, int state);
void log_event(int sensor_pin, int state);
void print_log();
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetMode(LED_1_PIN, PI_OUTPUT);
    gpioSetMode(LED_2_PIN, PI_OUTPUT);

    return 0;
}

// Function to read sensor value with debouncing
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    gpioDelay(DEBOUNCE_TIME * 1000); // Convert ms to microseconds
    return value;
}

// Function to control LED state
void control_led(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

// Function to log event to circular buffer
void log_event(int sensor_pin, int state) {
    log_buffer[log_index].sensor_pin = sensor_pin;
    log_buffer[log_index].timestamp = time(NULL);
    log_buffer[log_index].state = state;

    log_index = (log_index + 1) % LOG_BUFFER_SIZE;

    if (log_index == 0) {
        overflow_count++;
    }
}

// Function to print log buffer contents
void print_log() {
    printf("\n--- Log Buffer ---\n");
    for (int i = 0; i < LOG_BUFFER_SIZE; i++) {
        int index = (log_index + i) % LOG_BUFFER_SIZE;
        printf("[%d] Sensor: %d, Timestamp: %ld, State: %d\n", i, log_buffer[index].sensor_pin, log_buffer[index].timestamp, log_buffer[index].state);
    }
    printf("--- Overflow Count: %d ---\n", overflow_count);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to turn off LEDs and terminate pigpio
void cleanup() {
    control_led(LED_1_PIN, 0);
    control_led(LED_2_PIN, 0);
    gpioTerminate();
}

int main() {
