#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define RAIN_SENSOR_GPIO 17
#define LOG_FILE "/var/log/rain_events.log"

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library and GPIO pin
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(RAIN_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(RAIN_SENSOR_GPIO, PI_PUD_UP); // Enable pull-up resistor

    return 0;
}

// Function to read the rain sensor value
int read_rain_sensor() {
    return gpioRead(RAIN_SENSOR_GPIO);
}

// Function to log the rain event to a file
int log_rain_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure the log is written immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

// Function to cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    if (log_file != NULL) {
        fclose(log_file);
        printf("Log file closed.\n");
    }
    gpioTerminate();
    printf("pigpio terminated.\n");
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio and GPIO pin
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    int previous_state = -1; // Initialize to an invalid state

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop to continuously monitor the rain sensor
    while (running) {
        int current_state = read_rain_sensor();

        if (current_state == -1) {
            fprintf(stderr, "Error reading rain sensor.\n");
        } else {
            if (current_state != previous_state) {
                if (current_state == 0) {
                    if (log_rain_event("Rain Detected") != 0) {
                        fprintf(stderr, "Error logging rain event.\n");
                    }
                } else {
                    if (log_rain_event("No Rain") != 0) {
                        fprintf(stderr, "Error logging no rain event.\n");
                    }
                }
                previous_state = current_state;
            }
        }

        gpioDelay(500); // Wait 500ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

