#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 18
#define ALARM_PIN 27

// Define alarm duration (in seconds)
#define ALARM_DURATION 2

// Define log file name
#define LOG_FILE "bridge_integrity.log"

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int read_sensor(int gpio_pin);
void log_event(const char *event_type);
void activate_alarm();
void deactivate_alarm();
void signal_handler(int signal);

// Function to read sensor value
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor on GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate error
    }
    return value;
}

// Function to log events to file
void log_event(const char *event_type) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, event_type);
        fflush(log_file); // Ensure immediate write to file
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to activate the alarm
void activate_alarm() {
    if (gpioWrite(ALARM_PIN, 1) != 0) {
        fprintf(stderr, "Error activating alarm.\n");
    }
    log_event("Alarm Activated");
}

// Function to deactivate the alarm
void deactivate_alarm() {
    if (gpioWrite(ALARM_PIN, 0) != 0) {
        fprintf(stderr, "Error deactivating alarm.\n");
    }
    log_event("Alarm Deactivated");
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    deactivate_alarm();

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetMode(ALARM_PIN, PI_OUTPUT);

    // Enable pull-down resistors
    gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN);

    // Initialize alarm to OFF state
    deactivate_alarm();

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int alarm_active = 0;
    time_t alarm_start_time = 0;

    printf("Bridge integrity monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int sensor1_value = read_sensor(SENSOR_1_PIN);
        int sensor2_value = read_sensor(SENSOR_2_PIN);

        if (sensor1_value == -1 || sensor2_value == -1) {
            fprintf(stderr, "Error reading sensors, exiting.\n");
            break;
        }

        // Check for tilt start
        if (sensor1_value == 1 || sensor2_value == 1) {
            if (!alarm_active) {
                log_event("Tilt Start");
            }
        }

        // Check for threshold exceeded
        if (sensor1_value == 1 && sensor2_value == 1) {
            if (!alarm_active) {
                log_event("Threshold Exceeded");
                alarm_active = 1;
                activate_alarm();
                alarm_start_time = time(NULL);
            }
        }

        // Check for alarm duration
        if (alarm_active) {
            time_t current_time = time(NULL);
            if (difftime(current_time, alarm_start_time) >= ALARM_DURATION) {
                deactivate_alarm();
                alarm_active = 0;
            }
        }

        // Check for tilt end
        if (sensor1_value == 0 && sensor2_value == 0) {
            if (alarm_active) {
                log_event("Tilt End");
            }
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    deactivate_alarm();
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

