#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <math.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define D7S_ADDR 0x1D
#define CTRL1_REG 0x20
#define X_AXIS_LSB 0x28
#define Y_AXIS_LSB 0x2A
#define Z_AXIS_LSB 0x2C
#define THRESHOLD 500
#define ALERT_LED_GPIO 17
#define POLL_INTERVAL_MS 100
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function prototypes
int initialize_sensor();
sensor_data_t read_sensor_data();
double calculate_magnitude(sensor_data_t data);
void log_event(double magnitude);
void trigger_alert();
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initializes the D7S sensor
int initialize_sensor() {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        // Verify sensor presence by reading CTRL1 register
        int ctrl1 = i2cReadByteData(i2c_handle, CTRL1_REG);
        if (ctrl1 < 0) {
            fprintf(stderr, "Error reading CTRL1 register (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            gpioDelay(10000); // Wait 10ms before retrying
            continue;
        }

        // Check if the sensor is present (CTRL1 should not be 0xFF)
        if (ctrl1 == 0xFF) {
            fprintf(stderr, "Sensor not present (attempt %d)\n", retries + 1);
            retries++;
            gpioDelay(10000); // Wait 10ms before retrying
            continue;
        }

        // Clear power-down bit (CTRL1 = 0x01)
        if (i2cWriteByteData(i2c_handle, CTRL1_REG, 0x01) < 0) {
            fprintf(stderr, "Error writing to CTRL1 register (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            gpioDelay(10000); // Wait 10ms before retrying
            continue;
        }

        printf("Sensor initialized successfully.\n");
        return 0; // Success
    }

    fprintf(stderr, "Failed to initialize sensor after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Reads sensor data from the D7S
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        // Read X axis data
        int x_lsb = i2cReadByteData(i2c_handle, X_AXIS_LSB);
        int x_msb = i2cReadByteData(i2c_handle, X_AXIS_LSB + 1);

        if (x_lsb < 0 || x_msb < 0) {
            fprintf(stderr, "Error reading X axis data (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            gpioDelay(10000); // Wait 10ms before retrying
            continue;
        }

        data.x = (int16_t)((x_msb << 8) | x_lsb);

        // Read Y axis data
        int y_lsb = i2cReadByteData(i2c_handle, Y_AXIS_LSB);
        int y_msb = i2cReadByteData(i2c_handle, Y_AXIS_LSB + 1);

        if (y_lsb < 0 || y_msb < 0) {
            fprintf(stderr, "Error reading Y axis data (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            gpioDelay(10000); // Wait 10ms before retrying
            continue;
        }

        data.y = (int16_t)((y_msb << 8) | y_lsb);

        // Read Z axis data
        int z_lsb = i2cReadByteData(i2c_handle, Z_AXIS_LSB);
        int z_msb = i2cReadByteData(i2c_handle, Z_AXIS_LSB + 1);

        if (z_lsb < 0 || z_msb < 0) {
            fprintf(stderr, "Error reading Z axis data (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            gpioDelay(10000); // Wait 10ms before retrying
            continue;
        }

        data.z = (int16_t)((z_msb << 8) | z_lsb);

        return data; // Success
    }

    fprintf(stderr, "Failed to read sensor data after %d retries.\n", MAX_RETRIES);
    data.x = 0; // Return default values in case of failure
    data.y = 0;
    data.z = 0;
    return data;
}

// Calculates the Euclidean vibration magnitude
double calculate_magnitude(sensor_data_t data) {
    return sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
}

// Logs the event to a file
void log_event(double magnitude) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s, Magnitude: %.2f\n", timestamp, magnitude);
    fflush(log_file); // Ensure data is written to disk immediately
