#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <gpiod.h>

// Configuration
#define GPIO_CHIP "gpiochip0"
#define NUM_SENSORS 5
#define DEBOUNCE_DELAY_MS 50
#define LOG_FILE "/var/log/flame_events.log"
#define LOCK_FILE "/var/run/flame_monitor.lock"

// Sensor GPIO pins
const int sensor_pins[NUM_SENSORS] = {2, 3, 4, 17, 27};

// Sensor IDs
const char *sensor_ids[NUM_SENSORS] = {"sensor1", "sensor2", "sensor3", "sensor4", "sensor5"};

// Global variables
struct gpiod_chip *chip;
struct gpiod_line *lines[NUM_SENSORS];
volatile sig_atomic_t terminate = 0;
int lock_fd = -1;

// Function prototypes
int init_gpio();
int read_sensor(int pin);
int debounce_read(int pin);
int log_event(const char *sensor_id, int pin);
void signal_handler(int sig);
void cleanup();
int acquire_lock();
void release_lock();

// Signal handler
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Initialize GPIO lines
int init_gpio() {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %s", GPIO_CHIP);
        return -1;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!lines[i]) {
            syslog(LOG_ERR, "Failed to get line for GPIO %d", sensor_pins[i]);
            cleanup();
            return -1;
        }

        if (gpiod_line_request_input(lines[i], "flame_monitor") < 0) {
            syslog(LOG_ERR, "Failed to request line for GPIO %d as input", sensor_pins[i]);
            cleanup();
            return -1;
        }
    }

    syslog(LOG_INFO, "GPIO initialization complete.");
    return 0;
}

// Read sensor value
int read_sensor(int pin) {
    int i;
    for (i = 0; i < NUM_SENSORS; i++) {
        if (sensor_pins[i] == pin) {
            return gpiod_line_get_value(lines[i]);
        }
    }
    syslog(LOG_ERR, "Invalid pin number: %d", pin);
    return -1; // Indicate error
}

// Debounce read
int debounce_read(int pin) {
    int value = read_sensor(pin);
    if (value < 0) return -1; // Propagate error
    usleep(DEBOUNCE_DELAY_MS * 1000); // Debounce delay
    return value;
}

// Log event to file
int log_event(const char *sensor_id, int pin) {
    time_t now = time(NULL);
    struct tm *t = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        syslog(LOG_ERR, "Failed to open log file: %s", LOG_FILE);
        return -1;
    }

    if (flock(fileno(fp), LOCK_EX) == -1) {
        syslog(LOG_ERR, "Failed to acquire lock on log file: %s", strerror(errno));
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%s - Sensor ID: %s (GPIO %d) - Flame Detected\n", timestamp, sensor_id, pin);
    fflush(fp);

    if (flock(fileno(fp), LOCK_UN) == -1) {
        syslog(LOG_ERR, "Failed to release lock on log file: %s", strerror(errno));
    }

    fclose(fp);
    syslog(LOG_INFO, "Logged event: %s - Sensor ID: %s (GPIO %d) - Flame Detected", timestamp, sensor_id, pin);
    return 0;
}

// Cleanup resources
void cleanup() {
    syslog(LOG_INFO, "Cleaning up resources...");
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (lock_fd != -1) {
        release_lock();
    }
    closelog();
}

// Acquire lock file
int acquire_lock() {
    lock_fd = open(LOCK_FILE, O_CREAT | O_WRONLY, 0644);
    if (lock_fd == -1) {
        syslog(LOG_ERR, "Failed to open lock file: %s", strerror(errno));
        return -1;
    }

    if (flock(lock_fd, LOCK_EX | LOCK_NB) == -1) {
        syslog(LOG_ERR, "Failed to acquire lock: %s", strerror(errno));
        close(lock_fd);
        lock_fd = -1;
        return -1;
    }

    syslog(LOG_INFO, "Lock acquired.");
    return 0;
}

// Release lock file
void release_lock() {
    if (lock_fd != -1) {
        if (flock(lock_fd, LOCK_UN) == -1) {
            syslog(LOG_ERR, "Failed to release lock: %s", strerror(errno));
        }
        close(lock_fd);
        lock_fd = -1;
        syslog(LOG_INFO, "Lock released.");
    }
}

int main() {
    // Initialize syslog
    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Acquire lock
    if (acquire_lock() != 0) {
        syslog(LOG_ERR, "Failed to acquire lock, exiting.");
        closelog();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting.");
        release_lock();
        closelog();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    syslog(LOG_INFO, "Flame sensor monitoring started.");

    // Main loop
    while (!terminate) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int value = read_sensor(sensor_pins[i]);
            if (value < 0) {
                syslog(LOG_ERR, "Error reading sensor %s (GPIO %d)", sensor_ids[i], sensor_pins[i]);
                continue; // Skip to the next sensor
            }

            if (value == 0) { // Flame detected (LOW signal)
                int debounced_value = debounce_read(sensor_pins[i]);
                if (debounced_value < 0) {
                    syslog(LOG_ERR, "Error debouncing sensor %s (GPIO %d)", sensor_ids[i], sensor_pins[i]);
                    continue; // Skip to the next sensor
                }

                if (debounced_value == 0) { // Confirmed flame detection
                    if (log_event(sensor_ids[i], sensor_pins[i]) != 0) {
                        syslog(LOG_ERR, "Error logging event for sensor %s (GPIO %d)", sensor_ids[i], sensor_pins[i]);
                    }
                }
            }
        }
        sleep(1); // Check every second
    }

    // Cleanup and exit
    cleanup();
    syslog(LOG_INFO, "Flame sensor monitoring stopped.");
    return 0;
}

