// Define the GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define the GPIO lines
const int gpio_lines[] = {5, 6, 13, 19, 26, 12, 16, 20};
const int num_lines = sizeof(gpio_lines) / sizeof(gpio_lines[0]);

// Global variables
struct gpiod_chip *chip;
struct gpiod_line *lines[8];
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int read_sensor_data(int *sensor_data);
void log_touch_event(int sensor_index, int gpio_pin, int state);
void cleanup_gpio();
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");
        terminate = 1;
    }
}

// Initializes the GPIO chip and lines
int initialize_gpio() {
    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Request the GPIO lines as input
    for (int i = 0; i < num_lines; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpio_lines[i]);
        if (!lines[i]) {
            perror("Error getting GPIO line");
            cleanup_gpio();
            return -1;
        }

        struct gpiod_line_request_config config;
        memset(&config, 0, sizeof(config));
        config.consumer = "touch_sensor";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

        if (gpiod_line_request(lines[i], &config, 0) < 0) {
            perror("Error requesting GPIO line");
            cleanup_gpio();
            return -1;
        }
    }

    return 0;
}

// Reads the sensor data from the GPIO lines
int read_sensor_data(int *sensor_data) {
    for (int i = 0; i < num_lines; i++) {
        int value = gpiod_line_get_value(lines[i]);
        if (value < 0) {
            perror("Error reading GPIO line value");
            return -1;
        }
        sensor_data[i] = value;
    }
    return 0;
}

// Logs a touch event to the console
void log_touch_event(int sensor_index, int gpio_pin, int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    printf("%s Sensor %d (GPIO %d): %s\n", timestamp, sensor_index, gpio_pin, state ? "Touched" : "Released");
}

// Cleans up the GPIO chip and lines
void cleanup_gpio() {
    for (int i = 0; i < num_lines; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    // Install signal handler for SIGINT
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Error installing signal handler");
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    int sensor_data[num_lines];
    int previous_sensor_data[num_lines] = {0}; // Initialize to released state

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(sensor_data) < 0) {
            fprintf(stderr, "Error reading sensor data. Retrying.\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Log touch events
        for (int i = 0; i < num_lines; i++) {
            if (sensor_data[i] != previous_sensor_data[i]) {
                log_touch_event(i, gpio_lines[i], sensor_data[i]);
                previous_sensor_data[i] = sensor_data[i];
            }
        }

        // Wait 50ms
        usleep(50000); // 50ms = 50000 microseconds
    }

    // Cleanup GPIO
    cleanup_gpio();

    return 0;
}

