#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define VEML7700_ADDR 0x48
#define ALS_CONF 0x00
#define ALS_DATA 0x04
#define GPIO_LED 18
#define PWM_FREQ 1000
#define SAMPLE_INTERVAL 1 // seconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_veml7700();
int read_lux(float *lux);
int set_brightness(int brightness);
int log_data(float lux, int brightness, int error_code);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize VEML7700 sensor
int init_veml7700() {
    // Configure ALS_CONF register (integration time = 100ms, gain = 1/8)
    // 0b00000010 00000000
    if (i2cWriteByteData(i2c_handle, ALS_CONF, 0x02) < 0) {
        fprintf(stderr, "Error writing to ALS_CONF register\n");
        return -1;
    }
    return 0;
}

// Read lux value from VEML7700 sensor
int read_lux(float *lux) {
    unsigned int raw_data;

    // Read ALS_DATA register
    raw_data = i2cReadWordData(i2c_handle, ALS_DATA);
    if (raw_data < 0) {
        fprintf(stderr, "Error reading from ALS_DATA register\n");
        return -1;
    }

    // Convert raw data to lux (adjust gain and integration time as needed)
    *lux = (float)raw_data * 0.0576; // Example conversion, adjust as needed

    return 0;
}

// Set LED brightness using hardware PWM
int set_brightness(int brightness) {
    if (brightness < 0 || brightness > 100) {
        fprintf(stderr, "Invalid brightness value: %d\n", brightness);
        return -1;
    }

    // Calculate PWM duty cycle (0-1000000)
    int duty_cycle = (int)((float)brightness / 100.0 * 1000000.0);

    // Set PWM duty cycle
    gpioPWM(GPIO_LED, duty_cycle);

    return 0;
}

// Log data to file
int log_data(float lux, int brightness, int error_code) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f,%d,%d\n", timestamp, lux, brightness, error_code);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    // Turn off LED
    gpioPWM(GPIO_LED, 0);

    // Close I2C bus
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    float lux;
    int brightness;
    int error_code = 0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VEML7700 sensor
    if (init_veml7700() < 0) {
        fprintf(stderr, "VEML7700 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure GPIO18 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(GPIO_LED, PWM_FREQ);

    // Open log file
    log_file = fopen("grow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Grow light system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read lux value
        if (read_lux(&lux) < 0) {
            fprintf(stderr, "Error reading lux value\n");
            error_code = -1;
        } else {
            error_code = 0;

            // Map lux value to brightness level
            if (lux < 100) {
                brightness = 100;
            } else if (lux < 500) {
                brightness = 75;
            } else if (lux < 1000) {
                brightness = 50;
            } else {
                brightness = 25;
            }

            // Set LED brightness
            if (set_brightness(brightness) < 0) {
                fprintf(stderr, "Error setting brightness\n");
                error_code = -2;
            }
        }

        // Log data
        log_data(lux, brightness, error_code);

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

