#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for touch sensors and LED
#define TOUCH_SENSOR_1 2
#define TOUCH_SENSOR_2 3
#define TOUCH_SENSOR_3 4
#define TOUCH_SENSOR_4 5
#define TOUCH_SENSOR_5 6
#define TOUCH_SENSOR_6 7
#define TOUCH_SENSOR_7 8
#define TOUCH_SENSOR_8 9
#define LED_PIN 17

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Structure to hold previous touch states
typedef struct {
    int channel1;
    int channel2;
    int channel3;
    int channel4;
    int channel5;
    int channel6;
    int channel7;
    int channel8;
} TouchState;

TouchState previous_touch_state = {0, 0, 0, 0, 0, 0, 0, 0};

// Function prototypes
int initialize_gpio();
int read_touch_sensor(int gpio_pin);
void log_touch_event(int channel);
void control_led(int state);
void signal_handler(int signal);
