#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define LOG_FILE "light_data.txt"
#define SAMPLE_INTERVAL_MS 1000
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for OPT3001 configuration
typedef struct {
    uint16_t range;
    uint16_t conversion_time;
    uint16_t mode;
} opt3001_config_t;

// Function prototypes
int init_pigpio();
int init_i2c(int bus, int addr);
int write_config(int handle, opt3001_config_t config);
int read_result(int handle, uint16_t *result);
float convert_to_lux(uint16_t raw_data);
int log_data(const char *timestamp, float lux_value);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Write configuration to OPT3001
int write_config(int handle, opt3001_config_t config) {
    uint16_t config_value = (config.range << 12) | (config.conversion_time << 8) | config.mode;
    uint8_t data[2];
    data[0] = (config_value >> 8) & 0xFF; // MSB
    data[1] = config_value & 0xFF;      // LSB

    int result = i2cWriteDevice(handle, (char *)data, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write configuration: %d\n", result);
        return -1;
    }
    return 0;
}

// Read result from OPT3001
int read_result(int handle, uint16_t *result) {
    char buffer[2];
    int result_raw;

    result_raw = i2cReadDevice(handle, buffer, 2);
    if (result_raw != 2) {
        fprintf(stderr, "Failed to read result: %d\n", result_raw);
        return -1;
    }

    *result = (buffer[0] << 8) | buffer[1]; // Byte swap
    return 0;
}

// Convert raw data to lux value
float convert_to_lux(uint16_t raw_data) {
    int exponent = (raw_data >> 12) & 0x0F;
    int result = raw_data & 0x0FFF;
    return 0.01 * result * (1 << exponent);
}

// Log data to file
int log_data(const char *timestamp, float lux_value) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s, %.2f\n", timestamp, lux_value);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    i2c_handle = init_i2c(I2C_BUS, OPT3001_ADDR);
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Configure OPT3001 (Continuous conversion mode, 100ms conversion time, auto range)
    opt3001_config_t config = {0x03, 0x03, 0x01}; // Continuous conversion, 100ms, Auto range
    if (write_config(i2c_handle, config) != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint16_t raw_data;
        float lux_value;
        time_t now;
        struct tm *timeinfo;
        char timestamp[20];

        // Read result
        if (read_result(i2c_handle, &raw_data) == 0) {
            // Convert to lux
            lux_value = convert_to_lux(raw_data);

            // Get timestamp
            time(&now);
            timeinfo = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log data
            if (log_data(timestamp, lux_value) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }

            // Print to stdout
            printf("%s, %.2f\n", timestamp, lux_value);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

