#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define GPIO_PIN 4
#define DEBOUNCE_MS 50
#define LOG_FILE "touch_log.txt"

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to get the current timestamp in YYYY-MM-DD HH:MM:SS format
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; // Ensure buffer is large enough

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log a touch event to the log file
int log_touch_event(const char *event) {
    char *timestamp = get_timestamp();
    if (log_file == NULL) {
        fprintf(stderr, "%s: Error: Log file is not open.\n", timestamp);
        return -1;
    }

    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    char *timestamp = get_timestamp();
    printf("%s: Received signal %d, shutting down...\n", timestamp, signal);
    running = 0;
}

int main() {
    int last_state = 0; // 0 = released, 1 = pressed
    int current_state;
    int rc;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input with pull-down resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        current_state = gpioRead(GPIO_PIN);

        if (current_state != last_state) {
            gpioDelay(DEBOUNCE_MS * 1000); // Debounce delay
            current_state = gpioRead(GPIO_PIN); // Re-read after debounce

            if (current_state != last_state) {
                if (current_state == 1) {
                    if (log_touch_event("Touch Detected") != 0) {
                        running = 0; // Stop if logging fails
                    }
                } else {
                    if (log_touch_event("Touch Released") != 0) {
                        running = 0; // Stop if logging fails
                    }
                }
                last_state = current_state;
            }
        }

        gpioDelay(1000); // Small delay to reduce CPU usage
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

