#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SLF3S_ADDR 0x36
#define FLOW_CMD 0x3608
#define FLOW_SCALE 0.0625 // ml/min per LSB
#define MIN_FLOW 0.0
#define MAX_FLOW 100.0
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    int16_t flow_rate;
    uint8_t crc;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(sensor_data_t *data);
float convert_flow_rate(int16_t raw_flow);
uint8_t calculate_crc(uint8_t data[], int len);
const char *validate_flow_rate(float flow_rate);
int log_data(float flow_rate, const char *status);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(sensor_data_t *data) {
    char cmd[2] = {(FLOW_CMD >> 8) & 0xFF, FLOW_CMD & 0xFF};
    char buffer[3];

    if (i2cWriteDevice(i2c_handle, cmd, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    gpioDelay(2); // Wait 2 ms

    if (i2cReadDevice(i2c_handle, buffer, 3) != 3) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    data->flow_rate = (int16_t)((buffer[0] << 8) | buffer[1]);
    data->crc = buffer[2];

    return 0;
}

// Convert raw flow rate to ml/min
float convert_flow_rate(int16_t raw_flow) {
    return (float)raw_flow * FLOW_SCALE;
}

// Calculate CRC8 checksum
uint8_t calculate_crc(uint8_t data[], int len) {
    uint8_t crc = CRC8_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate flow rate
const char *validate_flow_rate(float flow_rate) {
    if (flow_rate >= MIN_FLOW && flow_rate <= MAX_FLOW) {
        return "VALID";
    } else {
        return "INVALID";
    }
}

// Log data to CSV file
int log_data(float flow_rate, const char *status) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen("cooling_log.csv", "w");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file\n");
            return -1;
        }
        fprintf(log_file, "Timestamp,Flow Rate (ml/min),Status\n");
    } else {
        log_file = fopen("cooling_log.csv", "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file\n");
            return -1;
        }
    }

    fprintf(log_file, "%s,%.2f,%s\n", timestamp, flow_rate, status);
    fclose(log_file);
    return 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;
    float flow_rate;
    const char *status;
    uint8_t crc_calculated;
    uint8_t crc_received;
    char data[2];

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Convert raw flow rate
            flow_rate = convert_flow_rate(sensor_data.flow_rate);

            // Validate flow rate
            status = validate_flow_rate(flow_rate);

            // Calculate CRC
            data[0] = (sensor_data.flow_rate >> 8) & 0xFF;
            data[1] = sensor_data.flow_rate & 0xFF;
            crc_calculated = calculate_crc(data, 2);

            // Validate CRC
            crc_received = sensor_data.crc;
            if (crc_calculated != crc_received) {
                fprintf(stderr, "CRC check failed! Calculated: 0x%02X, Received: 0x%02X\n", crc_calculated, crc_received);
                status = "ERROR";
            }

            // Log data
            if (log_data(flow_rate, status) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            // Log I2C read error
            log_data(0.0, "ERROR");

            // Attempt to re-initialize I2C
            i2cClose(i2c_handle);
            if (initialize_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                terminate = 1; // Exit loop if re-initialization fails
            }
        }

        sleep(1); // Sample every 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

