// Define GPIO pins for the sensors
#define LEFT_SENSOR_PIN 17
#define MIDDLE_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN 22

// Define the log file name
#define LOG_FILE "path_log.csv"

// Global variables
FILE *log_file = NULL;
bool running = true;

// Function prototypes
int read_sensor(int gpio_pin);
char* get_iso8601_timestamp();
int write_to_log(const char *timestamp, int left, int middle, int right);
void signal_handler(int signal);

// Function to read the sensor value from a given GPIO pin
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor on GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        fprintf(stderr, "Error allocating memory for timestamp\n");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    return timestamp;
}

// Function to write the sensor data to the log file
int write_to_log(const char *timestamp, int left, int middle, int right) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    int result = fprintf(log_file, "%s,%d,%d,%d\n", timestamp, left, middle, right);
    if (result < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = false;
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Write the header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,left,middle,right\n");
    }
    rewind(log_file);

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        // Read sensor values
        int left_value = read_sensor(LEFT_SENSOR_PIN);
        int middle_value = read_sensor(MIDDLE_SENSOR_PIN);
        int right_value = read_sensor(RIGHT_SENSOR_PIN);

        // Get the current timestamp
        char *timestamp = get_iso8601_timestamp();

        // Write the data to the log file
        if (timestamp != NULL && left_value != -1 && middle_value != -1 && right_value != -1) {
            if (write_to_log(timestamp, left_value, middle_value, right_value) != 0) {
                fprintf(stderr, "Error writing to log, exiting\n");
                running = false; // Exit loop on write error
            }
        } else {
            fprintf(stderr, "Error reading sensor data, skipping log entry\n");
        }

        // Free the timestamp memory
        if (timestamp != NULL) {
            free(timestamp);
        }

        // Delay for 50 milliseconds
        gpioDelay(50000); // pigpioDelay takes microseconds
    }

    // Clean up and exit
    printf("Cleaning up...\n");

    // Close the log file
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }

    // Release GPIO pins
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

