#include <pigpio.h>

#define FLAME_SENSOR_GPIO 4
#define LOG_FILE "flame_events.txt"

static volatile int running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to get the current timestamp in ISO 8601 format
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(21 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 21, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log an event to the log file
int log_event(const char *timestamp) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    fprintf(fp, "%s: Flame detected\n", timestamp);
    fclose(fp);
    return 0;
}

// Callback function for flame detection
void flame_detected_callback(int gpio, int level, uint32_t tick) {
    if (level == 0) { // Falling edge detected (flame detected)
        char *timestamp = get_timestamp();
        if (timestamp != NULL) {
            if (log_event(timestamp) == 0) {
                printf("%s: Flame detected and logged\n", timestamp);
            } else {
                fprintf(stderr, "%s: Failed to log event\n", timestamp);
            }
            free(timestamp);
        } else {
            fprintf(stderr, "Failed to get timestamp\n");
        }
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 4 as an input
    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", FLAME_SENSOR_GPIO);
        gpioTerminate();
        return 1;
    }

    // Set pull-up resistor (optional, depending on sensor wiring)
    gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP);

    // Register the callback function for falling edge detection
    if (gpioSetAlertFuncEx(FLAME_SENSOR_GPIO, flame_detected_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for GPIO %d\n", FLAME_SENSOR_GPIO);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        gpioDelay(100); // Sleep for 100ms to reduce CPU usage
    }

    // Clean up and exit
    gpioTerminate();
    printf("pigpio terminated.\n");
    return 0;
}

