#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 23
#define LED_PIN 24

// Define GPIO chip
#define GPIO_CHIP "gpiochip4"

// Define log file path
#define LOG_FILE "touch_log.txt"

// Global variables
static volatile int keep_running = 1;
static int led_state = 0; // 0 = off, 1 = on
static int log_fd = -1;

// Function prototypes
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_get_value(int pin);
int gpio_set_value(int pin, int value);
int log_event(const char *timestamp, int led_state);
void signal_handler(int sig);
int setup_gpio();
int cleanup_gpio();

// Structure to hold GPIO configuration
typedef struct {
    int touch_pin;
    int led_pin;
    const char *chip;
} gpio_config_t;

// Function to export a GPIO pin
int gpio_export(int pin) {
    char buffer[64];
    int fd;

    fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening /sys/class/gpio/export: %s\n", strerror(errno));
        return -1;
    }
    int len = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, len) != len) {
        fprintf(stderr, "Error writing to /sys/class/gpio/export: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to unexport a GPIO pin
int gpio_unexport(int pin) {
    char buffer[64];
    int fd;

    fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening /sys/class/gpio/unexport: %s\n", strerror(errno));
        return -1;
    }

    int len = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, len) != len) {
        fprintf(stderr, "Error writing to /sys/class/gpio/unexport: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to set the direction of a GPIO pin (in or out)
int gpio_set_direction(int pin, const char *direction) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }

    if (write(fd, direction, strlen(direction)) != strlen(direction)) {
        fprintf(stderr, "Error writing to %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to get the value of a GPIO pin
int gpio_get_value(int pin) {
    char path[64];
    char value_str[3];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    fd = open(path, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }

    if (read(fd, value_str, 3) < 0) {
        fprintf(stderr, "Error reading from %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return atoi(value_str);
}

// Function to set the value of a GPIO pin
int gpio_set_value(int pin, int value) {
    char path[64];
    char value_str[3];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }

    int len = snprintf(value_str, sizeof(value_str), "%d", value);
    if (write(fd, value_str, len) != len) {
        fprintf(stderr, "Error writing to %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to log an event to the log file
int log_event(const char *timestamp, int led_state) {
    if (log_fd == -1) {
        fprintf(stderr, "Log file not opened.\n");
        return -1;
    }

    char log_entry[256];
    int len = snprintf(log_entry, sizeof(log_entry), "%s, LED: %s\n", timestamp, led_state ? "ON" : "OFF");

    if (write(log_fd, log_entry, len) != len) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting gracefully.\n");
    keep_running = 0;
}

// Function to setup GPIO pins
int setup_gpio() {
    if (gpio_export(TOUCH_SENSOR_PIN) < 0) return -1;
    if (gpio_export(LED_PIN) < 0) {
        gpio_unexport(TOUCH_SENSOR_PIN);
        return -1;
    }

    if (gpio_set_direction(TOUCH_SENSOR_PIN, "in") < 0) {
        gpio_unexport(TOUCH_SENSOR_PIN);
        gpio_unexport(LED_PIN);
        return -1;
    }
    if (gpio_set_direction(LED_PIN, "out") < 0) {
        gpio_unexport(TOUCH_SENSOR_PIN);
        gpio_unexport(LED_PIN);
        return -1;
    }

    return 0;
}

// Function to cleanup GPIO pins
int cleanup_gpio() {
    if (gpio_unexport(TOUCH_SENSOR_PIN) < 0) return -1;
    if (gpio_unexport(LED_PIN) < 0) return -1;
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (setup_gpio() < 0) {
        fprintf(stderr, "GPIO setup failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup_gpio();
        return 1;
    }

    // Main loop
    while (keep_running) {
        int touch_value = gpio_get_value(TOUCH_SENSOR_PIN);
        if (touch_value < 0) {
            fprintf(stderr, "Error reading touch sensor value. Continuing.\n");
            sleep(1); // Avoid spamming errors
            continue;
        }

        if (touch_value == 1) {
            // Touch detected
            led_state = !led_state;
            if (gpio_set_value(LED_PIN, led_state) < 0) {
                fprintf(stderr, "Error setting LED value. Continuing.\n");
            }

            // Get timestamp
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[32];

            time(&rawtime);
            timeinfo = localtime(&rawtime);

            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

            // Log event
            if (log_event(timestamp, led_state) < 0) {
                fprintf(stderr, "Error logging event. Continuing.\n");
            }

            // Debounce: Wait for a short period to avoid multiple triggers
            usleep(500000); // 0.5 seconds
        }

        usleep(100000); // Check every 0.1 seconds
    }

    // Cleanup
    close(log_fd);
    cleanup_gpio();

    return 0;
}

