void activate_buzzer(int duration_ms) {
    gpioWrite(BUZZER_PIN, 1); // Turn buzzer on
    gpioDelay(duration_ms * 1000); // Delay for specified duration
    gpioWrite(BUZZER_PIN, 0); // Turn buzzer off
}

// Function to log events to a file
void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, event);
        fflush(log_file); // Ensure immediate write to file
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(BUZZER_PIN, 0); // Ensure buzzer is off
    gpioTerminate(); // Terminate pigpio

    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Log system started event
    log_event("System started");

    int flame_detected = 0; // Flag to track flame detection state

    // Main loop
    while (running) {
        int sensor_value = read_flame_sensor();

        if (sensor_value == 0 && !flame_detected) { // Flame detected (LOW signal)
            printf("Flame detected!\n");
            log_event("FLAME DETECTED");
            activate_buzzer(BUZZER_DURATION_MS);
            flame_detected = 1; // Set flag to prevent repeated logging
        } else if (sensor_value == 1) {
            flame_detected = 0; // Reset flag if flame is no longer detected
        }

        gpioDelay(POLL_INTERVAL_MS * 1000); // Poll every 500ms
    }

    // Log system stopped event
    log_event("System stopped");

    // Cleanup and exit
    cleanup();
    return 0;
}

