#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x49
#define PART_ID_REG 0x00
#define HW_REV_REG 0x01
#define HEART_RATE_REG 0x24
#define MOVING_AVG_SIZE 5
#define BPM_MIN 30
#define BPM_MAX 220
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor configuration
typedef struct {
    uint8_t part_id;
    uint8_t hw_rev;
} sensor_config_t;

// Function prototypes
int init_i2c();
int init_sensor(sensor_config_t *config);
int read_heart_rate(int *heart_rate);
float apply_moving_average(int new_value, float *history, int *index, int size);
int validate_bpm(float bpm);
int log_data(float bpm);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Initialize the Si1182 sensor
int init_sensor(sensor_config_t *config) {
    int part_id, hw_rev;
    int retries = RETRY_COUNT;

    // Read Part ID
    while (retries > 0) {
        part_id = i2cReadByteData(i2c_handle, PART_ID_REG);
        if (part_id >= 0) {
            break;
        } else {
            fprintf(stderr, "Error reading Part ID, retrying... (%d retries left)\n", retries - 1);
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read Part ID after multiple retries\n");
        return -1;
    }

    // Read HW Revision
    retries = RETRY_COUNT;
    while (retries > 0) {
        hw_rev = i2cReadByteData(i2c_handle, HW_REV_REG);
        if (hw_rev >= 0) {
            break;
        } else {
            fprintf(stderr, "Error reading HW Revision, retrying... (%d retries left)\n", retries - 1);
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read HW Revision after multiple retries\n");
        return -1;
    }

    config->part_id = (uint8_t)part_id;
    config->hw_rev = (uint8_t)hw_rev;

    // Verify Part ID and HW Revision
    if (config->part_id != 0x82) {
        fprintf(stderr, "Incorrect Part ID: 0x%02X\n", config->part_id);
        return -1;
    }
    if (config->hw_rev != 0x01) {
        fprintf(stderr, "Incorrect HW Revision: 0x%02X\n", config->hw_rev);
        return -1;
    }

    printf("Si1182 sensor initialized successfully\n");
    return 0;
}

// Read heart rate data from the sensor
int read_heart_rate(int *heart_rate) {
    int retries = RETRY_COUNT;
    int raw_value;

    while (retries > 0) {
        raw_value = i2cReadWordData(i2c_handle, HEART_RATE_REG);
        if (raw_value >= 0) {
            break;
        } else {
            fprintf(stderr, "Error reading heart rate, retrying... (%d retries left)\n", retries - 1);
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read heart rate after multiple retries\n");
        return -1;
    }

    *heart_rate = raw_value;
    return 0;
}

// Apply a moving average filter
float apply_moving_average(int new_value, float *history, int *index, int size) {
    history[*index] = (float)new_value;
    *index = (*index + 1) % size;

    float sum = 0.0;
    for (int i = 0; i < size; i++) {
        sum += history[i];
    }

    return sum / size;
}

// Validate BPM value
int validate_bpm(float bpm) {
    if (bpm >= BPM_MIN && bpm <= BPM_MAX) {
        return 0; // Valid
    } else {
        return -1; // Invalid
    }
}

// Log data to file
int log_data(float bpm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, bpm);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    sensor_config_t sensor_config;
    int heart_rate;
    float filtered_bpm;
    float bpm_history[MOVING_AVG_SIZE] = {0.0};
    int history_index = 0;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Initialize sensor
    if (init_sensor(&sensor_config) != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("heart_rate.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read heart rate
        if (read_heart_rate(&heart_rate) == 0) {
            // Apply moving average filter
            filtered_bpm = apply_moving_average(heart_rate, bpm_history, &history_index, MOVING_AVG_SIZE);

            // Validate BPM
            if (validate_bpm(filtered_bpm) == 0) {
                // Log data
                log_data(filtered_bpm);
                printf("Heart Rate: %.2f BPM\n", filtered_bpm);
            } else {
                fprintf(stderr, "Invalid BPM value: %.2f\n", filtered_bpm);
            }
        } else {
            fprintf(stderr, "Failed to read heart rate\n");
        }

        gpioDelay(1000000); // 1 second delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

