static volatile int running = 1;
static FILE *log_file = NULL;

// Function to get the current timestamp in ISO 8601 format
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[21]; // YYYY-MM-DDTHH:MM:SSZ\0

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log a message to the console and the log file
void log_message(const char *message) {
    char *timestamp = get_timestamp();
    printf("%s: %s\n", timestamp, message);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure the log is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_message("Received signal, shutting down...");
}

int main() {
    int last_state = 1; // Initialize to HIGH (no flame)
    int current_state;
    int result;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as an input with a pull-up resistor
    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP);

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    log_message("Flame sensor monitoring started.");

    // Main loop
    while (running) {
        current_state = gpioRead(FLAME_SENSOR_GPIO);

        if (current_state < 0) {
            fprintf(stderr, "Error reading GPIO %d\n", FLAME_SENSOR_GPIO);
            log_message("Error reading GPIO, exiting.");
            break;
        }

        // Detect falling edge (LOW signal)
        if (current_state == 0 && last_state == 1) {
            log_message("FLAME DETECTED");
            last_state = 0; // Update last state
        } else if (current_state == 1) {
            last_state = 1; // Update last state if no flame
        }

        gpioDelay(100); // Poll every 100ms
    }

    // Cleanup
    log_message("Cleaning up...");
    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    log_message("Flame sensor monitoring stopped.");

    return 0;
}

