    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    log_message("Flame sensor monitoring started.");

    // Main loop
    while (running) {
        current_state = gpioRead(FLAME_SENSOR_GPIO);

        if (current_state < 0) {
            fprintf(stderr, "Error reading GPIO %d\n", FLAME_SENSOR_GPIO);
            log_message("Error reading GPIO, exiting.");
            break;
        }

        // Detect falling edge (LOW signal)
        if (current_state == 0 && last_state == 1) {
            log_message("FLAME DETECTED");
            last_state = 0; // Update last state
        } else if (current_state == 1) {
            last_state = 1; // Update last state if no flame
        }

        gpioDelay(100); // Poll every 100ms
    }

    // Cleanup
    log_message("Cleaning up...");
    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    log_message("Flame sensor monitoring stopped.");

    return 0;
}

