#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define SENSOR_START_PIN 5
#define SENSOR_END_PIN 12
#define COUNTER_START_PIN 17
#define COUNTER_END_PIN 24

// Define constants
#define NUM_CHANNELS 8
#define STABILIZATION_DELAY_MS 200
#define POLLING_INTERVAL_MS 10
#define LOG_FILE "touch_log.txt"

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *sensor_lines[NUM_CHANNELS];
static struct gpiod_line *counter_lines[NUM_CHANNELS];
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio(void);
int read_sensor(int channel);
int increment_counter(int *counter);
int write_counter(int counter);
int log_event(int channel, int counter);
void signal_handler(int sig);
void cleanup(void);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal %d, terminating...\n", sig);
        terminate = 1;
    }
}

// Function to initialize GPIO lines
int initialize_gpio(void) {
    int i;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Request sensor lines as input with pull-down resistors
    for (i = 0; i < NUM_CHANNELS; i++) {
        sensor_lines[i] = gpiod_chip_get_line(chip, SENSOR_START_PIN + i);
        if (!sensor_lines[i]) {
            perror("Error getting sensor line");
            cleanup();
            return -1;
        }

        if (gpiod_line_request_input(sensor_lines[i], "touch_counter") < 0) {
            perror("Error requesting sensor line as input");
            cleanup();
            return -1;
        }
    }

    // Request counter lines as output
    for (i = 0; i < NUM_CHANNELS; i++) {
        counter_lines[i] = gpiod_chip_get_line(chip, COUNTER_START_PIN + i);
        if (!counter_lines[i]) {
            perror("Error getting counter line");
            cleanup();
            return -1;
        }

        if (gpiod_line_request_output(counter_lines[i], "touch_counter", 0) < 0) {
            perror("Error requesting counter line as output");
            cleanup();
            return -1;
        }
    }

    return 0;
}

// Function to read sensor value
int read_sensor(int channel) {
    if (channel < 0 || channel >= NUM_CHANNELS) {
        fprintf(stderr, "Error: Invalid sensor channel %d\n", channel);
        return -1;
    }

    int value = gpiod_line_get_value(sensor_lines[channel]);
    if (value < 0) {
        perror("Error reading sensor value");
        return -1;
    }

    return value;
}

// Function to increment the counter
int increment_counter(int *counter) {
    if (counter == NULL) {
        fprintf(stderr, "Error: Counter pointer is NULL\n");
        return -1;
    }

    (*counter)++;
    if (*counter > 255) {
        *counter = 0;
    }

    return 0;
}

// Function to write the counter value to the output pins
int write_counter(int counter) {
    int i;
    int bit;

    for (i = 0; i < NUM_CHANNELS; i++) {
        bit = (counter >> i) & 1;
        if (gpiod_line_set_value(counter_lines[i], bit) < 0) {
            perror("Error writing to counter line");
            return -1;
        }
    }

    return 0;
}

// Function to log the event to a file
int log_event(int channel, int counter) {
    FILE *fp;
    time_t t;
    struct tm tm_info;
    char timestamp[30];

    // Get current time
    time(&t);
    localtime_r(&t, &tm_info);

    // Format timestamp in ISO 8601 format
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm_info);

    // Open log file in append mode
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        fprintf(stderr, "Warning: Could not open log file, logging to stderr instead.\n");
        fprintf(stderr, "%s, Channel: %d, Counter: %d\n", timestamp, channel, counter);
        return -1;
    }

    // Write log entry
    fprintf(fp, "%s, Channel: %d, Counter: %d\n", timestamp, channel, counter);

    // Close log file
    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1;
    }

    return 0;
}

// Function to clean up GPIO resources
void cleanup(void) {
    int i;

    // Release sensor lines
    for (i = 0; i < NUM_CHANNELS; i++) {
        if (sensor_lines[i]) {
            gpiod_line_release(sensor_lines[i]);
        }
    }

    // Release counter lines
    for (i = 0; i < NUM_CHANNELS; i++) {
        if (counter_lines[i]) {
            gpiod_line_release(counter_lines[i]);
        }
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void) {
    int i, sensor_value, counter = 0;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Stabilization delay
    struct timespec delay;
    delay.tv_sec = 0;
    delay.tv_nsec = STABILIZATION_DELAY_MS * 1000000; // Convert milliseconds to nanoseconds
    nanosleep(&delay, NULL);

    printf("Touch counter started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        for (i = 0; i < NUM_CHANNELS; i++) {
            sensor_value = read_sensor(i);
            if (sensor_value < 0) {
                fprintf(stderr, "Error reading sensor %d, skipping.\n", i + 1);
                continue; // Skip to the next channel
            }

            if (sensor_value == 1) {
                // Rising edge detected
                if (increment_counter(&counter) < 0) {
                    fprintf(stderr, "Error incrementing counter.\n");
                }

                if (write_counter(counter) < 0) {
                    fprintf(stderr, "Error writing counter to output pins.\n");
                }

                if (log_event(i + 1, counter) < 0) {
                    fprintf(stderr, "Error logging event.\n");
                }

                printf("Touch on channel %d | Counter: %d\n", i + 1, counter);
            }
        }

        // Polling interval
        delay.tv_sec = 0;
        delay.tv_nsec = POLLING_INTERVAL_MS * 1000000; // Convert milliseconds to nanoseconds
        nanosleep(&delay, NULL);
    }

    // Cleanup and exit
    cleanup();
    printf("Touch counter stopped.\n");
    return 0;
}

