// Define GPIO pins for the sensors
#define SENSOR1_PIN 17
#define SENSOR2_PIN 18
#define SENSOR3_PIN 27
#define SENSOR4_PIN 22

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int sensor1;
    int sensor2;
    int sensor3;
    int sensor4;
} SensorData;

// Function prototypes
int initialize_gpio();
SensorData read_sensors();
char* get_timestamp();
int write_to_csv(char *timestamp, SensorData data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to initialize the pigpio library and set GPIO pins as inputs
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetMode(SENSOR3_PIN, PI_INPUT);
    gpioSetMode(SENSOR4_PIN, PI_INPUT);

    return 0;
}

// Function to read the sensor values
SensorData read_sensors() {
    SensorData data;
    data.sensor1 = gpioRead(SENSOR1_PIN);
    data.sensor2 = gpioRead(SENSOR2_PIN);
    data.sensor3 = gpioRead(SENSOR3_PIN);
    data.sensor4 = gpioRead(SENSOR4_PIN);

    if (data.sensor1 < 0 || data.sensor2 < 0 || data.sensor3 < 0 || data.sensor4 < 0) {
        fprintf(stderr, "Error reading sensor values\n");
        // Return default values in case of error
        data.sensor1 = -1;
        data.sensor2 = -1;
        data.sensor3 = -1;
        data.sensor4 = -1;
    }

    return data;
}

// Function to get the current timestamp in ISO 8601 format
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(21 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        fprintf(stderr, "Memory allocation failed for timestamp\n");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 21, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to write the timestamp and sensor data to the CSV file
int write_to_csv(char *timestamp, SensorData data) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return 1;
    }

    fprintf(log_file, "%s,%d,%d,%d,%d\n", timestamp, data.sensor1, data.sensor2, data.sensor3, data.sensor4);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

