    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the CSV file in append mode
    log_file = fopen("tracking_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening tracking_log.csv\n");
        cleanup();
        return 1;
    }

    // Write the header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,sensor1,sensor2,sensor3,sensor4\n");
        fflush(log_file);
    }

    // Main loop
    while (!terminate) {
        // Read sensor values
        SensorData sensor_data = read_sensors();

        // Get the current timestamp
        char *timestamp = get_timestamp();
        if (timestamp == NULL) {
            fprintf(stderr, "Failed to get timestamp, skipping logging\n");
            gpioDelay(100); // Delay before next iteration
            continue;
        }

        // Write the data to the CSV file
        if (write_to_csv(timestamp, sensor_data) != 0) {
            fprintf(stderr, "Failed to write to CSV file\n");
        }

        free(timestamp); // Free the allocated memory

        // Delay for 100 milliseconds
        gpioDelay(100);
    }

    // Perform cleanup before exiting
    cleanup();

    return 0;
}

