#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define SENSOR1_PIN 17
#define SENSOR2_PIN 27
#define LED_PIN 22

// Define log file name
#define LOG_FILE "obstacle_log.csv"

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int read_sensor(int gpio_pin);
int control_led(int gpio_pin, int state);
int log_data(FILE *fp, int sensor1_value, int sensor2_value, int led_state);
void signal_handler(int signal);

// Function to read sensor value
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor on GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate error
    }
    return value;
}

// Function to control LED state
int control_led(int gpio_pin, int state) {
    int result = gpioWrite(gpio_pin, state);
    if (result < 0) {
        fprintf(stderr, "Error writing to LED on GPIO %d: %d\n", gpio_pin, result);
        return -1; // Indicate error
    }
    return 0;
}

// Function to log data to file
int log_data(FILE *fp, int sensor1_value, int sensor2_value, int led_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, sensor1_value, sensor2_value, led_state) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1; // Indicate error
    }

    fflush(fp); // Flush the buffer to ensure data is written immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Obstacle detection program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR1_PIN);
        int sensor2_value = read_sensor(SENSOR2_PIN);

        if (sensor1_value == -1 || sensor2_value == -1) {
            fprintf(stderr, "Error reading sensors, skipping this iteration.\n");
            gpioDelay(100); // Wait 100ms before next iteration
            continue;
        }

        // Control LED based on sensor values
        int led_state = (sensor1_value == 0 && sensor2_value == 0) ? 1 : 0;
        if (control_led(LED_PIN, led_state) != 0) {
            fprintf(stderr, "Error controlling LED, skipping this iteration.\n");
        }

        // Log data
        if (log_data(log_file, sensor1_value, sensor2_value, led_state) != 0) {
            fprintf(stderr, "Error logging data, skipping this iteration.\n");
        }

        // Wait 100ms
        gpioDelay(100);
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_led(LED_PIN, 0); // Turn off LED
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

