#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define MIC_PIN 4
#define LED_PIN 17

// Define sampling period (125 us)
#define SAMPLE_PERIOD_US 125

// Define LED on time (100 ms)
#define LED_ON_TIME_MS 100

// Global flag for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to initialize the pigpio library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to configure GPIO pins
int configure_gpio() {
    if (gpioSetMode(MIC_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set MIC_PIN as input\n");
        return -1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED_PIN as output\n");
        return -1;
    }
    return 0;
}

// Function to read the microphone pin
int read_microphone() {
    return gpioRead(MIC_PIN);
}

// Function to get the current timestamp in milliseconds
long long get_timestamp_ms() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return (long long)(ts.tv_sec * 1000LL + ts.tv_nsec / 1000000LL);
}

// Function to turn the LED on
int turn_led_on() {
    if (gpioWrite(LED_PIN, 1) != 0) {
        fprintf(stderr, "Failed to turn LED on\n");
        return -1;
    }
    return 0;
}

// Function to turn the LED off
int turn_led_off() {
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Failed to turn LED off\n");
        return -1;
    }
    return 0;
}

// Function to handle a sound peak event
void handle_sound_peak() {
    long long timestamp = get_timestamp_ms();
    printf("%lld\n", timestamp);
    if (turn_led_on() != 0) {
        fprintf(stderr, "Failed to turn LED on during peak event\n");
    }
    gpioDelay(LED_ON_TIME_MS * 1000); // Delay for 100 ms
    if (turn_led_off() != 0) {
        fprintf(stderr, "Failed to turn LED off during peak event\n");
    }
}

// Function to clean up GPIO resources
void cleanup_gpio() {
    gpioWrite(LED_PIN, 0); // Ensure LED is off
    gpioTerminate();
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Configure GPIO pins
    if (configure_gpio() != 0) {
        cleanup_gpio();
        return 1;
    }

    fprintf(stderr, "Audio sampling started. Press Ctrl+C to terminate.\n");

    // Main loop
    while (!terminate) {
        int mic_value = read_microphone();
        if (mic_value == 1) {
            handle_sound_peak();
        }
        gpioDelay(SAMPLE_PERIOD_US); // Delay for 125 us
    }

    // Clean up GPIO resources
    cleanup_gpio();

    fprintf(stderr, "Audio sampling stopped.\n");

    return 0;
}

