// Define GPIO pins for the IR reflectance sensors
#define LEFT_SENSOR_PIN 17
#define CENTER_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN 22

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the state of an IR reflectance sensor
int read_sensor(int gpio_pin) {
    int sensor_value = gpioRead(gpio_pin);
    if (sensor_value < 0) {
        fprintf(stderr, "Error reading sensor on GPIO %d: %d\n", gpio_pin, sensor_value);
        return -1; // Indicate an error
    }
    return sensor_value;
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins as inputs with pull-up resistors
    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP);

    gpioSetMode(CENTER_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(CENTER_SENSOR_PIN, PI_PUD_UP);

    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP);

    printf("IR Reflectance Sensor Reader\n");

