#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Si1175 I2C address
#define SI1175_ADDR 0x60

// Si1175 register addresses
#define REG_ALS_VIS_DATA0 0x22
#define REG_ALS_VIS_DATA1 0x23

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t als_value;
} sensor_data_t;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCtrl+C pressed. Exiting gracefully...\n");
}

// Function to initialize the Si1175 sensor
int init_si1175() {
    // Reset the sensor (example initialization sequence)
    if (i2cWriteByteData(i2c_handle, 0x17, 0x00) < 0) { // Reset command
        fprintf(stderr, "Error: Failed to reset Si1175 sensor.\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Configure the sensor for ALS measurement (example configuration)
    if (i2cWriteByteData(i2c_handle, 0x02, 0x01) < 0) { // Enable ALS
        fprintf(stderr, "Error: Failed to enable ALS.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x03, 0x00) < 0) { // ALS integration time
        fprintf(stderr, "Error: Failed to set ALS integration time.\n");
        return -1;
    }

    return 0;
}

// Function to read ALS data from the Si1175 sensor
int read_als_data(sensor_data_t *data) {
    uint8_t lsb, msb;

    lsb = i2cReadByteData(i2c_handle, REG_ALS_VIS_DATA0);
    if (lsb < 0) {
        fprintf(stderr, "Error: Failed to read LSB of ALS data.\n");
        return -1;
    }

    msb = i2cReadByteData(i2c_handle, REG_ALS_VIS_DATA1);
    if (msb < 0) {
        fprintf(stderr, "Error: Failed to read MSB of ALS data.\n");
        return -1;
    }

    data->als_value = (msb << 8) | lsb;
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1175_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus. Error code: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the Si1175 sensor
    if (init_si1175() < 0) {
        fprintf(stderr, "Error: Si1175 initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read ALS data
        if (read_als_data(&sensor_data) == 0) {
            // Log the raw sensor reading
            printf("ALS Value: %u\n", sensor_data.als_value);
        } else {
            fprintf(stderr, "Error: Failed to read ALS data.\n");
        }

        // Wait for 100 milliseconds
        gpioDelay(100);
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

