#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the TTP226 channels
#define TP1_PIN 5
#define TP2_PIN 6
#define TP3_PIN 13
#define TP4_PIN 19
#define TP5_PIN 26
#define TP6_PIN 12
#define TP7_PIN 16
#define TP8_PIN 20

// Global variables for pigpio handles and program state
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Structure to hold GPIO pin configurations
typedef struct {
    int pin;
    int mode;
} gpio_config_t;

// Function prototypes
int initialize_gpio();
int read_touch_sensor(int channel);
void process_touch_data(int *channel_values);
void output_data(double timestamp, int *channel_values);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    gpio_config_t gpio_configs[] = {
        {TP1_PIN, PI_INPUT},
        {TP2_PIN, PI_INPUT},
        {TP3_PIN, PI_INPUT},
        {TP4_PIN, PI_INPUT},
        {TP5_PIN, PI_INPUT},
        {TP6_PIN, PI_INPUT},
        {TP7_PIN, PI_INPUT},
        {TP8_PIN, PI_INPUT}
    };
    int num_configs = sizeof(gpio_configs) / sizeof(gpio_configs[0]);

    for (int i = 0; i < num_configs; i++) {
        if (gpioSetMode(gpio_configs[i].pin, gpio_configs[i].mode) != 0) {
            fprintf(stderr, "Error setting mode for GPIO %d\n", gpio_configs[i].pin);
            return -1;
        }
    }
    return 0;
}

// Function to read the state of a single touch sensor channel
int read_touch_sensor(int channel) {
    int pin;

    switch (channel) {
        case 1: pin = TP1_PIN; break;
        case 2: pin = TP2_PIN; break;
        case 3: pin = TP3_PIN; break;
        case 4: pin = TP4_PIN; break;
        case 5: pin = TP5_PIN; break;
        case 6: pin = TP6_PIN; break;
        case 7: pin = TP7_PIN; break;
        case 8: pin = TP8_PIN; break;
        default:
            fprintf(stderr, "Invalid channel number: %d\n", channel);
            return -1;
    }

    return gpioRead(pin);
}

// Function to process the raw sensor data and determine if a channel is touched
void process_touch_data(int *channel_values) {
    for (int i = 0; i < 8; i++) {
        int value = read_touch_sensor(i + 1);
        if (value < 0) {
            fprintf(stderr, "Error reading channel %d\n", i + 1);
            channel_values[i] = -1; // Indicate an error
        } else {
            channel_values[i] = value;
        }
    }
}

// Function to output the timestamp and touch sensor data to the console
void output_data(double timestamp, int *channel_values) {
    printf("[%.3fs] CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d\n",
           timestamp, channel_values[0], channel_values[1], channel_values[2],
           channel_values[3], channel_values[4], channel_values[5],
           channel_values[6], channel_values[7]);
}

// Function to cleanup resources before exiting
void cleanup() {
    gpioTerminate();
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize GPIO pins
    if (initialize_gpio() != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (program_running) {
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        double timestamp = ts.tv_sec + ts.tv_nsec / 1000000000.0;

        int channel_values[8];
        process_touch_data(channel_values);

        output_data(timestamp, channel_values);

        gpioDelay(200); // Poll every 200ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

