    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(RED_PIN, PWM_RANGE);
    gpioSetPWMrange(GREEN_PIN, PWM_RANGE);
    gpioSetPWMrange(BLUE_PIN, PWM_RANGE);

    syslog(LOG_INFO, "GPIO initialized successfully");
    return 0;
}

// Function to set the RGB LED color using PWM
void set_led_color(RGBColor color) {
    // Common anode, so invert the color values
    gpioPWM(RED_PIN, PWM_RANGE - color.red);
    gpioPWM(GREEN_PIN, PWM_RANGE - color.green);
    gpioPWM(BLUE_PIN, PWM_RANGE - color.blue);
}

// Function to convert HSV color to RGB color
RGBColor hsv_to_rgb(float hue, float saturation, float value) {
    RGBColor rgb;
    float h = hue;
    float s = saturation;
    float v = value;

    if (s == 0.0) {
        rgb.red = rgb.green = rgb.blue = v * PWM_RANGE;
        return rgb;
    }

    h = h / 60.0;
    int i = (int)h;
    float f = h - i;
    float p = v * (1 - s);
    float q = v * (1 - s * f);
    float t = v * (1 - s * (1 - f));

    switch (i) {
        case 0:
            rgb.red = v * PWM_RANGE;
            rgb.green = t * PWM_RANGE;
            rgb.blue = p * PWM_RANGE;
            break;
        case 1:
            rgb.red = q * PWM_RANGE;
            rgb.green = v * PWM_RANGE;
            rgb.blue = p * PWM_RANGE;
            break;
        case 2:
            rgb.red = p * PWM_RANGE;
            rgb.green = v * PWM_RANGE;
            rgb.blue = t * PWM_RANGE;
            break;
        case 3:
            rgb.red = p * PWM_RANGE;
            rgb.green = q * PWM_RANGE;
            rgb.blue = v * PWM_RANGE;
