    float hue = (float)(rand() % 360);
    float saturation = 1.0; // Full saturation
    float value = 1.0;    // Full brightness

    return hsv_to_rgb(hue, saturation, value);
}

// Function to interpolate between two RGB colors
RGBColor interpolate_color(RGBColor start_color, RGBColor end_color, int step) {
    RGBColor interpolated_color;

    // Linear interpolation for each channel
    float red_diff = (float)(end_color.red - start_color.red) / NUM_STEPS;
    float green_diff = (float)(end_color.green - start_color.green) / NUM_STEPS;
