    interpolated_color.green = start_color.green + (int)(green_diff * step);
    interpolated_color.blue = start_color.blue + (int)(blue_diff * step);

    // Clamp values to 0-255 range
    if (interpolated_color.red < 0) interpolated_color.red = 0;
    if (interpolated_color.red > PWM_RANGE) interpolated_color.red = PWM_RANGE;
    if (interpolated_color.green < 0) interpolated_color.green = 0;
    if (interpolated_color.green > PWM_RANGE) interpolated_color.green = PWM_RANGE;
    if (interpolated_color.blue < 0) interpolated_color.blue = 0;
    if (interpolated_color.blue > PWM_RANGE) interpolated_color.blue = PWM_RANGE;

    return interpolated_color;
}

