        RGBColor start_color = generate_random_hue();
        RGBColor end_color = generate_random_hue();

        // Fade between the two colors
        for (int step = 0; step <= NUM_STEPS; step++) {
            RGBColor interpolated_color = interpolate_color(start_color, end_color, step);
            set_led_color(interpolated_color);
            gpioDelay((int)(FADE_DURATION * 1000000 / NUM_STEPS)); // Delay for each step
        }
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

