#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <pigpio.h>

// TCS34725 Registers
#define TCS34725_ADDRESS         (0x29)
#define TCS34725_COMMAND_BIT     (0x80)
#define TCS34725_ENABLE          (0x00)
#define TCS34725_ATIME           (0x01)
#define TCS34725_CONTROL         (0x0F)
#define TCS34725_CDATA           (0x14)
#define TCS34725_RDATA           (0x16)
#define TCS34725_GDATA           (0x18)
#define TCS34725_BDATA           (0x1A)

// GPIO Pin for LED
#define LED_PIN                 (17)

// Red Threshold
#define RED_THRESHOLD           (200)

// Integration Time (154ms)
#define INTEGRATION_TIME        (0xD5) // 154ms

// Global Variables
int i2c_fd;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_byte(int fd, uint8_t reg, uint8_t data);
int tcs34725_init(int fd);
int tcs34725_read_raw_data(int fd, uint16_t *r, uint16_t *g, uint16_t *b, uint16_t *c);
int tcs34725_calibrate_data(uint16_t r, uint16_t g, uint16_t b, uint16_t c, float *calibrated_r, float *calibrated_g, float *calibrated_b, float *calibrated_c);
void led_on(int pin);
void led_off(int pin);
void signal_handler(int sig);

// I2C Read Function
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, data, len) != len) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// I2C Write Function
int i2c_write_byte(int fd, uint8_t reg, uint8_t data) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = data;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// TCS34725 Initialization Function
int tcs34725_init(int fd) {
    // Enable power and RGBC
    if (i2c_write_byte(fd, TCS34725_COMMAND_BIT | TCS34725_ENABLE, 0x03) != 0) {
        fprintf(stderr, "Error enabling TCS34725\n");
        return -1;
    }

    // Set integration time
    if (i2c_write_byte(fd, TCS34725_COMMAND_BIT | TCS34725_ATIME, INTEGRATION_TIME) != 0) {
        fprintf(stderr, "Error setting integration time\n");
        return -1;
    }

    // Set gain (optional, default is 1x)
    if (i2c_write_byte(fd, TCS34725_COMMAND_BIT | TCS34725_CONTROL, 0x00) != 0) {
        fprintf(stderr, "Error setting gain\n");
        return -1;
    }

    return 0;
}

// TCS34725 Read Raw Data Function
int tcs34725_read_raw_data(int fd, uint16_t *r, uint16_t *g, uint16_t *b, uint16_t *c) {
    uint8_t data[8];

    if (i2c_read_bytes(fd, TCS34725_COMMAND_BIT | TCS34725_CDATA, data, 8) != 0) {
        fprintf(stderr, "Error reading raw data\n");
        return -1;
    }

    *c = (data[1] << 8) | data[0];
    *r = (data[3] << 8) | data[2];
    *g = (data[5] << 8) | data[4];
    *b = (data[7] << 8) | data[6];

    return 0;
}

// TCS34725 Calibrate Data Function
int tcs34725_calibrate_data(uint16_t r, uint16_t g, uint16_t b, uint16_t c, float *calibrated_r, float *calibrated_g, float *calibrated_b, float *calibrated_c) {
    // Simple calibration (adjust as needed)
    *calibrated_r = (float)r / (float)c * 255.0;
    *calibrated_g = (float)g / (float)c * 255.0;
    *calibrated_b = (float)b / (float)c * 255.0;
    *calibrated_c = (float)c;

    // Clamp values to 0-255
    if (*calibrated_r > 255.0) *calibrated_r = 255.0;
    if (*calibrated_g > 255.0) *calibrated_g = 255.0;
    if (*calibrated_b > 255.0) *calibrated_b = 255.0;
    if (*calibrated_c > 255.0) *calibrated_c = 255.0;

    return 0;
}

// LED On Function
void led_on(int pin) {
    gpioWrite(pin, 1);
}

// LED Off Function
void led_off(int pin) {
    gpioWrite(pin, 0);
}

// Signal Handler Function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize TCS34725 sensor
    if (tcs34725_init(i2c_fd) != 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    uint16_t raw_r, raw_g, raw_b, raw_c;
    float calibrated_r, calibrated_g, calibrated_b, calibrated_c;

    // Main loop
    while (!terminate) {
        // Read raw data
        if (tcs34725_read_raw_data(i2c_fd, &raw_r, &raw_g, &raw_b, &raw_c) == 0) {
            // Calibrate data
            if (tcs34725_calibrate_data(raw_r, raw_g, raw_b, raw_c, &calibrated_r, &calibrated_g, &calibrated_b, &calibrated_c) == 0) {
                // Print calibrated data
                printf("R: %.2f, G: %.2f, B: %.2f, C: %.2f\n", calibrated_r, calibrated_g, calibrated_b, calibrated_c);

                // Control LED based on red value
                if (calibrated_r > RED_THRESHOLD) {
                    led_on(LED_PIN);
                } else {
                    led_off(LED_PIN);
                }
            } else {
                fprintf(stderr, "Error calibrating data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data, re-initializing...\n");
            // Attempt to re-initialize the sensor
            close(i2c_fd);
            i2c_fd = open("/dev/i2c-1", O_RDWR);
            if (i2c_fd < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %s\n", strerror(errno));
                terminate = 1; // Exit loop if re-initialization fails
            } else {
                if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
                    fprintf(stderr, "Error re-setting I2C slave address: %s\n", strerror(errno));
                    close(i2c_fd);
                    terminate = 1;
                } else {
                    if (tcs34725_init(i2c_fd) != 0) {
                        fprintf(stderr, "TCS34725 re-initialization failed\n");
                        close(i2c_fd);
                        terminate = 1;
                    }
                }
            }
        }

        // Delay for 200ms
        gpioDelay(200000); // 200ms = 200000 microseconds
    }

    // Cleanup
    close(i2c_fd);
    led_off(LED_PIN);
    gpioTerminate();

    return 0;
}

