#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <math.h>
#include <pigpio.h>

// Constants
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define GPIO_PIN 18
#define NUM_LEDS 10
#define I2C_BUS 1
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_bh1750(float *lux);
int map_lux_to_brightness(float lux, uint8_t *brightness);
void set_led_brightness(uint8_t brightness);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read lux value from BH1750
int read_bh1750(float *lux) {
    int retries = 0;
    int result;
    uint8_t buffer[2];

    while (retries < MAX_RETRIES) {
        result = i2cWriteByte(i2c_handle, CONTINUOUS_HIGH_RES_MODE);
        if (result != 0) {
            fprintf(stderr, "Error writing to I2C (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        gpioDelay(180000); // Wait 180ms

        result = i2cReadDevice(i2c_handle, (char *)buffer, 2);
        if (result != 2) {
            fprintf(stderr, "Error reading from I2C (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        uint16_t raw_value = (buffer[0] << 8) | buffer[1];
        *lux = (float)raw_value / 1.2;
        return 0; // Success
    }

    fprintf(stderr, "Failed to read BH1750 after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Map lux value to brightness level (0-255)
int map_lux_to_brightness(float lux, uint8_t *brightness) {
    // Logarithmic mapping
    float log_lux = log10(lux + 1); // Add 1 to avoid log(0)
    float normalized_lux = log_lux / log10(1000); // Normalize to 0-1 range (adjust max lux as needed)

    if (normalized_lux < 0) normalized_lux = 0;
    if (normalized_lux > 1) normalized_lux = 1;

    *brightness = (uint8_t)(normalized_lux * 255);
    return 0;
}

// Set LED brightness using PWM/wave
void set_led_brightness(uint8_t brightness) {
    gpioWaveClear();

    gpioPulse_t pulse[NUM_LEDS * 2]; // 2 pulses per LED (mark, space)
    int pulse_index = 0;

    // Generate PWM signal for each LED
    for (int i = 0; i < NUM_LEDS; i++) {
        // Mark pulse (data bit 1)
        pulse[pulse_index].gpioOn = (1 << GPIO_PIN);
        pulse[pulse_index].gpioOff = 0;
        pulse[pulse_index].usDelay = 0.8; // 0.8us for mark
        pulse_index++;

        // Space pulse (data bit 0)
        pulse[pulse_index].gpioOn = 0;
        pulse[pulse_index].gpioOff = (1 << GPIO_PIN);
        pulse[pulse_index].usDelay = 0.45; // 0.45us for space (adjust for brightness)
        pulse_index++;

        // Adjust space pulse delay based on brightness (example)
        pulse[pulse_index - 1].usDelay = 0.8 + (0.45 * (255 - brightness) / 255.0); // Invert brightness for space
    }

    gpioWaveAddGeneric(pulse_index, pulse);
    int wave_id = gpioWaveCreate();

    if (wave_id >= 0) {
        gpioWaveTxSend(wave_id, PI_WAVE_MODE_REPEAT); // Send wave continuously
        gpioWaveDelete(wave_id);
    } else {
        fprintf(stderr, "Error creating wave: %d\n", wave_id);
    }
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioWaveTxStop();
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float lux;
    uint8_t brightness;

    printf("Starting ambient light sensor and LED control...\n");

    while (!terminate) {
        // Read lux value
        if (read_bh1750(&lux) == 0) {
            printf("Lux: %.2f\n", lux);

            // Map lux to brightness
            if (map_lux_to_brightness(lux, &brightness) == 0) {
                printf("Brightness: %d\n", brightness);

                // Set LED brightness
                set_led_brightness(brightness);
            } else {
                fprintf(stderr, "Error mapping lux to brightness.\n");
            }
        } else {
            fprintf(stderr, "Error reading lux value.\n");
        }

        gpioDelay(100000); // Delay 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

