#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

// Configuration
#define NUM_LEDS 10
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000 // 1 MHz
#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY_MS 10

// Global variables
int spi_fd = -1;
int i2c_fd = -1;
volatile sig_atomic_t terminate = 0;

// Structure for APA102 LED data
typedef struct {
    uint8_t start_frame[4];
    uint8_t led_data[NUM_LEDS * 4];
    uint8_t end_frame[4];
} apa102_data_t;

// Function prototypes
int init_i2c(const char *bus);
int init_spi(const char *device, uint32_t speed);
int read_bh1750(int fd);
int scale_brightness(int lux);
int set_apa102_led(apa102_data_t *data, int led_index, uint8_t brightness);
int send_apa102_data(int fd, const apa102_data_t *data);
void signal_handler(int sig);
void cleanup();

// I2C initialization function
int init_i2c(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI initialization function
int init_spi(const char *device, uint32_t speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    uint8_t mode = 0; // SPI mode 0
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    uint8_t bits = 8; // 8 bits per word
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Error setting SPI bits per word");
        close(fd);
        return -1;
    }

    uint32_t spi_speed = speed;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &spi_speed) < 0) {
        perror("Error setting SPI max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// BH1750 reading function with retry
int read_bh1750(int fd) {
    uint8_t config = BH1750_CONTINUOUS_HIGH_RES_MODE;
    int lux = -1;
    int retries = I2C_RETRY_COUNT;

    while (retries > 0) {
        if (write(fd, &config, 1) == 1) {
            usleep(180000); // Wait for measurement (at least 180ms)

            uint8_t buffer[2];
            if (read(fd, buffer, 2) == 2) {
                lux = (buffer[0] << 8) | buffer[1];
                return lux;
            } else {
                perror("Error reading BH1750 data");
            }
        } else {
            perror("Error writing BH1750 config");
        }

        retries--;
        usleep(I2C_RETRY_DELAY_MS * 1000); // Exponential backoff
    }

    fprintf(stderr, "Failed to read BH1750 after %d retries\n", I2C_RETRY_COUNT);
    return -1;
}

// Brightness scaling function
int scale_brightness(int lux) {
    if (lux < 0) return 0;
    if (lux > 1000) return 255; // Cap at 1000 lux
    return (int)(((float)lux / 1000.0) * 255.0);
}

// APA102 LED setting function
int set_apa102_led(apa102_data_t *data, int led_index, uint8_t brightness) {
    if (led_index < 0 || led_index >= NUM_LEDS) {
        fprintf(stderr, "Invalid LED index: %d\n", led_index);
        return -1;
    }

    int offset = led_index * 4;
    data->led_data[offset + 0] = 0xE0 | brightness; // Global brightness (0xE0-0xFF)
    data->led_data[offset + 1] = 0x00; // Blue
    data->led_data[offset + 2] = 0x00; // Green
    data->led_data[offset + 3] = 0x00; // Red

    return 0;
}

// APA102 data sending function
int send_apa102_data(int fd, const apa102_data_t *data) {
    uint8_t tx_buffer[4 + NUM_LEDS * 4 + 4];
    memcpy(tx_buffer, data->start_frame, 4);
    memcpy(tx_buffer + 4, data->led_data, NUM_LEDS * 4);
    memcpy(tx_buffer + 4 + NUM_LEDS * 4, data->end_frame, 4);

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buffer,
        .rx_buf = 0, // No receive data
        .len = sizeof(tx_buffer),
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0, // Delay after each transfer
        .cs_change = 0, // Keep CS active after transfer
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error sending SPI data");
        return -1;
    }

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to close file descriptors
void cleanup() {
    fprintf(stderr, "Cleaning up...\n");
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
}

int main() {
    // Initialize signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize SPI
    spi_fd = init_spi(SPI_DEVICE, SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Initialize APA102 data
    apa102_data_t apa102_data;
    memset(apa102_data.start_frame, 0x00, 4);
    memset(apa102_data.end_frame, 0xFF, 4);
    memset(apa102_data.led_data, 0x00, NUM_LEDS * 4);

    // Main loop
    while (!terminate) {
        // Read light level
        int lux = read_bh1750(i2c_fd);
        if (lux < 0) {
            fprintf(stderr, "Failed to read light level. Setting brightness to 0.\n");
            lux = 0; // Set lux to 0 to avoid further errors
        }

        // Scale brightness
        int brightness = scale_brightness(lux);

        // Set LED brightness
        for (int i = 0; i < NUM_LEDS; i++) {
            set_apa102_led(&apa102_data, i, brightness);
        }

        // Send data to APA102
        if (send_apa102_data(spi_fd, &apa102_data) < 0) {
            fprintf(stderr, "Failed to send APA102 data.\n");
        }

        // Delay
        usleep(50000); // 50ms
    }

    // Turn off LEDs before exiting
    memset(apa102_data.led_data, 0x00, NUM_LEDS * 4);
    send_apa102_data(spi_fd, &apa102_data);

    // Cleanup and exit
    cleanup();
    return 0;
}

