#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <wiringPiSPI.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

// Define sensor addresses
#define BH1750_ADDR_1 0x23
#define BH1750_ADDR_2 0x5C
#define BH1750_ADDR_3 0x46

// Define SPI channel and speed
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define APA102 GPIO pins (BCM numbering)
#define APA102_MOSI 10
#define APA102_SCLK 11

// Define number of LEDs in the strip
#define NUM_LEDS 30

// Define fade duration (ms)
#define FADE_DURATION 500

// Global variables
int bh1750_fds[3]; // File descriptors for I2C sensors
int spi_fd;        // File descriptor for SPI
volatile sig_atomic_t program_running = 1; // Flag to control the main loop

// Function prototypes
int init_bh1750(int address);
int read_bh1750(int fd);
float average_light_levels(int light_levels[], int num_sensors);
void set_apa102_brightness(int brightness);
void fade_brightness(int target_brightness);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize a BH1750 sensor
int init_bh1750(int address) {
    int fd = wiringPiI2CSetup(address);
    if (fd == -1) {
        fprintf(stderr, "Error initializing BH1750 sensor at address 0x%02X: %s\n", address, strerror(errno));
        return -1;
    }

    // Configure for continuous high-resolution mode
    if (wiringPiI2CWrite(fd, 0x10) == -1) {
        fprintf(stderr, "Error configuring BH1750 sensor at address 0x%02X: %s\n", address, strerror(errno));
        return -1;
    }

    return fd;
}

// Read light level from a BH1750 sensor
int read_bh1750(int fd) {
    int light_level = wiringPiI2CReadReg16(fd, 0x00);
    if (light_level == -1) {
        fprintf(stderr, "Error reading light level from BH1750: %s\n", strerror(errno));
        return -1;
    }

    // BH1750 returns big-endian data, so swap bytes
    light_level = (light_level >> 8) | (light_level << 8);

    return light_level;
}

// Average light levels from multiple sensors
float average_light_levels(int light_levels[], int num_sensors) {
    float sum = 0.0;
    int valid_count = 0;

    for (int i = 0; i < num_sensors; i++) {
        if (light_levels[i] != -1) {
            sum += light_levels[i];
            valid_count++;
        }
    }

    if (valid_count == 0) {
        return 0.0; // Return 0 if no valid readings
    }

    return sum / valid_count;
}

// Set APA102 LED strip brightness using SPI
void set_apa102_brightness(int brightness) {
    unsigned char data[4];
    data[0] = 0xE0 | (brightness & 0x1F); // Start frame (32 bits of 1)
    data[1] = 0x00; // Blue
    data[2] = 0x00; // Green
    data[3] = 0x00; // Red

    for (int i = 0; i < NUM_LEDS; i++) {
        wiringPiSPIDataRW(SPI_CHANNEL, data, 4);
    }

    data[0] = 0xFF; // End frame (at least (NUM_LEDS + 1) / 2 bytes of 0xFF)
    for (int i = 0; i < ((NUM_LEDS + 1) / 2); i++) {
        wiringPiSPIDataRW(SPI_CHANNEL, data, 4);
    }
}

// Fade brightness to a target value
void fade_brightness(int target_brightness) {
    int current_brightness = 0; // Start from 0 brightness
    int step = (target_brightness > current_brightness) ? 1 : -1;
    int delay_ms = FADE_DURATION / abs(target_brightness - current_brightness);

    while (current_brightness != target_brightness) {
        current_brightness += step;
        set_apa102_brightness(current_brightness);
        delay(delay_ms);
    }
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");

    // Turn off LED strip
    set_apa102_brightness(0);

    // Close I2C file descriptors
    for (int i = 0; i < 3; i++) {
        if (bh1750_fds[i] != -1) {
            close(bh1750_fds[i]);
        }
    }

    // Close SPI file descriptor
    close(spi_fd);

    // Reset wiringPi
    wiringPiSetup(); // Reinitialize to reset GPIO pins

    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Initialize SPI
    spi_fd = wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED);
    if (spi_fd == -1) {
        fprintf(stderr, "Error initializing SPI: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C sensors
    bh1750_fds[0] = init_bh1750(BH1750_ADDR_1);
    bh1750_fds[1] = init_bh1750(BH1750_ADDR_2);
    bh1750_fds[2] = init_bh1750(BH1750_ADDR_3);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int light_levels[3];

        // Read light levels from sensors
        for (int i = 0; i < 3; i++) {
            if (bh1750_fds[i] != -1) {
                light_levels[i] = read_bh1750(bh1750_fds[i]);
                if (light_levels[i] == -1) {
                    light_levels[i] = -1; // Mark as invalid
                }
            } else {
                light_levels[i] = -1; // Sensor not initialized, mark as invalid
            }
        }

        // Average light levels
        float average_light = average_light_levels(light_levels, 3);

        // Map average light level to brightness (0-31)
        int brightness = (int)(average_light / 100.0); // Adjust divisor as needed
        if (brightness < 0) brightness = 0;
        if (brightness > 31) brightness = 31;

        // Fade to the new brightness
        fade_brightness(brightness);

        // Wait 100ms
        delay(100);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

