#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define VEML7700_ADDR 0x48
#define ALS_CONF 0x00
#define ALS_DATA 0x04
#define GPIO_PIN 18
#define GAMMA 2.2
#define LUX_THRESHOLD 50.0
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100
#define WS2812B_TIMING_US 50 // Approximately 800kHz

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_veml7700();
int read_veml7700(float *lux);
int gamma_correct(float lux, uint8_t *brightness);
void set_led_brightness(uint8_t brightness);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize VEML7700 sensor
int init_veml7700() {
    int status;
    // Configure for continuous mode, integration time 100ms, gain 1/8
    uint16_t config_value = 0x0000; // ALS_EN = 1, ALS_IT = 100ms, ALS_GAIN = 1/8
    uint8_t config_data[2];

    config_data[0] = (config_value >> 8) & 0xFF;
    config_data[1] = config_value & 0xFF;

    status = i2cWriteI2CBlockData(i2c_handle, ALS_CONF, (char *)config_data, 2);
    if (status != 0) {
        fprintf(stderr, "Error writing to VEML7700 configuration register: %d\n", status);
        return -1;
    }

    return 0;
}

// Read ambient light data from VEML7700
int read_veml7700(float *lux) {
    int status;
    uint16_t raw_data;
    uint8_t data[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        status = i2cReadI2CBlockData(i2c_handle, ALS_DATA, (char *)data, 2);
        if (status == 2) {
            raw_data = (data[1] << 8) | data[0];
            *lux = (float)raw_data * 0.0576; // Conversion factor from datasheet
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading from VEML7700 data register: %d, retry %d\n", status, retries + 1);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }

    fprintf(stderr, "Failed to read VEML7700 data after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Gamma correction function
int gamma_correct(float lux, uint8_t *brightness) {
    float gamma_corrected_lux = pow(lux, 1.0 / GAMMA);
    *brightness = (uint8_t)(gamma_corrected_lux / 100.0 * 255.0); // Scale to 0-255
    if (*brightness > 255) *brightness = 255;
    return 0;
}

// Set LED brightness using bit-banging
void set_led_brightness(uint8_t brightness) {
    // Simple threshold-based on/off control
    if (brightness > 128) {
        gpioWrite(GPIO_PIN, 1); // LED on
    } else {
        gpioWrite(GPIO_PIN, 0); // LED off
    }
}

int main() {
    float lux;
    uint8_t brightness;
    int status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VEML7700 sensor
    if (init_veml7700() != 0) {
        fprintf(stderr, "VEML7700 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ambient light data
        if (read_veml7700(&lux) == 0) {
            // Gamma correct the lux value
            if (gamma_correct(lux, &brightness) == 0) {
                // Set LED brightness
                set_led_brightness(brightness);

