#define SELF_TEST_DURATION 1000 // milliseconds
#define FLAME_SENSOR_READ_INTERVAL 100 // milliseconds
#define BUZZER_DURATION 1000 // milliseconds
#define LED_ON_DURATION 100 // milliseconds
#define LED_OFF_DURATION 100 // milliseconds
#define ERROR_BLINK_DURATION 100 // milliseconds
#define ERROR_BLINK_INTERVAL 100 // milliseconds
#define ERROR_BLINK_CYCLES 5
#define ERROR_BUZZER_PATTERNS 3

// Global variables
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_flame_sensor();
void blink_led(int duration_ms);
void sound_buzzer(int duration_ms);
void self_test();
void log_event(const char *event_description);
void signal_handler(int signal);
void cleanup();

// Structure to hold buzzer pattern
typedef struct {
    int on_duration;
    int off_duration;
} BuzzerPattern;

// Function to play a buzzer pattern
void play_buzzer_pattern(BuzzerPattern *pattern, int num_patterns) {
    for (int i = 0; i < num_patterns; i++) {
        gpioWrite(BUZZER_PIN, 1); // Turn buzzer on
        gpioDelay(pattern[i].on_duration * 1000); // Delay in microseconds
        gpioWrite(BUZZER_PIN, 0); // Turn buzzer off
        gpioDelay(pattern[i].off_duration * 1000); // Delay in microseconds
    }
}

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("flame_sensor_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        cleanup();
        return 1;
    }

    // Perform self-test
    self_test();

    // Main loop
    while (program_running) {
        int flame_detected = read_flame_sensor();

        if (flame_detected == 0) {
            log_event("Flame detected!");
            gpioWrite(BUZZER_PIN, 1);
            gpioWrite(LED_PIN, 1);

            // Wait for flame to clear
            while (read_flame_sensor() == 0 && program_running) {
                gpioDelay(10000); // Check every 10ms
            }

            gpioWrite(BUZZER_PIN, 0);
            gpioWrite(LED_PIN, 0);
            log_event("Flame cleared.");
        } else if (flame_detected < 0) {
            fprintf(stderr, "Error reading flame sensor.\n");
        }

        gpioDelay(FLAME_SENSOR_READ_INTERVAL * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

