void blink_led(int duration_ms) {
    gpioWrite(LED_PIN, 1);
    gpioDelay(duration_ms * 1000); // Delay in microseconds
    gpioWrite(LED_PIN, 0);
    gpioDelay(duration_ms * 1000); // Delay in microseconds
}

// Sound buzzer for a specified duration
void sound_buzzer(int duration_ms) {
    gpioWrite(BUZZER_PIN, 1);
    gpioDelay(duration_ms * 1000); // Delay in microseconds
    gpioWrite(BUZZER_PIN, 0);
    gpioDelay(duration_ms * 1000); // Delay in microseconds
}

// Perform self-test
void self_test() {
    log_event("Starting self-test...");

    // LED blink test
    log_event("LED blink test...");
    for (int i = 0; i < 2; i++) {
        for (int j = 0; j < 5; j++) {
            blink_led(LED_ON_DURATION);
            gpioDelay(LED_OFF_DURATION * 1000); // Delay in microseconds
        }
        gpioDelay(500000); // Delay between blinks (0.5 seconds)
    }

    // Flame sensor test
    log_event("Flame sensor test...");
    int flame_detected_count = 0;
    for (int i = 0; i < 5; i++) {
        int sensor_value = read_flame_sensor();
        if (sensor_value == 0) {
            flame_detected_count++;
        }
        gpioDelay(100000); // Delay between reads (0.1 seconds)
    }

    if (flame_detected_count == 5) {
        log_event("Flame sensor test failed: persistent LOW detected.");
        fprintf(stderr, "Flame sensor test failed: persistent LOW detected.\n");

        // Error signal
        BuzzerPattern error_pattern[] = {{200, 200}, {200, 200}, {600, 200}, {200, 200}};
        for (int i = 0; i < ERROR_BUZZER_PATTERNS; i++) {
            play_buzzer_pattern(error_pattern, 4);
        }

        for (int i = 0; i < ERROR_BLINK_CYCLES; i++) {
            gpioWrite(LED_PIN, 1);
            gpioDelay(ERROR_BLINK_DURATION * 1000); // Delay in microseconds
            gpioWrite(LED_PIN, 0);
            gpioDelay(ERROR_BLINK_INTERVAL * 1000); // Delay in microseconds
        }

        cleanup();
        exit(1);
    } else {
        log_event("Flame sensor test passed.");
    }

    log_event("Self-test complete.");
}

// Log event to file
void log_event(const char *event_description) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s: %s\n", timestamp, event_description);
    fflush(log_file); // Ensure immediate write to file
    printf("%s: %s\n", timestamp, event_description); // Also print to console
}

// Signal handler for graceful shutdown
