    log_event("Received signal, shutting down...");
    program_running = 0;
}

// Cleanup GPIO resources
void cleanup() {
    log_event("Cleaning up GPIO resources...");
    gpioWrite(BUZZER_PIN, 0);
    gpioWrite(LED_PIN, 0);
    gpioTerminate();

    if (log_file != NULL) {
        fclose(log_file);
    }
}

