int buffer_count = 0;

// Function prototypes
int init_i2c();
int read_bh1750(float *lux);
void add_to_buffer(float lux);
float calculate_average();
void set_led_frequency(float average_lux);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    // Configure BH1750 for continuous high-resolution mode
    uint8_t config_data = CONTINUOUS_HIGH_RES_MODE;
    if (write(i2c_fd, &config_data, 1) != 1) {
        perror("Error writing to I2C device");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Read BH1750 sensor
int read_bh1750(float *lux) {
    uint8_t buffer[2];
    int result;

    result = read(i2c_fd, buffer, 2);
    if (result != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    uint16_t raw_value = (buffer[0] << 8) | buffer[1];
    *lux = (float)raw_value / 1.2;

    return 0;
}

// Add lux value to circular buffer
void add_to_buffer(float lux) {
    lux_buffer[buffer_index] = lux;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

// Calculate average lux value from circular buffer
float calculate_average() {
    if (buffer_count == 0) {
        return 0.0;
    }

    float sum = 0.0;
    for (int i = 0; i < buffer_count; i++) {
        sum += lux_buffer[i];
    }
    return sum / buffer_count;
}

// Set LED frequency based on average lux
void set_led_frequency(float average_lux) {
    float frequency;

    // Clamp lux value to defined range
    if (average_lux < MIN_LUX) {
        average_lux = MIN_LUX;
    } else if (average_lux > MAX_LUX) {
        average_lux = MAX_LUX;
    }

    // Map lux to frequency range
    frequency = MIN_FREQUENCY + (average_lux - MIN_LUX) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_LUX - MIN_LUX);

    // Set PWM frequency and duty cycle (50%)
    gpioSetPWMfrequency(GPIO_LED, (int)frequency);
    gpioPWM(GPIO_LED, 128); // 50% duty cycle
}

// Cleanup resources
void cleanup() {
    gpioPWM(GPIO_LED, 0); // Turn off LED
    gpioTerminate();       // Terminate pigpio
    close(i2c_fd);          // Close I2C file descriptor
}

int main() {
    float lux;
    float average_lux;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Starting ambient light monitoring...\n");

    while (!terminate) {
        // Read lux value from BH1750
        if (read_bh1750(&lux) == 0) {
            // Add lux value to circular buffer
            add_to_buffer(lux);

            // Calculate average lux value
            average_lux = calculate_average();

            // Set LED frequency
            set_led_frequency(average_lux);

            printf("Lux: %.2f, Average Lux: %.2f, Frequency: %.2f Hz\n", lux, average_lux, gpioGetPWMfrequency(GPIO_LED));
        } else {
            fprintf(stderr, "Failed to read lux value\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    printf("Program terminated.\n");
    return 0;
}

