#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define DATA_PIN 17
#define CLOCK_PIN 18
#define LATCH_PIN 27

// Define segment patterns for digits 0-9
const unsigned char digit_patterns[10] = {
    0x3F, // 0
    0x06, // 1
    0x5B, // 2
    0x4F, // 3
    0x66, // 4
    0x6D, // 5
    0x7D, // 6
    0x07, // 7
    0x7F, // 8
    0x6F  // 9
};

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to shift out data to the 74HC595
void shift_out(unsigned char data) {
    for (int i = 0; i < 8; i++) {
        // Set data pin based on the MSB of the data
        gpioWrite(DATA_PIN, (data >> 7) & 0x01);

        // Clock the data in
        gpioWrite(CLOCK_PIN, 1);
        gpioDelay(1); // Small delay for clock stability
        gpioWrite(CLOCK_PIN, 0);
        gpioDelay(1); // Small delay for clock stability

        // Shift the data to the next bit
        data <<= 1;
    }

    // Latch the data to the output
    gpioWrite(LATCH_PIN, 1);
    gpioDelay(1); // Small delay for latch stability
    gpioWrite(LATCH_PIN, 0);
    gpioDelay(1); // Small delay for latch stability
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(DATA_PIN, PI_OUTPUT);
    gpioSetMode(CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(LATCH_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("74HC595 shift register driver running. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Display digit '5'
        shift_out(digit_patterns[5]);
        gpioDelay(500); // 500ms on

        // Turn off display
        shift_out(0x00);
        gpioDelay(500); // 500ms off
    }

    // Clean up and terminate pigpio
    gpioWrite(DATA_PIN, 0);
    gpioWrite(CLOCK_PIN, 0);
    gpioWrite(LATCH_PIN, 0);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

