#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define LED_PIN 17
#define BUTTON_PIN 18

// Define chip number
#define CHIP_NUMBER 0

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to blink the LED
void blink_led(int led_pin, int chip_number) {
    while (program_running) {
        gpioWrite(led_pin, 1); // Turn LED on
        gpioDelay(1000000);    // Wait for 1 second (1000000 microseconds)
        gpioWrite(led_pin, 0); // Turn LED off
        gpioDelay(1000000);    // Wait for 1 second
    }
}

// Function to handle button press
void button_press_handler(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == 0) { // Falling edge detected
        printf("Button pressed!\n");
        program_running = 0; // Stop the blinking loop
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Set LED pin as output and initialize to LOW
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    // Set button pin as input with pull-up resistor
    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP);

    // Set alert function for falling edge detection on button pin
    gpioSetAlertFuncEx(BUTTON_PIN, button_press_handler, NULL);

    // Start blinking LED in a separate thread
    blink_led(LED_PIN, CHIP_NUMBER);

    // Clean up and terminate pigpio library
    gpioTerminate();

    return 0;
}

