#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins for RGB LED
#define RED_PIN   24
#define GREEN_PIN 23
#define BLUE_PIN  18

// Define PWM frequency (100 Hz)
#define PWM_FREQUENCY 100

// Define PWM period in microseconds
#define PWM_PERIOD (1000000 / PWM_FREQUENCY)

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
    }
}

// Function to set the PWM duty cycle for a given GPIO pin
int set_pwm_duty_cycle(int gpio_pin, int duty_cycle) {
    if (gpioPWM(gpio_pin, duty_cycle) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle for GPIO %d\n", gpio_pin);
        return -1;
    }
    return 0;
}

// Function to generate a random intensity value between 0 and 100
int generate_random_intensity() {
    return rand() % 101;
}

// Function to set the RGB LED color using PWM
int set_rgb_color(int red, int green, int blue) {
    if (set_pwm_duty_cycle(RED_PIN, red) != 0) return -1;
    if (set_pwm_duty_cycle(GREEN_PIN, green) != 0) return -1;
    if (set_pwm_duty_cycle(BLUE_PIN, blue) != 0) return -1;
    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Seed the random number generator
    srand(time(NULL));

    // Set GPIO pins as outputs
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM frequency for all GPIO pins
    gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("RGB LED control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Generate random intensity values for RGB channels
        int red_intensity = generate_random_intensity();
        int green_intensity = generate_random_intensity();
        int blue_intensity = generate_random_intensity();

        // Set the RGB LED color
        if (set_rgb_color(red_intensity, green_intensity, blue_intensity) != 0) {
            program_running = 0; // Exit loop on error
            break;
        }

        // Wait for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Clean up and terminate pigpio library
    gpioTerminate();

    printf("RGB LED control program terminated.\n");

    return 0;
}

