// Initialize LSM303DLHC accelerometer
int init_lsm303() {
    // Enable accelerometer (100Hz, normal mode)
    if (i2cWriteByteData(i2c_handle, CTRL_REG1_A, 0x57) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG1_A\n");
        return -1;
    }

    // Set accelerometer full-scale range to +/- 2G
    if (i2cWriteByteData(i2c_handle, CTRL_REG4_A, 0x00) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG4_A\n");
        return -1;
    }

    // Enable magnetometer (75 Hz, continuous conversion)
    i2cClose(i2c_handle);
    i2c_handle = i2cOpen(1, LSM303_MAG_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus for magnetometer: %d\n", i2c_handle);
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, CRA_REG_M, 0x18) < 0) {
        fprintf(stderr, "Failed to write to CRA_REG_M\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, MR_REG_M, 0x00) < 0) {
        fprintf(stderr, "Failed to write to MR_REG_M\n");
        return -1;
    }

    i2cClose(i2c_handle);
    i2c_handle = i2cOpen(1, LSM303_ACCEL_ADDR, 0); // Reopen accelerometer address
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return -1;
    }

    return 0;
}

// Read accelerometer data
int read_accelerometer(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L_A | 0x80, buffer, 6) != 6) {
        fprintf(stderr, "Failed to read accelerometer data\n");
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Read magnetometer data
int read_magnetometer(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    i2cClose(i2c_handle);
    i2c_handle = i2cOpen(1, LSM303_MAG_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus for magnetometer: %d\n", i2c_handle);
        return -1;
    }

    if (i2cReadI2CBlockData(i2c_handle, OUT_X_H_M, buffer, 6) != 6) {
        fprintf(stderr, "Failed to read magnetometer data\n");
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *z = (int16_t)((buffer[2] << 8) | buffer[3]);
    *y = (int16_t)((buffer[4] << 8) | buffer[5]);

    i2cClose(i2c_handle);
    i2c_handle = i2cOpen(1, LSM303_ACCEL_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return -1;
    }

    return 0;
}

// Calculate total G-force magnitude
double calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    // Convert raw values to G units (assuming +/- 2G range)
    double x_g = (double)x / 16384.0;
    double y_g = (double)y / 16384.0;
    double z_g = (double)z / 16384.0;

    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Trigger impact interrupt
void trigger_impact() {
    gpioWrite(IMPACT_PIN, 1); // Set GPIO high
    gpioDelay(50000);        // Wait 50ms
    gpioWrite(IMPACT_PIN, 0); // Set GPIO low
}

// Log data to file
void log_data(int16_t accel_x, int16_t accel_y, int16_t accel_z, int16_t mag_x, int16_t mag_y, int16_t mag_z, double magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Accel: X=%d, Y=%d, Z=%d, Mag: X=%d, Y=%d, Z=%d, Magnitude=%.2f\n",
            timestamp, accel_x, accel_y, accel_z, mag_x, mag_y, mag_z, magnitude);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

