#include <math.h>

// FXOS8700CQ I2C address
#define FXOS8700CQ_ADDR 0x1F

// FXOS8700CQ register addresses
#define FXOS8700CQ_WHO_AM_I 0x0D
#define FXOS8700CQ_CTRL_REG1 0x2A
#define FXOS8700CQ_XYZ_DATA_CFG 0x0E
#define FXOS8700CQ_STATUS 0x00
#define FXOS8700CQ_OUT_X_MSB 0x01

// Impact threshold (in g)
#define IMPACT_THRESHOLD 2.0

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_fxos8700cq();
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
float calculate_magnitude(int16_t x, int16_t y, int16_t z);
int log_impact(int16_t x, int16_t y, int16_t z, float magnitude);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize the FXOS8700CQ sensor
int init_fxos8700cq() {
    int who_am_i;

    // Check WHO_AM_I register
    who_am_i = i2cReadByteData(i2c_handle, FXOS8700CQ_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0xC7) {
        fprintf(stderr, "Incorrect WHO_AM_I value: 0x%02X\n", who_am_i);
        return -1;
    }
    printf("WHO_AM_I value: 0x%02X (expected 0xC7)\n", who_am_i);

    // Set to standby mode
    if (i2cWriteByteData(i2c_handle, FXOS8700CQ_CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Error setting standby mode\n");
        return -1;
    }

    // Configure for ±2g range
    if (i2cWriteByteData(i2c_handle, FXOS8700CQ_XYZ_DATA_CFG, 0x00) < 0) {
        fprintf(stderr, "Error configuring range\n");
        return -1;
    }

    // Set to active mode, 200 Hz ODR
    if (i2cWriteByteData(i2c_handle, FXOS8700CQ_CTRL_REG1, 0x15) < 0) {
        fprintf(stderr, "Error setting active mode\n");
        return -1;
    }

    return 0;
}

// Read acceleration data from the FXOS8700CQ
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, FXOS8700CQ_OUT_X_MSB, buffer, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]) >> 2;
    *y = (int16_t)((buffer[2] << 8) | buffer[3]) >> 2;
    *z = (int16_t)((buffer[4] << 8) | buffer[5]) >> 2;

    return 0;
}

// Calculate the magnitude of the acceleration vector
float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    return sqrt(x * x + y * y + z * z) / 4096.0; // Convert to g
}

// Log impact data to a file
int log_impact(int16_t x, int16_t y, int16_t z, float magnitude) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen("impact_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening impact_log.txt\n");
        return -1;
    }

    fprintf(fp, "%s,%d,%d,%d,%.3f\n", timestamp, x, y, z, magnitude);
    fclose(fp);

    return 0;
}

int main() {
    int16_t x, y, z;
    float magnitude;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, FXOS8700CQ_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_fxos8700cq() < 0) {
        fprintf(stderr, "FXOS8700CQ initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Starting impact detection...\n");

    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(&x, &y, &z) == 0) {
            // Calculate magnitude
            magnitude = calculate_magnitude(x, y, z);

            // Check for impact
            if (magnitude > IMPACT_THRESHOLD) {
                printf("Impact detected! Magnitude: %.3f g\n", magnitude);
                // Log impact data
                if (log_impact(x, y, z, magnitude) < 0) {
                    fprintf(stderr, "Error logging impact\n");
                }
            }
        } else {
            fprintf(stderr, "Error reading acceleration data, retrying...\n");
        }

        // Delay for 50ms
        gpioDelay(50000); // 50ms = 50000 microseconds
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

