#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// GY-50 L3G4200D I2C address
#define GYRO_ADDR 0x69

// GY-50 L3G4200D register addresses
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define WHO_AM_I 0x0F

// Sensitivity scale factor (250 dps)
#define SENSITIVITY 0.00875

// Number of samples for calibration
#define NUM_SAMPLES 100

// Alert threshold (50 dps)
#define ALERT_THRESHOLD 50.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Function prototypes
int init_gyro();
gyro_data_t read_gyro_data();
gyro_data_t calibrate_gyro(int num_samples);
void log_data(gyro_data_t data);
void check_alert(gyro_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize the gyroscope
int init_gyro() {
    // Check WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0xD3) {
        fprintf(stderr, "WHO_AM_I returned 0x%02X, expected 0xD3\n", who_am_i);
        return -1;
    }

    // Configure CTRL_REG1 (Normal mode, 200 Hz data rate)
    int status = i2cWriteByteData(i2c_handle, CTRL_REG1, 0x0F);
    if (status < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1: %d\n", status);
        return -1;
    }

    // Configure CTRL_REG4 (Full scale range +/- 250 dps)
    status = i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4: %d\n", status);
        return -1;
    }

    return 0;
}

// Read raw gyroscope data
gyro_data_t read_gyro_data() {
    gyro_data_t data;
    char buffer[6];

    int status = i2cReadI2CBlockData(i2c_handle, OUT_X_L | 0x80, buffer, 6); // Read multiple bytes with auto-increment
    if (status < 0) {
        fprintf(stderr, "Error reading gyro data: %d\n", status);
        data.x = 0.0;
        data.y = 0.0;
        data.z = 0.0;
        return data;
    }

    // Combine high and low bytes, convert to dps
    int16_t raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    data.x = (float)raw_x * SENSITIVITY;
    data.y = (float)raw_y * SENSITIVITY;
    data.z = (float)raw_z * SENSITIVITY;

    return data;
}

