#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define WHO_AM_I 0x0F

// Sensitivity scale factor (250 dps)
#define SENSITIVITY 0.00875

// Number of samples for calibration
#define NUM_SAMPLES 100

// Alert threshold (50 dps)
#define ALERT_THRESHOLD 50.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Function prototypes
int init_gyro();
gyro_data_t read_gyro_data();
gyro_data_t calibrate_gyro(int num_samples);
void log_data(gyro_data_t data);
void check_alert(gyro_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize the gyroscope
int init_gyro() {
    // Check WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0xD3) {
        fprintf(stderr, "WHO_AM_I returned 0x%02X, expected 0xD3\n", who_am_i);
        return -1;
    }

    // Configure CTRL_REG1 (Normal mode, 200 Hz data rate)
    int status = i2cWriteByteData(i2c_handle, CTRL_REG1, 0x0F);
    if (status < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1: %d\n", status);
        return -1;
    }

    // Configure CTRL_REG4 (Full scale range +/- 250 dps)
    status = i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4: %d\n", status);
        return -1;
    }

    return 0;
}

