        fprintf(stderr, "Incorrect device ID: 0x%02X\n", devid);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    printf("ADXL345 device ID: 0x%02X\n", devid);

    // Initialize ADXL345
    if (adxl345_init() < 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("accel_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(&x, &y, &z) == 0) {
            // Log data
            log_data(x, y, z);

            // Control LED
            control_led(x, y, z);
        } else {
            fprintf(stderr, "Failed to read acceleration data. Skipping logging.\n");
        }

        // Delay for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();
