#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define I2C addresses for the two sensors
#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69

// Define the I2C bus
#define I2C_BUS 1

// Define the sampling interval in milliseconds
#define SAMPLING_INTERVAL_MS 10

// Define the number of samples to read from each sensor
#define NUM_SAMPLES 100

// Define the CSV file name
#define CSV_FILE "audio_log.dat"

// Global variables for I2C handles and file pointer
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *fp = NULL;

// Structure to hold sensor data
typedef struct {
    int16_t sensor1_data[NUM_SAMPLES];
    int16_t sensor2_data[NUM_SAMPLES];
    struct timespec timestamp[NUM_SAMPLES];
} sensor_data_t;

// Function prototypes
int initialize_pigpio();
int initialize_i2c(int bus, int addr);
int read_sensor_data(int i2c_handle, int16_t *data, int num_samples);
int calculate_tdoa(int16_t *sensor1_data, int16_t *sensor2_data, int num_samples, double *tdoa);
int write_to_csv(FILE *fp, struct timespec *timestamp, int16_t *sensor1_data, int16_t *sensor2_data, double *tdoa, int num_samples);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
}

// Function to initialize the pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to initialize the I2C connection
int initialize_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02x: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Function to read data from the sensor
int read_sensor_data(int i2c_handle, int16_t *data, int num_samples) {
    char buf[2];
    int bytes_read;

    for (int i = 0; i < num_samples; i++) {
        bytes_read = i2cReadDevice(i2c_handle, buf, 2);
        if (bytes_read != 2) {
            fprintf(stderr, "Failed to read data from sensor: %d\n", bytes_read);
            return -1;
        }

        // Combine the two bytes into a 16-bit signed integer
        data[i] = (int16_t)((buf[0] << 8) | buf[1]);
    }
    return 0;
}

// Function to calculate the TDOA (Time Difference of Arrival)
int calculate_tdoa(int16_t *sensor1_data, int16_t *sensor2_data, int num_samples, double *tdoa) {
    // This is a placeholder.  A real implementation would use cross-correlation
    // or other TDOA estimation techniques.
    // For now, we'll just return a dummy value.
    *tdoa = 0.0; // Dummy TDOA value
    return 0;
}

// Function to write data to the CSV file
int write_to_csv(FILE *fp, struct timespec *timestamp, int16_t *sensor1_data, int16_t *sensor2_data, double *tdoa, int num_samples) {
    for (int i = 0; i < num_samples; i++) {
        fprintf(fp, "%ld,%ld,%d,%d,%.6f\n", timestamp[i].tv_sec, timestamp[i].tv_nsec, sensor1_data[i], sensor2_data[i], tdoa[i]);
    }
    return 0;
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C for both sensors
    i2c_handle1 = initialize_i2c(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        cleanup();
        return 1;
    }

    i2c_handle2 = initialize_i2c(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        cleanup();
        return 1;
    }

    // Open the CSV file for writing
    fp = fopen(CSV_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open CSV file\n");
        cleanup();
        return 1;
    }

    // Write the header row to the CSV file
    fprintf(fp, "sec,nsec,sensor1,sensor2,tdoa\n");

    sensor_data_t sensor_data;
    struct timespec ts;
    double tdoa;

    // Main loop to sample and process data
    while (1) {
        // Read data from sensor 1
        if (read_sensor_data(i2c_handle1, sensor_data.sensor1_data, NUM_SAMPLES) != 0) {
            fprintf(stderr, "Error reading from sensor 1, skipping sample\n");
            // Optionally, add a delay before retrying
            gpioDelay(1000); // 1 ms delay
            continue;
        }

        // Read data from sensor 2
        if (read_sensor_data(i2c_handle2, sensor_data.sensor2_data, NUM_SAMPLES) != 0) {
            fprintf(stderr, "Error reading from sensor 2, skipping sample\n");
            // Optionally, add a delay before retrying
            gpioDelay(1000); // 1 ms delay
            continue;
        }

        // Get timestamp for each sample
        for (int i = 0; i < NUM_SAMPLES; i++) {
            if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
                perror("clock_gettime");
                cleanup();
                return 1;
            }
            sensor_data.timestamp[i] = ts;
        }

        // Calculate TDOA
        if (calculate_tdoa(sensor_data.sensor1_data, sensor_data.sensor2_data, NUM_SAMPLES, &tdoa) != 0) {
            fprintf(stderr, "Error calculating TDOA, skipping sample\n");
            continue;
        }

        // Write data to CSV file
        if (write_to_csv(fp, sensor_data.timestamp, sensor_data.sensor1_data, sensor_data.sensor2_data, &tdoa, NUM_SAMPLES) != 0) {
            fprintf(stderr, "Error writing to CSV file\n");
        }

        // Flush the buffer to ensure data is written to the file
        fflush(fp);

        // Delay for the sampling interval
        gpioDelay(SAMPLING_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // The program should never reach here due to the infinite loop, but include cleanup for completeness
    cleanup();
    return 0;
}

