        if (bytes_read != 2) {
            fprintf(stderr, "Failed to read data from sensor: %d\n", bytes_read);
            return -1;
        }

        // Combine the two bytes into a 16-bit signed integer
        data[i] = (int16_t)((buf[0] << 8) | buf[1]);
    }
    return 0;
}

