#define YGYRO_OUT 0x06
#define ZGYRO_OUT 0x08
#define XACCL_OUT 0x0A
#define YACCL_OUT 0x0C
#define ZACCL_OUT 0x0E

// Scaling factors
#define GYRO_SCALE 0.02  // dps/LSB
#define ACCL_SCALE 0.00025 // g/LSB

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8          // GPIO8 (BCM)

int spi_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCtrl+C pressed. Cleaning up...\n");
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

// Function to read a 16-bit register from the ADIS16448
int16_t read_register(int handle, uint8_t reg_addr) {
    char tx_buf[2];
    char rx_buf[2];

    // Set MSB to 1 for read operation
    tx_buf[0] = reg_addr | 0x80;
    tx_buf[1] = 0x00; // Dummy byte for reading

    if (spiXfer(handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Combine the two bytes to form the 16-bit value
    return (int16_t)((rx_buf[0] << 8) | rx_buf[1]);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 3); // Mode 3
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Deactivate CS initially

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read gyroscope data
        int16_t gyro_x = read_register(spi_handle, XGYRO_OUT);
        int16_t gyro_y = read_register(spi_handle, YGYRO_OUT);
        int16_t gyro_z = read_register(spi_handle, ZGYRO_OUT);

        // Read accelerometer data
        int16_t accel_x = read_register(spi_handle, XACCL_OUT);
        int16_t accel_y = read_register(spi_handle, YACCL_OUT);
        int16_t accel_z = read_register(spi_handle, ZACCL_OUT);

        // Check for read errors
        if (gyro_x == -1 || gyro_y == -1 || gyro_z == -1 ||
            accel_x == -1 || accel_y == -1 || accel_z == -1) {
            fprintf(stderr, "Error: Failed to read IMU data\n");
            continue; // Skip to the next iteration
        }

        // Convert to physical units
        float gyro_x_dps = gyro_x * GYRO_SCALE;
        float gyro_y_dps = gyro_y * GYRO_SCALE;
        float gyro_z_dps = gyro_z * GYRO_SCALE;
        float accel_x_g = accel_x * ACCL_SCALE;
        float accel_y_g = accel_y * ACCL_SCALE;
        float accel_z_g = accel_z * ACCL_SCALE;

        // Log the data to the console
        printf("Gyro: X=%.2f dps, Y=%.2f dps, Z=%.2f dps | Accel: X=%.4f g, Y=%.4f g, Z=%.4f g\n",
               gyro_x_dps, gyro_y_dps, gyro_z_dps, accel_x_g, accel_y_g, accel_z_g);

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 us
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness.
    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

