#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

// MPU-6886 I2C address
#define MPU6886_ADDR 0x68

// MPU-6886 register addresses
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H  0x43

// Scaling factors
#define ACCEL_SCALE 16384.0f // +/- 2g range
#define GYRO_SCALE  131.0f   // +/- 250 deg/s range

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t accel_x, accel_y, accel_z;
    int16_t gyro_x, gyro_y, gyro_z;
} sensor_data_t;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCtrl+C pressed. Exiting...\n");
    terminate = 1;
}

// Function to initialize the MPU-6886
int init_mpu6886() {
    // Wake up the MPU-6886 (clear sleep mode bit)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) != 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6886. Error code: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read raw sensor data from the MPU-6886
int read_raw_data(sensor_data_t *data) {
    char buf[14];
    int retries = 3;

    while (retries > 0) {
        if (i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, buf, 14) == 14) {
            data->accel_x = (int16_t)((buf[0] << 8) | buf[1]);
            data->accel_y = (int16_t)((buf[2] << 8) | buf[3]);
            data->accel_z = (int16_t)((buf[4] << 8) | buf[5]);
            data->gyro_x  = (int16_t)((buf[8] << 8) | buf[9]);
            data->gyro_y  = (int16_t)((buf[10] << 8) | buf[11]);
            data->gyro_z  = (int16_t)((buf[12] << 8) | buf[13]);
            return 0; // Success
        } else {
            fprintf(stderr, "Error: I2C read failed (attempt %d). Error code: %d\n", 4 - retries, i2c_handle);
            retries--;
            gpioDelay(1000); // Wait 1 ms before retrying
        }
    }

    fprintf(stderr, "Error: I2C read failed after multiple retries.\n");
    return -1; // Failure
}

// Function to process raw sensor data and convert to physical units
void process_sensor_data(const sensor_data_t *raw_data, float *accel_x, float *accel_y, float *accel_z, float *gyro_x, float *gyro_y, float *gyro_z) {
    *accel_x = (float)raw_data->accel_x / ACCEL_SCALE;
    *accel_y = (float)raw_data->accel_y / ACCEL_SCALE;
    *accel_z = (float)raw_data->accel_z / ACCEL_SCALE;
    *gyro_x  = (float)raw_data->gyro_x  / GYRO_SCALE;
    *gyro_y  = (float)raw_data->gyro_y  / GYRO_SCALE;
    *gyro_z  = (float)raw_data->gyro_z  / GYRO_SCALE;
}

// Function to print sensor data to the console
void print_sensor_data(float accel_x, float accel_y, float accel_z, float gyro_x, float gyro_y, float gyro_z) {
    printf("Accel: X=%.2f g, Y=%.2f g, Z=%.2f g  |  Gyro: X=%.2f deg/s, Y=%.2f deg/s, Z=%.2f deg/s\n",
           accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6886_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus. Error code: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6886
    if (init_mpu6886() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    sensor_data_t raw_data;
    float accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;

    // Main loop
    while (!terminate) {
        // Read raw sensor data
        if (read_raw_data(&raw_data) == 0) {
            // Process sensor data
            process_sensor_data(&raw_data, &accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z);

            // Print sensor data
            print_sensor_data(accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data.\n");
        }

        // Delay for 50 ms
        gpioDelay(50000);
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

