#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// ICM-20602 I2C address
#define ICM20602_ADDR 0x68

// ICM-20602 register addresses
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H  0x43

// Scaling factors (adjust based on your configuration)
#define ACCEL_SCALE 16384.0f // +/- 2g range
#define GYRO_SCALE  131.0f   // +/- 250 dps range

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float accel_x, accel_y, accel_z;
    float gyro_x, gyro_y, gyro_z;
} sensor_data_t;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the ICM-20602
int init_icm20602() {
    // Wake up the device (clear sleep mode bit)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) != 0) {
        fprintf(stderr, "Error: Could not wake up ICM-20602\n");
        return -1;
    }
    gpioDelay(100); // Short delay after waking up
    return 0;
}

// Function to read raw sensor data
int read_raw_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    char buf[14];
    if (i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, buf, 14) != 14) {
        fprintf(stderr, "Error: Could not read sensor data\n");
        return -1;
    }

    *accel_x = (int16_t)((buf[0] << 8) | buf[1]);
    *accel_y = (int16_t)((buf[2] << 8) | buf[3]);
    *accel_z = (int16_t)((buf[4] << 8) | buf[5]);
    *gyro_x  = (int16_t)((buf[8] << 8) | buf[9]);
    *gyro_y  = (int16_t)((buf[10] << 8) | buf[11]);
    *gyro_z  = (int16_t)((buf[12] << 8) | buf[13]);

    return 0;
}

// Function to convert raw data to physical units
sensor_data_t convert_data(int16_t accel_x, int16_t accel_y, int16_t accel_z, int16_t gyro_x, int16_t gyro_y, int16_t gyro_z) {
    sensor_data_t data;
    data.accel_x = (float)accel_x / ACCEL_SCALE;
    data.accel_y = (float)accel_y / ACCEL_SCALE;
    data.accel_z = (float)accel_z / ACCEL_SCALE;
    data.gyro_x  = (float)gyro_x  / GYRO_SCALE;
    data.gyro_y  = (float)gyro_y  / GYRO_SCALE;
    data.gyro_z  = (float)gyro_z  / GYRO_SCALE;
    return data;
}

// Function to log data to a CSV file
int log_data(FILE *fp, sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n",
                timestamp, data.accel_x, data.accel_y, data.accel_z, data.gyro_x, data.gyro_y, data.gyro_z) < 0) {
        fprintf(stderr, "Error: Could not write to log file\n");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ICM20602_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize ICM-20602
    if (init_icm20602() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("imu_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Accel_X,Accel_Y,Accel_Z,Gyro_X,Gyro_Y,Gyro_Z\n");
    }
    rewind(log_file);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
    sensor_data_t sensor_data;

    while (!terminate) {
        // Read raw data
        if (read_raw_data(&accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Convert data
            sensor_data = convert_data(accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);

            // Log data
            if (log_data(log_file, sensor_data) != 0) {
                terminate = 1; // Stop if logging fails
            }
        } else {
            terminate = 1; // Stop if reading fails
        }

        gpioDelay(100); // 10 Hz rate (100 ms delay)
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

