    rewind(log_file);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
    sensor_data_t sensor_data;

    while (!terminate) {
        // Read raw data
        if (read_raw_data(&accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Convert data
            sensor_data = convert_data(accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);

            // Log data
            if (log_data(log_file, sensor_data) != 0) {
                terminate = 1; // Stop if logging fails
            }
        } else {
            terminate = 1; // Stop if reading fails
        }

        gpioDelay(100); // 10 Hz rate (100 ms delay)
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

