    *x = (int16_t)((buf[0] << 8) | buf[1]) >> 6; // 10-bit resolution
    *y = (int16_t)((buf[2] << 8) | buf[3]) >> 6;
    *z = (int16_t)((buf[4] << 8) | buf[5]) >> 6;

    return 0;
}

