#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>

// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define ADXL345_REG_DEVID 0x00
#define ADXL345_REG_THRESH_FF 0x28
#define ADXL345_REG_TIME_FF 0x29
#define ADXL345_REG_INT_ENABLE 0x2E
#define ADXL345_REG_INT_MAP 0x2F
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_POWER_CTL 0x2D

// GPIO pin for interrupt
#define INT_PIN 17

// Free-fall threshold (mg)
#define FREEFALL_THRESHOLD 200

// Free-fall time (ms)
#define FREEFALL_TIME 300

// Global variables
static volatile int keepRunning = 1;
static int i2c_fd;
static FILE *log_file;
static int freefall_active = 0;

// Function prototypes
int init_i2c(int address);
int init_adxl345(int fd);
int read_register(int fd, int reg);
int write_register(int fd, int reg, int value);
int read_acceleration(int fd, int *x, int *y, int *z);
int detect_freefall(int x, int y, int z);
void log_data(FILE *fp, int x, int y, int z);
void interrupt_handler(void);
void signal_handler(int sig);

// Structure to hold accelerometer data
typedef struct {
    int x;
    int y;
    int z;
} accelerometer_data_t;

// Function to initialize I2C
int init_i2c(int address) {
    int fd = wiringPiI2CSetup(address);
    if (fd == -1) {
        perror("wiringPiI2CSetup failed");
        return -1;
    }
    return fd;
}

// Function to initialize ADXL345
int init_adxl345(int fd) {
    // Verify device ID
    int devid = read_register(fd, ADXL345_REG_DEVID);
    if (devid != 0xE5) {
        fprintf(stderr, "Error: Invalid device ID: 0x%02X\n", devid);
        return -1;
    }

    // Set free-fall threshold
    if (write_register(fd, ADXL345_REG_THRESH_FF, FREEFALL_THRESHOLD / 7) == -1) {
        fprintf(stderr, "Error setting free-fall threshold\n");
        return -1;
    }

    // Set free-fall time
