#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// LSM6DSR I2C address
#define LSM6DSR_ADDR 0x6A

// LSM6DSR register addresses
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_H_G 0x23
#define OUTY_L_G 0x24
#define OUTY_H_G 0x25
#define OUTZ_L_G 0x26
#define OUTZ_H_G 0x27
#define OUTX_L_XL 0x28
#define OUTX_H_XL 0x29
#define OUTY_L_XL 0x2A
#define OUTY_H_XL 0x2B
#define OUTZ_L_XL 0x2C
#define OUTZ_H_XL 0x2D
#define WHO_AM_I 0x0F

// Scaling factors
#define ACCEL_SCALE 0.000061 // +/- 2g, 16-bit
#define GYRO_SCALE 0.00875  // +/- 250 dps, 16-bit

// Fall detection thresholds
#define FREEFALL_THRESHOLD 0.2  // g
#define IMPACT_THRESHOLD 2.5   // g
#define IMPACT_WINDOW 1.0      // seconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float accel_x, accel_y, accel_z;
    float gyro_x, gyro_y, gyro_z;
} sensor_data_t;

// Function prototypes
int init_lsm6dsr();
int read_sensor_data(sensor_data_t *data);
float calculate_acceleration_magnitude(sensor_data_t data);
void log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the LSM6DSR sensor
int init_lsm6dsr() {
    // Check WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0x69) {
        fprintf(stderr, "WHO_AM_I returned 0x%X, expected 0x69\n", who_am_i);
        return -1;
    }
    printf("LSM6DSR WHO_AM_I: 0x%X\n", who_am_i);

    // Configure accelerometer: 104 Hz, +/- 2g
    if (i2cWriteByteData(i2c_handle, CTRL1_XL, 0x80) < 0) { // 104 Hz, +/- 2g
        fprintf(stderr, "Error writing to CTRL1_XL register\n");
        return -1;
    }

    // Configure gyroscope: 104 Hz, +/- 250 dps
    if (i2cWriteByteData(i2c_handle, CTRL2_G, 0x80) < 0) { // 104 Hz, +/- 250 dps
        fprintf(stderr, "Error writing to CTRL2_G register\n");
        return -1;
    }

    return 0;
}

// Read sensor data from the LSM6DSR
int read_sensor_data(sensor_data_t *data) {
    char buffer[12];
    int result = i2cReadI2CBlockData(i2c_handle, OUTX_L_G, buffer, 12);

    if (result != 12) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    // Gyroscope data
    int16_t gyro_x_raw = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t gyro_y_raw = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t gyro_z_raw = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Accelerometer data
    int16_t accel_x_raw = (int16_t)((buffer[7] << 8) | buffer[6]);
    int16_t accel_y_raw = (int16_t)((buffer[9] << 8) | buffer[8]);
    int16_t accel_z_raw = (int16_t)((buffer[11] << 8) | buffer[10]);

    // Convert to g and dps
    data->gyro_x = (float)gyro_x_raw * GYRO_SCALE;
    data->gyro_y = (float)gyro_y_raw * GYRO_SCALE;
    data->gyro_z = (float)gyro_z_raw * GYRO_SCALE;
    data->accel_x = (float)accel_x_raw * ACCEL_SCALE;
    data->accel_y = (float)accel_y_raw * ACCEL_SCALE;
    data->accel_z = (float)accel_z_raw * ACCEL_SCALE;

    return 0;
}

// Calculate the magnitude of the acceleration vector
float calculate_acceleration_magnitude(sensor_data_t data) {
    return sqrt(data.accel_x * data.accel_x + data.accel_y * data.accel_y + data.accel_z * data.accel_z);
}

// Log data to a CSV file
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            timestamp, data.accel_x, data.accel_y, data.accel_z, data.gyro_x, data.gyro_y, data.gyro_z);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LSM6DSR sensor
    if (init_lsm6dsr() < 0) {
        fprintf(stderr, "LSM6DSR initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("motion_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,Accel_X,Accel_Y,Accel_Z,Gyro_X,Gyro_Y,Gyro_Z\n");

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;
    float acceleration_magnitude;
    time_t impact_start_time = 0;
    int impact_detected = 0;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Calculate acceleration magnitude
            acceleration_magnitude = calculate_acceleration_magnitude(sensor_data);

            // Log data
            log_data(sensor_data);

            // Fall detection state machine
            if (acceleration_magnitude < FREEFALL_THRESHOLD) {
                printf("Freefall detected!\n");
                impact_start_time = time(NULL);
                impact_detected = 0;
            } else if (acceleration_magnitude > IMPACT_THRESHOLD && impact_start_time != 0) {
                if (time(NULL) - impact_start_time <= IMPACT_WINDOW) {
                    printf("Impact detected!\n");
                    impact_detected = 1;
                } else {
                    impact_start_time = 0; // Reset if impact window expired
                }
            } else {
                impact_start_time = 0; // Reset if acceleration magnitude is below threshold
            }
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        gpioDelay(10); // 10 ms delay (104 Hz)
    }

    // Close log file
    fclose(log_file);

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

