    float z_rate;
} gyro_data_t;

// Function to read a register from the ADIS16266
int spi_read_register(int handle, uint8_t address, uint16_t *data) {
    char tx_buffer[2];
    char rx_buffer[2];

    // Construct the transmit buffer: OR the address with 0x80 for read
    tx_buffer[0] = address | 0x80;
    tx_buffer[1] = 0x00; // Dummy byte

    gpioWrite(CS_PIN, 0); // Select the device
    int result = spiXfer(handle, tx_buffer, rx_buffer, 2);
    gpioWrite(CS_PIN, 1); // Deselect the device

    if (result != 2) {
        fprintf(stderr, "Error: SPI read failed (address 0x%02X): %d\n", address, result);
        return -1;
    }

    // Combine the received bytes to form the 16-bit data
    *data = (rx_buffer[0] << 8) | rx_buffer[1];
    return 0;
}

// Function to write a register to the ADIS16266
int spi_write_register(int handle, uint8_t address, uint16_t data) {
    char tx_buffer[2];

    // Construct the transmit buffer: AND the address with 0x7F for write
    tx_buffer[0] = address & 0x7F;
    tx_buffer[1] = data & 0xFF; // LSB

    gpioWrite(CS_PIN, 0); // Select the device
    int result = spiWrite(handle, tx_buffer, 2);
    gpioWrite(CS_PIN, 1); // Deselect the device

    if (result != 2) {
