    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Deselect the device initially

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Verify device ID
    if (verify_device_id(spi_handle) != 0) {
        fprintf(stderr, "Error: Device verification failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X_Rate(deg/s),Y_Rate(deg/s),Z_Rate(deg/s)\n");
    }
    rewind(log_file);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Gyroscope data logging started. Press Ctrl+C to stop.\n");

    // Main loop
    while (!terminate) {
        uint16_t x_raw, y_raw, z_raw;
        float x_rate, y_rate, z_rate;

        // Read gyroscope data
        if (spi_read_register(spi_handle, ADIS16266_XGYRO_OUT, &x_raw) != 0 ||
            spi_read_register(spi_handle, ADIS16266_YGYRO_OUT, &y_raw) != 0 ||
            spi_read_register(spi_handle, ADIS16266_ZGYRO_OUT, &z_raw) != 0) {
            fprintf(stderr, "Error: Failed to read gyroscope data\n");
            continue; // Skip to the next iteration
        }

        // Convert raw data to degrees per second
        x_rate = convert_to_degrees_per_second((int16_t)x_raw);
        y_rate = convert_to_degrees_per_second((int16_t)y_raw);
        z_rate = convert_to_degrees_per_second((int16_t)z_raw);

        // Log the data
        log_data(log_file, x_rate, y_rate, z_rate);

        // Wait for 10 milliseconds
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Close SPI channel
    spiClose(spi_handle);

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    printf("Gyroscope data logging stopped.\n");

    return 0;
}

