#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// GY-50 L3G4200D I2C address
#define GYRO_ADDR 0x69

// GY-50 L3G4200D register addresses
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define WHO_AM_I 0x0F

// Sensitivity (mdps/LSB)
#define SENSITIVITY 8.75

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} gyro_data_t;

// Function prototypes
int init_gyro();
gyro_data_t read_gyro_data();
void process_gyro_data(gyro_data_t raw_data, float *x, float *y, float *z);
void log_data(float x, float y, float z);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful termination
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize the gyroscope
int init_gyro() {
    int retries = 3;
    int result;

    // Verify WHO_AM_I register
    while (retries > 0) {
        result = i2cReadByteData(i2c_handle, WHO_AM_I);
        if (result >= 0) {
            if (result == 0xD3) {
                printf("WHO_AM_I register verified (0xD3)\n");
                break;
            } else {
                fprintf(stderr, "Error: WHO_AM_I register returned 0x%02X, expected 0xD3\n", result);
                return -1;
            }
        } else {
            fprintf(stderr, "Error reading WHO_AM_I register: %d\n", result);
            retries--;
            gpioDelay(10000); // Wait 10ms before retrying
        }
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to verify WHO_AM_I register after multiple retries.\n");
        return -1;
    }

    // Configure CTRL_REG1 (Normal mode, 100Hz data rate)
    retries = 3;
    while (retries > 0) {
        result = i2cWriteByteData(i2c_handle, CTRL_REG1, 0x0F); //0b00001111
        if (result == 0) {
            printf("CTRL_REG1 configured successfully\n");
            break;
        } else {
            fprintf(stderr, "Error writing to CTRL_REG1: %d\n", result);
            retries--;
            gpioDelay(10000); // Wait 10ms before retrying
        }
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to configure CTRL_REG1 after multiple retries.\n");
        return -1;
    }

    // Configure CTRL_REG4 (Full scale range +/- 250 dps)
    retries = 3;
    while (retries > 0) {
        result = i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00); //0b00000000
        if (result == 0) {
            printf("CTRL_REG4 configured successfully\n");
            break;
        } else {
            fprintf(stderr, "Error writing to CTRL_REG4: %d\n", result);
            retries--;
            gpioDelay(10000); // Wait 10ms before retrying
        }
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to configure CTRL_REG4 after multiple retries.\n");
        return -1;
    }

    return 0;
}

// Read raw gyroscope data
gyro_data_t read_gyro_data() {
    gyro_data_t data;
    char buffer[6];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, OUT_X_L | 0x80, buffer, 6); // Read multiple bytes with auto-increment
    if (result != 6) {
        fprintf(stderr, "Error reading gyroscope data: %d\n", result);
        data.x = 0; // Set to 0 to avoid garbage data
        data.y = 0;
        data.z = 0;
        return data;
    }

    data.x = (int16_t)((buffer[1] << 8) | buffer[0]);
    data.y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data.z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return data;
}

// Process raw data and convert to degrees per second
