    // Initialize pigpio and GPIO pin
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop to continuously monitor the flame sensor
    while (running) {
        int flame_detected = read_flame_sensor();
        if (flame_detected >= 0) {
            log_flame_event(flame_detected);
        } else {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[20];

            time(&rawtime);
            timeinfo = localtime(&rawtime);

            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            fprintf(log_file, "%s - ERROR: Failed to read flame sensor\n", timestamp);
            fflush(log_file);
        }

        gpioDelay(500); // Wait 500 milliseconds
    }

    // Clean up resources before exiting
    cleanup();

    return 0;
}

