#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// MMA8452Q I2C address
#define MMA8452Q_ADDR 0x1D

// MMA8452Q register addresses
#define MMA8452Q_REG_WHO_AM_I 0x0D
#define MMA8452Q_REG_CTRL_REG1 0x2A
#define MMA8452Q_REG_OUT_X_MSB 0x01

// Expected WHO_AM_I value
#define MMA8452Q_WHO_AM_I_VALUE 0x2A

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_sensor();
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z);
float calculate_tilt(int16_t x, int16_t y, int16_t z);
int log_fall(int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, MMA8452Q_ADDR, 0); // Bus 1, address 0x1D, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Initialize the MMA8452Q sensor
int init_sensor() {
    // Verify WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, MMA8452Q_REG_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %s\n", strerror(errno));
        return -1;
    }
    if (who_am_i != MMA8452Q_WHO_AM_I_VALUE) {
        fprintf(stderr, "Error: Incorrect WHO_AM_I value (0x%02X, expected 0x%02X)\n", who_am_i, MMA8452Q_WHO_AM_I_VALUE);
        return -1;
    }
    printf("WHO_AM_I register verified.\n");

    // Configure CTRL_REG1: Active mode, 100 Hz data rate
    int status = i2cWriteByteData(i2c_handle, MMA8452Q_REG_CTRL_REG1, 0x01 | (0x02 << 3)); // Active mode, 100 Hz
    if (status < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1: %s\n", strerror(errno));
        return -1;
    }
    printf("Sensor initialized.\n");
    return 0;
}

// Read sensor data
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int status = i2cReadI2CBlockData(i2c_handle, MMA8452Q_REG_OUT_X_MSB, buffer, 6);
    if (status < 0) {
        fprintf(stderr, "Error reading sensor data: %s\n", strerror(errno));
        return -1;
    }

    // Combine MSB and LSB, right-shift by 4
    *x = ((int16_t)buffer[0] << 8 | buffer[1]) >> 4;
    *y = ((int16_t)buffer[2] << 8 | buffer[3]) >> 4;
    *z = ((int16_t)buffer[4] << 8 | buffer[5]) >> 4;

    return 0;
}

// Calculate tilt angle
float calculate_tilt(int16_t x, int16_t y, int16_t z) {
    float x_g = (float)x / 4096.0f; // Assuming +/- 2g range
    float y_g = (float)y / 4096.0f;
    float z_g = (float)z / 4096.0f;

    float tilt_x = atan2(y_g, sqrt(x_g * x_g + z_g * z_g)) * 180.0f / M_PI;
    float tilt_y = atan2(-x_g, sqrt(y_g * y_g + z_g * z_g)) * 180.0f / M_PI;

    return sqrt(tilt_x * tilt_x + tilt_y * tilt_y);
}

// Log fall event
int log_fall(int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, X: %d, Y: %d, Z: %d\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (init_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("fall_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data.x, &sensor_data.y, &sensor_data.z) == 0) {
            // Calculate tilt angle
            float tilt_angle = calculate_tilt(sensor_data.x, sensor_data.y, sensor_data.z);

            // Check for fall
            if (tilt_angle > 45.0f) {
                printf("Fall detected! Tilt angle: %.2f degrees\n", tilt_angle);
                log_fall(sensor_data.x, sensor_data.y, sensor_data.z);
            }
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        gpioDelay(10000); // 10 ms delay (100 Hz)
    }

    // Close I2C connection and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

