#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// LIS3MDL I2C address
#define LIS3MDL_ADDR 0x1E

// LIS3MDL register addresses
#define LIS3MDL_CTRL_REG1 0x20
#define LIS3MDL_CTRL_REG3 0x22
#define LIS3MDL_CTRL_REG4 0x23
#define LIS3MDL_OUT_X_L 0x28
#define LIS3MDL_OUT_X_H 0x29
#define LIS3MDL_OUT_Y_L 0x2A
#define LIS3MDL_OUT_Y_H 0x2B
#define LIS3MDL_OUT_Z_L 0x2C
#define LIS3MDL_OUT_Z_H 0x2D

// Calibration constants (replace with your calibration values)
#define X_OFFSET 0.0
#define Y_OFFSET 0.0
#define Z_OFFSET 0.0
#define X_SCALE 1.0
#define Y_SCALE 1.0
#define Z_SCALE 1.0

// Metal detector threshold (in mG)
#define METAL_DETECTOR_THRESHOLD 800.0

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold magnetometer data
typedef struct {
    float x;
    float y;
    float z;
} magnetometer_data_t;

// Function prototypes
int initialize_sensor();
magnetometer_data_t read_magnetometer_data();
magnetometer_data_t apply_calibration(magnetometer_data_t raw_data);
float calculate_total_field_magnitude(magnetometer_data_t calibrated_data);
void log_data(magnetometer_data_t calibrated_data);
void metal_detector_alert(float total_field_magnitude);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the LIS3MDL sensor
int initialize_sensor() {
    int retries = 0;
    int status;

    while (retries < 3) {
        // Configure CTRL_REG1: 10 Hz data rate, continuous conversion mode
        status = i2cWriteByteData(i2c_handle, LIS3MDL_CTRL_REG1, 0x70); //0b01110000
        if (status != 0) {
            fprintf(stderr, "Error writing to CTRL_REG1 (attempt %d): %d\n", retries + 1, status);
            retries++;
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        // Configure CTRL_REG3: Continuous-conversion mode
        status = i2cWriteByteData(i2c_handle, LIS3MDL_CTRL_REG3, 0x00);
        if (status != 0) {
            fprintf(stderr, "Error writing to CTRL_REG3 (attempt %d): %d\n", retries + 1, status);
            retries++;
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        // Configure CTRL_REG4: ±4 gauss full scale
        status = i2cWriteByteData(i2c_handle, LIS3MDL_CTRL_REG4, 0x00);
        if (status != 0) {
            fprintf(stderr, "Error writing to CTRL_REG4 (attempt %d): %d\n", retries + 1, status);
            retries++;
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        return 0; // Success
    }

    fprintf(stderr, "Failed to initialize sensor after multiple retries.\n");
    return -1; // Failure
}

// Function to read raw magnetometer data from the LIS3MDL
magnetometer_data_t read_magnetometer_data() {
    magnetometer_data_t raw_data;
    char buffer[6];
    int16_t x, y, z;
    int status;

    status = i2cReadI2CBlockData(i2c_handle, LIS3MDL_OUT_X_L, buffer, 6);
    if (status != 6) {
        fprintf(stderr, "Error reading magnetometer data: %d\n", status);
        raw_data.x = 0.0;
        raw_data.y = 0.0;
        raw_data.z = 0.0;
        return raw_data;
    }

    x = (int16_t)((buffer[1] << 8) | buffer[0]);
    y = (int16_t)((buffer[3] << 8) | buffer[2]);
    z = (int16_t)((buffer[5] << 8) | buffer[4]);

    raw_data.x = (float)x;
    raw_data.y = (float)y;
    raw_data.z = (float)z;

    return raw_data;
}

// Function to apply calibration to raw magnetometer data
magnetometer_data_t apply_calibration(magnetometer_data_t raw_data) {
    magnetometer_data_t calibrated_data;

    calibrated_data.x = (raw_data.x - X_OFFSET) * X_SCALE;
    calibrated_data.y = (raw_data.y - Y_OFFSET) * Y_SCALE;
    calibrated_data.z = (raw_data.z - Z_OFFSET) * Z_SCALE;

