#define Y_SCALE 1.0
#define Z_SCALE 1.0

// Metal detector threshold (in mG)
#define METAL_DETECTOR_THRESHOLD 800.0

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold magnetometer data
typedef struct {
    float x;
    float y;
    float z;
} magnetometer_data_t;

