int initialize_sensor();
magnetometer_data_t read_magnetometer_data();
magnetometer_data_t apply_calibration(magnetometer_data_t raw_data);
float calculate_total_field_magnitude(magnetometer_data_t calibrated_data);
void log_data(magnetometer_data_t calibrated_data);
void metal_detector_alert(float total_field_magnitude);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the LIS3MDL sensor
int initialize_sensor() {
    int retries = 0;
    int status;

    while (retries < 3) {
        // Configure CTRL_REG1: 10 Hz data rate, continuous conversion mode
        status = i2cWriteByteData(i2c_handle, LIS3MDL_CTRL_REG1, 0x70); //0b01110000
        if (status != 0) {
            fprintf(stderr, "Error writing to CTRL_REG1 (attempt %d): %d\n", retries + 1, status);
            retries++;
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        // Configure CTRL_REG3: Continuous-conversion mode
        status = i2cWriteByteData(i2c_handle, LIS3MDL_CTRL_REG3, 0x00);
        if (status != 0) {
            fprintf(stderr, "Error writing to CTRL_REG3 (attempt %d): %d\n", retries + 1, status);
            retries++;
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        // Configure CTRL_REG4: ±4 gauss full scale
        status = i2cWriteByteData(i2c_handle, LIS3MDL_CTRL_REG4, 0x00);
        if (status != 0) {
            fprintf(stderr, "Error writing to CTRL_REG4 (attempt %d): %d\n", retries + 1, status);
            retries++;
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

