#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADXL354B Register Addresses
#define ADXL354B_REG_DEVID_AD 0x00
#define ADXL354B_REG_DEVID_MST 0x01
#define ADXL354B_REG_PARTID 0x02
#define ADXL354B_REG_REVID 0x03
#define ADXL354B_REG_XDATA_H 0x08
#define ADXL354B_REG_XDATA_L 0x09
#define ADXL354B_REG_XDATA_XL 0x0A
#define ADXL354B_REG_YDATA_H 0x0B
#define ADXL354B_REG_YDATA_L 0x0C
#define ADXL354B_REG_YDATA_XL 0x0D
#define ADXL354B_REG_ZDATA_H 0x0E
#define ADXL354B_REG_ZDATA_L 0x0F
#define ADXL354B_REG_ZDATA_XL 0x10
#define ADXL354B_REG_STATUS 0x1D
#define ADXL354B_REG_POWER_CTL 0x2D
#define ADXL354B_REG_FILTER 0x28
#define ADXL354B_REG_RESET 0x1F

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_CE 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(int handle, uint8_t reg_addr, uint8_t *data, int len);
int spi_write_register(int handle, uint8_t reg_addr, uint8_t data);
int adxl354b_reset(int handle);
int adxl354b_init(int handle);
int adxl354b_read_acceleration(int handle, int32_t *x, int32_t *y, int32_t *z);
int log_data(FILE *fp, int32_t x, int32_t y, int32_t z);
void signal_handler(int signal);

// SPI Read Register Function
int spi_read_register(int handle, uint8_t reg_addr, uint8_t *data, int len) {
    char tx_buf[len + 1];
    char rx_buf[len + 1];
    int retries = 3;

    tx_buf[0] = reg_addr | 0x80; // Set MSB for read
    memset(tx_buf + 1, 0x00, len);

    while (retries > 0) {
        if (spiXfer(handle, tx_buf, rx_buf, len + 1) == len + 1) {
            memcpy(data, rx_buf + 1, len);
            return 0; // Success
        } else {
            fprintf(stderr, "SPI read error, retrying...\n");
            gpioDelay(1000); // 1 ms delay
            retries--;
        }
    }

    fprintf(stderr, "SPI read failed after multiple retries.\n");
    return -1; // Failure
}

// SPI Write Register Function
int spi_write_register(int handle, uint8_t reg_addr, uint8_t data) {
    char tx_buf[2];
    char rx_buf[2];
    int retries = 3;

    tx_buf[0] = reg_addr & 0x7F; // Clear MSB for write
    tx_buf[1] = data;

    while (retries > 0) {
        if (spiXfer(handle, tx_buf, rx_buf, 2) == 2) {
            return 0; // Success
        } else {
            fprintf(stderr, "SPI write error, retrying...\n");
            gpioDelay(1000); // 1 ms delay
            retries--;
        }
    }

    fprintf(stderr, "SPI write failed after multiple retries.\n");
    return -1; // Failure
}

// ADXL354B Reset Function
int adxl354b_reset(int handle) {
    if (spi_write_register(handle, ADXL354B_REG_RESET, 0x52) != 0) {
        fprintf(stderr, "Failed to reset ADXL354B.\n");
        return -1;
    }
    gpioDelay(1000); // Wait 1 ms
    return 0;
}

// ADXL354B Initialization Function
int adxl354b_init(int handle) {
    uint8_t part_id;

    // Reset the device
    if (adxl354b_reset(handle) != 0) {
        return -1;
    }

    // Verify Part ID
    if (spi_read_register(handle, ADXL354B_REG_PARTID, &part_id, 1) != 0) {
        fprintf(stderr, "Failed to read Part ID.\n");
        return -1;
    }

    if (part_id != 0xAD) {
        fprintf(stderr, "Incorrect Part ID: 0x%02X\n", part_id);
        return -1;
    }

    // Set Filter
    if (spi_write_register(handle, ADXL354B_REG_FILTER, 0x03) != 0) {
        fprintf(stderr, "Failed to set filter.\n");
        return -1;
    }

    // Clear Power Control Register
    if (spi_write_register(handle, ADXL354B_REG_POWER_CTL, 0x00) != 0) {
        fprintf(stderr, "Failed to clear power control register.\n");
        return -1;
    }

    gpioDelay(1000); // Wait 1 ms

    // Set Power Control Register to RUN
    if (spi_write_register(handle, ADXL354B_REG_POWER_CTL, 0x02) != 0) {
        fprintf(stderr, "Failed to set power control register to RUN.\n");
        return -1;
    }

    return 0;
}

// ADXL354B Read Acceleration Function
int adxl354b_read_acceleration(int handle, int32_t *x, int32_t *y, int32_t *z) {
    uint8_t x_data[3];
    uint8_t y_data[3];
    uint8_t z_data[3];

    if (spi_read_register(handle, ADXL354B_REG_XDATA_H, x_data, 3) != 0) {
        fprintf(stderr, "Failed to read X acceleration data.\n");
        return -1;
    }
    if (spi_read_register(handle, ADXL354B_REG_YDATA_H, y_data, 3) != 0) {
        fprintf(stderr, "Failed to read Y acceleration data.\n");
        return -1;
    }
    if (spi_read_register(handle, ADXL354B_REG_ZDATA_H, z_data, 3) != 0) {
        fprintf(stderr, "Failed to read Z acceleration data.\n");
        return -1;
    }

    *x = ((int32_t)x_data[0] << 12) | ((int32_t)x_data[1] << 4) | ((int32_t)x_data[2] >> 4);
    *y = ((int32_t)y_data[0] << 12) | ((int32_t)y_data[1] << 4) | ((int32_t)y_data[2] >> 4);
    *z = ((int32_t)z_data[0] << 12) | ((int32_t)z_data[1] << 4) | ((int32_t)z_data[2] >> 4);

    return 0;
}

// Log Data Function
int log_data(FILE *fp, int32_t x, int32_t y, int32_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s, %d, %d, %d\n", timestamp, x, y, z);
    fflush(fp); // Ensure data is written to file immediately

    return 0;
}

// Signal Handler Function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    int32_t x, y, z;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("vibration_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL354B
    if (adxl354b_init(spi_handle) != 0) {
        fprintf(stderr, "ADXL354B initialization failed\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        if (adxl354b_read_acceleration(spi_handle, &x, &y, &z) == 0) {
            log_data(log_file, x, y, z);
        } else {
            fprintf(stderr, "Failed to read acceleration data\n");
        }
        gpioDelay(100000); // 100 ms delay
    }

    // Cleanup
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

