#define Y_GYRO_OUT 0x06
#define Z_GYRO_OUT 0x08
#define X_ACCEL_OUT 0x0A
#define Y_ACCEL_OUT 0x0C
#define Z_ACCEL_OUT 0x0E
#define SMPL_PRD 0x36
#define GLOB_CMD 0x68
#define DIAG_STS 0x02

// Scaling factors
#define GYRO_SCALE 0.05  // deg/sec per LSB
#define ACCEL_SCALE 0.0025 // g per LSB

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_MODE 3

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold IMU data
typedef struct {
    double timestamp;
    float x_gyro;
    float y_gyro;
    float z_gyro;
    float x_accel;
    float y_accel;
    float z_accel;
} imu_data_t;

// Function prototypes
int initialize_imu();
int read_register(uint8_t address, int16_t *data);
imu_data_t process_data(int16_t gyro_x, int16_t gyro_y, int16_t gyro_z, int16_t accel_x, int16_t accel_y, int16_t accel_z);
int log_data(imu_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the ADIS16362 IMU
int initialize_imu() {
    // Reset the device
    if (write_register(GLOB_CMD, 0x0004) != 0) {
        fprintf(stderr, "Error: Failed to reset IMU.\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Set sample period (adjust as needed)
    if (write_register(SMPL_PRD, 0x000A) != 0) {
        fprintf(stderr, "Error: Failed to set sample period.\n");
        return -1;
    }

    // Verify initialization by reading diagnostic status
    int16_t diag_status;
    if (read_register(DIAG_STS, &diag_status) != 0) {
        fprintf(stderr, "Error: Failed to read diagnostic status.\n");
        return -1;
    }

    if (diag_status != 0) {
        fprintf(stderr, "Error: IMU initialization failed. Diagnostic status: 0x%04X\n", diag_status);
        return -1;
    }

    printf("IMU initialized successfully.\n");
    return 0;
}

// Writes a 16-bit value to a register
int write_register(uint8_t address, int16_t data) {
    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = address | 0x80; // Set MSB for write
    tx_buffer[1] = (data >> 8) & 0xFF; // MSB of data
    tx_buffer[2] = data & 0xFF;      // LSB of data

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI write failed for address 0x%02X\n", address);
        return -1;
    }

    return 0;
}

// Reads a 16-bit value from a register
int read_register(uint8_t address, int16_t *data) {
    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = address & 0x7F; // Clear MSB for read
    tx_buffer[1] = 0x00; // Dummy byte
    tx_buffer[2] = 0x00; // Dummy byte

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI read failed for address 0x%02X\n", address);
        return -1;
    }

    *data = (rx_buffer[1] << 8) | rx_buffer[2]; // Combine bytes

    return 0;
}

// Processes raw data and scales it
imu_data_t process_data(int16_t gyro_x, int16_t gyro_y, int16_t gyro_z, int16_t accel_x, int16_t accel_y, int16_t accel_z) {
    imu_data_t data;
    struct timespec ts;

    clock_gettime(CLOCK_REALTIME, &ts);
    data.timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;

    data.x_gyro = (float)gyro_x * GYRO_SCALE;
    data.y_gyro = (float)gyro_y * GYRO_SCALE;
    data.z_gyro = (float)gyro_z * GYRO_SCALE;
    data.x_accel = (float)accel_x * ACCEL_SCALE;
    data.y_accel = (float)accel_y * ACCEL_SCALE;
    data.z_accel = (float)accel_z * ACCEL_SCALE;

    return data;
}

