int log_data(imu_data_t data) {
    if (fprintf(log_file, "%.9f,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
                data.timestamp, data.x_gyro, data.y_gyro, data.z_gyro, data.x_accel, data.y_accel, data.z_accel) < 0) {
        fprintf(stderr, "Error: Failed to write data to log file.\n");
        return -1;
    }
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

