    while (!terminate) {
        int16_t gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;

        // Read IMU data
        if (read_register(X_GYRO_OUT, &gyro_x) != 0 ||
            read_register(Y_GYRO_OUT, &gyro_y) != 0 ||
            read_register(Z_GYRO_OUT, &gyro_z) != 0 ||
            read_register(X_ACCEL_OUT, &accel_x) != 0 ||
            read_register(Y_ACCEL_OUT, &accel_y) != 0 ||
            read_register(Z_ACCEL_OUT, &accel_z) != 0) {
            fprintf(stderr, "Error: Failed to read IMU data. Retrying...\n");
            gpioDelay(10); // Small delay before retrying
            continue;
        }

        // Process data
        imu_data_t data = process_data(gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);

        // Log data
        if (log_data(data) != 0) {
