// Define the GPIO pin connected to the IR obstacle sensor
#define SENSOR_PIN 17

// Define the GPIO chip number
#define GPIO_CHIP 4

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the sensor value from the specified GPIO pin
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value from GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to log a message with a timestamp to the console
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
}

// Function to simulate the self-parking sequence
void simulate_self_parking() {
    log_message("Self-parking sequence started");
    sleep(5); // Simulate the parking routine
    log_message("Self-parking sequence completed");
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure the GPIO pin as an input
    gpioSetMode(SENSOR_PIN, PI_INPUT);

    printf("IR Obstacle Sensor Monitoring started. Press Ctrl+C to exit.\n");

    // Main loop to continuously monitor the sensor
    while (program_running) {
        int sensor_value = read_sensor(SENSOR_PIN);
        if (sensor_value == 0) {
            // Obstacle detected (LOW signal)
            simulate_self_parking();
        } else if (sensor_value < 0) {
            // Error reading sensor, exit loop
            break;
        }

        sleep(1); // Wait for 1 second
    }

    // Clean up and terminate the pigpio library
    gpioTerminate();
    printf("pigpio terminated.\n");

    return 0;
}

