#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for the sensors
#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read sensor data from both GPIO pins
int read_sensors(int gpio17_value, int gpio27_value) {
    // Read the values from the GPIO pins
    gpio17_value = gpioRead(SENSOR_1_GPIO);
    gpio27_value = gpioRead(SENSOR_2_GPIO);

    // Return the combined sensor values
    return (gpio17_value << 1) | gpio27_value;
}

// Function to log sensor data with a timestamp
void log_data(int sensor_data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Get the current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format the timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Log the sensor data with the timestamp
    printf("[%s] Sensor 1: %s, Sensor 2: %s\n", timestamp,
           (sensor_data & 0x02) ? "Obstacle Detected" : "Path Clear",
           (sensor_data & 0x01) ? "Obstacle Detected" : "Path Clear");
}

int main() {
    int gpio17_value, gpio27_value, sensor_data;
    int pigpio_init_result;

    // Register the signal handler for SIGINT
