#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADIS16266 Register Addresses
#define XGYRO_OUT 0x04
#define YGYRO_OUT 0x06
#define ZGYRO_OUT 0x08

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 3

// Scale Factor
#define SCALE_FACTOR 0.02

// Global Variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Signal Handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCtrl+C pressed. Exiting...\n");
    terminate = 1;
}

// Function to read a 16-bit value from the ADIS16266
int16_t read_adis16266(int spi_handle, uint8_t register_address) {
    char tx_buffer[2];
    char rx_buffer[2];

    // Set MSB to 1 for read operation
    tx_buffer[0] = register_address | 0x80;
    tx_buffer[1] = 0x00; // Dummy byte for reading

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 2) != 0) {
        fprintf(stderr, "Error: SPI transfer failed.\n");
        return -1; // Indicate error
    }

    // Combine the two bytes to form the 16-bit value
    int16_t value = (rx_buffer[0] << 8) | rx_buffer[1];
    return value;
}

// Function to convert raw gyroscope data to degrees per second
gyro_data_t convert_to_dps(int16_t x_raw, int16_t y_raw, int16_t z_raw) {
    gyro_data_t dps;
    dps.x = x_raw * SCALE_FACTOR;
    dps.y = y_raw * SCALE_FACTOR;
    dps.z = z_raw * SCALE_FACTOR;
    return dps;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed.\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("ADIS16266 Gyroscope Data Acquisition\n");

    // Main loop
    while (!terminate) {
        // Read raw gyroscope data
        int16_t x_raw = read_adis16266(spi_handle, XGYRO_OUT);
        int16_t y_raw = read_adis16266(spi_handle, YGYRO_OUT);
        int16_t z_raw = read_adis16266(spi_handle, ZGYRO_OUT);

        // Check for read errors
        if (x_raw == -1 || y_raw == -1 || z_raw == -1) {
            fprintf(stderr, "Error: Failed to read gyroscope data. Retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Convert raw data to degrees per second
        gyro_data_t dps = convert_to_dps(x_raw, y_raw, z_raw);

        // Log the data to the console
        printf("X: %.2f deg/s, Y: %.2f deg/s, Z: %.2f deg/s\n", dps.x, dps.y, dps.z);

        // Wait for 100 milliseconds
        gpioDelay(100);
    }

    // Close SPI channel
    spiClose(spi_handle);

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

