#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

// FXOS8700 I2C address
#define FXOS8700_ADDR 0x1F

// FXOS8700 register addresses
#define FXOS8700_REG_STATUS 0x00
#define FXOS8700_REG_OUT_X_MSB 0x01
#define FXOS8700_REG_OUT_X_LSB 0x02
#define FXOS8700_REG_OUT_Y_MSB 0x03
#define FXOS8700_REG_OUT_Y_LSB 0x04
#define FXOS8700_REG_OUT_Z_MSB 0x05
#define FXOS8700_REG_OUT_Z_LSB 0x06
#define FXOS8700_REG_OUT_MAG_X_MSB 0x33
#define FXOS8700_REG_OUT_MAG_X_LSB 0x34
#define FXOS8700_REG_OUT_MAG_Y_MSB 0x35
#define FXOS8700_REG_OUT_MAG_Y_LSB 0x36
#define FXOS8700_REG_OUT_MAG_Z_MSB 0x37
#define FXOS8700_REG_OUT_MAG_Z_LSB 0x38
#define FXOS8700_REG_WHOAMI 0x0D
#define FXOS8700_REG_CTRL_REG1 0x2A
#define FXOS8700_REG_M_CTRL_REG1 0x5B
#define FXOS8700_REG_M_CTRL_REG2 0x5C

// Expected WHOAMI value
#define FXOS8700_WHOAMI_VALUE 0xC7

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t accel_x;
    int16_t accel_y;
    int16_t accel_z;
    int16_t mag_x;
    int16_t mag_y;
    int16_t mag_z;
} sensor_data_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the FXOS8700 sensor
int init_fxos8700() {
    // Check WHOAMI register
    int whoami = i2cReadByteData(i2c_handle, FXOS8700_REG_WHOAMI);
    if (whoami < 0) {
        fprintf(stderr, "Error reading WHOAMI register: %s\n", strerror(errno));
        return -1;
    }
    if (whoami != FXOS8700_WHOAMI_VALUE) {
        fprintf(stderr, "WHOAMI value mismatch: 0x%02X (expected 0x%02X)\n", whoami, FXOS8700_WHOAMI_VALUE);
        return -1;
    }
    printf("WHOAMI check passed. Device ID: 0x%02X\n", whoami);

    // Configure accelerometer: Active mode, 100 Hz ODR
    if (i2cWriteByteData(i2c_handle, FXOS8700_REG_CTRL_REG1, 0x01 | (0x02 << 3)) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1: %s\n", strerror(errno));
        return -1;
    }

    // Configure magnetometer: Hybrid mode, 80 Hz ODR
    if (i2cWriteByteData(i2c_handle, FXOS8700_REG_M_CTRL_REG1, 0x1F) < 0) {
        fprintf(stderr, "Error writing to M_CTRL_REG1: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, FXOS8700_REG_M_CTRL_REG2, 0x20) < 0) {
        fprintf(stderr, "Error writing to M_CTRL_REG2: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buffer[12];
    int retries = 3;

    while (retries > 0) {
        if (i2cReadI2CBlockData(i2c_handle, FXOS8700_REG_STATUS, buffer, 12) == 12) {
            // Combine MSB and LSB for accelerometer data
            data->accel_x = (int16_t)((buffer[0] << 8) | buffer[1]) >> 2;
            data->accel_y = (int16_t)((buffer[2] << 8) | buffer[3]) >> 2;
            data->accel_z = (int16_t)((buffer[4] << 8) | buffer[5]) >> 2;

