    int16_t accel_x;
    int16_t accel_y;
    int16_t accel_z;
    int16_t mag_x;
    int16_t mag_y;
    int16_t mag_z;
} sensor_data_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the FXOS8700 sensor
int init_fxos8700() {
    // Check WHOAMI register
    int whoami = i2cReadByteData(i2c_handle, FXOS8700_REG_WHOAMI);
    if (whoami < 0) {
        fprintf(stderr, "Error reading WHOAMI register: %s\n", strerror(errno));
        return -1;
    }
    if (whoami != FXOS8700_WHOAMI_VALUE) {
        fprintf(stderr, "WHOAMI value mismatch: 0x%02X (expected 0x%02X)\n", whoami, FXOS8700_WHOAMI_VALUE);
        return -1;
    }
    printf("WHOAMI check passed. Device ID: 0x%02X\n", whoami);

    // Configure accelerometer: Active mode, 100 Hz ODR
    if (i2cWriteByteData(i2c_handle, FXOS8700_REG_CTRL_REG1, 0x01 | (0x02 << 3)) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1: %s\n", strerror(errno));
        return -1;
    }

    // Configure magnetometer: Hybrid mode, 80 Hz ODR
    if (i2cWriteByteData(i2c_handle, FXOS8700_REG_M_CTRL_REG1, 0x1F) < 0) {
        fprintf(stderr, "Error writing to M_CTRL_REG1: %s\n", strerror(errno));
