#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define WINDOW_SIZE 5000 // 5 seconds in milliseconds
#define SAMPLE_INTERVAL 1 // 1 millisecond

static volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main(int argc, char *argv[]) {
    int threshold;
    int high_count;
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];

    // Check command-line argument
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return 1;
    }

    char *endptr;
    threshold = strtol(argv[1], &endptr, 10);

    if (*endptr != '\0' || threshold <= 0) {
        fprintf(stderr, "Error: Invalid threshold value. Must be a positive integer.\n");
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Monitoring GPIO %d for sound events. Threshold: %d\n", GPIO_PIN, threshold);

    while (running) {
        high_count = 0;
        current_time = time(NULL);
        time_info = localtime(&current_time);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

        // Sample the GPIO pin for the window
        for (int i = 0; i < WINDOW_SIZE; i++) {
            if (gpioRead(GPIO_PIN) == 1) {
                high_count++;
            }
            gpioDelay(SAMPLE_INTERVAL); // Delay for 1 millisecond
        }

        // Check if the threshold is exceeded
        if (high_count > threshold) {
            printf("%s ALERT: High readings detected (%d > %d)\n", timestamp, high_count, threshold);
        } else {
            printf("%s Status: No significant sound detected (%d <= %d)\n", timestamp, high_count, threshold);
        }

        gpioDelay(1000); // Pause for 1 second
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

