#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for door locks
#define DOOR_A_GPIO 17
#define DOOR_B_GPIO 27

// Define the log file name
#define LOG_FILE "access_log.txt"

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int generate_security_code();
int read_user_input(char *input_buffer, size_t buffer_size);
int compare_codes(int generated_code, const char *user_input);
int log_access(int security_code);
int lock_door(int gpio_pin);
int unlock_door(int gpio_pin);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        program_running = 0;
        fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
    }
}

// Function to generate a random security code
int generate_security_code() {
    return (rand() % 900000) + 100000; // Generate a number between 100000 and 999999
}

// Function to read user input from stdin
int read_user_input(char *input_buffer, size_t buffer_size) {
    if (fgets(input_buffer, buffer_size, stdin) == NULL) {
        perror("Error reading input");
        return -1; // Indicate an error
    }

