#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define PWM_PIN 18
#define TCP_PORT 12345
#define SHARED_SECRET "MySecretKey"
#define MOTION_DETECT_MSG "MOTION_DETECTED:"
#define SAMPLE_INTERVAL_MS 20
#define PLAYBACK_DURATION_S 5
#define PWM_FREQUENCY_MIN 200
#define PWM_FREQUENCY_MAX 2000
#define PWM_RANGE 1000

// Global variables
int i2c_handle;
int tcp_socket;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_mpr121();
int read_touch_data(unsigned short *touch_data);
int parse_tcp_message(int socket, char *message, size_t message_size);
int authenticate_message(const char *message);
int map_touch_to_frequency(unsigned short touch_data);
int play_tone(int frequency);
int log_frequency(int frequency);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, terminating...\n");
}

// Initialize MPR121
int init_mpr121() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error: Soft reset failed: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure electrodes (example: enable all 12 electrodes)
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, 0x5E + (i * 2), 0x0C) < 0) { // Touch threshold
            fprintf(stderr, "Error: Setting touch threshold for electrode %d failed: %s\n", i, strerror(errno));
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, 0x5F + (i * 2), 0x06) < 0) { // Release threshold
            fprintf(stderr, "Error: Setting release threshold for electrode %d failed: %s\n", i, strerror(errno));
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, 0x5C + (i * 2), 0x01) < 0) { // Enable electrode
            fprintf(stderr, "Error: Enabling electrode %d failed: %s\n", i, strerror(errno));
            return -1;
        }
    }

    // Configure baseline filtering
    if (i2cWriteByteData(i2c_handle, 0x2B, 0x01) < 0) {
        fprintf(stderr, "Error: Setting baseline filtering failed: %s\n", strerror(errno));
        return -1;
    }

    // Configure touch and release thresholds
    if (i2cWriteByteData(i2c_handle, 0x41, 0x30) < 0) {
        fprintf(stderr, "Error: Setting touch threshold failed: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x42, 0x10) < 0) {
        fprintf(stderr, "Error: Setting release threshold failed: %s\n", strerror(errno));
        return -1;
    }

    // Enable electrode sensing
    if (i2cWriteByteData(i2c_handle, 0x5B, 0x0F) < 0) {
        fprintf(stderr, "Error: Enabling electrode sensing failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read touch data from MPR121
int read_touch_data(unsigned short *touch_data) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read touch data: %s\n", strerror(errno));
        return -1;
    }
    *touch_data = (buf[1] << 8) | buf[0];
    return 0;
}

// Parse TCP message
int parse_tcp_message(int socket, char *message, size_t message_size) {
    ssize_t bytes_received = recv(socket, message, message_size - 1, 0);
    if (bytes_received < 0) {
        fprintf(stderr, "Error: Failed to receive data: %s\n", strerror(errno));
        return -1;
    } else if (bytes_received == 0) {
        fprintf(stderr, "Error: Connection closed by client.\n");
        return -1;
    }
    message[bytes_received] = '\0';
    return 0;
}

// Authenticate message
int authenticate_message(const char *message) {
    if (strstr(message, MOTION_DETECT_MSG) == NULL) {
        fprintf(stderr, "Error: Invalid message format.\n");
        return -1;
    }
    if (strstr(message, SHARED_SECRET) == NULL) {
        fprintf(stderr, "Error: Invalid shared secret.\n");
        return -1;
    }
    return 0;
}

// Map touch data to frequency
int map_touch_to_frequency(unsigned short touch_data) {
    // Simple mapping: touch data to frequency range
    int frequency = PWM_FREQUENCY_MIN + (touch_data % (PWM_FREQUENCY_MAX - PWM_FREQUENCY_MIN));
    return frequency;
}

// Play tone using PWM
int play_tone(int frequency) {
    if (frequency < PWM_FREQUENCY_MIN || frequency > PWM_FREQUENCY_MAX) {
        fprintf(stderr, "Error: Frequency out of range.\n");
        return -1;
    }

    gpioSetPWMfrequency(PWM_PIN, frequency);
    gpioPWM(PWM_PIN, PWM_RANGE / 2); // 50% duty cycle
    gpioDelay(PLAYBACK_DURATION_S * 1000); // Play for 5 seconds
    gpioPWM(PWM_PIN, 0); // Stop PWM
    return 0;
}

// Log frequency to file
int log_frequency(int frequency) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d\n", timestamp, frequency);
    fflush(log_file); // Ensure data is written to file immediately
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (tcp_socket >= 0) {
        close(tcp_socket);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioPWM(PWM_PIN, 0); // Stop PWM
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Initialize MPR121
    if (init_mpr121() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed.\n");
        cleanup();
        return 1;
    }

    // Configure PWM pin
    gpioSetMode(PWM_PIN, PI_OUTPUT);
    gpioSetPWMrange(PWM_PIN, PWM_RANGE);

    // Open log file
    log_file = fopen("frequency_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

