// LSM303DLHC I2C address
#define LSM303_ADDR 0x1E

// LSM303DLHC register addresses
#define CRA_REG_M 0x00
#define CRB_REG_M 0x01
#define MR_REG_M 0x02
#define OUT_X_H_M 0x03
#define OUT_X_L_M 0x04
#define OUT_Z_H_M 0x05
#define OUT_Z_L_M 0x06
#define OUT_Y_H_M 0x07
#define OUT_Y_L_M 0x08

// GPIO pin for LED
#define LED_PIN 17

// PWM frequency
#define PWM_FREQUENCY 1000

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_lsm303();
int read_magnetometer(int16_t *x, int16_t *y, int16_t *z);
float calculate_magnitude(int16_t x, int16_t y, int16_t z);
void set_led_brightness(float magnitude);
void signal_handler(int signal);
void log_error(const char *message);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Function to log errors to a file
void log_error(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

// Function to initialize the LSM303DLHC magnetometer
int init_lsm303() {
    // Configure CRA_REG_M (0x00): 75 Hz data rate
    if (i2cWriteByteData(i2c_handle, CRA_REG_M, 0x18) < 0) {
        log_error("Failed to write to CRA_REG_M");
        return -1;
    }

    // Configure CRB_REG_M (0x01): Gain = +/- 1.3 Gauss
    if (i2cWriteByteData(i2c_handle, CRB_REG_M, 0x20) < 0) {
        log_error("Failed to write to CRB_REG_M");
        return -1;
    }

    // Configure MR_REG_M (0x02): Continuous conversion mode
    if (i2cWriteByteData(i2c_handle, MR_REG_M, 0x00) < 0) {
        log_error("Failed to write to MR_REG_M");
        return -1;
    }

    return 0;
}

// Function to read magnetometer data
int read_magnetometer(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    // Read 6 bytes of data starting from OUT_X_H_M (0x03)
    if (i2cReadI2CBlockData(i2c_handle, OUT_X_H_M, buffer, 6) != 6) {
        log_error("Failed to read magnetometer data");
        return -1;
    }

    // Combine high and low bytes for each axis
    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *z = (int16_t)((buffer[2] << 8) | buffer[3]);
    *y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Function to calculate the magnitude of the magnetic field
float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    return sqrt(x * x + y * y + z * z);
}

// Function to set the LED brightness using hardware PWM
void set_led_brightness(float magnitude) {
    // Normalize the magnitude to a range of 0-1
    float normalized_magnitude = magnitude / 1000.0; // Assuming max magnitude is around 1000 Gauss
    if (normalized_magnitude > 1.0) normalized_magnitude = 1.0;
    if (normalized_magnitude < 0.0) normalized_magnitude = 0.0;

    // Set the PWM duty cycle (0-255)
    int duty_cycle = (int)(normalized_magnitude * 255.0);
    gpioPWM(LED_PIN, duty_cycle);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("magnetometer_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, LSM303_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize LSM303DLHC
    if (init_lsm303() < 0) {
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Configure LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(LED_PIN, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(LED_PIN, 255);

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;
    float magnitude;

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        if (read_magnetometer(&x, &y, &z) == 0) {
            // Calculate magnitude
            magnitude = calculate_magnitude(x, y, z);

            // Set LED brightness
            set_led_brightness(magnitude);

            // Print magnitude to console
            printf("Magnitude: %.2f Gauss\n", magnitude);
        } else {
            log_error("Failed to read magnetometer data in main loop");
        }

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Clean up
    gpioPWM(LED_PIN, 0); // Turn off LED
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

