#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08

// Configuration values
#define CONFIG_A_VALUE 0x70 // 8-average, 15 Hz, normal measurement
#define CONFIG_B_VALUE 0xA0 // Gain = 5
#define MODE_CONTINUOUS 0x00

// Number of samples for hard-iron offset calculation
#define NUM_SAMPLES 100

// Structure to hold magnetometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} magnetometer_data_t;

// Structure to hold hard-iron offsets
typedef struct {
    float x_offset;
    float y_offset;
    float z_offset;
} hard_iron_offsets_t;

// Global variables
int i2c_handle;
magnetometer_data_t raw_data[NUM_SAMPLES];
int sample_index = 0;
hard_iron_offsets_t offsets = {0.0, 0.0, 0.0};
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int configure_hmc5883l();
int read_magnetometer_data(magnetometer_data_t *data);
void calculate_hard_iron_offsets(hard_iron_offsets_t *offsets);
void apply_hard_iron_offsets(magnetometer_data_t *data, const hard_iron_offsets_t *offsets);
void print_magnetometer_data(const magnetometer_data_t *data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0); // Bus 1, address 0x1E, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Configure HMC5883L
int configure_hmc5883l() {
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, CONFIG_A_VALUE) < 0) {
        fprintf(stderr, "Failed to write to CONFIG_A register\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, CONFIG_B_VALUE) < 0) {
        fprintf(stderr, "Failed to write to CONFIG_B register\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, MODE_CONTINUOUS) < 0) {
        fprintf(stderr, "Failed to write to MODE register\n");
        return -1;
    }

    return 0;
}

// Read magnetometer data
int read_magnetometer_data(magnetometer_data_t *data) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, buffer, 6) != 6) {
        fprintf(stderr, "Failed to read magnetometer data\n");
        return -1;
    }

    data->x = (int16_t)((buffer[0] << 8) | buffer[1]);
    data->z = (int16_t)((buffer[2] << 8) | buffer[3]);
    data->y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Calculate hard-iron offsets
void calculate_hard_iron_offsets(hard_iron_offsets_t *offsets) {
    float x_sum = 0.0, y_sum = 0.0, z_sum = 0.0;

    for (int i = 0; i < NUM_SAMPLES; i++) {
        x_sum += raw_data[i].x;
        y_sum += raw_data[i].y;
        z_sum += raw_data[i].z;
    }

    offsets->x_offset = x_sum / NUM_SAMPLES;
    offsets->y_offset = y_sum / NUM_SAMPLES;
    offsets->z_offset = z_sum / NUM_SAMPLES;

    printf("Hard-iron offsets: X=%.2f, Y=%.2f, Z=%.2f\n", offsets->x_offset, offsets->y_offset, offsets->z_offset);
}

// Apply hard-iron offsets
void apply_hard_iron_offsets(magnetometer_data_t *data, const hard_iron_offsets_t *offsets) {
    data->x -= offsets->x_offset;
    data->y -= offsets->y_offset;
    data->z -= offsets->z_offset;
}

// Print magnetometer data
void print_magnetometer_data(const magnetometer_data_t *data) {
    printf("X: %d, Y: %d, Z: %d\n", data->x, data->y, data->z);
}

// Cleanup resources
void cleanup() {
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() < 0) {
        return 1;
    }

    // Configure HMC5883L
    if (configure_hmc5883l() < 0) {
        cleanup();
        return 1;
    }

    // Collect data for hard-iron offset calculation
    printf("Collecting data for hard-iron offset calculation...\n");
    for (int i = 0; i < NUM_SAMPLES; i++) {
        if (read_magnetometer_data(&raw_data[i]) < 0) {
            fprintf(stderr, "Error reading data during offset calculation\n");
            cleanup();
            return 1;
        }
        gpioDelay(10); // Small delay between readings
    }

    // Calculate hard-iron offsets
    calculate_hard_iron_offsets(&offsets);

    // Main loop
    magnetometer_data_t current_data;
    while (!terminate) {
        if (read_magnetometer_data(&current_data) == 0) {
            apply_hard_iron_offsets(&current_data, &offsets);
            print_magnetometer_data(&current_data);
        } else {
            fprintf(stderr, "Error reading magnetometer data\n");
        }

        gpioDelay(500); // 500 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

