        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Function to initialize LSM303D
int init_lsm303d() {
    // Verify device ID
    int who_am_i = i2cReadByteData(i2c_fd, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %s\n", strerror(errno));
        return -1;
    }
    if (who_am_i != 0x49) {
        fprintf(stderr, "Incorrect WHO_AM_I value: 0x%02X\n", who_am_i);
        return -1;
    }

    // Enable accelerometer, 100Hz data rate
    if (i2cWriteByteData(i2c_fd, CTRL_REG1_A, 0x57) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1_A: %s\n", strerror(errno));
        return -1;
    }

    // Set full-scale range to +/- 2g
    if (i2cWriteByteData(i2c_fd, CTRL_REG4_A, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4_A: %s\n", strerror(errno));
        return -1;
    }

    // Configure interrupt 1
    if (i2cWriteByteData(i2c_fd, INT1_CFG, 0x2A) < 0) {
        fprintf(stderr, "Error writing to INT1_CFG: %s\n", strerror(errno));
        return -1;
    }

    // Set interrupt threshold to 2000 mg
    if (i2cWriteByteData(i2c_fd, INT1_THS, 0x7D) < 0) {
        fprintf(stderr, "Error writing to INT1_THS: %s\n", strerror(errno));
        return -1;
    }

    // Set interrupt duration to zero for immediate triggering
    if (i2cWriteByteData(i2c_fd, INT1_DURATION, 0x00) < 0) {
        fprintf(stderr, "Error writing to INT1_DURATION: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read accelerometer data
int read_lsm303d(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_fd, OUT_X_L_A, buffer, 6) < 0) {
        fprintf(stderr, "Error reading accelerometer data: %s\n", strerror(errno));
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Function to add a sample to the circular buffer
void add_to_buffer(struct timeval timestamp, int16_t x, int16_t y, int16_t z) {
    buffer[buffer_index].timestamp = timestamp;
    buffer[buffer_index].x = x;
    buffer[buffer_index].y = y;
    buffer[buffer_index].z = z;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to dump the contents of the circular buffer
void dump_buffer() {
    printf("\n--- Dump of last %d samples ---\n", BUFFER_SIZE);
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE;
        printf("%ld.%06ld: X=%.2f mg, Y=%.2f mg, Z=%.2f mg\n",
               buffer[index].timestamp.tv_sec, buffer[index].timestamp.tv_usec,
               buffer[index].x * SENSITIVITY, buffer[index].y * SENSITIVITY, buffer[index].z * SENSITIVITY);
    }
    printf("--- End of dump ---\n\n");
}

// Interrupt handler function
void interrupt_handler(int signum) {
    struct timeval timestamp;
    gettimeofday(&timestamp, NULL);

    int16_t x, y, z;
    if (read_lsm303d(&x, &y, &z) == 0) {
        add_to_buffer(timestamp, x, y, z);
    } else {
        fprintf(stderr, "Failed to read accelerometer data in interrupt handler.\n");
    }

    dump_buffer();
}

// Signal handler function
void signal_handler(int signum) {
    terminate = 1;
    printf("Signal received, exiting...\n");
}

// Cleanup function
void cleanup() {
    // Disable accelerometer (set CTRL_REG1_A to 0x00)
    if (i2c_fd >= 0) {
        i2cWriteByteData(i2c_fd, CTRL_REG1_A, 0x00);
    }

    // Close I2C file descriptor
    if (i2c_fd >= 0) {
        i2cClose(i2c_fd);
    }

    // Release GPIO line
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }

    // Close GPIO chip
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() < 0) {
        cleanup();
        return 1;
    }

    // Initialize LSM303D
    if (init_lsm303d() < 0) {
        cleanup();
        return 1;
    }

    printf("LSM303D monitor started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read accelerometer data
        int16_t x, y, z;
        struct timeval timestamp;
        gettimeofday(&timestamp, NULL);

        if (read_lsm303d(&x, &y, &z) == 0) {
            add_to_buffer(timestamp, x, y, z);
        } else {
            fprintf(stderr, "Failed to read accelerometer data.\n");
        }

        // Check for interrupt
        struct gpiod_line_event event;
        int ret = gpiod_line_event_wait(gpio_line, -1); // Wait indefinitely
        if (ret < 0) {
            fprintf(stderr, "Error waiting for GPIO event: %s\n", strerror(errno));
            break;
        }

        event = gpiod_line_event_read(gpio_line);
        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            interrupt_handler(0); // Simulate interrupt
        } else if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            //printf("Falling edge detected.\n");
        } else {
            fprintf(stderr, "Unknown GPIO event type: %d\n", event.event_type);
        }

        usleep(10000); // 10ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

