#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for solenoids
#define SOLENOID_1_GPIO 17
#define SOLENOID_2_GPIO 27

// Global variable to track the active solenoid
int active_solenoid = 0;

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Set both solenoids LOW
    gpioWrite(SOLENOID_1_GPIO, 0);
    gpioWrite(SOLENOID_2_GPIO, 0);

    // Terminate pigpio library
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(SOLENOID_1_GPIO, PI_OUTPUT);
    gpioSetMode(SOLENOID_2_GPIO, PI_OUTPUT);

    // Set both solenoids LOW initially
    gpioWrite(SOLENOID_1_GPIO, 0);
    gpioWrite(SOLENOID_2_GPIO, 0);

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Solenoid control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Activate the active solenoid
        if (active_solenoid == 0) {
            gpioWrite(SOLENOID_1_GPIO, 1);
            gpioWrite(SOLENOID_2_GPIO, 0);
            active_solenoid = 1;
        } else {
            gpioWrite(SOLENOID_1_GPIO, 0);
            gpioWrite(SOLENOID_2_GPIO, 1);
            active_solenoid = 0;
        }

        // Delay for 500 milliseconds
        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = 500 * 1000 * 1000; // 500 milliseconds
        nanosleep(&delay, NULL);
    }

    return 0;
}

