#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_GPIO 17
#define RELAY2_GPIO 27

// Define UART ports
#define UART1_DEVICE "/dev/serial0"
#define UART2_DEVICE "/dev/serial1"

// Define baud rate
#define BAUD_RATE 9600

// Define expected code
#define EXPECTED_CODE "123456"

// Define timeout in seconds
#define TIMEOUT_SEC 5

// Global variables
int uart1_handle = -1;
int uart2_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int initialize_uart(const char *device);
int read_code(int uart_handle, char *code, int max_len);
int validate_code(const char *code, const char *expected_code);
int control_relay(int gpio_pin, int state);
void log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(RELAY1_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY2_GPIO, PI_OUTPUT);

    // Ensure relays are initially locked (LOW)
    gpioWrite(RELAY1_GPIO, 0);
    gpioWrite(RELAY2_GPIO, 0);

    return 0;
}

// Initialize UART
int initialize_uart(const char *device) {
    int handle = serOpen(device, BAUD_RATE, 0); // 0 for default flags
    if (handle < 0) {
        char error_message[100];
        snprintf(error_message, sizeof(error_message), "Failed to open UART %s: %d", device, handle);
        log_error(error_message);
        return -1;
    }
    return handle;
}

// Read code from UART with timeout
int read_code(int uart_handle, char *code, int max_len) {
    int i = 0;
    int c;
    time_t start_time = time(NULL);

    while (i < max_len) {
        c = serReadByte(uart_handle);
        if (c >= 0) {
            if (c >= '0' && c <= '9') {
                code[i++] = (char)c;
                code[i] = '\0'; // Null-terminate the string
                start_time = time(NULL); // Reset timeout
            } else {
                // Reset code if non-digit character is received
                code[0] = '\0';
                i = 0;
            }
        } else {
            // Check for timeout
            if (time(NULL) - start_time >= TIMEOUT_SEC) {
                code[0] = '\0'; // Clear code on timeout
                return -1; // Timeout error
            }
            gpioDelay(100); // Small delay to avoid busy-waiting
        }
    }

    return 0; // Success
}

// Validate code
int validate_code(const char *code, const char *expected_code) {
    return (strcmp(code, expected_code) == 0) ? 1 : 0;
}

// Control relay
int control_relay(int gpio_pin, int state) {
    if (gpioWrite(gpio_pin, state) != 0) {
        char error_message[50];
        snprintf(error_message, sizeof(error_message), "Failed to write to GPIO %d", gpio_pin);
        log_error(error_message);
        return -1;
    }
    return 0;
}

// Log error to stderr
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(stderr, "[%d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");

    // Ensure relays are locked on exit
    control_relay(RELAY1_GPIO, 0);
    control_relay(RELAY2_GPIO, 0);

    // Close UART ports
    if (uart1_handle >= 0) {
        serClose(uart1_handle);
    }
    if (uart2_handle >= 0) {
        serClose(uart2_handle);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize UART ports
    uart1_handle = initialize_uart(UART1_DEVICE);
    uart2_handle = initialize_uart(UART2_DEVICE);

    if (uart1_handle < 0 || uart2_handle < 0) {
        cleanup();
        return 1;
    }

    char code1[7] = {0}; // Buffer to store code from UART1 (6 digits + null terminator)
    char code2[7] = {0}; // Buffer to store code from UART2 (6 digits + null terminator)

    printf("Door lock authentication system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read code from UART1
        if (read_code(uart1_handle, code1, sizeof(code1)) == 0) {
            printf("Code received from UART1: %s\n", code1);
        } else {
            // Timeout or error reading from UART1
            //log_error("Timeout or error reading from UART1");
        }

        // Read code from UART2
        if (read_code(uart2_handle, code2, sizeof(code2)) == 0) {
            printf("Code received from UART2: %s\n", code2);
        } else {
            // Timeout or error reading from UART2
            //log_error("Timeout or error reading from UART2");
        }

        // Validate codes
        if (strlen(code1) == 6 && strlen(code2) == 6) {
            if (validate_code(code1, EXPECTED_CODE) && validate_code(code2, EXPECTED_CODE)) {
                printf("Codes match! Unlocking doors...\n");

                // Control relays to unlock doors
                if (control_relay(RELAY1_GPIO, 1) == 0 && control_relay(RELAY2_GPIO, 1) == 0) {
                    gpioDelay(2000); // Wait for 2 seconds

                    // Control relays to lock doors
                    if (control_relay(RELAY1_GPIO, 0) == 0 && control_relay(RELAY2_GPIO, 0) == 0) {
                        printf("Doors locked.\n");
                    } else {
                        log_error("Failed to lock doors");
                    }
                } else {
                    log_error("Failed to unlock doors");
                }
            } else {
                printf("Codes do not match.\n");
            }
        }

        gpioDelay(100); // Small delay to avoid busy-waiting
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

