#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

// Define GPIO pins
#define PIR_SENSOR_PIN 4
#define RELAY_PIN 17

// Define constants
#define RELAY_ON_TIME_MS 1000
#define MOTION_THRESHOLD_MS 10000
#define POLL_INTERVAL_MS 50

// Global variables
static volatile int running = 1;
static int pigpio_initialized = 0;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
void activate_relay();
void deactivate_relay();
void log_event(int priority, const char *message);
void failsafe();
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        log_event(LOG_INFO, "Received shutdown signal.");
        running = 0;
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_event(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    pigpio_initialized = 1;

    if (gpioSetMode(PIR_SENSOR_PIN, PI_INPUT) != 0) {
        log_event(LOG_ERR, "Failed to set PIR sensor pin as input");
        gpioTerminate();
        pigpio_initialized = 0;
        return -1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        log_event(LOG_ERR, "Failed to set relay pin as output");
        gpioTerminate();
        pigpio_initialized = 0;
