#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_GPIO 4
#define RELAY2_GPIO 17
#define RELAY3_GPIO 27
#define RELAY4_GPIO 22

// Define irrigation cycle parameters
#define IRRIGATION_DURATION 300 // seconds (5 minutes)
#define PAUSE_DURATION 60      // seconds (1 minute)
#define NUM_RELAYS 4

// Global variables
static volatile sig_atomic_t terminate = 0;
static int relay_states[NUM_RELAYS] = {0, 0, 0, 0}; // 0 = OFF, 1 = ON
static int current_relay = 0;

// Function prototypes
int initialize_gpio();
void cleanup_gpio();
void activate_relay(int gpio_pin);
void deactivate_relay(int gpio_pin);
void irrigation_cycle();
void signal_handler(int signal);
void log_message(int priority, const char *message);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        log_message(LOG_INFO, "Received signal, shutting down...");
        terminate = 1;
    }
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    // Set GPIO pins as outputs and initialize to HIGH (OFF)
    gpioSetMode(RELAY1_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY2_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY3_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY4_GPIO, PI_OUTPUT);

    gpioWrite(RELAY1_GPIO, 1);
    gpioWrite(RELAY2_GPIO, 1);
    gpioWrite(RELAY3_GPIO, 1);
    gpioWrite(RELAY4_GPIO, 1);

    log_message(LOG_INFO, "GPIO initialisation complete");
    return 0;
}

// Function to cleanup GPIO pins
void cleanup_gpio() {
    // Deactivate all relays
    deactivate_relay(RELAY1_GPIO);
    deactivate_relay(RELAY2_GPIO);
    deactivate_relay(RELAY3_GPIO);
    deactivate_relay(RELAY4_GPIO);

    // Terminate pigpio
    gpioTerminate();
    log_message(LOG_INFO, "GPIO cleanup complete");
}

// Function to activate a relay
void activate_relay(int gpio_pin) {
    if (gpioWrite(gpio_pin, 0) != 0) {
        char message[100];
        snprintf(message, sizeof(message), "Failed to activate relay on GPIO %d", gpio_pin);
        log_message(LOG_ERR, message);
    } else {
        char message[100];
        snprintf(message, sizeof(message), "Relay on GPIO %d activated", gpio_pin);
        log_message(LOG_INFO, message);
    }
}

// Function to deactivate a relay
void deactivate_relay(int gpio_pin) {
    if (gpioWrite(gpio_pin, 1) != 0) {
        char message[100];
        snprintf(message, sizeof(message), "Failed to deactivate relay on GPIO %d", gpio_pin);
        log_message(LOG_ERR, message);
    } else {
        char message[100];
        snprintf(message, sizeof(message), "Relay on GPIO %d deactivated", gpio_pin);
        log_message(LOG_INFO, message);
    }
}

// Function to perform the irrigation cycle
void irrigation_cycle() {
    while (!terminate) {
        // Activate the current relay
        activate_relay(RELAY1_GPIO + current_relay);
        relay_states[current_relay] = 1;

        // Wait for the irrigation duration
        time_sleep(IRRIGATION_DURATION);

        // Deactivate the current relay
        deactivate_relay(RELAY1_GPIO + current_relay);
        relay_states[current_relay] = 0;

        // Increment the current relay
        current_relay = (current_relay + 1) % NUM_RELAYS;

        // Wait for the pause duration
        time_sleep(PAUSE_DURATION);
    }
}

// Function to log messages to syslog
void log_message(int priority, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    char log_entry[200];
    snprintf(log_entry, sizeof(log_entry), "%s: %s", timestamp, message);

    syslog(priority, "%s", log_entry);
    printf("%s\n", log_entry); // Also print to console
}

int main() {
    // Open syslog
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_message(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    // Start the irrigation cycle
    irrigation_cycle();

    // Cleanup GPIO
    cleanup_gpio();

    // Close syslog
    closelog();

    return 0;
}

