#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <sys/timerfd.h>
#include <sys/stat.h>
#include <sys/types.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_ACCEL_YOUT_H 0x3D
#define MPU6050_ACCEL_ZOUT_H 0x3F
#define MPU6050_ACCEL_CONFIG 0x1C

// Accelerometer sensitivity scale factor (±2g)
#define ACCEL_SCALE 16384.0f

// Circular buffer size
#define BUFFER_SIZE 100

// Global variables
static int i2c_fd = -1;
static int timer_fd = -1;
static volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accel_data_t;

// Circular buffer
accel_data_t accel_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_i2c(int address);
int init_mpu6050(int fd);
int read_accel_data(int fd, float *x, float *y, float *z);
void timer_handler(int sig, siginfo_t *si, void *uc);
void signal_handler(int sig);
int create_driver_files();
int remove_driver_files();

// Function to initialize I2C
int init_i2c(int address) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to initialize MPU6050
int init_mpu6050(int fd) {
    // Wake up the MPU6050 (clear sleep mode bit)
    if (i2c_smbus_write_byte_data(fd, MPU6050_PWR_MGMT_1, 0) < 0) {
        perror("Error writing to PWR_MGMT_1 register");
        return -1;
    }

    // Set accelerometer range to ±2g
    if (i2c_smbus_write_byte_data(fd, MPU6050_ACCEL_CONFIG, 0x00) < 0) {
        perror("Error writing to ACCEL_CONFIG register");
        return -1;
    }

    return 0;
}

// Function to read accelerometer data
int read_accel_data(int fd, float *x, float *y, float *z) {
    int16_t raw_x, raw_y, raw_z;

    // Read raw accelerometer data
    raw_x = i2c_smbus_read_word_data(fd, MPU6050_ACCEL_XOUT_H);
    if (raw_x < 0) {
        perror("Error reading accelerometer X data");
        return -1;
    }
    raw_y = i2c_smbus_read_word_data(fd, MPU6050_ACCEL_YOUT_H);
    if (raw_y < 0) {
        perror("Error reading accelerometer Y data");
        return -1;
    }
    raw_z = i2c_smbus_read_word_data(fd, MPU6050_ACCEL_ZOUT_H);
    if (raw_z < 0) {
        perror("Error reading accelerometer Z data");
        return -1;
    }

    // Convert raw data to g-force units
    *x = (float)raw_x / ACCEL_SCALE;
    *y = (float)raw_y / ACCEL_SCALE;
    *z = (float)raw_z / ACCEL_SCALE;

    return 0;
}

// Timer handler function
void timer_handler(int sig, siginfo_t *si, void *uc) {
    float x, y, z;

    // Read accelerometer data
    if (read_accel_data(i2c_fd, &x, &y, &z) == 0) {
        // Store data in circular buffer
        accel_buffer[buffer_index].x = x;
        accel_buffer[buffer_index].y = y;
        accel_buffer[buffer_index].z = z;

        // Increment buffer index (wrap around)
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        // Update driver files
        if (create_driver_files() != 0) {
            fprintf(stderr, "Error updating driver files.\n");
        }
    } else {
        fprintf(stderr, "Error reading accelerometer data in timer handler.\n");
    }

    // Read and discard the timer value
    uint64_t expirations;
    ssize_t s = read(timer_fd, &expirations, sizeof(expirations));
    if (s != sizeof(expirations)) {
        perror("Error reading timer value");
    }
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to create driver files
int create_driver_files() {
    char buffer[256];
    int fd;

    // Create /sys/kernel/mpu6050_accel/latest
    snprintf(buffer, sizeof(buffer), "/sys/kernel/mpu6050_accel/latest");
    fd = open(buffer, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        perror("Error creating /sys/kernel/mpu6050_accel/latest");
        return -1;
    }

    // Write the latest accelerometer data to the file
    snprintf(buffer, sizeof(buffer), "%.3f,%.3f,%.3f\n",
             accel_buffer[buffer_index].x,
             accel_buffer[buffer_index].y,
             accel_buffer[buffer_index].z);
    if (write(fd, buffer, strlen(buffer)) < 0) {
        perror("Error writing to /sys/kernel/mpu6050_accel/latest");
        close(fd);
        return -1;
    }

    close(fd);

    return 0;
}

// Function to remove driver files
int remove_driver_files() {
    if (remove("/sys/kernel/mpu6050_accel/latest") != 0) {
        perror("Error removing /sys/kernel/mpu6050_accel/latest");
        return -1;
    }
    return 0;
}

int main() {
    struct sigevent sev;
    struct itimerspec its;
    struct sigaction sa;

    // Register signal handlers
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Error setting signal handler");
        return 1;
    }

    // Initialize I2C
    i2c_fd = init_i2c(MPU6050_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "MPU6050 not found. Exiting.\n");
        return 1;
    }

    // Initialize MPU6050
    if (init_mpu6050(i2c_fd) < 0) {
        fprintf(stderr, "MPU6050 initialization failed. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Create timer
    timer_fd = timerfd_create(CLOCK_MONOTONIC, 0);
    if (timer_fd < 0) {
        perror("Error creating timer");
        close(i2c_fd);
        return 1;
    }

    // Configure timer event
    sev.sigev_notify = SIGEV_SIGNAL;
    sev.sigev_signo = SIGRTMIN;
    sev.sigev_value.sival_ptr = &timer_fd;
    if (timerfd_settime(timer_fd, 0, &its, NULL) == -1) {
        perror("Error setting timer time");
        close(timer_fd);
        close(i2c_fd);
        return 1;
    }

    // Set timer interval to 10ms (100Hz)
    its.it_value.tv_sec = 0;
    its.it_value.tv_nsec = 10000000; // 10ms
    its.it_interval.tv_sec = 0;
    its.it_interval.tv_nsec = 10000000; // 10ms

    if (timerfd_settime(timer_fd, 0, &its, NULL) == -1) {
        perror("Error setting timer time");
        close(timer_fd);
        close(i2c_fd);
        return 1;
    }

    // Create driver files
    if (create_driver_files() != 0) {
        fprintf(stderr, "Error creating driver files.\n");
        close(timer_fd);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        pause(); // Wait for signals
    }

    // Cleanup
    printf("Cleaning up...\n");
    close(timer_fd);
    close(i2c_fd);
    remove_driver_files();

    return 0;
}

