#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_GPIO 18
#define RELAY2_GPIO 23
#define RELAY3_GPIO 24
#define RELAY4_GPIO 25

// Define prime numbers for the intervals
#define INTERVAL1 2
#define INTERVAL2 3
#define INTERVAL3 5
#define INTERVAL4 7

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO pins as outputs
    if (gpioSetMode(RELAY1_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RELAY1_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(RELAY2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RELAY2_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(RELAY3_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RELAY3_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(RELAY4_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RELAY4_GPIO);
        gpioTerminate();
        return -1;
    }

    // Ensure all relays are initially off
    gpioWrite(RELAY1_GPIO, 0);
    gpioWrite(RELAY2_GPIO, 0);
    gpioWrite(RELAY3_GPIO, 0);
    gpioWrite(RELAY4_GPIO, 0);

    return 0;
}

// Function to toggle a relay
void toggle_relay(int gpio_pin) {
    int current_state = gpioRead(gpio_pin);
    if (current_state == PI_BAD_GPIO) {
        fprintf(stderr, "Error reading GPIO%d state\n", gpio_pin);
        return;
    }

    int new_state = !current_state;
    if (gpioWrite(gpio_pin, new_state) != 0) {
        fprintf(stderr, "Failed to write to GPIO%d\n", gpio_pin);
    }
}

// Function to calculate the next toggle time
long long calculate_next_toggle_time(long long current_time, int interval) {
    return current_time + interval * 1000000; // Convert seconds to microseconds
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Get initial time
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    long long current_time = ts.tv_sec * 1000000 + ts.tv_nsec / 1000; // Convert to microseconds

    // Main loop
    while (program_running) {
        // Calculate next toggle times
        long long next_toggle_time1 = calculate_next_toggle_time(current_time, INTERVAL1);
        long long next_toggle_time2 = calculate_next_toggle_time(current_time, INTERVAL2);
        long long next_toggle_time3 = calculate_next_toggle_time(current_time, INTERVAL3);
        long long next_toggle_time4 = calculate_next_toggle_time(current_time, INTERVAL4);

        // Get current time
        clock_gettime(CLOCK_MONOTONIC, &ts);
        current_time = ts.tv_sec * 1000000 + ts.tv_nsec / 1000;

        // Toggle relays based on next toggle times
        if (current_time >= next_toggle_time1) {
            toggle_relay(RELAY1_GPIO);
            current_time = next_toggle_time1; // Update current time to avoid multiple toggles
        }
        if (current_time >= next_toggle_time2) {
            toggle_relay(RELAY2_GPIO);
            current_time = next_toggle_time2;
        }
        if (current_time >= next_toggle_time3) {
            toggle_relay(RELAY3_GPIO);
            current_time = next_toggle_time3;
        }
        if (current_time >= next_toggle_time4) {
            toggle_relay(RELAY4_GPIO);
            current_time = next_toggle_time4;
        }

        // Sleep for a short interval to avoid busy-waiting
        usleep(10000); // 10ms
    }

    // Turn off all relays before exiting
    gpioWrite(RELAY1_GPIO, 0);
    gpioWrite(RELAY2_GPIO, 0);
    gpioWrite(RELAY3_GPIO, 0);
    gpioWrite(RELAY4_GPIO, 0);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

