#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define RELAY_PIN 27

// Define debounce and cooldown times (in milliseconds)
#define DEBOUNCE_TIME 50
#define COOLDOWN_TIME 5000

// Global variables
static volatile int running = 1;
static volatile unsigned long last_trigger_time = 0;

// Function prototypes
int initialize_gpio();
int read_sound_sensor();
int activate_relay();
int deactivate_relay();
int log_event(const char *timestamp);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    return 0;
}

// Function to read the sound sensor
int read_sound_sensor() {
    return gpioRead(SOUND_SENSOR_PIN);
}

// Function to activate the relay
int activate_relay() {
    if (gpioWrite(RELAY_PIN, 1) != 0) {
        fprintf(stderr, "Failed to activate relay\n");
        return 1;
    }
    return 0;
}

// Function to deactivate the relay
int deactivate_relay() {
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Failed to deactivate relay\n");
        return 1;
    }
    return 0;
}

// Function to log the event to a file
int log_event(const char *timestamp) {
    FILE *fp = fopen("alarm_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open alarm_log.txt\n");
        return 1;
    }

    fprintf(fp, "%s\n", timestamp);
    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    deactivate_relay();
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int sound_detected = read_sound_sensor();
        unsigned long current_time = gpioTick();

        if (sound_detected == 0) { // KY-038 outputs LOW when sound is detected
            if (current_time - last_trigger_time > DEBOUNCE_TIME * 1000) { // Debounce
                printf("Sound detected!\n");

                // Get current timestamp
                time_t rawtime;
                struct tm *timeinfo;
                char timestamp[20];

                time(&rawtime);
                timeinfo = localtime(&rawtime);

                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

                // Activate relay
                if (activate_relay() == 0) {
                    // Log event
                    if (log_event(timestamp) != 0) {
                        fprintf(stderr, "Failed to log event\n");
                    }

                    // Wait for 3 seconds
                    gpioDelay(3000000); // 3 seconds

                    // Deactivate relay
                    if (deactivate_relay() != 0) {
                        fprintf(stderr, "Failed to deactivate relay\n");
                    }
                }

                last_trigger_time = current_time;
            }
        }

        gpioDelay(100000); // 100ms polling interval
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

