#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47

// Sensitivity scale factor (degrees/second per LSB)
#define GYRO_SCALE 131.0

// Circular buffer size
#define BUFFER_SIZE 100

// Global variables
int i2c_fd;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int init_i2c();
int init_mpu6050();
int read_gyro_data(float *x, float *y, float *z);
float calculate_angular_velocity(float x, float y, float z);
void add_to_buffer(CircularBuffer *cb, float value);
float get_latest_sample(CircularBuffer *cb);
void callback(float angular_velocity);
void signal_handler(int signal);
void cleanup();

// Initialize circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Initialize I2C
int init_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Initialize MPU-6050
int init_mpu6050() {
    // Wake up the MPU-6050 (clear sleep mode bit)
    uint8_t data[2];
    data[0] = PWR_MGMT_1;
    data[1] = 0;

    if (write(i2c_fd, data, 2) != 2) {
        perror("Error writing to PWR_MGMT_1 register");
        return -1;
    }

    return 0;
}

// Read gyroscope data
int read_gyro_data(float *x, float *y, float *z) {
    uint8_t buffer[6];

    if (read(i2c_fd, buffer, 6) != 6) {
        perror("Error reading gyroscope data");
        return -1;
    }

    // Combine high and low bytes, and convert to degrees/second
    int16_t raw_x = (buffer[0] << 8) | buffer[1];
    int16_t raw_y = (buffer[2] << 8) | buffer[3];
    int16_t raw_z = (buffer[4] << 8) | buffer[5];

    *x = (float)raw_x / GYRO_SCALE;
    *y = (float)raw_y / GYRO_SCALE;
    *z = (float)raw_z / GYRO_SCALE;

    return 0;
}

// Calculate angular velocity magnitude
float calculate_angular_velocity(float x, float y, float z) {
    return sqrt(x * x + y * y + z * z);
}

// Add a sample to the circular buffer
void add_to_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Get the latest sample from the circular buffer
float get_latest_sample(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0; // Return 0 if the buffer is empty
    }
    int index = (cb->head - 1 + BUFFER_SIZE) % BUFFER_SIZE; // Calculate the index of the last element
    return cb->buffer[index];
}

// Callback function
void callback(float angular_velocity) {
    printf("Angular velocity exceeded 50.0 degrees/second: %.2f degrees/second\n", angular_velocity);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() < 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() < 0) {
        cleanup();
        return 1;
    }

    // Initialize circular buffer
    CircularBuffer angular_velocity_buffer;
    init_circular_buffer(&angular_velocity_buffer);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float x, y, z, angular_velocity;

    printf("Starting data acquisition...\n");

    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(&x, &y, &z) == 0) {
            // Calculate angular velocity
            angular_velocity = calculate_angular_velocity(x, y, z);

            // Add to circular buffer
            add_to_buffer(&angular_velocity_buffer, angular_velocity);

            // Get latest sample
            float latest_velocity = get_latest_sample(&angular_velocity_buffer);

            // Check if angular velocity exceeds threshold
            if (latest_velocity > 50.0) {
                callback(latest_velocity);
            }
        } else {
            fprintf(stderr, "Error reading gyro data, retrying...\n");
        }

        // Delay for 10 milliseconds
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

