#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <sys/select.h>
#include <errno.h>
#include <sys/time.h>

// Configuration
#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B9600
#define CO2_LOG_FILE "co2_log.json"
#define ERROR_LOG_FILE "co2_error.log"
#define SAMPLE_INTERVAL_SEC 5
#define TIMEOUT_SEC 1
#define MAX_RETRIES 3

// MH-Z19B Commands
#define READ_CO2_CMD_1 0x01
#define READ_CO2_CMD_2 0x86
#define READ_CO2_CMD_3 0x00
#define READ_CO2_CMD_4 0x00
#define READ_CO2_CMD_5 0x00
#define READ_CO2_CMD_6 0x00
#define READ_CO2_CMD_7 0x00
#define READ_CO2_CMD_8 0x00
#define READ_CO2_CMD_9 0x79

// Global variables
volatile sig_atomic_t program_running = 1;
int uart_fd = -1;
FILE *co2_log_fp = NULL;
FILE *error_log_fp = NULL;

// Structure to hold sensor data
typedef struct {
    unsigned int ppm;
    int error_flag;
} sensor_data_t;

// Function prototypes
int init_uart(const char *device, speed_t baud_rate);
int send_command(int fd, unsigned char command);
int read_response(int fd, unsigned char *response, int expected_len);
sensor_data_t parse_response(const unsigned char *response);
int log_data(FILE *fp, unsigned long long timestamp, unsigned int ppm, int error_flag);
int log_error(FILE *fp, const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Initialize UART
int init_uart(const char *device, speed_t baud_rate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD;  // 8N1, no parity, ignore modem control lines, enable receiver
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0; // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read doesn't block
    tty.c_cc[VTIME] = 5; // 0.5 seconds read timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

// Send command to MH-Z19B
int send_command(int fd, unsigned char command) {
    unsigned char cmd[1] = {command};
    ssize_t bytes_written = write(fd, cmd, 1);
    if (bytes_written != 1) {
        perror("Error writing to UART");
        return -1;
    }
    return 0;
}

// Read response from MH-Z19B
int read_response(int fd, unsigned char *response, int expected_len) {
    fd_set readfds;
    struct timeval timeout;
    int bytes_read = 0;

    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    timeout.tv_sec = TIMEOUT_SEC;
    timeout.tv_usec = 0;

    int select_result = select(fd + 1, &readfds, NULL, NULL, &timeout);

    if (select_result == -1) {
        perror("Error in select");
        return -1;
    } else if (select_result == 0) {
        fprintf(stderr, "Timeout reading from UART\n");
        return -1;
    } else {
        while (bytes_read < expected_len) {
            ssize_t bytes_available = read(fd, response + bytes_read, expected_len - bytes_read);
            if (bytes_available == -1) {
                perror("Error reading from UART");
                return -1;
            } else if (bytes_available == 0) {
                fprintf(stderr, "EOF reading from UART\n");
                return -1;
            }
            bytes_read += bytes_available;
        }
    }
    return 0;
}

// Parse response data
sensor_data_t parse_response(const unsigned char *response) {
    sensor_data_t data;
    data.error_flag = 0;

    // Checksum calculation
    unsigned char checksum = 0;
    for (int i = 1; i < 8; i++) {
        checksum += response[i];
    }
    checksum = 0xFF - checksum + 1;

    if (checksum != response[8]) {
        data.error_flag = 1;
        data.ppm = 0; // Set ppm to 0 on checksum error
        return data;
    }

    // Extract ppm value
    data.ppm = (response[2] << 8) | response[3];

    return data;
}

// Log data to file
int log_data(FILE *fp, unsigned long long timestamp, unsigned int ppm, int error_flag) {
    fprintf(fp, "{\"timestamp\": %llu, \"ppm\": %u, \"error\": %d}\n", timestamp, ppm, error_flag);
    fflush(fp);
    return 0;
}

// Log error to file
int log_error(FILE *fp, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(fp, "%s: %s\n", timestamp, message);
    fflush(fp);
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (uart_fd != -1) {
        close(uart_fd);
    }
    if (co2_log_fp != NULL) {
        fclose(co2_log_fp);
    }
    if (error_log_fp != NULL) {
        fclose(error_log_fp);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize UART
    uart_fd = init_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd == -1) {
        return 1;
    }

    // Open log files
    co2_log_fp = fopen(CO2_LOG_FILE, "a");
    if (co2_log_fp == NULL) {
        perror("Error opening CO2 log file");
        cleanup();
        return 1;
    }

    error_log_fp = fopen(ERROR_LOG_FILE, "a");
    if (error_log_fp == NULL) {
        perror("Error opening error log file");
        cleanup();
        return 1;
    }

    unsigned char command[] = {READ_CO2_CMD_1, READ_CO2_CMD_2, READ_CO2_CMD_3, READ_CO2_CMD_4, READ_CO2_CMD_5, READ_CO2_CMD_6, READ_CO2_CMD_7, READ_CO2_CMD_8, READ_CO2_CMD_9};
    unsigned char response[9];
    sensor_data_t sensor_data;
    struct timeval tv;
    unsigned long long timestamp;
    int retries;

    printf("CO2 monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        retries = 0;
        while (retries < MAX_RETRIES) {
            // Send command
            if (send_command(uart_fd, command[0]) != 0) {
                log_error(error_log_fp, "Failed to send command, retrying...");
                retries++;
                usleep(100000); // Wait 100ms before retrying
                continue;
            }
            if (send_command(uart_fd, command[1]) != 0) {
                log_error(error_log_fp, "Failed to send command, retrying...");
                retries++;
                usleep(100000); // Wait 100ms before retrying
                continue;
            }
            if (send_command(uart_fd, command[2]) != 0) {
                log_error(error_log_fp, "Failed to send command, retrying...");
                retries++;
                usleep(100000); // Wait 100ms before retrying
                continue;
            }
            if (send_command(uart_fd, command[3]) != 0) {
                log_error(error_log_fp, "Failed to send command, retrying...");
                retries++;
                usleep(100000); // Wait 100ms before retrying
                continue;
            }
            if (send_command(uart_fd, command[4]) != 0) {
                log_error(error_log_fp, "Failed to send command, retrying...");
                retries++;
                usleep(100000); // Wait 100ms before retrying
                continue;
            }
            if (send_command(uart_fd, command[5]) != 0) {
                log_error(error_log_fp, "Failed to send command, retrying...");
                retries++;
                usleep(100000); // Wait 100ms before retrying
                continue;
            }
            if (send_command(uart_fd, command[6]) != 0) {
                log_error(error_log_fp, "Failed to send command, retrying...");
                retries++;
                usleep(100000); // Wait 100ms before retrying
                continue;
            }
            if (send_command(uart_fd, command[7]) != 0) {
                log_error(error_log_fp, "Failed to send command, retrying...");
                retries++;
                usleep(100000); // Wait 100ms before retrying
                continue;
            }
            if (send_command(uart_fd, command[8]) != 0) {
                log_error(error_log_fp, "Failed to send command, retrying...");
                retries++;
                usleep(100000); // Wait 100ms before retrying
                continue;
            }

            // Read response
            if (read_response(uart_fd, response, 9) != 0) {
                log_error(error_log_fp, "Failed to read response, retrying...");
                retries++;
                usleep(100000); // Wait 100ms before retrying
                continue;
            }

            // Parse response
            sensor_data = parse_response(response);

            // Get timestamp
            gettimeofday(&tv, NULL);
            timestamp = (unsigned long long)(tv.tv_sec) * 1000000 + (unsigned long long)(tv.tv_usec);

            // Log data
            log_data(co2_log_fp, timestamp, sensor_data.ppm, sensor_data.error_flag);

            // Print to stdout (simulating API call)
            printf("Timestamp: %llu, CO2: %u ppm, Error: %d\n", timestamp, sensor_data.ppm, sensor_data.error_flag);

            break; // Exit retry loop on success
        }

        if (retries == MAX_RETRIES) {
            log_error(error_log_fp, "Failed to read sensor data after multiple retries.");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    cleanup();
    return 0;
}

