    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize UART
    uart_fd = init_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd == -1) {
        return 1;
    }

    // Open log files
    co2_log_fp = fopen(CO2_LOG_FILE, "a");
    if (co2_log_fp == NULL) {
        perror("Error opening CO2 log file");
        cleanup();
        return 1;
    }

