                log_error(error_log_fp, "Failed to send command, retrying...");
                retries++;
                usleep(100000); // Wait 100ms before retrying
                continue;
            }
            if (send_command(uart_fd, command[4]) != 0) {
                log_error(error_log_fp, "Failed to send command, retrying...");
                retries++;
                usleep(100000); // Wait 100ms before retrying
                continue;
            }
            if (send_command(uart_fd, command[5]) != 0) {
                log_error(error_log_fp, "Failed to send command, retrying...");
                retries++;
                usleep(100000); // Wait 100ms before retrying
                continue;
            }
            if (send_command(uart_fd, command[6]) != 0) {
                log_error(error_log_fp, "Failed to send command, retrying...");
                retries++;
                usleep(100000); // Wait 100ms before retrying
                continue;
            }
            if (send_command(uart_fd, command[7]) != 0) {
                log_error(error_log_fp, "Failed to send command, retrying...");
                retries++;
                usleep(100000); // Wait 100ms before retrying
                continue;
            }
            if (send_command(uart_fd, command[8]) != 0) {
                log_error(error_log_fp, "Failed to send command, retrying...");
                retries++;
                usleep(100000); // Wait 100ms before retrying
                continue;
            }

            // Read response
            if (read_response(uart_fd, response, 9) != 0) {
                log_error(error_log_fp, "Failed to read response, retrying...");
                retries++;
                usleep(100000); // Wait 100ms before retrying
                continue;
            }

            // Parse response
            sensor_data = parse_response(response);

            // Get timestamp
            gettimeofday(&tv, NULL);
            timestamp = (unsigned long long)(tv.tv_sec) * 1000000 + (unsigned long long)(tv.tv_usec);

            // Log data
            log_data(co2_log_fp, timestamp, sensor_data.ppm, sensor_data.error_flag);

            // Print to stdout (simulating API call)
            printf("Timestamp: %llu, CO2: %u ppm, Error: %d\n", timestamp, sensor_data.ppm, sensor_data.error_flag);

            break; // Exit retry loop on success
        }

        if (retries == MAX_RETRIES) {
            log_error(error_log_fp, "Failed to read sensor data after multiple retries.");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    cleanup();
    return 0;
