#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L register addresses
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08

// GPIO pin for heading deviation indicator
#define GPIO_PIN 17

// Target heading
#define TARGET_HEADING 90.0

// Deviation threshold
#define DEVIATION_THRESHOLD 10.0

// Hard iron offsets
#define HARD_IRON_X 100
#define HARD_IRON_Y -50

// Circular buffer size
#define BUFFER_SIZE 100

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int init_hmc5883l();
int read_hmc5883l(int16_t *x, int16_t *y, int16_t *z);
float calculate_heading(int16_t x, int16_t y);
float apply_hard_iron_compensation(int16_t x, int16_t y);
void add_to_circular_buffer(CircularBuffer *cb, float heading);
float calculate_average_heading(CircularBuffer *cb);
void control_gpio(float average_heading);
void signal_handler(int signal);
void cleanup();

// Initialize circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Add a value to the circular buffer
void add_to_circular_buffer(CircularBuffer *cb, float heading) {
    cb->buffer[cb->head] = heading;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Calculate the average heading from the circular buffer
float calculate_average_heading(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Initialize HMC5883L
int init_hmc5883l() {
    // Set configuration register A (8-average, 15 Hz, normal measurement)
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to HMC5883L_CONFIG_A\n");
        return -1;
    }

    // Set configuration register B (Gain = +/- 1.3 Ga)
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0xA0) < 0) {
        fprintf(stderr, "Error writing to HMC5883L_CONFIG_B\n");
        return -1;
    }

    // Set mode register (Continuous measurement mode)
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing to HMC5883L_MODE\n");
        return -1;
    }

    return 0;
}

// Read data from HMC5883L
int read_hmc5883l(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, buffer, 6) != 6) {
        fprintf(stderr, "Error reading from HMC5883L\n");
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *z = (int16_t)((buffer[2] << 8) | buffer[3]);
    *y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Calculate heading in degrees
float calculate_heading(int16_t x, int16_t y) {
    float heading = atan2(y, x) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }
    return heading;
}

// Apply hard iron compensation
float apply_hard_iron_compensation(int16_t x, int16_t y) {
    return calculate_heading(x - HARD_IRON_X, y - HARD_IRON_Y);
}

// Control GPIO pin
void control_gpio(float average_heading) {
    float deviation = fabs(average_heading - TARGET_HEADING);
    if (deviation > DEVIATION_THRESHOLD) {
        gpioWrite(GPIO_PIN, 1); // Set GPIO high
    } else {
        gpioWrite(GPIO_PIN, 0); // Set GPIO low
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    gpioWrite(GPIO_PIN, 0); // Ensure GPIO is low
    gpioSetMode(GPIO_PIN, PI_INPUT); // Set GPIO back to input
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize HMC5883L
    if (init_hmc5883l() < 0) {
        fprintf(stderr, "HMC5883L initialisation failed\n");
        cleanup();
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Initialize circular buffer
    CircularBuffer heading_buffer;
    init_circular_buffer(&heading_buffer);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int16_t x, y, z;

        // Read data from HMC5883L
        if (read_hmc5883l(&x, &y, &z) == 0) {
            // Apply hard iron compensation
            float compensated_heading = apply_hard_iron_compensation(x, y);

            // Add heading to circular buffer
            add_to_circular_buffer(&heading_buffer, compensated_heading);

            // Calculate average heading
            float average_heading = calculate_average_heading(&heading_buffer);

            // Control GPIO pin
            control_gpio(average_heading);

            printf("X: %d, Y: %d, Z: %d, Compensated Heading: %.2f, Average Heading: %.2f\n", x, y, z, compensated_heading, average_heading);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
            // Attempt to re-initialize I2C
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, HMC5883L_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                terminate = 1; // Exit loop if re-initialization fails
            } else {
                if (init_hmc5883l() < 0) {
                    fprintf(stderr, "HMC5883L re-initialisation failed\n");
                    terminate = 1; // Exit loop if re-initialization fails
                }
            }
        }

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

