#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define RED_GPIO 17
#define GREEN_GPIO 27
#define BLUE_GPIO 22
#define LUX_THRESHOLD_1 50.0
#define LUX_THRESHOLD_2 150.0
#define LUX_THRESHOLD_3 300.0
#define LOG_FILE "lighting_log.txt"
#define SLEEP_DURATION 1 // seconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
float read_bh1750();
void control_relays(float lux);
void log_data(float lux, int red_state, int green_state, int blue_state);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }

    // Configure BH1750 for continuous high-resolution mode
    if (i2cWriteByteData(i2c_handle, 0x00, CONTINUOUS_HIGH_RES_MODE) < 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", i2c_handle);
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Read ambient light level from BH1750
float read_bh1750() {
    int raw_value;
    float lux;

    raw_value = i2cReadWordData(i2c_handle, 0x00);
    if (raw_value < 0) {
        fprintf(stderr, "Error reading from I2C device: %d\n", i2c_handle);
        return -1.0;
    }

    // BH1750 returns big-endian data, so swap bytes
    raw_value = ((raw_value & 0xFF00) >> 8) | ((raw_value & 0x00FF) << 8);

    lux = (float)raw_value / 1.2;
    return lux;
}

// Control relays based on lux value
void control_relays(float lux) {
    int red_state = 0, green_state = 0, blue_state = 0;

    if (lux < LUX_THRESHOLD_1) {
        red_state = 1;
    } else if (lux < LUX_THRESHOLD_2) {
        green_state = 1;
    } else if (lux < LUX_THRESHOLD_3) {
        blue_state = 1;
