#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Motor A GPIO pins
#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18

// Motor B GPIO pins
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

// PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Proportional gain
#define KP 50.0

// Target distance (cm)
#define TARGET_DISTANCE 50.0

// Global variables for graceful shutdown
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping motors and cleaning up...\n", signal);
}

// Function to set motor direction and PWM duty cycle
void set_motor_direction(int in1_pin, int in2_pin, int in3_pin, int in4_pin, int distance) {
    if (distance < TARGET_DISTANCE) {
        // Forward
        if (gpioWrite(in1_pin, 1) != 0) {
            fprintf(stderr, "Error setting IN1 high\n");
        }
        if (gpioWrite(in3_pin, 1) != 0) {
            fprintf(stderr, "Error setting IN3 high\n");
        }

        // Calculate PWM duty cycle based on distance
        float error = TARGET_DISTANCE - distance;
        int duty_cycle = (int)(KP * error);

        // Limit duty cycle to 0-255 range
        if (duty_cycle < 0) {
            duty_cycle = 0;
        } else if (duty_cycle > 255) {
            duty_cycle = 255;
        }

        if (gpioPWM(in2_pin, duty_cycle) != 0) {
            fprintf(stderr, "Error setting PWM duty cycle for IN2\n");
        }
        if (gpioPWM(in4_pin, duty_cycle) != 0) {
            fprintf(stderr, "Error setting PWM duty cycle for IN4\n");
        }
    } else {
        // Backward
        if (gpioWrite(in1_pin, 0) != 0) {
            fprintf(stderr, "Error setting IN1 low\n");
        }
        if (gpioWrite(in3_pin, 0) != 0) {
            fprintf(stderr, "Error setting IN3 low\n");
        }

        // Calculate PWM duty cycle based on distance
        float error = distance - TARGET_DISTANCE;
        int duty_cycle = (int)(KP * error);

        // Limit duty cycle to 0-255 range
        if (duty_cycle < 0) {
            duty_cycle = 0;
        } else if (duty_cycle > 255) {
            duty_cycle = 255;
        }

        if (gpioPWM(in2_pin, duty_cycle) != 0) {
            fprintf(stderr, "Error setting PWM duty cycle for IN2\n");
        }
        if (gpioPWM(in4_pin, duty_cycle) != 0) {
            fprintf(stderr, "Error setting PWM duty cycle for IN4\n");
        }
    }
}

int main(int argc, char *argv[]) {
    // Check for command-line arguments
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <distance_a> <distance_b>\n", argv[0]);
        return 1;
    }

    // Parse command-line arguments
    float distance_a = atof(argv[1]);
    float distance_b = atof(argv[2]);

    // Validate distance readings
    if (distance_a < 10.0 || distance_a > 100.0 || distance_b < 10.0 || distance_b > 100.0) {
        fprintf(stderr, "Error: Distance readings must be between 10 and 100 cm\n");
        return 1;
    }

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    if (gpioSetMode(MOTOR_A_IN1, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting MOTOR_A_IN1 as output\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MOTOR_A_IN2, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting MOTOR_A_IN2 as output\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MOTOR_B_IN3, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting MOTOR_B_IN3 as output\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MOTOR_B_IN4, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting MOTOR_B_IN4 as output\n");
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency
    if (gpioSetPWMfrequency(MOTOR_A_IN2, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error setting PWM frequency for MOTOR_A_IN2\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMfrequency(MOTOR_B_IN4, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error setting PWM frequency for MOTOR_B_IN4\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main control loop
    while (program_running) {
        // Set motor directions and PWM duty cycles
        set_motor_direction(MOTOR_A_IN1, MOTOR_A_IN2, MOTOR_B_IN3, MOTOR_B_IN4, distance_a);

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Stop motors
    if (gpioWrite(MOTOR_A_IN1, 0) != 0) {
        fprintf(stderr, "Error setting MOTOR_A_IN1 low\n");
    }
    if (gpioWrite(MOTOR_A_IN2, 0) != 0) {
        fprintf(stderr, "Error setting MOTOR_A_IN2 low\n");
    }
    if (gpioWrite(MOTOR_B_IN3, 0) != 0) {
        fprintf(stderr, "Error setting MOTOR_B_IN3 low\n");
    }
    if (gpioWrite(MOTOR_B_IN4, 0) != 0) {
        fprintf(stderr, "Error setting MOTOR_B_IN4 low\n");
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

