#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>

// Configuration
#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define SERVO_GPIO 18
#define PWM_CHIP 2
#define PWM_NUM 0
#define PWM_PERIOD 2000000 // 2ms period (50Hz)
#define PWM_DUTY_CYCLE_MIN 1000000 // 1ms
#define PWM_DUTY_CYCLE_MAX 2000000 // 2ms
#define LOG_FILE "solar_tracker.log"
#define RETRY_COUNT 5
#define RETRY_DELAY_MS 10

// MPU6050 Registers
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H 0x43

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t accel_x;
    int16_t accel_y;
    int16_t accel_z;
    int16_t gyro_x;
    int16_t gyro_y;
    int16_t gyro_z;
} sensor_data_t;

// Function prototypes
int i2c_read_register(int fd, uint8_t reg);
int i2c_write_register(int fd, uint8_t reg, uint8_t value);
int read_sensor_data(int fd, sensor_data_t *data);
void calculate_pitch_roll(sensor_data_t data, float *pitch, float *roll);
int set_servo_angle(int gpio, int angle);
int log_data(float pitch, float roll, int position);
void signal_handler(int sig);
int initialize_i2c(const char *bus);
int initialize_pwm(int chip, int num);
int set_pwm_period(int chip, int num, int period);
int set_pwm_duty_cycle(int chip, int num, int duty_cycle);
int enable_pwm(int chip, int num);
int disable_pwm(int chip, int num);

// I2C read register with retry
int i2c_read_register(int fd, uint8_t reg) {
    int retries = RETRY_COUNT;
    int result;

    while (retries > 0) {
        result = i2c_smbus_read_byte_data(fd, reg);
        if (result >= 0) {
            return result;
        }
        perror("I2C read error");
        retries--;
        usleep(RETRY_DELAY_MS * 1000); // Convert ms to microseconds
    }

    fprintf(stderr, "Failed to read register 0x%02X after %d retries\n", reg, RETRY_COUNT);
    return -1; // Indicate failure
}

// I2C write register with retry
int i2c_write_register(int fd, uint8_t reg, uint8_t value) {
    int retries = RETRY_COUNT;
    int result;

    while (retries > 0) {
        result = i2c_smbus_write_byte_data(fd, reg, value);
        if (result == 0) {
            return 0; // Success
        }
        perror("I2C write error");
        retries--;
        usleep(RETRY_DELAY_MS * 1000); // Convert ms to microseconds
    }

    fprintf(stderr, "Failed to write register 0x%02X after %d retries\n", reg, RETRY_COUNT);
    return -1; // Indicate failure
}

// Read sensor data
int read_sensor_data(int fd, sensor_data_t *data) {
    data->accel_x = (int16_t)((i2c_read_register(fd, ACCEL_XOUT_H) << 8) | i2c_read_register(fd, ACCEL_XOUT_H + 1));
    data->accel_y = (int16_t)((i2c_read_register(fd, ACCEL_XOUT_H + 2) << 8) | i2c_read_register(fd, ACCEL_XOUT_H + 3));
    data->accel_z = (int16_t)((i2c_read_register(fd, ACCEL_XOUT_H + 4) << 8) | i2c_read_register(fd, ACCEL_XOUT_H + 5));
    data->gyro_x = (int16_t)((i2c_read_register(fd, GYRO_XOUT_H) << 8) | i2c_read_register(fd, GYRO_XOUT_H + 1));
    data->gyro_y = (int16_t)((i2c_read_register(fd, GYRO_XOUT_H + 2) << 8) | i2c_read_register(fd, GYRO_XOUT_H + 3));
    data->gyro_z = (int16_t)((i2c_read_register(fd, GYRO_XOUT_H + 4) << 8) | i2c_read_register(fd, GYRO_XOUT_H + 5));

    return 0;
}

// Calculate pitch and roll
void calculate_pitch_roll(sensor_data_t data, float *pitch, float *roll) {
    float accel_x = (float)data.accel_x;
    float accel_y = (float)data.accel_y;
    float accel_z = (float)data.accel_z;

    *pitch = atan2(accel_x, sqrt(accel_y * accel_y + accel_z * accel_z)) * 180 / M_PI;
    *roll = atan2(accel_y, sqrt(accel_x * accel_x + accel_z * accel_z)) * 180 / M_PI;
