        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return -1;
    }

    // Wake up the MPU6050
    if (i2c_write_register(fd, PWR_MGMT_1, 0) != 0) {
        fprintf(stderr, "Failed to wake up MPU6050\n");
        close(fd);
        return -1;
    }

    return fd;
}

// Initialize PWM
int initialize_pwm(int chip, int num) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d", chip, num);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open PWM device");
        return -1;
    }

    // Export PWM channel
    char export_path[64];
    snprintf(export_path, sizeof(export_path), "/sys/class/pwm/pwmchip%d/export", chip);
    int export_fd = open(export_path, O_WRONLY);
    if (export_fd < 0) {
        perror("Failed to open PWM export file");
        close(fd);
        return -1;
    }
    char num_str[2];
    snprintf(num_str, sizeof(num_str), "%d", num);
    if (write(export_fd, num_str, strlen(num_str)) < 0) {
        perror("Failed to write to PWM export file");
        close(fd);
        close(export_fd);
        return -1;
    }
    close(export_fd);

    // Set PWM period
    if (set_pwm_period(chip, num, PWM_PERIOD) != 0) {
        fprintf(stderr, "Failed to set PWM period\n");
        close(fd);
        return -1;
    }

    // Enable PWM
    if (enable_pwm(chip, num) != 0) {
        fprintf(stderr, "Failed to enable PWM\n");
        close(fd);
        return -1;
    }

    return fd;
}

// Set PWM period
int set_pwm_period(int chip, int num, int period) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/period", chip, num);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open PWM period file");
        return -1;
    }

    char period_str[16];
    snprintf(period_str, sizeof(period_str), "%d", period);
    if (write(fd, period_str, strlen(period_str)) < 0) {
        perror("Failed to write to PWM period file");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Set PWM duty cycle
int set_pwm_duty_cycle(int chip, int num, int duty_cycle) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/duty_cycle", chip, num);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open PWM duty_cycle file");
        return -1;
    }

    char duty_cycle_str[16];
    snprintf(duty_cycle_str, sizeof(duty_cycle_str), "%d", duty_cycle);
    if (write(fd, duty_cycle_str, strlen(duty_cycle_str)) < 0) {
        perror("Failed to write to PWM duty_cycle file");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Enable PWM
int enable_pwm(int chip, int num) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/enable", chip, num);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open PWM enable file");
        return -1;
    }

    char enable_str[2] = "1";
    if (write(fd, enable_str, 1) < 0) {
        perror("Failed to write to PWM enable file");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Disable PWM
int disable_pwm(int chip, int num) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/enable", chip, num);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open PWM enable file");
        return -1;
    }

    char enable_str[2] = "0";
    if (write(fd, enable_str, 1) < 0) {
        perror("Failed to write to PWM enable file");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = initialize_i2c(I2C_BUS);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed\n");
        return 1;
    }

    // Initialize PWM
    int pwm_fd = initialize_pwm(PWM_CHIP, PWM_NUM);
    if (pwm_fd < 0) {
        fprintf(stderr, "PWM initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        close(pwm_fd);
        disable_pwm(PWM_CHIP, PWM_NUM);
        return 1;
    }

    sensor_data_t sensor_data;
    float pitch, roll;
    int angle;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_fd, &sensor_data) == 0) {
            // Calculate pitch and roll
            calculate_pitch_roll(sensor_data, &pitch, &roll);

            // Map pitch to servo angle (0-180 degrees)
            angle = (int)(pitch + 90.0); // Assuming pitch range is -90 to 90
            if (angle < 0) angle = 0;
            if (angle > 180) angle = 180;

            // Set servo angle
            if (set_servo_angle(SERVO_GPIO, angle) != 0) {
                fprintf(stderr, "Failed to set servo angle\n");
            }

            // Log data
            if (log_data(pitch, roll, angle) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        usleep(100000); // 100ms delay
    }

    // Cleanup
    fprintf(stderr, "Cleaning up...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (pwm_fd != -1) {
        disable_pwm(PWM_CHIP, PWM_NUM);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

