    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/period", chip, num);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open PWM period file");
        return -1;
    }

    char period_str[16];
    snprintf(period_str, sizeof(period_str), "%d", period);
    if (write(fd, period_str, strlen(period_str)) < 0) {
        perror("Failed to write to PWM period file");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

