#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for the relays
#define RELAY1_GPIO 4
#define RELAY2_GPIO 17
#define RELAY3_GPIO 27
#define RELAY4_GPIO 22

// Define the schedule file name
#define SCHEDULE_FILE "lighting_schedule.txt"

// Define the fade duration (in seconds)
#define FADE_DURATION 1800

// Define the PWM frequency (in Hz)
#define PWM_FREQUENCY 100

// Structure to represent a schedule entry
typedef struct {
    int hour;
    int minute;
    int second;
    int relay_number;
    int state; // 1 for ON, 0 for OFF
} ScheduleEntry;

// Global variables
FILE *schedule_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_schedule(ScheduleEntry *schedule, int *num_entries);
int parse_schedule_entry(const char *line, ScheduleEntry *entry);
int is_time_between(int hour, int minute, int second, int start_hour, int start_minute, int start_second, int end_hour, int end_minute, int end_second);
int fade_relay(int gpio_pin, int start_duty_cycle, int end_duty_cycle, int duration);
void signal_handler(int signal);

// Function to read the schedule from the file
int read_schedule(ScheduleEntry *schedule, int *num_entries) {
    char line[256];
    int i = 0;

    schedule_file = fopen(SCHEDULE_FILE, "r");
    if (schedule_file == NULL) {
        perror("Error opening schedule file");
        return -1;
    }

    while (fgets(line, sizeof(line), schedule_file) != NULL && i < 100) { // Limit to 100 entries
        if (parse_schedule_entry(line, &schedule[i]) == 0) {
            i++;
        } else {
            fprintf(stderr, "Error parsing schedule entry: %s", line);
        }
    }

    *num_entries = i;
    fclose(schedule_file);
    return 0;
}

// Function to parse a schedule entry from the file
int parse_schedule_entry(const char *line, ScheduleEntry *entry) {
    if (sscanf(line, "%d:%d:%d,%d,%d", &entry->hour, &entry->minute, &entry->second, &entry->relay_number, &entry->state) == 5) {
        if (entry->hour >= 0 && entry->hour <= 23 && entry->minute >= 0 && entry->minute <= 59 && entry->second >= 0 && entry->second <= 59 &&
            entry->relay_number >= 1 && entry->relay_number <= 4 && (entry->state == 0 || entry->state == 1)) {
            return 0; // Success
        } else {
            fprintf(stderr, "Invalid schedule entry: %s", line);
            return -1; // Invalid data
        }
    } else {
        fprintf(stderr, "Invalid schedule format: %s", line);
        return -1; // Invalid format
    }
}

// Function to check if the current time is between two times
int is_time_between(int hour, int minute, int second, int start_hour, int start_minute, int start_second, int end_hour, int end_minute, int end_second) {
    time_t current_time = time(NULL);
    struct tm *time_info = localtime(&current_time);

    if (time_info == NULL) {
        perror("Error getting local time");
        return 0; // Assume not between if localtime fails
    }

    int current_seconds = time_info->tm_hour * 3600 + time_info->tm_min * 60 + time_info->tm_sec;
    int start_seconds = start_hour * 3600 + start_minute * 60 + start_second;
    int end_seconds = end_hour * 3600 + end_minute * 60 + end_second;

    if (start_seconds > end_seconds) {
        // Handle cases where the end time is before the start time (e.g., overnight)
        return (current_seconds >= start_seconds || current_seconds <= end_seconds);
    } else {
        return (current_seconds >= start_seconds && current_seconds <= end_seconds);
    }
}

// Function to fade the relay brightness using PWM
int fade_relay(int gpio_pin, int start_duty_cycle, int end_duty_cycle, int duration) {
    int steps = 100; // Number of steps in the fade
    int delay_ms = duration * 1000 / steps; // Delay between steps in milliseconds
    int direction = (end_duty_cycle > start_duty_cycle) ? 1 : -1; // 1 for increasing, -1 for decreasing
    int current_duty_cycle = start_duty_cycle;

    for (int i = 0; i < steps; i++) {
        current_duty_cycle += direction;
        if (current_duty_cycle < 0) current_duty_cycle = 0;
        if (current_duty_cycle > 100) current_duty_cycle = 100;

        gpioPWM(gpio_pin, current_duty_cycle * 2.55); // Convert duty cycle to PWM value (0-255)
        gpioDelay(delay_ms);
    }

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    program_running = 0;

    // Turn off all relays
    gpioWrite(RELAY1_GPIO, 1);
    gpioWrite(RELAY2_GPIO, 1);
    gpioWrite(RELAY3_GPIO, 1);
    gpioWrite(RELAY4_GPIO, 1);

    // Release GPIO resources
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY2_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY3_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY4_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(RELAY1_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY2_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY3_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY4_GPIO, PWM_FREQUENCY);

    // Set PWM range (0-100)
    gpioSetPWMrange(RELAY1_GPIO, 100);
    gpioSetPWMrange(RELAY2_GPIO, 100);
    gpioSetPWMrange(RELAY3_GPIO, 100);
    gpioSetPWMrange(RELAY4_GPIO, 100);

    // Turn off all relays initially
    gpioWrite(RELAY1_GPIO, 1);
    gpioWrite(RELAY2_GPIO, 1);
    gpioWrite(RELAY3_GPIO, 1);
    gpioWrite(RELAY4_GPIO, 1);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    ScheduleEntry schedule[100];
    int num_entries = 0;

    // Read the schedule
    if (read_schedule(schedule, &num_entries) != 0) {
        fprintf(stderr, "Failed to read schedule, exiting.\n");
        gpioTerminate();
        return 1;
    }

    printf("Schedule read successfully. %d entries found.\n", num_entries);

    // Main loop
    while (program_running) {
        time_t current_time = time(NULL);
        struct tm *time_info = localtime(&current_time);

        if (time_info == NULL) {
            perror("Error getting local time");
            sleep(1); // Avoid spamming errors
            continue;
        }

        int current_hour = time_info->tm_hour;
        int current_minute = time_info->tm_min;
        int current_second = time_info->tm_sec;

        // Check for schedule transitions
        for (int i = 0; i < num_entries; i++) {
            if (schedule[i].hour == current_hour && schedule[i].minute == current_minute && schedule[i].second == current_second) {
                int gpio_pin;
                switch (schedule[i].relay_number) {
                    case 1:
                        gpio_pin = RELAY1_GPIO;
                        break;
                    case 2:
                        gpio_pin = RELAY2_GPIO;
                        break;
                    case 3:
                        gpio_pin = RELAY3_GPIO;
                        break;
                    case 4:
                        gpio_pin = RELAY4_GPIO;
                        break;
                    default:
                        fprintf(stderr, "Invalid relay number: %d\n", schedule[i].relay_number);
                        continue;
                }

                int current_duty_cycle = gpioGetPWMdutycycle(gpio_pin) / 2.55; // Get current duty cycle
                int target_duty_cycle = schedule[i].state * 100; // 100 for ON, 0 for OFF

                printf("Transition: Relay %d, State %d, Current Duty Cycle %d, Target Duty Cycle %d\n", schedule[i].relay_number, schedule[i].state, current_duty_cycle, target_duty_cycle);

                if (current_duty_cycle != target_duty_cycle) {
                    fade_relay(gpio_pin, current_duty_cycle, target_duty_cycle, FADE_DURATION);
                }
            }
        }

        sleep(1); // Check every second
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(RELAY1_GPIO, 1);
    gpioWrite(RELAY2_GPIO, 1);
    gpioWrite(RELAY3_GPIO, 1);
    gpioWrite(RELAY4_GPIO, 1);
    gpioTerminate();

    return 0;
}

