        struct timespec current_time;
        clock_gettime(CLOCK_MONOTONIC, &current_time);
        long elapsed_ms = (current_time.tv_sec - last_measurement_time.tv_sec) * 1000 + (current_time.tv_nsec - last_measurement_time.tv_nsec) / 1000000;
