#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// Define PWM frequency
#define PWM_FREQUENCY 1000 // Hz

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to set the color of the RGB LED using PWM
void set_rgb_color(int red, int green, int blue) {
    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

// Function to generate a sine wave value
float generate_sine_wave(float time) {
    return (float)(sin(time * M_PI * 2.0) + 1.0) / 2.0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM frequency for all pins
    gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    float time = 0.0;
    while (program_running) {
        // Generate sine wave values
        float proximity = generate_sine_wave(time);

        // Map proximity value to RGB color components (example mapping)
        int red   = (int)(proximity * 255.0);
        int green = (int)((1.0 - proximity) * 255.0);
        int blue  = 0; // Constant blue component

        // Set the RGB color
        set_rgb_color(red, green, blue);

        // Increment time
        time += 0.01; // Adjust for desired speed

        // Delay to control loop frequency
        gpioDelay(10000); // 10ms delay (100Hz)
    }

    // Turn off the LED before exiting
    set_rgb_color(0, 0, 0);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

