#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define BUTTON_PIN 17
#define BUZZER_PIN 18

// Define melody lookup table
typedef struct {
    int frequency;
    int duration;
} Note;

Note melody[] = {
    {440, 250},   // A4
    {494, 250},   // B4
    {523, 250},   // C5
    {0, 500}      // Rest
};

int melody_length = sizeof(melody) / sizeof(melody[0]);

// Global variables
volatile int button_pressed = 0;
volatile int melody_playing = 0;

// Function prototypes
void button_isr(int gpio, int level, uint32_t tick);
void play_melody();
void stop_melody();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    stop_melody();
    gpioTerminate();
    exit(0);
}

// Button interrupt service routine
void button_isr(int gpio, int level, uint32_t tick) {
    static uint32_t last_tick = 0;
    uint32_t current_tick = gpioTick();

    if (current_tick - last_tick > 50000) { // Debounce: 50ms
        if (level == 0) { // Button pressed (active low)
            button_pressed = 1;
            last_tick = current_tick;
        }
    }
}

// Function to play the melody
void play_melody() {
    if (melody_playing) return; // Prevent re-entry

    melody_playing = 1;
    for (int i = 0; i < melody_length; i++) {
        if (!melody_playing) break; // Check if stop_melody was called

        if (melody[i].frequency > 0) {
            gpioPWM(BUZZER_PIN, 128); // 50% duty cycle
            gpioSetPWMfrequency(BUZZER_PIN, melody[i].frequency);
        } else {
            gpioPWM(BUZZER_PIN, 0); // Rest
        }
        gpioDelay(melody[i].duration * 1000); // Delay in microseconds
    }
    stop_melody();
}

// Function to stop the melody
void stop_melody() {
    melody_playing = 0;
    gpioPWM(BUZZER_PIN, 0); // Stop PWM
}

int main() {
    // Initialize pigpio library
