#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define DEFAULT_TIMEOUT_MS 1000
#define SLIDING_WINDOW_SIZE 5

// Structure to hold the sliding window
typedef struct {
    int window[SLIDING_WINDOW_SIZE];
    int head;
    int count;
} SlidingWindow;

// Global variables
static volatile sig_atomic_t terminate = 0;
static FILE *log_file = NULL;
static int timeout_ms = DEFAULT_TIMEOUT_MS;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void cleanup_gpio();
int read_sensor();
void add_to_window(SlidingWindow *window, int value);
int check_threshold(SlidingWindow *window);
void log_event(int value);
void print_alert();
char* get_iso8601_timestamp();
void sliding_window_init(SlidingWindow *window);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize GPIO using pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN); // Use pull-down resistor

    return 0;
}

// Cleanup GPIO resources
void cleanup_gpio() {
    gpioTerminate();
}

// Read sensor value with debouncing
int read_sensor() {
    int value = gpioRead(GPIO_PIN);
    gpioDelay(50); // Debounce delay
    return value;
}

// Add a new value to the sliding window
void add_to_window(SlidingWindow *window, int value) {
    window->window[window->head] = value;
    window->head = (window->head + 1) % SLIDING_WINDOW_SIZE;
    if (window->count < SLIDING_WINDOW_SIZE) {
        window->count++;
    }
}

// Check if the threshold is reached (3 or more HIGH values)
int check_threshold(SlidingWindow *window) {
    if (window->count < 3) {
        return 0;
    }

    int high_count = 0;
    for (int i = 0; i < SLIDING_WINDOW_SIZE; i++) {
        if (window->window[i] == 1) {
            high_count++;
        }
    }

    return (high_count >= 3);
}

// Log event to file
void log_event(int value) {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp\n");
        return;
    }

    if (log_file != NULL) {
        fprintf(log_file, "%s, %d\n", timestamp, value);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Log file is not open\n");
    }
    free(timestamp);
}

// Print earthquake alert message
void print_alert() {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp\n");
        return;
    }

    printf("EARTHQUAKE ALERT: %s\n", timestamp);
    free(timestamp);
}

// Get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *buffer = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (buffer == NULL) {
        fprintf(stderr, "Failed to allocate memory for timestamp\n");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(buffer, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    return buffer;
}

// Initialize the sliding window
void sliding_window_init(SlidingWindow *window) {
    window->head = 0;
    window->count = 0;
    for (int i = 0; i < SLIDING_WINDOW_SIZE; i++) {
        window->window[i] = 0; // Initialize to 0
    }
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        timeout_ms = atoi(argv[1]);
        if (timeout_ms <= 0) {
            fprintf(stderr, "Invalid timeout value. Using default: %d ms\n", DEFAULT_TIMEOUT_MS);
            timeout_ms = DEFAULT_TIMEOUT_MS;
        }
    }

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("vibration_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup_gpio();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    SlidingWindow window;
    sliding_window_init(&window);

    // Main loop
    while (!terminate) {
        int sensor_value = read_sensor();
        add_to_window(&window, sensor_value);
        log_event(sensor_value);

        if (check_threshold(&window)) {
            print_alert();
        }

        gpioDelay(timeout_ms); // Poll every timeout_ms milliseconds
    }

    // Cleanup
    cleanup_gpio();
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

