#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// LSM303DLHC Magnetometer I2C address
#define LSM303_ADDR 0x1E

// LSM303DLHC Magnetometer Registers
#define CRA_REG_M 0x00
#define CRB_REG_M 0x01
#define MR_REG_M 0x02
#define OUT_X_H_M 0x03
#define OUT_X_L_M 0x04
#define OUT_Z_H_M 0x05
#define OUT_Z_L_M 0x06
#define OUT_Y_H_M 0x07
#define OUT_Y_L_M 0x08

// Hard iron calibration offsets
#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_magnetometer();
int read_magnetometer(int16_t *x, int16_t *y, int16_t *z);
void calibrate_magnetometer(int16_t x, int16_t y, int16_t z, int16_t *calibrated_x, int16_t *calibrated_y, int16_t *calibrated_z);
float calculate_heading(int16_t x, int16_t y);
char *map_heading_to_direction(float heading);
int log_data(int16_t x, int16_t y, int16_t z, float heading);
void signal_handler(int signal);

// Structure to hold magnetometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} magnetometer_data_t;

// Function to initialize the I2C interface
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, LSM303_ADDR, 0); // Bus 1, address 0x1E, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to initialize the LSM303DLHC magnetometer
int init_magnetometer() {
    // Configure CRA_REG_M (0x00): Output data rate (ODR) = 15 Hz, Temp sensor enable
    if (i2cWriteByteData(i2c_handle, CRA_REG_M, 0x18) < 0) {
        fprintf(stderr, "Failed to write to CRA_REG_M\n");
        return -1;
    }

    // Configure CRB_REG_M (0x01): Gain = +/- 1.3 Gauss
    if (i2cWriteByteData(i2c_handle, CRB_REG_M, 0x20) < 0) {
        fprintf(stderr, "Failed to write to CRB_REG_M\n");
        return -1;
    }

    // Configure MR_REG_M (0x02): Continuous conversion mode
    if (i2cWriteByteData(i2c_handle, MR_REG_M, 0x00) < 0) {
        fprintf(stderr, "Failed to write to MR_REG_M\n");
        return -1;
    }

    return 0;
}

// Function to read magnetometer data
int read_magnetometer(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, OUT_X_H_M, buffer, 6) != 6) {
        fprintf(stderr, "Failed to read magnetometer data\n");
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *z = (int16_t)((buffer[2] << 8) | buffer[3]);
    *y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Function to calibrate the magnetometer data
void calibrate_magnetometer(int16_t x, int16_t y, int16_t z, int16_t *calibrated_x, int16_t *calibrated_y, int16_t *calibrated_z) {
    *calibrated_x = x - X_OFFSET;
    *calibrated_y = y - Y_OFFSET;
    *calibrated_z = z - Z_OFFSET;
}

// Function to calculate the heading in degrees
float calculate_heading(int16_t x, int16_t y) {
    float heading = atan2(y, x) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }
    return heading;
}

// Function to map the heading to a compass direction
char *map_heading_to_direction(float heading) {
    if (heading >= 337.5 || heading < 22.5) {
        return "N";
    } else if (heading >= 22.5 && heading < 67.5) {
        return "NE";
    } else if (heading >= 67.5 && heading < 112.5) {
        return "E";
    } else if (heading >= 112.5 && heading < 157.5) {
        return "SE";
    } else if (heading >= 157.5 && heading < 202.5) {
        return "S";
    } else if (heading >= 202.5 && heading < 247.5) {
        return "SW";
    } else if (heading >= 247.5 && heading < 292.5) {
        return "W";
    } else {
        return "NW";
    }
}

// Function to log the data to a CSV file
int log_data(int16_t x, int16_t y, int16_t z, float heading) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen("mag_log.csv", "a");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open log file\n");
            return -1;
        }
        fprintf(log_file, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading\n");
    }

    fprintf(log_file, "%s,%d,%d,%d,%.2f\n", timestamp, x, y, z, heading);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        return 1;
    }

    // Initialize magnetometer
    if (init_magnetometer() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    magnetometer_data_t raw_data;
    int16_t calibrated_x, calibrated_y, calibrated_z;
    float heading;
    char *direction;

    printf("Magnetometer data logging started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read magnetometer data
        if (read_magnetometer(&raw_data.x, &raw_data.y, &raw_data.z) == 0) {
            // Calibrate magnetometer data
            calibrate_magnetometer(raw_data.x, raw_data.y, raw_data.z, &calibrated_x, &calibrated_y, &calibrated_z);

            // Calculate heading
            heading = calculate_heading(calibrated_x, calibrated_y);

            // Map heading to direction
            direction = map_heading_to_direction(heading);

            // Log data
            if (log_data(calibrated_x, calibrated_y, calibrated_z, heading) < 0) {
                fprintf(stderr, "Failed to log data\n");
            }

            // Print heading and direction
            printf("Heading: %.2f degrees, Direction: %s\n", heading, direction);
        } else {
            fprintf(stderr, "Failed to read magnetometer data. Retrying...\n");
        }

        gpioDelay(1000); // Wait for 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    if (log_file != NULL) {
        fclose(log_file);
    }

    printf("Magnetometer data logging stopped.\n");

    return 0;
}

