#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Debounce time in milliseconds
#define DEBOUNCE_TIME 200

// Global variables
static volatile unsigned long last_touch_time = 0;
static volatile int relay_state = 0; // 0 = OFF, 1 = ON
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
void touch_callback(int gpio, int level, unsigned int tick, void *user_data);
int toggle_relay();
int log_relay_state(const char *state);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN);

    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Initialize relay to OFF

    return 0;
}

// Callback function for touch sensor interrupt
void touch_callback(int gpio, int level, unsigned int tick, void *user_data) {
    if (level == 1) { // Rising edge detected (touch)
        unsigned long current_time = gpioTick();
        if (current_time - last_touch_time > DEBOUNCE_TIME * 1000) { // Convert ms to us
            if (toggle_relay() == 0) {
                if (relay_state == 1) {
                    log_relay_state("ON");
                } else {
                    log_relay_state("OFF");
                }
            } else {
                fprintf(stderr, "Failed to toggle relay\n");
            }
            last_touch_time = current_time;
        }
    }
}

// Function to toggle the relay state
int toggle_relay() {
    relay_state = !relay_state;
    if (gpioWrite(RELAY_PIN, relay_state) != 0) {
        fprintf(stderr, "Failed to write to relay pin\n");
        return 1;
    }
    return 0;
}

// Function to log relay state to file
int log_relay_state(const char *state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return 1;
    }

    fprintf(log_file, "{\"timestamp\": \"%s\", \"relay_state\": \"%s\"}\n", timestamp, state);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Cleanup function to release resources
void cleanup() {
    // Force relay OFF
    gpioWrite(RELAY_PIN, 0);

    // Log final relay state
    log_relay_state("OFF");

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("relay_log.json", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Set up interrupt callback
    if (gpioSetAlertFuncEx(TOUCH_SENSOR_PIN, touch_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function\n");
        cleanup();
        return 1;
    }

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    // Keep the program running
    while (1) {
        sleep(1); // Reduce CPU usage
    }

    return 0;
}

