#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_GPIO 17
#define RELAY2_GPIO 23
#define RELAY3_GPIO 24
#define RELAY4_GPIO 25

// Define moisture threshold
#define MOISTURE_THRESHOLD 30

// Define irrigation duration (seconds)
#define IRRIGATION_DURATION 5

// Define gap between relays (seconds)
#define RELAY_GAP 1

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static int soil_moisture = 0;

// Function prototypes
int initialize_gpio();
int generate_moisture_level();
int control_relay(int gpio, int state);
int log_irrigation_event(int relay_number, int moisture_level);
void signal_handler(int signal);
void cleanup();

// Structure to hold GPIO pin configurations
typedef struct {
    int relay1;
    int relay2;
    int relay3;
    int relay4;
} gpio_config_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    gpio_config_t config = {RELAY1_GPIO, RELAY2_GPIO, RELAY3_GPIO, RELAY4_GPIO};

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO pins as outputs
    if (gpioSetMode(config.relay1, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", config.relay1);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(config.relay2, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", config.relay2);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(config.relay3, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", config.relay3);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(config.relay4, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", config.relay4);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to generate a random soil moisture level
int generate_moisture_level() {
    return rand() % 101; // Returns a value between 0 and 100
}

// Function to control the relay state
int control_relay(int gpio, int state) {
    if (gpioWrite(gpio, state) != 0) {
        fprintf(stderr, "Failed to write to GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

// Function to log irrigation events
int log_irrigation_event(int relay_number, int moisture_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s, Relay %d, Moisture Level: %d\n", timestamp, relay_number, moisture_level);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");

    // Deactivate all relays
    control_relay(RELAY1_GPIO, 1);
    control_relay(RELAY2_GPIO, 1);
    control_relay(RELAY3_GPIO, 1);
    control_relay(RELAY4_GPIO, 1);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen("irrigation_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    printf("Smart Irrigation System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Generate a new soil moisture level
        soil_moisture = generate_moisture_level();
        printf("Soil moisture level: %d\n", soil_moisture);

        // Check if the moisture level is below the threshold
        if (soil_moisture < MOISTURE_THRESHOLD) {
            printf("Moisture level below threshold. Activating irrigation.\n");

            // Activate relays sequentially
            for (int i = 1; i <= 4; i++) {
                int gpio;
                switch (i) {
                    case 1: gpio = RELAY1_GPIO; break;
                    case 2: gpio = RELAY2_GPIO; break;
                    case 3: gpio = RELAY3_GPIO; break;
                    case 4: gpio = RELAY4_GPIO; break;
                    default: gpio = -1; break; // Should not happen
                }

                if (gpio != -1) {
                    if (control_relay(gpio, 0) == 0) { // Activate relay (low)
                        log_irrigation_event(i, soil_moisture);
                        gpioDelay(IRRIGATION_DURATION * 1000000); // Delay for irrigation duration (microseconds)
                        if (control_relay(gpio, 1) == 0) { // Deactivate relay (high)
                            gpioDelay(RELAY_GAP * 1000000); // Delay for relay gap (microseconds)
                        } else {
                            fprintf(stderr, "Error deactivating relay %d\n", i);
                        }
                    } else {
                        fprintf(stderr, "Error activating relay %d\n", i);
                    }
                }
            }
        } else {
            printf("Moisture level is sufficient. No irrigation needed.\n");
        }

        // Wait for 10 seconds
        gpioDelay(10000000); // 10 seconds (microseconds)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

