#define VALVE_OPEN 1500
#define VALVE_CLOSED 500
#define NOZZLE_0 500
#define NOZZLE_45 1000
#define NOZZLE_90 1500
#define NOZZLE_135 2000
#define NOZZLE_180 2500

// Define moisture thresholds
#define MOISTURE_THRESHOLD_LOW 50
#define MOISTURE_THRESHOLD_HIGH 50

// Define spray duration
#define SPRAY_DURATION 5

// Define delay between cycles
#define CYCLE_DELAY 5

// Define retry count and backoff delay
#define MAX_RETRIES 3
#define BACKOFF_DELAY 100

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_soil_moisture();
int open_valve();
int close_valve();
int sweep_nozzle();
void log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("Received signal %d, shutting down...\n", signal);
        program_running = 0;
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(VALVE_PIN, PI_OUTPUT);
    gpioSetMode(NOZZLE_PIN, PI_OUTPUT);

    return 0;
}

// Read simulated soil moisture value
int read_soil_moisture() {
    static int moisture_level = 20;
    static int direction = 1; // 1 for increasing, -1 for decreasing

    moisture_level += direction;

    if (moisture_level > 100) {
        moisture_level = 100;
        direction = -1;
    } else if (moisture_level < 20) {
        moisture_level = 20;
        direction = 1;
    }

    return moisture_level;
}

// Open the valve
int open_valve() {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = gpioServo(VALVE_PIN, VALVE_OPEN);
        if (result == 0) {
            return 0; // Success
        } else {
            log_error("Failed to open valve");
            retries++;
            gpioDelay(BACKOFF_DELAY * 1000); // Convert ms to us
        }
    }

    fprintf(stderr, "Failed to open valve after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Close the valve
int close_valve() {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = gpioServo(VALVE_PIN, VALVE_CLOSED);
        if (result == 0) {
            return 0; // Success
        } else {
            log_error("Failed to close valve");
            retries++;
            gpioDelay(BACKOFF_DELAY * 1000); // Convert ms to us
        }
    }

    fprintf(stderr, "Failed to close valve after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Sweep the nozzle
int sweep_nozzle() {
    int angles[] = {0, 45, 90, 135, 180};
    int pulse_widths[] = {NOZZLE_0, NOZZLE_45, NOZZLE_90, NOZZLE_135, NOZZLE_180};
    int num_angles = sizeof(angles) / sizeof(angles[0]);
    int retries, result;

    for (int i = 0; i < num_angles; i++) {
        retries = 0;
        while (retries < MAX_RETRIES) {
            result = gpioServo(NOZZLE_PIN, pulse_widths[i]);
            if (result == 0) {
                gpioDelay(2000000); // 2 seconds
                break; // Success
            } else {
                log_error("Failed to set nozzle angle");
                retries++;
                gpioDelay(BACKOFF_DELAY * 1000); // Convert ms to us
            }
        }
        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to set nozzle angle after %d retries, skipping to next angle\n", MAX_RETRIES);
            continue; // Skip to the next angle
        }
    }

    return 0;
}

// Log errors to file
void log_error(const char *message) {
    FILE *fp = fopen("watering.log", "a");
    if (fp != NULL) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
        fclose(fp);
    } else {
        fprintf(stderr, "Failed to open log file\n");
    }
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    gpioServo(VALVE_PIN, 0); // Stop valve
    gpioServo(NOZZLE_PIN, 0); // Stop nozzle
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Plant watering system started\n");

    while (program_running) {
        // Read soil moisture
        int moisture = read_soil_moisture();
        printf("Soil moisture: %d\n", moisture);

        // Watering cycle
        if (moisture < MOISTURE_THRESHOLD_LOW) {
            printf("Moisture below threshold, starting watering cycle\n");

            // Open valve
            if (open_valve() != 0) {
                fprintf(stderr, "Failed to open valve, skipping watering cycle\n");
                continue; // Skip to the next cycle
            }

            // Sweep nozzle
            if (sweep_nozzle() != 0) {
                fprintf(stderr, "Failed to sweep nozzle, skipping watering cycle\n");
            }

            // Spray
            printf("Spraying for %d seconds\n", SPRAY_DURATION);
            gpioDelay(SPRAY_DURATION * 1000000); // Convert seconds to microseconds

            // Close valve
            if (close_valve() != 0) {
                fprintf(stderr, "Failed to close valve, skipping watering cycle\n");
            }

            printf("Watering cycle complete\n");
        } else {
            printf("Moisture above threshold, skipping watering cycle\n");
        }

        // Wait before next cycle
        printf("Waiting for %d seconds before next cycle\n", CYCLE_DELAY);
        gpioDelay(CYCLE_DELAY * 1000000); // Convert seconds to microseconds
    }

    // Cleanup and exit
    cleanup();
    printf("Plant watering system stopped\n");
    return 0;
}

