#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 50000       // Timeout in microseconds (50ms)
#define MIN_DISTANCE 2.0      // Minimum measurable distance in cm
#define MAX_DISTANCE 400.0    // Maximum measurable distance in cm

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
void trigger_sensor();
long long get_pulse_width();
double calculate_distance(long long pulse_width);
int log_distance(double distance);
void signal_handler(int signal);
void cleanup();

// Structure to hold GPIO configuration
typedef struct {
    int trigger_pin;
    int echo_pin;
} gpio_config_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    return 0;
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse width
long long get_pulse_width() {
    long long start_tick, end_tick, pulse_width;

    // Wait for the echo pin to go high with a timeout
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        gpioDelay(1); // Check every microsecond
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for rising edge\n");
        return -1; // Timeout
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go low with a timeout
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        gpioDelay(1); // Check every microsecond
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for falling edge\n");
        return -1; // Timeout
    }

    end_tick = gpioTick();

    pulse_width = end_tick - start_tick;
    return pulse_width;
}

// Function to calculate the distance in centimeters
double calculate_distance(long long pulse_width) {
    if (pulse_width < 0) {
        return -1.0; // Indicate error
    }

    double time_taken = (double)pulse_width / 1000000.0; // Convert microseconds to seconds
    double distance = (time_taken * SPEED_OF_SOUND) / 2.0;

    // Validate distance
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        fprintf(stderr, "Distance out of range: %.2f cm\n", distance);
        return -1.0; // Indicate out-of-range error
    }

    return distance;
}

// Function to log the distance to a file
int log_distance(double distance) {
    if (distance < 0) {
        fprintf(log_file, "-1\n");
        fprintf(stderr, "Error: Invalid distance value\n");
        return -1;
    }

    fprintf(log_file, "%.2f\n", distance);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        trigger_sensor();
        long long pulse_width = get_pulse_width();
        double distance = calculate_distance(pulse_width);

        if (log_distance(distance) != 0) {
            fprintf(stderr, "Error logging distance\n");
        }

        gpioDelay(60000); // Wait 60 ms
    }

    // Cleanup and exit
    cleanup();
    printf("Distance measurement stopped.\n");
    return 0;
}

