#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_GPIO 17
#define RELAY2_GPIO 18
#define RELAY3_GPIO 27
#define RELAY4_GPIO 22

// Define the watering duration in seconds
#define WATERING_DURATION 5

// Define the total cycle duration in seconds
#define TOTAL_CYCLE_DURATION 86400

// Define the log file name
#define LOG_FILE "watering_log.txt"

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
void set_relay_state(int gpio, int state);
void water_plant(int gpio);
void log_cycle_start();
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library and set GPIO pins as outputs
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY2_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY3_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY4_GPIO, PI_OUTPUT);

    // Initialize all relays to OFF (HIGH)
    set_relay_state(RELAY1_GPIO, 1);
    set_relay_state(RELAY2_GPIO, 1);
    set_relay_state(RELAY3_GPIO, 1);
    set_relay_state(RELAY4_GPIO, 1);

    return 0; // Indicate success
}

// Function to set the state of a relay (ON or OFF)
void set_relay_state(int gpio, int state) {
    gpioWrite(gpio, state); // pigpio uses 0 for LOW and 1 for HIGH
}

// Function to water a plant for a specified duration
void water_plant(int gpio) {
    set_relay_state(gpio, 0); // Turn relay ON (LOW)
    gpioDelay(WATERING_DURATION * 1000000); // Delay for watering duration (microseconds)
    set_relay_state(gpio, 1); // Turn relay OFF (HIGH)
}

// Function to log the start time of a watering cycle to a file
void log_cycle_start() {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s\n", s);
    fclose(fp);
}

// Function to perform cleanup before exiting
void cleanup() {
    // Turn off all relays
    set_relay_state(RELAY1_GPIO, 1);
    set_relay_state(RELAY2_GPIO, 1);
    set_relay_state(RELAY3_GPIO, 1);
    set_relay_state(RELAY4_GPIO, 1);

    gpioTerminate(); // Terminate pigpio
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Plant watering system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Log the start of the watering cycle
        log_cycle_start();

        // Water each plant in turn
        water_plant(RELAY1_GPIO);
        water_plant(RELAY2_GPIO);
        water_plant(RELAY3_GPIO);
        water_plant(RELAY4_GPIO);

        // Wait for the total cycle duration
        sleep(TOTAL_CYCLE_DURATION);
    }

    // Perform cleanup before exiting
    cleanup();

    printf("Plant watering system stopped.\n");

    return 0;
}

