#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for the relays
#define RELAY1_GPIO 17
#define RELAY2_GPIO 18
#define RELAY3_GPIO 27
#define RELAY4_GPIO 22

// Define PWM frequency
#define PWM_FREQUENCY 1000 // 1 kHz

// Define sunrise duration (in seconds)
#define SUNRISE_DURATION 1800 // 30 minutes

// Define log file name
#define LOG_FILE "smart_lighting.log"

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
int set_relay_intensity(int gpio, int intensity);
int calculate_intensity(int time_elapsed);
void log_event(const char *message);
void signal_handler(int signal);
void cleanup();

// Structure to hold GPIO pin configurations
typedef struct {
    int relay1;
    int relay2;
    int relay3;
    int relay4;
} gpio_config_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    gpio_config_t config = {RELAY1_GPIO, RELAY2_GPIO, RELAY3_GPIO, RELAY4_GPIO};

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO pins as outputs
    if (gpioSetMode(config.relay1, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", config.relay1);
        return -1;
    }
    if (gpioSetMode(config.relay2, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", config.relay2);
        return -1;
    }
    if (gpioSetMode(config.relay3, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", config.relay3);
        return -1;
    }
    if (gpioSetMode(config.relay4, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", config.relay4);
        return -1;
    }

    // Set PWM frequency for all GPIO pins
    if (gpioSetPWMfrequency(config.relay1, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", config.relay1);
        return -1;
    }
    if (gpioSetPWMfrequency(config.relay2, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", config.relay2);
        return -1;
    }
    if (gpioSetPWMfrequency(config.relay3, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", config.relay3);
        return -1;
    }
    if (gpioSetPWMfrequency(config.relay4, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", config.relay4);
        return -1;
    }

    return 0;
}

// Function to set the intensity of a relay
int set_relay_intensity(int gpio, int intensity) {
    if (intensity < 0 || intensity > 255) {
        fprintf(stderr, "Invalid intensity value: %d. Must be between 0 and 255\n", intensity);
        return -1;
    }

    if (gpioPWM(gpio, intensity) != 0) {
        fprintf(stderr, "Failed to set PWM duty cycle for GPIO %d\n", gpio);
        return -1;
    }

    return 0;
}

// Function to calculate the intensity based on time elapsed
int calculate_intensity(int time_elapsed) {
    if (time_elapsed < 0) {
        fprintf(stderr, "Invalid time elapsed: %d. Must be non-negative\n", time_elapsed);
        return -1;
    }

    if (time_elapsed >= SUNRISE_DURATION) {
        return 255; // Full intensity
    }

    return (int)(((float)time_elapsed / SUNRISE_DURATION) * 255.0);
}

// Function to log events to a file
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "[%s] %s\n", timestamp, message);
        fflush(log_file); // Ensure the log is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_event("Received signal, shutting down...");
}

// Function to clean up resources before exiting
void cleanup() {
    log_event("Cleaning up resources...");

    // Turn off all relays
    set_relay_intensity(RELAY1_GPIO, 0);
    set_relay_intensity(RELAY2_GPIO, 0);
    set_relay_intensity(RELAY3_GPIO, 0);
    set_relay_intensity(RELAY4_GPIO, 0);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    log_event("Cleanup complete. Exiting.");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        return 1;
    }

    log_event("Starting smart lighting program...");

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_event("GPIO initialization failed. Exiting.");
        cleanup();
        return 1;
    }

    log_event("GPIO initialization complete.");

    // Main loop
    int time_elapsed = 0;
    while (running && time_elapsed <= SUNRISE_DURATION) {
        // Calculate intensity
        int intensity = calculate_intensity(time_elapsed);
        if (intensity == -1) {
            log_event("Error calculating intensity. Exiting.");
            break;
        }

        // Set relay intensities
        if (set_relay_intensity(RELAY1_GPIO, intensity) != 0) {
            log_event("Error setting relay 1 intensity. Exiting.");
            break;
        }
        if (set_relay_intensity(RELAY2_GPIO, intensity) != 0) {
            log_event("Error setting relay 2 intensity. Exiting.");
            break;
        }
        if (set_relay_intensity(RELAY3_GPIO, intensity) != 0) {
            log_event("Error setting relay 3 intensity. Exiting.");
            break;
        }
        if (set_relay_intensity(RELAY4_GPIO, intensity) != 0) {
            log_event("Error setting relay 4 intensity. Exiting.");
            break;
        }

        // Log the intensity
        char log_message[100];
        snprintf(log_message, sizeof(log_message), "Intensity set to %d", intensity);
        log_event(log_message);

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function takes milliseconds

        // Increment time elapsed
        time_elapsed += 1;
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

