#include <wiringPiI2C.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define GYRO_XOUT_H  0x43
#define GYRO_YOUT_H  0x45
#define GYRO_ZOUT_H  0x47

// LED GPIO pin (BCM)
#define LED_PIN 17

// Circular buffer size
#define BUFFER_SIZE 100

// Gyroscope sensitivity (degrees/second per LSB)
#define GYRO_SENSITIVITY 131.0

// Threshold for angular velocity (degrees/second)
#define THRESHOLD 250.0

// Structure to hold gyroscope data
typedef struct {
    time_t timestamp;
    float x;
    float y;
    float z;
} gyro_data_t;

// Circular buffer
gyro_data_t gyro_buffer[BUFFER_SIZE];
int buffer_index = 0;

// I2C file descriptor
int fd;

// Function prototypes
int init_i2c(int address);
int read_gyro_data(int fd, float *x, float *y, float *z);
void add_to_buffer(gyro_data_t data);
gyro_data_t get_from_buffer(int index);
void control_led(float x, float y, float z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    digitalWrite(LED_PIN, LOW); // Turn off LED
    close(fd); // Close I2C connection
    wiringPiSetupGpio(); // Reinitialize wiringPi
    pinMode(LED_PIN, OUTPUT); // Set LED pin as output
    digitalWrite(LED_PIN, LOW); // Ensure LED is off
    exit(0);
}

// Initialize I2C communication
int init_i2c(int address) {
    int fd = wiringPiI2CSetup(address);
    if (fd == -1) {
        fprintf(stderr, "Error initializing I2C: %s\n", strerror(errno));
        return -1;
    }

    // Wake up the MPU-6050 (clear sleep mode bit)
    if (wiringPiI2CWriteReg8(fd, PWR_MGMT_1, 0) == -1) {
        fprintf(stderr, "Error writing to PWR_MGMT_1: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Read gyroscope data from MPU-6050
int read_gyro_data(int fd, float *x, float *y, float *z) {
    int16_t raw_x, raw_y, raw_z;

    // Read raw gyroscope data
    raw_x = (int16_t)((wiringPiI2CReadReg8(fd, GYRO_XOUT_H) << 8) | wiringPiI2CReadReg8(fd, GYRO_XOUT_H + 1));
    raw_y = (int16_t)((wiringPiI2CReadReg8(fd, GYRO_YOUT_H) << 8) | wiringPiI2CReadReg8(fd, GYRO_YOUT_H + 1));
    raw_z = (int16_t)((wiringPiI2CReadReg8(fd, GYRO_ZOUT_H) << 8) | wiringPiI2CReadReg8(fd, GYRO_ZOUT_H + 1));

    // Convert to degrees per second
    *x = (float)raw_x / GYRO_SENSITIVITY;
    *y = (float)raw_y / GYRO_SENSITIVITY;
    *z = (float)raw_z / GYRO_SENSITIVITY;

    return 0;
}

// Add data to the circular buffer
void add_to_buffer(gyro_data_t data) {
    gyro_buffer[buffer_index] = data;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Get data from the circular buffer
gyro_data_t get_from_buffer(int index) {
    return gyro_buffer[index];
}

// Control the LED based on angular velocity
void control_led(float x, float y, float z) {
    if (fabs(x) > THRESHOLD || fabs(y) > THRESHOLD || fabs(z) > THRESHOLD) {
        digitalWrite(LED_PIN, HIGH); // Turn on LED
    } else {
        digitalWrite(LED_PIN, LOW);  // Turn off LED
    }
}

int main() {
    // Initialize wiringPi using BCM GPIO numbering
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Set LED pin as output
    pinMode(LED_PIN, OUTPUT);

    // Initialize I2C communication with retry mechanism
    int retries = 0;
    while (retries < 3) {
        fd = init_i2c(MPU6050_ADDR);
        if (fd != -1) {
            break; // I2C initialized successfully
        }
        fprintf(stderr, "Retrying I2C initialization (%d/3)...\n", retries + 1);
        retries++;
        delay(100); // Wait before retrying
    }

    if (fd == -1) {
        fprintf(stderr, "Failed to initialize I2C after multiple retries.\n");
        return 1;
    }

    // Set up signal handling for Ctrl+C and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float x, y, z;
    time_t current_time;
    gyro_data_t gyro_data;

    // Main loop
    while (1) {
        // Read gyroscope data
        if (read_gyro_data(fd, &x, &y, &z) == 0) {
            // Get current timestamp
            current_time = time(NULL);

            // Populate gyro_data struct
            gyro_data.timestamp = current_time;
            gyro_data.x = x;
            gyro_data.y = y;
            gyro_data.z = z;

            // Add data to the circular buffer
            add_to_buffer(gyro_data);

            // Control the LED
            control_led(x, y, z);

            // Print the data (optional)
            //printf("Timestamp: %ld, X: %.2f, Y: %.2f, Z: %.2f\n", current_time, x, y, z);
        } else {
            fprintf(stderr, "Error reading gyroscope data.\n");
        }

        // Delay for 50 milliseconds (20 Hz sampling rate)
        delay(50);
    }

    return 0;
}

