#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <stdbool.h>

// MPU-9250 Register Addresses
#define MPU9250_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47
#define GYRO_CONFIG 0x1B

// SPI Configuration
#define SPI_BUS "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz

// GPIO Configuration
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 8

// Global Variables
static int spi_fd = -1;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z);
char* get_iso8601_timestamp(char *timestamp_str, size_t size);
int log_data(const char *timestamp, int16_t x, int16_t y, int16_t z);
void signal_handler(int sig);
int initialize();
void cleanup();

// SPI Transfer Function
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
    };

    int ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer);
    if (ret < 0) {
        fprintf(stderr, "SPI Transfer Error: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read Gyroscope Data Function
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t tx_buf[7];
    uint8_t rx_buf[7];
    int retries = 3;

    tx_buf[0] = GYRO_XOUT_H | 0x80; // Read multiple bytes starting from GYRO_XOUT_H
    memset(rx_buf, 0, sizeof(rx_buf));

    while (retries > 0) {
        if (spi_transfer(tx_buf, rx_buf, 7) == 0) {
            *x = (int16_t)((rx_buf[1] << 8) | rx_buf[2]);
            *y = (int16_t)((rx_buf[3] << 8) | rx_buf[4]);
            *z = (int16_t)((rx_buf[5] << 8) | rx_buf[6]);
            return 0; // Success
        } else {
            fprintf(stderr, "SPI Read Error, retrying...\n");
            retries--;
            usleep(10000); // 10ms delay
        }
    }

    fprintf(stderr, "Failed to read gyro data after multiple retries.\n");
    return -1; // Failure
}

// Get ISO 8601 Timestamp Function
char* get_iso8601_timestamp(char *timestamp_str, size_t size) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    strftime(timestamp_str, size, "%Y-%m-%dT%H:%M:%S", &tm_info);
    snprintf(timestamp_str + strlen(timestamp_str), size - strlen(timestamp_str), ".%09ldZ", ts.tv_nsec);

    return timestamp_str;
}

// Log Data Function
int log_data(const char *timestamp, int16_t x, int16_t y, int16_t z) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal Handler Function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialization Function
int initialize() {
    // SPI Initialization
    spi_fd = open(SPI_BUS, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI Open Error: %s\n", strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI Mode Set Error: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI Bits Per Word Set Error: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI Max Speed Hz Set Error: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    // GPIO Initialization
    gpio_line = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_line) {
        fprintf(stderr, "GPIO Chip Open Error: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_line, GPIO_LINE);
    if (!gpio_line) {
        fprintf(stderr, "GPIO Line Get Error: %s\n", strerror(errno));
        gpiod_chip_close(gpio_line);
        close(spi_fd);
        return -1;
    }

    if (gpiod_line_request_output(gpio_line, "spi_cs", 0) < 0) {
        fprintf(stderr, "GPIO Line Request Output Error: %s\n", strerror(errno));
        gpiod_chip_close(gpio_line);
        close(spi_fd);
        return -1;
    }

    // MPU-9250 Initialization
    uint8_t init_buf[2];

    // Wake up the MPU-9250 (clear sleep mode bit)
    init_buf[0] = PWR_MGMT_1;
    init_buf[1] = 0x00;
    if (spi_transfer(init_buf, NULL, 2) < 0) {
        fprintf(stderr, "MPU-9250 Wake Up Error\n");
        gpiod_chip_close(gpio_line);
        close(spi_fd);
        return -1;
    }

    // Configure gyroscope range (+/- 250 dps)
    init_buf[0] = GYRO_CONFIG;
    init_buf[1] = 0x00; // Full scale range of +/- 250 dps
    if (spi_transfer(init_buf, NULL, 2) < 0) {
        fprintf(stderr, "MPU-9250 Gyro Config Error\n");
        gpiod_chip_close(gpio_line);
        close(spi_fd);
        return -1;
    }

    // Open Log File
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Log File Open Error: %s\n", strerror(errno));
        gpiod_chip_close(gpio_line);
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Cleanup Function
void cleanup() {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (gpio_line) {
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_line);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    // Register Signal Handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() < 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    int16_t x, y, z;
    char timestamp[32];

    // Main Loop
    while (!terminate) {
