#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <wiringPi.h>

// Constants
#define SPI_BUS 0
#define SPI_DEVICE 0
#define SPI_SPEED 3900000 // 3.9 MHz
#define SPI_MODE 0
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define GYRO_CONFIG 0x1B
#define GYRO_XOUT_H 0x43
#define LED_PIN 17
#define BUFFER_SIZE 64
#define GYRO_SCALE 131.0 // Sensitivity scale factor for +/- 250 deg/s range
#define THRESHOLD 200.0

// Data structure for gyroscope data
typedef struct {
    long timestamp;
    float x;
    float y;
    float z;
} gyro_data_t;

// Circular buffer structure
typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global variables
int spi_fd;
circular_buffer_t gyro_buffer;
bool running = true;

// Function prototypes
int spi_init(int bus, int device, int speed, int mode);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len);
int mpu6050_init(int fd);
int read_gyro_data(int fd, float *x, float *y, float *z);
void buffer_init(circular_buffer_t *buffer);
void buffer_add(circular_buffer_t *buffer, gyro_data_t data);
void buffer_print(circular_buffer_t *buffer);
void signal_handler(int signal);
void blink_led(int pin, int duration_ms);

// SPI initialization function
int spi_init(int bus, int device, int speed, int mode) {
    char spi_device[20];
    snprintf(spi_device, sizeof(spi_device), "/dev/spidev%d.%d", bus, device);

    int fd = open(spi_device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode_u8 = mode;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_u8) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set SPI speed
    uint32_t speed_u32 = speed;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_u32) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI transfer function
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// MPU6050 initialization function
int mpu6050_init(int fd) {
    uint8_t tx_buf[2];
    uint8_t rx_buf[2];

    // Wake up the MPU6050 (clear sleep mode bit)
    tx_buf[0] = PWR_MGMT_1;
    tx_buf[1] = 0x00;
    if (spi_transfer(fd, tx_buf, rx_buf, 2) < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1 register\n");
        return -1;
    }

    // Configure gyroscope range to +/- 250 deg/s
    tx_buf[0] = GYRO_CONFIG;
    tx_buf[1] = 0x00; // 0x00 for +/- 250 deg/s
    if (spi_transfer(fd, tx_buf, rx_buf, 2) < 0) {
        fprintf(stderr, "Error writing to GYRO_CONFIG register\n");
        return -1;
    }

    return 0;
}

// Function to read gyroscope data
int read_gyro_data(int fd, float *x, float *y, float *z) {
    uint8_t tx_buf[7];
    uint8_t rx_buf[7];

    // Read gyroscope data registers (X, Y, Z)
    tx_buf[0] = GYRO_XOUT_H | 0x80; // Read multiple bytes starting from GYRO_XOUT_H
    memset(rx_buf, 0, sizeof(rx_buf));

    if (spi_transfer(fd, tx_buf, rx_buf, 7) < 0) {
        fprintf(stderr, "Error reading gyroscope data\n");
        return -1;
    }

    // Combine high and low bytes for each axis
    int16_t raw_x = (rx_buf[2] << 8) | rx_buf[1];
    int16_t raw_y = (rx_buf[4] << 8) | rx_buf[3];
    int16_t raw_z = (rx_buf[6] << 8) | rx_buf[5];

    // Convert to degrees per second
    *x = (float)raw_x / GYRO_SCALE;
    *y = (float)raw_y / GYRO_SCALE;
    *z = (float)raw_z / GYRO_SCALE;

    return 0;
}

// Circular buffer initialization function
void buffer_init(circular_buffer_t *buffer) {
    buffer->head = 0;
    buffer->count = 0;
}

// Circular buffer add function
void buffer_add(circular_buffer_t *buffer, gyro_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Circular buffer print function
void buffer_print(circular_buffer_t *buffer) {
    printf("Timestamp,X,Y,Z\n");
    for (int i = 0; i < buffer->count; i++) {
        int index = (buffer->head - buffer->count + i + BUFFER_SIZE) % BUFFER_SIZE;
        printf("%ld,%.2f,%.2f,%.2f\n", buffer->data[index].timestamp, buffer->data[index].x, buffer->data[index].y, buffer->data[index].z);
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = false;
}

// LED blink function
void blink_led(int pin, int duration_ms) {
    digitalWrite(pin, HIGH);
    delay(duration_ms);
    digitalWrite(pin, LOW);
    delay(duration_ms);
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi\n");
        return 1;
    }

    // Set LED pin as output
    pinMode(LED_PIN, OUTPUT);

    // Initialize SPI
    spi_fd = spi_init(SPI_BUS, SPI_DEVICE, SPI_SPEED, SPI_MODE);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return 1;
    }

    // Initialize MPU6050
    if (mpu6050_init(spi_fd) < 0) {
        fprintf(stderr, "MPU6050 initialization failed\n");
        close(spi_fd);
        return 1;
    }

    // Initialize circular buffer
    buffer_init(&gyro_buffer);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float x, y, z;
    struct timespec ts;

    printf("Starting data acquisition...\n");

    while (running) {
        // Read gyroscope data
        if (read_gyro_data(spi_fd, &x, &y, &z) == 0) {
            // Get timestamp
            if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
                perror("clock_gettime");
                running = false;
                continue;
            }
            long timestamp = ts.tv_sec * 1000000000LL + ts.tv_nsec;

            // Store data in circular buffer
            gyro_data_t data = {timestamp, x, y, z};
            buffer_add(&gyro_buffer, data);

            // Check for threshold exceedance
            if (fabs(x) > THRESHOLD || fabs(y) > THRESHOLD || fabs(z) > THRESHOLD) {
                printf("Threshold exceeded! X=%.2f, Y=%.2f, Z=%.2f\n", x, y, z);
                blink_led(LED_PIN, 500);
            }
        } else {
            fprintf(stderr, "Failed to read gyro data. Retrying...\n");
        }

        delay(10); // Sample every 10 ms
    }

    // Print buffer before exiting
    buffer_print(&gyro_buffer);

    // Close SPI device
    close(spi_fd);

    printf("Exiting.\n");
    return 0;
}

