    struct timespec ts;

    printf("Starting data acquisition...\n");

    while (running) {
        // Read gyroscope data
        if (read_gyro_data(spi_fd, &x, &y, &z) == 0) {
            // Get timestamp
            if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
                perror("clock_gettime");
                running = false;
                continue;
            }
            long timestamp = ts.tv_sec * 1000000000LL + ts.tv_nsec;

            // Store data in circular buffer
            gyro_data_t data = {timestamp, x, y, z};
            buffer_add(&gyro_buffer, data);

            // Check for threshold exceedance
            if (fabs(x) > THRESHOLD || fabs(y) > THRESHOLD || fabs(z) > THRESHOLD) {
                printf("Threshold exceeded! X=%.2f, Y=%.2f, Z=%.2f\n", x, y, z);
                blink_led(LED_PIN, 500);
            }
        } else {
            fprintf(stderr, "Failed to read gyro data. Retrying...\n");
        }

        delay(10); // Sample every 10 ms
    }

    // Print buffer before exiting
    buffer_print(&gyro_buffer);

    // Close SPI device
    close(spi_fd);

    printf("Exiting.\n");
    return 0;
}

