    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("tilt_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    sensor_data_t sensor_data;
    float roll, pitch;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_raw_data(&sensor_data.accel_x, &sensor_data.accel_y, &sensor_data.accel_z, &sensor_data.gyro_x, &sensor_data.gyro_y, &sensor_data.gyro_z) == 0) {
            // Convert to degrees
            convert_to_degrees(sensor_data.accel_x, sensor_data.accel_y, sensor_data.accel_z, &roll, &pitch);

            // Print roll and pitch
            printf("Roll: %.2f, Pitch: %.2f\n", roll, pitch);

            // Log data
            log_data(roll, pitch);

            // Control LED
            control_led(roll, pitch);
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
        }

        // Delay for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup
    gpioWrite(LED_PIN, 0); // Turn off LED
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

