#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SI1145_ADDR 0x60
#define ALS_DATA0 0x22
#define PS1_DATA0 0x24
#define PROXIMITY_THRESHOLD 100
#define LED_GPIO 17
#define LOG_FILE "biometric_log.txt"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(const char *bus, int addr);
int read_register(int fd, uint8_t reg);
int write_register(int fd, uint8_t reg, uint8_t value);
int read_sensor_data(int fd, uint16_t *ambient_light, uint16_t *proximity);
int log_data(FILE *fp, uint16_t ambient_light, uint16_t proximity);
void control_led(int gpio, int state);
void signal_handler(int signal);

// Structure for sensor data (optional)
typedef struct {
    uint16_t ambient_light;
    uint16_t proximity;
} sensor_data_t;

// Function to initialize I2C
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read a register
int read_register(int fd, uint8_t reg) {
    int result = i2c_smbus_read_byte_data(fd, reg);
    if (result < 0) {
        perror("Error reading register");
        return -1;
    }
    return result;
}

// Function to write a register
int write_register(int fd, uint8_t reg, uint8_t value) {
    int result = i2c_smbus_write_byte_data(fd, reg, value);
    if (result < 0) {
        perror("Error writing register");
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(int fd, uint16_t *ambient_light, uint16_t *proximity) {
    int als_low, als_high, ps_low, ps_high;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        als_low = read_register(fd, ALS_DATA0);
        als_high = read_register(fd, ALS_DATA0 + 1);
        ps_low = read_register(fd, PS1_DATA0);
        ps_high = read_register(fd, PS1_DATA0 + 1);

        if (als_low >= 0 && als_high >= 0 && ps_low >= 0 && ps_high >= 0) {
            *ambient_light = (als_high << 8) | als_low;
            *proximity = (ps_high << 8) | ps_low;
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed, retrying (%d/%d)\n", retries + 1, MAX_RETRIES);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "I2C read failed after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to log data to file
int log_data(FILE *fp, uint16_t ambient_light, uint16_t proximity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,AmbientLight:%u,Proximity:%u\n", timestamp, ambient_light, proximity) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    fflush(fp); // Ensure data is written immediately
    return 0;
}

// Function to control the LED
void control_led(int gpio, int state) {
    gpioWrite(gpio, state);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, SI1145_ADDR);
    if (i2c_fd < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t ambient_light, proximity;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(i2c_fd, &ambient_light, &proximity) == 0) {
            if (log_data(log_file, ambient_light, proximity) != 0) {
                fprintf(stderr, "Error logging data\n");
            }

            if (proximity > PROXIMITY_THRESHOLD) {
                control_led(LED_GPIO, 1); // Turn LED on
            } else {
                control_led(LED_GPIO, 0); // Turn LED off
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(100000); // 100ms delay (microseconds)
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);
    control_led(LED_GPIO, 0); // Turn LED off
    gpioTerminate();

    return 0;
}

