            if (log_data(log_file, ambient_light, proximity) != 0) {
                fprintf(stderr, "Error logging data\n");
            }

            if (proximity > PROXIMITY_THRESHOLD) {
                control_led(LED_GPIO, 1); // Turn LED on
            } else {
                control_led(LED_GPIO, 0); // Turn LED off
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(100000); // 100ms delay (microseconds)
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);
    control_led(LED_GPIO, 0); // Turn LED off
    gpioTerminate();

    return 0;
}

