#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define ALERT_PIN 17

// Define constants
#define ALERT_DURATION_MS 2000
#define DEBOUNCE_MS 50

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int open_log_file();
void sensor_callback(int gpio, int level, uint32_t tick, void *user_data);
void trigger_alert();
void log_event();
void cleanup();
void signal_handler(int signal);

// Structure to hold sensor states
typedef struct {
    int sensor1_state;
    int sensor2_state;
    uint32_t last_change_time;
} SensorState;

SensorState sensor_state = {0, 0, 0};

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Open log file
    if (open_log_file() != 0) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        cleanup();
        return 1;
    }

    // Register callbacks
    if (gpioSetAlertFuncEx(SENSOR_1_PIN, sensor_callback, NULL) != 0) {
        fprintf(stderr, "Failed to register callback for sensor 1. Exiting.\n");
        cleanup();
        return 1;
    }
    if (gpioSetAlertFuncEx(SENSOR_2_PIN, sensor_callback, NULL) != 0) {
        fprintf(stderr, "Failed to register callback for sensor 2. Exiting.\n");
        cleanup();
        return 1;
    }

    printf("Seismic monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        gpioDelay(100); // Sleep for 100ms to reduce CPU usage
    }

    // Cleanup and exit
    cleanup();
    printf("Seismic monitoring stopped.\n");
    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN);

    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN);

    gpioSetMode(ALERT_PIN, PI_OUTPUT);
    gpioWrite(ALERT_PIN, 0); // Ensure alert pin is initially LOW

    return 0;
}

// Open log file
int open_log_file() {
    log_file = fopen("seismic_events.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return 1;
    }
    return 0;
}

// Callback function for sensor events
void sensor_callback(int gpio, int level, uint32_t tick, void *user_data) {
    uint32_t current_time = gpioTick();

    // Debounce
    if (current_time - sensor_state.last_change_time < DEBOUNCE_MS * 1000) {
        return;
    }
    sensor_state.last_change_time = current_time;

    if (gpio == SENSOR_1_PIN) {
        sensor_state.sensor1_state = level;
    } else if (gpio == SENSOR_2_PIN) {
        sensor_state.sensor2_state = level;
    }

    // Check if both sensors are HIGH
    if (sensor_state.sensor1_state == 1 && sensor_state.sensor2_state == 1) {
        trigger_alert();
        log_event();
    }
}

// Trigger the alert pin
void trigger_alert() {
    gpioWrite(ALERT_PIN, 1);
    gpioDelay(ALERT_DURATION_MS);
    gpioWrite(ALERT_PIN, 0);
}

// Log the event to the file
void log_event() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s - Seismic event detected!\n", timestamp);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources
void cleanup() {
    program_running = 0; // Stop the main loop

    // Disable callbacks
    gpioSetAlertFuncEx(SENSOR_1_PIN, NULL, NULL);
    gpioSetAlertFuncEx(SENSOR_2_PIN, NULL, NULL);

    // Set alert pin LOW
    gpioWrite(ALERT_PIN, 0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received (%d). Cleaning up...\n", signal);
    cleanup();
    exit(0);
}

