#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define CS_PIN 8
#define LED_PIN 17
#define RATE_THRESHOLD 20.0
#define BUFFER_CAPACITY 100
#define SAMPLE_INTERVAL_MS 10

// ADXRS290 Register Addresses
#define REG_X_RATE 0x80 // Read X-axis rate
#define REG_TEMP 0x82   // Read temperature
#define REG_DIAG 0x84   // Read diagnostic status

// Data Structures
typedef struct {
    struct timespec timestamp;
    float rate;
} gyro_data_t;

typedef struct {
    gyro_data_t buffer[BUFFER_CAPACITY];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

// Global Variables
static volatile sig_atomic_t program_running = 1;
static int spi_fd = -1;
static circular_buffer_t gyro_buffer;

// Function Prototypes
int spi_init(int channel, int speed, int mode);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len);
int read_gyro_data(int fd, float *rate);
void buffer_init(circular_buffer_t *buffer);
bool buffer_is_full(const circular_buffer_t *buffer);
bool buffer_is_empty(const circular_buffer_t *buffer);
int buffer_add(circular_buffer_t *buffer, gyro_data_t data);
int buffer_remove(circular_buffer_t *buffer, gyro_data_t *data);
void signal_handler(int signal);
void cleanup();

// SPI Initialization
int spi_init(int channel, int speed, int mode) {
    int fd;
    char spi_device[20];

    snprintf(spi_device, sizeof(spi_device), "/dev/spidev0.%d", channel);

    fd = open(spi_device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode_u8 = mode;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_u8) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set SPI speed
    uint32_t speed_u32 = speed;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_u32) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI Transfer
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// Read Gyro Data
int read_gyro_data(int fd, float *rate) {
    uint8_t tx_buf[2];
    uint8_t rx_buf[2];
    int16_t raw_rate;

    // Read X-axis rate
    tx_buf[0] = REG_X_RATE | 0x80; // Set MSB for read
    tx_buf[1] = 0x00; // Dummy byte

    if (spi_transfer(fd, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error reading gyro data\n");
        return -1;
    }

    raw_rate = (rx_buf[0] << 8) | rx_buf[1];
    *rate = (float)raw_rate / 14.375; // Convert to degrees/second

    return 0;
}

// Circular Buffer Initialization
void buffer_init(circular_buffer_t *buffer) {
    buffer->head = 0;
    buffer->tail = 0;
    buffer->count = 0;
    pthread_mutex_init(&buffer->mutex, NULL);
}

// Circular Buffer Is Full
bool buffer_is_full(const circular_buffer_t *buffer) {
    return buffer->count == BUFFER_CAPACITY;
}

// Circular Buffer Is Empty
bool buffer_is_empty(const circular_buffer_t *buffer) {
    return buffer->count == 0;
}

// Circular Buffer Add
int buffer_add(circular_buffer_t *buffer, gyro_data_t data) {
    pthread_mutex_lock(&buffer->mutex);
    if (buffer_is_full(buffer)) {
