// SPI Initialization
int spi_init(int channel, int speed, int mode) {
    int fd;
    char spi_device[20];

    snprintf(spi_device, sizeof(spi_device), "/dev/spidev0.%d", channel);

    fd = open(spi_device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode_u8 = mode;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_u8) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set SPI speed
    uint32_t speed_u32 = speed;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_u32) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI Transfer
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
