#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the lamps
#define LAMP1_GPIO 17
#define LAMP2_GPIO 18
#define LAMP3_GPIO 27

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 100

// Define PWM range (0-255)
#define PWM_RANGE 255

// Global variables
static volatile int running = 1;
static int total_duration = 0;

// Function prototypes
int parse_arguments(int argc, char *argv[]);
void initialize_gpio();
void set_lamp_brightness(int gpio, int brightness);
void fade_lamp(int gpio, int duration);
void cleanup();
void signal_handler(int signal);
void log_message(const char *message);

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    log_message("Received signal, shutting down...");
}

// Function to parse command-line arguments
int parse_arguments(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <duration_seconds>\n", argv[0]);
        return 1;
    }

    char *endptr;
    long duration = strtol(argv[1], &endptr, 10);

    if (*endptr != '\0' || duration <= 0 || duration > 3600) {
        fprintf(stderr, "Error: Invalid duration.  Must be an integer between 1 and 3600.\n");
        return 1;
    }

    total_duration = (int)duration;
    return 0;
}

// Function to initialize GPIO pins
void initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        exit(1);
    }

    gpioSetMode(LAMP1_GPIO, PI_OUTPUT);
    gpioSetMode(LAMP2_GPIO, PI_OUTPUT);
    gpioSetMode(LAMP3_GPIO, PI_OUTPUT);

    gpioSetPWMfrequency(LAMP1_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(LAMP2_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(LAMP3_GPIO, PWM_FREQUENCY);

    gpioSetPWMrange(LAMP1_GPIO, PWM_RANGE);
    gpioSetPWMrange(LAMP2_GPIO, PWM_RANGE);
    gpioSetPWMrange(LAMP3_GPIO, PWM_RANGE);

    log_message("GPIO initialized successfully.");
}

// Function to set the brightness of a lamp
void set_lamp_brightness(int gpio, int brightness) {
    gpioPWM(gpio, brightness);
}

// Function to fade a lamp over a specified duration
void fade_lamp(int gpio, int duration) {
    time_t start_time = time(NULL);
    time_t current_time;
    double elapsed_time;
    int brightness;

    while (running && (time(NULL) - start_time) < duration) {
        current_time = time(NULL);
        elapsed_time = difftime(current_time, start_time);

        brightness = (int)((1.0 - (elapsed_time / duration)) * PWM_RANGE);

        if (brightness < 0) {
            brightness = 0;
        }

        set_lamp_brightness(gpio, brightness);

        gpioDelay(10); // Delay for 10 milliseconds
    }

    // Ensure the lamp is fully off at the end of the fade
    set_lamp_brightness(gpio, 0);
}

// Function to log messages with timestamps
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
}

// Function to cleanup GPIO resources
void cleanup() {
    log_message("Cleaning up GPIO resources...");
    set_lamp_brightness(LAMP1_GPIO, 0);
    set_lamp_brightness(LAMP2_GPIO, 0);
    set_lamp_brightness(LAMP3_GPIO, 0);
    gpioTerminate();
    log_message("GPIO resources released.");
}

int main(int argc, char *argv[]) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Parse command-line arguments
    if (parse_arguments(argc, argv) != 0) {
        return 1;
    }

    // Initialize GPIO
    initialize_gpio();

    // Log program start message
    char message[100];
    snprintf(message, sizeof(message), "Sunset simulation started for %d seconds.", total_duration);
    log_message(message);

    // Fade lamps sequentially
    fade_lamp(LAMP1_GPIO, total_duration);
    log_message("Lamp 1 faded.");
    fade_lamp(LAMP2_GPIO, total_duration);
    log_message("Lamp 2 faded.");
    fade_lamp(LAMP3_GPIO, total_duration);
    log_message("Lamp 3 faded.");

    // Log program complete message
    log_message("Sunset simulation complete.");

    // Cleanup and exit
    cleanup();
    return 0;
}

