// Define GPIO pins for the traffic lights
#define RED_PIN   17
#define YELLOW_PIN 22
#define GREEN_PIN  23
#define YELLOW2_PIN 24

// Function prototypes
void set_traffic_light_state(int red, int yellow, int green, int yellow2);
void signal_handler(int signal);

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("\nCaught signal %d, cleaning up and exiting...\n", signal);
        program_running = 0;
        // Turn off all relays
        set_traffic_light_state(1, 1, 1, 1);
        // Release GPIO resources
        gpioTerminate();
        exit(0);
    }
}

// Function to set the state of the traffic lights
void set_traffic_light_state(int red, int yellow, int green, int yellow2) {
    int result;

    result = gpioWrite(RED_PIN, red);
    if (result != 0) {
        fprintf(stderr, "Error writing to RED_PIN: %d\n", result);
    }

    result = gpioWrite(YELLOW_PIN, yellow);
    if (result != 0) {
        fprintf(stderr, "Error writing to YELLOW_PIN: %d\n", result);
    }

    result = gpioWrite(GREEN_PIN, green);
    if (result != 0) {
        fprintf(stderr, "Error writing to GREEN_PIN: %d\n", result);
    }

    result = gpioWrite(YELLOW2_PIN, yellow2);
    if (result != 0) {
        fprintf(stderr, "Error writing to YELLOW2_PIN: %d\n", result);
    }
}

int main() {
    int result;

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    result = gpioSetMode(RED_PIN, PI_OUTPUT);
    if (result != 0) {
        fprintf(stderr, "Error setting RED_PIN as output: %d\n", result);
        gpioTerminate();
        return 1;
    }

    result = gpioSetMode(YELLOW_PIN, PI_OUTPUT);
    if (result != 0) {
        fprintf(stderr, "Error setting YELLOW_PIN as output: %d\n", result);
        gpioTerminate();
        return 1;
    }

    result = gpioSetMode(GREEN_PIN, PI_OUTPUT);
    if (result != 0) {
        fprintf(stderr, "Error setting GREEN_PIN as output: %d\n", result);
        gpioTerminate();
        return 1;
    }

    result = gpioSetMode(YELLOW2_PIN, PI_OUTPUT);
    if (result != 0) {
        fprintf(stderr, "Error setting YELLOW2_PIN as output: %d\n", result);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Traffic light simulation started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Red light
        set_traffic_light_state(0, 1, 1, 1);
        printf("Red light\n");
        sleep(10);

        // Red + Yellow
        set_traffic_light_state(0, 0, 1, 1);
        printf("Red + Yellow\n");
        sleep(2);

        // Green light
        set_traffic_light_state(1, 1, 0, 1);
        printf("Green light\n");
        sleep(10);

        // Yellow light
        set_traffic_light_state(1, 1, 1, 0);
        printf("Yellow light\n");
        sleep(3);
    }

    // Clean up and exit (should not reach here if signal handler works correctly)
    set_traffic_light_state(1, 1, 1, 1);
    gpioTerminate();
    return 0;
}

