#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Constants
#define MPR121_ADDR 0x5A
#define RELAY_PIN 17
#define DEBOUNCE_DELAY_MS 100
#define LOG_FILE "touch_relay.log"

// MPR121 Registers
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_BASELINE_FILTER_CONFIG 0x2B
#define MPR121_TOUCHTH_0 0x41
#define MPR121_RELEASETH_0 0x42

// Global variables
static int i2c_fd;
static FILE *log_file;
static volatile sig_atomic_t program_running = 1;
static bool relay_state = false;

// Function prototypes
int mpr121_init(int fd);
int read_touch_status(int fd);
void debounce_touch(int electrode, int status);
void toggle_relay(int pin);
void log_message(const char *message);
void signal_handler(int signal);

// Function to initialize the MPR121
int mpr121_init(int fd) {
    // Stop mode
    if (wiringPiI2CWriteReg8(fd, MPR121_ELECTRODE_CONFIG, 0x00) < 0) {
        log_message("Error: Failed to set MPR121 to stop mode.");
        return -1;
    }
    delay(1); // Small delay after stop mode

    // Configure baseline filter
    if (wiringPiI2CWriteReg8(fd, MPR121_BASELINE_FILTER_CONFIG, 0x10) < 0) {
        log_message("Error: Failed to configure baseline filter.");
        return -1;
    }

    // Set touch and release thresholds for electrode 0
    if (wiringPiI2CWriteReg8(fd, MPR121_TOUCHTH_0, 40) < 0) {
        log_message("Error: Failed to set touch threshold for electrode 0.");
        return -1;
    }
    if (wiringPiI2CWriteReg8(fd, MPR121_RELEASETH_0, 20) < 0) {
        log_message("Error: Failed to set release threshold for electrode 0.");
        return -1;
    }

    // Enable electrode 0
    if (wiringPiI2CWriteReg8(fd, MPR121_ELECTRODE_CONFIG, 0x01) < 0) {
        log_message("Error: Failed to enable electrode 0.");
        return -1;
    }

    return 0;
}

// Function to read the touch status from the MPR121
int read_touch_status(int fd) {
    int touch_status_l = wiringPiI2CReadReg8(fd, MPR121_TOUCHSTATUS_L);
    int touch_status_h = wiringPiI2CReadReg8(fd, MPR121_TOUCHSTATUS_H);

    if (touch_status_l < 0 || touch_status_h < 0) {
        log_message("Error: Failed to read touch status.");
        return -1;
    }

    return (touch_status_h << 8) | touch_status_l;
}

// Function to debounce touch events
void debounce_touch(int electrode, int status) {
    static unsigned long last_touch_time[12] = {0}; // Array to store last touch time for each electrode
    unsigned long current_time = millis();

    if (status == 1) {
        if (current_time - last_touch_time[electrode] > DEBOUNCE_DELAY_MS) {
            toggle_relay(RELAY_PIN);
            last_touch_time[electrode] = current_time;
        }
    }
}

// Function to toggle the relay state
void toggle_relay(int pin) {
    relay_state = !relay_state;
    digitalWrite(pin, relay_state ? HIGH : LOW);
    char message[100];
    snprintf(message, sizeof(message), "Relay toggled to %s", relay_state ? "HIGH" : "LOW");
    log_message(message);
}

// Function to log messages to the log file
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
    fflush(log_file); // Ensure the message is written to the file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    log_message("Signal received, shutting down...");
}

int main() {
    // Initialize WiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error: Failed to initialize WiringPi. %s\n", strerror(errno));
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file. %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    i2c_fd = wiringPiI2CSetup(MPR121_ADDR);
    if (i2c_fd == -1) {
        log_message("Error: Failed to initialize I2C.");
        fclose(log_file);
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init(i2c_fd) == -1) {
        log_message("Error: Failed to initialize MPR121.");
        fclose(log_file);
        return 1;
    }

    // Configure relay pin as output
    pinMode(RELAY_PIN, OUTPUT);
    digitalWrite(RELAY_PIN, LOW); // Initialize relay to LOW
    log_message("Relay initialized to LOW.");

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_message("Program started.");

    // Main loop
    while (program_running) {
        int touch_status = read_touch_status(i2c_fd);
        if (touch_status != -1) {
            debounce_touch(0, (touch_status >> 0) & 1); // Check electrode 0
        }
        delay(10); // Delay for 10ms
    }

    // Cleanup
    log_message("Cleaning up...");
    digitalWrite(RELAY_PIN, LOW); // Ensure relay is off
    fclose(log_file);
    return 0;
}

