#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define FLAME_SENSOR_1 17
#define FLAME_SENSOR_2 22
#define FLAME_SENSOR_3 27
#define BUZZER 18
#define LED 23

// Define constants
#define DEBOUNCE_READS 3
#define DEBOUNCE_DELAY_MS 50
#define LOG_FILE "flame_log.txt"

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_flame_sensor(int gpio_pin);
int debounce_flame_sensor(int gpio_pin);
void log_flame_detection(void);
void activate_buzzer(int gpio_pin);
void deactivate_buzzer(int gpio_pin);
void activate_led(int gpio_pin);
void deactivate_led(int gpio_pin);
void signal_handler(int signal);

// Function to read a flame sensor
int read_flame_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate error
    }
    return value;
}

// Function to debounce a flame sensor
int debounce_flame_sensor(int gpio_pin) {
    int low_count = 0;
    for (int i = 0; i < DEBOUNCE_READS; i++) {
        int value = read_flame_sensor(gpio_pin);
        if (value < 0) return -1; // Propagate error
        if (value == 0) {
            low_count++;
        }
        gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Delay in microseconds
    }
    return (low_count == DEBOUNCE_READS) ? 0 : 1; // Return 0 if all reads are LOW, 1 otherwise
}

// Function to log flame detection
void log_flame_detection(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Flame Detected\n", timestamp);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to activate the buzzer
void activate_buzzer(int gpio_pin) {
    int result = gpioWrite(gpio_pin, 1); // HIGH to activate
    if (result != 0) {
        fprintf(stderr, "Error activating buzzer on GPIO %d: %d\n", gpio_pin, result);
    }
}

// Function to deactivate the buzzer
void deactivate_buzzer(int gpio_pin) {
    int result = gpioWrite(gpio_pin, 0); // LOW to deactivate
    if (result != 0) {
        fprintf(stderr, "Error deactivating buzzer on GPIO %d: %d\n", gpio_pin, result);
    }
}

// Function to activate the LED
void activate_led(int gpio_pin) {
    int result = gpioWrite(gpio_pin, 1); // HIGH to activate
    if (result != 0) {
        fprintf(stderr, "Error activating LED on GPIO %d: %d\n", gpio_pin, result);
    }
}

// Function to deactivate the LED
void deactivate_led(int gpio_pin) {
    int result = gpioWrite(gpio_pin, 0); // LOW to deactivate
    if (result != 0) {
        fprintf(stderr, "Error deactivating LED on GPIO %d: %d\n", gpio_pin, result);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLAME_SENSOR_1, PI_INPUT);
    gpioSetMode(FLAME_SENSOR_2, PI_INPUT);
    gpioSetMode(FLAME_SENSOR_3, PI_INPUT);
    gpioSetMode(BUZZER, PI_OUTPUT);
    gpioSetMode(LED, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Flame detection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int flame_detected = debounce_flame_sensor(FLAME_SENSOR_1) == 0 &&
                            debounce_flame_sensor(FLAME_SENSOR_2) == 0 &&
                            debounce_flame_sensor(FLAME_SENSOR_3) == 0;

        if (flame_detected) {
            log_flame_detection();
            activate_buzzer(BUZZER);
            activate_led(LED);

            // Wait for flame to clear
            while (program_running && debounce_flame_sensor(FLAME_SENSOR_1) == 0 && debounce_flame_sensor(FLAME_SENSOR_2) == 0 && debounce_flame_sensor(FLAME_SENSOR_3) == 0) {
                gpioDelay(100000); // Check every 0.1 seconds
            }

            deactivate_buzzer(BUZZER);
            deactivate_led(LED);
        }

        gpioDelay(10000); // Check every 0.1 seconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    deactivate_buzzer(BUZZER);
    deactivate_led(LED);
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

