#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Motor A GPIO pins
#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18
#define MOTOR_A_ENABLE 24

// Motor B GPIO pins
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23
#define MOTOR_B_ENABLE 25

// PID constants
#define KP 1.0
#define KI 0.01
#define KD 0.1

// Obstacle avoidance distance threshold (cm)
#define OBSTACLE_THRESHOLD 20.0

// PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Structure to hold PID state
typedef struct {
    float integral;
    float previous_error;
} PIDState;

PIDState pid_state = {0.0, 0.0};

// Function prototypes
float generate_tilt_error();
float generate_distance();
float calculate_pid(float setpoint, float actual_value, PIDState *pid_state);
void set_motor_speed(int motor, int speed);
void obstacle_avoidance();
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed);
void signal_handler(int signal);
int initialize_gpio();
void cleanup_gpio();

// Function to generate a random tilt error between -10.0 and 10.0 degrees
float generate_tilt_error() {
    return (float)(rand() % 2001 - 1000) / 100.0;
}

// Function to generate a random distance between 2.0 and 400.0 cm
float generate_distance() {
    return (float)(rand() % 39801 + 200) / 100.0;
}

// Function to calculate the PID output
float calculate_pid(float setpoint, float actual_value, PIDState *pid_state) {
    float error = setpoint - actual_value;
    pid_state->integral += error;
    float derivative = error - pid_state->previous_error;
    float output = KP * error + KI * pid_state->integral + KD * derivative;
    pid_state->previous_error = error;
    return output;
}

// Function to set the motor speed using PWM
void set_motor_speed(int motor, int speed) {
    if (speed < -255) speed = -255;
    if (speed > 255) speed = 255;

    int forward_pin, backward_pin, enable_pin;

    if (motor == 1) {
        forward_pin = MOTOR_A_FORWARD;
        backward_pin = MOTOR_A_BACKWARD;
        enable_pin = MOTOR_A_ENABLE;
    } else if (motor == 2) {
        forward_pin = MOTOR_B_FORWARD;
        backward_pin = MOTOR_B_BACKWARD;
        enable_pin = MOTOR_B_ENABLE;
    } else {
        fprintf(stderr, "Error: Invalid motor number: %d\n", motor);
        return;
    }

    if (speed > 0) {
        gpioWrite(forward_pin, 1);
        gpioWrite(backward_pin, 0);
        gpioPWM(enable_pin, speed);
    } else if (speed < 0) {
        gpioWrite(forward_pin, 0);
        gpioWrite(backward_pin, 1);
        gpioPWM(enable_pin, -speed);
    } else {
        gpioWrite(forward_pin, 0);
        gpioWrite(backward_pin, 0);
        gpioPWM(enable_pin, 0);
    }
}

// Function to implement obstacle avoidance
void obstacle_avoidance() {
    set_motor_speed(1, -128); // Reverse Motor A
    set_motor_speed(2, -128); // Reverse Motor B
    gpioDelay(500);           // Wait for 0.5 seconds
    set_motor_speed(1, 0);    // Stop Motor A
    set_motor_speed(2, 0);    // Stop Motor B
}

// Function to log data to a file
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping motors and exiting...\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_ENABLE, PI_OUTPUT);

    // Enable PWM on enable pins
    gpioSetPWMfrequency(MOTOR_A_ENABLE, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_B_ENABLE, PWM_FREQUENCY);
    gpioSetPWMrange(MOTOR_A_ENABLE, 255);
    gpioSetPWMrange(MOTOR_B_ENABLE, 255);

    return 0;
}

// Function to cleanup GPIO pins
void cleanup_gpio() {
    // Stop motors
    set_motor_speed(1, 0);
    set_motor_speed(2, 0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("balance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup_gpio();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Generate simulated sensor data
        float tilt_error = generate_tilt_error();
        float distance = generate_distance();

        // Calculate PID output
        float pid_output = calculate_pid(0.0, tilt_error, &pid_state);

        // Set motor speeds based on PID output
        int motor_a_speed = (int)pid_output;
        int motor_b_speed = (int)pid_output;

        // Obstacle avoidance
        if (distance < OBSTACLE_THRESHOLD) {
            obstacle_avoidance();
            motor_a_speed = 0;
            motor_b_speed = 0;
        }

        // Clamp motor speeds to -255 to 255
        if (motor_a_speed > 255) motor_a_speed = 255;
        if (motor_a_speed < -255) motor_a_speed = -255;
        if (motor_b_speed > 255) motor_b_speed = 255;
        if (motor_b_speed < -255) motor_b_speed = -255;

        // Set motor speeds
        set_motor_speed(1, motor_a_speed);
        set_motor_speed(2, motor_b_speed);

        // Log data
        log_data(tilt_error, distance, motor_a_speed, motor_b_speed);

        // Delay for 50 milliseconds
        gpioDelay(50);
    }

    // Cleanup and exit
    cleanup_gpio();
    return 0;
}

