#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

// Configuration
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27
#define SAMPLE_RATE 8000
#define NUM_CHANNELS 1
#define BITS_PER_SAMPLE 16
#define PERIOD_SIZE 1024
#define BUFFER_SIZE (PERIOD_SIZE * NUM_CHANNELS * (BITS_PER_SAMPLE / 8))
#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 255
#define SINE_FREQUENCY 2.0 // Hz
#define SINE_AMPLITUDE 1000.0
#define DEFAULT_SENSITIVITY 1.0
#define ALSA_AVAILABLE // Define this to enable ALSA

// Global variables
static volatile int running = 1;
static float sensitivity = DEFAULT_SENSITIVITY;

// Structure for RGB color
typedef struct {
    int red;
    int green;
    int blue;
} RGBColor;

// Function prototypes
void signal_handler(int signal);
RGBColor map_amplitude_to_color(float amplitude);
float calculate_rms(const short *buffer, int buffer_size);
void set_led_color(RGBColor color);
void simulate_audio_input(short *buffer, int buffer_size);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to map amplitude to RGB color
RGBColor map_amplitude_to_color(float amplitude) {
    RGBColor color;

    // Normalize amplitude
    amplitude = fabs(amplitude) / SINE_AMPLITUDE; // Scale to 0-1 range
    amplitude = amplitude * sensitivity; // Apply sensitivity

    // Map amplitude to color (example: red to green)
    color.red = (int)(amplitude * PWM_RANGE);
    color.green = (int)((1.0 - amplitude) * PWM_RANGE);
    color.blue = 0;

    // Clamp values to PWM range
    color.red = (color.red > PWM_RANGE) ? PWM_RANGE : color.red;
    color.green = (color.green > PWM_RANGE) ? PWM_RANGE : color.green;
    color.blue = (color.blue > PWM_RANGE) ? PWM_RANGE : color.blue;

    return color;
}

// Function to calculate RMS amplitude
float calculate_rms(const short *buffer, int buffer_size) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < buffer_size; i++) {
        sum_of_squares += (double)buffer[i] * buffer[i];
    }
    return sqrt(sum_of_squares / buffer_size);
}

// Function to set LED color using PWM
void set_led_color(RGBColor color) {
    gpioPWM(RED_PIN, color.red);
    gpioPWM(GREEN_PIN, color.green);
    gpioPWM(BLUE_PIN, color.blue);
}

// Function to simulate audio input (sine wave)
void simulate_audio_input(short *buffer, int buffer_size) {
    double time_step = 1.0 / SAMPLE_RATE;
    double time = 0.0;
    for (int i = 0; i < buffer_size; i++) {
        buffer[i] = (short)(SINE_AMPLITUDE * sin(2 * M_PI * SINE_FREQUENCY * time));
        time += time_step;
    }
}

int main(int argc, char *argv[]) {
    // Parse command-line argument for sensitivity
    if (argc > 1) {
        sensitivity = atof(argv[1]);
        if (sensitivity <= 0.0) {
            fprintf(stderr, "Error: Sensitivity must be a positive number.\n");
            return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(RED_PIN, PWM_RANGE);
    gpioSetPWMrange(GREEN_PIN, PWM_RANGE);
    gpioSetPWMrange(BLUE_PIN, PWM_RANGE);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Mood light started. Sensitivity: %.2f\n", sensitivity);

    // Main loop
#ifdef ALSA_AVAILABLE
    // ALSA implementation
    #include <alsa/asoundlib.h>
    snd_pcm_t *pcm_handle;
    snd_pcm_hw_params_t *hw_params;
    short *buffer;

    // Open PCM device for capture
    int err = snd_pcm_open(&pcm_handle, "default", SND_PCM_STREAM_CAPTURE, 0);
    if (err < 0) {
        fprintf(stderr, "Error: Could not open PCM device: %s\n", snd_strerror(err));
        gpioTerminate();
        return 1;
    }

    // Allocate buffer
    buffer = (short *)malloc(BUFFER_SIZE);
    if (buffer == NULL) {
        fprintf(stderr, "Error: Could not allocate buffer\n");
        snd_pcm_close(pcm_handle);
        gpioTerminate();
        return 1;
    }

    // Configure hardware parameters
    snd_pcm_hw_params_alloca(&hw_params);
    err = snd_pcm_hw_params_any(pcm_handle, hw_params);
    if (err < 0) {
        fprintf(stderr, "Error: Could not configure hardware parameters: %s\n", snd_strerror(err));
        free(buffer);
        snd_pcm_close(pcm_handle);
        gpioTerminate();
        return 1;
    }

    err = snd_pcm_hw_params_set_access(pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED);
    if (err < 0) {
        fprintf(stderr, "Error: Could not set access type: %s\n", snd_strerror(err));
        free(buffer);
        snd_pcm_close(pcm_handle);
        gpioTerminate();
        return 1;
    }

    err = snd_pcm_hw_params_set_format(pcm_handle, hw_params, SND_PCM_FORMAT_S16_LE);
    if (err < 0) {
        fprintf(stderr, "Error: Could not set format: %s\n", snd_strerror(err));
        free(buffer);
        snd_pcm_close(pcm_handle);
        gpioTerminate();
        return 1;
    }

    err = snd_pcm_hw_params_set_channels(pcm_handle, hw_params, NUM_CHANNELS);
    if (err < 0) {
        fprintf(stderr, "Error: Could not set channels: %s\n", snd_strerror(err));
        free(buffer);
        snd_pcm_close(pcm_handle);
        gpioTerminate();
        return 1;
    }

    unsigned int rate = SAMPLE_RATE;
    err = snd_pcm_hw_params_set_rate_near(pcm_handle, hw_params, &rate, 0);
    if (err < 0) {
        fprintf(stderr, "Error: Could not set rate: %s\n", snd_strerror(err));
        free(buffer);
        snd_pcm_close(pcm_handle);
        gpioTerminate();
        return 1;
    }

    err = snd_pcm_hw_params_set_period_size_near(pcm_handle, hw_params, &PERIOD_SIZE, 0);
    if (err < 0) {
        fprintf(stderr, "Error: Could not set period size: %s\n", snd_strerror(err));
        free(buffer);
        snd_pcm_close(pcm_handle);
        gpioTerminate();
        return 1;
    }

    err = snd_pcm_hw_params(pcm_handle, hw_params);
    if (err < 0) {
        fprintf(stderr, "Error: Could not set hardware parameters: %s\n", snd_strerror(err));
        free(buffer);
        snd_pcm_close(pcm_handle);
        gpioTerminate();
        return 1;
    }

    // Prepare PCM device
    err = snd_pcm_prepare(pcm_handle);
    if (err < 0) {
        fprintf(stderr, "Error: Could not prepare PCM device: %s\n", snd_strerror(err));
        free(buffer);
        snd_pcm_close(pcm_handle);
        gpioTerminate();
        return 1;
    }

    while (running) {
        // Read audio data
        err = snd_pcm_readi(pcm_handle, buffer, PERIOD_SIZE);
        if (err == -EPIPE) {
            fprintf(stderr, "Error: Overrun occurred\n");
            snd_pcm_prepare(pcm_handle);
        } else if (err == -ESTRPIPE) {
            fprintf(stderr, "Error: Stream is suspended\n");
            snd_pcm_resume(pcm_handle);
        } else if (err < 0) {
            fprintf(stderr, "Error: Could not read PCM data: %s\n", snd_strerror(err));
            break;
        } else if (err != PERIOD_SIZE) {
            fprintf(stderr, "Error: Short read, read %d frames\n", err);
        }

        // Calculate RMS amplitude
        float rms_amplitude = calculate_rms(buffer, BUFFER_SIZE);

        // Map amplitude to color
        RGBColor color = map_amplitude_to_color(rms_amplitude);

        // Set LED color
        set_led_color(color);

        // Delay for 10ms
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Clean up
    free(buffer);
    snd_pcm_close(pcm_handle);
#else
    // Simulate ALSA implementation
    short *buffer;
    buffer = (short *)malloc(BUFFER_SIZE);
    if (buffer == NULL) {
        fprintf(stderr, "Error: Could not allocate buffer\n");
        gpioTerminate();
        return 1;
    }

    while (running) {
        // Simulate audio input
        simulate_audio_input(buffer, BUFFER_SIZE);

        // Calculate RMS amplitude
        float rms_amplitude = calculate_rms(buffer, BUFFER_SIZE);

        // Map amplitude to color
        RGBColor color = map_amplitude_to_color(rms_amplitude);

        // Set LED color
        set_led_color(color);

        // Delay for 10ms
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    free(buffer);
#endif

    // Clean up and exit
    gpioTerminate();
    printf("Mood light stopped.\n");
    return 0;
}

