#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// TCS34725 I2C address
#define TCS34725_ADDRESS 0x29

// TCS34725 register addresses
#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_CDATA 0x94
#define TCS34725_RDATA 0x96
#define TCS34725_GDATA 0x98
#define TCS34725_BDATA 0x9A

// Global variables
int i2c_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t clear;
    uint16_t red;
    uint16_t green;
    uint16_t blue;
} sensor_data_t;

// Function prototypes
int initialize_sensor();
sensor_data_t read_sensor_data();
void log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// Function to initialize the TCS34725 sensor
int initialize_sensor() {
    // Enable the sensor (power on and enable RGBC)
    if (i2cWriteByteData(i2c_handle, TCS34725_ENABLE, 0x03) < 0) {
        fprintf(stderr, "Error writing to TCS34725_ENABLE register: %d\n", i2c_handle);
        return -1;
    }

    // Set integration time (154ms)
    if (i2cWriteByteData(i2c_handle, TCS34725_ATIME, 0xD5) < 0) {
        fprintf(stderr, "Error writing to TCS34725_ATIME register: %d\n", i2c_handle);
        return -1;
    }

    return 0;
}

// Function to read color data from the TCS34725 sensor
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    uint8_t buffer[8];

    // Read all color data registers in one go
    if (i2cReadI2CBlockData(i2c_handle, TCS34725_CDATA, (char *)buffer, 8) < 0) {
        fprintf(stderr, "Error reading color data: %d\n", i2c_handle);
        data.clear = 0;
        data.red = 0;
        data.green = 0;
        data.blue = 0;
        return data;
    }

