#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 27
#define RELAY3_PIN 22
#define RELAY4_PIN 23

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 100

// Define sunrise and sunset durations (seconds)
#define SUNRISE_DURATION 3600
#define SUNSET_DURATION 3600

// Define daytime and nighttime durations (seconds)
#define DAYTIME_DURATION 21600
#define NIGHTTIME_DURATION 86400

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to set the duty cycle of a relay
int set_relay_duty_cycle(int gpio_pin, int duty_cycle) {
    if (gpioPWM(gpio_pin, duty_cycle) != 0) {
        fprintf(stderr, "Error setting duty cycle for GPIO %d\n", gpio_pin);
        return -1;
    }
    return 0;
}

// Function to turn off all relays
void turn_off_all_relays() {
    set_relay_duty_cycle(RELAY1_PIN, 0);
    set_relay_duty_cycle(RELAY2_PIN, 0);
    set_relay_duty_cycle(RELAY3_PIN, 0);
    set_relay_duty_cycle(RELAY4_PIN, 0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(RELAY1_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY2_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY3_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY4_PIN, PWM_FREQUENCY);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Sunrise/Sunset Lighting Simulation started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Sunrise phase
        printf("Sunrise phase started...\n");
        for (int i = 0; i <= 255 && program_running; i++) {
            if (set_relay_duty_cycle(RELAY1_PIN, i) != 0 ||
                set_relay_duty_cycle(RELAY2_PIN, i) != 0 ||
                set_relay_duty_cycle(RELAY3_PIN, i) != 0 ||
                set_relay_duty_cycle(RELAY4_PIN, i) != 0) {
                program_running = 0;
                break;
            }
            gpioDelay(SUNRISE_DURATION * 1000 / 255); // Delay for sunrise duration
        }
        if (!program_running) break;

        // Daytime phase
        printf("Daytime phase started...\n");
        for (int i = 0; i <= 255 && program_running; i++) {
            if (set_relay_duty_cycle(RELAY1_PIN, 255) != 0 ||
                set_relay_duty_cycle(RELAY2_PIN, 255) != 0 ||
                set_relay_duty_cycle(RELAY3_PIN, 255) != 0 ||
                set_relay_duty_cycle(RELAY4_PIN, 255) != 0) {
                program_running = 0;
                break;
            }
            gpioDelay(DAYTIME_DURATION * 1000 / 255); // Delay for daytime duration
        }
        if (!program_running) break;

        // Sunset phase
        printf("Sunset phase started...\n");
        for (int i = 255; i >= 0 && program_running; i--) {
            if (set_relay_duty_cycle(RELAY1_PIN, i) != 0 ||
                set_relay_duty_cycle(RELAY2_PIN, i) != 0 ||
                set_relay_duty_cycle(RELAY3_PIN, i) != 0 ||
                set_relay_duty_cycle(RELAY4_PIN, i) != 0) {
                program_running = 0;
                break;
            }
            gpioDelay(SUNSET_DURATION * 1000 / 255); // Delay for sunset duration
        }
        if (!program_running) break;

        // Nighttime phase
        printf("Nighttime phase started...\n");
        for (int i = 0; i <= 255 && program_running; i++) {
            if (set_relay_duty_cycle(RELAY1_PIN, 0) != 0 ||
                set_relay_duty_cycle(RELAY2_PIN, 0) != 0 ||
                set_relay_duty_cycle(RELAY3_PIN, 0) != 0 ||
                set_relay_duty_cycle(RELAY4_PIN, 0) != 0) {
                program_running = 0;
                break;
            }
            gpioDelay(NIGHTTIME_DURATION * 1000 / 255); // Delay for nighttime duration
        }
        if (!program_running) break;
    }

    // Turn off all relays before exiting
    turn_off_all_relays();

    // Terminate pigpio library
    gpioTerminate();

    printf("Sunrise/Sunset Lighting Simulation stopped.\n");

    return 0;
}

