#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SENSOR_PIN 17
#define DEBOUNCE_DELAY_MS 200
#define VIDEO_DURATION_SEC 5
#define VIDEO_DIR "/home/pi/videos/"
#define LOG_FILE "/home/pi/logs/motion_log.txt"

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to generate a filename for the video capture
char* generate_filename() {
    time_t rawtime;
    struct tm *timeinfo;
    char *filename = (char*)malloc(100 * sizeof(char)); // Allocate memory for the filename string

    if (filename == NULL) {
        perror("Failed to allocate memory for filename");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime); // Use localtime for local time

    strftime(filename, 100, "%Y%m%d_%H%M%S.h264", timeinfo);
    return filename;
}

// Function to capture a video using raspivid
int capture_video(const char *filename) {
    char command[200];
    snprintf(command, sizeof(command), "raspivid -o %s%s -t %d000", VIDEO_DIR, filename, VIDEO_DURATION_SEC);
    int status = system(command);
    if (status == -1) {
        perror("Failed to execute raspivid command");
        return -1;
    }
    return 0;
}

// Function to log a motion event to the log file
int log_motion(const char *timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s\n", timestamp);
    fflush(log_file); // Ensure the log is written immediately
    return 0;
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin 17 as input
    gpioSetMode(SENSOR_PIN, PI_INPUT);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read the sensor value
        int sensor_value = gpioRead(SENSOR_PIN);

        // Check for motion (LOW signal)
        if (sensor_value == 0) {
            // Debounce the input
            gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Delay in microseconds

            // Re-read the sensor value after the debounce delay
            int debounced_sensor_value = gpioRead(SENSOR_PIN);

            if (debounced_sensor_value == 0) {
                // Motion detected
                printf("Motion detected!\n");

                // Get the current timestamp
                char *timestamp = get_iso8601_timestamp();
                if (timestamp == NULL) {
                    fprintf(stderr, "Failed to get timestamp, skipping motion event.\n");
                    continue; // Skip to the next iteration
                }

                // Generate a filename for the video capture
                char *filename = generate_filename();
                if (filename == NULL) {
                    fprintf(stderr, "Failed to generate filename, skipping motion event.\n");
                    free(timestamp);
                    continue; // Skip to the next iteration
                }

                // Log the motion event
                if (log_motion(timestamp) != 0) {
                    fprintf(stderr, "Failed to log motion event.\n");
                }

                // Capture the video
                if (capture_video(filename) != 0) {
                    fprintf(stderr, "Failed to capture video.\n");
                }

                // Free the allocated memory
                free(timestamp);
                free(filename);
            }
        }

        // Small delay to prevent busy-waiting
        gpioDelay(10000); // 10ms delay
    }

    // Clean up resources
    printf("Cleaning up resources...\n");

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

