            // Debounce the input
            gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Delay in microseconds

            // Re-read the sensor value after the debounce delay
            int debounced_sensor_value = gpioRead(SENSOR_PIN);

            if (debounced_sensor_value == 0) {
                // Motion detected
                printf("Motion detected!\n");

                // Get the current timestamp
                char *timestamp = get_iso8601_timestamp();
                if (timestamp == NULL) {
                    fprintf(stderr, "Failed to get timestamp, skipping motion event.\n");
                    continue; // Skip to the next iteration
                }

                // Generate a filename for the video capture
                char *filename = generate_filename();
                if (filename == NULL) {
                    fprintf(stderr, "Failed to generate filename, skipping motion event.\n");
                    free(timestamp);
                    continue; // Skip to the next iteration
                }

                // Log the motion event
                if (log_motion(timestamp) != 0) {
                    fprintf(stderr, "Failed to log motion event.\n");
                }

                // Capture the video
                if (capture_video(filename) != 0) {
                    fprintf(stderr, "Failed to capture video.\n");
                }

                // Free the allocated memory
                free(timestamp);
                free(filename);
            }
        }

        // Small delay to prevent busy-waiting
        gpioDelay(10000); // 10ms delay
    }

    // Clean up resources
    printf("Cleaning up resources...\n");

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

