#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define GYRO_CONFIG 0x1B
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47

// Sensitivity scale factor for +/- 250 deg/s range
#define GYRO_SCALE 131.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Function prototypes
int initialize_mpu6050();
gyro_data_t read_gyro_data();
void log_data(gyro_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the MPU-6050
int initialize_mpu6050() {
    int retries = 3;
    int status;

    while (retries > 0) {
        // Wake up the MPU-6050 (clear sleep mode bit)
        status = i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0);
        if (status != 0) {
            fprintf(stderr, "Error: Could not wake up MPU-6050 (PWR_MGMT_1), retrying... (%d retries left)\n", retries);
            gpioDelay(100); // Wait before retrying
            retries--;
            continue;
        }

        // Configure gyroscope range (+/- 250 deg/s)
        status = i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0);
        if (status != 0) {
            fprintf(stderr, "Error: Could not configure gyroscope range, retrying... (%d retries left)\n", retries);
            gpioDelay(100); // Wait before retrying
            retries--;
            continue;
        }

        printf("MPU-6050 initialized successfully.\n");
        return 0; // Success
    }

    fprintf(stderr, "Error: Failed to initialize MPU-6050 after multiple retries.\n");
    return -1; // Failure
}

// Function to read gyroscope data from the MPU-6050
gyro_data_t read_gyro_data() {
    gyro_data_t data;
    char buffer[6];
    int16_t raw_x, raw_y, raw_z;
    int status;

    status = i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buffer, 6);
    if (status != 6) {
        fprintf(stderr, "Error: Could not read gyroscope data. Status: %d\n", status);
        data.x = 0.0;
        data.y = 0.0;
        data.z = 0.0;
        return data; // Return default values on error
    }

    raw_x = (buffer[0] << 8) | buffer[1];
    raw_y = (buffer[2] << 8) | buffer[3];
    raw_z = (buffer[4] << 8) | buffer[5];

    // Convert raw data to degrees per second
    data.x = (float)raw_x / GYRO_SCALE;
    data.y = (float)raw_y / GYRO_SCALE;
    data.z = (float)raw_z / GYRO_SCALE;

    return data;
}

// Function to log data to a CSV file
void log_data(gyro_data_t data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

    fprintf(log_file, "%ld,%.3f,%.3f,%.3f\n", timestamp_ms, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus. Error code: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (initialize_mpu6050() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,X_degps,Y_degps,Z_degps\n");
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        gyro_data_t gyro_data = read_gyro_data();
        log_data(gyro_data);
        gpioDelay(10); // 10 ms delay (100 Hz sampling rate)
    }

    // Close log file
    fclose(log_file);

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

