#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define the moisture threshold
#define MOISTURE_THRESHOLD 30

// Define the log file name
#define LOG_FILE "irrigation_log.txt"

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
int read_moisture_sensor();
void control_relay(int relay_pin, int state);
void log_data(int moisture_level, int relay1_state, int relay2_state, int relay3_state, int relay4_state);
void signal_handler(int signal);
void cleanup();

// Structure to hold relay states
typedef struct {
    int relay1;
    int relay2;
    int relay3;
    int relay4;
} RelayStates;

// Function to initialize the pigpio library and set GPIO pins as outputs
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    return 0; // Indicate success
}

// Function to read the moisture sensor and return a random value between 0 and 100
int read_moisture_sensor() {
    // Seed the random number generator with the current time
    srand(time(NULL));
    return rand() % 101; // Generate a random number between 0 and 100
}

// Function to control the relay by setting the GPIO pin to the specified state
void control_relay(int relay_pin, int state) {
    gpioWrite(relay_pin, state);
}

// Function to log the data to the file
void log_data(int moisture_level, int relay1_state, int relay2_state, int relay3_state, int relay4_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Moisture: %d, Relay1: %s, Relay2: %s, Relay3: %s, Relay4: %s\n",
            timestamp, moisture_level,
            relay1_state ? "ON" : "OFF",
            relay2_state ? "ON" : "OFF",
            relay3_state ? "ON" : "OFF",
            relay4_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to the file immediately
}

// Signal handler function to catch SIGINT and other errors
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0; // Stop the main loop
}

// Function to cleanup resources before exiting
void cleanup() {
    // Deactivate all relays
    control_relay(RELAY1_PIN, 1);
    control_relay(RELAY2_PIN, 1);
    control_relay(RELAY3_PIN, 1);
    control_relay(RELAY4_PIN, 1);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate the pigpio library
    gpioTerminate();
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1; // Exit if file opening fails
    }

    printf("Smart Greenhouse Irrigation System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read the moisture sensor
        int moisture_level = read_moisture_sensor();

        // Control the relays based on the moisture level
        control_relay(RELAY1_PIN, moisture_level < MOISTURE_THRESHOLD ? 0 : 1);
        control_relay(RELAY2_PIN, moisture_level < MOISTURE_THRESHOLD ? 0 : 1);
        control_relay(RELAY3_PIN, moisture_level < MOISTURE_THRESHOLD ? 0 : 1);
        control_relay(RELAY4_PIN, moisture_level < MOISTURE_THRESHOLD ? 0 : 1);

        // Log the data
        log_data(moisture_level,
                 gpioRead(RELAY1_PIN) == 0,
                 gpioRead(RELAY2_PIN) == 0,
                 gpioRead(RELAY3_PIN) == 0,
                 gpioRead(RELAY4_PIN) == 0);

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Cleanup and exit
    cleanup();
    printf("Smart Greenhouse Irrigation System stopped.\n");
    return 0;
}

