#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIG_PIN 4
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MAX_DISTANCE 400.0    // cm
#define TIMEOUT_US 100000      // 100ms
#define TRIG_PULSE_US 10       // 10us trigger pulse

// Global variables
static volatile uint32_t rising_edge_tick = 0;
static volatile uint32_t falling_edge_tick = 0;
static volatile int echo_received = 0;
static volatile int timeout_occurred = 0;
static FILE *log_file = NULL;
static pthread_mutex_t mutex;
static volatile int running = 1;

// Function prototypes
void trigger_sensor();
void echo_callback(int gpio, int level, uint32_t tick);
double calculate_distance(uint32_t pulse_width);
void log_distance(double distance);
void timeout_handler();
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure to hold sensor data
typedef struct {
    uint32_t rising_edge;
    uint32_t falling_edge;
    int echo_received;
    int timeout_occurred;
} sensor_data_t;

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(TRIG_PULSE_US);
    gpioWrite(TRIG_PIN, 0);
}

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
    pthread_mutex_lock(&mutex);
    if (level == 1) {
        rising_edge_tick = tick;
        echo_received = 0; // Reset echo_received flag on rising edge
        timeout_occurred = 0; // Reset timeout flag on rising edge
    } else if (level == 0) {
        falling_edge_tick = tick;
        echo_received = 1;
    }
    pthread_mutex_unlock(&mutex);
}

// Function to calculate distance from pulse width
double calculate_distance(uint32_t pulse_width) {
    if (pulse_width > 23200) {
        return -1.0; // Invalid pulse width (out of range)
    }
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // Distance in cm
}

// Function to log distance to file
void log_distance(double distance) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    uint64_t timestamp_ns = (uint64_t)ts.tv_sec * 1000000000LL + ts.tv_nsec;

    pthread_mutex_lock(&mutex);
    if (log_file != NULL) {
        fprintf(log_file, "%llu,%.2f\n", timestamp_ns, distance);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
    pthread_mutex_unlock(&mutex);
}

// Timeout handler function
void timeout_handler() {
    pthread_mutex_lock(&mutex);
    timeout_occurred = 1;
    echo_received = 0; // Reset echo_received flag
    pthread_mutex_unlock(&mutex);
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
}

// Initialization function
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (pthread_mutex_init(&mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    gpioWrite(TRIG_PIN, 0); // Ensure TRIG is low initially

    // Set up interrupt handlers
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for ECHO pin\n");
        gpioTerminate();
        pthread_mutex_destroy(&mutex);
        return 1;
    }

    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        pthread_mutex_destroy(&mutex);
        return 1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    pthread_mutex_lock(&mutex);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    pthread_mutex_destroy(&mutex);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize() != 0) {
        return 1;
    }

    printf("Ultrasonic sensor program started. Press Ctrl+C to exit.\n");

    while (running) {
        trigger_sensor();

        // Set up timeout
        gpioSetTimerFuncEx(0, TIMEOUT_US, timeout_handler, NULL);

        // Wait for echo or timeout
        while (!echo_received && !timeout_occurred && running) {
            gpioDelay(100); // Check every 100us
        }

        gpioSetTimerFuncEx(0, 0, NULL, NULL); // Disable timeout

        pthread_mutex_lock(&mutex);
        uint32_t pulse_width = falling_edge_tick - rising_edge_tick;
        pthread_mutex_unlock(&mutex);

        if (timeout_occurred) {
            fprintf(stderr, "Timeout occurred\n");
        } else {
            double distance = calculate_distance(pulse_width);

            if (distance >= 0) {
                log_distance(distance);
                printf("Distance: %.2f cm\n", distance);
            } else {
                fprintf(stderr, "Invalid pulse width: %u\n", pulse_width);
            }
        }

        gpioDelay(200000); // Wait 200ms before next measurement
    }

    cleanup();
    printf("Program terminated.\n");
    return 0;
}

