#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// LIS3DH I2C address
#define LIS3DH_ADDR 0x18

// LIS3DH register addresses
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D

// Buzzer GPIO pin
#define BUZZER_PIN 17

// Default free-fall and impact thresholds
#define DEFAULT_FREEFALL_THRESHOLD 0.2
#define DEFAULT_IMPACT_THRESHOLD 1.5

// Global variables
int i2c_handle;
double freefall_threshold = DEFAULT_FREEFALL_THRESHOLD;
double impact_threshold = DEFAULT_IMPACT_THRESHOLD;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c();
int init_lis3dh();
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
double calculate_magnitude(int16_t x, int16_t y, int16_t z);
int detect_freefall(double magnitude);
int detect_impact(double magnitude);
void activate_buzzer();
void signal_handler(int signal);
void cleanup();

// Structure to hold accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        freefall_threshold = atof(argv[1]);
    }
    if (argc > 2) {
        impact_threshold = atof(argv[2]);
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Initialize LIS3DH
    if (init_lis3dh() != 0) {
        fprintf(stderr, "LIS3DH initialisation failed\n");
        cleanup();
        return 1;
    }

    // Set buzzer pin as output
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    accelerometer_data_t accel_data;
    double magnitude;

    // Main loop
    while (program_running) {
        // Read acceleration data
        if (read_acceleration(&accel_data.x, &accel_data.y, &accel_data.z) == 0) {
            // Calculate acceleration magnitude
            magnitude = calculate_magnitude(accel_data.x, accel_data.y, accel_data.z);

            // Detect free-fall
            if (detect_freefall(magnitude)) {
                printf("Free-fall detected!\n");
            }

            // Detect impact
            if (detect_impact(magnitude)) {
                printf("Impact detected!\n");
                activate_buzzer();
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data\n");
        }

        // Delay for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

