#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// LIS3DH Registers
#define LIS3DH_REG_CTRL1 0x20
#define LIS3DH_REG_CTRL4 0x23
#define LIS3DH_REG_OUT_X_L 0x28
#define LIS3DH_REG_OUT_X_H 0x29
#define LIS3DH_REG_OUT_Y_L 0x2A
#define LIS3DH_REG_OUT_Y_H 0x2B
#define LIS3DH_REG_OUT_Z_L 0x2C
#define LIS3DH_REG_OUT_Z_H 0x2D

// Default values
#define DEFAULT_I2C_ADDRESS 0x18
#define DEFAULT_THRESHOLD 2.0
#define DEFAULT_SAMPLE_RATE 10 // Hz

// Global variables
int i2c_handle;
int i2c_address = DEFAULT_I2C_ADDRESS;
float threshold = DEFAULT_THRESHOLD;
int sample_rate = DEFAULT_SAMPLE_RATE;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_lis3dh();
int read_acceleration(float *x, float *y, float *z);
int log_acceleration(float x, float y, float z);
void signal_handler(int signal);
void cleanup();

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function to initialize the LIS3DH accelerometer
int init_lis3dh() {
    // Configure CTRL1: 100 Hz, Normal mode, Enable all axes
    if (i2cWriteByteData(i2c_handle, LIS3DH_REG_CTRL1, 0x77) != 0) {
        fprintf(stderr, "Error writing to CTRL1 register\n");
        return -1;
    }

    // Configure CTRL4: ±2g range, High-resolution mode
    if (i2cWriteByteData(i2c_handle, LIS3DH_REG_CTRL4, 0x88) != 0) {
        fprintf(stderr, "Error writing to CTRL4 register\n");
        return -1;
    }

    return 0;
}

// Function to read acceleration data from the LIS3DH
int read_acceleration(float *x, float *y, float *z) {
    char buffer[6];
    int16_t raw_x, raw_y, raw_z;

    // Read 6 bytes of data (X_L, X_H, Y_L, Y_H, Z_L, Z_H)
    if (i2cReadI2CBlockData(i2c_handle, LIS3DH_REG_OUT_X_L, buffer, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    // Combine low and high bytes for each axis
    raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Convert raw values to g units (±2g range, 12-bit resolution)
    *x = (float)raw_x / 4096.0f;
    *y = (float)raw_y / 4096.0f;
    *z = (float)raw_z / 4096.0f;

    return 0;
}

// Function to log acceleration data to a file
int log_acceleration(float x, float y, float z) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);

    fp = fopen("/var/log/high_acceleration.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return -1;
    }

    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, X: %.3f g, Y: %.3f g, Z: %.3f g\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            x, y, z);

    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to close I2C and terminate pigpio
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;
    accelerometer_data_t accel_data;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 16);
                if (i2c_address < 0x18 || i2c_address > 0x1F) {
                    fprintf(stderr, "Invalid I2C address. Must be between 0x18 and 0x1F.\n");
                    return 1;
                }
                break;
            case 't':
                threshold = atof(optarg);
                if (threshold <= 0) {
                    fprintf(stderr, "Invalid threshold. Must be greater than 0.\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, i2c_address, 0); // Bus 1, address, flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LIS3DH
    if (init_lis3dh() != 0) {
        fprintf(stderr, "LIS3DH initialisation failed\n");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(&accel_data.x, &accel_data.y, &accel_data.z) == 0) {
            // Check for threshold exceedance
            if (fabs(accel_data.x) > threshold || fabs(accel_data.y) > threshold || fabs(accel_data.z) > threshold) {
                // Log acceleration data
                if (log_acceleration(accel_data.x, accel_data.y, accel_data.z) != 0) {
                    fprintf(stderr, "Error logging acceleration data\n");
                }

                // Shutdown the system
                fprintf(stderr, "Threshold exceeded, shutting down...\n");
                system("sudo shutdown -h now");
                break; // Exit the loop after shutdown command
            }
        } else {
            fprintf(stderr, "Error reading acceleration data, retrying...\n");
        }

        // Delay for 100ms (10Hz sampling rate)
        gpioDelay(100000); // 100000 microseconds = 100 milliseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

