// Define GPIO pins
#define LEFT_SENSOR_PIN 4
#define CENTER_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27
#define ALERT_PIN 22

// Define circular buffer size
#define BUFFER_SIZE 5

// Structure to hold sensor readings
typedef struct {
    int left;
    int center;
    int right;
} SensorReadings;

// Circular buffer
SensorReadings sensor_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int read_sensor(int gpio_pin);
void add_reading(SensorReadings reading);
SensorReadings get_latest_readings();
int check_line_present();
void move_forward();
void turn_left();
void turn_right();
void stop_robot();
void alert_user();
void signal_handler(int signal);

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function to read sensor value
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor on GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate error
    }
    return value;
}

// Function to add reading to circular buffer
void add_reading(SensorReadings reading) {
    sensor_buffer[buffer_index] = reading;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

