void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    program_running = 0; // Set program state to stop
    gpioWrite(ALERT_PIN, 0); // Ensure alert pin is LOW
    gpioTerminate();       // Terminate pigpio
    exit(0);                // Exit program
}

