    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetMode(CENTER_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);
    gpioSetMode(ALERT_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Line following robot started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor values
        int left_value = read_sensor(LEFT_SENSOR_PIN);
        int center_value = read_sensor(CENTER_SENSOR_PIN);
        int right_value = read_sensor(RIGHT_SENSOR_PIN);

        if (left_value == -1 || center_value == -1 || right_value == -1) {
            fprintf(stderr, "Error reading sensors, skipping iteration.\n");
            gpioDelay(10); // Small delay to prevent busy-waiting
            continue;
        }

        // Create sensor readings struct
        SensorReadings readings = {left_value, center_value, right_value};

        // Add reading to circular buffer
        add_reading(readings);

        // Check if line is present
        if (check_line_present()) {
            alert_user();
        } else {
            // Determine motor control based on sensor readings
            if (left_value == 0) {
                turn_left();
            } else if (right_value == 0) {
                turn_right();
            } else {
                move_forward();
            }
        }

        gpioDelay(10); // Delay for 10 milliseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(ALERT_PIN, 0);
    gpioTerminate();

    return 0;
}

