#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI7210_ADDR 0x40
#define MAGNETIC_FIELD_REG 0x00 // Replace with actual register address
#define RELAY_GPIO 17
#define THRESHOLD 5.0
#define POLL_ATTEMPTS 50
#define POLL_DELAY_US 1000 // 1ms
#define SAMPLE_DELAY_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_magnetic_field(float *field);
int control_relay(int state);
int log_event(const char *message);
void signal_handler(int signal);
void cleanup();

// Structure for sensor configuration (example)
typedef struct {
    int i2c_bus;
    int i2c_address;
    int relay_gpio;
    float threshold;
} sensor_config_t;

// Function to initialize the I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7210_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read magnetic field data from the sensor
int read_magnetic_field(float *field) {
    char buf[2];
    int16_t raw_data;
    int i;

    // Attempt to read the magnetic field data with retries
    for (i = 0; i < POLL_ATTEMPTS; ++i) {
        if (i2cReadI2CBlockData(i2c_handle, MAGNETIC_FIELD_REG, buf, 2) == 2) {
            // Combine the two bytes into a 16-bit value
            raw_data = (buf[0] << 8) | buf[1];

            // Convert raw data to magnetic field (mT) - Replace with actual conversion formula
            *field = (float)raw_data * 0.01; // Example conversion

            // Data validation (example)
            if (*field < -1000.0 || *field > 1000.0) {
                fprintf(stderr, "Error: Magnetic field reading out of range: %.2f mT\n", *field);
                log_event("Error: Magnetic field reading out of range");
                return -1;
            }

            return 0; // Success
        } else {
            fprintf(stderr, "Error reading I2C data (attempt %d): %d\n", i + 1, i2c_handle);
            log_event("Error reading I2C data");
            gpioDelay(POLL_DELAY_US); // Wait before retrying
        }
    }

    fprintf(stderr, "Timeout reading I2C data after %d attempts\n", POLL_ATTEMPTS);
    log_event("Timeout reading I2C data");
    return -1; // Failure after all retries
}

// Function to control the relay
int control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
    return 0;
}

// Function to log events to a file
int log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure the log is written immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    fprintf(stderr, "Cleaning up...\n");
    control_relay(0); // Deactivate relay
    i2cClose(i2c_handle);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    float magnetic_field;
    int relay_state = 0; // 0 = off, 1 = on

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("magnetic_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Magnetic field monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read magnetic field
        if (read_magnetic_field(&magnetic_field) == 0) {
            char log_message[128];
            snprintf(log_message, sizeof(log_message), "Magnetic field: %.2f mT", magnetic_field);
            log_event(log_message);

            // Control relay based on threshold
            if (magnetic_field > THRESHOLD && relay_state == 0) {
                control_relay(1);
                relay_state = 1;
                log_event("Relay activated");
            } else if (magnetic_field <= THRESHOLD && relay_state == 1) {
                control_relay(0);
                relay_state = 0;
                log_event("Relay deactivated");
            }
        } else {
            fprintf(stderr, "Failed to read magnetic field. Deactivating relay.\n");
            control_relay(0);
            relay_state = 0;
        }

        gpioDelay(SAMPLE_DELAY_MS * 1000); // Delay for 100ms
    }

    // Cleanup and exit
    cleanup();
    fprintf(stderr, "Exiting.\n");
    return 0;
}

