#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define PORT 5000
#define BUFFER_SIZE 1024

int server_fd, new_socket;
FILE *log_file;

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Ensure relay is off initially
    return 0;
}

// Function to turn the relay ON
void relay_on() {
    gpioWrite(GPIO_PIN, 1);
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s - Relay ON\n", timestamp);
    fflush(log_file);
}

// Function to turn the relay OFF
void relay_off() {
    gpioWrite(GPIO_PIN, 0);
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s - Relay OFF\n", timestamp);
    fflush(log_file);
}

// Function to handle commands
void handle_command(char *command) {
    if (strcmp(command, "ON") == 0) {
        relay_on();
    } else if (strcmp(command, "OFF") == 0) {
        relay_off();
    } else {
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[80];

        time(&rawtime);
        timeinfo = localtime(&rawtime);

        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
        fprintf(log_file, "%s - Invalid command: %s\n", timestamp, command);
        fflush(log_file);
    }
}

// Function to handle client connection
void handle_client(int client_socket) {
    char buffer[BUFFER_SIZE] = {0};
    ssize_t valread;

    valread = recv(client_socket, buffer, BUFFER_SIZE - 1, 0);
    if (valread < 0) {
        perror("recv failed");
        return;
    }

    // Remove trailing whitespace
    char *end = buffer + strlen(buffer) - 1;
    while (end > buffer && isspace((unsigned char)*end)) {
        end--;
    }
    end[1] = '\0';

    handle_command(buffer);
    close(client_socket);
}

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    printf("Caught signal %d, shutting down...\n", signum);

    // Turn off the relay
    relay_off();

    // Close the socket
    close(new_socket);
    close(server_fd);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    struct sockaddr_in address;
    int addrlen = sizeof(address);
    int opt = 1;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the log file
    log_file = fopen("relay_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fclose(log_file);
        return 1;
    }

    // Create socket file descriptor
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    // Forcefully attaching socket to the port 5000
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        perror("setsockopt");
        gpioTerminate();
        fclose(log_file);
        close(server_fd);
        return 1;
    }
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    // Forcefully attaching socket to the port 5000
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        gpioTerminate();
        fclose(log_file);
        close(server_fd);
        return 1;
    }
    if (listen(server_fd, 3) < 0) {
        perror("listen");
        gpioTerminate();
        fclose(log_file);
        close(server_fd);
        return 1;
    }

    printf("Server listening on port %d...\n", PORT);

    while (1) {
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("accept");
            continue; // Continue listening for other connections
        }

        handle_client(new_socket);
    }

    return 0;
}

