#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Sensor I2C addresses
#define SENSOR1_ADDR 0x36
#define SENSOR2_ADDR 0x37

// I2C bus
#define I2C_BUS 1

// GPIO pin for relay control
#define RELAY_PIN 18

// Flow rate threshold (ml/min)
#define FLOW_THRESHOLD 5.0

// Start measurement command (high precision)
#define START_MEASUREMENT_CMD_1 0x36
#define START_MEASUREMENT_CMD_2 0x08

// CRC-8 polynomial
#define CRC8_POLYNOMIAL 0x31

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float flow_rate;
    int crc_valid;
} sensor_data_t;

// Function prototypes
int initialize_i2c(int bus, int addr);
int start_measurement(int handle);
int read_sensor_data(int handle, uint8_t *data);
float convert_to_flow_rate(uint16_t raw_flow);
int validate_crc(uint8_t data[], int len);
void control_relay(int gpio_pin, int state);
void log_flow_rate(float flow_rate1, float flow_rate2);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C communication
int initialize_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Start measurement on the sensor
int start_measurement(int handle) {
    char cmd[2] = {START_MEASUREMENT_CMD_1, START_MEASUREMENT_CMD_2};
    int result = i2cWriteDevice(handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing start measurement command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(int handle, uint8_t *data) {
    int bytes_read = i2cReadDevice(handle, (char *)data, 3);
    if (bytes_read != 3) {
        fprintf(stderr, "Error reading sensor data: %d\n", bytes_read);
        return -1;
    }
    return 0;
}

// Convert raw flow rate data to ml/min
float convert_to_flow_rate(uint16_t raw_flow) {
    // Conversion formula from SLF3S-1300F datasheet
    return (float)raw_flow / 120.0;
}

// Validate CRC-8 checksum
int validate_crc(uint8_t data[], int len) {
    uint8_t crc = crc8(data, len - 1);
    return (crc == data[len - 1]);
}

// Control the relay
void control_relay(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

// Log flow rate data to file
void log_flow_rate(float flow_rate1, float flow_rate2) {
    FILE *fp = fopen("flow_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

    fprintf(fp, "%ld,%.2f,%.2f\n", timestamp_ms, flow_rate1, flow_rate2);
    fflush(fp);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    fprintf(stderr, "Cleaning up resources...\n");
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }
    gpioWrite(RELAY_PIN, 0); // De-energize relay
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin for relay as output
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Initialize I2C for both sensors
    i2c_handle1 = initialize_i2c(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        cleanup();
        return 1;
    }

    i2c_handle2 = initialize_i2c(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Monitoring flow rates... Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        uint8_t data1[3];
        uint8_t data2[3];
        sensor_data_t sensor1_data, sensor2_data;

        // Read data from sensor 1
        if (start_measurement(i2c_handle1) == 0 && read_sensor_data(i2c_handle1, data1) == 0) {
            uint16_t raw_flow1 = (data1[0] << 8) | data1[1];
            sensor1_data.flow_rate = convert_to_flow_rate(raw_flow1);
            sensor1_data.crc_valid = validate_crc(data1, 3);
        } else {
            sensor1_data.flow_rate = -1.0; // Indicate error
            sensor1_data.crc_valid = 0;
        }

        // Read data from sensor 2
        if (start_measurement(i2c_handle2) == 0 && read_sensor_data(i2c_handle2, data2) == 0) {
            uint16_t raw_flow2 = (data2[0] << 8) | data2[1];
            sensor2_data.flow_rate = convert_to_flow_rate(raw_flow2);
            sensor2_data.crc_valid = validate_crc(data2, 3);
        } else {
            sensor2_data.flow_rate = -1.0; // Indicate error
            sensor2_data.crc_valid = 0;
        }

        // Check for CRC errors
        if (!sensor1_data.crc_valid) {
            fprintf(stderr, "CRC error in sensor 1 data!\n");
        }
        if (!sensor2_data.crc_valid) {
            fprintf(stderr, "CRC error in sensor 2 data!\n");
        }

        // Control relay based on flow rates
        if (sensor1_data.flow_rate >= FLOW_THRESHOLD && sensor2_data.flow_rate >= FLOW_THRESHOLD) {
            control_relay(RELAY_PIN, 1); // Energize relay
        } else {
            control_relay(RELAY_PIN, 0); // De-energize relay
        }

        // Log flow rates
        log_flow_rate(sensor1_data.flow_rate, sensor2_data.flow_rate);

        // Delay for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup and exit
    cleanup();
    fprintf(stderr, "Program terminated.\n");
    return 0;
}

