// Define GPIO pins
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

// Define motor control constants
#define MOTOR_CLOSE_DURATION 5 // seconds
#define MOTOR_START_DELAY 1    // seconds

// Define debounce constants
#define DEBOUNCE_READINGS 3
#define DEBOUNCE_DELAY 200 // milliseconds

