volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_rain_sensor();
int debounce_rain_sensor();
int control_motor(int direction);
int stop_motor();
void log_event(int priority, const char *message);
void signal_handler(int signal);
void cleanup();

// Structure to hold GPIO pin configurations
typedef struct {
    int rain_sensor;
    int motor_ena;
    int motor_in1;
    int motor_in2;
} gpio_config_t;

gpio_config_t gpio_config = {
    RAIN_SENSOR_PIN,
    MOTOR_ENA_PIN,
    MOTOR_IN1_PIN,
    MOTOR_IN2_PIN
};

int main() {
    // Initialize syslog
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);

    // Log program startup
    log_event(LOG_INFO, "Program started");

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_event(LOG_ERR, "GPIO initialization failed");
        cleanup();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read rain sensor
        if (debounce_rain_sensor() == 0) { // Dry to wet transition
            // Log rain detection
            log_event(LOG_INFO, "Rain detected");

            // Start motor
            if (control_motor(1) != 0) { // Close window
                log_event(LOG_ERR, "Failed to start motor");
            } else {
                // Wait for motor to close
                sleep(MOTOR_CLOSE_DURATION);

                // Stop motor
                if (stop_motor() != 0) {
                    log_event(LOG_ERR, "Failed to stop motor");
                } else {
                    // Log motor stop
                    log_event(LOG_INFO, "Motor stopped");
                }
            }

            // Debounce delay
            gpioDelay(MOTOR_START_DELAY * 1000000); // Convert seconds to microseconds
        }

        // Small delay to prevent busy-waiting
        gpioDelay(10000); // 10ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        log_event(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Set rain sensor pin as input with pull-up resistor
    if (gpioSetMode(gpio_config.rain_sensor, PI_INPUT) != 0) {
        log_event(LOG_ERR, "Failed to set rain sensor pin as input");
        gpioTerminate();
        return 1;
