    if (gpioSetMode(gpio_config.motor_ena, PI_OUTPUT) != 0) {
        log_event(LOG_ERR, "Failed to set motor ENA pin as output");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(gpio_config.motor_in1, PI_OUTPUT) != 0) {
        log_event(LOG_ERR, "Failed to set motor IN1 pin as output");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(gpio_config.motor_in2, PI_OUTPUT) != 0) {
        log_event(LOG_ERR, "Failed to set motor IN2 pin as output");
