int debounce_rain_sensor() {
    int readings[DEBOUNCE_READINGS];
    int dry_count = 0;

    // Take multiple readings
    for (int i = 0; i < DEBOUNCE_READINGS; i++) {
        readings[i] = read_rain_sensor();
        gpioDelay(DEBOUNCE_DELAY * 1000); // Convert milliseconds to microseconds
    }

    // Check if all readings are dry
    for (int i = 0; i < DEBOUNCE_READINGS; i++) {
        if (readings[i] == 0) {
            dry_count++;
        }
    }

    // Return 1 if all readings are dry, 0 otherwise
    return (dry_count == DEBOUNCE_READINGS) ? 1 : 0;
}

// Control motor direction
int control_motor(int direction) {
    // direction: 1 = close, 0 = open
    if (direction == 1) {
        // Close window
        if (gpioWrite(gpio_config.motor_ena, 1) != 0) {
            log_event(LOG_ERR, "Failed to set motor ENA high");
            return 1;
        }
        if (gpioWrite(gpio_config.motor_in1, 1) != 0) {
            log_event(LOG_ERR, "Failed to set motor IN1 high");
            return 1;
        }
        if (gpioWrite(gpio_config.motor_in2, 0) != 0) {
            log_event(LOG_ERR, "Failed to set motor IN2 low");
            return 1;
        }
    } else {
        // Open window (not implemented in this version)
        log_event(LOG_WARNING, "Motor open direction not implemented");
        return 1;
    }
    return 0;
}

// Stop motor
int stop_motor() {
    if (gpioWrite(gpio_config.motor_ena, 0) != 0) {
        log_event(LOG_ERR, "Failed to set motor ENA low");
        return 1;
    }
    if (gpioWrite(gpio_config.motor_in1, 0) != 0) {
        log_event(LOG_ERR, "Failed to set motor IN1 low");
        return 1;
    }
    if (gpioWrite(gpio_config.motor_in2, 0) != 0) {
        log_event(LOG_ERR, "Failed to set motor IN2 low");
        return 1;
    }
    return 0;
}

// Log events to syslog
void log_event(int priority, const char *message) {
    syslog(priority, "%s", message);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    log_event(LOG_INFO, "Signal received, shutting down...");
}

// Cleanup function
void cleanup() {
    // Stop motor
    stop_motor();

    // Terminate pigpio library
    gpioTerminate();

    // Close syslog
    closelog();
}

