#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

// Define servo pulse widths
#define LOCK_PULSE_WIDTH 2000
#define UNLOCK_PULSE_WIDTH 1000

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int lock_door();
int unlock_door();
int stop_servo();
void button_callback(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// Structure to hold button states
typedef struct {
    int lock_pressed;
    int unlock_pressed;
} ButtonState;

ButtonState button_states = {0, 0};

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return 1;
    }

    // Set up button callbacks
    gpioSetAlertFuncEx(LOCK_BUTTON_PIN, button_callback, NULL);
    gpioSetAlertFuncEx(UNLOCK_BUTTON_PIN, button_callback, NULL);

    printf("Door lock control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        sleep(1); // Reduce CPU usage
    }

    // Clean up and exit
    return 0;
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set servo pin as output
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set button pins as inputs with pull-up resistors
    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);

    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);

    return 0;
}

// Function to lock the door
int lock_door() {
    int result = gpioServo(SERVO_PIN, LOCK_PULSE_WIDTH);
    if (result != 0) {
        fprintf(stderr, "Error locking door: %d\n", result);
        return 1;
    }
    printf("Door locked.\n");
    return 0;
}

// Function to unlock the door
int unlock_door() {
    int result = gpioServo(SERVO_PIN, UNLOCK_PULSE_WIDTH);
    if (result != 0) {
        fprintf(stderr, "Error unlocking door: %d\n", result);
        return 1;
    }
    printf("Door unlocked.\n");
    return 0;
}

// Function to stop the servo
int stop_servo() {
    int result = gpioServo(SERVO_PIN, 0);
    if (result != 0) {
        fprintf(stderr, "Error stopping servo: %d\n", result);
        return 1;
    }
    printf("Servo stopped.\n");
    return 0;
}

// Callback function for button presses
void button_callback(int gpio, int level, uint32_t tick) {
    if (level == 0) { // Button pressed (falling edge)
        if (gpio == LOCK_BUTTON_PIN) {
            if (!button_states.lock_pressed) {
                lock_door();
                button_states.lock_pressed = 1;
                gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce
            }
        } else if (gpio == UNLOCK_BUTTON_PIN) {
            if (!button_states.unlock_pressed) {
                unlock_door();
                button_states.unlock_pressed = 1;
                gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce
            }
        }
    } else { // Button released (rising edge)
        if (gpio == LOCK_BUTTON_PIN) {
            button_states.lock_pressed = 0;
        } else if (gpio == UNLOCK_BUTTON_PIN) {
            button_states.unlock_pressed = 0;
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received, shutting down...\n");
    program_running = 0;
    stop_servo();
    gpioTerminate();
    exit(0);
}

