volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
int control_led(int state);
int log_event(const char *event_type, const char *timestamp, double duration);
void cleanup();
void signal_handler(int signal);
char* get_iso8601_timestamp();

// Signal handler function
