int read_pir_sensor() {
    return gpioRead(PIR_SENSOR_PIN);
}

// Function to control the LED
int control_led(int state) {
    gpioWrite(LED_PIN, state);
    return 0;
}

// Function to log events to a file
int log_event(const char *event_type, const char *timestamp, double duration) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return 1;
    }

    if (strcmp(event_type, "activation") == 0) {
        fprintf(log_file, "%s - Motion detected, LED activated\n", timestamp);
    } else if (strcmp(event_type, "deactivation") == 0) {
        fprintf(log_file, "%s - LED deactivated, duration: %.2f seconds\n", timestamp, duration);
    } else {
        fprintf(stderr, "Invalid event type: %s\n", event_type);
