// Global variables
static int i2c_fd;
static volatile sig_atomic_t program_running = 1;
static volatile bool relay_state = false;

// Function prototypes
int mpr121_init(int fd);
int mpr121_read_touch_status(int fd);
void relay_on(int pin);
void relay_off(int pin);
void debounce_delay(int ms);
void signal_handler(int signal);

// Function to initialize the MPR121
int mpr121_init(int fd) {
    // Soft reset
    if (wiringPiI2CWriteReg8(fd, MPR121_SOFTRESET, 0x63) < 0) {
        fprintf(stderr, "Error: Soft reset failed\n");
        return -1;
    }
    delay(100); // Wait for reset to complete

    // Configure baseline filtering
    if (wiringPiI2CWriteReg8(fd, MPR121_MHDR, 0x01) < 0) return -1;
    if (wiringPiI2CWriteReg8(fd, MPR121_NHDR, 0x01) < 0) return -1;
    if (wiringPiI2CWriteReg8(fd, MPR121_NCLR, 0x0E) < 0) return -1;
    if (wiringPiI2CWriteReg8(fd, MPR121_FDLR, 0x00) < 0) return -1;
    if (wiringPiI2CWriteReg8(fd, MPR121_MHDF, 0x01) < 0) return -1;
    if (wiringPiI2CWriteReg8(fd, MPR121_NHDF, 0x01) < 0) return -1;
    if (wiringPiI2CWriteReg8(fd, MPR121_NCLF, 0x0E) < 0) return -1;
    if (wiringPiI2CWriteReg8(fd, MPR121_FDLF, 0x00) < 0) return -1;

    // Set touch and release thresholds for electrode 0
    if (wiringPiI2CWriteReg8(fd, MPR121_ELE0_TOUCHTH, 0x30) < 0) return -1;
    if (wiringPiI2CWriteReg8(fd, MPR121_ELE0_RELEASETH, 0x10) < 0) return -1;

    // Enable auto-config and set electrode sensitivity
    if (wiringPiI2CWriteReg8(fd, MPR121_CONFIG1, 0x10) < 0) return -1; // Set Electrode Configuration
    if (wiringPiI2CWriteReg8(fd, MPR121_CONFIG2, 0x20) < 0) return -1; // Set Debounce Configuration
    if (wiringPiI2CWriteReg8(fd, MPR121_CONFIG3, 0x01) < 0) return -1; // Set Filter Configuration

    // Enable all 12 electrodes
    if (wiringPiI2CWriteReg8(fd, MPR121_ECR, 0x0C) < 0) return -1; // Enable electrodes 0-11

    return 0;
}

