int mpr121_read_touch_status(int fd) {
    int touch_status_l = wiringPiI2CReadReg8(fd, MPR121_TOUCHSTATUS_L);
    int touch_status_h = wiringPiI2CReadReg8(fd, MPR121_TOUCHSTATUS_H);

    if (touch_status_l < 0 || touch_status_h < 0) {
        fprintf(stderr, "Error: Failed to read touch status\n");
        return -1;
    }

    return (touch_status_h << 8) | touch_status_l;
}

// Function to turn the relay ON
void relay_on(int pin) {
    digitalWrite(pin, HIGH);
    relay_state = true;
    printf("Relay ON\n");
}

// Function to turn the relay OFF
void relay_off(int pin) {
    digitalWrite(pin, LOW);
    relay_state = false;
    printf("Relay OFF\n");
}

// Function to implement a delay with debouncing
void debounce_delay(int ms) {
    delay(ms);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    program_running = 0;
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error: Failed to initialize wiringPi\n");
        return 1;
    }

    // Initialize I2C
    i2c_fd = wiringPiI2CSetup(MPR121_I2C_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Error: Failed to initialize I2C communication\n");
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init(i2c_fd) == -1) {
        fprintf(stderr, "Error: Failed to initialize MPR121\n");
        return 1;
    }

    // Set relay pin as output
    pinMode(RELAY_GPIO_PIN, OUTPUT);
    relay_off(RELAY_GPIO_PIN); // Ensure relay is initially OFF

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("MPR121 Relay Control Program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int touch_status = mpr121_read_touch_status(i2c_fd);
        if (touch_status == -1) {
            fprintf(stderr, "Error: Failed to read touch status, exiting.\n");
            break;
        }

        // Check if electrode 0 is touched
        if (touch_status & 0x01) {
            // Debounce the touch
            debounce_delay(DEBOUNCE_DELAY_MS);

            // Re-read the touch status to confirm the rising edge
            int touch_status_after_debounce = mpr121_read_touch_status(i2c_fd);
            if (touch_status_after_debounce == -1) {
                fprintf(stderr, "Error: Failed to read touch status after debounce, exiting.\n");
                break;
            }

            if (touch_status_after_debounce & 0x01) {
                // Toggle the relay state
                if (!relay_state) {
                    relay_on(RELAY_GPIO_PIN);
                } else {
                    relay_off(RELAY_GPIO_PIN);
                }
            }
        }

        delay(50); // Small delay to prevent busy-waiting
    }

    // Clean up and exit
    relay_off(RELAY_GPIO_PIN); // Ensure relay is OFF on exit
    printf("Program finished.\n");
    return 0;
}

