#include <time.h>
#include <errno.h>
#include <pigpio.h>

#define SERVO_GPIO 17
#define PIR_GPIO 4
#define PORT 5000
#define PWM_FREQUENCY 50
#define PWM_RANGE 20000 // 20ms period
#define LOG_FILE "security.log"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int server_fd = -1;
int client_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int set_servo_angle(int angle);
int read_pir_sensor();
int handle_client(int client_socket);
void log_message(int priority, const char *format, ...);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO using pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(SERVO_GPIO, PI_OUTPUT);
    gpioSetMode(PIR_GPIO, PI_INPUT);
    gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN); // Use pull-down resistor

    // Set PWM frequency and range
    gpioSetPWMfrequency(SERVO_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(SERVO_GPIO, PWM_RANGE);

    return 0;
}

// Function to set the servo angle using PWM
int set_servo_angle(int angle) {
    if (angle < 0 || angle > 180) {
        log_message(LOG_ERR, "Invalid servo angle: %d", angle);
        return -1;
    }

    // Convert angle to pulse width (1ms - 2ms)
    int pulse_width = 1000 + (angle * 1000 / 180); // 1000us + (angle * 1000us / 180)

    // Set PWM duty cycle (pulse width / period)
    int duty_cycle = (pulse_width * PWM_RANGE) / 20000; // 20ms period

    if (gpioPWM(SERVO_GPIO, duty_cycle) != 0) {
        log_message(LOG_ERR, "Failed to set PWM duty cycle: %d", duty_cycle);
        return -1;
    }

    log_message(LOG_INFO, "Servo angle set to: %d", angle);
    return 0;
}

// Function to read the PIR sensor
int read_pir_sensor() {
    int pir_value = gpioRead(PIR_GPIO);
    if (pir_value < 0) {
        log_message(LOG_ERR, "Failed to read PIR sensor");
        return -1;
    }
    return pir_value;
}

// Function to handle client connections
int handle_client(int client_socket) {
    char buffer[1024] = {0};
    ssize_t bytes_received;

    while ((bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0)) > 0) {
        buffer[bytes_received] = '\0';
        log_message(LOG_INFO, "Received: %s", buffer);

        if (strncmp(buffer, "the library's API call ", 22) == 0) {
            int angle;
            if (sscanf(buffer + 22, "%d", &angle) == 1) {
                if (set_servo_angle(angle) == 0) {
                    send(client_socket, "OK", strlen("OK"), 0);
                } else {
                    send(client_socket, "ERROR", strlen("ERROR"), 0);
                }
            } else {
                log_message(LOG_ERR, "Invalid angle format");
                send(client_socket, "ERROR", strlen("ERROR"), 0);
            }
        } else if (strcmp(buffer, "PIR") == 0) {
            int pir_value = read_pir_sensor();
            if (pir_value >= 0) {
                char response[10];
                snprintf(response, sizeof(response), "PIR:%d", pir_value);
                send(client_socket, response, strlen(response), 0);
            } else {
                send(client_socket, "ERROR", strlen("ERROR"), 0);
            }
        } else {
            log_message(LOG_WARNING, "Unknown command: %s", buffer);
            send(client_socket, "ERROR", strlen("ERROR"), 0);
        }
    }

    if (bytes_received == 0) {
        log_message(LOG_INFO, "Client disconnected");
    } else if (bytes_received < 0) {
        log_message(LOG_ERR, "Receive failed: %s", strerror(errno));
    }

    return 0;
}

// Function to log messages to syslog and file
void log_message(int priority, const char *format, ...) {
    va_list args;
    va_start(args, format);

    // Log to syslog
    vsyslog(priority, format, args);

    // Log to file
    if (log_file != NULL) {
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[30];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

        fprintf(log_file, "%s: ", timestamp);
        vfprintf(log_file, format, args);
        fprintf(log_file, "\n");
        fflush(log_file); // Ensure immediate write
    }

    va_end(args);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    log_message(LOG_INFO, "Signal received, shutting down...");
}

