void cleanup() {
    log_message(LOG_INFO, "Cleaning up resources...");

    // Close socket
    if (client_fd != -1) {
        close(client_fd);
    }
    if (server_fd != -1) {
        close(server_fd);
    }

    // Stop PWM
    gpioPWM(SERVO_GPIO, 0);

    // Release GPIO resources
    gpioTerminate();

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    log_message(LOG_INFO, "Cleanup complete. Exiting.");
}

int main() {
    // Initialize syslog
    openlog("servo_control", LOG_PID | LOG_CONS, LOG_USER);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        log_message(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        closelog();
        return 1;
    }

    log_message(LOG_INFO, "Starting servo control program...");

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_message(LOG_ERR, "GPIO initialization failed. Exiting.");
        cleanup();
        closelog();
        return 1;
    }

    // Create socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == -1) {
        log_message(LOG_ERR, "Socket creation failed: %s", strerror(errno));
        cleanup();
        closelog();
        return 1;
    }

    // Bind socket to address and port
    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        log_message(LOG_ERR, "Socket bind failed: %s", strerror(errno));
        cleanup();
        closelog();
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        log_message(LOG_ERR, "Socket listen failed: %s", strerror(errno));
        cleanup();
        closelog();
        return 1;
    }

    log_message(LOG_INFO, "Listening on port %d...", PORT);

    // Main loop
    while (program_running) {
        struct sockaddr_in client_address;
        int client_address_len = sizeof(client_address);

        // Accept connection
        client_fd = accept(server_fd, (struct sockaddr *)&client_address, (socklen_t*)&client_address_len);
        if (client_fd < 0) {
            if (program_running) { // Only log if not shutting down
                log_message(LOG_ERR, "Socket accept failed: %s", strerror(errno));
            }
            continue; // Continue listening for other connections
        }

        log_message(LOG_INFO, "Connection accepted from %s:%d", inet_ntoa(client_address.sin_addr), ntohs(client_address.sin_port));

        // Handle client
        handle_client(client_fd);

        // Close client socket
        close(client_fd);
        client_fd = -1;
    }

    // Cleanup and exit
    cleanup();
    closelog();
    return 0;
}

