#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define RELAY_GPIO 23
#define LUX_THRESHOLD 150.0
#define SAMPLE_INTERVAL 2.0 // seconds
#define RETRY_DELAY 0.1 // seconds
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_gpio();
int init_logging();
int read_bh1750(float *lux);
int control_relay(int state);
int log_data(float lux);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int bh1750_address;
    int relay_gpio;
    float lux_threshold;
    float sample_interval;
} config_t;

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize GPIO
int init_gpio() {
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        return -1;
    }
    return 0;
}

// Initialize logging
int init_logging() {
    log_file = fopen("grow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return -1;
    }
    return 0;
}

// Read BH1750 sensor
int read_bh1750(float *lux) {
    char buf[2];
    int result;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        result = i2cWriteByte(i2c_handle, CONTINUOUS_HIGH_RES_MODE);
        if (result != 0) {
            fprintf(stderr, "Error writing to I2C (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY * 1000000); // Delay in microseconds
            retries++;
            continue;
        }

        gpioDelay(180000); // Wait for measurement (at least 180ms)

        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result != 2) {
            fprintf(stderr, "Error reading from I2C (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY * 1000000); // Delay in microseconds
            retries++;
            continue;
        }

        uint16_t raw_value = (buf[0] << 8) | buf[1];
        *lux = (float)raw_value / 1.2;
        return 0; // Success
    }

    fprintf(stderr, "Failed to read BH1750 after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Control relay
int control_relay(int state) {
    if (gpioWrite(RELAY_GPIO, state) != 0) {
        fprintf(stderr, "Error writing to GPIO\n");
        return -1;
    }
    return 0;
}

// Log data
int log_data(float lux) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(log_file, "%s, %.2f\n", timestamp, lux) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    control_relay(0); // Deactivate relay
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C, GPIO, and logging
    if (init_i2c() != 0 || init_gpio() != 0 || init_logging() != 0) {
        cleanup();
        return 1;
    }

    float lux;
    int relay_state = 0; // 0 = off, 1 = on

    printf("Grow light control started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        if (read_bh1750(&lux) == 0) {
            printf("Lux: %.2f\n", lux);

            if (log_data(lux) != 0) {
                fprintf(stderr, "Error logging data\n");
            }

            if (lux < LUX_THRESHOLD && relay_state == 0) {
                if (control_relay(1) == 0) {
                    relay_state = 1;
                    printf("Relay activated\n");
                } else {
                    fprintf(stderr, "Error activating relay\n");
                }
            } else if (lux >= LUX_THRESHOLD && relay_state == 1) {
                if (control_relay(0) == 0) {
                    relay_state = 0;
                    printf("Relay deactivated\n");
                } else {
                    fprintf(stderr, "Error deactivating relay\n");
                }
            }
        } else {
            fprintf(stderr, "Error reading lux value\n");
        }

        gpioDelay(SAMPLE_INTERVAL * 1000000); // Delay in microseconds
    }

    cleanup();
    return 0;
}

