        *lux = (float)raw_value / 1.2;
        return 0; // Success
    }

    fprintf(stderr, "Failed to read BH1750 after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Control relay
int control_relay(int state) {
    if (gpioWrite(RELAY_GPIO, state) != 0) {
        fprintf(stderr, "Error writing to GPIO\n");
        return -1;
    }
    return 0;
}

// Log data
int log_data(float lux) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(log_file, "%s, %.2f\n", timestamp, lux) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    control_relay(0); // Deactivate relay
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C, GPIO, and logging
    if (init_i2c() != 0 || init_gpio() != 0 || init_logging() != 0) {
        cleanup();
        return 1;
    }

    float lux;
    int relay_state = 0; // 0 = off, 1 = on

    printf("Grow light control started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        if (read_bh1750(&lux) == 0) {
            printf("Lux: %.2f\n", lux);

            if (log_data(lux) != 0) {
                fprintf(stderr, "Error logging data\n");
            }

            if (lux < LUX_THRESHOLD && relay_state == 0) {
                if (control_relay(1) == 0) {
                    relay_state = 1;
                    printf("Relay activated\n");
                } else {
                    fprintf(stderr, "Error activating relay\n");
                }
            } else if (lux >= LUX_THRESHOLD && relay_state == 1) {
                if (control_relay(0) == 0) {
                    relay_state = 0;
                    printf("Relay deactivated\n");
                } else {
                    fprintf(stderr, "Error deactivating relay\n");
                }
            }
        } else {
            fprintf(stderr, "Error reading lux value\n");
        }

        gpioDelay(SAMPLE_INTERVAL * 1000000); // Delay in microseconds
    }

    cleanup();
    return 0;
}

