#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DOUT 23
#define HX711_SCK 24
#define SOLENOID_PIN 25

// Default values
#define DEFAULT_THRESHOLD 1000.0
#define DEFAULT_SCALE 1.0
#define DEFAULT_DURATION 200

// Global variables
static volatile int running = 1;
static double scale_factor = DEFAULT_SCALE;
static int solenoid_duration = DEFAULT_DURATION;
static double threshold = DEFAULT_THRESHOLD;

// Function prototypes
int read_hx711();
double tare(int num_readings);
double convert_to_grams(int raw_value);
void control_solenoid(int state);
void signal_handler(int signal);
void parse_arguments(int argc, char *argv[]);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    running = 0;
    control_solenoid(0); // Ensure solenoid is off
    gpioTerminate(); // Release GPIO resources
    closelog(); // Close syslog
    exit(0);
}

// Function to read raw data from HX711
int read_hx711() {
    int i;
    int data = 0;
    int timeout = 1000; // Timeout in milliseconds

    // Wait for DOUT to go LOW with timeout
    while (gpioRead(HX711_DOUT) == 1 && timeout > 0) {
        gpioDelay(1); // Wait 1 ms
        timeout--;
    }

    if (timeout == 0) {
        syslog(LOG_ERR, "HX711 timeout waiting for DOUT to go LOW");
        return -1; // Indicate timeout error
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK, 1);
        gpioDelay(1); // Short delay
        data = data << 1;
        if (gpioRead(HX711_DOUT)) {
            data++;
        }
        gpioWrite(HX711_SCK, 0);
        gpioDelay(1); // Short delay
    }

    // Apply the 25th clock pulse for gain 128
    gpioWrite(HX711_SCK, 1);
    gpioDelay(1); // Short delay
    gpioWrite(HX711_SCK, 0);
    gpioDelay(1); // Short delay

    // Convert to signed 2's complement
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Function to tare the load cell
double tare(int num_readings) {
    double sum = 0.0;
    int i;

    syslog(LOG_INFO, "Taring...");

    for (i = 0; i < num_readings; i++) {
        int raw_value = read_hx711();
        if (raw_value == -1) {
            syslog(LOG_ERR, "Tare failed due to HX711 timeout");
            return -1.0; // Indicate tare failure
        }
        sum += raw_value;
        gpioDelay(10); // Small delay between readings
    }

    return sum / num_readings;
}

// Function to convert raw value to grams
double convert_to_grams(int raw_value) {
    return (raw_value - tare_value) / scale_factor;
}

// Function to control the solenoid lock
void control_solenoid(int state) {
    gpioWrite(SOLENOID_PIN, state);
    syslog(LOG_INFO, "Solenoid set to %d", state);
}

// Function to parse command-line arguments
void parse_arguments(int argc, char *argv[]) {
    int opt;

    while ((opt = getopt(argc, argv, "t:s:d:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                syslog(LOG_INFO, "Threshold set to %f", threshold);
                break;
            case 's':
                scale_factor = atof(optarg);
                syslog(LOG_INFO, "Scale factor set to %f", scale_factor);
                break;
            case 'd':
                solenoid_duration = atoi(optarg);
                syslog(LOG_INFO, "Solenoid duration set to %d", solenoid_duration);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-s scale_factor] [-d solenoid_duration]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }
}

int main(int argc, char *argv[]) {
    int i;
    double sum;
    double average_weight;
    double grams;
    int raw_value;
    double tare_value;

    // Initialize syslog
    openlog("weight_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Parse command-line arguments
    parse_arguments(argc, argv);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(HX711_DOUT, PI_INPUT);
    gpioSetMode(HX711_SCK, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Tare the load cell
    tare_value = tare(10);
    if (tare_value == -1.0) {
        syslog(LOG_ERR, "Tare failed, exiting");
        gpioTerminate();
        closelog();
        return 1;
    }
    syslog(LOG_INFO, "Tare value: %f", tare_value);

    // Main loop
    while (running) {
        sum = 0.0;

        // Average five readings
        for (i = 0; i < 5; i++) {
            raw_value = read_hx711();
            if (raw_value == -1) {
                syslog(LOG_ERR, "Failed to read HX711, retrying...");
                gpioDelay(100); // Wait before retrying
                i--; // Retry the current reading
                continue;
            }
            sum += raw_value;
            gpioDelay(10); // Small delay between readings
        }

        average_weight = sum / 5.0;
        grams = convert_to_grams(average_weight);

        syslog(LOG_INFO, "Raw: %f, Average: %f, Grams: %f", average_weight, average_weight, grams);

        // Check if weight exceeds threshold
        if (grams > threshold) {
            syslog(LOG_INFO, "Weight exceeds threshold, activating solenoid");
            control_solenoid(1); // Activate solenoid
            gpioDelay(solenoid_duration); // Keep solenoid activated for specified duration
            control_solenoid(0); // Deactivate solenoid
        }

        gpioDelay(500); // Wait 500ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioTerminate();
    closelog();
    return 0;
}

