#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <mosquitto.h>
#include <pigpio.h>

#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_TOPIC "home/lights/control"
#define MQTT_QOS 0
#define MQTT_KEEPALIVE 60
#define GPIO_PIN 17
#define LOG_TAG "mqtt_relay"

static struct mosquitto *mosq = NULL;
static volatile int running = 1;

// Function to log messages to syslog
void log_message(int priority, const char *message) {
    syslog(priority, "%s: %s", LOG_TAG, message);
}

// Function to set the relay state
int set_relay_state(int state) {
    if (gpioWrite(GPIO_PIN, state) != 0) {
        log_message(LOG_ERR, "Failed to write to GPIO pin");
        return -1;
    }
    return 0;
}

// Function to handle MQTT messages
void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        char *payload = (char *)message->payload;
        if (strcmp(payload, "ON") == 0) {
            if (set_relay_state(1) == 0) {
                log_message(LOG_INFO, "Relay ON");
            } else {
                log_message(LOG_ERR, "Failed to set relay ON");
            }
        } else if (strcmp(payload, "OFF") == 0) {
            if (set_relay_state(0) == 0) {
                log_message(LOG_INFO, "Relay OFF");
            } else {
                log_message(LOG_ERR, "Failed to set relay OFF");
            }
        } else {
            log_message(LOG_ERR, "Invalid payload received");
        }
    } else {
        log_message(LOG_ERR, "Empty payload received");
    }
}

// Function to handle MQTT connection
void connect_callback(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        log_message(LOG_INFO, "Connected to MQTT broker");
        int subscribe_result = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, MQTT_QOS);
        if (subscribe_result != MOSQ_ERR_SUCCESS) {
            log_message(LOG_ERR, "Failed to subscribe to topic");
            running = 0; // Stop the loop if subscription fails
        } else {
            log_message(LOG_INFO, "Subscribed to topic");
        }
    } else {
        log_message(LOG_ERR, "Connection failed");
        running = 0; // Stop the loop if connection fails
    }
}

// Function to handle MQTT disconnection
void disconnect_callback(struct mosquitto *mosq, void *userdata, int rc) {
    if (rc != 0) {
        log_message(LOG_WARNING, "Disconnected unexpectedly");
    } else {
        log_message(LOG_INFO, "Disconnected from MQTT broker");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    running = 0;
    log_message(LOG_INFO, "Signal received, shutting down...");
}

int main() {
    // Initialize syslog
    openlog(LOG_TAG, LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Initialize relay to OFF

    // Initialize MQTT client
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        log_message(LOG_ERR, "Failed to create MQTT client");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set callbacks
    mosquitto_connect_callback_set(mosq, connect_callback);
    mosquitto_disconnect_callback_set(mosq, disconnect_callback);
    mosquitto_message_callback_set(mosq, message_callback);

    // Connect to MQTT broker
    int connect_result = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, MQTT_KEEPALIVE);
    if (connect_result != MOSQ_ERR_SUCCESS) {
        log_message(LOG_ERR, "Failed to connect to MQTT broker");
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        int loop_result = mosquitto_loop(mosq, -1, 1); // Non-blocking loop with a timeout
        if (loop_result != MOSQ_ERR_SUCCESS) {
            log_message(LOG_ERR, "MQTT loop error");
            running = 0; // Exit loop on error
        }
        sleep(1); // Reduce CPU usage
    }

    // Cleanup
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioWrite(GPIO_PIN, 0); // Ensure relay is OFF on exit
    gpioTerminate();
    closelog();

    return 0;
}

