#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <wiringPi.h>
#include <softPwm.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Motor A
#define MOTOR_A_PWM_PIN 17
#define MOTOR_A_DIR_PIN 18

// Motor B
#define MOTOR_B_PWM_PIN 22
#define MOTOR_B_DIR_PIN 23

// Encoder A
#define ENCODER_A_A_PIN 4
#define ENCODER_A_B_PIN 5

// Encoder B
#define ENCODER_B_A_PIN 6
#define ENCODER_B_B_PIN 12

// Target RPM
#define TARGET_RPM 50.0

// PI Gains
#define KP 1.0
#define KI 0.1

// Anti-windup limit
#define ANTI_WINDUP_LIMIT 50.0

// Stall detection threshold (seconds)
#define STALL_THRESHOLD 2.0

// PWM frequency (Hz)
#define PWM_FREQUENCY 10000

// Global variables
volatile int encoder_a_ticks = 0;
volatile int encoder_b_ticks = 0;
volatile bool encoder_a_a_state = false;
volatile bool encoder_a_b_state = false;
volatile bool encoder_b_a_state = false;
volatile bool encoder_b_b_state = false;
volatile unsigned long last_encoder_a_a_change = 0;
volatile unsigned long last_encoder_a_b_change = 0;
volatile unsigned long last_encoder_b_a_change = 0;
volatile unsigned long last_encoder_b_b_change = 0;
volatile unsigned long last_encoder_a_a_stall_check = 0;
volatile unsigned long last_encoder_a_b_stall_check = 0;
volatile unsigned long last_encoder_b_a_stall_check = 0;
volatile unsigned long last_encoder_b_b_stall_check = 0;
volatile bool encoder_a_a_stalled = false;
volatile bool encoder_a_b_stalled = false;
volatile bool encoder_b_a_stalled = false;
volatile bool encoder_b_b_stalled = false;
volatile unsigned long last_control_loop_time = 0;
volatile bool running = true;

// Function prototypes
void encoder_a_a_isr(void);
void encoder_a_b_isr(void);
void encoder_b_a_isr(void);
void encoder_b_b_isr(void);
float calculate_rpm(int ticks);
float calculate_pid(float setpoint, float actual_value, float *integral, float *previous_error);
void set_motor_speed(int motor_pwm_pin, int motor_dir_pin, float rpm);
void stop_motors(void);
void signal_handler(int signal);
void log_message(const char *message);

// Function to log messages with timestamps
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] %s\n", timestamp, message);
}

// Interrupt service routine for Encoder A phase A
void encoder_a_a_isr(void) {
    unsigned long current_time = millis();
    if (current_time - last_encoder_a_a_change > 10) { // Debounce
        bool current_state = digitalRead(ENCODER_A_A_PIN);
        if (current_state != encoder_a_a_state) {
            encoder_a_a_state = current_state;
            last_encoder_a_a_change = current_time;
            if (encoder_a_a_state != encoder_a_b_state) {
                encoder_a_ticks++;
            } else {
                encoder_a_ticks--;
            }
        }
    }
}

// Interrupt service routine for Encoder A phase B
void encoder_a_b_isr(void) {
    unsigned long current_time = millis();
    if (current_time - last_encoder_a_b_change > 10) { // Debounce
        bool current_state = digitalRead(ENCODER_A_B_PIN);
        if (current_state != encoder_a_b_state) {
            encoder_a_b_state = current_state;
            last_encoder_a_b_change = current_time;
            if (encoder_a_a_state != encoder_a_b_state) {
                encoder_a_ticks--;
            } else {
                encoder_a_ticks++;
            }
        }
    }
}

// Interrupt service routine for Encoder B phase A
void encoder_b_a_isr(void) {
    unsigned long current_time = millis();
    if (current_time - last_encoder_b_a_change > 10) { // Debounce
        bool current_state = digitalRead(ENCODER_B_A_PIN);
        if (current_state != encoder_b_a_state) {
            encoder_b_a_state = current_state;
            last_encoder_b_a_change = current_time;
            if (encoder_b_a_state != encoder_b_b_state) {
                encoder_b_ticks++;
            } else {
                encoder_b_ticks--;
            }
        }
    }
}

// Interrupt service routine for Encoder B phase B
void encoder_b_b_isr(void) {
    unsigned long current_time = millis();
    if (current_time - last_encoder_b_b_change > 10) { // Debounce
        bool current_state = digitalRead(ENCODER_B_B_PIN);
        if (current_state != encoder_b_b_state) {
            encoder_b_b_state = current_state;
            last_encoder_b_b_change = current_time;
            if (encoder_b_a_state != encoder_b_b_state) {
                encoder_b_ticks--;
            } else {
                encoder_b_ticks++;
            }
        }
    }
}

// Function to calculate RPM
float calculate_rpm(int ticks) {
    // Assuming 64 ticks per revolution and a 1:1 encoder-to-output-shaft ratio
    return (float)ticks * 60.0 / 64.0;
}

// Function to calculate PID output
float calculate_pid(float setpoint, float actual_value, float *integral, float *previous_error) {
    float error = setpoint - actual_value;
    *integral += error;
    // Anti-windup
    if (*integral > ANTI_WINDUP_LIMIT) {
        *integral = ANTI_WINDUP_LIMIT;
    } else if (*integral < -ANTI_WINDUP_LIMIT) {
        *integral = -ANTI_WINDUP_LIMIT;
    }
    float derivative = error - *previous_error;
    float output = KP * error + KI * (*integral) + KD * derivative;
    *previous_error = error;
    return output;
}

// Function to set motor speed using PWM
void set_motor_speed(int motor_pwm_pin, int motor_dir_pin, float rpm) {
    // Clamp RPM to a reasonable range
    if (rpm < 0.0) rpm = 0.0;
    if (rpm > 100.0) rpm = 100.0;

    // Calculate PWM duty cycle (0-255)
    int duty_cycle = (int)(rpm * 2.55); // Assuming 100 RPM = 255 duty cycle

    // Set motor direction (forward)
    digitalWrite(motor_dir_pin, HIGH);

    // Set PWM duty cycle
    softPwmWrite(motor_pwm_pin, duty_cycle);
}

// Function to stop motors
void stop_motors(void) {
    softPwmWrite(MOTOR_A_PWM_PIN, 0);
    softPwmWrite(MOTOR_B_PWM_PIN, 0);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    running = false;
    log_message("Stopping motors and exiting...");
    stop_motors();
    exit(0);
}

int main(void) {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "wiringPiSetupGpio failed: %s\n", strerror(errno));
        return 1;
    }

    // Set GPIO pins as output for PWM
    pinMode(MOTOR_A_PWM_PIN, OUTPUT);
    pinMode(MOTOR_B_PWM_PIN, OUTPUT);

    // Set GPIO pins as output for motor direction
    pinMode(MOTOR_A_DIR_PIN, OUTPUT);
    pinMode(MOTOR_B_DIR_PIN, OUTPUT);

    // Set GPIO pins as input for encoder signals
    pinMode(ENCODER_A_A_PIN, INPUT);
    pinMode(ENCODER_A_B_PIN, INPUT);
    pinMode(ENCODER_B_A_PIN, INPUT);
    pinMode(ENCODER_B_B_PIN, INPUT);

    // Enable pull-up resistors on encoder pins
    pullUpDnControl(ENCODER_A_A_PIN, PUD_UP);
    pullUpDnControl(ENCODER_A_B_PIN, PUD_UP);
    pullUpDnControl(ENCODER_B_A_PIN, PUD_UP);
    pullUpDnControl(ENCODER_B_B_PIN, PUD_UP);

    // Initialize softPwm
    softPwmCreate(MOTOR_A_PWM_PIN, 0, 255);
    softPwmCreate(MOTOR_B_PWM_PIN, 0, 255);

    // Set PWM frequency
    softPwmSetClock(192); // Adjust for desired frequency (19.2 MHz / (range * clock) = frequency)

    // Initialize encoder states
    encoder_a_a_state = digitalRead(ENCODER_A_A_PIN);
    encoder_a_b_state = digitalRead(ENCODER_A_B_PIN);
    encoder_b_a_state = digitalRead(ENCODER_B_A_PIN);
    encoder_b_b_state = digitalRead(ENCODER_B_B_PIN);

    // Initialize last change times
    last_encoder_a_a_change = millis();
    last_encoder_a_b_change = millis();
    last_encoder_b_a_change = millis();
    last_encoder_b_b_change = millis();
    last_encoder_a_a_stall_check = millis();
    last_encoder_a_b_stall_check = millis();
    last_encoder_b_a_stall_check = millis();
    last_encoder_b_b_stall_check = millis();

    // Initialize PID variables
    float integral_a = 0.0;
    float previous_error_a = 0.0;
    float integral_b = 0.0;
    float previous_error_b = 0.0;

    // Set up interrupt service routines
    if (wiringPiISR(ENCODER_A_A_PIN, INT_EDGE_BOTH, &encoder_a_a_isr) < 0) {
        fprintf(stderr, "Unable to setup ISR for Encoder A A: %s\n", strerror(errno));
        return 1;
    }
    if (wiringPiISR(ENCODER_A_B_PIN, INT_EDGE_BOTH, &encoder_a_b_isr) < 0) {
        fprintf(stderr, "Unable to setup ISR for Encoder A B: %s\n", strerror(errno));
        return 1;
    }
    if (wiringPiISR(ENCODER_B_A_PIN, INT_EDGE_BOTH, &encoder_b_a_isr) < 0) {
        fprintf(stderr, "Unable to setup ISR for Encoder B A: %s\n", strerror(errno));
        return 1;
    }
    if (wiringPiISR(ENCODER_B_B_PIN, INT_EDGE_BOTH, &encoder_b_b_isr) < 0) {
        fprintf(stderr, "Unable to setup ISR for Encoder B B: %s\n", strerror(errno));
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    log_message("Motor control started");

    // Main control loop
    while (running) {
        // Read encoder ticks
        int current_encoder_a_ticks = encoder_a_ticks;
        int current_encoder_b_ticks = encoder_b_ticks;

        // Reset encoder ticks
        encoder_a_ticks = 0;
        encoder_b_ticks = 0;

        // Calculate RPM
        float rpm_a = calculate_rpm(current_encoder_a_ticks);
        float rpm_b = calculate_rpm(current_encoder_b_ticks);

        // Calculate PID output
        float pid_output_a = calculate_pid(TARGET_RPM, rpm_a, &integral_a, &previous_error_a);
        float pid_output_b = calculate_pid(TARGET_RPM, rpm_b, &integral_b, &previous_error_b);

        // Set motor speed
        set_motor_speed(MOTOR_A_PWM_PIN, MOTOR_A_DIR_PIN, pid_output_a);
        set_motor_speed(MOTOR_B_PWM_PIN, MOTOR_B_DIR_PIN, pid_output_b);

        // Print RPM and PWM duty cycle
        printf("Motor A: RPM = %.2f, PWM = %.2f\n", rpm_a, pid_output_a);
        printf("Motor B: RPM = %.2f, PWM = %.2f\n", rpm_b, pid_output_b);

        // Stall detection
        unsigned long current_time = millis();
        if (current_encoder_a_ticks == 0 && current_time - last_encoder_a_a_stall_check > STALL_THRESHOLD * 1000) {
            log_message("Motor A stalled!");
            stop_motors();
            running = false; // Stop the program after stall
        }
        if (current_encoder_b_ticks == 0 && current_time - last_encoder_b_a_stall_check > STALL_THRESHOLD * 1000) {
            log_message("Motor B stalled!");
            stop_motors();
            running = false; // Stop the program after stall
        }

        // Wait for 100ms
        delay(100);
    }

    // Stop motors
    stop_motors();

    log_message("Motor control stopped");

    return 0;
}

