#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define GPIO_RELAY 17
#define DUSK_LUX 50.0
#define DAWN_LUX 200.0
#define LOG_FILE "chicken_coop_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
float read_lux();
void control_relay(int state);
void log_data(float lux, int relay_state);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read lux value from BH1750 sensor
float read_lux() {
    char config_mode = 0x10; // Continuous high resolution mode
    int result;

    result = i2cWriteByteData(i2c_handle, 0x00, config_mode);
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1.0;
    }

    gpioDelay(180000); // Wait 180ms

    result = i2cReadWordData(i2c_handle, 0x00);
    if (result < 0) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1.0;
    }

    unsigned int raw_value = (result >> 8) | (result << 8); // Swap bytes
    float lux = (float)raw_value / 1.2;
    return lux;
}

// Control the relay (ON/OFF)
void control_relay(int state) {
    gpioWrite(GPIO_RELAY, state);
}

// Log data to file
void log_data(float lux, int relay_state) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    const char *relay_status = (relay_state == 1) ? "ON" : "OFF";

    fprintf(log_file, "%s: Lux = %.2f, Relay = %s\n", timestamp, lux, relay_status);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    control_relay(0); // Turn off relay
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO_RELAY as output
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int relay_state = 0; // 0 = OFF, 1 = ON
    float lux;

    printf("Monitoring ambient light and controlling relay...\n");

    while (!terminate) {
        lux = read_lux();

        if (lux < 0) {
            fprintf(stderr, "Error reading lux value, retrying...\n");
            log_data(-1.0, relay_state); // Log error
            gpioDelay(1000000); // Wait 1 second before retrying
            continue;
        }

        if (lux < DUSK_LUX && relay_state == 0) {
            control_relay(1);
            relay_state = 1;
            log_data(lux, relay_state);
            printf("Dusk detected, turning relay ON\n");
        } else if (lux > DAWN_LUX && relay_state == 1) {
            control_relay(0);
            relay_state = 0;
            log_data(lux, relay_state);
            printf("Dawn detected, turning relay OFF\n");
        } else {
            log_data(lux, relay_state);
        }

        gpioDelay(5000000); // Wait 5 seconds
    }

    cleanup();
    return 0;
}

