// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variable to store the relay state
static volatile int relay_state = 0;

// Function prototypes
int read_touch_sensor();
int debounce_touch();
int toggle_relay();
int log_relay_state(int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, turning relay OFF and exiting...\n");
        gpioWrite(RELAY_PIN, 0); // Turn relay OFF
        gpioTerminate(); // Terminate pigpio
        exit(0);
    }
}

// Function to read the touch sensor
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to debounce the touch sensor
int debounce_touch() {
    int i;
    for (i = 0; i < 5; i++) {
        if (read_touch_sensor() == 0) {
            return 0; // Not stable
        }
        gpioDelay(DEBOUNCE_DELAY * 1000); // Delay in microseconds
    }
    return 1; // Stable
}

// Function to toggle the relay state
int toggle_relay() {
    relay_state = !relay_state;
    return gpioWrite(RELAY_PIN, relay_state);
}

// Function to log the relay state with timestamp
int log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    printf("%s Relay is %s\n", timestamp, state ? "ON" : "OFF");
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Set initial relay state to OFF
    gpioWrite(RELAY_PIN, 0);
    relay_state = 0;

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Touch-activated relay control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        if (read_touch_sensor() == 1) {
            if (debounce_touch()) {
                if (toggle_relay() != 0) {
                    fprintf(stderr, "Error writing to relay pin\n");
                }
                log_relay_state(relay_state);
                while (read_touch_sensor() == 1) {
                    gpioDelay(10000); // Small delay to prevent busy-waiting
                }
            }
        }
        gpioDelay(10000); // Sleep for 10 milliseconds
    }

    return 0;
}

