#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

// Define GPIO pins
#define FLOW_SENSOR_PIN 17
#define SOLENOID_PIN 27

// Define constants
#define PULSES_PER_LITER 450.0
#define FLOW_THRESHOLD_HIGH 5.0
#define FLOW_THRESHOLD_LOW 4.5
#define DEBOUNCE_TIME_MS 1000
#define SAMPLE_INTERVAL_S 1

// Global variables
volatile int pulse_count = 0;
pthread_mutex_t pulse_mutex;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data);
float calculate_lpm(int pulses);
void control_solenoid(float lpm);
void log_data(float lpm, int solenoid_state);
void signal_handler(int signal);
int initialize();
void cleanup();

// Interrupt service routine for the flow sensor
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == 1) { // Rising edge detected
        pthread_mutex_lock(&pulse_mutex);
        pulse_count++;
        pthread_mutex_unlock(&pulse_mutex);
    }
}

// Function to calculate LPM from pulse count
float calculate_lpm(int pulses) {
    return (float)pulses / PULSES_PER_LITER * 60.0;
}

// Function to control the solenoid based on LPM
void control_solenoid(float lpm) {
    static int solenoid_state = 1; // 1 = open, 0 = closed
    static uint32_t last_debounce_time = 0;
    uint32_t current_time = gpioTick();

    if (lpm > FLOW_THRESHOLD_HIGH && solenoid_state == 1) {
        // Debounce the signal
        if (current_time - last_debounce_time > DEBOUNCE_TIME_MS * 1000) {
            gpioWrite(SOLENOID_PIN, 0); // Close the solenoid
            solenoid_state = 0;
            log_data(-1.0, solenoid_state); // Log the event
            last_debounce_time = current_time;
        }
    } else if (lpm < FLOW_THRESHOLD_LOW && solenoid_state == 0) {
        // Debounce the signal
        if (current_time - last_debounce_time > DEBOUNCE_TIME_MS * 1000) {
            gpioWrite(SOLENOID_PIN, 1); // Open the solenoid
            solenoid_state = 1;
            log_data(-1.0, solenoid_state); // Log the event
            last_debounce_time = current_time;
        }
    }
}

// Function to log data to a file
void log_data(float lpm, int solenoid_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        if (lpm >= 0) {
            fprintf(log_file, "%s, LPM: %.2f\n", timestamp, lpm);
        } else {
            fprintf(log_file, "%s, Solenoid: %s\n", timestamp, solenoid_state ? "Open" : "Closed");
        }
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

