        fprintf(stderr, "Error: pigpio initialisation failed for API call\n");
        return -1;
    }
    return 0;
}

// Read HX711 value
int read_hx711() {
    int i;
    int data = 0;
    int attempts = 0;

    // Wait for DATA pin to go low (sensor ready)
    while (gpioRead(hx711_data_pin) == 1 && attempts < timeout_us) {
        gpioDelay(1); // Wait 1 us
        attempts++;
    }

    if (attempts >= timeout_us) {
        fprintf(stderr, "Error: HX711 timeout waiting for data pin to go low\n");
        return -1;
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(hx711_sck_pin, 1);
        gpioDelay(1); // Clock pulse width
        data = data << 1;
        if (gpioRead(hx711_data_pin)) {
            data++;
        }
        gpioWrite(hx711_sck_pin, 0);
        gpioDelay(1); // Clock pulse width
    }

    // Apply the 25th clock pulse for gain selection (Channel A, gain 128)
    gpioWrite(hx711_sck_pin, 1);
    gpioDelay(1); // Clock pulse width
    gpioWrite(hx711_sck_pin, 0);
    gpioDelay(1); // Clock pulse width

    // Convert to signed 2's complement
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Calibrate weight
double calibrate_weight(int raw_value) {
    return (double)raw_value / calibration_factor;
}

// Set servo pulse width
int set_servo_pulse_width(int pulse_width) {
    if (pulse_width < 1000 || pulse_width > 2000) {
        fprintf(stderr, "Error: Invalid pulse width: %d. Must be between 1000 and 2000\n", pulse_width);
        return -1;
    }

    gpioServo(servo_pin, pulse_width);
    return 0;
}

// Dispense ingredient
int dispense_ingredient(double target_weight) {
    int raw_value = read_hx711();
    if (raw_value == -1) {
        return -1;
    }

    double actual_weight = calibrate_weight(raw_value);

    // Map target weight to pulse width (1000-2000)
    int pulse_width = (int)(1000 + (target_weight / actual_weight) * 1000); // Assuming target_weight <= actual_weight
    if (pulse_width < 1000) pulse_width = 1000;
    if (pulse_width > 2000) pulse_width = 2000;

    if (set_servo_pulse_width(pulse_width) == -1) {
        return -1;
    }

    return 0;
}

// Send weight to client
int send_weight_to_client(int client_socket, double actual_weight) {
    char buffer[64];
    snprintf(buffer, sizeof(buffer), "%.2f", actual_weight);
    if (send(client_socket, buffer, strlen(buffer), 0) < 0) {
        perror("Error sending weight to client");
        return -1;
    }
    return 0;
}

// Log dispensing event
int log_dispensing_event(double target_weight, double actual_weight, const char *error_message) {
    json_t *root = json_object();
    json_object_set_new(root, "timestamp", json_string(NULL)); // Placeholder for timestamp
    json_object_set_new(root, "target_weight", json_real(target_weight));
    json_object_set_new(root, "actual_weight", json_real(actual_weight));
    json_object_set_new(root, "error_message", json_string(error_message));

    // Get current timestamp
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tstruct);
    json_object_set_new(root, "timestamp", json_string(timestamp));

    // Append to log file
    FILE *fp = fopen("dispensing_log.json", "a");
    if (fp == NULL) {
        perror("Error opening dispensing_log.json");
        json_decref(root);
        return -1;
    }

    char *json_str = json_dumps(root, JSON_INDENT(4));
    if (json_str == NULL) {
        fprintf(stderr, "Error: Failed to serialize JSON\n");
        fclose(fp);
        json_decref(root);
        return -1;
    }

    fprintf(fp, "%s\n", json_str);
    fclose(fp);
    free(json_str);
    json_decref(root);

    return 0;
}

// Handle client connection
int handle_client(int client_socket) {
    char buffer[64];
    ssize_t bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received < 0) {
        perror("Error receiving data from client");
        return -1;
    }
    buffer[bytes_received] = '\0';

    double target_weight = atof(buffer);
    printf("Received target weight: %.2f\n", target_weight);

    if (dispense_ingredient(target_weight) == -1) {
        fprintf(stderr, "Error: Dispensing failed\n");
        log_dispensing_event(target_weight, 0.0, "Dispensing failed");
        send_weight_to_client(client_socket, 0.0); // Send 0.0 as error indicator
        return -1;
    }

    gpioDelay(stabilization_delay_s * 1000000); // Wait for stabilization

    int raw_value = read_hx711();
    if (raw_value == -1) {
        fprintf(stderr, "Error: Failed to read weight after dispensing\n");
        log_dispensing_event(target_weight, 0.0, "Failed to read weight after dispensing");
        send_weight_to_client(client_socket, 0.0); // Send 0.0 as error indicator
        return -1;
    }

    double actual_weight = calibrate_weight(raw_value);
    printf("Actual weight: %.2f\n", actual_weight);

    if (send_weight_to_client(client_socket, actual_weight) == -1) {
        fprintf(stderr, "Error: Failed to send weight to client\n");
        log_dispensing_event(target_weight, actual_weight, "Failed to send weight to client");
        return -1;
    }

    log_dispensing_event(target_weight, actual_weight, "Success");

    return 0;
}

// Create TCP server
int create_tcp_server() {
    int server_socket, client_socket;
    struct sockaddr_in server_address, client_address;
    socklen_t client_address_len = sizeof(client_address);

    // Create socket
    server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket == -1) {
        perror("Error creating socket");
        return -1;
    }

    // Configure server address
    server_address.sin_family = AF_INET;
    server_address.sin_addr.s_addr = inet_addr(tcp_ip);
    server_address.sin_port = htons(tcp_port);

    // Bind socket to address
    if (bind(server_socket, (struct sockaddr *)&server_address, sizeof(server_address)) < 0) {
        perror("Error binding socket");
        close(server_socket);
        return -1;
    }

    // Listen for connections
    if (listen(server_socket, 5) < 0) {
        perror("Error listening on socket");
        close(server_socket);
        return -1;
    }

    printf("Listening on %s:%d...\n", tcp_ip, tcp_port);

    // Accept connections
    while (running) {
        client_socket = accept(server_socket, (struct sockaddr *)&client_address, &client_address_len);
        if (client_socket < 0) {
            perror("Error accepting connection");
            continue; // Continue listening for other connections
        }

        printf("Connection accepted from %s:%d\n", inet_ntoa(client_address.sin_addr), ntohs(client_address.sin_port));

        if (handle_client(client_socket) == -1) {
            fprintf(stderr, "Error handling client\n");
        }

        close(client_socket);
    }

    close(server_socket);
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Load configuration
    if (load_configuration() == -1) {
        fprintf(stderr, "Using default configuration values.\n");
    }

    // Initialize GPIO
    if (initialize_gpio() == -1) {
        return 1;
    }

    // Initialize API call
    if (initialize_api_call() == -1) {
        gpioTerminate();
        return 1;
    }

    // Create TCP server
    if (create_tcp_server() == -1) {
        gpioTerminate();
        return 1;
    }

    // Cleanup
    gpioTerminate();
    printf("Exiting.\n");
    return 0;
}

