int initialize_gpio();
int read_touch_sensor();
int debounce_touch_sensor(int interval_ms);
int toggle_relay();
int log_relay_state(int state);
void signal_handler(int signal);
void cleanup();

// Structure to hold GPIO configuration
typedef struct {
    int touch_pin;
    int relay_pin;
} gpio_config_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    return 0;
}

// Function to read the touch sensor
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to debounce the touch sensor
int debounce_touch_sensor(int interval_ms) {
    gpioDelay(interval_ms * 1000); // Convert milliseconds to microseconds
    return read_touch_sensor();
}

// Function to toggle the relay state
int toggle_relay() {
    relay_state = !relay_state;
    gpioWrite(RELAY_PIN, relay_state);
    return relay_state;
}

// Function to log the relay state with timestamp
int log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (state == 1) {
        printf("%s Relay: ON\n", timestamp);
    } else {
        printf("%s Relay: OFF\n", timestamp);
    }

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(RELAY_PIN, 0); // Turn off relay
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        if (strcmp(argv[1], "-d") == 0 && argc > 2) {
            debounce_interval = atoi(argv[2]);
            if (debounce_interval <= 0) {
                fprintf(stderr, "Invalid debounce interval. Using default value (%d ms).\n", DEFAULT_DEBOUNCE_INTERVAL);
                debounce_interval = DEFAULT_DEBOUNCE_INTERVAL;
            }
        } else {
            fprintf(stderr, "Usage: %s [-d <milliseconds>]\n", argv[0]);
            return 1;
        }
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Touch sensor monitoring started. Debounce interval: %d ms\n", debounce_interval);

    // Main loop
    while (running) {
        int touch_detected = (read_touch_sensor() == 0); // Assuming LOW signal indicates touch

        if (touch_detected) {
            if (debounce_touch_sensor(debounce_interval) == 0) {
                toggle_relay();
                log_relay_state(relay_state);
            }
        }

        gpioDelay(1000); // Check every 1 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

