#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <termios.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

// Define GPIO pin for servo
#define SERVO_PIN 18

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 50

// Define pulse width range (us)
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500

// Define initial pulse width (us)
#define INITIAL_PULSE_WIDTH 1500

// Define angle increment/decrement (degrees)
#define ANGLE_INCREMENT 10

// Global variable to store the current pulse width
static volatile int current_pulse_width = INITIAL_PULSE_WIDTH;

// Global variable to store the terminal settings
static struct termios original_termios;

// Function prototypes
int set_servo_pulse_width(int gpio, int pulse_width);
int get_terminal_settings(struct termios *termios);
int set_terminal_settings(const struct termios *termios);
void signal_handler(int signal);

// Function to set the servo pulse width using pigpio
int set_servo_pulse_width(int gpio, int pulse_width) {
    if (gpioPWM(gpio, pulse_width) != 0) {
        fprintf(stderr, "Error: Failed to set servo pulse width on GPIO %d: %s\n", gpio, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to get the current terminal settings
int get_terminal_settings(struct termios *termios) {
    if (tcgetattr(STDIN_FILENO, termios) != 0) {
        fprintf(stderr, "Error: Failed to get terminal settings: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to set the terminal settings
int set_terminal_settings(const struct termios *termios) {
    if (tcsetattr(STDIN_FILENO, TCSANOW, termios) != 0) {
        fprintf(stderr, "Error: Failed to set terminal settings: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, stopping servo and exiting...\n", signal);
    if (set_servo_pulse_width(SERVO_PIN, 0) != 0) {
        fprintf(stderr, "Error stopping servo.\n");
    }
    if (set_terminal_settings(&original_termios) != 0) {
        fprintf(stderr, "Error restoring terminal settings.\n");
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(SERVO_PIN, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(SERVO_PIN, 255);

    // Set initial pulse width
    if (set_servo_pulse_width(SERVO_PIN, current_pulse_width) != 0) {
        gpioTerminate();
        return 1;
    }

    // Get the current terminal settings
    if (get_terminal_settings(&original_termios) != 0) {
        gpioTerminate();
        return 1;
    }

    // Set terminal to raw mode
    struct termios raw_termios = original_termios;
    raw_termios.c_lflag &= ~(ICANON | ECHO);
    raw_termios.c_cc[VMIN] = 0;  // Non-blocking read
    raw_termios.c_cc[VTIME] = 0; // No timeout

    if (set_terminal_settings(&raw_termios) != 0) {
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Servo control program. Press '+' to increase angle, '-' to decrease, 'q' to quit.\n");

    // Main loop
    while (1) {
        char ch;
        ssize_t bytes_read = read(STDIN_FILENO, &ch, 1);

        if (bytes_read > 0) {
            switch (ch) {
                case '+':
                    current_pulse_width += ANGLE_INCREMENT * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) / 180; // Scale angle to pulse width
                    if (current_pulse_width > MAX_PULSE_WIDTH) {
                        current_pulse_width = MAX_PULSE_WIDTH;
                    }
                    break;
                case '-':
                    current_pulse_width -= ANGLE_INCREMENT * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) / 180; // Scale angle to pulse width
                    if (current_pulse_width < MIN_PULSE_WIDTH) {
                        current_pulse_width = MIN_PULSE_WIDTH;
                    }
                    break;
                case 'q':
                    signal_handler(SIGINT); // Simulate Ctrl+C to exit gracefully
                    break;
                default:
                    // Ignore other characters
                    break;
            }

            // Set the servo pulse width
            if (set_servo_pulse_width(SERVO_PIN, current_pulse_width) != 0) {
                fprintf(stderr, "Error setting servo pulse width.\n");
            }

            // Calculate and print the current angle
            float angle = (float)(current_pulse_width - MIN_PULSE_WIDTH) * 180.0 / (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH);
            printf("Angle: %.2f degrees\n", angle);
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from terminal: %s\n", strerror(errno));
            break;
        }
    }

    // Restore terminal settings and terminate pigpio (should not reach here if signal handler works)
    set_terminal_settings(&original_termios);
    gpioTerminate();

    return 0;
}

