#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_MS 2
#define LOG_FILE "motor_rpm.log"
#define SAMPLE_INTERVAL_SEC 5

static volatile int running = 1;
static FILE *log_file = NULL;
static int pulse_count = 0;
static struct timespec last_pulse_time;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for timestamp.\n");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log the RPM data to a file
int log_rpm_data(const char *timestamp, double rpm) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, rpm);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Callback function for GPIO interrupts
void pulse_callback(int gpio, int level, uint32_t tick) {
    struct timespec current_time;
    clock_gettime(CLOCK_MONOTONIC, &current_time);

    // Debounce the signal
    double time_diff_ms = (current_time.tv_sec - last_pulse_time.tv_sec) * 1000.0 +
                          (current_time.tv_nsec - last_pulse_time.tv_nsec) / 1000000.0;

    if (time_diff_ms < DEBOUNCE_MS) {
        return; // Ignore the pulse
    }

    last_pulse_time = current_time;
    pulse_count++;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input with pull-up resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize last pulse time
    clock_gettime(CLOCK_MONOTONIC, &last_pulse_time);

    // Set up interrupt callback for rising edge detection
    if (gpioSetAlertFuncEx(GPIO_PIN, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set alert function for GPIO %d\n", GPIO_PIN);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    struct timespec start_time, current_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    // Main loop
    while (running) {
        sleep(SAMPLE_INTERVAL_SEC);

        clock_gettime(CLOCK_MONOTONIC, &current_time);
        double elapsed_time_sec = (current_time.tv_sec - start_time.tv_sec) +
                                  (current_time.tv_nsec - start_time.tv_nsec) / 1000000000.0;

        // Calculate RPM
        double rpm = (double)pulse_count / elapsed_time_sec * 60.0;

        // Get timestamp
        char *timestamp = get_iso8601_timestamp();
        if (timestamp == NULL) {
            fprintf(stderr, "Error: Failed to get timestamp.\n");
            running = 0; // Exit loop on error
            continue;
        }

        // Log RPM data
        if (log_rpm_data(timestamp, rpm) != 0) {
            fprintf(stderr, "Error: Failed to log RPM data.\n");
        }

        // Print RPM to stdout
        printf("RPM: %.2f\n", rpm);

        // Reset pulse count and start time
        pulse_count = 0;
        clock_gettime(CLOCK_MONOTONIC, &start_time);
        free(timestamp);
    }

    // Cleanup
    gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL); // Disable callback
    fclose(log_file);
    gpioTerminate();

    return 0;
}

