#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Define constants
#define DEBOUNCE_DELAY_MS 50
#define CONTINUOUS_HIGH_THRESHOLD_S 10

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_touch_sensor();
void control_relay(int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the touch sensor
int read_touch_sensor() {
    int sensor_value = gpioRead(TOUCH_SENSOR_PIN);
    if (sensor_value < 0) {
        fprintf(stderr, "Error reading touch sensor: %d\n", sensor_value);
        return -1; // Indicate an error
    }
    return sensor_value;
}

// Function to control the relay
void control_relay(int state) {
    int result = gpioWrite(RELAY_PIN, state);
    if (result < 0) {
        fprintf(stderr, "Error writing to relay: %d\n", result);
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Initialize relay to OFF state
    control_relay(0);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Touch sensor relay control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int sensor_value = read_touch_sensor();
        if (sensor_value < 0) {
            // Error reading sensor, exit loop
            break;
        }

        if (sensor_value == 1) {
            // Touch detected
            static int relay_state = 0; // Keep track of relay state
            static time_t last_touch_time = 0;
            time_t current_time = time(NULL);

            if (difftime(current_time, last_touch_time) >= (DEBOUNCE_DELAY_MS / 1000.0)) {
                // Debounce delay passed
                if (relay_state == 0) {
                    // Toggle relay state
                    relay_state = 1;
                    control_relay(relay_state);
                    printf("Relay ON\n");
                } else {
                    // Toggle relay state
                    relay_state = 0;
                    control_relay(relay_state);
                    printf("Relay OFF\n");
                }

                last_touch_time = current_time;

                // Check for continuous HIGH state
                if (relay_state == 1) {
                    static time_t continuous_high_start_time = 0;
                    if (continuous_high_start_time == 0) {
                        continuous_high_start_time = current_time;
                    }

                    if (difftime(current_time, continuous_high_start_time) >= CONTINUOUS_HIGH_THRESHOLD_S) {
                        // Continuous HIGH state exceeded threshold
                        printf("Continuous HIGH state detected for %d seconds. Disabling relay.\n", CONTINUOUS_HIGH_THRESHOLD_S);
                        control_relay(0); // Turn relay OFF
                        relay_state = 0; // Update relay state
                        continuous_high_start_time = 0; // Reset timer
                    }
                } else {
                    // Reset continuous HIGH timer if relay is OFF
                    static time_t continuous_high_start_time = 0;
                    continuous_high_start_time = 0;
                }
            }
        } else {
            // No touch detected
            // Reset continuous HIGH timer if no touch is detected
            static time_t continuous_high_start_time = 0;
            continuous_high_start_time = 0;
        }

        gpioDelay(1000); // Delay for 1ms (adjust as needed)
    }

    // Cleanup
    control_relay(0); // Ensure relay is OFF on exit
    gpioTerminate(); // Terminate pigpio

    printf("Program terminated.\n");
    return 0;
}

