double calculate_flow_rate(int pulses)
{
    double flow_rate = (double)pulses / PULSES_PER_LITER * 60000.0 / SAMPLE_INTERVAL_MS; // L/min
    return flow_rate;
}

// Function to set valve position using proportional control
int set_valve_position(double flow_rate, double target_flow_rate)
{
    double error = target_flow_rate - flow_rate;
    double duty_cycle = KP * error;

    // Clamp duty cycle to 0-255 range
    if (duty_cycle < 0)
    {
        duty_cycle = 0;
    }
    else if (duty_cycle > 255)
    {
        duty_cycle = 255;
    }

    return (int)duty_cycle;
}

// Function to log data to CSV file
void log_data(double flow_rate, int valve_position)
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

    if (log_file != NULL)
    {
        fprintf(log_file, "%ld,%.2f,%d\n", timestamp_ms, flow_rate, valve_position);
        fflush(log_file); // Ensure data is written to disk immediately
    }
    else
    {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Initialization function
int initialize()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(VALVE_PWM_PIN, PI_OUTPUT);
    gpioSetMode(VALVE_ENABLE_PIN, PI_OUTPUT);
    gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(VALVE_PWM_PIN, PWM_FREQUENCY);

    // Enable valve
    gpioWrite(VALVE_ENABLE_PIN, 1);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL)
    {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Register interrupt handler
    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, pulse_counter, NULL) != 0)
    {
        fprintf(stderr, "Error: Could not register interrupt handler\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup function
void cleanup()
{
    // Disable valve
    gpioWrite(VALVE_ENABLE_PIN, 0);

    // Set PWM duty cycle to 0
    gpioPWM(VALVE_PWM_PIN, 0);

    // Close log file
    if (log_file != NULL)
    {
        fclose(log_file);
    }

    // Terminate pigpio library
    gpioTerminate();
}

int main(int argc, char *argv[])
{
    // Parse command-line arguments
    if (argc != 3)
    {
        fprintf(stderr, "Usage: %s -t <target_flow_rate>\n", argv[0]);
        return 1;
    }

    if (strcmp(argv[1], "-t") == 0)
    {
        target_flow_rate = atof(argv[2]);
        if (target_flow_rate <= 0)
        {
            fprintf(stderr, "Error: Invalid target flow rate. Must be a positive number.\n");
            return 1;
        }
    }
    else
    {
        fprintf(stderr, "Error: Invalid command-line arguments.\n");
        return 1;
    }

    // Initialize
    if (initialize())
    {
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Flow control started. Target flow rate: %.2f L/min\n", target_flow_rate);

    // Main loop
    while (running)
    {
        // Reset pulse count
        pulse_count = 0;

        // Wait for the sample interval
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds

        // Calculate flow rate
        double flow_rate = calculate_flow_rate(pulse_count);

        // Set valve position
        int valve_position = set_valve_position(flow_rate, target_flow_rate);

        // Set PWM duty cycle
        gpioPWM(VALVE_PWM_PIN, valve_position);

        // Log data
        log_data(flow_rate, valve_position);

        printf("Flow rate: %.2f L/min, Valve position: %d\n", flow_rate, valve_position);
    }

    // Cleanup and exit
    cleanup();
    printf("Flow control stopped.\n");
    return 0;
}

