#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>
#include <math.h>

// Motor 1 GPIO pins
#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25

// Motor 2 GPIO pins
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20

// Encoder 1 GPIO pins
#define ENCODER1_A 5
#define ENCODER1_B 6

// Encoder 2 GPIO pins
#define ENCODER2_A 26
#define ENCODER2_B 19

// PID parameters
#define KP 1.0
#define KI 0.1
#define KD 0.01

// Target speed (RPM)
#define TARGET_SPEED 60.0

// PWM frequency (Hz)
#define PWM_FREQUENCY 100.0

// Sample time (ms)
#define SAMPLE_TIME 100

// Global variables
volatile int encoder1_count = 0;
volatile int encoder2_count = 0;
double last_encoder1_count = 0.0;
double last_encoder2_count = 0.0;
double last_time = 0.0;
FILE *log_file = NULL;
pthread_mutex_t encoder_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
void encoder1_callback(int gpio, int level, uint32_t tick, void *user);
void encoder2_callback(int gpio, int level, uint32_t tick, void *user);
double calculate_rpm(double encoder_count, double time_diff);
double pid_control(double setpoint, double actual_speed, double *integral, double *previous_error);
void set_motor_speed(int motor_number, double duty_cycle);
void *encoder_monitor(void *arg);
void signal_handler(int signal);
int initialize_gpio();
void cleanup();

// Encoder callback function for Motor 1
void encoder1_callback(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; // unused
    (void)level; // unused
    (void)tick;  // unused
    (void)user;  // unused

    pthread_mutex_lock(&encoder_mutex);
    if (gpioRead(ENCODER1_B) == 1) {
        encoder1_count++;
    } else {
        encoder1_count--;
    }
    pthread_mutex_unlock(&encoder_mutex);
}

// Encoder callback function for Motor 2
void encoder2_callback(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; // unused
    (void)level; // unused
    (void)tick;  // unused
    (void)user;  // unused

    pthread_mutex_lock(&encoder_mutex);
    if (gpioRead(ENCODER2_B) == 1) {
        encoder2_count++;
    } else {
        encoder2_count--;
    }
    pthread_mutex_unlock(&encoder_mutex);
}

// Function to calculate RPM
double calculate_rpm(double encoder_count, double time_diff) {
    return (encoder_count / 360.0) * (60.0 / (time_diff / 1000.0));
}

// PID control function
double pid_control(double setpoint, double actual_speed, double *integral, double *previous_error) {
    double error = setpoint - actual_speed;
    *integral += error * SAMPLE_TIME / 1000.0;
    double derivative = (error - *previous_error) / SAMPLE_TIME * 1000.0;
    double output = KP * error + KI * (*integral) + KD * derivative;
    *previous_error = error;
    return output;
}

// Function to set motor speed using PWM
void set_motor_speed(int motor_number, double duty_cycle) {
    int ena_pin, in1_pin, in2_pin;

    if (motor_number == 1) {
        ena_pin = MOTOR1_ENA;
        in1_pin = MOTOR1_IN1;
        in2_pin = MOTOR1_IN2;
    } else if (motor_number == 2) {
        ena_pin = MOTOR2_ENB;
        in1_pin = MOTOR2_IN3;
        in2_pin = MOTOR2_IN4;
    } else {
        fprintf(stderr, "Error: Invalid motor number: %d\n", motor_number);
        return;
    }

    if (duty_cycle > 0) {
        gpioWrite(in1_pin, 1);
        gpioWrite(in2_pin, 0);
    } else if (duty_cycle < 0) {
        gpioWrite(in1_pin, 0);
        gpioWrite(in2_pin, 1);
        duty_cycle = -duty_cycle; // Make duty cycle positive for PWM
    } else {
        gpioWrite(in1_pin, 0);
        gpioWrite(in2_pin, 0);
        gpioPWM(ena_pin, 0); // Stop PWM
        return;
    }

    int pwm_value = (int)(duty_cycle * 255.0 / 100.0); // Scale duty cycle to PWM range (0-255)
    if (pwm_value > 255) pwm_value = 255;
    if (pwm_value < 0) pwm_value = 0;

    gpioPWM(ena_pin, pwm_value);
}

// Encoder monitoring thread function
void *encoder_monitor(void *arg) {
    (void)arg; // unused
    double current_time, time_diff, rpm1, rpm2;
    double integral1 = 0.0, previous_error1 = 0.0;
    double integral2 = 0.0, previous_error2 = 0.0;
    double pid_output1, pid_output2;

    while (1) {
        gpioDelay(SAMPLE_TIME * 1000); // Delay for the sample time

        pthread_mutex_lock(&encoder_mutex);
        double current_encoder1_count = (double)encoder1_count;
        double current_encoder2_count = (double)encoder2_count;
        pthread_mutex_unlock(&encoder_mutex);

        current_time = time_time();
        time_diff = current_time - last_time;

        rpm1 = calculate_rpm(current_encoder1_count - last_encoder1_count, time_diff);
        rpm2 = calculate_rpm(current_encoder2_count - last_encoder2_count, time_diff);

        pid_output1 = pid_control(TARGET_SPEED, rpm1, &integral1, &previous_error1);
        pid_output2 = pid_control(TARGET_SPEED, rpm2, &integral2, &previous_error2);

        // Clamp PID output to 0-100%
        if (pid_output1 > 100.0) pid_output1 = 100.0;
        if (pid_output1 < -100.0) pid_output1 = -100.0;
        if (pid_output2 > 100.0) pid_output2 = 100.0;
        if (pid_output2 < -100.0) pid_output2 = -100.0;

        set_motor_speed(1, pid_output1);
        set_motor_speed(2, pid_output2);

        // Log data to file
        fprintf(log_file, "%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
                current_time, rpm1, pid_output1, KP, KI, KD, rpm2, pid_output2, TARGET_SPEED);
        fflush(log_file);

        last_encoder1_count = current_encoder1_count;
        last_encoder2_count = current_encoder2_count;
        last_time = current_time;
    }

    return NULL;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, stopping motors and cleaning up...\n", signal);
    set_motor_speed(1, 0.0);
    set_motor_speed(2, 0.0);
    cleanup();
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Motor 1 pins
    gpioSetMode(MOTOR1_ENA, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN2, PI_OUTPUT);

    // Motor 2 pins
    gpioSetMode(MOTOR2_ENB, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN4, PI_OUTPUT);

    // Encoder 1 pins
    gpioSetMode(ENCODER1_A, PI_INPUT);
    gpioSetMode(ENCODER1_B, PI_INPUT);
    gpioSetPullUpDown(ENCODER1_A, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER1_B, PI_PUD_UP);
    gpioSetAlertFuncEx(ENCODER1_A, encoder1_callback, NULL);

    // Encoder 2 pins
    gpioSetMode(ENCODER2_A, PI_INPUT);
    gpioSetMode(ENCODER2_B, PI_INPUT);
    gpioSetPullUpDown(ENCODER2_A, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER2_B, PI_PUD_UP);
    gpioSetAlertFuncEx(ENCODER2_A, encoder2_callback, NULL);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR1_ENA, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR2_ENB, PWM_FREQUENCY);

    return 0;
}

// Cleanup function
void cleanup() {
    // Stop motors
    set_motor_speed(1, 0.0);
    set_motor_speed(2, 0.0);

    // Release GPIO pins
    gpioSetMode(MOTOR1_ENA, PI_INPUT);
    gpioSetMode(MOTOR1_IN1, PI_INPUT);
    gpioSetMode(MOTOR1_IN2, PI_INPUT);
    gpioSetMode(MOTOR2_ENB, PI_INPUT);
    gpioSetMode(MOTOR2_IN3, PI_INPUT);
    gpioSetMode(MOTOR2_IN4, PI_INPUT);
    gpioSetMode(ENCODER1_A, PI_INPUT);
    gpioSetMode(ENCODER1_B, PI_INPUT);
    gpioSetMode(ENCODER2_A, PI_INPUT);
