#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define LOG_FILE "relay_log.txt"

// MPR121 Registers
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_SOFTRESET 0x80

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int mpr121_init();
int read_touch_status(uint16_t *touch_status);
void control_relay(int state);
void log_event(const char *message);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the MPR121 sensor
int mpr121_init() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, MPR121_SOFTRESET, 0x63) < 0) {
        log_event("Error: Soft reset failed");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure electrode sensitivity and release thresholds
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, 0x41 + (i * 2), 0x30) < 0) { // Touch threshold
            log_event("Error: Touch threshold write failed");
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, 0x42 + (i * 2), 0x10) < 0) { // Release threshold
            log_event("Error: Release threshold write failed");
            return -1;
        }
    }

    // Configure filtering parameters (example values)
    if (i2cWriteByteData(i2c_handle, 0x2B, 0x01) < 0) { // MHD_R
        log_event("Error: MHD_R write failed");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x2C, 0x01) < 0) { // NHD_R
        log_event("Error: NHD_R write failed");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x2D, 0x00) < 0) { // NCL_R
        log_event("Error: NCL_R write failed");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x2E, 0x00) < 0) { // FDL_R
        log_event("Error: FDL_R write failed");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, 0x2F, 0x01) < 0) { // MHD_T
        log_event("Error: MHD_T write failed");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x30, 0x01) < 0) { // NHD_T
        log_event("Error: NHD_T write failed");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x31, 0x00) < 0) { // NCL_T
        log_event("Error: NCL_T write failed");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x32, 0x00) < 0) { // FDL_T
        log_event("Error: FDL_T write failed");
        return -1;
    }

    // Enable electrodes
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG, 0x0C) < 0) {
        log_event("Error: Electrode config write failed");
        return -1;
    }

    // Enable run mode
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG, 0x10) < 0) {
        log_event("Error: Run mode enable failed");
        return -1;
    }

    log_event("MPR121 initialized successfully");
    return 0;
}

// Read the touch status from the MPR121
int read_touch_status(uint16_t *touch_status) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, buf, 2) != 2) {
        log_event("Error: Failed to read touch status");
        return -1;
    }

    *touch_status = ((uint16_t)buf[1] << 8) | (uint16_t)buf[0];
    return 0;
}

// Control the relay state
void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
    char message[100];
    snprintf(message, sizeof(message), "Relay set to %s", state ? "HIGH" : "LOW");
    log_event(message);
}

// Log an event to the log file
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write to file
    printf("%s: %s\n", timestamp, message); // Also print to console
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() != 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    control_relay(0); // Initialize relay to LOW

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    uint16_t touch_status;
    int relay_state = 0; // 0 = LOW, 1 = HIGH

    // Main loop
    while (program_running) {
        if (read_touch_status(&touch_status) == 0) {
            // Check if any electrode is touched
            if (touch_status != 0) {
                control_relay(1);
                relay_state = 1;
            } else {
                control_relay(0);
                relay_state = 0;
            }
        } else {
            log_event("Error reading touch status, retrying...");
        }

        gpioDelay(50); // Poll every 50ms
    }

    // Cleanup
    control_relay(0); // Ensure relay is off on exit
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

