    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG, 0x10) < 0) {
        log_event("Error: Run mode enable failed");
        return -1;
    }

    log_event("MPR121 initialized successfully");
    return 0;
}

// Read the touch status from the MPR121
int read_touch_status(uint16_t *touch_status) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, buf, 2) != 2) {
        log_event("Error: Failed to read touch status");
        return -1;
    }

    *touch_status = ((uint16_t)buf[1] << 8) | (uint16_t)buf[0];
    return 0;
}

// Control the relay state
void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
    char message[100];
    snprintf(message, sizeof(message), "Relay set to %s", state ? "HIGH" : "LOW");
    log_event(message);
}

// Log an event to the log file
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write to file
    printf("%s: %s\n", timestamp, message); // Also print to console
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() != 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    control_relay(0); // Initialize relay to LOW

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    uint16_t touch_status;
    int relay_state = 0; // 0 = LOW, 1 = HIGH

    // Main loop
    while (program_running) {
        if (read_touch_status(&touch_status) == 0) {
            // Check if any electrode is touched
            if (touch_status != 0) {
                control_relay(1);
                relay_state = 1;
            } else {
                control_relay(0);
                relay_state = 0;
            }
        } else {
            log_event("Error reading touch status, retrying...");
        }

        gpioDelay(50); // Poll every 50ms
    }

    // Cleanup
    control_relay(0); // Ensure relay is off on exit
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

