#include <pigpio.h>

// Define GPIO pins for the valves
#define VALVE1_GPIO 17
#define VALVE2_GPIO 18

// Define valve activation durations (in milliseconds)
#define VALVE1_DURATION 500
#define VALVE2_DURATION 1000

// Define pause durations (in seconds)
#define VALVE1_PAUSE 5
#define VALVE2_PAUSE 10

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int open_valve(int gpio_pin);
int close_valve(int gpio_pin);
int log_event(const char *event_message);
void signal_handler(int signal);
void cleanup();

// Function to initialize the pigpio library and set GPIO pins as outputs
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(VALVE1_GPIO, PI_OUTPUT);
    gpioSetMode(VALVE2_GPIO, PI_OUTPUT);

    return 0;
}

// Function to open a valve by setting the GPIO pin HIGH
int open_valve(int gpio_pin) {
    if (gpioWrite(gpio_pin, 1) != 0) {
        fprintf(stderr, "Failed to open valve on GPIO %d\n", gpio_pin);
        return -1;
    }
    return 0;
}

// Function to close a valve by setting the GPIO pin LOW
int close_valve(int gpio_pin) {
    if (gpioWrite(gpio_pin, 0) != 0) {
        fprintf(stderr, "Failed to close valve on GPIO %d\n", gpio_pin);
        return -1;
    }
    return 0;
}

// Function to log an event to the log file with an ISO 8601 timestamp
int log_event(const char *event_message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, event_message);
        fflush(log_file); // Ensure the log is written immediately
        return 0;
    } else {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }
}

// Signal handler for SIGINT and SIGTERM signals
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release GPIO lines and close the log file
void cleanup() {
    printf("Cleaning up...\n");
    close_valve(VALVE1_GPIO);
    close_valve(VALVE2_GPIO);
    gpioTerminate();

    if (log_file != NULL) {
        fclose(log_file);
    }
}

