    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen("valve_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    printf("Water distribution schedule started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Valve 1 activation
        if (open_valve(VALVE1_GPIO) == 0) {
            log_event("Valve 1 opened");
            gpioDelay(VALVE1_DURATION * 1000); // Delay in microseconds
            if (close_valve(VALVE1_GPIO) == 0) {
                log_event("Valve 1 closed");
            } else {
                log_event("Failed to close Valve 1");
            }
        } else {
            log_event("Failed to open Valve 1");
        }

        gpioDelay(VALVE1_PAUSE * 1000000); // Delay in microseconds

        // Valve 2 activation
        if (open_valve(VALVE2_GPIO) == 0) {
            log_event("Valve 2 opened");
            gpioDelay(VALVE2_DURATION * 1000); // Delay in microseconds
            if (close_valve(VALVE2_GPIO) == 0) {
                log_event("Valve 2 closed");
            } else {
                log_event("Failed to close Valve 2");
            }
        } else {
            log_event("Failed to open Valve 2");
        }

        gpioDelay(VALVE2_PAUSE * 1000000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

