#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <signal.h>
#include <unistd.h>

// Define MPR121 I2C address
#define MPR121_ADDR 0x5A

// Define MPR121 register addresses
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_TOUCHTH_0 0x41
#define MPR121_RELEASETH_0 0x42
#define MPR121_FILTERTH_0 0x2B
#define MPR121_BASELINE_0 0x1E
#define MPR121_MHDR 0x2B
#define MPR121_NHDR 0x2C
#define MPR121_NCLR 0x2D
#define MPR121_FDLR 0x2E
#define MPR121_MHDF 0x2F
#define MPR121_NHDF 0x30
#define MPR121_NCLF 0x31
#define MPR121_FDLF 0x32
#define MPR121_NHDT 0x33
#define MPR121_NCLT 0x34
#define MPR121_FDLT 0x35
#define MPR121_TOUCHTH_1 0x43
#define MPR121_RELEASETH_1 0x44
#define MPR121_TOUCHTH_2 0x45
#define MPR121_RELEASETH_2 0x46
#define MPR121_TOUCHTH_3 0x47
#define MPR121_RELEASETH_3 0x48
#define MPR121_TOUCHTH_4 0x49
#define MPR121_RELEASETH_4 0x4A
#define MPR121_TOUCHTH_5 0x4B
#define MPR121_RELEASETH_5 0x4C
#define MPR121_TOUCHTH_6 0x4D
#define MPR121_RELEASETH_6 0x4E
#define MPR121_TOUCHTH_7 0x4F
#define MPR121_RELEASETH_7 0x50
#define MPR121_TOUCHTH_8 0x51
#define MPR121_RELEASETH_8 0x52
#define MPR121_TOUCHTH_9 0x53
#define MPR121_RELEASETH_9 0x54
#define MPR121_TOUCHTH_10 0x55
#define MPR121_RELEASETH_10 0x56
#define MPR121_TOUCHTH_11 0x57
#define MPR121_RELEASETH_11 0x58
#define MPR121_ECR 0x5C
#define MPR121_CONFIG1 0x5B
#define MPR121_CONFIG2 0x5D

// Define GPIO pin for relay control
#define RELAY_PIN 17

// Global variables
int i2c_fd;
bool relay_state = false;

// Function prototypes
int mpr121_init();
int mpr121_read_touch_status();
int mpr121_write_register(int reg, int value);
int mpr121_read_register(int reg);
void relay_toggle();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    digitalWrite(RELAY_PIN, LOW); // Ensure relay is off
    close(i2c_fd);
    exit(0);
}

// Function to initialize the MPR121
int mpr121_init() {
    // Stop mode
    if (mpr121_write_register(MPR121_ECR, 0x00) < 0) return -1;
    delay(1);

    // Configure touch and release thresholds for all electrodes
    for (int i = 0; i < 12; i++) {
        if (mpr121_write_register(MPR121_TOUCHTH_0 + 2 * i, 40) < 0) return -1; // Touch threshold
        if (mpr121_write_register(MPR121_RELEASETH_0 + 2 * i, 20) < 0) return -1; // Release threshold
    }

    // Configure filter and charge time
    if (mpr121_write_register(MPR121_MHDR, 0x01) < 0) return -1;
    if (mpr121_write_register(MPR121_NHDR, 0x01) < 0) return -1;
    if (mpr121_write_register(MPR121_NCLR, 0x0E) < 0) return -1;
    if (mpr121_write_register(MPR121_FDLR, 0x00) < 0) return -1;
    if (mpr121_write_register(MPR121_MHDF, 0x01) < 0) return -1;
    if (mpr121_write_register(MPR121_NHDF, 0x01) < 0) return -1;
    if (mpr121_write_register(MPR121_NCLF, 0x0E) < 0) return -1;
    if (mpr121_write_register(MPR121_FDLF, 0x00) < 0) return -1;
    if (mpr121_write_register(MPR121_NHDT, 0x01) < 0) return -1;
    if (mpr121_write_register(MPR121_NCLT, 0x0E) < 0) return -1;
    if (mpr121_write_register(MPR121_FDLT, 0x00) < 0) return -1;

    // Electrode current
    if (mpr121_write_register(MPR121_ECR, 0x8F) < 0) return -1; // Enable all electrodes

    // Run mode
    if (mpr121_write_register(MPR121_ECR, 0x10) < 0) return -1; // Enable all electrodes
    delay(1);

    return 0;
}

// Function to read the touch status from the MPR121
int mpr121_read_touch_status() {
    int touch_status_l = mpr121_read_register(MPR121_TOUCHSTATUS_L);
    int touch_status_h = mpr121_read_register(MPR121_TOUCHSTATUS_H);

    if (touch_status_l < 0 || touch_status_h < 0) {
        return -1; // Indicate error
    }

    return (touch_status_h << 8) | touch_status_l;
}

// Function to write a register value to the MPR121
int mpr121_write_register(int reg, int value) {
    int result = wiringPiI2CWriteReg8(i2c_fd, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a register value from the MPR121
int mpr121_read_register(int reg) {
    int result = wiringPiI2CReadReg8(i2c_fd, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return result;
}

// Function to toggle the relay state
void relay_toggle() {
    relay_state = !relay_state;
    digitalWrite(RELAY_PIN, relay_state);
    printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "wiringPiSetupGpio failed\n");
        return 1;
    }

    // Initialize I2C
    i2c_fd = wiringPiI2CSetup(MPR121_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "wiringPiI2CSetup failed\n");
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Set relay pin as output
    pinMode(RELAY_PIN, OUTPUT);
    digitalWrite(RELAY_PIN, LOW); // Initialize relay to OFF

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("MPR121 touch sensor and relay control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        int touch_status = mpr121_read_touch_status();
        if (touch_status < 0) {
            fprintf(stderr, "Error reading touch status\n");
        } else {
            if (touch_status > 0) {
                relay_toggle();
            }
        }

        delay(100);
    }

    return 0;
}

