int mpr121_read_touch_status() {
    int touch_status_l = mpr121_read_register(MPR121_TOUCHSTATUS_L);
    int touch_status_h = mpr121_read_register(MPR121_TOUCHSTATUS_H);

    if (touch_status_l < 0 || touch_status_h < 0) {
        return -1; // Indicate error
    }

    return (touch_status_h << 8) | touch_status_l;
}

// Function to write a register value to the MPR121
int mpr121_write_register(int reg, int value) {
    int result = wiringPiI2CWriteReg8(i2c_fd, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a register value from the MPR121
int mpr121_read_register(int reg) {
    int result = wiringPiI2CReadReg8(i2c_fd, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return result;
}

// Function to toggle the relay state
void relay_toggle() {
    relay_state = !relay_state;
    digitalWrite(RELAY_PIN, relay_state);
    printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "wiringPiSetupGpio failed\n");
        return 1;
    }

    // Initialize I2C
    i2c_fd = wiringPiI2CSetup(MPR121_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "wiringPiI2CSetup failed\n");
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Set relay pin as output
    pinMode(RELAY_PIN, OUTPUT);
    digitalWrite(RELAY_PIN, LOW); // Initialize relay to OFF

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("MPR121 touch sensor and relay control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        int touch_status = mpr121_read_touch_status();
        if (touch_status < 0) {
            fprintf(stderr, "Error reading touch status\n");
        } else {
            if (touch_status > 0) {
                relay_toggle();
            }
        }

        delay(100);
    }

    return 0;
}

