// Define GPIO pins
#define PIR_SENSOR_1 17
#define PIR_SENSOR_2 22
#define PIR_SENSOR_3 23
#define RELAY_PIN 18

// Define constants
#define UNLOCK_DURATION_MS 500
#define RATE_LIMIT_MS 2000
#define POLLING_INTERVAL_MS 50

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_pir_sensor(int gpio_pin);
void control_relay(int gpio_pin, int state);
void log_event(const char *event_type, int gpio_pin);
void rate_limit(int gpio_pin);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    int gpio_pin;
    unsigned long last_unlock_time;
} sensor_data_t;

sensor_data_t sensor_data[3];

int main() {
    // Initialize sensor data
    sensor_data[0].gpio_pin = PIR_SENSOR_1;
    sensor_data[0].last_unlock_time = 0;
    sensor_data[1].gpio_pin = PIR_SENSOR_2;
    sensor_data[1].last_unlock_time = 0;
    sensor_data[2].gpio_pin = PIR_SENSOR_3;
    sensor_data[2].last_unlock_time = 0;

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("door_events.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Door access control system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        for (int i = 0; i < 3; i++) {
            int motion_detected = read_pir_sensor(sensor_data[i].gpio_pin);

            if (motion_detected) {
                log_event("Motion Detected", sensor_data[i].gpio_pin);
                control_relay(RELAY_PIN, 1); // Activate relay
                log_event("Door Unlocked", RELAY_PIN);
                gpioDelay(UNLOCK_DURATION_MS * 1000); // Delay for unlock duration
                control_relay(RELAY_PIN, 0); // Deactivate relay
                rate_limit(sensor_data[i].gpio_pin);
                break; // Exit loop after unlocking
            }
        }
        gpioDelay(POLLING_INTERVAL_MS * 1000); // Delay for polling interval
    }

    // Cleanup and exit
    cleanup();
    printf("Door access control system stopped.\n");
    return 0;
}

// Initialize pigpio library and configure GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set PIR sensor pins as inputs with pull-down resistors
    gpioSetMode(PIR_SENSOR_1, PI_INPUT);
    gpioSetPullUpDown(PIR_SENSOR_1, PI_PUD_DOWN);
    gpioSetMode(PIR_SENSOR_2, PI_INPUT);
    gpioSetPullUpDown(PIR_SENSOR_2, PI_PUD_DOWN);
    gpioSetMode(PIR_SENSOR_3, PI_INPUT);
    gpioSetPullUpDown(PIR_SENSOR_3, PI_PUD_DOWN);

    // Set relay pin as output
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    control_relay(RELAY_PIN, 0); // Ensure relay is initially off

    return 0;
}

// Read PIR sensor value
int read_pir_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Control relay state
void control_relay(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

// Log event to file
void log_event(const char *event_type, int gpio_pin) {
    if (log_file != NULL) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        char timestamp[30];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
        fprintf(log_file, "%s.%03ld: %s (GPIO %d)\n", timestamp, ts.tv_nsec / 1000000, event_type, gpio_pin);
        fflush(log_file); // Ensure data is written to file immediately
    } else {
        fprintf(stderr, "Log file is not open.\n");
    }
}

// Rate limit unlocking
void rate_limit(int gpio_pin) {
    for (int i = 0; i < 3; i++) {
        if (sensor_data[i].gpio_pin == gpio_pin) {
            sensor_data[i].last_unlock_time = gpioTick();
            break;
        }
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
}

// Cleanup function to release resources
void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
    }
    control_relay(RELAY_PIN, 0); // Ensure relay is off
    gpioTerminate();
}

