#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins for Motor 1 and Motor 2
#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Define minimum and maximum PWM duty cycle values
#define MIN_DUTY_CYCLE 0
#define MAX_DUTY_CYCLE 255

// Define minimum and maximum step duration (ms)
#define MIN_STEP_DURATION 50
#define MAX_STEP_DURATION 200

// Define the number of steps in a pattern
#define MIN_STEPS 5
#define MAX_STEPS 15

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, terminating gracefully...\n");
}

// Function to generate a random integer between min and max (inclusive)
int generate_random_integer(int min, int max) {
    return (rand() % (max - min + 1)) + min;
}

// Function to generate a random PWM duty cycle
int generate_random_duty_cycle() {
    return generate_random_integer(MIN_DUTY_CYCLE, MAX_DUTY_CYCLE);
}

// Function to generate a random step duration
int generate_random_step_duration() {
    return generate_random_integer(MIN_STEP_DURATION, MAX_STEP_DURATION);
}

// Function to generate a random number of steps
int generate_random_steps() {
    return generate_random_integer(MIN_STEPS, MAX_STEPS);
}

// Function to generate a random haptic feedback pattern
void generate_random_pattern(int *motor1_duty_cycles, int *motor2_duty_cycles, int *step_durations, int *num_steps) {
    *num_steps = generate_random_steps();

    for (int i = 0; i < *num_steps; i++) {
        motor1_duty_cycles[i] = generate_random_duty_cycle();
        motor2_duty_cycles[i] = generate_random_duty_cycle();
        step_durations[i] = generate_random_step_duration();
    }
}

// Function to play a haptic feedback pattern
void play_pattern(int *motor1_duty_cycles, int *motor2_duty_cycles, int *step_durations, int num_steps) {
    for (int i = 0; i < num_steps; i++) {
        gpioPWM(MOTOR1_GPIO, motor1_duty_cycles[i]);
        gpioPWM(MOTOR2_GPIO, motor2_duty_cycles[i]);
        gpioDelay(step_durations[i] * 1000); // Convert ms to microseconds
    }
}

// Function to stop both motors
void stop_motors() {
    gpioPWM(MOTOR1_GPIO, 0);
    gpioPWM(MOTOR2_GPIO, 0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes for Motor 1 and Motor 2 to PWM output
    if (gpioSetMode(MOTOR1_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d to output mode\n", MOTOR1_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MOTOR2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d to output mode\n", MOTOR2_GPIO);
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency for Motor 1 and Motor 2
    if (gpioSetPWMfrequency(MOTOR1_GPIO, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", MOTOR1_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMfrequency(MOTOR2_GPIO, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", MOTOR2_GPIO);
        gpioTerminate();
        return 1;
    }

    // Seed the random number generator with the current time
    srand(time(NULL));

    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Allocate memory for the pattern
        int *motor1_duty_cycles = malloc(MAX_STEPS * sizeof(int));
        int *motor2_duty_cycles = malloc(MAX_STEPS * sizeof(int));
        int *step_durations = malloc(MAX_STEPS * sizeof(int));
        int num_steps;

        if (motor1_duty_cycles == NULL || motor2_duty_cycles == NULL || step_durations == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            stop_motors();
            gpioTerminate();
            return 1;
        }

        // Generate a random haptic feedback pattern
        generate_random_pattern(motor1_duty_cycles, motor2_duty_cycles, step_durations, &num_steps);

        // Play the pattern
        play_pattern(motor1_duty_cycles, motor2_duty_cycles, step_durations, num_steps);

        // Free allocated memory
        free(motor1_duty_cycles);
        free(motor2_duty_cycles);
        free(step_durations);

        // Delay before generating the next pattern
        gpioDelay(500000); // 0.5 seconds
    }

    // Stop both motors
    stop_motors();

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

