#include <pigpio.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Define weight threshold
#define WEIGHT_THRESHOLD 10.0

// Define calibration file
#define CALIBRATION_FILE "calibration.txt"

// Define log file
#define LOG_FILE "weight_log.txt"

// Define timeout duration (in milliseconds)
#define TIMEOUT_DURATION 500

// Global variables
static volatile int running = 1;
static double scale_factor = 1.0;
static double offset = 0.0;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
long read_hx711();
double calculate_weight(long raw_value);
int control_solenoid(double weight);
int load_calibration();
int save_calibration();
void log_data(double weight);
void signal_handler(int signal);
void cleanup();

// Structure to hold calibration data
typedef struct {
    double scale;
    double offset;
} CalibrationData;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    return 0;
}

// Function to read data from HX711
long read_hx711() {
    long value = 0;
    int i;
    int timeout_counter = 0;

    // Wait for data pin to go low (with timeout)
    while (gpioRead(HX711_DATA_PIN) == 1 && timeout_counter < TIMEOUT_DURATION) {
        gpioDelay(1); // Small delay to avoid busy-waiting
        timeout_counter++;
    }

    if (timeout_counter >= TIMEOUT_DURATION) {
        fprintf(stderr, "Timeout reading HX711 data\n");
        return -1; // Indicate timeout error
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // Small delay
        value = value << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            value++;
        }
