#define MOTOR_IN2_PIN 18
#define MOTOR_PWM_PIN 27

// Define constants
#define DEBOUNCE_READINGS 5
#define DEBOUNCE_DELAY_MS 50
#define RAIN_THRESHOLD 3
#define PWM_FREQUENCY 1000
#define PWM_DUTY_CYCLE 150
#define MOTOR_CLOSE_DURATION_S 5
#define SLEEP_INTERVAL_S 60

// Global variables
