int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT);

    gpioSetPWMfrequency(MOTOR_PWM_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(MOTOR_PWM_PIN, 255);

    return 0;
}

// Function to cleanup GPIO pins
void cleanup_gpio() {
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioPWM(MOTOR_PWM_PIN, 0);
    gpioTerminate();
}

int main() {
    // Initialize syslog
    openlog("window_control", LOG_PID | LOG_CONS, LOG_USER);

    // Open log file
    log_file = fopen("/var/log/window_control.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        syslog(LOG_ERR, "Error opening log file");
        closelog();
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_event("GPIO initialization failed, exiting.");
        fclose(log_file);
        closelog();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Window control system started.");

    // Main loop
    while (running) {
        if (debounce_rain_sensor()) {
            log_event("Rain detected!");
            close_window();
        }
        gpioDelay(SLEEP_INTERVAL_S * 1000000); // Convert seconds to microseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    stop_motor();
    cleanup_gpio();
    fclose(log_file);
    closelog();

