#define CALIBRATION_FILE "calibration.txt"
#define SECURITY_LOG_FILE "security.log"
#define WEIGHT_THRESHOLD 5.0 // kg
#define SOLENOID_DURATION 5 // seconds
#define TIMEOUT_MS 100

// Global variables
static volatile int running = 1;
static double calibration_factor = 0.0;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_hx711(long *raw_value);
double calibrate_hx711(double known_weight);
double convert_to_kg(long raw_value);
