// Structure for HX711 configuration
typedef struct {
    int data_pin;
    int clock_pin;
} HX711Config;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    return 0;
}

// Function to read raw data from HX711
int read_hx711(long *raw_value) {
    int i;
    long value = 0;
    int timeout_count = 0;

    // Wait for data line to go low (start of data transmission)
    while (gpioRead(HX711_DATA_PIN) == 1) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout_count++;
        if (timeout_count > TIMEOUT_MS) {
            fprintf(stderr, "HX711 timeout waiting for data line to go low\n");
            return -1; // Timeout
        }
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // Clock high delay
        value = value << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            value++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // Clock low delay
    }

    // Apply the 25th clock pulse for gain selection (Channel A, gain 128)
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1); // Clock high delay
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1); // Clock low delay

    // Convert to signed 24-bit integer
    if (value & 0x800000) {
        value |= 0xFF000000;
    }

    *raw_value = value;
    return 0;
}

