    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Read calibration factor from file
    FILE *cal_file = fopen(CALIBRATION_FILE, "r");
    if (cal_file != NULL) {
        if (fscanf(cal_file, "%lf", &calibration_factor) != 1) {
            fprintf(stderr, "Error reading calibration factor from file, using default value.\n");
            calibration_factor = 0.0; // Use default value
        }
        fclose(cal_file);
    } else {
        fprintf(stderr, "Calibration file not found, using default value.\n");
        calibration_factor = 0.0; // Use default value
    }

    // If calibration factor is still 0, prompt user for calibration
    if (calibration_factor == 0.0) {
        double known_weight;
        printf("Enter the known weight (in kg) used for calibration: ");
        if (scanf("%lf", &known_weight) != 1) {
            fprintf(stderr, "Invalid input for known weight.\n");
