            fprintf(cal_file, "%lf", calibration_factor);
            fclose(cal_file);
        } else {
            fprintf(stderr, "Error opening calibration file for writing!\n");
        }
    }

    printf("Weight monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        if (read_hx711(&raw_value) == 0) {
            weight = convert_to_kg(raw_value);
            printf("Raw: %ld, Weight: %.2f kg\n", raw_value, weight);

            if (weight > WEIGHT_THRESHOLD) {
                printf("Weight threshold exceeded! Activating solenoid.\n");
                control_solenoid(1); // Activate solenoid
