                control_solenoid(0); // Deactivate solenoid
                printf("Solenoid deactivated.\n");
            }
        } else {
            fprintf(stderr, "Error reading HX711 data.\n");
        }

        gpioDelay(100); // Delay to avoid excessive CPU usage
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

