#include <string.h>

// Define GPIO pins
#define SENSOR_PIN 16
#define RELAY_PIN 20

// Define log file name
#define LOG_FILE "relay_events.log"

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
int read_sensor();
int toggle_relay();
int log_event(int relay_state);
void cleanup();
void signal_handler(int signal);

// Structure to hold GPIO configuration
typedef struct {
    int sensor_pin;
    int relay_pin;
} gpio_config_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    return 0;
}

// Function to read the sensor value
int read_sensor() {
    int sensor_value = gpioRead(SENSOR_PIN);
    if (sensor_value < 0) {
        fprintf(stderr, "Error reading sensor value\n");
        return -1;
    }
    return sensor_value;
}

// Function to toggle the relay state
int toggle_relay() {
    int current_state = gpioRead(RELAY_PIN);
    if (current_state < 0) {
        fprintf(stderr, "Error reading relay state\n");
        return 1;
    }

    int new_state = !current_state;
    if (gpioWrite(RELAY_PIN, new_state) != 0) {
        fprintf(stderr, "Error writing to relay pin\n");
        return 1;
    }

    return 0;
}

// Function to log the event to a file
int log_event(int relay_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return 1;
    }

    if (relay_state == 1) {
        fprintf(log_file, "%s - Relay ON\n", timestamp);
    } else {
        fprintf(log_file, "%s - Relay OFF\n", timestamp);
    }

    fflush(log_file); // Ensure the log is written immediately
    return 0;
}

// Function to clean up GPIO resources
void cleanup() {
    printf("Cleaning up and exiting...\n");
    gpioWrite(RELAY_PIN, 0); // Turn off relay
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    cleanup();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    printf("Monitoring obstacle avoidance sensor...\n");

    // Main loop
    while (running) {
        int sensor_value = read_sensor();
        if (sensor_value == 0) { // Obstacle detected (LOW signal)
            if (toggle_relay() == 0) {
                int relay_state = gpioRead(RELAY_PIN);
                if (relay_state >= 0) {
                    if (log_event(relay_state) != 0) {
                        fprintf(stderr, "Error logging event\n");
                    }
                } else {
                    fprintf(stderr, "Error reading relay state after toggle\n");
                }
            } else {
                fprintf(stderr, "Error toggling relay\n");
            }
        } else if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor, exiting...\n");
            break;
        }

        gpioDelay(100); // Delay for 100ms
    }

    cleanup();
    return 0;
}

