#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define CONFIG_FILE "watering.conf"
#define LOG_FILE "watering.log"

static volatile sig_atomic_t terminate = 0;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nSignal received, shutting down gracefully...\n");
}

// Function to read the watering duration from the configuration file
int read_duration(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open configuration file %s\n", filename);
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error: Could not read from configuration file %s\n", filename);
        fclose(fp);
        return -1;
    }

    fclose(fp);

    char *token = strtok(line, "=");
    if (token == NULL || strcmp(token, "duration") != 0) {
        fprintf(stderr, "Error: Invalid configuration file format\n");
        return -1;
    }

    token = strtok(NULL, "=");
    if (token == NULL) {
        fprintf(stderr, "Error: Invalid configuration file format\n");
        return -1;
    }

    char *endptr;
    long duration = strtol(token, &endptr, 10);

    if (*endptr != '\0' && *endptr != '\n') {
        fprintf(stderr, "Error: Invalid duration value\n");
        return -1;
    }

    if (duration < 1 || duration > 3600) {
        fprintf(stderr, "Error: Duration must be between 1 and 3600 seconds\n");
        return -1;
    }

    return (int)duration;
}

// Function to initialize the GPIO pin
int initialize_gpio(int pin) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(pin, PI_OUTPUT);
    gpioWrite(pin, 0); // Ensure valve is initially off
    return 0;
}

// Function to activate the watering valve
int activate_valve(int pin) {
    if (gpioWrite(pin, 1) != 0) {
        fprintf(stderr, "Error: Failed to activate valve\n");
        return -1;
    }
    return 0;
}

// Function to deactivate the watering valve
int deactivate_valve(int pin) {
    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "Error: Failed to deactivate valve\n");
        return -1;
    }
    return 0;
}

// Function to log events to a file
int log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Read watering duration from configuration file
    int duration = read_duration(CONFIG_FILE);
    if (duration < 0) {
        fprintf(stderr, "Error: Failed to read watering duration. Exiting.\n");
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio(GPIO_PIN) != 0) {
        fprintf(stderr, "Error: Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Activate valve
        if (activate_valve(GPIO_PIN) != 0) {
            fprintf(stderr, "Error: Failed to activate valve. Continuing.\n");
        } else {
            char log_message[128];
            snprintf(log_message, sizeof(log_message), "Valve activated for %d seconds", duration);
            log_event(log_message);
            printf("%s\n", log_message);
        }

        // Wait for the specified duration
        sleep(duration);

        // Deactivate valve
        if (deactivate_valve(GPIO_PIN) != 0) {
            fprintf(stderr, "Error: Failed to deactivate valve. Continuing.\n");
        } else {
            log_event("Valve deactivated");
            printf("Valve deactivated\n");
        }

        // Check for termination signal
        if (terminate) break;
    }

    // Ensure valve is off before exiting
    deactivate_valve(GPIO_PIN);

    // Release GPIO resources
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

