#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27
#define LEFT_MOTOR_FORWARD_PIN 22
#define LEFT_MOTOR_BACKWARD_PIN 23
#define RIGHT_MOTOR_FORWARD_PIN 24
#define RIGHT_MOTOR_BACKWARD_PIN 25

// Define motor speeds
#define BASE_SPEED 150
#define TURN_SPEED 75

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Define log file name
#define LOG_FILE "trace_log.txt"

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_sensors();
void set_motor_speed(int left_speed, int right_speed);
void log_data(int left_sensor, int middle_sensor, int right_sensor, int left_speed, int right_speed);
void stop_motors();
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    int left;
    int middle;
    int right;
} sensor_data_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);

    gpioSetMode(LEFT_MOTOR_FORWARD_PIN, PI_OUTPUT);
    gpioSetMode(LEFT_MOTOR_BACKWARD_PIN, PI_OUTPUT);
    gpioSetMode(RIGHT_MOTOR_FORWARD_PIN, PI_OUTPUT);
    gpioSetMode(RIGHT_MOTOR_BACKWARD_PIN, PI_OUTPUT);

    gpioSetPWMfrequency(LEFT_MOTOR_FORWARD_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(LEFT_MOTOR_BACKWARD_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RIGHT_MOTOR_FORWARD_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RIGHT_MOTOR_BACKWARD_PIN, PWM_FREQUENCY);

    return 0;
}

// Function to read sensor values
int read_sensors() {
    sensor_data_t sensor_data;
    sensor_data.left = gpioRead(LEFT_SENSOR_PIN);
    sensor_data.middle = gpioRead(MIDDLE_SENSOR_PIN);
    sensor_data.right = gpioRead(RIGHT_SENSOR_PIN);

    // Validate sensor readings
    if (sensor_data.left != 0 && sensor_data.left != 1) {
        fprintf(stderr, "Invalid left sensor reading: %d\n", sensor_data.left);
        return -1; // Indicate an error
    }
    if (sensor_data.middle != 0 && sensor_data.middle != 1) {
        fprintf(stderr, "Invalid middle sensor reading: %d\n", sensor_data.middle);
        return -1; // Indicate an error
    }
    if (sensor_data.right != 0 && sensor_data.right != 1) {
        fprintf(stderr, "Invalid right sensor reading: %d\n", sensor_data.right);
        return -1; // Indicate an error
    }

    return (sensor_data.left << 2) | (sensor_data.middle << 1) | sensor_data.right;
