#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define GPIO_RELAY 23
#define LUX_THRESHOLD 150.0
#define MEASUREMENT_DELAY_MS 180
#define LOG_FILE "grow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
float read_lux();
void control_relay(int state);
void log_data(float lux, int relay_state);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int bh1750_address;
    int gpio_relay;
    float lux_threshold;
    int measurement_delay_ms;
    char *log_file;
} Config;

Config config = {
    .i2c_bus = I2C_BUS,
    .bh1750_address = BH1750_ADDR,
    .gpio_relay = GPIO_RELAY,
    .lux_threshold = LUX_THRESHOLD,
    .measurement_delay_ms = MEASUREMENT_DELAY_MS,
    .log_file = LOG_FILE
};

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Set GPIO mode for relay
    gpioSetMode(config.gpio_relay, PI_OUTPUT);

    // Open log file
    log_file = fopen(config.log_file, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int relay_state = 0; // 0 = off, 1 = on

    // Main loop
    while (!terminate) {
        float lux = read_lux();

        if (lux >= 0) {
            if (lux < config.lux_threshold && relay_state == 0) {
                control_relay(1); // Turn on relay
                relay_state = 1;
                log_data(lux, relay_state);
            } else if (lux >= config.lux_threshold && relay_state == 1) {
                control_relay(0); // Turn off relay
                relay_state = 0;
                log_data(lux, relay_state);
            } else {
                log_data(lux, relay_state);
            }
        } else {
            fprintf(stderr, "Failed to read lux value\n");
        }

        gpioDelay(config.measurement_delay_ms * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(config.i2c_bus, config.bh1750_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read illuminance from BH1750 sensor
float read_lux() {
    char config_mode = 0x10; // Continuous high resolution mode
    int result;

    result = i2cWriteByteData(i2c_handle, 0x00, config_mode);
    if (result != 0) {
        fprintf(stderr, "Failed to write to I2C device: %d\n", result);
        return -1.0;
    }

    gpioDelay(200000); // Wait for measurement (at least 180ms)

    result = i2cReadWordData(i2c_handle, 0x00);
    if (result < 0) {
        fprintf(stderr, "Failed to read from I2C device: %d\n", result);
        return -1.0;
    }

    // BH1750 returns big-endian data, so swap bytes
    uint16_t raw_value = (result >> 8) | (result << 8);
    float lux = (float)raw_value / 1.2;
    return lux;
}

// Control the relay
void control_relay(int state) {
    gpioWrite(config.gpio_relay, state);
}

// Log data to file
void log_data(float lux, int relay_state) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

    fprintf(log_file, "%s, Lux: %.2f, Relay: %s\n", timestamp, lux, relay_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed, exiting...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    control_relay(0); // Turn off relay
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

