int initialize_gpio();
void motor1_pulse();
void motor2_pulse();
void cleanup_gpio();
void signal_handler(int signal);

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("\nCaught signal %d, cleaning up and exiting...\n", signal);
        program_running = 0;
        cleanup_gpio();
        exit(0);
    }
}

// Function to initialize the pigpio library and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO17 as an output
    if (gpioSetMode(MOTOR1_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", MOTOR1_GPIO);
        gpioTerminate();
        return 1;
    }

    // Set GPIO27 as an output
    if (gpioSetMode(MOTOR2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", MOTOR2_GPIO);
        gpioTerminate();
        return 1;
    }

    return 0; // Indicate success
}

// Function to pulse motor 1 for 200ms
void motor1_pulse() {
    if (gpioWrite(MOTOR1_GPIO, 1) != 0) {
        fprintf(stderr, "Failed to write to GPIO%d\n", MOTOR1_GPIO);
        return;
    }
    gpioDelay(200); // Delay for 200ms
    if (gpioWrite(MOTOR1_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to write to GPIO%d\n", MOTOR1_GPIO);
        return;
    }
}

// Function to pulse motor 2 for 300ms
void motor2_pulse() {
    if (gpioWrite(MOTOR2_GPIO, 1) != 0) {
        fprintf(stderr, "Failed to write to GPIO%d\n", MOTOR2_GPIO);
        return;
    }
    gpioDelay(300); // Delay for 300ms
    if (gpioWrite(MOTOR2_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to write to GPIO%d\n", MOTOR2_GPIO);
        return;
    }
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    // Set GPIO pins to input mode to avoid short circuits
    gpioSetMode(MOTOR1_GPIO, PI_INPUT);
    gpioSetMode(MOTOR2_GPIO, PI_INPUT);

    gpioTerminate();
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Haptic feedback system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        motor1_pulse();
        motor2_pulse();
    }

    // Cleanup GPIO before exiting
    cleanup_gpio();

    return 0;
}

