#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>
#include <zmq.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 27

// Define ZeroMQ endpoints
#define ALARM_NODE_ENDPOINT "tcp://*:5555"
#define SOUND_SENSOR_ENDPOINT "tcp://localhost:5555"

// Define topic
#define SOUND_ALERTS_TOPIC "SOUND_ALERTS"

// Global variables
static volatile int running = 1;
static void *zmq_context = NULL;
static void *zmq_socket = NULL;
static int alarm_mode = 0; // 0: sound_sensor, 1: alarm_node

// Function prototypes
int initialize_gpio();
int initialize_zmq();
void cleanup();
void signal_handler(int signal);
int publish_sound_alert();
int subscribe_to_sound_alerts();

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    gpioSetMode(ALARM_LED_PIN, PI_OUTPUT);

    return 0;
}

// Initialize ZeroMQ
int initialize_zmq() {
    zmq_context = zmq_ctx_new();
    if (!zmq_context) {
        fprintf(stderr, "Failed to create ZeroMQ context\n");
        return -1;
    }

    if (alarm_mode == 0) { // Sound sensor mode
        zmq_socket = zmq_socket(zmq_context, ZMQ_PUB);
        if (!zmq_socket) {
            fprintf(stderr, "Failed to create ZeroMQ socket (PUB)\n");
            zmq_ctx_destroy(zmq_context);
            return -1;
        }
        if (zmq_bind(zmq_socket, ALARM_NODE_ENDPOINT) != 0) {
            fprintf(stderr, "Failed to bind ZeroMQ socket\n");
            zmq_close(zmq_socket);
            zmq_ctx_destroy(zmq_context);
            return -1;
        }
    } else { // Alarm node mode
        zmq_socket = zmq_socket(zmq_context, ZMQ_SUB);
        if (!zmq_socket) {
            fprintf(stderr, "Failed to create ZeroMQ socket (SUB)\n");
            zmq_ctx_destroy(zmq_context);
            return -1;
        }
        if (zmq_connect(zmq_socket, SOUND_SENSOR_ENDPOINT) != 0) {
            fprintf(stderr, "Failed to connect ZeroMQ socket\n");
            zmq_close(zmq_socket);
            zmq_ctx_destroy(zmq_context);
            return -1;
        }
        if (zmq_setsockopt(zmq_socket, ZMQ_SUBSCRIBE, SOUND_ALERTS_TOPIC, strlen(SOUND_ALERTS_TOPIC), 0) != 0) {
            fprintf(stderr, "Failed to set ZeroMQ subscription\n");
            zmq_close(zmq_socket);
            zmq_ctx_destroy(zmq_context);
            return -1;
        }
    }

    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (zmq_socket) {
        zmq_close(zmq_socket);
    }
    if (zmq_context) {
        zmq_ctx_destroy(zmq_context);
    }
    gpioTerminate();
}

// Publish sound alert
int publish_sound_alert() {
    char timestamp[30];
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    char message[100];
    snprintf(message, sizeof(message), "%s: Sound detected!", timestamp);

    zmq_msg_t zmq_message;
    zmq_msg_init_size(&zmq_message, strlen(message));
    memcpy(zmq_msg_data(&zmq_message), message, strlen(message));

    int rc = zmq_msg_send(&zmq_message, zmq_socket, 0);
    zmq_msg_close(&zmq_message);

    if (rc == -1) {
        fprintf(stderr, "Failed to send ZeroMQ message\n");
        return -1;
    }

    printf("Published sound alert: %s\n", message);
    return 0;
}

// Subscribe to sound alerts
int subscribe_to_sound_alerts() {
    zmq_msg_t zmq_message;
    zmq_msg_init(&zmq_message);

    while (running) {
        int rc = zmq_msg_recv(&zmq_message, zmq_socket, 0);
        if (rc == -1) {
            fprintf(stderr, "Failed to receive ZeroMQ message\n");
            zmq_msg_close(&zmq_message);
            return -1;
        }

        char *message = (char *)zmq_msg_data(&zmq_message);
        printf("Received sound alert: %s\n", message);

        gpioWrite(ALARM_LED_PIN, 1); // Turn on LED
        gpioDelay(1000);           // Wait for 1 second
        gpioWrite(ALARM_LED_PIN, 0); // Turn off LED

        zmq_msg_close(&zmq_message);
    }

    zmq_msg_close(&zmq_message);
    return 0;
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <mode>\n", argv[0]);
        fprintf(stderr, "  mode: sound_sensor or alarm_node\n");
        return 1;
    }

    if (strcmp(argv[1], "sound_sensor") == 0) {
        alarm_mode = 0;
    } else if (strcmp(argv[1], "alarm_node") == 0) {
        alarm_mode = 1;
    } else {
        fprintf(stderr, "Invalid mode: %s\n", argv[1]);
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize ZeroMQ
    if (initialize_zmq() != 0) {
        cleanup();
        return 1;
    }

    printf("Alarm system started in %s mode\n", argv[1]);

    // Main loop
    if (alarm_mode == 0) { // Sound sensor mode
        while (running) {
            if (gpioRead(SOUND_SENSOR_PIN) == 0) { // Sound detected (active low)
                publish_sound_alert();
                gpioDelay(10); // Debounce delay
            }
            gpioDelay(10); // Check every 10ms
        }
    } else { // Alarm node mode
        subscribe_to_sound_alerts();
    }

    // Cleanup and exit
    cleanup();
    printf("Alarm system stopped\n");
    return 0;
}

