static volatile unsigned int pulse_lengths[MAX_PULSES];
static volatile unsigned int last_tick = 0;
static struct mosquitto *mosq = NULL;
static volatile int running = 1;

// Function prototypes
void alert_callback(int gpio, int level, unsigned int tick);
int decode_nec(unsigned int *pulse_lengths, int pulse_count, unsigned int *address, unsigned int *command);
int validate_nec(unsigned int address, unsigned int command, unsigned int inv_address, unsigned int inv_command);
int publish_mqtt(const char *topic, const char *payload);
void signal_handler(int signal);
int initialize_mqtt();
void cleanup();

// Alert callback function
void alert_callback(int gpio, int level, unsigned int tick) {
    if (level == FALLING_EDGE) {
        if (pulse_count < MAX_PULSES) {
            pulse_lengths[pulse_count++] = tick - last_tick;
        } else {
            syslog(LOG_ERR, "Pulse buffer overflow!");
            pulse_count = 0; // Reset buffer
        }
        last_tick = tick;
    }
}

// NEC decoding function
int decode_nec(unsigned int *pulse_lengths, int pulse_count, unsigned int *address, unsigned int *command) {
    if (pulse_count < 68) {
        syslog(LOG_ERR, "Not enough pulses received (%d)", pulse_count);
        return -1;
    }

    // Check for valid header
    if (pulse_lengths[0] < NEC_HDR_MARK * 0.8 || pulse_lengths[0] > NEC_HDR_MARK * 1.2 ||
        pulse_lengths[1] < NEC_HDR_SPACE * 0.8 || pulse_lengths[1] > NEC_HDR_SPACE * 1.2) {
        syslog(LOG_ERR, "Invalid NEC header");
        return -1;
    }

    unsigned int data = 0;
    for (int i = 2; i < 34; i++) {
        if (pulse_lengths[2 * i] < NEC_BIT_MARK * 0.8 || pulse_lengths[2 * i] > NEC_BIT_MARK * 1.2) {
            syslog(LOG_ERR, "Invalid bit mark at pulse %d", 2 * i);
            return -1;
        }

        if (pulse_lengths[2 * i + 1] > NEC_ONE_SPACE * 0.8 && pulse_lengths[2 * i + 1] < NEC_ONE_SPACE * 1.2) {
            data |= (1 << (31 - (i - 2)));
        } else if (pulse_lengths[2 * i + 1] > NEC_ZERO_SPACE * 0.8 && pulse_lengths[2 * i + 1] < NEC_ZERO_SPACE * 1.2) {
