#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// Define sensor addresses
#define SENSOR1_ADDR 0x23
#define SENSOR2_ADDR 0x5C
#define SENSOR3_ADDR 0x46
#define SENSOR4_ADDR 0x60

// Define multicast address and port
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005

// Define I2C bus
#define I2C_BUS 1

// Define BH1750FVI command for continuous high-resolution mode
#define BH1750FVI_CONTINUOUS_HIGH_RES_MODE 0x10

// Global variables
int i2c_handle1, i2c_handle2, i2c_handle3, i2c_handle4;
int udp_socket;
volatile sig_atomic_t terminate = 0;

// Function prototypes
float read_bh1750(int i2c_handle);
char* format_data(float lux1, float lux2, float lux3, float lux4);
int send_udp_multicast(const char* data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to read lux value from BH1750FVI sensor
float read_bh1750(int i2c_handle) {
    char buf[2];
    int result;

    // Send start-conversion command
    result = i2cWriteByteData(i2c_handle, 0x00, BH1750FVI_CONTINUOUS_HIGH_RES_MODE);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return NAN;
    }

    // Wait for measurement (at least 180ms)
    gpioDelay(180000); // 180ms

    // Read 2 bytes of data
    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return NAN;
    }

    // Convert data to lux value
    unsigned int raw_value = (buf[0] << 8) | buf[1];
    float lux = (float)raw_value / 1.2;

    return lux;
}

// Function to format data into a string
char* format_data(float lux1, float lux2, float lux3, float lux4) {
    char* data = (char*)malloc(100 * sizeof(char)); // Allocate memory for the string
    if (data == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    snprintf(data, 100, "1,%.2f;2,%.2f;3,%.2f;4,%.2f", lux1, lux2, lux3, lux4);
    return data;
}

// Function to send UDP multicast packet
int send_udp_multicast(const char* data) {
    struct sockaddr_in addr;
    int result;

    // Create UDP socket
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        perror("Error creating socket");
        return -1;
    }

    // Configure multicast address
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    // Set multicast TTL
    int ttl = 1;
    if (setsockopt(udp_socket, IPPROTO_IP, IP_MULTICAST_TTL, (void*)&ttl, sizeof(ttl)) < 0) {
        perror("Error setting TTL");
        close(udp_socket);
        return -1;
    }

    // Send data
    result = sendto(udp_socket, data, strlen(data), 0, (struct sockaddr*)&addr, sizeof(addr));
    if (result < 0) {
        perror("Error sending data");
        close(udp_socket);
        return -1;
    }

    close(udp_socket);
    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C devices
    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C device 1: %d\n", i2c_handle1);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C device 2: %d\n", i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    i2c_handle3 = i2cOpen(I2C_BUS, SENSOR3_ADDR, 0);
    if (i2c_handle3 < 0) {
        fprintf(stderr, "Error opening I2C device 3: %d\n", i2c_handle3);
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    i2c_handle4 = i2cOpen(I2C_BUS, SENSOR4_ADDR, 0);
    if (i2c_handle4 < 0) {
        fprintf(stderr, "Error opening I2C device 4: %d\n", i2c_handle4);
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        i2cClose(i2c_handle3);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float lux1, lux2, lux3, lux4;
        char* data;

        // Read lux values from sensors
        lux1 = read_bh1750(i2c_handle1);
        lux2 = read_bh1750(i2c_handle2);
        lux3 = read_bh1750(i2c_handle3);
        lux4 = read_bh1750(i2c_handle4);

        // Format data
        data = format_data(lux1, lux2, lux3, lux4);
        if (data == NULL) {
            fprintf(stderr, "Failed to format data, skipping multicast\n");
            sleep(1);
            continue;
        }

        // Send UDP multicast packet
        if (send_udp_multicast(data) != 0) {
            fprintf(stderr, "Failed to send UDP multicast packet\n");
        }

        free(data); // Free allocated memory

        // Wait for 1 second
        sleep(1);
    }

    // Close I2C devices
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    i2cClose(i2c_handle3);
    i2cClose(i2c_handle4);

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated successfully.\n");
    return 0;
}

