#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define AWM7300V_ADDR 0x28
#define FLOW_SCALE_FACTOR 0.0625 // SLPM per LSB
#define LOG_FILE "airflow_log.txt"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float flow_rate;
    time_t timestamp;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(uint16_t *raw_flow);
float convert_to_slpm(uint16_t raw_flow);
int log_data(float flow_rate);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, AWM7300V_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read sensor data with retry mechanism
int read_sensor_data(uint16_t *raw_flow) {
    char buf[2];
    int result;
    int retries = RETRY_COUNT;

    while (retries > 0) {
        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) {
            *raw_flow = (buf[0] << 8) | buf[1];
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %s\n", RETRY_COUNT - retries + 1, strerror(errno));
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
        }
    }

    fprintf(stderr, "Failed to read sensor data after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Convert raw flow data to SLPM
float convert_to_slpm(uint16_t raw_flow) {
    // Mask the 14-bit flow value (bits 15-2 are valid)
    raw_flow &= 0x3FFF; // Clear the upper 2 bits
    return (float)raw_flow * FLOW_SCALE_FACTOR;
}

// Log data to file
int log_data(float flow_rate) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    fprintf(log_file, "%s, %.4f SLPM\n", timestamp, flow_rate);
    fclose(log_file);
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        uint16_t raw_flow;
        float flow_rate;

        if (read_sensor_data(&raw_flow) == 0) {
            flow_rate = convert_to_slpm(raw_flow);
            if (log_data(flow_rate) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        gpioDelay(1000000); // 1 second delay (microseconds)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

