#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// AS7341 I2C address
#define AS7341_ADDR 0x39

// AS7341 register addresses
#define AS7341_ID 0x80
#define AS7341_ENABLE 0x80
#define AS7341_ATIME 0x81
#define AS7341_ASTEP 0x82
#define AS7341_CFG0 0x83
#define AS7341_CFG1 0x84
#define AS7341_CFG2 0x85
#define AS7341_CFG3 0x86
#define AS7341_CFG4 0x87
#define AS7341_CFG5 0x88
#define AS7341_CFG6 0x89
#define AS7341_STATUS 0x93
#define AS7341_F1DATAH 0x94
#define AS7341_F1DATAL 0x95
#define AS7341_F2DATAH 0x96
#define AS7341_F2DATAL 0x97
#define AS7341_F3DATAH 0x98
#define AS7341_F3DATAL 0x99
#define AS7341_F4DATAH 0x9A
#define AS7341_F4DATAL 0x9B
#define AS7341_F5DATAH 0x9C
#define AS7341_F5DATAL 0x9D
#define AS7341_F6DATAH 0x9E
#define AS7341_F6DATAL 0x9F
#define AS7341_F7DATAH 0xA0
#define AS7341_F7DATAL 0xA1
#define AS7341_F8DATAH 0xA2
#define AS7341_F8DATAL 0xA3
#define AS7341_CDATAH 0xA4
#define AS7341_CDATAL 0xA5
#define AS7341_NIRDATAH 0xA6
#define AS7341_NIRDATAL 0xA7

// Expected sensor ID
#define AS7341_ID_VALUE 0x44

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t f1, f2, f3, f4, f5, f6, f7, f8, clear, nir;
} sensor_data_t;

// Function prototypes
int init_pigpio();
int init_i2c();
int init_sensor();
int read_sensor_data(sensor_data_t *data);
float calculate_lux(sensor_data_t data);
int log_data(sensor_data_t data, float lux);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, AS7341_ADDR, 0); // Bus 1, address 0x39, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize the AS7341 sensor
int init_sensor() {
    // Check sensor ID
    int id = i2cReadByteData(i2c_handle, AS7341_ID);
    if (id < 0) {
        fprintf(stderr, "Failed to read sensor ID: %d\n", id);
        return -1;
    }
    if (id != AS7341_ID_VALUE) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X (expected 0x%02X)\n", id, AS7341_ID_VALUE);
        return -1;
    }
    printf("Sensor ID: 0x%02X\n", id);

    // Power on the sensor
    if (i2cWriteByteData(i2c_handle, AS7341_ENABLE, 0x03) < 0) { // PON = 1, AEN = 1
        fprintf(stderr, "Failed to power on sensor\n");
        return -1;
    }

    // Configure the sensor (example configuration)
    if (i2cWriteByteData(i2c_handle, AS7341_CFG0, 0x00) < 0) { // IT = 100ms, Gain = 60x
        fprintf(stderr, "Failed to configure CFG0\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, AS7341_CFG1, 0x00) < 0) { // AGAIN = 1x
        fprintf(stderr, "Failed to configure CFG1\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, AS7341_CFG2, 0x00) < 0) { // LED drive strength = 100mA
        fprintf(stderr, "Failed to configure CFG2\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, AS7341_CFG3, 0x00) < 0) { // Enable all channels
        fprintf(stderr, "Failed to configure CFG3\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, AS7341_CFG4, 0x00) < 0) { // Disable proximity
        fprintf(stderr, "Failed to configure CFG4\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, AS7341_CFG5, 0x00) < 0) { // Disable interrupt
        fprintf(stderr, "Failed to configure CFG5\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, AS7341_CFG6, 0x03) < 0) { // Enable spectral measurement
        fprintf(stderr, "Failed to configure CFG6\n");
        return -1;
    }

    return 0;
}

// Read spectral and lux data from the sensor
int read_sensor_data(sensor_data_t *data) {
    data->f1 = i2cReadWordData(i2c_handle, AS7341_F1DATAH);
    data->f2 = i2cReadWordData(i2c_handle, AS7341_F2DATAH);
    data->f3 = i2cReadWordData(i2c_handle, AS7341_F3DATAH);
    data->f4 = i2cReadWordData(i2c_handle, AS7341_F4DATAH);
    data->f5 = i2cReadWordData(i2c_handle, AS7341_F5DATAH);
    data->f6 = i2cReadWordData(i2c_handle, AS7341_F6DATAH);
    data->f7 = i2cReadWordData(i2c_handle, AS7341_F7DATAH);
    data->f8 = i2cReadWordData(i2c_handle, AS7341_F8DATAH);
    data->clear = i2cReadWordData(i2c_handle, AS7341_CDATAH);
    data->nir = i2cReadWordData(i2c_handle, AS7341_NIRDATAH);

    if (data->f1 < 0 || data->f2 < 0 || data->f3 < 0 || data->f4 < 0 || data->f5 < 0 ||
        data->f6 < 0 || data->f7 < 0 || data->f8 < 0 || data->clear < 0 || data->nir < 0) {
        fprintf(stderr, "Failed to read sensor data\n");
        return -1;
    }

    return 0;
}

// Calculate lux value from spectral data (simplified approximation)
float calculate_lux(sensor_data_t data) {
    // This is a placeholder.  A real implementation would use
    // calibration data and a more accurate lux calculation formula.
    // The AS7341 datasheet provides a lux calculation example.
    return (float)(data.clear + data.nir) / 2.0; // Simple average
}

// Log data to a CSV file
int log_data(sensor_data_t data, float lux) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%.2f\n",
            timestamp, data.f1, data.f2, data.f3, data.f4, data.f5, data.f6, data.f7, data.f8, data.clear, data.nir, lux);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() < 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() < 0) {
        cleanup();
        return 1;
    }

    // Initialize the sensor
    if (init_sensor() < 0) {
        cleanup();
        return 1;
    }

    // Open the log file
    log_file = fopen("spectral_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,F1,F2,F3,F4,F5,F6,F7,F8,Clear,NIR,Lux\n");
    }

    sensor_data_t sensor_data;
    float lux;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Calculate lux value
            lux = calculate_lux(sensor_data);

            // Log the data
            log_data(sensor_data, lux);

            printf("F1: %u, F2: %u, F3: %u, F4: %u, F5: %u, F6: %u, F7: %u, F8: %u, Clear: %u, NIR: %u, Lux: %.2f\n",
                   sensor_data.f1, sensor_data.f2, sensor_data.f3, sensor_data.f4, sensor_data.f5,
                   sensor_data.f6, sensor_data.f7, sensor_data.f8, sensor_data.clear, sensor_data.nir, lux);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

