#define D7S_REG_Y_LSB 0x2A
#define D7S_REG_Y_MSB 0x2B
#define D7S_REG_Z_LSB 0x2C
#define D7S_REG_Z_MSB 0x2D
#define D7S_REG_CTRL1 0x20 // Example control register

// Global variables
int i2c_handle;
FILE *data_file = NULL;
FILE *error_file = NULL;
int i2c_address = DEFAULT_I2C_ADDRESS;
int sampling_interval = DEFAULT_SAMPLING_INTERVAL;
char *filename = DEFAULT_FILENAME;
volatile sig_atomic_t terminate = 0;
time_t last_sensor_check = 0;

// Structure to hold sensor data
typedef struct {
    float x;
    float y;
    float z;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int configure_sensor();
