int log_error(const char *message);
void signal_handler(int signal);
void cleanup();
int is_sensor_present();

// Function to initialize I2C
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return -1;
    }

    i2c_handle = i2cOpen(1, i2c_address, 0); // Bus 1, address, flags
    if (i2c_handle < 0) {
        log_error("Failed to open I2C device");
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to configure the sensor
int configure_sensor() {
    // Example: Set CTRL1 register to enable measurement and set data rate
    char buf[2];
    buf[0] = D7S_REG_CTRL1; // Register address
    buf[1] = 0x80; // Example value: Enable measurement, 100 Hz data rate

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        log_error("Failed to configure sensor");
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buf[1];
    char raw_data[6];
    int16_t x, y, z;

    // Read X axis data
    buf[0] = D7S_REG_X_LSB;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        log_error("Failed to set register address for X axis");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, raw_data, 6) != 6) {
        log_error("Failed to read sensor data");
        return -1;
    }

    x = (int16_t)((raw_data[1] << 8) | raw_data[0]);
    y = (int16_t)((raw_data[3] << 8) | raw_data[2]);
    z = (int16_t)((raw_data[5] << 8) | raw_data[4]);

    // Convert raw data to g (adjust scale factor as needed)
    data->x = (float)x / 1000.0; // Example scale factor
    data->y = (float)y / 1000.0;
    data->z = (float)z / 1000.0;

    return 0;
}

// Function to log data to CSV file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(data_file, "%s,%.3f,%.3f,%.3f\n", timestamp, data.x, data.y, data.z);
    fflush(data_file); // Ensure data is written immediately

    return 0;
}

// Function to log errors to file
int log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(error_file, "%s: %s\n", timestamp, message);
    fflush(error_file);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Cleanup function to close files and terminate pigpio
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (data_file != NULL) {
        fclose(data_file);
    }
    if (error_file != NULL) {
        fclose(error_file);
    }
    gpioTerminate();
}

// Function to check if the sensor is present
int is_sensor_present() {
    char buf[1];
    char data[1];

    buf[0] = D7S_REG_CTRL1; // Example register to read

    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        log_error("Failed to set register address for sensor presence check");
        return 0; // Assume not present
    }

    if (i2cReadDevice(i2c_handle, data, 1) != 1) {
        log_error("Failed to read sensor presence check data");
        return 0; // Assume not present
    }

    return 1; // Sensor is present
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 0);
                break;
            case 'i':
                sampling_interval = atoi(optarg);
                break;
            case 'f':
                filename = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-i sampling_interval] [-f filename]\n", argv[0]);
                return 1;
        }
    }

    // Open error log file
    error_file = fopen("seismic_error.log", "a");
    if (error_file == NULL) {
        perror("Failed to open error log file");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fclose(error_file);
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        cleanup();
        return 1;
    }

    // Open data file
    data_file = fopen(filename, "a");
    if (data_file == NULL) {
        perror("Failed to open data file");
        cleanup();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(data_file, 0, SEEK_END);
    long file_size = ftell(data_file);
    if (file_size == 0) {
        fprintf(data_file, "timestamp,x_g,y_g,z_g\n");
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Check if the sensor is present
        if (time(NULL) - last_sensor_check >= SENSOR_PRESENT_CHECK_INTERVAL) {
            if (!is_sensor_present()) {
                log_error("Sensor not present");
                terminate = 1; // Exit loop if sensor is not present
                continue;
