            last_sensor_check = time(NULL);
        }

        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Log data
            log_data(sensor_data);
        } else {
            log_error("Failed to read sensor data");
        }

        // Wait for the next sample
        gpioDelay(sampling_interval * 1000000); // pigpio uses microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

