#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000
#define TTL 1

int i2c_fd = -1;
int udp_socket = -1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, cleaning up...\n", signum);
        if (i2c_fd != -1) {
            close(i2c_fd);
        }
        if (udp_socket != -1) {
            close(udp_socket);
        }
        exit(0);
    }
}

// Function to initialize the I2C bus
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Function to configure the BH1750 sensor
int config_bh1750() {
    unsigned char config_data = CONTINUOUS_HIGH_RES_MODE;
    if (write(i2c_fd, &config_data, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// Function to read the light level from the BH1750 sensor
int read_light_level(unsigned int *raw_value) {
    unsigned char buffer[2];

    if (read(i2c_fd, buffer, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    *raw_value = (buffer[0] << 8) | buffer[1];
