#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define UART_DEVICE "/dev/ttyS0"
#define BAUD_RATE 921600
#define CSV_FILE "radar_data.csv"
#define BUFFER_SIZE 2048
#define MAGIC_WORD_SIZE 8
#define MAX_OBJECTS 10

// TLV Types (Example, adjust based on AWR1642 documentation)
#define TLV_TYPE_DETECTED_OBJECTS 1

// Global variables
int uart_handle;
FILE *csv_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold radar data
typedef struct {
    float range;
    float velocity;
} RadarData;

// Structure to hold TLV header
typedef struct {
    uint16_t type;
    uint16_t length;
} TLVHeader;

// Function prototypes
int initialize_uart();
int read_uart_data(char *buffer, int max_length);
int validate_magic_word(const char *buffer);
int parse_tlv(const char *buffer, int length, RadarData *radar_data, int *num_objects);
int write_to_csv(const RadarData *radar_data, int num_objects);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize UART
int initialize_uart() {
    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0); // 0 for default flags
    if (uart_handle < 0) {
        fprintf(stderr, "Error opening UART: %d\n", uart_handle);
        return -1;
    }
    return 0;
}

// Read data from UART with timeout
int read_uart_data(char *buffer, int max_length) {
    int bytes_read = 0;
    int timeout_ms = 100; // Timeout after 100ms
    int start_time = gpioTick();

    while (bytes_read < max_length && !terminate) {
        int available = serDataAvailable(uart_handle);
        if (available > 0) {
            buffer[bytes_read++] = serReadByte(uart_handle);
            start_time = gpioTick(); // Reset timeout
        } else {
            int current_time = gpioTick();
            if (current_time - start_time > timeout_ms * 1000) {
                fprintf(stderr, "UART read timeout\n");
                return -1; // Timeout
            }
            gpioDelay(1); // Small delay to avoid busy-waiting
        }
    }

    if (terminate) {
        return -1; // Terminated by signal
    }

    return bytes_read;
}

// Validate magic word
int validate_magic_word(const char *buffer) {
    // Example magic word (adjust based on AWR1642 documentation)
    const char expected_magic_word[] = {0x02, 0x01, 0x04, 0x03, 0x06, 0x05, 0x08, 0x07};
    if (memcmp(buffer, expected_magic_word, MAGIC_WORD_SIZE) == 0) {
        return 0; // Valid magic word
    } else {
        fprintf(stderr, "Invalid magic word\n");
        return -1; // Invalid magic word
    }
}

// Parse TLV data
int parse_tlv(const char *buffer, int length, RadarData *radar_data, int *num_objects) {
    int offset = 0;
    *num_objects = 0;

    while (offset < length - sizeof(TLVHeader)) {
        TLVHeader header;
        memcpy(&header, buffer + offset, sizeof(TLVHeader));

        // Byte swap header (assuming little-endian)
        header.type = (header.type >> 8) | (header.type << 8);
        header.length = (header.length >> 8) | (header.length << 8);

        if (offset + sizeof(TLVHeader) + header.length > length) {
            fprintf(stderr, "TLV length exceeds buffer size\n");
            return -1; // Error: TLV length exceeds buffer size
        }

        if (header.type == TLV_TYPE_DETECTED_OBJECTS) {
            // Example: Assuming detected objects are a simple array of floats (range, velocity)
            if (header.length % (sizeof(float) * 2) != 0) {
                fprintf(stderr, "Detected objects TLV length is not a multiple of 8\n");
                return -1; // Error: Inconsistent TLV length
            }

            int num_detected_objects = header.length / (sizeof(float) * 2);
            if (num_detected_objects > MAX_OBJECTS) {
                num_detected_objects = MAX_OBJECTS; // Limit number of objects
            }

            for (int i = 0; i < num_detected_objects; i++) {
                float range, velocity;
                memcpy(&range, buffer + offset + sizeof(TLVHeader) + i * (sizeof(float) * 2), sizeof(float));
                memcpy(&velocity, buffer + offset + sizeof(TLVHeader) + i * (sizeof(float) * 2) + sizeof(float), sizeof(float));

                // Byte swap range and velocity (assuming little-endian)
                range = (range >> 24) | ((range >> 8) & 0x0000FF00) | ((range << 8) & 0x00FF0000) | (range << 24);
                velocity = (velocity >> 24) | ((velocity >> 8) & 0x0000FF00) | ((velocity << 8) & 0x00FF0000) | (velocity << 24);

                radar_data[i].range = range;
                radar_data[i].velocity = velocity;
                (*num_objects)++;
            }
        }

        offset += sizeof(TLVHeader) + header.length;
    }

    return 0;
}

// Write data to CSV file
int write_to_csv(const RadarData *radar_data, int num_objects) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    for (int i = 0; i < num_objects; i++) {
        fprintf(csv_file, "%s,%d,%.2f,%.2f\n", timestamp, i, radar_data[i].range, radar_data[i].velocity);
    }
    fflush(csv_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources
void cleanup() {
    if (uart_handle >= 0) {
        serClose(uart_handle);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize UART
    if (initialize_uart() != 0) {
        cleanup();
        return 1;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file\n");
        cleanup();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "timestamp,object_index,range_m,velocity_mps\n");
    }

    char buffer[BUFFER_SIZE];
    RadarData radar_data[MAX_OBJECTS];
    int num_objects;

    fprintf(stderr, "Starting data acquisition...\n");

    while (!terminate) {
        // Read data from UART
        int bytes_read = read_uart_data(buffer, BUFFER_SIZE);
        if (bytes_read > 0) {
            // Validate magic word
            if (validate_magic_word(buffer) == 0) {
                // Parse TLV data
                if (parse_tlv(buffer, bytes_read, radar_data, &num_objects) == 0) {
                    // Write data to CSV file
                    write_to_csv(radar_data, num_objects);
                }
            }
        } else if (bytes_read < 0) {
            // Error reading from UART, already logged in read_uart_data
        }

        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    // Cleanup and exit
    cleanup();
    fprintf(stderr, "Data acquisition stopped.\n");
    return 0;
}

