#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27

// Define UART device and baud rate
#define UART_DEVICE "/dev/ttyAMA0"
#define BAUD_RATE 115200

// Global variables for UART handle and program termination
int uart_handle = -1;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int initialize_uart();
void read_sensors(int *left, int *middle, int *right);
void log_data(int left, int middle, int right);
void send_emergency_stop();
void cleanup();
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int left;
    int middle;
    int right;
} sensor_data_t;

// Function to initialize the pigpio library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP);

    gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(MIDDLE_SENSOR_PIN, PI_PUD_UP);

    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP);

    return 0;
}

// Function to initialize the UART interface
int initialize_uart() {
    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0); // 0 for no flags
    if (uart_handle < 0) {
        fprintf(stderr, "Failed to open UART device: %s\n", UART_DEVICE);
        return -1;
    }
    return 0;
}

// Function to read the sensor values
void read_sensors(int *left, int *middle, int *right) {
    *left = gpioRead(LEFT_SENSOR_PIN);
    *middle = gpioRead(MIDDLE_SENSOR_PIN);
    *right = gpioRead(RIGHT_SENSOR_PIN);
}

// Function to log the sensor data with a timestamp
void log_data(int left, int middle, int right) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Left: %d, Middle: %d, Right: %d\n", timestamp, left, middle, right);
}

// Function to send the emergency stop message
void send_emergency_stop() {
    int bytes_written = serWrite(uart_handle, "EMERGENCY STOP!\n", strlen("EMERGENCY STOP!\n"));
    if (bytes_written < 0) {
        fprintf(stderr, "Error writing to UART: %d\n", bytes_written);
    }
}

// Function to clean up resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (uart_handle >= 0) {
        serClose(uart_handle);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received (%d). Terminating program...\n", signal);
    program_running = 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize UART
    if (initialize_uart() != 0) {
        cleanup();
        return 1;
    }

    printf("Program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int left, middle, right;

        read_sensors(&left, &middle, &right);
        log_data(left, middle, &right);

        if (left == 0 && middle == 0 && right == 0) {
            send_emergency_stop();
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

